             qs_scf_kp_energy_occupation_plateau_ready, &
             qs_scf_kp_energy_closure_ready, &
             qs_scf_kp_energy_closure_tail_ready, &
             qs_scf_kp_energy_bootstrap_curvature_floor, &
             qs_scf_kp_energy_curvature_floor, &
             qs_scf_kp_energy_relative_metric_ready, &
             qs_scf_kp_exit_residual, &
             qs_scf_kp_raw_exit_floor, &
             qs_scf_kp_raw_exit_floor_ratio, &
             qs_scf_kp_residual_split, &
             qs_scf_kp_directional_curvature_update, &
             qs_scf_kp_directional_subspace_curvature_update, &
             qs_scf_kp_symmetric_multisecant_update, &
             qs_scf_kp_symmetric_secant_update, &
             qs_scf_kp_added_mos_basis_bootstrap_ready, &
             qs_scf_kp_added_mos_fractional_density_ready, &
             qs_scf_kp_added_mos_fractional_tail_ready, &
             qs_scf_kp_added_mos_integer_density_ready, &
             qs_scf_kp_subspace_is_collapsed, &
             qs_scf_kp_density_closure_buffer_ready, &
             qs_scf_kp_density_closure_history_refresh_ready, &
             qs_scf_kp_density_closure_refresh_ready, &
             qs_scf_kp_orbital_tail_rebase_ready, &
             qs_scf_kp_rebased_calibration_samples, &
             qs_scf_kp_subspace_refresh_step_ready, &
             qs_scf_kp_subspace_refresh_gate, &
             qs_scf_kp_secant_bootstrap_probe, &
             qs_scf_kp_secant_calibration_probe, &
             qs_scf_kp_secant_candidate_promoted

CONTAINS

! **************************************************************************************************
!> \brief chemical-potential response for a fixed-N spin/k-point group
!>
!>        A perturbation may be local to one irreducible k-point, but the chemical potential
!>        enforces the electron count over the complete fixed-N group.  Therefore its numerator
!>        contains the local weighted energy response while its denominator contains the global
!>        occupation susceptibility.
!> \param weighted_energy_response local sum_i (-df_i/de_i) de_i
!> \param local_curvature_sum local sum_i (-df_i/de_i), used as a serial fallback
!> \param fixed_n_curvature_sum global susceptibility of the fixed-N spin/k-point group
!> \return fixed-N chemical-potential response
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_fixed_n_response_mu_shift( &
      weighted_energy_response, local_curvature_sum, fixed_n_curvature_sum) RESULT(mu_shift)
      REAL(KIND=dp), INTENT(IN)                          :: weighted_energy_response, &
                                                            local_curvature_sum, &
                                                            fixed_n_curvature_sum
      REAL(KIND=dp)                                      :: mu_shift

      REAL(KIND=dp)                                      :: response_denominator

      response_denominator = MAX(0.0_dp, fixed_n_curvature_sum)
      IF (response_denominator <= EPSILON(response_denominator)) &
         response_denominator = MAX(0.0_dp, local_curvature_sum)
      mu_shift = 0.0_dp
      IF (response_denominator > EPSILON(response_denominator)) &
         mu_shift = weighted_energy_response/response_denominator

   END FUNCTION qs_scf_kp_fixed_n_response_mu_shift

! **************************************************************************************************
!> \brief begin one complete fixed-N k-point physical-gradient audit
!>
!>        The audit accumulators describe the current Hamiltonian/orbital endpoint.  They must be
!>        rebuilt for every full gradient evaluation, including evaluations that close or restart
!>        a line search.  Accepted-step calibration and minimizer history have a longer lifetime
!>        and are deliberately not modified here.
!> \param qs_ot_env first k-point OT channel carrying the globally reduced audit state
!> \param eps_scf requested SCF threshold for this endpoint
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_physical_audit_begin(qs_ot_env, eps_scf)
      TYPE(qs_ot_type), INTENT(INOUT)                    :: qs_ot_env
      REAL(KIND=dp), INTENT(IN)                          :: eps_scf

      qs_ot_env%kpoint_physical_delta_ready = .TRUE.
      qs_ot_env%kpoint_physical_delta_groups = 0
      qs_ot_env%kpoint_complete_physical_delta = -1.0_dp
      qs_ot_env%kpoint_eps_scf = eps_scf
      qs_ot_env%kpoint_physical_gnorm = 0.0_dp
      qs_ot_env%kpoint_physical_rot_gnorm = 0.0_dp
      qs_ot_env%kpoint_full_physical_rot_gnorm = 0.0_dp
      qs_ot_env%kpoint_physical_energy_gnorm = 0.0_dp
      qs_ot_env%kpoint_gauge_gnorm = 0.0_dp

   END SUBROUTINE qs_scf_kp_physical_audit_begin

! **************************************************************************************************
!> \brief add one independent fixed-N spin group to the current physical-gradient audit
!> \param qs_ot_env first k-point OT channel carrying the globally reduced audit state
!> \param group_ready whether this complete spin-group audit satisfies its stationarity gate
!> \param physical_norm complete physical gradient norm squared for this group
!> \param rotation_norm active physical rotation-gradient norm squared
!> \param full_rotation_norm complete physical rotation-gradient norm squared
!> \param energy_norm fixed-N auxiliary-energy gradient norm squared
!> \param gauge_norm occupation-gauge rotation-gradient norm squared
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_physical_audit_add_group(qs_ot_env, group_ready, physical_norm, &
                                                 rotation_norm, full_rotation_norm, energy_norm, &
                                                 gauge_norm)
      TYPE(qs_ot_type), INTENT(INOUT)                    :: qs_ot_env
      LOGICAL, INTENT(IN)                                :: group_ready
      REAL(KIND=dp), INTENT(IN)                          :: physical_norm, rotation_norm, &
                                                            full_rotation_norm, energy_norm, &
                                                            gauge_norm

      qs_ot_env%kpoint_physical_delta_groups = qs_ot_env%kpoint_physical_delta_groups + 1
      qs_ot_env%kpoint_physical_gnorm = qs_ot_env%kpoint_physical_gnorm + physical_norm
      qs_ot_env%kpoint_physical_rot_gnorm = qs_ot_env%kpoint_physical_rot_gnorm + rotation_norm
      qs_ot_env%kpoint_full_physical_rot_gnorm = &
         qs_ot_env%kpoint_full_physical_rot_gnorm + full_rotation_norm
      qs_ot_env%kpoint_physical_energy_gnorm = &
         qs_ot_env%kpoint_physical_energy_gnorm + energy_norm
      qs_ot_env%kpoint_gauge_gnorm = qs_ot_env%kpoint_gauge_gnorm + gauge_norm
      qs_ot_env%kpoint_physical_delta_ready = &
         qs_ot_env%kpoint_physical_delta_ready .AND. group_ready

   END SUBROUTINE qs_scf_kp_physical_audit_add_group

! **************************************************************************************************
!> \brief complete physical gradient norm for a reduced k-point OT rotation space
!>
!>        A dense Schur model may retain only a thermal/density-selected subset of all complex
!>        rotations. That subset is sufficient for constructing a search direction, but the
!>        omitted physical rotations must remain part of the convergence residual.
!> \param active_rotation_norm physical rotation-gradient norm represented by the Schur model
!> \param full_rotation_norm physical rotation-gradient norm over every complex MO pair
!> \param energy_norm fixed-N auxiliary-energy gradient norm
!> \param reduced_rotation_space whether the Schur rotation space is incomplete
!> \return complete nonnegative physical gradient norm
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_complete_physical_gradient_norm( &
      active_rotation_norm, full_rotation_norm, energy_norm, reduced_rotation_space) RESULT(gradient_norm)
      REAL(KIND=dp), INTENT(IN)                          :: active_rotation_norm, &
                                                            full_rotation_norm, energy_norm
      LOGICAL, INTENT(IN)                                :: reduced_rotation_space
      REAL(KIND=dp)                                      :: gradient_norm

      gradient_norm = MAX(0.0_dp, energy_norm) + &
                      MAX(0.0_dp, MERGE(full_rotation_norm, active_rotation_norm, &
                                        reduced_rotation_space))

   END FUNCTION qs_scf_kp_complete_physical_gradient_norm

! **************************************************************************************************
!> \brief decide convergence directly from a complete fixed-N physical-gradient audit
!>
!>        Model-quality history calibrates a reduced Schur search direction, but it is not part
!>        of the variational stationarity condition.  Once every complex rotation and auxiliary
!>        energy has contributed to the direct RMS, that norm is independently conclusive.
!> \param physical_delta_norm complete fixed-N physical-gradient RMS
!> \param physical_delta_norm_limit requested convergence limit for that RMS
!> \param physical_delta_nvar full-grid-equivalent number of audited variables
!> \return true when a nonempty complete audit is below its limit
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_complete_physical_audit_ready( &
      physical_delta_norm, physical_delta_norm_limit, physical_delta_nvar) RESULT(ready)
      REAL(KIND=dp), INTENT(IN)                          :: physical_delta_norm, &
                                                            physical_delta_norm_limit, &
                                                            physical_delta_nvar
      LOGICAL                                            :: ready

      ready = physical_delta_norm_limit > 0.0_dp .AND. physical_delta_nvar > 0.0_dp .AND. &
              physical_delta_norm >= 0.0_dp .AND. &
              physical_delta_norm <= physical_delta_norm_limit

   END FUNCTION qs_scf_kp_complete_physical_audit_ready

! **************************************************************************************************
!> \brief squared-gradient budget left outside a reduced complex rotation space
!>
!>        Reserve half of EPS_SCF for omitted rotations; the remaining half is available for
!>        represented rotations, auxiliary energies, and the orbital gradient.  The argument is
!>        the full-grid-equivalent number of complex rotation variables used by the physical RMS.
!> \param eps_scf requested SCF threshold
!> \param rotation_nvar full-grid-equivalent number of complex rotation variables
!> \return maximum omitted physical rotation-gradient norm squared
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_residual_pair_omission_limit(eps_scf, rotation_nvar) RESULT(norm_limit)
      REAL(KIND=dp), INTENT(IN)                          :: eps_scf, rotation_nvar
      REAL(KIND=dp)                                      :: norm_limit

      norm_limit = 0.0_dp
      IF (eps_scf > 0.0_dp .AND. rotation_nvar > 0.0_dp) &
         norm_limit = (0.5_dp*eps_scf)**2*rotation_nvar

   END FUNCTION qs_scf_kp_residual_pair_omission_limit

! **************************************************************************************************
!> \brief squared-gradient omission limit for adaptive complex-pair capture
!>
!>        Outside the final convergence tail, require the reduced rotation space to represent at
!>        least as much physical gradient norm as it omits.  Once the raw residual reaches the
!>        final tail, retain the strict EPS_SCF omission budget.
!> \param eps_scf requested SCF threshold
!> \param rotation_nvar full-grid-equivalent number of complex rotation variables
!> \param represented_score physical rotation-gradient norm squared already in the reduced space
!> \param strict_tail whether the endpoint is in the final convergence tail
!> \return maximum omitted physical rotation-gradient norm squared
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_residual_pair_capture_limit( &
      eps_scf, rotation_nvar, represented_score, strict_tail) RESULT(norm_limit)
      REAL(KIND=dp), INTENT(IN)                          :: eps_scf, rotation_nvar, represented_score
      LOGICAL, INTENT(IN)                                :: strict_tail
      REAL(KIND=dp)                                      :: norm_limit

      norm_limit = qs_scf_kp_residual_pair_omission_limit(eps_scf, rotation_nvar)
      IF (.NOT. strict_tail) norm_limit = MAX(norm_limit, represented_score, 0.0_dp)

   END FUNCTION qs_scf_kp_residual_pair_capture_limit

! **************************************************************************************************
!> \brief deterministic moments identifying a channel-resolved upper-triangle pair set
!>
!>        The three moments are intended for diagnostics, not cryptographic identity.  Duplicate
!>        membership across the Fermi, density, and residual masks is counted once.  Padding,
!>        diagonal entries, lower triangles, and entries beyond a channel's current MO count are
!>        ignored.
!> \param fermi_active Fermi-window pair mask
!> \param density_active canonical-density pair mask
!> \param residual_active physical-residual completion mask
!> \param channel_nmo valid MO count for every channel
!> \param pair_count number of unique valid pairs
!> \param pair_moment sum of deterministic pair indices
!> \param pair_square_moment sum of squared deterministic pair indices
! **************************************************************************************************
   PURE SUBROUTINE qs_scf_kp_pair_mask_moments( &
      fermi_active, density_active, residual_active, channel_nmo, &
      pair_count, pair_moment, pair_square_moment)
      LOGICAL, DIMENSION(:, :, :), INTENT(IN)            :: fermi_active, density_active, &
                                                            residual_active
      INTEGER, DIMENSION(:), INTENT(IN)                  :: channel_nmo
      INTEGER(KIND=int_8), INTENT(OUT)                   :: pair_count, pair_moment, &
                                                            pair_square_moment

      INTEGER                                            :: channel, imo, jmo, nmo, nmo_max
      INTEGER(KIND=int_8)                                :: pair_index

      pair_count = 0_int_8
      pair_moment = 0_int_8
      pair_square_moment = 0_int_8
      nmo_max = MIN(SIZE(fermi_active, 1), SIZE(fermi_active, 2))
      DO channel = 1, MIN(SIZE(fermi_active, 3), SIZE(channel_nmo))
         nmo = MIN(nmo_max, MAX(0, channel_nmo(channel)))
         DO imo = 1, nmo - 1
            DO jmo = imo + 1, nmo
               IF (.NOT. (fermi_active(imo, jmo, channel) .OR. &
                          density_active(imo, jmo, channel) .OR. &
                          residual_active(imo, jmo, channel))) CYCLE
               pair_index = (INT(channel - 1, KIND=int_8)*INT(nmo_max, KIND=int_8) + &
                             INT(imo - 1, KIND=int_8))*INT(nmo_max, KIND=int_8) + &
                            INT(jmo, KIND=int_8)
               pair_count = pair_count + 1_int_8
               pair_moment = pair_moment + pair_index
               pair_square_moment = pair_square_moment + pair_index*pair_index
            END DO
         END DO
      END DO

   END SUBROUTINE qs_scf_kp_pair_mask_moments

! **************************************************************************************************
!> \brief whether accepted residual growth exceeds the local plateau tolerance
!> \param previous_delta residual represented by the accepted search model
!> \param current_delta residual at the accepted endpoint
!> \param relative_slack nonnegative relative plateau tolerance
!> \return true only for residual growth beyond the tolerated plateau
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_residual_history_reset_needed( &
      previous_delta, current_delta, relative_slack) RESULT(reset_needed)
      REAL(KIND=dp), INTENT(IN)                          :: previous_delta, current_delta, &
                                                            relative_slack
      LOGICAL                                            :: reset_needed

      reset_needed = previous_delta > EPSILON(previous_delta) .AND. &
                     current_delta > (1.0_dp + MAX(0.0_dp, relative_slack))*previous_delta

   END FUNCTION qs_scf_kp_residual_history_reset_needed

! **************************************************************************************************
!> \brief canonical band-energy response represented by a covariant density derivative
!>
!>        The density derivative and occupation curvature must refer to the same canonical band.
!>        In particular, a canonical projector derivative must not be divided by the curvature of
!>        the equally numbered REF orbital: those labels differ after a finite REF rotation and the
!>        latter curvature can vanish at an otherwise active Fermi-surface mode.
!> \param projected_density_derivative Tr[P_i dP], including spin and k-point weights
!> \param canonical_occ_curv positive canonical -df_i/de_i curvature, including k-point weight
!> \return canonical auxiliary-energy response; zero for a thermally inactive band
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_canonical_projector_density_response( &
      projected_density_derivative, canonical_occ_curv) RESULT(response)
      REAL(KIND=dp), INTENT(IN)                          :: projected_density_derivative, &
                                                            canonical_occ_curv
      REAL(KIND=dp)                                      :: response

      response = 0.0_dp
      IF (canonical_occ_curv > EPSILON(canonical_occ_curv)) &
         response = 0.5_dp*projected_density_derivative/canonical_occ_curv

   END FUNCTION qs_scf_kp_canonical_projector_density_response

! **************************************************************************************************
!> \brief Fixed-N Frechet derivative of a smooth canonical occupation projector.
!>
!>        For P(H)=2*w*f(H-mu), the divided-difference kernel is invariant under rotations inside
!>        a degenerate eigenspace.  Evaluating that kernel directly avoids differentiated sorted
!>        eigenvectors and their arbitrary cluster gauge.  The diagonal response includes the
!>        chemical-potential shift of the complete fixed-N spin/k-point group.
!> \param chc projected Hermitian Hamiltonian in the current REF basis
!> \param dchc Hermitian Hamiltonian perturbation in the same basis
!> \param occupation_numbers canonical occupations, without spin or k-point weight
!> \param kpoint_weight irreducible-k-point weight
!> \param occupation_curvature positive weighted -df/de for each canonical band
!> \param fixed_n_curvature_sum susceptibility summed over the complete fixed-N group
!> \param projector_weight fraction of the canonical projector used by the response model
!> \param projector_derivative derivative of the weighted occupation projector in the REF basis
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_fixed_n_projector_frechet( &
      chc, dchc, occupation_numbers, kpoint_weight, occupation_curvature, &
      fixed_n_curvature_sum, projector_weight, projector_derivative)

      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(IN)      :: chc, dchc
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: occupation_numbers
      REAL(KIND=dp), INTENT(IN)                          :: kpoint_weight
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: occupation_curvature
      REAL(KIND=dp), INTENT(IN)                          :: fixed_n_curvature_sum, projector_weight
      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(OUT)     :: projector_derivative

      COMPLEX(KIND=dp), ALLOCATABLE, DIMENSION(:, :)     :: eigenvectors, kernel, work
      INTEGER                                            :: i, j, n
      REAL(KIND=dp)                                      :: coefficient, denominator, gap_tolerance, &
                                                            local_curvature_sum, mu_numerator, &
                                                            mu_shift, scale
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: eigenvalues, weighted_occupation

      n = SIZE(chc, 1)
      CPASSERT(n > 0)
      CPASSERT(ALL(SHAPE(chc) == [n, n]))
      CPASSERT(ALL(SHAPE(dchc) == [n, n]))
      CPASSERT(SIZE(occupation_numbers) == n)
      CPASSERT(SIZE(occupation_curvature) == n)
      CPASSERT(ALL(SHAPE(projector_derivative) == [n, n]))

      projector_derivative(:, :) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)
      IF (projector_weight <= 0.0_dp .OR. kpoint_weight <= 0.0_dp) RETURN

      ALLOCATE (eigenvectors(n, n), kernel(n, n), work(n, n), eigenvalues(n), &
                weighted_occupation(n))
      CALL diag_complex(chc, eigenvectors, eigenvalues)
      work(:, :) = MATMUL(CONJG(TRANSPOSE(eigenvectors)), MATMUL(dchc, eigenvectors))
      weighted_occupation(:) = 2.0_dp*kpoint_weight*occupation_numbers(:)

      local_curvature_sum = SUM(MAX(0.0_dp, occupation_curvature(:)))
      mu_numerator = 0.0_dp
      DO i = 1, n
         mu_numerator = mu_numerator + MAX(0.0_dp, occupation_curvature(i))* &
                        REAL(work(i, i), KIND=dp)
      END DO
      mu_shift = qs_scf_kp_fixed_n_response_mu_shift( &
                 mu_numerator, local_curvature_sum, fixed_n_curvature_sum)

      scale = MAX(1.0_dp, MAXVAL(ABS(eigenvalues(:))))
      gap_tolerance = SQRT(EPSILON(1.0_dp))*scale
      kernel(:, :) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)
      DO j = 1, n
         DO i = 1, n
            IF (i == j) THEN
               coefficient = -2.0_dp*MAX(0.0_dp, occupation_curvature(i))
               kernel(i, i) = CMPLX(coefficient*(REAL(work(i, i), KIND=dp) - mu_shift), &
                                    0.0_dp, KIND=dp)
            ELSE
               denominator = eigenvalues(i) - eigenvalues(j)
               IF (ABS(denominator) > gap_tolerance) THEN
                  coefficient = (weighted_occupation(i) - weighted_occupation(j))/denominator
               ELSE
                  coefficient = -2.0_dp*SQRT(MAX(0.0_dp, occupation_curvature(i))* &
                                             MAX(0.0_dp, occupation_curvature(j)))
               END IF
               kernel(i, j) = coefficient*work(i, j)
            END IF
         END DO
      END DO

      projector_derivative(:, :) = projector_weight* &
                                   MATMUL(eigenvectors, &
                                          MATMUL(kernel, CONJG(TRANSPOSE(eigenvectors))))
      projector_derivative(:, :) = 0.5_dp*(projector_derivative + &
                                           CONJG(TRANSPOSE(projector_derivative)))

      DEALLOCATE (eigenvectors, kernel, work, eigenvalues, weighted_occupation)

   END SUBROUTINE qs_scf_kp_fixed_n_projector_frechet

! **************************************************************************************************
!> \brief Fixed-N auxiliary-energy gradient for a Hamiltonian frozen at a line-search start.
!> \param frozen_diagonal current diagonal of U^H H0 U
!> \param energy_coordinate current auxiliary energies
!> \param response_weight weighted positive occupation susceptibility
!> \param fixed_n_weight_sum susceptibility summed over the complete fixed-N group
!> \param fixed_n_weighted_residual weighted residual summed over the complete fixed-N group
!> \param gradient projected fixed-N gradient
! **************************************************************************************************
   PURE SUBROUTINE qs_scf_kp_fixed_n_frozen_energy_gradient( &
      frozen_diagonal, energy_coordinate, response_weight, fixed_n_weight_sum, &
      fixed_n_weighted_residual, gradient)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: frozen_diagonal, energy_coordinate, &
                                                            response_weight
      REAL(KIND=dp), INTENT(IN)                          :: fixed_n_weight_sum, &
                                                            fixed_n_weighted_residual
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: gradient

      REAL(KIND=dp)                                      :: fixed_n_mean

      fixed_n_mean = 0.0_dp
      IF (fixed_n_weight_sum > EPSILON(fixed_n_weight_sum)) &
         fixed_n_mean = fixed_n_weighted_residual/fixed_n_weight_sum
      gradient(:) = response_weight(:)* &
                    (fixed_n_mean - (frozen_diagonal(:) - energy_coordinate(:)))

   END SUBROUTINE qs_scf_kp_fixed_n_frozen_energy_gradient

! **************************************************************************************************
!> \brief whether ADDED_MOS AUTO has physical support for rebuilding an integer subspace
!>
!>        A truncated subspace can hide a thermally active degenerate manifold and therefore
!>        contain only integer occupations.  Permit an early rebuild when the independent
!>        density-response basis audit detects that deficiency.  The caller supplies the
!>        residual and small-subspace gates through basis_probe_limited and enrichment_window.
!> \param active_tail whether the current subspace already contains fractional occupations
!> \param basis_probe_limited whether the density-response basis audit requests enrichment
!> \param enrichment_window whether AUTO may still enlarge this small response subspace
!> \param residual_spike whether model and physical residuals are inconsistent
!> \return true if occupation or basis evidence supports rebuilding the MO subspace
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_added_mos_basis_bootstrap_ready( &
      active_tail, basis_probe_limited, enrichment_window, residual_spike) RESULT(ready)
      LOGICAL, INTENT(IN)                                :: active_tail, basis_probe_limited, &
                                                            enrichment_window, residual_spike
      LOGICAL                                            :: ready

      ready = .NOT. residual_spike .AND. enrichment_window .AND. &
              (active_tail .OR. basis_probe_limited)

   END FUNCTION qs_scf_kp_added_mos_basis_bootstrap_ready

! **************************************************************************************************
!> \brief whether a relaxed integer AUTO subspace needs a larger density-response basis
!>
!>        In a small AUTO buffer the occupation-weighted OT gradient can converge before the
!>        occupied projector is stationary in the canonical Hamiltonian basis.  The independent
!>        density residual detects this hidden occupied/virtual response.  Admit enrichment after
!>        the search residual is relaxed and while the density residual remains unresolved but
!>        finite.  Continue adaptively until the residual closes or the AO basis is exhausted.
!> \param search_delta occupation-weighted OT search residual
!> \param density_delta canonical fixed-N density-stationarity residual
!> \param eps_scf requested SCF convergence threshold
!> \param search_limit largest search residual admitted for a relaxed rebuild
!> \param density_limit largest density residual admitted for a relaxed rebuild
!> \param expandable whether AUTO can still enlarge the response subspace
!> \param active_tail whether the current subspace already contains fractional occupations
!> \return true if the integer subspace needs density-response enrichment
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_added_mos_integer_density_ready( &
      search_delta, density_delta, eps_scf, search_limit, density_limit, &
      expandable, active_tail) RESULT(ready)
      REAL(KIND=dp), INTENT(IN)                          :: search_delta, density_delta, eps_scf, &
                                                            search_limit, density_limit
      LOGICAL, INTENT(IN)                                :: expandable, active_tail
      LOGICAL                                            :: ready

      ready = expandable .AND. .NOT. active_tail .AND. eps_scf > 0.0_dp .AND. &
              search_limit >= eps_scf .AND. density_limit > eps_scf .AND. &
              search_delta >= 0.0_dp .AND. search_delta <= search_limit .AND. &
              density_delta > eps_scf .AND. density_delta <= density_limit

   END FUNCTION qs_scf_kp_added_mos_integer_density_ready

! **************************************************************************************************
!> \brief whether a thermal AUTO frontier needs density-response enrichment before it collapses
!>
!>        A small virtual buffer can still contain a well-resolved fractional frontier while its
!>        highest MOs are empty.  If the independent canonical density residual remains unresolved,
!>        enlarge that response space before Gaussian or Fermi occupations collapse to an integer
!>        branch.  The coherent-tail and small-buffer restrictions are supplied by the caller.
!> \param search_delta occupation-weighted OT search residual
!> \param density_delta canonical fixed-N density-stationarity residual
!> \param eps_scf requested SCF convergence threshold
!> \param search_limit largest search residual admitted for frontier-preserving enrichment
!> \param density_limit largest density residual admitted for frontier-preserving enrichment
!> \param expandable whether AUTO can still enlarge the response subspace
!> \param active_tail whether the current subspace contains fractional occupations
!> \param coherent_tail whether the integrated and peak fractional weights are significant
!> \param basis_supported whether the frontier or residual basis signal supports enrichment
!> \param buffer_supported whether the edge is active or the non-edge buffer remains small
!> \return true if the fractional subspace needs density-response enrichment
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_added_mos_fractional_density_ready( &
      search_delta, density_delta, eps_scf, search_limit, density_limit, &
      expandable, active_tail, coherent_tail, basis_supported, buffer_supported) RESULT(ready)
      REAL(KIND=dp), INTENT(IN)                          :: search_delta, density_delta, eps_scf, &
                                                            search_limit, density_limit
      LOGICAL, INTENT(IN)                                :: expandable, active_tail, coherent_tail, &
                                                            basis_supported, buffer_supported
      LOGICAL                                            :: ready

      ready = expandable .AND. active_tail .AND. coherent_tail .AND. basis_supported .AND. &
              buffer_supported .AND. eps_scf > 0.0_dp .AND. &
              search_limit >= eps_scf .AND. density_limit > eps_scf .AND. &
              search_delta >= 0.0_dp .AND. search_delta <= search_limit .AND. &
              density_delta > eps_scf .AND. density_delta <= density_limit

   END FUNCTION qs_scf_kp_added_mos_fractional_density_ready

! **************************************************************************************************
!> \brief residual gate for non-edge ADDED_MOS AUTO enrichment
!>
!>        Bootstrap growth and a fractionally occupied MO edge may enrich the subspace early.
!>        Once that edge is empty, however, fractional occupations below it only diagnose an
!>        incomplete response basis.  Relax the current subspace tightly before discarding its
!>        minimizer history and rebuilding a larger one.
!> \param residual_delta maximum model/physical residual
!> \param eps_scf requested SCF accuracy
!> \param edge_grow_limit residual limit for edge-driven growth
!> \param bootstrap whether this is the initial small AUTO subspace
!> \param edge_limited whether the current highest-MO edge is fractionally occupied
!> \return true if fractional-tail growth is sufficiently relaxed
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_added_mos_fractional_tail_ready( &
      residual_delta, eps_scf, edge_grow_limit, bootstrap, edge_limited) RESULT(ready)
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta, eps_scf, edge_grow_limit
      LOGICAL, INTENT(IN)                                :: bootstrap, edge_limited
      LOGICAL                                            :: ready

      REAL(KIND=dp)                                      :: residual_limit

      residual_limit = MAX(ot_kp_added_mos_auto_fractional_tail_residual_factor*edge_grow_limit, &
                           ot_kp_added_mos_auto_fractional_tail_residual_floor)
      IF (.NOT. bootstrap .AND. .NOT. edge_limited) THEN
         residual_limit = MIN(residual_limit, ot_kp_added_mos_auto_response_eps_factor*eps_scf)
      END IF
      ready = residual_delta <= residual_limit

   END FUNCTION qs_scf_kp_added_mos_fractional_tail_ready

! **************************************************************************************************
!> \brief Residual-quality metric for an accepted density-response candidate.
!>
!>        A candidate designed to improve canonical density stationarity must be calibrated by that
!>        stationarity whenever it was measured.  Using the generic OT residual can mark a useful
!>        density step as failed when the orthogonal orbital channel temporarily grows.
!> \param raw_quality generic accepted-step OT residual quality
!> \param density_quality canonical density-stationarity quality
!> \param density_quality_ready whether density_quality belongs to this accepted step
!> \return candidate-specific residual quality
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_density_candidate_residual_quality( &
      raw_quality, density_quality, density_quality_ready) RESULT(candidate_quality)
      REAL(KIND=dp), INTENT(IN)                          :: raw_quality, density_quality
      LOGICAL, INTENT(IN)                                :: density_quality_ready
      REAL(KIND=dp)                                      :: candidate_quality

      candidate_quality = raw_quality
      IF (density_quality_ready) candidate_quality = density_quality
      candidate_quality = MAX(0.0_dp, candidate_quality)

   END FUNCTION qs_scf_kp_density_candidate_residual_quality

! **************************************************************************************************
!> \brief Decide whether an accepted physical residual has reached the density-response tail.
!> \param raw_delta unprojected residual measured at the previous accepted OT state
!> \param tail_delta upper residual limit for the endpoint-local response model
!> \return true only for a finite, positive accepted-state residual inside the tail
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_density_response_tail_ready(raw_delta, tail_delta) RESULT(ready)

      REAL(KIND=dp), INTENT(IN)                          :: raw_delta, tail_delta
      LOGICAL                                            :: ready

      ready = raw_delta == raw_delta .AND. tail_delta > 0.0_dp .AND. &
              raw_delta > 0.0_dp .AND. raw_delta <= tail_delta

   END FUNCTION qs_scf_kp_density_response_tail_ready

! **************************************************************************************************
!> \brief Isolate accepted finite density-response directions from mixed minimizer history.
!>
!>        Only candidates whose finite step explicitly contains a canonical-density response may
!>        calibrate this endpoint-local response model.  The flavor identity follows every
!>        transported current/previous/anchor closure secant.  The newest valid density-specific
!>        sample is retained across intervening ordinary CG steps without combining response maps
!>        measured at different self-consistent endpoints.
!> \param flavors accepted k-point OT candidate flavor for every history column
!> \param tail_armed the minimizer has reached the finite-response residual tail
!> \param closure_steps accepted closure-secants in rotation coordinates
!> \param closure_targets measured self-consistent closure-gradient changes
!> \param probe_steps density-specific accepted secant history
!> \param probe_targets density-specific accepted response targets
!> \param ready a finite, nonzero density-response sample was selected
! **************************************************************************************************
   PURE SUBROUTINE qs_scf_kp_density_response_probe( &
      flavors, tail_armed, closure_steps, closure_targets, &
      probe_steps, probe_targets, ready)

      INTEGER, DIMENSION(:), INTENT(IN)                  :: flavors
      LOGICAL, INTENT(IN)                                :: tail_armed
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: closure_steps, closure_targets
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: probe_steps, probe_targets
      LOGICAL, INTENT(OUT)                               :: ready

      INTEGER, DIMENSION(3), PARAMETER                   :: newest_first = [2, 1, 3]

      INTEGER                                            :: ihistory, isample
      LOGICAL                                            :: density_flavor

      probe_steps(:, :) = 0.0_dp
      probe_targets(:, :) = 0.0_dp
      ready = .FALSE.
      IF (ANY(SHAPE(closure_targets) /= SHAPE(closure_steps))) RETURN
      IF (ANY(SHAPE(probe_steps) /= SHAPE(closure_steps))) RETURN
      IF (ANY(SHAPE(probe_targets) /= SHAPE(closure_steps))) RETURN
      IF (SIZE(flavors) /= SIZE(closure_steps, 2)) RETURN
      IF (SIZE(flavors) /= SIZE(newest_first)) RETURN
      IF (.NOT. tail_armed) RETURN

      DO ihistory = 1, SIZE(newest_first)
         isample = newest_first(ihistory)
         SELECT CASE (flavors(isample))
         CASE (32, 33, 38, 39, 40)
            density_flavor = .TRUE.
         CASE DEFAULT
            density_flavor = .FALSE.
         END SELECT
         IF (.NOT. density_flavor) CYCLE
         IF (.NOT. ALL(closure_steps(:, isample) == closure_steps(:, isample)) .OR. &
             .NOT. ALL(closure_targets(:, isample) == closure_targets(:, isample))) CYCLE
         IF (DOT_PRODUCT(closure_steps(:, isample), closure_steps(:, isample)) <= TINY(1.0_dp)) CYCLE
         IF (DOT_PRODUCT(closure_targets(:, isample), closure_targets(:, isample)) <= TINY(1.0_dp)) CYCLE

         probe_steps(:, 1) = closure_steps(:, isample)
         probe_targets(:, 1) = closure_targets(:, isample)
         ready = .TRUE.
         RETURN
      END DO

   END SUBROUTINE qs_scf_kp_density_response_probe

! **************************************************************************************************
!> \brief Accepted-step trust scale for a density-response candidate.
!>
!>        The cumulative measured/predicted Mermin ratio supplies a secant estimate of model
!>        quality.  Combining it conservatively with the recent EMA and applying its square root
!>        scales the step, rather than merely its candidate-selection score.
!> \param predicted_sum accumulated predicted accepted-position Mermin decrease
!> \param measured_sum accumulated measured Mermin decrease
!> \param quality_ema recent measured/predicted quality
!> \param samples number of accepted candidate samples
!> \return bounded step scale
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_density_candidate_history_scale( &
      predicted_sum, measured_sum, quality_ema, samples) RESULT(step_scale)
      REAL(KIND=dp), INTENT(IN)                          :: predicted_sum, measured_sum, quality_ema
      INTEGER, INTENT(IN)                                :: samples
      REAL(KIND=dp)                                      :: step_scale

      REAL(KIND=dp)                                      :: cumulative_quality, history_quality

      step_scale = 1.0_dp
      IF (samples <= 0 .OR. predicted_sum <= EPSILON(predicted_sum)) RETURN
      cumulative_quality = MAX(0.0_dp, measured_sum/predicted_sum)
      history_quality = cumulative_quality
      IF (quality_ema > EPSILON(quality_ema)) history_quality = MIN(history_quality, quality_ema)
      history_quality = MIN(1.0_dp, MAX(ot_kp_schur_calibration_floor, history_quality))
      step_scale = SQRT(history_quality)

   END FUNCTION qs_scf_kp_density_candidate_history_scale

! **************************************************************************************************
!> \brief Whether mature density-candidate history is worse than the density baseline.
!>
!>        Candidate and baseline qualities must describe the same canonical-density residual.
!>        No absolute quality floor is used because asymptotically useful improvements can be much
!>        smaller than ten percent while still dominating an almost stationary Direct baseline.
!> \param selected_quality latest selected density-stationarity quality
!> \param selected_quality_ema EMA of selected density-stationarity quality
!> \param samples number of accepted density-candidate samples
!> \param baseline_quality density-stationarity quality of the Direct baseline
!> \return true if mature selected history is weaker than the baseline
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_density_candidate_residual_bad( &
      selected_quality, selected_quality_ema, samples, baseline_quality) RESULT(bad)
      REAL(KIND=dp), INTENT(IN)                          :: selected_quality, selected_quality_ema
      INTEGER, INTENT(IN)                                :: samples
      REAL(KIND=dp), INTENT(IN)                          :: baseline_quality
      LOGICAL                                            :: bad

      REAL(KIND=dp)                                      :: residual_reference

      bad = .FALSE.
      IF (samples < ot_kp_schur_calibration_min_samples) RETURN
      residual_reference = MAX(0.0_dp, baseline_quality, EPSILON(1.0_dp))
      bad = selected_quality_ema < &
            ot_kp_schur_projector_density_fdir_probe_residual_ratio*residual_reference .OR. &
            selected_quality < &
            0.5_dp*ot_kp_schur_projector_density_fdir_probe_residual_ratio*residual_reference

   END FUNCTION qs_scf_kp_density_candidate_residual_bad

! **************************************************************************************************
!> \brief whether a full-density Direct candidate may collect tail line-search history
!> \param residual_delta current OT residual
!> \param candidate_expected_drop calibrated candidate Mermin drop
!> \param reference_expected_drop currently selected dense-coupled expected drop
!> \param quality_ema accepted shadow-history Mermin quality
!> \param samples number of accepted shadow-history samples
!> \param selected_residual_quality latest residual quality of already selected Direct probes
!> \param selected_residual_quality_ema residual quality of already selected Direct probes
!> \param selected_samples number of selected Direct probes
!> \param density_tail_active whether the canonical density residual still exceeds EPS_SCF
!> \param dense_residual_quality residual quality of the dense-coupled baseline
!> \return true if the candidate is a calibrated residual-tail close call
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_density_full_direct_tail_probe( &
      residual_delta, candidate_expected_drop, reference_expected_drop, quality_ema, samples, &
      selected_residual_quality, selected_residual_quality_ema, selected_samples, &
      density_tail_active, dense_residual_quality) RESULT(do_probe)
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta, candidate_expected_drop, &
                                                            reference_expected_drop, quality_ema
      INTEGER, INTENT(IN)                                :: samples
      REAL(KIND=dp), INTENT(IN)                          :: selected_residual_quality, &
                                                            selected_residual_quality_ema
      INTEGER, INTENT(IN)                                :: selected_samples
      LOGICAL, INTENT(IN)                                :: density_tail_active
      REAL(KIND=dp), INTENT(IN)                          :: dense_residual_quality
      LOGICAL                                            :: do_probe

      LOGICAL                                            :: residual_recovery_probe, &
                                                            selected_bootstrap_probe, &
                                                            stale_residual_probe
      REAL(KIND=dp)                                      :: required_drop_ratio, residual_reference

      do_probe = .FALSE.
      IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) RETURN
      IF (samples < ot_kp_schur_projector_response_min_samples .AND. &
          selected_samples <= 0) RETURN
      IF (quality_ema < ot_kp_schur_projector_response_quality_min_ratio) RETURN
      IF (candidate_expected_drop <= ot_kp_schur_projector_density_full_min_drop) RETURN

      ! A nearly stationary dense baseline is not enough evidence that a weak selected candidate
      ! is useful.  Keep the accepted residual contraction tied to the calibrated physical floor.
      residual_reference = MAX(0.0_dp, dense_residual_quality, &
                               ot_kp_schur_calibrated_quality_min_ratio)
      residual_recovery_probe = .FALSE.
      selected_bootstrap_probe = .FALSE.
      stale_residual_probe = .FALSE.
      IF (selected_samples >= ot_kp_schur_calibration_min_samples) THEN
         ! The Mermin prediction alone cannot distinguish a direction that repeatedly reduces the
         ! exact fixed-N density residual from a formally larger dense step that leaves it stationary.
         residual_recovery_probe = density_tail_active .AND. &
                                   selected_residual_quality_ema >= &
                                   2.0_dp*ot_kp_schur_projector_density_fdir_probe_residual_ratio* &
                                   residual_reference .AND. &
                                   selected_residual_quality >= &
                                   0.5_dp*ot_kp_schur_projector_density_fdir_probe_residual_ratio* &
                                   residual_reference
         stale_residual_probe = &
            dense_residual_quality <= 2.0_dp*ot_kp_schur_calibrated_quality_min_ratio .AND. &
            selected_residual_quality_ema < &
            ot_kp_schur_projector_density_fdir_probe_residual_ratio*residual_reference .AND. &
            quality_ema >= 2.0_dp*ot_kp_schur_projector_response_quality_min_ratio .AND. &
            MOD(samples, MAX(1, 2*ot_kp_schur_calibration_min_samples)) == 0
      ELSE IF (selected_samples > 0) THEN
         selected_bootstrap_probe = &
            selected_residual_quality_ema >= &
            0.5_dp*ot_kp_schur_projector_density_fdir_probe_residual_ratio*residual_reference .AND. &
            quality_ema >= 2.0_dp*ot_kp_schur_projector_response_quality_min_ratio
      END IF

      required_drop_ratio = ot_kp_schur_projector_density_fdir_probe_ratio
      IF (stale_residual_probe) &
         required_drop_ratio = MIN(required_drop_ratio, &
                                   ot_kp_schur_projector_density_fdir_refresh_ratio)
      IF (selected_bootstrap_probe) &
         required_drop_ratio = MIN(required_drop_ratio, &
                                   MAX(ot_kp_schur_projector_density_fdir_refresh_ratio, &
                                       ot_kp_schur_branch_loss_density_recovery))
      IF (residual_recovery_probe) &
         required_drop_ratio = MIN(required_drop_ratio, &
                                   MAX(ot_kp_schur_projector_density_fdir_refresh_ratio, &
                                       ot_kp_schur_branch_loss_density_recovery))
      IF (candidate_expected_drop < required_drop_ratio* &
          MAX(reference_expected_drop, ot_kp_schur_projector_density_full_min_drop)) RETURN

      IF (selected_samples >= ot_kp_schur_calibration_min_samples) THEN
         IF (.NOT. stale_residual_probe) THEN
            IF (selected_residual_quality_ema < &
                ot_kp_schur_projector_density_fdir_probe_residual_ratio*residual_reference) RETURN
            IF (selected_residual_quality < &
                0.5_dp*ot_kp_schur_projector_density_fdir_probe_residual_ratio* &
                residual_reference) RETURN
         END IF
      END IF

      do_probe = .TRUE.

   END FUNCTION qs_scf_kp_density_full_direct_tail_probe

! **************************************************************************************************
!> \brief Quadratic Mermin-model decrease at a finite line-search position.
!> \param slope directional Mermin slope g^T p
!> \param quadratic directional curvature p^T H p
!> \param position cumulative line-search coordinate
!> \return nonnegative predicted Mermin decrease
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_quadratic_position_drop(slope, quadratic, position) RESULT(model_drop)
      REAL(KIND=dp), INTENT(IN)                          :: slope, quadratic, position
      REAL(KIND=dp)                                      :: model_drop

      REAL(KIND=dp)                                      :: bounded_position

      bounded_position = MAX(0.0_dp, position)
      model_drop = bounded_position*slope - &
                   0.5_dp*bounded_position*bounded_position*quadratic
      IF (model_drop /= model_drop .OR. ABS(model_drop) >= HUGE(model_drop)) model_drop = 0.0_dp
      model_drop = MAX(0.0_dp, model_drop)

   END FUNCTION qs_scf_kp_quadratic_position_drop

! **************************************************************************************************
!> \brief Bounded minimizer position of a one-dimensional quadratic Mermin model.
!> \param slope directional Mermin slope g^T p
!> \param quadratic directional curvature p^T H p
!> \param max_scale largest admissible position
!> \return descent position, or zero when the model has no finite positive descent
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_quadratic_descent_scale(slope, quadratic, max_scale) RESULT(scale)
      REAL(KIND=dp), INTENT(IN)                          :: slope, quadratic, max_scale
      REAL(KIND=dp)                                      :: scale

      scale = 0.0_dp
      IF (.NOT. (slope == slope .AND. quadratic == quadratic .AND. max_scale == max_scale)) RETURN
      IF (ABS(slope) >= HUGE(slope) .OR. ABS(quadratic) >= HUGE(quadratic) .OR. &
          ABS(max_scale) >= HUGE(max_scale)) RETURN
      IF (slope <= EPSILON(MAX(1.0_dp, ABS(slope))) .OR. &
          max_scale <= EPSILON(MAX(1.0_dp, ABS(max_scale)))) RETURN

      scale = max_scale
      IF (quadratic > EPSILON(MAX(1.0_dp, ABS(quadratic)))) &
         scale = MIN(scale, slope/quadratic)
      IF (scale <= EPSILON(MAX(1.0_dp, ABS(scale)))) THEN
         scale = 0.0_dp
         RETURN
      END IF
      IF (qs_scf_kp_quadratic_position_drop(slope, quadratic, scale) <= &
          EPSILON(MAX(1.0_dp, ABS(slope)))) scale = 0.0_dp

   END FUNCTION qs_scf_kp_quadratic_descent_scale

! **************************************************************************************************
!> \brief Candidate-specific Mermin decrease at the accepted line-search position.
!>
!>        Candidate histories store their calibrated decrease for the complete search direction.
!>        Scale that value by the common quadratic model at the accepted position so predicted and
!>        measured decreases refer to the same finite step.
!> \param candidate_drop calibrated candidate decrease for the complete direction
!> \param model_drop common quadratic decrease for the complete direction
!> \param model_slope common directional Mermin slope
!> \param model_quadratic common directional Mermin curvature
!> \param position accepted cumulative line-search coordinate
!> \return candidate decrease corresponding to the accepted position
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_candidate_position_drop( &
      candidate_drop, model_drop, model_slope, model_quadratic, position) RESULT(position_drop)
      REAL(KIND=dp), INTENT(IN)                          :: candidate_drop, model_drop, model_slope, &
                                                            model_quadratic, position
      REAL(KIND=dp)                                      :: position_drop

      REAL(KIND=dp)                                      :: model_position_drop

      position_drop = 0.0_dp
      IF (candidate_drop <= 0.0_dp .OR. model_drop <= EPSILON(model_drop) .OR. &
          position <= EPSILON(position)) RETURN
      model_position_drop = qs_scf_kp_quadratic_position_drop( &
                            model_slope, model_quadratic, position)
      IF (model_position_drop <= 0.0_dp) RETURN
      position_drop = candidate_drop*model_position_drop/model_drop
      IF (position_drop /= position_drop .OR. ABS(position_drop) >= HUGE(position_drop)) &
         position_drop = 0.0_dp
      position_drop = MAX(0.0_dp, position_drop)

   END FUNCTION qs_scf_kp_candidate_position_drop

! **************************************************************************************************
!> \brief Rebase a calibrated affine-candidate decrease onto its exact base-direction slope.
!>
!>        A reduced response candidate preserves the established base curvature but can rebuild
!>        the base direction in a different active subspace.  Its linear term must therefore use
!>        the exact gradient dot product of that rebuilt direction.  Apply that slope difference
!>        before adding the affine correction and response-mismatch penalty.
!> \param established_slope linear term carried by the established candidate
!> \param exact_base_slope exact gradient dot product of the rebuilt base direction
!> \param established_drop calibrated decrease carried by the established candidate
!> \param correction_increment affine correction to the established quadratic model
!> \param mismatch_drop response-model mismatch penalty
!> \return calibrated decrease of the rebased affine candidate
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_affine_rebased_drop( &
      established_slope, exact_base_slope, established_drop, correction_increment, &
      mismatch_drop) RESULT(rebased_drop)
      REAL(KIND=dp), INTENT(IN)                          :: established_slope, exact_base_slope, &
                                                            established_drop, &
                                                            correction_increment, mismatch_drop
      REAL(KIND=dp)                                      :: rebased_drop

      rebased_drop = established_drop + exact_base_slope - established_slope + &
                     correction_increment - mismatch_drop
      IF (rebased_drop /= rebased_drop .OR. ABS(rebased_drop) >= HUGE(rebased_drop)) &
         rebased_drop = 0.0_dp
      rebased_drop = MAX(0.0_dp, rebased_drop)

   END FUNCTION qs_scf_kp_affine_rebased_drop

! **************************************************************************************************
!> \brief Numerical floor for the exact fixed-N auxiliary-energy Newton bootstrap.
!>
!>        The energy gradient and Hessian both contain the Fermi susceptibility.  Dividing by a
!>        macroscopic floor leaves nearly empty frontier states frozen in an integer occupation.
!>        Keep only a roundoff-scale floor here so that the susceptibility cancels analytically;
!>        the separate thermal trust region bounds the resulting energy step on the kT scale.
!> \param curvature_max largest diagonal occupation curvature in the fixed-N group
!> \return roundoff-scale bootstrap regularization floor
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_energy_bootstrap_curvature_floor(curvature_max) RESULT(curvature_floor)
      REAL(KIND=dp), INTENT(IN)                          :: curvature_max
      REAL(KIND=dp)                                      :: curvature_floor

      curvature_floor = 0.0_dp
      IF (curvature_max <= 0.0_dp) RETURN
      curvature_floor = ot_kp_energy_curvature_numerical_factor*EPSILON(1.0_dp)* &
                        MAX(1.0_dp, curvature_max)
      curvature_floor = MIN(ot_kp_energy_curvature_absolute_cap, curvature_floor)

   END FUNCTION qs_scf_kp_energy_bootstrap_curvature_floor

! **************************************************************************************************
!> \brief Regularization floor for the fixed-N auxiliary-energy Hessian of one spin group.
!>
!>        The physical diagonal is the weighted occupation susceptibility.  An absolute 1 Ha floor
!>        erases that scale for weakly occupied metallic tails.  This relative floor preserves all
!>        modes above five percent of the largest group susceptibility, caps the inactive-mode
!>        condition number, and retains the former 1 Ha protection for broad high-curvature groups.
!> \param curvature_max largest diagonal occupation curvature in the fixed-N group
!> \return group-relative regularization floor
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_energy_curvature_floor(curvature_max) RESULT(curvature_floor)
      REAL(KIND=dp), INTENT(IN)                          :: curvature_max
      REAL(KIND=dp)                                      :: curvature_floor

      curvature_floor = 0.0_dp
      IF (curvature_max <= 0.0_dp) RETURN
      curvature_floor = MAX(ot_kp_energy_curvature_relative_floor*curvature_max, &
                            ot_kp_energy_curvature_numerical_factor*SQRT(EPSILON(curvature_max))* &
                            MAX(1.0_dp, curvature_max))
      curvature_floor = MIN(ot_kp_energy_curvature_absolute_cap, curvature_floor)

   END FUNCTION qs_scf_kp_energy_curvature_floor

! **************************************************************************************************
!> \brief Release the bootstrap auxiliary-energy regularization in the converged fixed-N tail.
!> \param physical_ready whether the complete projected Mermin residual is available
!> \param physical_delta projected fixed-N Mermin residual
!> \param eps_scf requested SCF accuracy
!> \return whether group-relative occupation curvature may replace the bootstrap floor
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_energy_relative_metric_ready(physical_ready, physical_delta, eps_scf) &
      RESULT(ready)
      LOGICAL, INTENT(IN)                                :: physical_ready
      REAL(KIND=dp), INTENT(IN)                          :: physical_delta, eps_scf
      LOGICAL                                            :: ready

      ready = physical_ready .AND. eps_scf > 0.0_dp .AND. &
              physical_delta >= 0.0_dp .AND. physical_delta <= eps_scf

   END FUNCTION qs_scf_kp_energy_relative_metric_ready

! **************************************************************************************************
!> \brief Identify a canonical-density defect dominated by occupation coordinates.
!>
!>        A diagonal mismatch in the canonical Hamiltonian frame is repaired by the fixed-N
!>        auxiliary-energy block.  An off-diagonal mismatch instead needs orbital rotation or a
!>        subspace rebuild.  Require accepted Mermin history before classifying the former as a
!>        closure plateau.
!> \param density_ready whether the canonical-density decomposition is complete
!> \param density_diag RMS diagonal canonical-density mismatch
!> \param density_offdiag RMS off-diagonal canonical-density mismatch
!> \param accepted_samples accepted Mermin calibration samples in the current subspace
!> \return whether an exact fixed-N occupation-closure candidate may be considered
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_energy_occupation_plateau_ready( &
      density_ready, density_diag, density_offdiag, accepted_samples) RESULT(ready)
      LOGICAL, INTENT(IN)                                :: density_ready
      REAL(KIND=dp), INTENT(IN)                          :: density_diag, density_offdiag
      INTEGER, INTENT(IN)                                :: accepted_samples
      LOGICAL                                            :: ready

      ready = density_ready .AND. density_diag > 0.0_dp .AND. &
              density_offdiag >= 0.0_dp .AND. density_diag > density_offdiag .AND. &
              accepted_samples >= ot_kp_schur_calibration_min_samples

   END FUNCTION qs_scf_kp_energy_occupation_plateau_ready

! **************************************************************************************************
!> \brief Require a complete, calibrated physical residual before blockwise energy closure.
!> \param residual_delta current global OT residual
!> \param physical_delta_norm complete fixed-N energy/rotation RMS
!> \param density_delta canonical-density stationarity residual
!> \param accepted_samples accepted Mermin calibration samples
!> \return whether the current MO-space state is an asymptotic physical tail
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_energy_closure_tail_ready( &
      residual_delta, physical_delta_norm, density_delta, accepted_samples) RESULT(ready)
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta, physical_delta_norm, &
                                                            density_delta
      INTEGER, INTENT(IN)                                :: accepted_samples
      LOGICAL                                            :: ready

      ready = residual_delta >= 0.0_dp .AND. &
              residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
              physical_delta_norm >= 0.0_dp .AND. &
              physical_delta_norm <= ot_kp_schur_projector_coupled_tail_delta .AND. &
              density_delta >= 0.0_dp .AND. &
              density_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
              accepted_samples >= ot_kp_schur_calibration_min_samples

   END FUNCTION qs_scf_kp_energy_closure_tail_ready

! **************************************************************************************************
!> \brief Select a fixed-N energy closure when the auxiliary-energy block limits density stationarity.
!> \param new_search_point whether a fresh line-search direction can be constructed
!> \param density_ready whether the complete canonical-density audit is available
!> \param physical_delta current global OT residual
!> \param density_delta canonical-density stationarity residual
!> \param eps_scf requested SCF accuracy
!> \param energy_residual fixed-N auxiliary-energy gradient norm squared
!> \param rotation_residual physical rotation-gradient norm squared
!> \param gauge_residual gauge-like rotation-gradient norm squared
!> \param tail_ready whether the current MO space has mature accepted tail history
!> \param occupation_plateau_ready whether the density defect is diagonal occupation mismatch
!> \return whether an energy-only fixed-N closure candidate is required
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_energy_closure_ready(new_search_point, density_ready, physical_delta, &
                                                density_delta, eps_scf, energy_residual, &
                                                rotation_residual, gauge_residual, tail_ready, &
                                                occupation_plateau_ready) RESULT(ready)
      LOGICAL, INTENT(IN)                                :: new_search_point, density_ready
      REAL(KIND=dp), INTENT(IN)                          :: physical_delta, density_delta, eps_scf, &
                                                            energy_residual, rotation_residual, &
                                                            gauge_residual
      LOGICAL, INTENT(IN)                                :: tail_ready, occupation_plateau_ready
      LOGICAL                                            :: ready

      REAL(KIND=dp)                                      :: energy_signal, nonenergy_signal

      ready = new_search_point .AND. density_ready .AND. tail_ready .AND. eps_scf > 0.0_dp .AND. &
              physical_delta >= 0.0_dp .AND. density_delta > eps_scf
      IF (.NOT. ready .OR. physical_delta <= eps_scf) RETURN

      ! Above the converged-residual tail, an energy-only block step is admissible only when the
      ! exact block it solves is the leading physical-gradient component and the independently
      ! measured canonical-density defect is larger than the global OT defect.  The competing
      ! coupled model and the ordinary Mermin line search still decide whether the step is accepted.
      energy_signal = MAX(0.0_dp, energy_residual)
      nonenergy_signal = MAX(0.0_dp, rotation_residual) + MAX(0.0_dp, gauge_residual)
      ready = energy_signal > MAX(nonenergy_signal, EPSILON(energy_signal)) .AND. &
              (physical_delta <= density_delta .OR. occupation_plateau_ready)

   END FUNCTION qs_scf_kp_energy_closure_ready

! **************************************************************************************************
!> \brief Prefer fixed-N energy closure only when it improves on an available coupled candidate.
!>
!>        Energy closure is a fallback for the auxiliary-energy block.  It must not replace a
!>        valid density/rotation candidate whose calibrated Mermin decrease is larger, because
!>        doing so can leave canonical density stationarity on a flat energy-only plateau.
!> \param closure_drop predicted Mermin decrease of the energy-only closure
!> \param competing_drop calibrated predicted decrease of the current coupled candidate
!> \param competing_ready whether a valid coupled candidate is already available
!> \return whether the energy-only closure should replace the current candidate
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_energy_closure_preferred( &
      closure_drop, competing_drop, competing_ready) RESULT(preferred)
      REAL(KIND=dp), INTENT(IN)                          :: closure_drop, competing_drop
      LOGICAL, INTENT(IN)                                :: competing_ready
      LOGICAL                                            :: preferred

      preferred = closure_drop > EPSILON(closure_drop)
      IF (.NOT. preferred .OR. .NOT. competing_ready) RETURN
      preferred = closure_drop >= ot_kp_schur_projector_response_advantage_ratio* &
                  MAX(competing_drop, EPSILON(competing_drop))

   END FUNCTION qs_scf_kp_energy_closure_preferred

! **************************************************************************************************
!> \brief Admit a fresh coupled density-closure model after the projected Mermin residual converged.
!>
!>        Accepted-step history is useful while competing models explore the ordinary residual
!>        regime.  It must not permanently suppress a fresh, trust-safe coupled rotation/energy
!>        model when canonical density stationarity is the sole remaining exit condition.  The
!>        candidate is still validated by the normal Mermin line search and residual closure.
!> \param closure_ready whether density stationarity alone blocks convergence at a fresh search
!> \param coupled_model_ready whether the finite complex coupled quadratic model is valid
!> \param model_drop uncalibrated predicted Mermin decrease
!> \param weighted_trust_ratio curvature-weighted response trust ratio
!> \param abs_trust_ratio maximum-component response trust ratio
!> \return whether the coupled density model may bypass stale history calibration
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_density_closure_model_ready(closure_ready, coupled_model_ready, &
                                                       model_drop, weighted_trust_ratio, &
                                                       abs_trust_ratio) RESULT(ready)
      LOGICAL, INTENT(IN)                                :: closure_ready, coupled_model_ready
      REAL(KIND=dp), INTENT(IN)                          :: model_drop, weighted_trust_ratio, &
                                                            abs_trust_ratio
      LOGICAL                                            :: ready

      ready = closure_ready .AND. coupled_model_ready .AND. &
              model_drop > ot_kp_schur_projector_density_full_min_drop .AND. &
              weighted_trust_ratio >= 0.0_dp .AND. weighted_trust_ratio <= 1.0_dp .AND. &
              abs_trust_ratio >= 0.0_dp .AND. abs_trust_ratio <= 1.0_dp

   END FUNCTION qs_scf_kp_density_closure_model_ready

! **************************************************************************************************
!> \brief Apply a trust scale only to a coupled response correction.
!>
!>        The fixed-N auxiliary-energy solution is an independently projected Mermin step.  A trust
!>        model for a finite rotation/occupation response must not scale that exact base step away.
!> \param base_step exact fixed-N auxiliary-energy step
!> \param response_step coupled rotation/occupation correction
!> \param response_scale trust scale of the coupled correction
!> \param corrected_step base_step + response_scale*response_step
! **************************************************************************************************
   PURE SUBROUTINE qs_scf_kp_response_corrected_step(base_step, response_step, response_scale, &
                                                     corrected_step)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: base_step, response_step
      REAL(KIND=dp), INTENT(IN)                          :: response_scale
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: corrected_step

      corrected_step(:) = base_step(:) + response_scale*response_step(:)

   END SUBROUTINE qs_scf_kp_response_corrected_step

! **************************************************************************************************
!> \brief Replace the density part of a canonical fixed-N rotation/energy response.
!>
!>        The canonical response already contains the covariant occupation-projector contribution.
!>        An alternative density response therefore replaces that contribution; adding it directly
!>        to the canonical response would count the density derivative twice.
!> \param canonical_response complete canonical fixed-N energy response
!> \param canonical_cross complete canonical fixed-N energy/rotation cross block
!> \param active_response canonical response with its density contribution removed
!> \param active_cross cross block conjugate to active_response
!> \param density_response replacement density response
!> \param density_cross cross block conjugate to density_response
!> \param replacement_ready whether both active and replacement density maps are valid
!> \param model_response composed response used by the coupled model
!> \param model_cross composed energy/rotation cross block
! **************************************************************************************************
   PURE SUBROUTINE qs_scf_kp_density_replaced_response( &
      canonical_response, canonical_cross, active_response, active_cross, density_response, &
      density_cross, replacement_ready, model_response, model_cross)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: canonical_response, canonical_cross, &
                                                            active_response, active_cross, &
                                                            density_response, density_cross
      LOGICAL, INTENT(IN)                                :: replacement_ready
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: model_response, model_cross

      IF (replacement_ready) THEN
         model_response(:, :) = active_response(:, :) + density_response(:, :)
         model_cross(:, :) = active_cross(:, :) + density_cross(:, :)
      ELSE
         model_response(:, :) = canonical_response(:, :)
         model_cross(:, :) = canonical_cross(:, :)
      END IF

   END SUBROUTINE qs_scf_kp_density_replaced_response

! **************************************************************************************************
!> \brief Project a positive diagonal rotation floor away from physical density-response modes.
!>
!>        Elementwise rotation floors can spuriously harden a soft collective metallic density
!>        mode.  This routine returns D**1/2 (I - QQ**T) D**1/2, where Q spans D**1/2 times the
!>        supplied modes.  The correction remains positive semidefinite and vanishes along every
!>        independent density mode.
!> \param diagonal_shift nonnegative elementwise rotation-floor correction
!> \param density_modes physical density-response modes to leave unregularized
!> \param projected_floor positive semidefinite correction orthogonal to density_modes
!> \param projected_rank number of independent projected density modes
! **************************************************************************************************
   PURE SUBROUTINE qs_scf_kp_density_mode_projected_floor( &
      diagonal_shift, density_modes, projected_floor, projected_rank)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: diagonal_shift
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: density_modes
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: projected_floor
      INTEGER, INTENT(OUT)                               :: projected_rank

      INTEGER                                            :: imode, iorth, nmode, nrot
      REAL(KIND=dp)                                      :: raw_norm, residual_norm
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: sqrt_shift, work
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: orthonormal

      nrot = SIZE(diagonal_shift)
      nmode = SIZE(density_modes, 2)
      ALLOCATE (orthonormal(nrot, nmode), sqrt_shift(nrot), work(nrot))
      orthonormal(:, :) = 0.0_dp
      sqrt_shift(:) = SQRT(MAX(0.0_dp, diagonal_shift(:)))
      projected_rank = 0

      DO imode = 1, nmode
         work(:) = sqrt_shift(:)*density_modes(:, imode)
         raw_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(work, work)))
         IF (raw_norm <= TINY(raw_norm)) CYCLE
         ! Two modified Gram-Schmidt passes keep nearly dependent spin/k-point
         ! channel modes from leaving a numerically visible floor component.
         DO iorth = 1, projected_rank
            work(:) = work(:) - DOT_PRODUCT(orthonormal(:, iorth), work)* &
                      orthonormal(:, iorth)
         END DO
         DO iorth = 1, projected_rank
            work(:) = work(:) - DOT_PRODUCT(orthonormal(:, iorth), work)* &
                      orthonormal(:, iorth)
         END DO
         residual_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(work, work)))
         IF (residual_norm <= SQRT(EPSILON(1.0_dp))*raw_norm) CYCLE
         projected_rank = projected_rank + 1
         orthonormal(:, projected_rank) = work(:)/residual_norm
      END DO

      projected_floor(:, :) = 0.0_dp
      DO iorth = 1, nrot
         projected_floor(iorth, iorth) = MAX(0.0_dp, diagonal_shift(iorth))
      END DO
      DO iorth = 1, projected_rank
         work(:) = sqrt_shift(:)*orthonormal(:, iorth)
         projected_floor(:, :) = projected_floor(:, :) - &
                                 SPREAD(work, DIM=2, NCOPIES=nrot)* &
                                 SPREAD(work, DIM=1, NCOPIES=nrot)
      END DO
      projected_floor(:, :) = 0.5_dp*(projected_floor(:, :) + &
                                      TRANSPOSE(projected_floor(:, :)))

      DEALLOCATE (orthonormal, sqrt_shift, work)

   END SUBROUTINE qs_scf_kp_density_mode_projected_floor

! **************************************************************************************************
!> \brief Measure finite-temperature density stationarity in a projected Hamiltonian eigenbasis.
!> \param eigenvectors eigenvectors of the Hermitian projected Hamiltonian
!> \param current_occupation occupations attached to the current orbital labels
!> \param canonical_occupation fixed-N occupations of the projected Hamiltonian eigenvalues
!> \param sigma electronic temperature in Hartree
!> \param maxocc maximum occupation of one orbital
!> \param kpoint_weight irreducible k-point integration weight
!> \param residual_sq weighted squared residual in energy units
!> \param state_weight weighted number of states
!> \param max_residual largest element residual in energy units
!> \param diagonal_residual_sq optional diagonal contribution to residual_sq
!> \param offdiagonal_residual_sq optional off-diagonal contribution to residual_sq
!> \param pair_residual optional elementwise residual in energy units
!> \param method optional smearing method, defaults to Fermi-Dirac
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_canonical_density_residual(eigenvectors, current_occupation, &
                                                   canonical_occupation, sigma, maxocc, &
                                                   kpoint_weight, residual_sq, state_weight, &
                                                   max_residual, diagonal_residual_sq, &
                                                   offdiagonal_residual_sq, pair_residual, method)

      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(IN)      :: eigenvectors
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: current_occupation, canonical_occupation
      REAL(KIND=dp), INTENT(IN)                          :: sigma, maxocc, kpoint_weight
      REAL(KIND=dp), INTENT(OUT)                         :: residual_sq, state_weight, max_residual
      REAL(KIND=dp), INTENT(OUT), OPTIONAL               :: diagonal_residual_sq, &
                                                            offdiagonal_residual_sq
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT), &
         OPTIONAL                                        :: pair_residual
      INTEGER, INTENT(IN), OPTIONAL                      :: method

      COMPLEX(KIND=dp), ALLOCATABLE, DIMENSION(:, :)     :: projector
      INTEGER                                            :: imo, method_active, nmo
      REAL(KIND=dp)                                      :: diagonal_norm_sq, &
                                                            inverse_susceptibility, peak_response, &
                                                            total_norm_sq

      nmo = SIZE(eigenvectors, 1)
      CPASSERT(SIZE(eigenvectors, 2) == nmo)
      CPASSERT(SIZE(current_occupation) == nmo)
      CPASSERT(SIZE(canonical_occupation) == nmo)

      residual_sq = 0.0_dp
      state_weight = 0.0_dp
      max_residual = 0.0_dp
      IF (PRESENT(diagonal_residual_sq)) diagonal_residual_sq = 0.0_dp
      IF (PRESENT(offdiagonal_residual_sq)) offdiagonal_residual_sq = 0.0_dp
      IF (PRESENT(pair_residual)) THEN
         CPASSERT(ALL(SHAPE(pair_residual) == [nmo, nmo]))
         pair_residual(:, :) = 0.0_dp
      END IF
      IF (nmo == 0 .OR. sigma <= 0.0_dp .OR. maxocc <= 0.0_dp .OR. kpoint_weight <= 0.0_dp) RETURN
      method_active = smear_fermi_dirac
      IF (PRESENT(method)) method_active = method
      peak_response = kpoint_ot_smearing_peak_response(sigma, maxocc, method_active)
      IF (peak_response <= EPSILON(peak_response)) RETURN

      ALLOCATE (projector(nmo, nmo))
      projector(:, :) = eigenvectors(:, :)
      DO imo = 1, nmo
         projector(:, imo) = canonical_occupation(imo)*projector(:, imo)
      END DO
      projector(:, :) = MATMUL(projector, CONJG(TRANSPOSE(eigenvectors)))
      DO imo = 1, nmo
         projector(imo, imo) = projector(imo, imo) - current_occupation(imo)
      END DO

      ! The inverse peak susceptibility maps a bounded density mismatch to a
      ! conservative thermodynamic residual with the same energy units as EPS_SCF.
      inverse_susceptibility = 1.0_dp/peak_response
      total_norm_sq = REAL(SUM(CONJG(projector(:, :))*projector(:, :)), KIND=dp)
      diagonal_norm_sq = 0.0_dp
      DO imo = 1, nmo
         diagonal_norm_sq = diagonal_norm_sq + ABS(projector(imo, imo))**2
      END DO
      residual_sq = kpoint_weight*inverse_susceptibility**2*total_norm_sq
      IF (PRESENT(diagonal_residual_sq)) &
         diagonal_residual_sq = kpoint_weight*inverse_susceptibility**2*diagonal_norm_sq
      IF (PRESENT(offdiagonal_residual_sq)) &
         offdiagonal_residual_sq = kpoint_weight*inverse_susceptibility**2* &
                                   MAX(0.0_dp, total_norm_sq - diagonal_norm_sq)
      state_weight = kpoint_weight*REAL(nmo, KIND=dp)
      max_residual = inverse_susceptibility*MAXVAL(ABS(projector(:, :)))
      IF (PRESENT(pair_residual)) pair_residual(:, :) = inverse_susceptibility*ABS(projector(:, :))
      DEALLOCATE (projector)

   END SUBROUTINE qs_scf_kp_canonical_density_residual

! **************************************************************************************************
!> \brief Decide whether canonical-density mismatch must enlarge the active Schur pair space.
!>
!>        The raw OT residual is the scale already represented by the current minimizer model.
!>        In the calibrated coupled tail, omitting a larger individual canonical-density pair makes
!>        the reduced response blind to a physically dominant occupied-projector relabeling mode.
!>        The aggregate density residual is an RMS over a different number of variables and must
!>        therefore not be compared with the raw residual before the elementwise pair test.  A
!>        positive raw residual is still required so a freshly rebuilt MO space cannot activate
!>        pairs from stale or uncalibrated residual history.
!> \param density_ready canonical fixed-N density audit is valid for the current orbitals
!> \param density_delta RMS canonical-density residual in energy units
!> \param raw_delta unprojected residual of the previous accepted OT state
!> \param eps_scf requested SCF residual
!> \return true when density-selected complex pairs belong in the coupled response space
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_density_pair_activation_ready(density_ready, density_delta, raw_delta, &
                                                         eps_scf) RESULT(ready)
      LOGICAL, INTENT(IN)                                :: density_ready
      REAL(KIND=dp), INTENT(IN)                          :: density_delta, raw_delta, eps_scf
      LOGICAL                                            :: ready

      ready = density_ready .AND. eps_scf > 0.0_dp .AND. raw_delta > 0.0_dp .AND. &
              raw_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
              density_delta > eps_scf

   END FUNCTION qs_scf_kp_density_pair_activation_ready

! **************************************************************************************************
!> \brief Build the finite-generator tangent which rotates the current diagonal occupation
!>        matrix toward the fixed-N canonical density in the current orbital basis.
!> \param x_re real antisymmetric part of the finite OT generator
!> \param x_im imaginary symmetric part of the finite OT generator
!> \param eigenvectors eigenvectors of the current projected Hamiltonian
!> \param current_occupation occupations attached to the current orbital labels
!> \param canonical_occupation fixed-N occupations of the projected Hamiltonian eigenvalues
!> \param occupation_regularization Tikhonov floor for nearly equal occupation pairs
!> \param frechet_regularization Tikhonov floor for a nearly singular exponential map
!> \param max_pair_rotation current-frame trust radius for the physical density rotation
!> \param tangent_re real antisymmetric generator-coordinate tangent
!> \param tangent_im imaginary symmetric generator-coordinate tangent
!> \param target_offdiag_norm off-diagonal norm of the canonical density mismatch
!> \param linear_offdiag_norm mismatch norm after the mapped linear tangent
!> \param tangent_norm norm of the returned finite-generator tangent
!> \param active_i optional first orbital of the active complex rotation coordinates
!> \param active_j optional second orbital of the active complex rotation coordinates
!> \param active_kind optional coordinate kind, 1 for real and 2 for imaginary
!> \param cauchy_tangent_re optional real finite-generator Cauchy tangent
!> \param cauchy_tangent_im optional imaginary finite-generator Cauchy tangent
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_canonical_density_tangent( &
      x_re, x_im, eigenvectors, current_occupation, canonical_occupation, &
      occupation_regularization, frechet_regularization, max_pair_rotation, tangent_re, tangent_im, &
      target_offdiag_norm, linear_offdiag_norm, tangent_norm, active_i, active_j, active_kind, &
      cauchy_tangent_re, cauchy_tangent_im)

      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: x_re, x_im
      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(IN)      :: eigenvectors
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: current_occupation, canonical_occupation
      REAL(KIND=dp), INTENT(IN)                          :: occupation_regularization, &
                                                            frechet_regularization, &
                                                            max_pair_rotation
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: tangent_re, tangent_im
      REAL(KIND=dp), INTENT(OUT)                         :: target_offdiag_norm, &
                                                            linear_offdiag_norm, tangent_norm
      INTEGER, DIMENSION(:), INTENT(IN), OPTIONAL        :: active_i, active_j, active_kind
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT), &
         OPTIONAL                                        :: cauchy_tangent_re, cauchy_tangent_im

      COMPLEX(KIND=dp)                                   :: kernel, right_kernel
      COMPLEX(KIND=dp), ALLOCATABLE, DIMENSION(:, :) :: achieved, achieved_inner, cauchy_omega, &
         cauchy_tangent, density_residual, generator, generator_evec, omega, omega_inner, tangent, &
         tangent_inner, weighted_evec
      INTEGER                                            :: i, j, n
      REAL(KIND=dp)                                      :: frechet_floor_sq, tangent_norm_sq, &
                                                            target_norm_sq
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: generator_evals

      n = SIZE(current_occupation)
      CPASSERT(n > 0)
      CPASSERT(ALL(SHAPE(x_re) == [n, n]))
      CPASSERT(ALL(SHAPE(x_im) == [n, n]))
      CPASSERT(ALL(SHAPE(eigenvectors) == [n, n]))
      CPASSERT(SIZE(canonical_occupation) == n)
      CPASSERT(ALL(SHAPE(tangent_re) == [n, n]))
      CPASSERT(ALL(SHAPE(tangent_im) == [n, n]))
      CPASSERT(occupation_regularization >= 0.0_dp)
      CPASSERT(frechet_regularization >= 0.0_dp)
      CPASSERT(max_pair_rotation > 0.0_dp)
      CPASSERT(PRESENT(active_i) .EQV. PRESENT(active_j))
      CPASSERT(PRESENT(active_i) .EQV. PRESENT(active_kind))
      CPASSERT(PRESENT(cauchy_tangent_re) .EQV. PRESENT(cauchy_tangent_im))
      IF (PRESENT(active_i)) THEN
         CPASSERT(SIZE(active_j) == SIZE(active_i))
         CPASSERT(SIZE(active_kind) == SIZE(active_i))
      END IF
      IF (PRESENT(cauchy_tangent_re)) THEN
         CPASSERT(ALL(SHAPE(cauchy_tangent_re) == [n, n]))
         CPASSERT(ALL(SHAPE(cauchy_tangent_im) == [n, n]))
      END IF

      ALLOCATE (achieved(n, n), achieved_inner(n, n), cauchy_omega(n, n), &
                cauchy_tangent(n, n), density_residual(n, n), generator(n, n), &
                generator_evec(n, n), omega(n, n), omega_inner(n, n), tangent(n, n), &
                tangent_inner(n, n), weighted_evec(n, n), generator_evals(n))

      weighted_evec(:, :) = eigenvectors(:, :)
      DO i = 1, n
         weighted_evec(:, i) = canonical_occupation(i)*weighted_evec(:, i)
      END DO
      density_residual(:, :) = MATMUL(weighted_evec, CONJG(TRANSPOSE(eigenvectors)))
      DO i = 1, n
         density_residual(i, i) = density_residual(i, i) - current_occupation(i)
      END DO

      ! For U -> U exp(Omega), d(U f U^H)=[Omega,f].  Use the complete
      ! Riemannian Hessian of 0.5*||U f U^H-P_FD||^2, not the pairwise
      ! Gauss-Newton inverse.  The residual-Hessian term couples real and
      ! imaginary rotations and prevents nearly equal occupations from
      ! becoming large gauge-dominated pair steps.
      CALL canonical_density_trust_tangent( &
         density_residual, current_occupation, occupation_regularization, max_pair_rotation, omega, &
         active_i, active_j, active_kind, cauchy_omega)

      ! The OT variables are the finite generator X, while Omega=U^H dU is
      ! the physical tangent in the current orbital frame.  Invert the
      ! right-trivialized Frechet derivative of U=exp(X), rather than treating
      ! the local Omega as an additive finite-generator coordinate.
      generator(:, :) = CMPLX(-x_im(:, :), x_re(:, :), KIND=dp)
      CALL diag_complex(generator, generator_evec, generator_evals)
      omega_inner(:, :) = MATMUL(CONJG(TRANSPOSE(generator_evec)), &
                                 MATMUL(omega, generator_evec))
      tangent_inner(:, :) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)
      frechet_floor_sq = frechet_regularization**2
      DO j = 1, n
         DO i = 1, n
            kernel = qs_ot_complex_exp_frechet_kernel(generator_evals(i), generator_evals(j))
            right_kernel = EXP(CMPLX(0.0_dp, generator_evals(i), KIND=dp))*kernel
            tangent_inner(i, j) = omega_inner(i, j)*CONJG(right_kernel)/ &
                                  (ABS(right_kernel)**2 + frechet_floor_sq + EPSILON(1.0_dp))
         END DO
      END DO
      tangent(:, :) = MATMUL(generator_evec, &
                             MATMUL(tangent_inner, CONJG(TRANSPOSE(generator_evec))))
      tangent(:, :) = 0.5_dp*(tangent(:, :) - CONJG(TRANSPOSE(tangent(:, :))))
      DO i = 1, n
         tangent(i, i) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)
      END DO
      tangent_re(:, :) = REAL(tangent, KIND=dp)
      tangent_im(:, :) = AIMAG(tangent)

      IF (PRESENT(cauchy_tangent_re)) THEN
         omega_inner(:, :) = MATMUL(CONJG(TRANSPOSE(generator_evec)), &
                                    MATMUL(cauchy_omega, generator_evec))
         tangent_inner(:, :) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)
         DO j = 1, n
            DO i = 1, n
               kernel = qs_ot_complex_exp_frechet_kernel(generator_evals(i), generator_evals(j))
               right_kernel = EXP(CMPLX(0.0_dp, generator_evals(i), KIND=dp))*kernel
               tangent_inner(i, j) = omega_inner(i, j)*CONJG(right_kernel)/ &
                                     (ABS(right_kernel)**2 + frechet_floor_sq + EPSILON(1.0_dp))
            END DO
         END DO
         cauchy_tangent(:, :) = MATMUL(generator_evec, &
                                       MATMUL(tangent_inner, CONJG(TRANSPOSE(generator_evec))))
         cauchy_tangent(:, :) = &
            0.5_dp*(cauchy_tangent(:, :) - CONJG(TRANSPOSE(cauchy_tangent(:, :))))
         DO i = 1, n
            cauchy_tangent(i, i) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)
         END DO
         cauchy_tangent_re(:, :) = REAL(cauchy_tangent, KIND=dp)
         cauchy_tangent_im(:, :) = AIMAG(cauchy_tangent)
      END IF

      ! Re-evaluate the physical linear tangent after projecting out diagonal
      ! phase gauges, so the reported reduction describes exactly the
      ! coordinates returned to the OT minimizer.
      tangent_inner(:, :) = MATMUL(CONJG(TRANSPOSE(generator_evec)), &
                                   MATMUL(tangent, generator_evec))
      DO j = 1, n
         DO i = 1, n
            kernel = qs_ot_complex_exp_frechet_kernel(generator_evals(i), generator_evals(j))
            right_kernel = EXP(CMPLX(0.0_dp, generator_evals(i), KIND=dp))*kernel
            achieved_inner(i, j) = right_kernel*tangent_inner(i, j)
         END DO
      END DO
      achieved(:, :) = MATMUL(generator_evec, &
                              MATMUL(achieved_inner, CONJG(TRANSPOSE(generator_evec))))
      achieved(:, :) = 0.5_dp*(achieved(:, :) - CONJG(TRANSPOSE(achieved(:, :))))

      target_norm_sq = 0.0_dp
      linear_offdiag_norm = 0.0_dp
      DO j = 2, n
         DO i = 1, j - 1
            target_norm_sq = target_norm_sq + 2.0_dp*ABS(density_residual(i, j))**2
            linear_offdiag_norm = linear_offdiag_norm + &
                                  2.0_dp*ABS(density_residual(i, j) - &
                                             (current_occupation(j) - current_occupation(i))*achieved(i, j))**2
         END DO
      END DO
      tangent_norm_sq = REAL(SUM(CONJG(tangent(:, :))*tangent(:, :)), KIND=dp)
      target_offdiag_norm = SQRT(MAX(0.0_dp, target_norm_sq))
      linear_offdiag_norm = SQRT(MAX(0.0_dp, linear_offdiag_norm))
      tangent_norm = SQRT(MAX(0.0_dp, tangent_norm_sq))

      DEALLOCATE (achieved, achieved_inner, cauchy_omega, cauchy_tangent, density_residual, &
                  generator, generator_evec, omega, omega_inner, tangent, tangent_inner, &
                  weighted_evec, generator_evals)

   END SUBROUTINE qs_scf_kp_canonical_density_tangent

! **************************************************************************************************
!> \brief Build a gradient-connected trust-region Newton tangent for the canonical density.
!> \param density_residual P_FD-f in the current orbital frame
!> \param occupation current diagonal occupations
!> \param curvature_regularization numerical floor for the shifted Hessian
!> \param trust_radius Euclidean radius of the independent anti-Hermitian coordinates
!> \param omega local anti-Hermitian density-rotation tangent
!> \param active_i optional first orbital of active coordinates
!> \param active_j optional second orbital of active coordinates
!> \param active_kind optional coordinate kind, 1 for real and 2 for imaginary
!> \param cauchy_omega optional trust-region Cauchy direction in the current orbital frame
! **************************************************************************************************
   SUBROUTINE canonical_density_trust_tangent( &
      density_residual, occupation, curvature_regularization, trust_radius, omega, &
      active_i, active_j, active_kind, cauchy_omega)

      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(IN)      :: density_residual
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: occupation
      REAL(KIND=dp), INTENT(IN)                          :: curvature_regularization, trust_radius
      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(OUT)     :: omega
      INTEGER, DIMENSION(:), INTENT(IN), OPTIONAL        :: active_i, active_j, active_kind
      COMPLEX(KIND=dp), DIMENSION(:, :), INTENT(OUT), &
         OPTIONAL                                        :: cauchy_omega

      INTEGER, PARAMETER                                 :: trust_bisection_steps = 80

      COMPLEX(KIND=dp)                                   :: basis_value, response_value
      COMPLEX(KIND=dp), ALLOCATABLE, DIMENSION(:, :)     :: basis, commutator_left, &
                                                            commutator_right, density_error, &
                                                            response
      INTEGER                                            :: i, icoord, j, jcoord, kind, n, ncoord
      INTEGER, ALLOCATABLE, DIMENSION(:)                 :: coord_i, coord_j, coord_kind
      LOGICAL                                            :: boundary_step
      REAL(KIND=dp) :: cauchy_curvature, cauchy_scale, curvature_scale, direction_norm, &
         gradient_dot, gradient_norm_sq, shift, shift_high, shift_low, shift_mid, shift_tolerance
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: cauchy_direction, coefficients, &
                                                            direction, eigenvalues, gradient, &
                                                            projected_gradient
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: hessian

      n = SIZE(occupation)
      CPASSERT(n > 0)
      CPASSERT(ALL(SHAPE(density_residual) == [n, n]))
      CPASSERT(ALL(SHAPE(omega) == [n, n]))
      IF (PRESENT(cauchy_omega)) THEN
         CPASSERT(ALL(SHAPE(cauchy_omega) == [n, n]))
      END IF
      CPASSERT(curvature_regularization >= 0.0_dp)
      CPASSERT(trust_radius > 0.0_dp)
      CPASSERT(PRESENT(active_i) .EQV. PRESENT(active_j))
      CPASSERT(PRESENT(active_i) .EQV. PRESENT(active_kind))

      IF (PRESENT(active_i)) THEN
         ncoord = SIZE(active_i)
         CPASSERT(SIZE(active_j) == ncoord)
         CPASSERT(SIZE(active_kind) == ncoord)
      ELSE
         ncoord = n*(n - 1)
      END IF
      omega(:, :) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)
      IF (PRESENT(cauchy_omega)) cauchy_omega(:, :) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)
      IF (ncoord <= 0) RETURN

      ALLOCATE (coord_i(ncoord), coord_j(ncoord), coord_kind(ncoord))
      IF (PRESENT(active_i)) THEN
         coord_i(:) = active_i(:)
         coord_j(:) = active_j(:)
         coord_kind(:) = active_kind(:)
      ELSE
         icoord = 0
         DO j = 2, n
            DO i = 1, j - 1
               icoord = icoord + 1
               coord_i(icoord) = i
               coord_j(icoord) = j
               coord_kind(icoord) = 1
               icoord = icoord + 1
               coord_i(icoord) = i
               coord_j(icoord) = j
               coord_kind(icoord) = 2
            END DO
         END DO
         CPASSERT(icoord == ncoord)
      END IF
      CPASSERT(ALL(coord_i >= 1 .AND. coord_i <= n))
      CPASSERT(ALL(coord_j >= 1 .AND. coord_j <= n))
      CPASSERT(ALL(coord_i < coord_j))
      CPASSERT(ALL(coord_kind == 1 .OR. coord_kind == 2))

      ALLOCATE (basis(n, n), commutator_left(n, n), commutator_right(n, n), &
                density_error(n, n), response(n, n))
      ALLOCATE (cauchy_direction(ncoord), coefficients(ncoord), direction(ncoord), &
                eigenvalues(ncoord), gradient(ncoord), projected_gradient(ncoord), &
                hessian(ncoord, ncoord))
      density_error(:, :) = -density_residual(:, :)
      gradient(:) = 0.0_dp
      hessian(:, :) = 0.0_dp

      DO jcoord = 1, ncoord
         i = coord_i(jcoord)
         j = coord_j(jcoord)
         kind = coord_kind(jcoord)
         basis_value = MERGE(CMPLX(1.0_dp, 0.0_dp, KIND=dp), &
                             CMPLX(0.0_dp, 1.0_dp, KIND=dp), kind == 1)
         basis(:, :) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)
         basis(i, j) = basis_value
         basis(j, i) = -CONJG(basis_value)
         response(:, :) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)
         response_value = basis_value*(occupation(j) - occupation(i))
         response(i, j) = response_value
         response(j, i) = CONJG(response_value)

         gradient(jcoord) = 2.0_dp*REAL(CONJG(density_error(i, j))*response_value, KIND=dp)
         commutator_left(:, :) = MATMUL(density_error, basis) - MATMUL(basis, density_error)
         commutator_right(:, :) = MATMUL(response, density_error) - MATMUL(density_error, response)
         DO icoord = 1, ncoord
            i = coord_i(icoord)
            j = coord_j(icoord)
            kind = coord_kind(icoord)
            basis_value = MERGE(CMPLX(1.0_dp, 0.0_dp, KIND=dp), &
                                CMPLX(0.0_dp, 1.0_dp, KIND=dp), kind == 1)
            response_value = basis_value*(occupation(j) - occupation(i))
            hessian(icoord, jcoord) = &
               MERGE(2.0_dp*ABS(response_value)**2, 0.0_dp, icoord == jcoord) + &
               REAL(CONJG(commutator_left(i, j))*response_value - &
                    CONJG(commutator_right(i, j))*basis_value, KIND=dp)
         END DO
      END DO
      hessian(:, :) = 0.5_dp*(hessian(:, :) + TRANSPOSE(hessian(:, :)))

      cauchy_direction(:) = -gradient(:)
      gradient_norm_sq = DOT_PRODUCT(gradient, gradient)
      cauchy_scale = 0.0_dp
      IF (gradient_norm_sq > EPSILON(gradient_norm_sq)) THEN
         direction_norm = SQRT(gradient_norm_sq)
         cauchy_scale = trust_radius/direction_norm
         cauchy_curvature = DOT_PRODUCT(cauchy_direction, MATMUL(hessian, cauchy_direction))
         IF (cauchy_curvature > EPSILON(ABS(cauchy_curvature))) &
            cauchy_scale = MIN(cauchy_scale, gradient_norm_sq/cauchy_curvature)
      END IF
      cauchy_direction(:) = cauchy_scale*cauchy_direction(:)

      CALL diamat_all(hessian, eigenvalues, dac=.TRUE.)
      projected_gradient(:) = MATMUL(TRANSPOSE(hessian), gradient)
      curvature_scale = MAX(1.0_dp, MAXVAL(ABS(eigenvalues)))
      shift_tolerance = MAX(curvature_regularization**2, &
                            100.0_dp*EPSILON(curvature_scale)*curvature_scale)
      boundary_step = eigenvalues(1) <= shift_tolerance
      IF (.NOT. boundary_step) THEN
         coefficients(:) = -projected_gradient(:)/eigenvalues(:)
         boundary_step = DOT_PRODUCT(coefficients, coefficients) > trust_radius**2
      END IF

      IF (boundary_step) THEN
         shift_low = MAX(0.0_dp, -eigenvalues(1)) + shift_tolerance
         shift_high = MAX(1.0_dp, 2.0_dp*shift_low, &
                          MAXVAL(ABS(projected_gradient))/MAX(trust_radius, EPSILON(trust_radius)))
         DO
            coefficients(:) = -projected_gradient(:)/(eigenvalues(:) + shift_high)
            IF (DOT_PRODUCT(coefficients, coefficients) <= trust_radius**2) EXIT
            shift_high = 2.0_dp*shift_high
         END DO
         coefficients(:) = -projected_gradient(:)/(eigenvalues(:) + shift_low)
         IF (DOT_PRODUCT(coefficients, coefficients) <= trust_radius**2) THEN
            shift = shift_low
         ELSE
            DO icoord = 1, trust_bisection_steps
               shift_mid = 0.5_dp*(shift_low + shift_high)
               coefficients(:) = -projected_gradient(:)/(eigenvalues(:) + shift_mid)
               IF (DOT_PRODUCT(coefficients, coefficients) > trust_radius**2) THEN
                  shift_low = shift_mid
               ELSE
                  shift_high = shift_mid
               END IF
            END DO
            shift = shift_high
         END IF
         coefficients(:) = -projected_gradient(:)/(eigenvalues(:) + shift)
      END IF

      direction(:) = MATMUL(hessian, coefficients)
      gradient_dot = DOT_PRODUCT(gradient, direction)
      IF (gradient_dot >= 0.0_dp .OR. gradient_dot /= gradient_dot) THEN
         direction(:) = -gradient(:)
         direction_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(direction, direction)))
         IF (direction_norm > trust_radius) direction(:) = (trust_radius/direction_norm)*direction(:)
      END IF

      DO icoord = 1, ncoord
         i = coord_i(icoord)
         j = coord_j(icoord)
         kind = coord_kind(icoord)
         IF (kind == 1) THEN
            omega(i, j) = omega(i, j) + CMPLX(direction(icoord), 0.0_dp, KIND=dp)
         ELSE
            omega(i, j) = omega(i, j) + CMPLX(0.0_dp, direction(icoord), KIND=dp)
         END IF
      END DO
      DO j = 2, n
         DO i = 1, j - 1
            omega(j, i) = -CONJG(omega(i, j))
         END DO
      END DO
      IF (PRESENT(cauchy_omega)) THEN
         DO icoord = 1, ncoord
            i = coord_i(icoord)
            j = coord_j(icoord)
            kind = coord_kind(icoord)
            IF (kind == 1) THEN
               cauchy_omega(i, j) = cauchy_omega(i, j) + &
                                    CMPLX(cauchy_direction(icoord), 0.0_dp, KIND=dp)
            ELSE
               cauchy_omega(i, j) = cauchy_omega(i, j) + &
                                    CMPLX(0.0_dp, cauchy_direction(icoord), KIND=dp)
            END IF
         END DO
         DO j = 2, n
            DO i = 1, j - 1
               cauchy_omega(j, i) = -CONJG(cauchy_omega(i, j))
            END DO
         END DO
      END IF

      DEALLOCATE (basis, cauchy_direction, coefficients, commutator_left, commutator_right, &
                  coord_i, coord_j, coord_kind, density_error, direction, eigenvalues, gradient, &
                  hessian, projected_gradient, response)

   END SUBROUTINE canonical_density_trust_tangent

! **************************************************************************************************
!> \brief Select a bounded canonical-density tangent in the same reduced fixed-N Mermin model as
!>        the coupled rotation/energy candidate.
!> \param grad_rot rotation gradient
!> \param grad_e energy-variable gradient
!> \param rot_hessian finite complex rotation Hessian
!> \param energy_cross rotation/energy Hessian cross block
!> \param energy_response fixed-N solution H_ee^-1 H_er
!> \param base_rot base rotation candidate
!> \param tangent_rot canonical-density rotation tangent
!> \param alpha optimal bounded tangent coefficient
!> \param tangent_gdot Mermin gradient contraction with the tangent
!> \param tangent_cross reduced-Hessian cross term between base and tangent
!> \param tangent_curvature reduced-Hessian tangent curvature
!> \param tangent_gain predicted incremental Mermin decrease at alpha
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_canonical_density_blend( &
      grad_rot, grad_e, rot_hessian, energy_cross, energy_response, base_rot, tangent_rot, &
      alpha, tangent_gdot, tangent_cross, tangent_curvature, tangent_gain)

      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: grad_rot, grad_e
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: rot_hessian, energy_cross, &
                                                            energy_response
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: base_rot, tangent_rot
      REAL(KIND=dp), INTENT(OUT)                         :: alpha, tangent_gdot, tangent_cross, &
                                                            tangent_curvature, tangent_gain

      INTEGER                                            :: ne, nrot
      REAL(KIND=dp)                                      :: endpoint_gain
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: base_cross, base_response, hessian_base, &
                                                            hessian_tangent, tangent_cross_energy, &
                                                            tangent_response

      nrot = SIZE(grad_rot)
      ne = SIZE(grad_e)
      CPASSERT(nrot > 0)
      CPASSERT(ne > 0)
      CPASSERT(SIZE(base_rot) == nrot)
      CPASSERT(SIZE(tangent_rot) == nrot)
      CPASSERT(ALL(SHAPE(rot_hessian) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(energy_cross) == [ne, nrot]))
      CPASSERT(ALL(SHAPE(energy_response) == [ne, nrot]))

      ALLOCATE (base_cross(ne), base_response(ne), hessian_base(nrot), &
                hessian_tangent(nrot), tangent_cross_energy(ne), tangent_response(ne))
      base_cross(:) = MATMUL(energy_cross, base_rot)
      tangent_cross_energy(:) = MATMUL(energy_cross, tangent_rot)
      base_response(:) = MATMUL(energy_response, base_rot)
      tangent_response(:) = MATMUL(energy_response, tangent_rot)
      hessian_base(:) = 0.5_dp*MATMUL(rot_hessian + TRANSPOSE(rot_hessian), base_rot)
      hessian_tangent(:) = 0.5_dp*MATMUL(rot_hessian + TRANSPOSE(rot_hessian), tangent_rot)

      ! With the CP2K search convention H_ee e - H_er r = g_e, eliminating e gives
      ! S = H_rr - sym(H_re H_ee^-1 H_er).  Evaluate both the tangent curvature and
      ! its cross term with the base in that same dense reduced model.
      tangent_gdot = DOT_PRODUCT(grad_rot, tangent_rot) + &
                     DOT_PRODUCT(grad_e, tangent_response)
      tangent_cross = DOT_PRODUCT(tangent_rot, hessian_base) - &
                      0.5_dp*(DOT_PRODUCT(tangent_response, base_cross) + &
                              DOT_PRODUCT(tangent_cross_energy, base_response))
      tangent_curvature = DOT_PRODUCT(tangent_rot, hessian_tangent) - &
                          DOT_PRODUCT(tangent_response, tangent_cross_energy)

      alpha = 0.0_dp
      tangent_gain = 0.0_dp
      IF (tangent_curvature > EPSILON(ABS(tangent_curvature))) THEN
         alpha = MIN(1.0_dp, MAX(0.0_dp, &
                                 (tangent_gdot - tangent_cross)/tangent_curvature))
         tangent_gain = alpha*(tangent_gdot - tangent_cross) - &
                        0.5_dp*alpha*alpha*tangent_curvature
      ELSE
         ! A negative reduced mode is not a reason to discard a bounded physical
         ! tangent: the Mermin decrease is then maximal at an endpoint.
         endpoint_gain = tangent_gdot - tangent_cross - 0.5_dp*tangent_curvature
         IF (endpoint_gain > EPSILON(ABS(endpoint_gain))) THEN
            alpha = 1.0_dp
            tangent_gain = endpoint_gain
         END IF
      END IF
      IF (tangent_gain <= EPSILON(ABS(tangent_gain))) THEN
         alpha = 0.0_dp
         tangent_gain = 0.0_dp
      END IF

      DEALLOCATE (base_cross, base_response, hessian_base, hessian_tangent, &
                  tangent_cross_energy, tangent_response)

   END SUBROUTINE qs_scf_kp_canonical_density_blend

! **************************************************************************************************
!> \brief Blend independent channel density tangents in one coupled fixed-N Mermin model.
!> \param grad_rot rotation gradient
!> \param grad_e energy-variable gradient
!> \param rot_hessian finite complex rotation Hessian
!> \param energy_cross rotation/energy Hessian cross block
!> \param energy_response fixed-N solution H_ee^-1 H_er
!> \param base_rot base rotation candidate
!> \param tangent_modes channel-resolved canonical-density tangents
!> \param initial_alpha common scalar coefficient used as the feasible starting point
!> \param alpha optimized bounded coefficient of every tangent mode
!> \param mode_linear reduced-model linear gain of every mode
!> \param mode_curvature reduced-model diagonal curvature of every mode
!> \param total_gain predicted incremental Mermin decrease
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_canonical_density_multimode_blend( &
      grad_rot, grad_e, rot_hessian, energy_cross, energy_response, base_rot, tangent_modes, &
      initial_alpha, alpha, mode_linear, mode_curvature, total_gain)

      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: grad_rot, grad_e
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: rot_hessian, energy_cross, &
                                                            energy_response
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: base_rot
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: tangent_modes
      REAL(KIND=dp), INTENT(IN)                          :: initial_alpha
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: alpha, mode_linear, mode_curvature
      REAL(KIND=dp), INTENT(OUT)                         :: total_gain

      INTEGER, PARAMETER                                 :: coordinate_sweeps = 16

      INTEGER                                            :: imode, isweep, ne, nmode, nrot
      REAL(KIND=dp)                                      :: effective_linear, endpoint_gain
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: base_cross, base_response, hessian_base, &
                                                            mode_gdot
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: hessian_modes, mode_cross_energy, &
                                                            mode_response, reduced_mode_hessian

      nrot = SIZE(grad_rot)
      ne = SIZE(grad_e)
      nmode = SIZE(tangent_modes, 2)
      CPASSERT(nrot > 0)
      CPASSERT(ne > 0)
      CPASSERT(nmode > 0)
      CPASSERT(SIZE(base_rot) == nrot)
      CPASSERT(SIZE(tangent_modes, 1) == nrot)
      CPASSERT(ALL(SHAPE(rot_hessian) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(energy_cross) == [ne, nrot]))
      CPASSERT(ALL(SHAPE(energy_response) == [ne, nrot]))
      CPASSERT(SIZE(alpha) == nmode)
      CPASSERT(SIZE(mode_linear) == nmode)
      CPASSERT(SIZE(mode_curvature) == nmode)

      ALLOCATE (base_cross(ne), base_response(ne), hessian_base(nrot), mode_gdot(nmode))
      ALLOCATE (hessian_modes(nrot, nmode), mode_cross_energy(ne, nmode), &
                mode_response(ne, nmode), reduced_mode_hessian(nmode, nmode))
      base_cross(:) = MATMUL(energy_cross, base_rot)
      base_response(:) = MATMUL(energy_response, base_rot)
      hessian_base(:) = 0.5_dp*MATMUL(rot_hessian + TRANSPOSE(rot_hessian), base_rot)
      hessian_modes(:, :) = 0.5_dp*MATMUL(rot_hessian + TRANSPOSE(rot_hessian), tangent_modes)
      mode_cross_energy(:, :) = MATMUL(energy_cross, tangent_modes)
      mode_response(:, :) = MATMUL(energy_response, tangent_modes)

      mode_gdot(:) = MATMUL(TRANSPOSE(tangent_modes), grad_rot) + &
                     MATMUL(TRANSPOSE(mode_response), grad_e)
      mode_linear(:) = mode_gdot(:) - MATMUL(TRANSPOSE(tangent_modes), hessian_base) + &
                       0.5_dp*(MATMUL(TRANSPOSE(mode_response), base_cross) + &
                               MATMUL(TRANSPOSE(mode_cross_energy), base_response))
      reduced_mode_hessian(:, :) = MATMUL(TRANSPOSE(tangent_modes), hessian_modes) - &
                                   0.5_dp*(MATMUL(TRANSPOSE(mode_response), mode_cross_energy) + &
                                           MATMUL(TRANSPOSE(mode_cross_energy), mode_response))
      reduced_mode_hessian(:, :) = &
         0.5_dp*(reduced_mode_hessian(:, :) + TRANSPOSE(reduced_mode_hessian(:, :)))
      DO imode = 1, nmode
         mode_curvature(imode) = reduced_mode_hessian(imode, imode)
      END DO

      alpha(:) = MIN(1.0_dp, MAX(0.0_dp, initial_alpha))
      DO imode = 1, nmode
         IF (MAXVAL(ABS(tangent_modes(:, imode))) <= EPSILON(1.0_dp)) alpha(imode) = 0.0_dp
      END DO
      DO isweep = 1, coordinate_sweeps
         DO imode = 1, nmode
            IF (MAXVAL(ABS(tangent_modes(:, imode))) <= EPSILON(1.0_dp)) CYCLE
            effective_linear = mode_linear(imode) - &
                               DOT_PRODUCT(reduced_mode_hessian(imode, :), alpha) + &
                               reduced_mode_hessian(imode, imode)*alpha(imode)
            IF (mode_curvature(imode) > EPSILON(ABS(mode_curvature(imode)))) THEN
               alpha(imode) = MIN(1.0_dp, MAX(0.0_dp, &
                                              effective_linear/mode_curvature(imode)))
            ELSE
               endpoint_gain = effective_linear - 0.5_dp*mode_curvature(imode)
               alpha(imode) = MERGE(1.0_dp, 0.0_dp, endpoint_gain > 0.0_dp)
            END IF
         END DO
      END DO
      total_gain = DOT_PRODUCT(mode_linear, alpha) - &
                   0.5_dp*DOT_PRODUCT(alpha, MATMUL(reduced_mode_hessian, alpha))
      IF (total_gain <= EPSILON(ABS(total_gain))) THEN
         alpha(:) = 0.0_dp
         total_gain = 0.0_dp
      END IF

      DEALLOCATE (base_cross, base_response, hessian_base, hessian_modes, mode_cross_energy, &
                  mode_gdot, mode_response, reduced_mode_hessian)

   END SUBROUTINE qs_scf_kp_canonical_density_multimode_blend

! **************************************************************************************************
!> \brief Fit accepted self-consistent response secants in physical density modes.
!>
!>        Rotation and response gauge components are removed before fitting one symmetric
!>        Hessian from the most independent pair in the canonical fixed-N density tangent
!>        span.  Additional accepted secants remain in the residual audit.  The compatible
!>        signed fit retains both positive and negative physical response modes without a
!>        least-change completion in the unconstrained rotation space.  If the accepted
!>        steps resolve only one physical direction, retain only the scalar curvature
!>        projected onto that direction.  A transverse target determines a cross coupling
!>        but not the companion orthogonal curvature needed to close its indefinite block,
!>        so it remains a reported residual and the orthogonal density curvature stays
!>        unsupported.
!> \param tangent_modes physical channel-resolved density tangents
!> \param response_steps accepted rotation steps
!> \param response_targets measured closure-gradient changes for those steps
!> \param response_correction validated low-rank response in rotation coordinates
!> \param ready at least one physical response mode was retained
!> \param positive_modes number of retained positive-curvature modes
!> \param negative_modes number of retained negative-curvature modes
!> \param unsupported_modes number of dependent or numerically unsupported modes
!> \param independence normalized independence of the projected accepted steps
!> \param compatibility_norm relative correction enforcing a symmetric secant pair
!> \param residual_ratio relative residual against the unmodified projected targets
!> \param response_prior optional analytic physical response already present in the candidate
!> \param fitted_residual_ratio optional normalized residual of the full-rank all-sample shadow fit
!> \param pair_fitted_residual_ratio optional normalized residual of the active pair response
!> \param fullrank_response_correction optional passive all-sample correction in rotation space
!> \param response_baseline optional response already present in the candidate when response_prior
!>        is a separately fitted physical model
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_validated_density_response( &
      tangent_modes, response_steps, response_targets, response_correction, ready, &
      positive_modes, negative_modes, unsupported_modes, independence, compatibility_norm, &
      residual_ratio, response_prior, fitted_residual_ratio, pair_fitted_residual_ratio, &
      fullrank_response_correction, response_baseline)

      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: tangent_modes, response_steps, &
                                                            response_targets
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: response_correction
      LOGICAL, INTENT(OUT)                               :: ready
      INTEGER, INTENT(OUT)                               :: positive_modes, negative_modes, &
                                                            unsupported_modes
      REAL(KIND=dp), INTENT(OUT)                         :: independence, compatibility_norm, &
                                                            residual_ratio
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN), &
         OPTIONAL                                        :: response_prior
      REAL(KIND=dp), INTENT(OUT), OPTIONAL               :: fitted_residual_ratio, &
                                                            pair_fitted_residual_ratio
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT), &
         OPTIONAL                                        :: fullrank_response_correction
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN), &
         OPTIONAL                                        :: response_baseline

      INTEGER                                            :: active_modes, best_i, best_j, &
                                                            fullrank_samples, i, imode, isample, &
                                                            j, jmode, jsample, nmode, nrot, nsample
      LOGICAL                                            :: fit_ready, fullrank_fit_ready, &
                                                            rank_one_fit
      REAL(KIND=dp) :: best_independence, correction_norm, curvature_floor, &
         fullrank_residual_ratio, initial_norm, mode_curvature, mode_norm, normalized_target_norm, &
         pair_fit_residual_ratio, pair_independence, pair_residual_ratio, projected_target_norm, &
         residual_norm, response_scale, step_cosine, step_dot, step_norm_i, step_norm_j, &
         step_norm_sq, updated_residual_norm
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: eigenvalues, fullrank_eigenvalues, mode, &
                                                            sample_coeff, step_eigenvalues, &
                                                            supported_step, supported_target
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :) :: basis, fullrank_correction, &
         fullrank_eigenvectors, fullrank_inner, fullrank_residual, fullrank_rhs, normalized_steps, &
         normalized_targets, projected_residual, projected_steps, projected_targets, &
         reduced_baseline, reduced_correction, reduced_eigenvectors, reduced_output_correction, &
         reduced_prior, reduced_response, residual_targets, response_modes, selected_steps, &
         selected_targets, step_eigenvectors

      nrot = SIZE(tangent_modes, 1)
      nmode = SIZE(tangent_modes, 2)
      nsample = SIZE(response_steps, 2)
      CPASSERT(SIZE(response_steps, 1) == nrot)
      CPASSERT(ALL(SHAPE(response_targets) == [nrot, nsample]))
      CPASSERT(ALL(SHAPE(response_correction) == [nrot, nrot]))
      IF (PRESENT(response_prior)) THEN
         CPASSERT(ALL(SHAPE(response_prior) == [nrot, nrot]))
      END IF
      IF (PRESENT(response_baseline)) THEN
         CPASSERT(ALL(SHAPE(response_baseline) == [nrot, nrot]))
      END IF
      IF (PRESENT(fullrank_response_correction)) THEN
         CPASSERT(ALL(SHAPE(fullrank_response_correction) == [nrot, nrot]))
      END IF

      response_correction(:, :) = 0.0_dp
      IF (PRESENT(fullrank_response_correction)) fullrank_response_correction(:, :) = 0.0_dp
      ready = .FALSE.
      positive_modes = 0
      negative_modes = 0
      unsupported_modes = nmode
      independence = 0.0_dp
      compatibility_norm = 0.0_dp
      residual_ratio = 0.0_dp
      IF (PRESENT(fitted_residual_ratio)) fitted_residual_ratio = 0.0_dp
      IF (PRESENT(pair_fitted_residual_ratio)) pair_fitted_residual_ratio = 0.0_dp
      IF (nrot <= 0 .OR. nmode <= 0 .OR. nsample < 2) RETURN
      IF (.NOT. ALL(response_steps == response_steps) .OR. &
          .NOT. ALL(response_targets == response_targets)) RETURN

      ALLOCATE (basis(nrot, nmode), mode(nrot))
      basis(:, :) = 0.0_dp
      active_modes = 0
      DO imode = 1, nmode
         mode(:) = tangent_modes(:, imode)
         initial_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(mode, mode)))
         IF (initial_norm <= TINY(1.0_dp)) CYCLE
         DO jmode = 1, active_modes
            mode(:) = mode - DOT_PRODUCT(basis(:, jmode), mode)*basis(:, jmode)
         END DO
         mode_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(mode, mode)))
         IF (mode_norm <= 64.0_dp*SQRT(EPSILON(1.0_dp))*initial_norm) CYCLE
         active_modes = active_modes + 1
         basis(:, active_modes) = mode/mode_norm
      END DO
      unsupported_modes = nmode - active_modes
      IF (active_modes <= 0) THEN
         DEALLOCATE (basis, mode)
         RETURN
      END IF

      ALLOCATE (eigenvalues(active_modes), projected_residual(active_modes, nsample), &
                projected_steps(active_modes, nsample), projected_targets(active_modes, nsample), &
                reduced_baseline(active_modes, active_modes), &
                reduced_correction(active_modes, active_modes), &
                reduced_eigenvectors(active_modes, active_modes), &
                reduced_output_correction(active_modes, active_modes), &
                reduced_prior(active_modes, active_modes), reduced_response(active_modes, active_modes), &
                residual_targets(active_modes, nsample), &
                response_modes(nrot, active_modes), selected_steps(active_modes, 2), &
                selected_targets(active_modes, 2))
      projected_steps(:, :) = MATMUL(TRANSPOSE(basis(:, 1:active_modes)), response_steps)
      projected_targets(:, :) = MATMUL(TRANSPOSE(basis(:, 1:active_modes)), response_targets)
      reduced_prior(:, :) = 0.0_dp
      IF (PRESENT(response_prior)) &
         reduced_prior(:, :) = MATMUL(TRANSPOSE(basis(:, 1:active_modes)), &
                                      MATMUL(0.5_dp*(response_prior + TRANSPOSE(response_prior)), &
                                             basis(:, 1:active_modes)))
      reduced_baseline(:, :) = reduced_prior(:, :)
      IF (PRESENT(response_baseline)) &
         reduced_baseline(:, :) = MATMUL(TRANSPOSE(basis(:, 1:active_modes)), &
                                         MATMUL(0.5_dp*(response_baseline + &
                                                        TRANSPOSE(response_baseline)), &
                                                basis(:, 1:active_modes)))
      residual_targets(:, :) = projected_targets - MATMUL(reduced_prior, projected_steps)
      reduced_response(:, :) = reduced_prior(:, :)
      reduced_correction(:, :) = 0.0_dp
      fit_ready = .FALSE.
      rank_one_fit = .FALSE.
      correction_norm = 0.0_dp
      residual_norm = 0.0_dp
      updated_residual_norm = 0.0_dp
      IF (active_modes == 1) THEN
         step_norm_sq = SUM(projected_steps**2)
         IF (step_norm_sq > EPSILON(1.0_dp)) THEN
            reduced_correction(1, 1) = SUM(projected_steps*residual_targets)/step_norm_sq
            reduced_response(1, 1) = reduced_prior(1, 1) + reduced_correction(1, 1)
            independence = 1.0_dp
            fit_ready = reduced_correction(1, 1) == reduced_correction(1, 1)
         END IF
      ELSE
         best_i = 0
         best_j = 0
         best_independence = -1.0_dp
         DO jsample = 2, nsample
            DO isample = 1, jsample - 1
               step_norm_i = DOT_PRODUCT(projected_steps(:, isample), &
                                         projected_steps(:, isample))
               step_norm_j = DOT_PRODUCT(projected_steps(:, jsample), &
                                         projected_steps(:, jsample))
               IF (step_norm_i <= TINY(1.0_dp) .OR. step_norm_j <= TINY(1.0_dp)) CYCLE
               step_dot = DOT_PRODUCT(projected_steps(:, isample), &
                                      projected_steps(:, jsample))
               step_cosine = MAX(-1.0_dp, MIN(1.0_dp, &
                                              step_dot/(SQRT(step_norm_i)*SQRT(step_norm_j))))
               pair_independence = MAX(0.0_dp, 1.0_dp - step_cosine*step_cosine)
               IF (pair_independence > best_independence) THEN
                  best_independence = pair_independence
                  best_i = isample
                  best_j = jsample
               END IF
            END DO
         END DO
         selected_steps(:, :) = 0.0_dp
         selected_targets(:, :) = 0.0_dp
         IF (best_i > 0) THEN
            selected_steps(:, 1) = projected_steps(:, best_i)
            selected_steps(:, 2) = projected_steps(:, best_j)
            selected_targets(:, 1) = projected_targets(:, best_i)
            selected_targets(:, 2) = projected_targets(:, best_j)
            DO isample = 1, 2
               step_norm_sq = DOT_PRODUCT(selected_steps(:, isample), &
                                          selected_steps(:, isample))
               IF (step_norm_sq <= TINY(1.0_dp)) EXIT
               response_scale = SQRT(step_norm_sq)
               selected_steps(:, isample) = selected_steps(:, isample)/response_scale
               selected_targets(:, isample) = selected_targets(:, isample)/response_scale
            END DO
         END IF
         CALL qs_scf_kp_symmetric_multisecant_update( &
            reduced_prior, selected_steps, selected_targets, 1.0_dp, reduced_response, &
            fit_ready, independence, compatibility_norm, correction_norm, residual_norm, &
            updated_residual_norm)
         reduced_correction(:, :) = reduced_response - reduced_prior
         IF (.NOT. fit_ready) THEN
            ALLOCATE (sample_coeff(SIZE(projected_steps, 2)), &
                      step_eigenvalues(active_modes), step_eigenvectors(active_modes, active_modes), &
                      supported_step(active_modes), supported_target(active_modes))
            step_eigenvectors(:, :) = MATMUL(projected_steps, TRANSPOSE(projected_steps))
            CALL diamat_all(step_eigenvectors, step_eigenvalues)
            step_norm_sq = MAX(0.0_dp, step_eigenvalues(active_modes))
            IF (step_norm_sq > EPSILON(step_norm_sq)) THEN
               supported_step(:) = step_eigenvectors(:, active_modes)
               sample_coeff(:) = MATMUL(TRANSPOSE(projected_steps), supported_step)
               supported_target(:) = MATMUL(residual_targets, sample_coeff)/step_norm_sq
               mode_curvature = DOT_PRODUCT(supported_step, supported_target)
               DO j = 1, active_modes
                  DO i = 1, active_modes
                     reduced_correction(i, j) = &
                        mode_curvature*supported_step(i)*supported_step(j)
                  END DO
               END DO
               reduced_response(:, :) = reduced_prior + reduced_correction
               correction_norm = ABS(mode_curvature)
               fit_ready = mode_curvature == mode_curvature .AND. &
                           ALL(reduced_correction == reduced_correction)
               rank_one_fit = fit_ready
               independence = step_norm_sq/ &
                              MAX(SUM(MAX(0.0_dp, step_eigenvalues)), EPSILON(1.0_dp))
            END IF
            DEALLOCATE (sample_coeff, step_eigenvalues, step_eigenvectors, supported_step, &
                        supported_target)
         END IF
      END IF
      IF (.NOT. fit_ready) THEN
         unsupported_modes = nmode
         DEALLOCATE (basis, eigenvalues, mode, projected_residual, projected_steps, &
                     projected_targets, reduced_baseline, reduced_correction, reduced_eigenvectors, &
                     reduced_output_correction, reduced_prior, reduced_response, residual_targets, &
                     response_modes, selected_steps, selected_targets)
         RETURN
      END IF

      projected_residual(:, :) = projected_targets - &
                                 MATMUL(reduced_response, projected_steps)
      projected_target_norm = SQRT(MAX(0.0_dp, SUM(projected_targets**2)))
      pair_residual_ratio = SQRT(MAX(0.0_dp, SUM(projected_residual**2)))/ &
                            MAX(projected_target_norm, EPSILON(1.0_dp))
      fullrank_residual_ratio = pair_residual_ratio
      pair_fit_residual_ratio = pair_residual_ratio
      fullrank_fit_ready = .FALSE.
      IF (.NOT. rank_one_fit .AND. active_modes > 1 .AND. nsample >= active_modes) THEN
         ALLOCATE (fullrank_correction(active_modes, active_modes), &
                   fullrank_eigenvalues(active_modes), &
                   fullrank_eigenvectors(active_modes, active_modes), &
                   fullrank_inner(active_modes, active_modes), &
                   fullrank_residual(active_modes, nsample), &
                   fullrank_rhs(active_modes, active_modes), &
                   normalized_steps(active_modes, nsample), &
                   normalized_targets(active_modes, nsample))
         normalized_steps(:, :) = 0.0_dp
         normalized_targets(:, :) = 0.0_dp
         fullrank_samples = 0
         DO isample = 1, nsample
            step_norm_sq = DOT_PRODUCT(projected_steps(:, isample), &
                                       projected_steps(:, isample))
            IF (step_norm_sq <= TINY(1.0_dp)) CYCLE
            response_scale = SQRT(step_norm_sq)
            normalized_steps(:, isample) = projected_steps(:, isample)/response_scale
            normalized_targets(:, isample) = projected_targets(:, isample)/response_scale
            fullrank_samples = fullrank_samples + 1
         END DO
         fullrank_eigenvectors(:, :) = &
            MATMUL(normalized_steps, TRANSPOSE(normalized_steps))
         CALL diamat_all(fullrank_eigenvectors, fullrank_eigenvalues)
         response_scale = MAXVAL(ABS(fullrank_eigenvalues))
         fullrank_fit_ready = fullrank_samples >= active_modes .AND. &
                              fullrank_eigenvalues(1) > &
                              128.0_dp*SQRT(EPSILON(1.0_dp))* &
                              MAX(response_scale, TINY(1.0_dp))
         IF (fullrank_fit_ready) THEN
            fullrank_residual(:, :) = normalized_targets - &
                                      MATMUL(reduced_prior, normalized_steps)
            fullrank_rhs(:, :) = &
               MATMUL(fullrank_residual, TRANSPOSE(normalized_steps)) + &
               MATMUL(normalized_steps, TRANSPOSE(fullrank_residual))
            fullrank_inner(:, :) = &
               MATMUL(TRANSPOSE(fullrank_eigenvectors), &
                      MATMUL(fullrank_rhs, fullrank_eigenvectors))
            DO j = 1, active_modes
               DO i = 1, active_modes
                  fullrank_inner(i, j) = fullrank_inner(i, j)/ &
                                         (fullrank_eigenvalues(i) + fullrank_eigenvalues(j))
               END DO
            END DO
            fullrank_correction(:, :) = &
               MATMUL(fullrank_eigenvectors, &
                      MATMUL(fullrank_inner, TRANSPOSE(fullrank_eigenvectors)))
            fullrank_correction(:, :) = 0.5_dp* &
                                        (fullrank_correction + TRANSPOSE(fullrank_correction))
            normalized_target_norm = SQRT(MAX(0.0_dp, SUM(normalized_targets**2)))
            residual_norm = SUM((normalized_targets - &
                                 MATMUL(reduced_response, normalized_steps))**2)
            updated_residual_norm = SUM((normalized_targets - &
                                         MATMUL(reduced_prior + fullrank_correction, &
                                                normalized_steps))**2)
            pair_fit_residual_ratio = SQRT(MAX(0.0_dp, residual_norm))/ &
                                      MAX(normalized_target_norm, EPSILON(1.0_dp))
            fullrank_fit_ready = ALL(fullrank_correction == fullrank_correction) .AND. &
                                 updated_residual_norm <= residual_norm + &
                                 128.0_dp*EPSILON(MAX(1.0_dp, residual_norm))
            IF (fullrank_fit_ready) &
               fullrank_residual_ratio = SQRT(MAX(0.0_dp, updated_residual_norm))/ &
                                         MAX(normalized_target_norm, EPSILON(1.0_dp))
            IF (fullrank_fit_ready .AND. PRESENT(fullrank_response_correction)) THEN
               fullrank_rhs(:, :) = reduced_prior + fullrank_correction - reduced_baseline
               fullrank_response_correction(:, :) = &
                  MATMUL(basis(:, 1:active_modes), &
                         MATMUL(fullrank_rhs, TRANSPOSE(basis(:, 1:active_modes))))
               fullrank_response_correction(:, :) = 0.5_dp* &
                                                    (fullrank_response_correction + &
                                                     TRANSPOSE(fullrank_response_correction))
            END IF
         END IF
         DEALLOCATE (fullrank_correction, fullrank_eigenvalues, fullrank_eigenvectors, &
                     fullrank_inner, fullrank_residual, fullrank_rhs, normalized_steps, &
                     normalized_targets)
      END IF
      residual_ratio = pair_residual_ratio
      IF (PRESENT(fitted_residual_ratio)) fitted_residual_ratio = fullrank_residual_ratio
      IF (PRESENT(pair_fitted_residual_ratio)) &
         pair_fitted_residual_ratio = pair_fit_residual_ratio
      IF (rank_one_fit) compatibility_norm = residual_ratio

      reduced_output_correction(:, :) = reduced_response - reduced_baseline
      reduced_output_correction(:, :) = 0.5_dp* &
                                        (reduced_output_correction + &
                                         TRANSPOSE(reduced_output_correction))
      reduced_eigenvectors(:, :) = reduced_output_correction(:, :)
      CALL diamat_all(reduced_eigenvectors, eigenvalues)
      response_modes(:, :) = MATMUL(basis(:, 1:active_modes), reduced_eigenvectors)
      response_scale = MAXVAL(ABS(eigenvalues))
      curvature_floor = 128.0_dp*EPSILON(1.0_dp)*MAX(response_scale, TINY(1.0_dp))
      DO imode = 1, active_modes
         mode_curvature = eigenvalues(imode)
         IF (ABS(mode_curvature) <= curvature_floor) THEN
            unsupported_modes = unsupported_modes + 1
            CYCLE
         END IF
         DO j = 1, nrot
            DO i = 1, nrot
               response_correction(i, j) = response_correction(i, j) + &
                                           mode_curvature*response_modes(i, imode)* &
                                           response_modes(j, imode)
            END DO
         END DO
         IF (mode_curvature > 0.0_dp) THEN
            positive_modes = positive_modes + 1
         ELSE
            negative_modes = negative_modes + 1
         END IF
      END DO
      ready = positive_modes + negative_modes > 0 .AND. &
              ALL(response_correction == response_correction)
      IF (.NOT. ready) response_correction(:, :) = 0.0_dp

      DEALLOCATE (basis, eigenvalues, mode, projected_residual, projected_steps, &
                  projected_targets, reduced_baseline, reduced_correction, reduced_eigenvectors, &
                  reduced_output_correction, reduced_prior, reduced_response, residual_targets, &
                  response_modes, selected_steps, selected_targets)

   END SUBROUTINE qs_scf_kp_validated_density_response

! **************************************************************************************************
!> \brief Prefer a coupled closure response only when it improves on a physical baseline.
!>
!>        Before the reduced response fit is available, the identity baseline has normalized
!>        residual one.  A fitted response whose validation or pair residual exceeds that value
!>        is worse than applying no closure correction and must remain a shadow model.  Once a
!>        reduced baseline is available, the coupled pair fit must improve on both it and the
!>        identity baseline.
!> \param candidate_ready whether the coupled physical-subspace fit is available
!> \param baseline_ready whether a reduced closure-response fit is available
!> \param candidate_residual normalized validation residual of the coupled response
!> \param candidate_pair_residual normalized active-pair fit residual of the coupled response
!> \param baseline_pair_residual normalized active-pair fit residual of the reduced response
!> \return whether the coupled response may replace the reduced response
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_closure_response_preferred( &
      candidate_ready, baseline_ready, candidate_residual, candidate_pair_residual, &
      baseline_pair_residual) RESULT(preferred)
      LOGICAL, INTENT(IN)                                :: candidate_ready, baseline_ready
      REAL(KIND=dp), INTENT(IN)                          :: candidate_residual, &
                                                            candidate_pair_residual, &
                                                            baseline_pair_residual
      LOGICAL                                            :: preferred

      REAL(KIND=dp)                                      :: comparison_residual, tolerance

      preferred = .FALSE.
      IF (.NOT. candidate_ready) RETURN
      IF (candidate_residual /= candidate_residual .OR. &
          candidate_pair_residual /= candidate_pair_residual .OR. &
          candidate_residual < 0.0_dp .OR. candidate_pair_residual < 0.0_dp) RETURN

      comparison_residual = 1.0_dp
      IF (baseline_ready) THEN
         IF (baseline_pair_residual /= baseline_pair_residual .OR. &
             baseline_pair_residual < 0.0_dp) RETURN
         comparison_residual = MIN(comparison_residual, baseline_pair_residual)
      END IF
      tolerance = 64.0_dp*EPSILON(MAX(1.0_dp, comparison_residual))
      preferred = candidate_residual < 1.0_dp - tolerance .AND. &
                  candidate_pair_residual < comparison_residual - tolerance

   END FUNCTION qs_scf_kp_closure_response_preferred

! **************************************************************************************************
!> \brief Promote a closure-response shadow only after repeated accepted Mermin improvement.
!> \param samples number of closed-endpoint shadow comparisons
!> \param advantage_ema EMA of baseline error minus shadow error for accepted Mermin decrease
!> \return whether the shadow history supports active use of the response
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_closure_response_history_ready(samples, advantage_ema) RESULT(ready)
      INTEGER, INTENT(IN)                                :: samples
      REAL(KIND=dp), INTENT(IN)                          :: advantage_ema
      LOGICAL                                            :: ready

      ready = samples >= ot_kp_schur_calibration_min_samples .AND. &
              advantage_ema == advantage_ema .AND. &
              advantage_ema > 64.0_dp*EPSILON(1.0_dp)

   END FUNCTION qs_scf_kp_closure_response_history_ready

! **************************************************************************************************
!> \brief Compare a signed shadow-model prediction with an accepted Mermin decrease.
!>
!>        A nonpositive candidate prediction is a resolved model failure, not a missing sample.
!>        Recording it with zero quality prevents an over-curved response mode from being promoted
!>        merely because the positive-prediction subset happened to agree with line search.
!> \param baseline_drop predicted decrease without the shadow response
!> \param candidate_drop signed predicted decrease with the shadow response
!> \param measured_drop accepted line-search decrease
!> \param quality measured/candidate ratio, or zero for a nonpositive candidate
!> \param baseline_error symmetric relative baseline error
!> \param candidate_error symmetric relative shadow-candidate error
!> \param advantage baseline_error-candidate_error
!> \param ready whether the comparison is finite and has a positive baseline and measurement
! **************************************************************************************************
   PURE SUBROUTINE qs_scf_kp_shadow_prediction_quality( &
      baseline_drop, candidate_drop, measured_drop, quality, baseline_error, candidate_error, &
      advantage, ready)
      REAL(KIND=dp), INTENT(IN)                          :: baseline_drop, candidate_drop, &
                                                            measured_drop
      REAL(KIND=dp), INTENT(OUT)                         :: quality, baseline_error, &
                                                            candidate_error, advantage
      LOGICAL, INTENT(OUT)                               :: ready

      REAL(KIND=dp)                                      :: correction, resolution, scale

      quality = 0.0_dp
      baseline_error = 1.0_dp
      candidate_error = 1.0_dp
      advantage = 0.0_dp
      ready = .FALSE.
      IF (.NOT. (baseline_drop == baseline_drop .AND. candidate_drop == candidate_drop .AND. &
                 measured_drop == measured_drop)) RETURN
      IF (ABS(baseline_drop) >= HUGE(baseline_drop) .OR. &
          ABS(candidate_drop) >= HUGE(candidate_drop) .OR. &
          ABS(measured_drop) >= HUGE(measured_drop)) RETURN
      IF (baseline_drop <= EPSILON(baseline_drop) .OR. measured_drop <= 0.0_dp) RETURN

      scale = MAX(measured_drop, ABS(baseline_drop), ABS(candidate_drop), TINY(1.0_dp))
      baseline_error = ABS(measured_drop - baseline_drop)/scale
      candidate_error = ABS(measured_drop - candidate_drop)/scale
      IF (candidate_drop > EPSILON(candidate_drop)) quality = measured_drop/candidate_drop
      advantage = baseline_error - candidate_error
      correction = ABS(candidate_drop - baseline_drop)
      resolution = 64.0_dp*EPSILON(1.0_dp)*MAX(scale, 1.0_dp)
      ready = quality == quality .AND. baseline_error == baseline_error .AND. &
              candidate_error == candidate_error .AND. advantage == advantage .AND. &
              ABS(quality) < HUGE(quality) .AND. ABS(advantage) < HUGE(advantage) .AND. &
              correction > resolution

   END SUBROUTINE qs_scf_kp_shadow_prediction_quality

! **************************************************************************************************
!> \brief Project a finite gradient secant onto its accepted Mermin-energy work.
!>
!>        This least-norm longitudinal update makes the response work agree exactly with the
!>        finite accepted Mermin-energy curvature.  It preserves all response components
!>        orthogonal to the joint complex-rotation/fixed-N auxiliary-energy step.
!> \param rotation_step accepted complex-rotation step
!> \param energy_step accepted fixed-N auxiliary-energy step
!> \param rotation_response total rotation-gradient secant, updated in place
!> \param energy_response total auxiliary-energy-gradient secant, updated in place
!> \param work_ratio finite-energy curvature divided by endpoint-gradient curvature
!> \param applied whether a numerically resolved longitudinal correction was applied
!> \param work_before response work before projection
!> \param work_after response work after projection
! **************************************************************************************************
   PURE SUBROUTINE qs_scf_kp_work_consistent_response( &
      rotation_step, energy_step, rotation_response, energy_response, work_ratio, applied, &
      work_before, work_after)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: rotation_step, energy_step
      REAL(KIND=dp), DIMENSION(:), INTENT(INOUT)         :: rotation_response, energy_response
      REAL(KIND=dp), INTENT(IN)                          :: work_ratio
      LOGICAL, INTENT(OUT)                               :: applied
      REAL(KIND=dp), INTENT(OUT)                         :: work_before, work_after

      REAL(KIND=dp)                                      :: correction, longitudinal_scale, &
                                                            resolution, step_norm_sq

      applied = .FALSE.
      work_before = 0.0_dp
      work_after = 0.0_dp
      IF (SIZE(rotation_step) /= SIZE(rotation_response) .OR. &
          SIZE(energy_step) /= SIZE(energy_response)) RETURN
      work_before = DOT_PRODUCT(rotation_step, rotation_response) + &
                    DOT_PRODUCT(energy_step, energy_response)
      work_after = work_before
      IF (.NOT. (work_ratio == work_ratio) .OR. work_ratio <= 0.0_dp .OR. &
          ABS(work_ratio) >= HUGE(work_ratio)) RETURN
      step_norm_sq = DOT_PRODUCT(rotation_step, rotation_step) + &
                     DOT_PRODUCT(energy_step, energy_step)
      IF (step_norm_sq <= EPSILON(1.0_dp)) RETURN
      correction = (work_ratio - 1.0_dp)*work_before
      resolution = 64.0_dp*EPSILON(1.0_dp)*MAX(ABS(work_before), 1.0_dp)
      IF (ABS(correction) <= resolution) RETURN
      longitudinal_scale = correction/step_norm_sq
      rotation_response(:) = rotation_response + longitudinal_scale*rotation_step
      energy_response(:) = energy_response + longitudinal_scale*energy_step
      work_after = DOT_PRODUCT(rotation_step, rotation_response) + &
                   DOT_PRODUCT(energy_step, energy_response)
      applied = ALL(rotation_response == rotation_response) .AND. &
                ALL(energy_response == energy_response) .AND. work_after == work_after

   END SUBROUTINE qs_scf_kp_work_consistent_response

! **************************************************************************************************
!> \brief Express reduced-baseline and coupled-candidate curvatures relative to the active model.
!> \param baseline_quadratic reduced-response curvature on the accepted step
!> \param candidate_quadratic coupled-response curvature on the accepted step
!> \param closure_candidate_active whether the accepted model contains a closure response
!> \param coupled_response_active whether that active closure response is the coupled response
!> \param baseline_adjustment curvature taking the active model to the reduced baseline
!> \param candidate_adjustment curvature taking the active model to the coupled candidate
! **************************************************************************************************
   PURE SUBROUTINE qs_scf_kp_closure_response_model_adjustments( &
      baseline_quadratic, candidate_quadratic, closure_candidate_active, &
      coupled_response_active, baseline_adjustment, candidate_adjustment)
      REAL(KIND=dp), INTENT(IN)                          :: baseline_quadratic, candidate_quadratic
      LOGICAL, INTENT(IN)                                :: closure_candidate_active, &
                                                            coupled_response_active
      REAL(KIND=dp), INTENT(OUT)                         :: baseline_adjustment, candidate_adjustment

      baseline_adjustment = baseline_quadratic
      candidate_adjustment = candidate_quadratic
      IF (closure_candidate_active) THEN
         IF (coupled_response_active) THEN
            baseline_adjustment = baseline_quadratic - candidate_quadratic
            candidate_adjustment = 0.0_dp
         ELSE
            baseline_adjustment = 0.0_dp
            candidate_adjustment = candidate_quadratic - baseline_quadratic
         END IF
      END IF

   END SUBROUTINE qs_scf_kp_closure_response_model_adjustments

! **************************************************************************************************
!> \brief Express a full-space closure candidate relative to the accepted active model.
!> \param active_quadratic active closure-response curvature on the accepted step
!> \param candidate_quadratic full-space candidate curvature on the accepted step
!> \param closure_candidate_active whether the accepted model contains the active response
!> \param baseline_adjustment curvature adjustment for the accepted baseline
!> \param candidate_adjustment curvature taking the accepted model to the full candidate
! **************************************************************************************************
   PURE SUBROUTINE qs_scf_kp_full_closure_response_model_adjustments( &
      active_quadratic, candidate_quadratic, closure_candidate_active, &
      baseline_adjustment, candidate_adjustment)
      REAL(KIND=dp), INTENT(IN)                          :: active_quadratic, candidate_quadratic
      LOGICAL, INTENT(IN)                                :: closure_candidate_active
      REAL(KIND=dp), INTENT(OUT)                         :: baseline_adjustment, candidate_adjustment

      baseline_adjustment = 0.0_dp
      candidate_adjustment = candidate_quadratic
      IF (closure_candidate_active) candidate_adjustment = candidate_quadratic - active_quadratic

   END SUBROUTINE qs_scf_kp_full_closure_response_model_adjustments

! **************************************************************************************************
!> \brief Evaluate a coupled response correction on one rotation/auxiliary-energy step.
!> \param rotation_step complex-rotation coordinates
!> \param energy_step fixed-N auxiliary-energy coordinates
!> \param rotation_response correction to H_RR
!> \param energy_response correction to H_ee
!> \param cross_response correction to B in [H_RR,-B^T;-B,H_ee]
!> \param rotation_quadratic optional rotation-block contribution
!> \param energy_quadratic optional auxiliary-energy-block contribution
!> \param cross_quadratic optional signed cross-block contribution
!> \return full response quadratic on the supplied step
! **************************************************************************************************
   FUNCTION qs_scf_kp_coupled_response_quadratic( &
      rotation_step, energy_step, rotation_response, energy_response, cross_response, &
      rotation_quadratic, energy_quadratic, cross_quadratic) &
      RESULT(quadratic)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: rotation_step, energy_step
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: rotation_response, energy_response, &
                                                            cross_response
      REAL(KIND=dp), INTENT(OUT), OPTIONAL               :: rotation_quadratic, energy_quadratic, &
                                                            cross_quadratic
      REAL(KIND=dp)                                      :: quadratic

      INTEGER                                            :: nener, nrot
      REAL(KIND=dp)                                      :: cross_part, energy_part, rotation_part

      nrot = SIZE(rotation_step)
      nener = SIZE(energy_step)
      CPASSERT(ALL(SHAPE(rotation_response) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(energy_response) == [nener, nener]))
      CPASSERT(ALL(SHAPE(cross_response) == [nener, nrot]))

      rotation_part = DOT_PRODUCT(rotation_step, MATMUL(rotation_response, rotation_step))
      energy_part = DOT_PRODUCT(energy_step, MATMUL(energy_response, energy_step))
      cross_part = -2.0_dp*DOT_PRODUCT(energy_step, MATMUL(cross_response, rotation_step))
      quadratic = rotation_part + energy_part + cross_part
      IF (PRESENT(rotation_quadratic)) rotation_quadratic = rotation_part
      IF (PRESENT(energy_quadratic)) energy_quadratic = energy_part
      IF (PRESENT(cross_quadratic)) cross_quadratic = cross_part

   END FUNCTION qs_scf_kp_coupled_response_quadratic

! **************************************************************************************************
!> \brief Apply channel-resolved canonical-density Newton modes to a coupled rotation candidate.
!>
!>        Regular Newton modes are additive corrections selected in the final coupled Mermin
!>        model.  A channel whose density Hessian is uphill instead supplies a complete
!>        trust-region Cauchy replacement.
!> \param base_rot coupled rotation candidate
!> \param tangent_modes channel-resolved canonical-density Newton modes
!> \param mode_alpha accepted coefficient of every Newton mode
!> \param density_tangent complete channel tangent, including Cauchy replacements
!> \param cauchy_channel nonzero for channels using a complete Cauchy replacement
!> \param var_channel channel identity of every rotation coordinate
!> \param candidate_rot resulting density-aware rotation candidate
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_canonical_density_candidate( &
      base_rot, tangent_modes, mode_alpha, density_tangent, cauchy_channel, var_channel, candidate_rot)

      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: base_rot
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: tangent_modes
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: mode_alpha, density_tangent
      INTEGER, DIMENSION(:), INTENT(IN)                  :: cauchy_channel, var_channel
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: candidate_rot

      INTEGER                                            :: r

      CPASSERT(SIZE(candidate_rot) == SIZE(base_rot))
      CPASSERT(SIZE(density_tangent) == SIZE(base_rot))
      CPASSERT(SIZE(var_channel) == SIZE(base_rot))
      CPASSERT(SIZE(tangent_modes, 1) == SIZE(base_rot))
      CPASSERT(SIZE(tangent_modes, 2) == SIZE(mode_alpha))

      candidate_rot(:) = base_rot(:) + MATMUL(tangent_modes, mode_alpha)
      DO r = 1, SIZE(candidate_rot)
         CPASSERT(var_channel(r) >= 1 .AND. var_channel(r) <= SIZE(cauchy_channel))
         IF (cauchy_channel(var_channel(r)) > 0) candidate_rot(r) = density_tangent(r)
      END DO

   END SUBROUTINE qs_scf_kp_canonical_density_candidate

! **************************************************************************************************
!> \brief Couple a density-corrected rotation to its enriched auxiliary-energy response.
!>
!>        The response correction changes only the auxiliary-energy block.  The rotation block,
!>        its gradient contraction, and its norm must remain those of the density-corrected base
!>        candidate used to construct base_response.
!> \param base_sol density-corrected rotation candidate
!> \param base_response auxiliary-energy response of base_sol
!> \param response_correction projected full-density response correction
!> \param base_gdot_rotation rotation-gradient contraction of base_sol
!> \param base_norm_rotation rotation norm of base_sol
!> \param candidate_sol coupled density-descent rotation
!> \param candidate_response coupled density-descent auxiliary-energy response
!> \param candidate_gdot_rotation coupled rotation-gradient contraction
!> \param candidate_norm_rotation coupled rotation norm
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_density_descent_candidate( &
      base_sol, base_response, response_correction, base_gdot_rotation, base_norm_rotation, &
      candidate_sol, candidate_response, candidate_gdot_rotation, candidate_norm_rotation)

      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: base_sol, base_response, &
                                                            response_correction
      REAL(KIND=dp), INTENT(IN)                          :: base_gdot_rotation, base_norm_rotation
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: candidate_sol, candidate_response
      REAL(KIND=dp), INTENT(OUT)                         :: candidate_gdot_rotation, &
                                                            candidate_norm_rotation

      CPASSERT(SIZE(candidate_sol) == SIZE(base_sol))
      CPASSERT(SIZE(candidate_response) == SIZE(base_response))
      CPASSERT(SIZE(response_correction) == SIZE(base_response))

      candidate_sol(:) = base_sol(:)
      candidate_response(:) = base_response(:) + response_correction(:)
      candidate_gdot_rotation = base_gdot_rotation
      candidate_norm_rotation = base_norm_rotation

   END SUBROUTINE qs_scf_kp_density_descent_candidate

!> \brief Uncalibrated Mermin drop used for one canonical-density tail probe.
!>
!>        A density-aware candidate must first be accepted or rejected by the real line search
!>        before it owns useful history.  Admit that first probe only when the final coupled
!>        model predicts a positive density-mode gain, the independent density stationarity
!>        condition is still open, and both response norms are inside their trust regions.
!> \param model_drop predicted total Mermin decrease of the density-aware candidate
!> \param tangent_gain predicted incremental decrease from canonical-density Newton modes
!> \param density_delta independent canonical-density stationarity residual
!> \param eps_scf requested SCF convergence threshold
!> \param weighted_trust_ratio curvature-weighted response trust ratio
!> \param abs_trust_ratio maximum-component response trust ratio
!> \return uncalibrated drop admitted for a physical tail probe
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_canonical_density_probe_drop( &
      model_drop, tangent_gain, density_delta, eps_scf, weighted_trust_ratio, abs_trust_ratio) &
      RESULT(probe_drop)

      REAL(KIND=dp), INTENT(IN)                          :: model_drop, tangent_gain, density_delta, &
                                                            eps_scf, weighted_trust_ratio, &
                                                            abs_trust_ratio
      REAL(KIND=dp)                                      :: probe_drop

      probe_drop = 0.0_dp
      IF (eps_scf <= 0.0_dp .OR. density_delta <= eps_scf) RETURN
      IF (model_drop <= ot_kp_schur_projector_density_full_min_drop) RETURN
      IF (tangent_gain <= EPSILON(MAX(1.0_dp, ABS(tangent_gain)))) RETURN
      IF (weighted_trust_ratio < 0.0_dp .OR. weighted_trust_ratio > 1.0_dp) RETURN
      IF (abs_trust_ratio < 0.0_dp .OR. abs_trust_ratio > 1.0_dp) RETURN

      probe_drop = model_drop

   END FUNCTION qs_scf_kp_canonical_density_probe_drop

! **************************************************************************************************
!> \brief Fractional reduction of the exact fixed-N canonical density residual.
!> \param model_delta residual at the accepted line-search model point
!> \param current_delta residual after the accepted line-search step
!> \return bounded signed reduction fraction
! **************************************************************************************************
   FUNCTION qs_scf_kp_density_stationarity_quality(model_delta, current_delta) RESULT(quality)
      REAL(KIND=dp), INTENT(IN)                          :: model_delta, current_delta
      REAL(KIND=dp)                                      :: quality

      quality = 0.0_dp
      IF (model_delta <= EPSILON(model_delta) .OR. current_delta < 0.0_dp) RETURN
      quality = (model_delta - current_delta)/model_delta
      quality = MAX(-1.0_dp, MIN(1.0_dp, quality))

   END FUNCTION qs_scf_kp_density_stationarity_quality

! **************************************************************************************************
!> \brief Contract the FULL_ALL complement metric with finite complex occupation-matrix responses.
!> \param response_metric reduced R^H P_j R metric for every output orbital j
!> \param occupation_response d(U F U^H)/dx_r for every real rotation variable r
!> \param correction positive orbital-complement Schur correction B^T P B
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_orbital_schur_correction(response_metric, occupation_response, correction)

      COMPLEX(KIND=dp), DIMENSION(:, :, :), INTENT(IN)   :: response_metric, occupation_response
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: correction

      COMPLEX(KIND=dp), ALLOCATABLE, DIMENSION(:, :)     :: metric_response
      INTEGER                                            :: imo, nmo, nrot

      nmo = SIZE(response_metric, 1)
      nrot = SIZE(occupation_response, 3)
      CPASSERT(SIZE(response_metric, 2) == nmo)
      CPASSERT(SIZE(response_metric, 3) == nmo)
      CPASSERT(SIZE(occupation_response, 1) == nmo)
      CPASSERT(SIZE(occupation_response, 2) == nmo)
      CPASSERT(SIZE(correction, 1) == nrot)
      CPASSERT(SIZE(correction, 2) == nrot)

      correction(:, :) = 0.0_dp
      ALLOCATE (metric_response(nmo, nrot))
      DO imo = 1, nmo
         metric_response(:, :) = MATMUL(response_metric(:, :, imo), &
                                        occupation_response(:, imo, :))
         correction(:, :) = correction(:, :) + &
                            REAL(MATMUL(CONJG(TRANSPOSE(occupation_response(:, imo, :))), metric_response), KIND=dp)
      END DO
      correction(:, :) = 0.5_dp*(correction(:, :) + TRANSPOSE(correction(:, :)))
      DEALLOCATE (metric_response)

   END SUBROUTINE qs_scf_kp_orbital_schur_correction

! **************************************************************************************************
!> \brief Apply the finite coupled rotation/energy Hessian to a secant step.
!> \param rotation_hessian finite complex rotation block
!> \param energy_hessian dense fixed-N auxiliary-energy block
!> \param energy_cross signed Schur cross block C for [H_RR,-C^T;-C,H_ee]
!> \param step_rotation independent complex rotation coordinates
!> \param step_energy fixed-N auxiliary-energy coordinates
!> \param model_rotation predicted rotation-gradient difference
!> \param model_energy predicted auxiliary-energy-gradient difference
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_coupled_secant_model(rotation_hessian, energy_hessian, energy_cross, &
                                             step_rotation, step_energy, model_rotation, model_energy)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: rotation_hessian, energy_hessian, &
                                                            energy_cross
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: step_rotation, step_energy
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: model_rotation, model_energy

      CPASSERT(SIZE(rotation_hessian, 1) == SIZE(step_rotation))
      CPASSERT(SIZE(rotation_hessian, 2) == SIZE(step_rotation))
      CPASSERT(SIZE(energy_hessian, 1) == SIZE(step_energy))
      CPASSERT(SIZE(energy_hessian, 2) == SIZE(step_energy))
      CPASSERT(SIZE(energy_cross, 1) == SIZE(step_energy))
      CPASSERT(SIZE(energy_cross, 2) == SIZE(step_rotation))
      CPASSERT(SIZE(model_rotation) == SIZE(step_rotation))
      CPASSERT(SIZE(model_energy) == SIZE(step_energy))

      model_rotation(:) = MATMUL(rotation_hessian, step_rotation) - &
                          MATMUL(TRANSPOSE(energy_cross), step_energy)
      model_energy(:) = MATMUL(energy_hessian, step_energy) - &
                        MATMUL(energy_cross, step_rotation)

   END SUBROUTINE qs_scf_kp_coupled_secant_model

! **************************************************************************************************
!> \brief Apply a symmetric least-change update that satisfies one vector secant.
!> \param hessian symmetric reference Hessian
!> \param step accepted step s
!> \param secant_target measured gradient difference y
!> \param weight fraction of the exact secant update in [0,1]
!> \param updated_hessian symmetric updated Hessian
!> \param ready whether the update was finite and well defined
!> \param correction_norm Frobenius norm of the applied correction
!> \param residual_norm norm of y-Hs before the update
!> \param updated_residual_norm norm of y-H_new*s after the update
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_symmetric_secant_update(hessian, step, secant_target, weight, &
                                                updated_hessian, ready, correction_norm, &
                                                residual_norm, updated_residual_norm)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: hessian
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: step, secant_target
      REAL(KIND=dp), INTENT(IN)                          :: weight
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: updated_hessian
      LOGICAL, INTENT(OUT)                               :: ready
      REAL(KIND=dp), INTENT(OUT)                         :: correction_norm, residual_norm, &
                                                            updated_residual_norm

      INTEGER                                            :: i, j, n
      REAL(KIND=dp)                                      :: residual_dot_step, step_norm_sq, &
                                                            update_weight
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: residual, updated_residual

      n = SIZE(step)
      CPASSERT(ALL(SHAPE(hessian) == [n, n]))
      CPASSERT(SIZE(secant_target) == n)
      CPASSERT(ALL(SHAPE(updated_hessian) == [n, n]))

      updated_hessian(:, :) = hessian(:, :)
      ready = .FALSE.
      correction_norm = 0.0_dp
      residual_norm = 0.0_dp
      updated_residual_norm = 0.0_dp
      IF (n <= 0) RETURN

      step_norm_sq = DOT_PRODUCT(step, step)
      IF (step_norm_sq <= EPSILON(1.0_dp)) RETURN
      update_weight = MIN(1.0_dp, MAX(0.0_dp, weight))
      IF (update_weight <= EPSILON(1.0_dp)) RETURN

      ALLOCATE (residual(n), updated_residual(n))
      residual(:) = secant_target(:) - MATMUL(hessian, step)
      residual_dot_step = DOT_PRODUCT(residual, step)
      DO j = 1, n
         DO i = 1, n
            updated_hessian(i, j) = updated_hessian(i, j) + update_weight* &
                                    ((residual(i)*step(j) + step(i)*residual(j))/step_norm_sq - &
                                     residual_dot_step*step(i)*step(j)/(step_norm_sq*step_norm_sq))
         END DO
      END DO
      residual_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(residual, residual)))
      correction_norm = SQRT(MAX(0.0_dp, SUM((updated_hessian - hessian)**2)))
      updated_residual(:) = secant_target(:) - MATMUL(updated_hessian, step)
      updated_residual_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(updated_residual, updated_residual)))
      ready = correction_norm == correction_norm .AND. updated_residual_norm == updated_residual_norm
      IF (.NOT. ready) updated_hessian(:, :) = hessian(:, :)
      DEALLOCATE (residual, updated_residual)

   END SUBROUTINE qs_scf_kp_symmetric_secant_update

! **************************************************************************************************
!> \brief Add the missing positive curvature measured along one accepted direction.
!>
!>        The rank-one correction is positive semidefinite and changes no curvature orthogonal
!>        to the accepted step.  It is therefore suitable for completing a reduced fixed-N Schur
!>        response without fitting unresolved orthogonal components of the gradient secant.
!> \param hessian symmetric reference Hessian
!> \param step accepted step s
!> \param measured_curvature measured s^T y curvature
!> \param updated_hessian curvature-completed Hessian
!> \param ready whether a finite positive correction was applied
!> \param model_curvature original s^T H s curvature
!> \param correction_curvature applied directional curvature
!> \param correction_norm Frobenius norm of the rank-one correction
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_directional_curvature_update(hessian, step, measured_curvature, &
                                                     updated_hessian, ready, model_curvature, &
                                                     correction_curvature, correction_norm)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: hessian
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: step
      REAL(KIND=dp), INTENT(IN)                          :: measured_curvature
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: updated_hessian
      LOGICAL, INTENT(OUT)                               :: ready
      REAL(KIND=dp), INTENT(OUT)                         :: model_curvature, correction_curvature, &
                                                            correction_norm

      INTEGER                                            :: i, j, n
      REAL(KIND=dp)                                      :: coefficient, curvature_scale, &
                                                            step_norm_sq

      n = SIZE(step)
      CPASSERT(ALL(SHAPE(hessian) == [n, n]))
      CPASSERT(ALL(SHAPE(updated_hessian) == [n, n]))

      updated_hessian(:, :) = hessian(:, :)
      ready = .FALSE.
      model_curvature = 0.0_dp
      correction_curvature = 0.0_dp
      correction_norm = 0.0_dp
      IF (n <= 0) RETURN

      step_norm_sq = DOT_PRODUCT(step, step)
      IF (step_norm_sq <= SQRT(TINY(1.0_dp))) RETURN
      model_curvature = DOT_PRODUCT(step, MATMUL(hessian, step))
      IF (model_curvature /= model_curvature .OR. measured_curvature /= measured_curvature) RETURN
      IF (ABS(model_curvature) >= HUGE(1.0_dp) .OR. ABS(measured_curvature) >= HUGE(1.0_dp)) RETURN

      correction_curvature = measured_curvature - model_curvature
      curvature_scale = MAX(ABS(measured_curvature), ABS(model_curvature), TINY(1.0_dp))
      IF (measured_curvature <= 0.0_dp .OR. &
          correction_curvature <= 64.0_dp*EPSILON(1.0_dp)*curvature_scale) THEN
         correction_curvature = 0.0_dp
         RETURN
      END IF

      coefficient = correction_curvature/(step_norm_sq*step_norm_sq)
      DO j = 1, n
         DO i = 1, n
            updated_hessian(i, j) = updated_hessian(i, j) + &
                                    coefficient*step(i)*step(j)
         END DO
      END DO
      correction_norm = correction_curvature/step_norm_sq
      ready = ALL(updated_hessian == updated_hessian) .AND. &
              ALL(ABS(updated_hessian) < HUGE(1.0_dp)) .AND. &
              correction_norm < HUGE(1.0_dp)
      IF (.NOT. ready) THEN
         updated_hessian(:, :) = hessian(:, :)
         correction_curvature = 0.0_dp
         correction_norm = 0.0_dp
      END IF

   END SUBROUTINE qs_scf_kp_directional_curvature_update

! **************************************************************************************************
!> \brief Complete missing positive curvature in an orthonormal accepted-secant subspace.
!>
!>        Steps and their measured Hessian responses are transformed together by modified
!>        Gram-Schmidt.  Positive rank-one corrections in the resulting orthonormal basis are
!>        mutually independent, preserve earlier modal curvatures, and leave the orthogonal
!>        complement unchanged.
!> \param hessian symmetric reference Hessian
!> \param steps accepted steps, newest first
!> \param secant_targets measured Hessian responses for steps
!> \param updated_hessian PSD-completed Hessian
!> \param ready whether a finite positive correction was applied
!> \param independent_rank number of independent transformed directions
!> \param correction_rank number of directions with positive missing curvature
!> \param independence smallest retained orthogonal step fraction
!> \param compatibility relative antisymmetric norm of the measured modal response
!> \param correction_norm Frobenius norm of the PSD correction
!> \param curvature_error largest retained modal curvature error after the update
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_directional_subspace_curvature_update( &
      hessian, steps, secant_targets, updated_hessian, ready, independent_rank, &
      correction_rank, independence, compatibility, correction_norm, curvature_error)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: hessian, steps, secant_targets
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: updated_hessian
      LOGICAL, INTENT(OUT)                               :: ready
      INTEGER, INTENT(OUT)                               :: independent_rank, correction_rank
      REAL(KIND=dp), INTENT(OUT)                         :: independence, compatibility, &
                                                            correction_norm, curvature_error

      INTEGER                                            :: i, j, mode, n, nmode
      REAL(KIND=dp) :: coefficient, correction_curvature, curvature_scale, measured_curvature, &
         modal_norm, model_curvature, original_norm, projection, response_norm
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: response, vector
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: modal_metric, modes, responses

      n = SIZE(steps, 1)
      nmode = SIZE(steps, 2)
      CPASSERT(ALL(SHAPE(hessian) == [n, n]))
      CPASSERT(ALL(SHAPE(secant_targets) == [n, nmode]))
      CPASSERT(ALL(SHAPE(updated_hessian) == [n, n]))

      updated_hessian(:, :) = hessian(:, :)
      ready = .FALSE.
      independent_rank = 0
      correction_rank = 0
      independence = 0.0_dp
      compatibility = 0.0_dp
      correction_norm = 0.0_dp
      curvature_error = 0.0_dp
      IF (n <= 0 .OR. nmode <= 0) RETURN

      ALLOCATE (vector(n), response(n), modes(n, nmode), responses(n, nmode), &
                modal_metric(nmode, nmode))
      modes(:, :) = 0.0_dp
      responses(:, :) = 0.0_dp
      modal_metric(:, :) = 0.0_dp
      independence = 1.0_dp

      DO mode = 1, nmode
         vector(:) = steps(:, mode)
         response(:) = secant_targets(:, mode)
         original_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(vector, vector)))
         IF (original_norm <= SQRT(TINY(1.0_dp))) CYCLE
         DO j = 1, independent_rank
            projection = DOT_PRODUCT(modes(:, j), vector)
            vector(:) = vector - projection*modes(:, j)
            response(:) = response - projection*responses(:, j)
         END DO
         modal_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(vector, vector)))
         independence = MIN(independence, modal_norm/original_norm)
         IF (modal_norm <= SQRT(EPSILON(1.0_dp))*original_norm) CYCLE

         independent_rank = independent_rank + 1
         modes(:, independent_rank) = vector/modal_norm
         responses(:, independent_rank) = response/modal_norm
      END DO
      IF (independent_rank <= 0) THEN
         independence = 0.0_dp
         DEALLOCATE (vector, response, modes, responses, modal_metric)
         RETURN
      END IF

      modal_metric(1:independent_rank, 1:independent_rank) = &
         MATMUL(TRANSPOSE(modes(:, 1:independent_rank)), responses(:, 1:independent_rank))
      response_norm = SQRT(MAX(0.0_dp, &
                               SUM(modal_metric(1:independent_rank, 1:independent_rank)**2)))
      compatibility = SQRT(MAX(0.0_dp, &
                               SUM((modal_metric(1:independent_rank, 1:independent_rank) - &
                                    TRANSPOSE(modal_metric(1:independent_rank, 1:independent_rank)))**2)))/ &
                      MAX(response_norm, EPSILON(1.0_dp))

      DO mode = 1, independent_rank
         measured_curvature = DOT_PRODUCT(modes(:, mode), responses(:, mode))
         model_curvature = DOT_PRODUCT(modes(:, mode), &
                                       MATMUL(updated_hessian, modes(:, mode)))
         correction_curvature = measured_curvature - model_curvature
         curvature_scale = MAX(ABS(measured_curvature), ABS(model_curvature), TINY(1.0_dp))
         IF (measured_curvature <= 0.0_dp .OR. &
             correction_curvature <= 64.0_dp*EPSILON(1.0_dp)*curvature_scale) CYCLE
         correction_rank = correction_rank + 1
         coefficient = correction_curvature
         DO j = 1, n
            DO i = 1, n
               updated_hessian(i, j) = updated_hessian(i, j) + &
                                       coefficient*modes(i, mode)*modes(j, mode)
            END DO
         END DO
         correction_norm = correction_norm + correction_curvature**2
      END DO
      correction_norm = SQRT(MAX(0.0_dp, correction_norm))
      DO mode = 1, independent_rank
         curvature_error = MAX(curvature_error, &
                               ABS(DOT_PRODUCT(modes(:, mode), &
                                               MATMUL(updated_hessian, modes(:, mode))) - &
                                   DOT_PRODUCT(modes(:, mode), responses(:, mode))))
      END DO
      ready = correction_rank > 0 .AND. ALL(updated_hessian == updated_hessian) .AND. &
              ALL(ABS(updated_hessian) < HUGE(1.0_dp)) .AND. &
              compatibility == compatibility .AND. correction_norm < HUGE(1.0_dp)
      IF (.NOT. ready) THEN
         updated_hessian(:, :) = hessian(:, :)
         correction_rank = 0
         correction_norm = 0.0_dp
         curvature_error = 0.0_dp
      END IF
      DEALLOCATE (vector, response, modes, responses, modal_metric)

   END SUBROUTINE qs_scf_kp_directional_subspace_curvature_update

! **************************************************************************************************
!> \brief Apply a symmetric least-change update for two accepted vector secants.
!> \param hessian symmetric reference Hessian
!> \param steps independent accepted steps S
!> \param secant_targets observed gradient differences Y
!> \param weight fraction of the least-change correction
!> \param updated_hessian corrected symmetric Hessian
!> \param ready whether the two-step subspace was finite and independent
!> \param independence normalized determinant of S^T S
!> \param compatibility_norm relative target correction needed to make S^T Y symmetric
!> \param correction_norm Frobenius norm of the Hessian correction
!> \param residual_norm norm of the compatible secant residual before the update
!> \param updated_residual_norm norm of the compatible secant residual after the update
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_symmetric_multisecant_update(hessian, steps, secant_targets, weight, &
                                                     updated_hessian, ready, independence, &
                                                     compatibility_norm, correction_norm, &
                                                     residual_norm, updated_residual_norm)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: hessian, steps, secant_targets
      REAL(KIND=dp), INTENT(IN)                          :: weight
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: updated_hessian
      LOGICAL, INTENT(OUT)                               :: ready
      REAL(KIND=dp), INTENT(OUT)                         :: independence, compatibility_norm, &
                                                            correction_norm, residual_norm, &
                                                            updated_residual_norm

      INTEGER                                            :: n
      REAL(KIND=dp)                                      :: det, gram_scale, update_weight
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: compatible_targets, correction, model, &
                                                            residual, step_inverse, &
                                                            updated_residual
      REAL(KIND=dp), DIMENSION(2, 2)                     :: gram, gram_inverse, skew, step_residual

      n = SIZE(steps, 1)
      CPASSERT(ALL(SHAPE(hessian) == [n, n]))
      CPASSERT(SIZE(steps, 2) == 2)
      CPASSERT(ALL(SHAPE(secant_targets) == [n, 2]))
      CPASSERT(ALL(SHAPE(updated_hessian) == [n, n]))

      updated_hessian(:, :) = hessian(:, :)
      ready = .FALSE.
      independence = 0.0_dp
      compatibility_norm = 0.0_dp
      correction_norm = 0.0_dp
      residual_norm = 0.0_dp
      updated_residual_norm = 0.0_dp
      IF (n <= 0) RETURN

      update_weight = MIN(1.0_dp, MAX(0.0_dp, weight))
      IF (update_weight <= EPSILON(1.0_dp)) RETURN
      gram(:, :) = MATMUL(TRANSPOSE(steps), steps)
      gram_scale = gram(1, 1)*gram(2, 2)
      IF (gram_scale <= EPSILON(1.0_dp)) RETURN
      det = gram_scale - gram(1, 2)*gram(2, 1)
      independence = MAX(0.0_dp, det/gram_scale)
      IF (det <= SQRT(EPSILON(1.0_dp))*gram_scale) RETURN

      gram_inverse(1, 1) = gram(2, 2)/det
      gram_inverse(1, 2) = -gram(1, 2)/det
      gram_inverse(2, 1) = -gram(2, 1)/det
      gram_inverse(2, 2) = gram(1, 1)/det
      step_residual(:, :) = MATMUL(TRANSPOSE(steps), secant_targets)
      skew(:, :) = 0.5_dp*(step_residual - TRANSPOSE(step_residual))

      ALLOCATE (compatible_targets(n, 2), correction(n, n), model(n, 2), residual(n, 2), &
                step_inverse(n, 2), updated_residual(n, 2))
      step_inverse(:, :) = MATMUL(steps, gram_inverse)
      compatible_targets(:, :) = secant_targets - MATMUL(step_inverse, skew)
      compatibility_norm = SQRT(MAX(0.0_dp, SUM((compatible_targets - secant_targets)**2)))/ &
                           MAX(SQRT(MAX(0.0_dp, SUM(secant_targets**2))), EPSILON(1.0_dp))

      model(:, :) = MATMUL(hessian, steps)
      residual(:, :) = compatible_targets - model
      step_residual(:, :) = MATMUL(TRANSPOSE(steps), residual)
      step_residual(:, :) = 0.5_dp*(step_residual + TRANSPOSE(step_residual))
      correction(:, :) = MATMUL(residual, TRANSPOSE(step_inverse)) + &
                         MATMUL(step_inverse, TRANSPOSE(residual)) - &
                         MATMUL(step_inverse, MATMUL(step_residual, TRANSPOSE(step_inverse)))
      correction(:, :) = 0.5_dp*(correction + TRANSPOSE(correction))
      updated_hessian(:, :) = hessian + update_weight*correction

      residual_norm = SQRT(MAX(0.0_dp, SUM(residual**2)))
      correction_norm = SQRT(MAX(0.0_dp, SUM((updated_hessian - hessian)**2)))
      updated_residual(:, :) = compatible_targets - MATMUL(updated_hessian, steps)
      updated_residual_norm = SQRT(MAX(0.0_dp, SUM(updated_residual**2)))
      ready = correction_norm == correction_norm .AND. &
              updated_residual_norm == updated_residual_norm .AND. &
              compatibility_norm == compatibility_norm
      IF (.NOT. ready) updated_hessian(:, :) = hessian(:, :)
      DEALLOCATE (compatible_targets, correction, model, residual, step_inverse, updated_residual)

   END SUBROUTINE qs_scf_kp_symmetric_multisecant_update

! **************************************************************************************************
!> \brief Apply a dimensionally scaled full coupled two-secant update.
!> \param rotation_hessian rotation block H_RR
!> \param energy_hessian fixed-N energy block H_ee
!> \param energy_cross signed cross block C
!> \param rotation_steps accepted rotation steps
!> \param energy_steps accepted energy steps
!> \param rotation_targets observed rotation-gradient differences
!> \param energy_targets observed energy-gradient differences
!> \param weight fraction of the least-change correction
!> \param updated_rotation_hessian corrected rotation block
!> \param updated_energy_hessian corrected energy block
!> \param updated_energy_cross corrected signed cross block
!> \param ready whether the full update was finite and independent
!> \param independence normalized determinant of the two-step Gram matrix
!> \param compatibility_norm relative symmetric-target correction
!> \param correction_norm scaled Frobenius norm of the full Hessian correction
!> \param residual_norm scaled full-secant residual before the update
!> \param updated_residual_norm scaled full-secant residual after the update
!> \param reference_norm scaled Frobenius norm of the reference Hessian
!> \param rotation_correction_ratio relative scaled H_RR correction
!> \param energy_correction_ratio relative scaled H_ee correction
!> \param cross_correction_ratio relative scaled C correction
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_coupled_multisecant_update(rotation_hessian, energy_hessian, energy_cross, &
                                                   rotation_steps, energy_steps, rotation_targets, &
                                                   energy_targets, weight, updated_rotation_hessian, &
                                                   updated_energy_hessian, updated_energy_cross, ready, &
                                                   independence, compatibility_norm, correction_norm, &
                                                   residual_norm, updated_residual_norm, reference_norm, &
                                                   rotation_correction_ratio, energy_correction_ratio, &
                                                   cross_correction_ratio)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN) :: rotation_hessian, energy_hessian, &
         energy_cross, rotation_steps, energy_steps, rotation_targets, energy_targets
      REAL(KIND=dp), INTENT(IN)                          :: weight
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: updated_rotation_hessian, &
                                                            updated_energy_hessian, &
                                                            updated_energy_cross
      LOGICAL, INTENT(OUT)                               :: ready
      REAL(KIND=dp), INTENT(OUT) :: independence, compatibility_norm, correction_norm, &
         residual_norm, updated_residual_norm, reference_norm, rotation_correction_ratio, &
         energy_correction_ratio, cross_correction_ratio

      INTEGER                                            :: i, j, nener, nfull, nrot
      REAL(KIND=dp)                                      :: block_floor, block_max
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: coordinate_scale
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: full_hessian, full_steps, full_targets, &
                                                            updated_full_hessian

      nrot = SIZE(rotation_hessian, 1)
      nener = SIZE(energy_hessian, 1)
      nfull = nrot + nener
      CPASSERT(SIZE(rotation_hessian, 2) == nrot)
      CPASSERT(SIZE(energy_hessian, 2) == nener)
      CPASSERT(ALL(SHAPE(energy_cross) == [nener, nrot]))
      CPASSERT(ALL(SHAPE(rotation_steps) == [nrot, 2]))
      CPASSERT(ALL(SHAPE(energy_steps) == [nener, 2]))
      CPASSERT(ALL(SHAPE(rotation_targets) == [nrot, 2]))
      CPASSERT(ALL(SHAPE(energy_targets) == [nener, 2]))
      CPASSERT(ALL(SHAPE(updated_rotation_hessian) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(updated_energy_hessian) == [nener, nener]))
      CPASSERT(ALL(SHAPE(updated_energy_cross) == [nener, nrot]))

      updated_rotation_hessian(:, :) = rotation_hessian(:, :)
      updated_energy_hessian(:, :) = energy_hessian(:, :)
      updated_energy_cross(:, :) = energy_cross(:, :)
      ready = .FALSE.
      independence = 0.0_dp
      compatibility_norm = 0.0_dp
      correction_norm = 0.0_dp
      residual_norm = 0.0_dp
      updated_residual_norm = 0.0_dp
      reference_norm = 0.0_dp
      rotation_correction_ratio = 0.0_dp
      energy_correction_ratio = 0.0_dp
      cross_correction_ratio = 0.0_dp
      IF (nrot <= 0 .OR. nener <= 0) RETURN
      ALLOCATE (coordinate_scale(nfull), full_hessian(nfull, nfull), full_steps(nfull, 2), &
                full_targets(nfull, 2), updated_full_hessian(nfull, nfull))

      full_hessian(:, :) = 0.0_dp
      full_hessian(1:nrot, 1:nrot) = rotation_hessian(:, :)
      full_hessian(1:nrot, nrot + 1:nfull) = -TRANSPOSE(energy_cross(:, :))
      full_hessian(nrot + 1:nfull, 1:nrot) = -energy_cross(:, :)
      full_hessian(nrot + 1:nfull, nrot + 1:nfull) = energy_hessian(:, :)
      full_steps(1:nrot, :) = rotation_steps(:, :)
      full_steps(nrot + 1:nfull, :) = energy_steps(:, :)
      full_targets(1:nrot, :) = rotation_targets(:, :)
      full_targets(nrot + 1:nfull, :) = energy_targets(:, :)

      ! Rotation coordinates are dimensionless while auxiliary energies carry
      ! energy units.  Normalize each block with its reference diagonal before
      ! applying the Euclidean least-change update so that the result is
      ! invariant under a change of auxiliary-energy units.
      block_max = MAXVAL(ABS([(rotation_hessian(i, i), i=1, nrot)]))
      IF (block_max > TINY(1.0_dp)) THEN
         block_floor = SQRT(EPSILON(1.0_dp))*block_max
         DO i = 1, nrot
            coordinate_scale(i) = SQRT(MAX(ABS(rotation_hessian(i, i)), block_floor))
         END DO
      ELSE
         coordinate_scale(1:nrot) = 1.0_dp
      END IF
      block_max = MAXVAL(ABS([(energy_hessian(i, i), i=1, nener)]))
      IF (block_max > TINY(1.0_dp)) THEN
         block_floor = SQRT(EPSILON(1.0_dp))*block_max
         DO i = 1, nener
            coordinate_scale(nrot + i) = SQRT(MAX(ABS(energy_hessian(i, i)), block_floor))
         END DO
      ELSE
         coordinate_scale(nrot + 1:nfull) = 1.0_dp
      END IF

      DO j = 1, nfull
         DO i = 1, nfull
            full_hessian(i, j) = full_hessian(i, j)/ &
                                 (coordinate_scale(i)*coordinate_scale(j))
         END DO
      END DO
      DO i = 1, nfull
         full_steps(i, :) = coordinate_scale(i)*full_steps(i, :)
         full_targets(i, :) = full_targets(i, :)/coordinate_scale(i)
      END DO

      reference_norm = SQRT(MAX(0.0_dp, SUM(full_hessian**2)))
      CALL qs_scf_kp_symmetric_multisecant_update( &
         full_hessian, full_steps, full_targets, weight, updated_full_hessian, ready, independence, &
         compatibility_norm, correction_norm, residual_norm, updated_residual_norm)
      rotation_correction_ratio = &
         SQRT(MAX(0.0_dp, SUM((updated_full_hessian(1:nrot, 1:nrot) - &
                               full_hessian(1:nrot, 1:nrot))**2)))/ &
         MAX(SQRT(MAX(0.0_dp, SUM(full_hessian(1:nrot, 1:nrot)**2))), EPSILON(1.0_dp))
      energy_correction_ratio = &
         SQRT(MAX(0.0_dp, SUM((updated_full_hessian(nrot + 1:nfull, nrot + 1:nfull) - &
                               full_hessian(nrot + 1:nfull, nrot + 1:nfull))**2)))/ &
         MAX(SQRT(MAX(0.0_dp, SUM(full_hessian(nrot + 1:nfull, nrot + 1:nfull)**2))), &
             EPSILON(1.0_dp))
      cross_correction_ratio = &
         SQRT(MAX(0.0_dp, SUM((updated_full_hessian(nrot + 1:nfull, 1:nrot) - &
                               full_hessian(nrot + 1:nfull, 1:nrot))**2)))/ &
         MAX(SQRT(MAX(0.0_dp, SUM(full_hessian(nrot + 1:nfull, 1:nrot)**2))), EPSILON(1.0_dp))
      IF (ready) THEN
         DO j = 1, nfull
            DO i = 1, nfull
               updated_full_hessian(i, j) = updated_full_hessian(i, j)* &
                                            coordinate_scale(i)*coordinate_scale(j)
            END DO
         END DO
         updated_rotation_hessian(:, :) = updated_full_hessian(1:nrot, 1:nrot)
         updated_energy_cross(:, :) = -updated_full_hessian(nrot + 1:nfull, 1:nrot)
         updated_energy_hessian(:, :) = updated_full_hessian(nrot + 1:nfull, nrot + 1:nfull)
      END IF
      DEALLOCATE (coordinate_scale, full_hessian, full_steps, full_targets, updated_full_hessian)

   END SUBROUTINE qs_scf_kp_coupled_multisecant_update

! **************************************************************************************************
!> \brief Fit a symmetric coupled Hessian only in the span of two accepted full-space steps.
!>
!>        The unrestricted least-change update can introduce rotation/energy response outside the
!>        directions sampled by the accepted steps.  This variant first applies the same
!>        dimensionally consistent coordinate scaling, then replaces only Q^T H Q, where Q spans
!>        the two coupled (rotation, auxiliary-energy) steps.  The orthogonal complement and its
!>        coupling to Q remain exactly equal to the analytic fixed-N Mermin model.
!> \param rotation_hessian rotation block H_RR
!> \param energy_hessian fixed-N energy block H_ee
!> \param energy_cross signed cross block C
!> \param rotation_steps accepted rotation steps
!> \param energy_steps accepted auxiliary-energy steps
!> \param rotation_targets observed rotation-gradient differences
!> \param energy_targets observed auxiliary-energy-gradient differences
!> \param weight fraction of the subspace correction
!> \param updated_rotation_hessian corrected rotation block
!> \param updated_energy_hessian corrected energy block
!> \param updated_energy_cross corrected signed cross block
!> \param ready whether the two-step subspace update is finite and independent
!> \param independence normalized determinant of the scaled two-step Gram matrix
!> \param compatibility_norm relative antisymmetric part of the measured subspace curvature
!> \param response_capture fraction of the analytic-model residual lying in the sampled span
!> \param correction_norm scaled Frobenius norm of the subspace Hessian correction
!> \param residual_norm scaled full-secant residual before the update
!> \param updated_residual_norm scaled full-secant residual after the update
!> \param projected_residual_norm residual left inside the sampled span after the update
!> \param rotation_correction_ratio relative scaled H_RR correction
!> \param energy_correction_ratio relative scaled H_ee correction
!> \param cross_correction_ratio relative scaled C correction
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_coupled_subspace_multisecant_update( &
      rotation_hessian, energy_hessian, energy_cross, rotation_steps, energy_steps, &
      rotation_targets, energy_targets, weight, updated_rotation_hessian, &
      updated_energy_hessian, updated_energy_cross, ready, independence, compatibility_norm, &
      response_capture, correction_norm, residual_norm, updated_residual_norm, &
      projected_residual_norm, rotation_correction_ratio, energy_correction_ratio, &
      cross_correction_ratio)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN) :: rotation_hessian, energy_hessian, &
         energy_cross, rotation_steps, energy_steps, rotation_targets, energy_targets
      REAL(KIND=dp), INTENT(IN)                          :: weight
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: updated_rotation_hessian, &
                                                            updated_energy_hessian, &
                                                            updated_energy_cross
      LOGICAL, INTENT(OUT)                               :: ready
      REAL(KIND=dp), INTENT(OUT) :: independence, compatibility_norm, response_capture, &
         correction_norm, residual_norm, updated_residual_norm, projected_residual_norm, &
         rotation_correction_ratio, energy_correction_ratio, cross_correction_ratio

      INTEGER                                            :: i, j, nener, nfull, nrot
      REAL(KIND=dp)                                      :: block_floor, block_max, det, gram_scale, &
                                                            qnorm, update_weight
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: coordinate_scale
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :) :: correction, full_hessian, full_steps, &
         full_targets, model_residual, projected_residual, q, updated_full_hessian, &
         updated_model_residual
      REAL(KIND=dp), DIMENSION(2, 2)                     :: gram, inverse_coordinates, &
                                                            measured_curvature, step_coordinates, &
                                                            subspace_hessian, symmetric_curvature

      nrot = SIZE(rotation_hessian, 1)
      nener = SIZE(energy_hessian, 1)
      nfull = nrot + nener
      CPASSERT(SIZE(rotation_hessian, 2) == nrot)
      CPASSERT(SIZE(energy_hessian, 2) == nener)
      CPASSERT(ALL(SHAPE(energy_cross) == [nener, nrot]))
      CPASSERT(ALL(SHAPE(rotation_steps) == [nrot, 2]))
      CPASSERT(ALL(SHAPE(energy_steps) == [nener, 2]))
      CPASSERT(ALL(SHAPE(rotation_targets) == [nrot, 2]))
      CPASSERT(ALL(SHAPE(energy_targets) == [nener, 2]))
      CPASSERT(ALL(SHAPE(updated_rotation_hessian) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(updated_energy_hessian) == [nener, nener]))
      CPASSERT(ALL(SHAPE(updated_energy_cross) == [nener, nrot]))

      updated_rotation_hessian(:, :) = rotation_hessian(:, :)
      updated_energy_hessian(:, :) = energy_hessian(:, :)
      updated_energy_cross(:, :) = energy_cross(:, :)
      ready = .FALSE.
      independence = 0.0_dp
      compatibility_norm = 0.0_dp
      response_capture = 0.0_dp
      correction_norm = 0.0_dp
      residual_norm = 0.0_dp
      updated_residual_norm = 0.0_dp
      projected_residual_norm = 0.0_dp
      rotation_correction_ratio = 0.0_dp
      energy_correction_ratio = 0.0_dp
      cross_correction_ratio = 0.0_dp
      IF (nrot <= 0 .OR. nener <= 0) RETURN
      update_weight = MIN(1.0_dp, MAX(0.0_dp, weight))
      IF (update_weight <= EPSILON(1.0_dp)) RETURN

      ALLOCATE (coordinate_scale(nfull), correction(nfull, nfull), full_hessian(nfull, nfull), &
                full_steps(nfull, 2), full_targets(nfull, 2), model_residual(nfull, 2), &
                projected_residual(nfull, 2), q(nfull, 2), updated_full_hessian(nfull, nfull), &
                updated_model_residual(nfull, 2))

      full_hessian(:, :) = 0.0_dp
      full_hessian(1:nrot, 1:nrot) = rotation_hessian(:, :)
      full_hessian(1:nrot, nrot + 1:nfull) = -TRANSPOSE(energy_cross(:, :))
      full_hessian(nrot + 1:nfull, 1:nrot) = -energy_cross(:, :)
      full_hessian(nrot + 1:nfull, nrot + 1:nfull) = energy_hessian(:, :)
      full_steps(1:nrot, :) = rotation_steps(:, :)
      full_steps(nrot + 1:nfull, :) = energy_steps(:, :)
      full_targets(1:nrot, :) = rotation_targets(:, :)
      full_targets(nrot + 1:nfull, :) = energy_targets(:, :)

      block_max = MAXVAL(ABS([(rotation_hessian(i, i), i=1, nrot)]))
      IF (block_max > TINY(1.0_dp)) THEN
         block_floor = SQRT(EPSILON(1.0_dp))*block_max
         DO i = 1, nrot
            coordinate_scale(i) = SQRT(MAX(ABS(rotation_hessian(i, i)), block_floor))
         END DO
      ELSE
         coordinate_scale(1:nrot) = 1.0_dp
      END IF
      block_max = MAXVAL(ABS([(energy_hessian(i, i), i=1, nener)]))
      IF (block_max > TINY(1.0_dp)) THEN
         block_floor = SQRT(EPSILON(1.0_dp))*block_max
         DO i = 1, nener
            coordinate_scale(nrot + i) = SQRT(MAX(ABS(energy_hessian(i, i)), block_floor))
         END DO
      ELSE
         coordinate_scale(nrot + 1:nfull) = 1.0_dp
      END IF

      DO j = 1, nfull
         DO i = 1, nfull
            full_hessian(i, j) = full_hessian(i, j)/ &
                                 (coordinate_scale(i)*coordinate_scale(j))
         END DO
      END DO
      DO i = 1, nfull
         full_steps(i, :) = coordinate_scale(i)*full_steps(i, :)
         full_targets(i, :) = full_targets(i, :)/coordinate_scale(i)
      END DO

      gram(:, :) = MATMUL(TRANSPOSE(full_steps), full_steps)
      gram_scale = gram(1, 1)*gram(2, 2)
      IF (gram_scale <= EPSILON(1.0_dp)) THEN
         DEALLOCATE (coordinate_scale, correction, full_hessian, full_steps, full_targets, &
                     model_residual, projected_residual, q, updated_full_hessian, &
                     updated_model_residual)
         RETURN
      END IF
      det = gram_scale - gram(1, 2)*gram(2, 1)
      independence = MAX(0.0_dp, det/gram_scale)
      IF (det <= SQRT(EPSILON(1.0_dp))*gram_scale) THEN
         DEALLOCATE (coordinate_scale, correction, full_hessian, full_steps, full_targets, &
                     model_residual, projected_residual, q, updated_full_hessian, &
                     updated_model_residual)
         RETURN
      END IF

      q(:, 1) = full_steps(:, 1)/SQRT(gram(1, 1))
      q(:, 2) = full_steps(:, 2) - DOT_PRODUCT(q(:, 1), full_steps(:, 2))*q(:, 1)
      qnorm = SQRT(MAX(0.0_dp, DOT_PRODUCT(q(:, 2), q(:, 2))))
      IF (qnorm <= SQRT(EPSILON(1.0_dp))*SQRT(gram(2, 2))) THEN
         DEALLOCATE (coordinate_scale, correction, full_hessian, full_steps, full_targets, &
                     model_residual, projected_residual, q, updated_full_hessian, &
                     updated_model_residual)
         RETURN
      END IF
      q(:, 2) = q(:, 2)/qnorm
      step_coordinates(:, :) = MATMUL(TRANSPOSE(q), full_steps)
      det = step_coordinates(1, 1)*step_coordinates(2, 2) - &
            step_coordinates(1, 2)*step_coordinates(2, 1)
      IF (ABS(det) <= SQRT(EPSILON(1.0_dp))* &
          MAX(1.0_dp, SQRT(MAX(0.0_dp, SUM(step_coordinates**2))))) THEN
         DEALLOCATE (coordinate_scale, correction, full_hessian, full_steps, full_targets, &
                     model_residual, projected_residual, q, updated_full_hessian, &
                     updated_model_residual)
         RETURN
      END IF
      inverse_coordinates(1, 1) = step_coordinates(2, 2)/det
      inverse_coordinates(1, 2) = -step_coordinates(1, 2)/det
      inverse_coordinates(2, 1) = -step_coordinates(2, 1)/det
      inverse_coordinates(2, 2) = step_coordinates(1, 1)/det

      measured_curvature(:, :) = MATMUL(MATMUL(TRANSPOSE(q), full_targets), inverse_coordinates)
      symmetric_curvature(:, :) = 0.5_dp*(measured_curvature + TRANSPOSE(measured_curvature))
      compatibility_norm = SQRT(MAX(0.0_dp, SUM((measured_curvature - symmetric_curvature)**2)))/ &
                           MAX(SQRT(MAX(0.0_dp, SUM(measured_curvature**2))), EPSILON(1.0_dp))
      subspace_hessian(:, :) = MATMUL(TRANSPOSE(q), MATMUL(full_hessian, q))
      correction(:, :) = MATMUL(q, MATMUL(symmetric_curvature - subspace_hessian, TRANSPOSE(q)))
      updated_full_hessian(:, :) = full_hessian + update_weight*correction
      updated_full_hessian(:, :) = 0.5_dp*(updated_full_hessian + TRANSPOSE(updated_full_hessian))

      model_residual(:, :) = full_targets - MATMUL(full_hessian, full_steps)
      residual_norm = SQRT(MAX(0.0_dp, SUM(model_residual**2)))
      projected_residual(:, :) = MATMUL(q, MATMUL(TRANSPOSE(q), model_residual))
      IF (residual_norm > EPSILON(residual_norm)) &
         response_capture = SQRT(MAX(0.0_dp, SUM(projected_residual**2)))/residual_norm
      updated_model_residual(:, :) = full_targets - MATMUL(updated_full_hessian, full_steps)
      updated_residual_norm = SQRT(MAX(0.0_dp, SUM(updated_model_residual**2)))
      projected_residual_norm = SQRT(MAX(0.0_dp, &
                                         SUM(MATMUL(TRANSPOSE(q), updated_model_residual)**2)))
      correction_norm = SQRT(MAX(0.0_dp, SUM((updated_full_hessian - full_hessian)**2)))
      rotation_correction_ratio = &
         update_weight*SQRT(MAX(0.0_dp, SUM(correction(1:nrot, 1:nrot)**2)))/ &
         MAX(SQRT(MAX(0.0_dp, SUM(full_hessian(1:nrot, 1:nrot)**2))), EPSILON(1.0_dp))
      energy_correction_ratio = &
         update_weight*SQRT(MAX(0.0_dp, SUM(correction(nrot + 1:nfull, nrot + 1:nfull)**2)))/ &
         MAX(SQRT(MAX(0.0_dp, SUM(full_hessian(nrot + 1:nfull, nrot + 1:nfull)**2))), &
             EPSILON(1.0_dp))
      cross_correction_ratio = &
         update_weight*SQRT(MAX(0.0_dp, SUM(correction(nrot + 1:nfull, 1:nrot)**2)))/ &
         MAX(SQRT(MAX(0.0_dp, SUM(full_hessian(nrot + 1:nfull, 1:nrot)**2))), EPSILON(1.0_dp))

      ready = ALL(updated_full_hessian == updated_full_hessian) .AND. &
              compatibility_norm == compatibility_norm .AND. response_capture == response_capture .AND. &
              updated_residual_norm == updated_residual_norm .AND. &
              projected_residual_norm == projected_residual_norm
      IF (ready) THEN
         DO j = 1, nfull
            DO i = 1, nfull
               updated_full_hessian(i, j) = updated_full_hessian(i, j)* &
                                            coordinate_scale(i)*coordinate_scale(j)
            END DO
         END DO
         updated_rotation_hessian(:, :) = updated_full_hessian(1:nrot, 1:nrot)
         updated_energy_cross(:, :) = -updated_full_hessian(nrot + 1:nfull, 1:nrot)
         updated_energy_hessian(:, :) = updated_full_hessian(nrot + 1:nfull, nrot + 1:nfull)
      END IF
      DEALLOCATE (coordinate_scale, correction, full_hessian, full_steps, full_targets, &
                  model_residual, projected_residual, q, updated_full_hessian, &
                  updated_model_residual)

   END SUBROUTINE qs_scf_kp_coupled_subspace_multisecant_update

! **************************************************************************************************
!> \brief Score a rank-one coupled response fitted on one accepted secant against the next.
!>
!>        The training response changes the analytic fixed-N Mermin Hessian only along the scaled
!>        full-space training step.  The validation secant is not used to build the correction.
!>        Its residual reduction is therefore an out-of-sample measure of whether the observed
!>        self-consistent density/Hamiltonian response persists between accepted steps.
!> \param rotation_hessian rotation block H_RR
!> \param energy_hessian fixed-N energy block H_ee
!> \param energy_cross signed cross block C
!> \param training_rotation_step older accepted rotation step
!> \param training_energy_step older accepted auxiliary-energy step
!> \param training_rotation_target older observed rotation-gradient difference
!> \param training_energy_target older observed auxiliary-energy-gradient difference
!> \param validation_rotation_step newer accepted rotation step
!> \param validation_energy_step newer accepted auxiliary-energy step
!> \param validation_rotation_target newer observed rotation-gradient difference
!> \param validation_energy_target newer observed auxiliary-energy-gradient difference
!> \param updated_rotation_hessian rank-one response model fitted to the training secant
!> \param updated_energy_hessian rank-one response energy block
!> \param updated_energy_cross rank-one response signed cross block
!> \param ready whether the scaled training and validation geometry is finite
!> \param step_overlap absolute cosine between the training and validation steps
!> \param training_response_capture fraction of the training model residual parallel to its step
!> \param validation_quality fractional squared full-residual reduction; negative means degradation
!> \param validation_rotation_quality fractional squared rotation-residual reduction
!> \param validation_energy_quality fractional squared energy-residual reduction
!> \param validation_alignment alignment of predicted and observed validation response
!> \param validation_curvature_ratio validation/training scalar response curvature
!> \param validation_residual_norm analytic validation residual norm
!> \param predicted_residual_norm validation residual norm after the rank-one response
!> \param response_curvature fitted scaled rank-one response curvature
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_coupled_secant_prediction( &
      rotation_hessian, energy_hessian, energy_cross, training_rotation_step, &
      training_energy_step, training_rotation_target, training_energy_target, &
      validation_rotation_step, validation_energy_step, validation_rotation_target, &
      validation_energy_target, updated_rotation_hessian, updated_energy_hessian, &
      updated_energy_cross, ready, step_overlap, training_response_capture, validation_quality, &
      validation_rotation_quality, validation_energy_quality, validation_alignment, &
      validation_curvature_ratio, validation_residual_norm, predicted_residual_norm, &
      response_curvature)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: rotation_hessian, energy_hessian, &
                                                            energy_cross
      REAL(KIND=dp), DIMENSION(:), INTENT(IN) :: training_rotation_step, training_energy_step, &
         training_rotation_target, training_energy_target, validation_rotation_step, &
         validation_energy_step, validation_rotation_target, validation_energy_target
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: updated_rotation_hessian, &
                                                            updated_energy_hessian, &
                                                            updated_energy_cross
      LOGICAL, INTENT(OUT)                               :: ready
      REAL(KIND=dp), INTENT(OUT) :: step_overlap, training_response_capture, validation_quality, &
         validation_rotation_quality, validation_energy_quality, validation_alignment, &
         validation_curvature_ratio, validation_residual_norm, predicted_residual_norm, &
         response_curvature

      INTEGER                                            :: i, j, nener, nfull, nrot
      REAL(KIND=dp) :: block_floor, block_max, correction_norm, energy_residual_sq, &
         predicted_energy_residual_sq, predicted_rotation_residual_sq, projected_step, &
         rotation_residual_sq, training_norm, training_residual_norm, validation_norm, &
         validation_residual_sq, validation_response_curvature
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:) :: coordinate_scale, predicted_response, &
         predicted_validation_residual, q, training_residual, training_step, training_target, &
         validation_residual, validation_step, validation_target
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: full_hessian, updated_full_hessian

      nrot = SIZE(rotation_hessian, 1)
      nener = SIZE(energy_hessian, 1)
      nfull = nrot + nener
      CPASSERT(SIZE(rotation_hessian, 2) == nrot)
      CPASSERT(SIZE(energy_hessian, 2) == nener)
      CPASSERT(ALL(SHAPE(energy_cross) == [nener, nrot]))
      CPASSERT(SIZE(training_rotation_step) == nrot)
      CPASSERT(SIZE(training_energy_step) == nener)
      CPASSERT(SIZE(training_rotation_target) == nrot)
      CPASSERT(SIZE(training_energy_target) == nener)
      CPASSERT(SIZE(validation_rotation_step) == nrot)
      CPASSERT(SIZE(validation_energy_step) == nener)
      CPASSERT(SIZE(validation_rotation_target) == nrot)
      CPASSERT(SIZE(validation_energy_target) == nener)
      CPASSERT(ALL(SHAPE(updated_rotation_hessian) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(updated_energy_hessian) == [nener, nener]))
      CPASSERT(ALL(SHAPE(updated_energy_cross) == [nener, nrot]))

      updated_rotation_hessian(:, :) = rotation_hessian(:, :)
      updated_energy_hessian(:, :) = energy_hessian(:, :)
      updated_energy_cross(:, :) = energy_cross(:, :)
      ready = .FALSE.
      step_overlap = 0.0_dp
      training_response_capture = 0.0_dp
      validation_quality = 0.0_dp
      validation_rotation_quality = 0.0_dp
      validation_energy_quality = 0.0_dp
      validation_alignment = 0.0_dp
      validation_curvature_ratio = 0.0_dp
      validation_residual_norm = 0.0_dp
      predicted_residual_norm = 0.0_dp
      response_curvature = 0.0_dp
      IF (nrot <= 0 .OR. nener <= 0) RETURN

      ALLOCATE (coordinate_scale(nfull), full_hessian(nfull, nfull), &
                updated_full_hessian(nfull, nfull), predicted_response(nfull), &
                predicted_validation_residual(nfull), q(nfull), training_residual(nfull), &
                training_step(nfull), training_target(nfull), validation_residual(nfull), &
                validation_step(nfull), validation_target(nfull))
      full_hessian(:, :) = 0.0_dp
      full_hessian(1:nrot, 1:nrot) = rotation_hessian(:, :)
      full_hessian(1:nrot, nrot + 1:nfull) = -TRANSPOSE(energy_cross(:, :))
      full_hessian(nrot + 1:nfull, 1:nrot) = -energy_cross(:, :)
      full_hessian(nrot + 1:nfull, nrot + 1:nfull) = energy_hessian(:, :)
      training_step(1:nrot) = training_rotation_step(:)
      training_step(nrot + 1:nfull) = training_energy_step(:)
      training_target(1:nrot) = training_rotation_target(:)
      training_target(nrot + 1:nfull) = training_energy_target(:)
      validation_step(1:nrot) = validation_rotation_step(:)
      validation_step(nrot + 1:nfull) = validation_energy_step(:)
      validation_target(1:nrot) = validation_rotation_target(:)
      validation_target(nrot + 1:nfull) = validation_energy_target(:)

      block_max = MAXVAL(ABS([(rotation_hessian(i, i), i=1, nrot)]))
      IF (block_max > TINY(1.0_dp)) THEN
         block_floor = SQRT(EPSILON(1.0_dp))*block_max
         DO i = 1, nrot
            coordinate_scale(i) = SQRT(MAX(ABS(rotation_hessian(i, i)), block_floor))
         END DO
      ELSE
         coordinate_scale(1:nrot) = 1.0_dp
      END IF
      block_max = MAXVAL(ABS([(energy_hessian(i, i), i=1, nener)]))
      IF (block_max > TINY(1.0_dp)) THEN
         block_floor = SQRT(EPSILON(1.0_dp))*block_max
         DO i = 1, nener
            coordinate_scale(nrot + i) = SQRT(MAX(ABS(energy_hessian(i, i)), block_floor))
         END DO
      ELSE
         coordinate_scale(nrot + 1:nfull) = 1.0_dp
      END IF
      DO j = 1, nfull
         DO i = 1, nfull
            full_hessian(i, j) = full_hessian(i, j)/ &
                                 (coordinate_scale(i)*coordinate_scale(j))
         END DO
      END DO
      training_step(:) = coordinate_scale(:)*training_step(:)
      validation_step(:) = coordinate_scale(:)*validation_step(:)
      training_target(:) = training_target(:)/coordinate_scale(:)
      validation_target(:) = validation_target(:)/coordinate_scale(:)

      training_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(training_step, training_step)))
      validation_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(validation_step, validation_step)))
      IF (training_norm <= SQRT(EPSILON(1.0_dp)) .OR. &
          validation_norm <= SQRT(EPSILON(1.0_dp))) THEN
         DEALLOCATE (coordinate_scale, full_hessian, updated_full_hessian, predicted_response, &
                     predicted_validation_residual, q, training_residual, training_step, &
                     training_target, validation_residual, validation_step, validation_target)
         RETURN
      END IF
      q(:) = training_step(:)/training_norm
      projected_step = DOT_PRODUCT(q, validation_step)
      step_overlap = ABS(projected_step)/validation_norm

      training_residual(:) = training_target(:) - MATMUL(full_hessian, training_step)
      training_residual_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(training_residual, training_residual)))
      response_curvature = DOT_PRODUCT(q, training_residual)/training_norm
      updated_full_hessian(:, :) = full_hessian(:, :)
      DO j = 1, nfull
         DO i = 1, nfull
            updated_full_hessian(i, j) = updated_full_hessian(i, j) + &
                                         response_curvature*q(i)*q(j)
         END DO
      END DO
      IF (training_residual_norm > EPSILON(training_residual_norm)) &
         training_response_capture = ABS(DOT_PRODUCT(q, training_residual))/training_residual_norm

      validation_residual(:) = validation_target(:) - MATMUL(full_hessian, validation_step)
      predicted_response(:) = response_curvature*projected_step*q(:)
      predicted_validation_residual(:) = validation_residual(:) - predicted_response(:)
      validation_residual_sq = MAX(0.0_dp, DOT_PRODUCT(validation_residual, validation_residual))
      validation_residual_norm = SQRT(validation_residual_sq)
      predicted_residual_norm = &
         SQRT(MAX(0.0_dp, DOT_PRODUCT(predicted_validation_residual, &
                                      predicted_validation_residual)))
      IF (validation_residual_sq > EPSILON(validation_residual_sq)) &
         validation_quality = 1.0_dp - predicted_residual_norm**2/validation_residual_sq

      rotation_residual_sq = MAX(0.0_dp, &
                                 DOT_PRODUCT(validation_residual(1:nrot), &
                                             validation_residual(1:nrot)))
      predicted_rotation_residual_sq = MAX(0.0_dp, &
                                           DOT_PRODUCT(predicted_validation_residual(1:nrot), &
                                                       predicted_validation_residual(1:nrot)))
      IF (rotation_residual_sq > EPSILON(rotation_residual_sq)) &
         validation_rotation_quality = 1.0_dp - &
                                       predicted_rotation_residual_sq/rotation_residual_sq
      energy_residual_sq = MAX(0.0_dp, &
                               DOT_PRODUCT(validation_residual(nrot + 1:nfull), &
                                           validation_residual(nrot + 1:nfull)))
      predicted_energy_residual_sq = MAX(0.0_dp, &
                                         DOT_PRODUCT(predicted_validation_residual(nrot + 1:nfull), &
                                                     predicted_validation_residual(nrot + 1:nfull)))
      IF (energy_residual_sq > EPSILON(energy_residual_sq)) &
         validation_energy_quality = 1.0_dp - predicted_energy_residual_sq/energy_residual_sq

      correction_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(predicted_response, predicted_response)))
      IF (validation_residual_norm > EPSILON(validation_residual_norm) .AND. &
          correction_norm > EPSILON(correction_norm)) &
         validation_alignment = DOT_PRODUCT(validation_residual, predicted_response)/ &
                                (validation_residual_norm*correction_norm)
      IF (ABS(projected_step) > SQRT(EPSILON(1.0_dp))*validation_norm .AND. &
          ABS(response_curvature) > SQRT(EPSILON(1.0_dp))) THEN
         validation_response_curvature = DOT_PRODUCT(q, validation_residual)/projected_step
         validation_curvature_ratio = validation_response_curvature/response_curvature
      END IF
      ready = step_overlap == step_overlap .AND. training_response_capture == training_response_capture .AND. &
              validation_quality == validation_quality .AND. &
              validation_rotation_quality == validation_rotation_quality .AND. &
              validation_energy_quality == validation_energy_quality .AND. &
              validation_alignment == validation_alignment .AND. &
              validation_curvature_ratio == validation_curvature_ratio .AND. &
              validation_residual_norm == validation_residual_norm .AND. &
              predicted_residual_norm == predicted_residual_norm .AND. &
              response_curvature == response_curvature
      IF (ready) THEN
         DO j = 1, nfull
            DO i = 1, nfull
               updated_full_hessian(i, j) = updated_full_hessian(i, j)* &
                                            coordinate_scale(i)*coordinate_scale(j)
            END DO
         END DO
         updated_rotation_hessian(:, :) = updated_full_hessian(1:nrot, 1:nrot)
         updated_energy_cross(:, :) = -updated_full_hessian(nrot + 1:nfull, 1:nrot)
         updated_energy_hessian(:, :) = updated_full_hessian(nrot + 1:nfull, nrot + 1:nfull)
      END IF
      DEALLOCATE (coordinate_scale, full_hessian, updated_full_hessian, predicted_response, &
                  predicted_validation_residual, q, training_residual, training_step, &
                  training_target, validation_residual, validation_step, validation_target)

   END SUBROUTINE qs_scf_kp_coupled_secant_prediction

! **************************************************************************************************
!> \brief Predict one accepted secant from another after eliminating the fixed-N energy block.
!>
!>        The reduced target is y_R + R^T y_e and the analytic Schur block is H_RR - R^T M R.
!>        Fitting in this space rejects full-coordinate response modes that are only auxiliary-
!>        energy gauge transformations and therefore disappear from the physical OT direction.
!>        A symmetric least-change update retains response components transverse to the accepted
!>        rotation while satisfying the complete endpoint-local vector secant.
!> \param rotation_hessian ...
!> \param response_metric ...
!> \param energy_response ...
!> \param training_rotation_step ...
!> \param training_rotation_target ...
!> \param training_energy_target ...
!> \param validation_rotation_step ...
!> \param validation_rotation_target ...
!> \param validation_energy_target ...
!> \param updated_rotation_hessian ...
!> \param ready ...
!> \param step_overlap ...
!> \param training_response_capture ...
!> \param validation_quality ...
!> \param validation_alignment ...
!> \param validation_curvature_ratio ...
!> \param validation_residual_norm ...
!> \param predicted_residual_norm ...
!> \param response_curvature ...
!> \param training_reduced_target optional endpoint-local reduced training target
!> \param validation_reduced_target optional endpoint-local reduced validation target
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_reduced_secant_prediction( &
      rotation_hessian, response_metric, energy_response, training_rotation_step, &
      training_rotation_target, training_energy_target, validation_rotation_step, &
      validation_rotation_target, validation_energy_target, updated_rotation_hessian, ready, &
      step_overlap, training_response_capture, validation_quality, validation_alignment, &
      validation_curvature_ratio, validation_residual_norm, predicted_residual_norm, &
      response_curvature, training_reduced_target, validation_reduced_target)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: rotation_hessian, response_metric, &
                                                            energy_response
      REAL(KIND=dp), DIMENSION(:), INTENT(IN) :: training_rotation_step, training_rotation_target, &
         training_energy_target, validation_rotation_step, validation_rotation_target, &
         validation_energy_target
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: updated_rotation_hessian
      LOGICAL, INTENT(OUT)                               :: ready
      REAL(KIND=dp), INTENT(OUT) :: step_overlap, training_response_capture, validation_quality, &
         validation_alignment, validation_curvature_ratio, validation_residual_norm, &
         predicted_residual_norm, response_curvature
      REAL(KIND=dp), DIMENSION(:), INTENT(IN), OPTIONAL  :: training_reduced_target, &
                                                            validation_reduced_target

      INTEGER                                            :: i, j, nener, nrot
      LOGICAL                                            :: update_ready
      REAL(KIND=dp) :: block_floor, block_max, correction_norm, observed_curvature, &
         predicted_curvature, predicted_response_norm, training_norm, training_residual_norm, &
         updated_training_residual_norm, validation_norm, validation_residual_sq
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:) :: coordinate_scale, predicted_response, &
         predicted_validation_residual, q, training_residual, training_step, training_target, &
         validation_residual, validation_step, validation_target
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: reduced_hessian, updated_reduced_hessian

      nrot = SIZE(rotation_hessian, 1)
      nener = SIZE(energy_response, 1)
      CPASSERT(ALL(SHAPE(rotation_hessian) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(response_metric) == [nrot, nrot]))
      CPASSERT(SIZE(energy_response, 2) == nrot)
      CPASSERT(SIZE(training_rotation_step) == nrot)
      CPASSERT(SIZE(training_rotation_target) == nrot)
      CPASSERT(SIZE(training_energy_target) == nener)
      CPASSERT(SIZE(validation_rotation_step) == nrot)
      CPASSERT(SIZE(validation_rotation_target) == nrot)
      CPASSERT(SIZE(validation_energy_target) == nener)
      CPASSERT(ALL(SHAPE(updated_rotation_hessian) == [nrot, nrot]))
      CPASSERT(PRESENT(training_reduced_target) .EQV. PRESENT(validation_reduced_target))
      IF (PRESENT(training_reduced_target)) THEN
         CPASSERT(SIZE(training_reduced_target) == nrot)
         CPASSERT(SIZE(validation_reduced_target) == nrot)
      END IF

      updated_rotation_hessian(:, :) = rotation_hessian(:, :)
      ready = .FALSE.
      step_overlap = 0.0_dp
      training_response_capture = 0.0_dp
      validation_quality = 0.0_dp
      validation_alignment = 0.0_dp
      validation_curvature_ratio = 0.0_dp
      validation_residual_norm = 0.0_dp
      predicted_residual_norm = 0.0_dp
      response_curvature = 0.0_dp
      IF (nrot <= 0 .OR. nener <= 0) RETURN

      ALLOCATE (coordinate_scale(nrot), predicted_response(nrot), &
                predicted_validation_residual(nrot), q(nrot), reduced_hessian(nrot, nrot), &
                training_residual(nrot), training_step(nrot), training_target(nrot), &
                updated_reduced_hessian(nrot, nrot), validation_residual(nrot), &
                validation_step(nrot), validation_target(nrot))
      reduced_hessian(:, :) = rotation_hessian - response_metric
      reduced_hessian(:, :) = 0.5_dp*(reduced_hessian + TRANSPOSE(reduced_hessian))
      training_step(:) = training_rotation_step(:)
      validation_step(:) = validation_rotation_step(:)
      IF (PRESENT(training_reduced_target)) THEN
         training_target(:) = training_reduced_target
         validation_target(:) = validation_reduced_target
      ELSE
         training_target(:) = training_rotation_target + &
                              MATMUL(TRANSPOSE(energy_response), training_energy_target)
         validation_target(:) = validation_rotation_target + &
                                MATMUL(TRANSPOSE(energy_response), validation_energy_target)
      END IF

      block_max = MAXVAL(ABS([(reduced_hessian(i, i), i=1, nrot)]))
      IF (block_max > TINY(1.0_dp)) THEN
         block_floor = SQRT(EPSILON(1.0_dp))*block_max
         DO i = 1, nrot
            coordinate_scale(i) = SQRT(MAX(ABS(reduced_hessian(i, i)), block_floor))
         END DO
      ELSE
         coordinate_scale(:) = 1.0_dp
      END IF
      DO j = 1, nrot
         DO i = 1, nrot
            reduced_hessian(i, j) = reduced_hessian(i, j)/ &
                                    (coordinate_scale(i)*coordinate_scale(j))
         END DO
      END DO
      training_step(:) = coordinate_scale*training_step
      validation_step(:) = coordinate_scale*validation_step
      training_target(:) = training_target/coordinate_scale
      validation_target(:) = validation_target/coordinate_scale

      training_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(training_step, training_step)))
      validation_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(validation_step, validation_step)))
      IF (training_norm <= SQRT(EPSILON(1.0_dp)) .OR. &
          validation_norm <= SQRT(EPSILON(1.0_dp))) THEN
         DEALLOCATE (coordinate_scale, predicted_response, predicted_validation_residual, q, &
                     reduced_hessian, training_residual, training_step, training_target, &
                     updated_reduced_hessian, validation_residual, validation_step, validation_target)
         RETURN
      END IF
      q(:) = training_step/training_norm
      step_overlap = ABS(DOT_PRODUCT(q, validation_step))/validation_norm
      training_residual(:) = training_target - MATMUL(reduced_hessian, training_step)
      training_residual_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(training_residual, training_residual)))
      CALL qs_scf_kp_symmetric_secant_update( &
         reduced_hessian, training_step, training_target, 1.0_dp, updated_reduced_hessian, &
         update_ready, correction_norm, training_residual_norm, updated_training_residual_norm)
      IF (.NOT. update_ready) THEN
         DEALLOCATE (coordinate_scale, predicted_response, predicted_validation_residual, q, &
                     reduced_hessian, training_residual, training_step, training_target, &
                     updated_reduced_hessian, validation_residual, validation_step, validation_target)
         RETURN
      END IF
      response_curvature = DOT_PRODUCT( &
                           training_step, MATMUL(updated_reduced_hessian - reduced_hessian, &
                                                 training_step))/MAX(training_norm**2, EPSILON(1.0_dp))
      IF (training_residual_norm > EPSILON(training_residual_norm)) &
         training_response_capture = MIN(1.0_dp, MAX(0.0_dp, &
                                                     1.0_dp - updated_training_residual_norm/ &
                                                     training_residual_norm))

      validation_residual(:) = validation_target - MATMUL(reduced_hessian, validation_step)
      predicted_response(:) = MATMUL(updated_reduced_hessian - reduced_hessian, validation_step)
      predicted_validation_residual(:) = validation_residual - predicted_response
      validation_residual_sq = MAX(0.0_dp, DOT_PRODUCT(validation_residual, validation_residual))
      validation_residual_norm = SQRT(validation_residual_sq)
      predicted_residual_norm = SQRT(MAX(0.0_dp, &
                                         DOT_PRODUCT(predicted_validation_residual, &
                                                     predicted_validation_residual)))
      IF (validation_residual_sq > EPSILON(validation_residual_sq)) &
         validation_quality = 1.0_dp - predicted_residual_norm**2/validation_residual_sq
      predicted_response_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(predicted_response, predicted_response)))
      IF (validation_residual_norm > EPSILON(validation_residual_norm) .AND. &
          predicted_response_norm > EPSILON(predicted_response_norm)) &
         validation_alignment = DOT_PRODUCT(validation_residual, predicted_response)/ &
                                (validation_residual_norm*predicted_response_norm)
      predicted_curvature = DOT_PRODUCT(validation_step, predicted_response)/ &
                            MAX(validation_norm**2, EPSILON(1.0_dp))
      IF (ABS(predicted_curvature) > SQRT(EPSILON(1.0_dp))) THEN
         observed_curvature = DOT_PRODUCT(validation_step, validation_residual)/ &
                              MAX(validation_norm**2, EPSILON(1.0_dp))
         validation_curvature_ratio = observed_curvature/predicted_curvature
      END IF
      ready = update_ready .AND. step_overlap == step_overlap .AND. &
              training_response_capture == training_response_capture .AND. &
              validation_quality == validation_quality .AND. &
              validation_alignment == validation_alignment .AND. &
              validation_curvature_ratio == validation_curvature_ratio .AND. &
              validation_residual_norm == validation_residual_norm .AND. &
              predicted_residual_norm == predicted_residual_norm .AND. &
              response_curvature == response_curvature
      IF (ready) THEN
         DO j = 1, nrot
            DO i = 1, nrot
               updated_reduced_hessian(i, j) = updated_reduced_hessian(i, j)* &
                                               coordinate_scale(i)*coordinate_scale(j)
            END DO
         END DO
         updated_rotation_hessian(:, :) = updated_reduced_hessian + response_metric
         updated_rotation_hessian(:, :) = 0.5_dp* &
                                          (updated_rotation_hessian + &
                                           TRANSPOSE(updated_rotation_hessian))
      END IF
      DEALLOCATE (coordinate_scale, predicted_response, predicted_validation_residual, q, &
                  reduced_hessian, training_residual, training_step, training_target, &
                  updated_reduced_hessian, validation_residual, validation_step, validation_target)

   END SUBROUTINE qs_scf_kp_reduced_secant_prediction

! **************************************************************************************************
!> \brief Test whether two accepted coupled secants predict each other well enough to form a trial
!>        Hessian.  The bidirectional test separates a persistent physical response mode from a
!>        one-step fit before the mode is allowed into the line-search calibration.
!> \param forward_finite older secant produced a finite model of the newer secant
!> \param reverse_finite newer secant produced a finite model of the older secant
!> \param active_subspace rotations are restricted to the thermal Fermi subspace
!> \param residual_delta current fixed-N Mermin residual
!> \param forward_overlap scaled step overlap for the older-to-newer prediction
!> \param reverse_overlap scaled step overlap for the newer-to-older prediction
!> \param forward_capture training-response fraction represented by the older step
!> \param reverse_capture training-response fraction represented by the newer step
!> \param forward_quality fractional full-residual reduction on the newer secant
!> \param reverse_quality fractional full-residual reduction on the older secant
!> \param forward_energy_quality fractional energy-residual reduction on the newer secant
!> \param reverse_energy_quality fractional energy-residual reduction on the older secant
!> \param forward_alignment response alignment on the newer secant
!> \param reverse_alignment response alignment on the older secant
!> \param forward_curvature_ratio newer/older response curvature
!> \param reverse_curvature_ratio older/newer response curvature
!> \return whether the current-secanted rank-one coupled model may enter candidate calibration
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_coupled_prediction_consistent( &
      forward_finite, reverse_finite, active_subspace, residual_delta, &
      forward_overlap, reverse_overlap, forward_capture, reverse_capture, &
      forward_quality, reverse_quality, forward_energy_quality, reverse_energy_quality, &
      forward_alignment, reverse_alignment, forward_curvature_ratio, reverse_curvature_ratio) &
      RESULT(consistent)
      LOGICAL, INTENT(IN)                                :: forward_finite, reverse_finite, &
                                                            active_subspace
      REAL(KIND=dp), INTENT(IN) :: residual_delta, forward_overlap, reverse_overlap, &
         forward_capture, reverse_capture, forward_quality, reverse_quality, &
         forward_energy_quality, reverse_energy_quality, forward_alignment, reverse_alignment, &
         forward_curvature_ratio, reverse_curvature_ratio
      LOGICAL                                            :: consistent

      consistent = forward_finite .AND. reverse_finite .AND. active_subspace .AND. &
                   residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
                   forward_overlap >= ot_kp_schur_prediction_overlap_min .AND. &
                   reverse_overlap >= ot_kp_schur_prediction_overlap_min .AND. &
                   forward_capture >= ot_kp_schur_prediction_capture_min .AND. &
                   reverse_capture >= ot_kp_schur_prediction_capture_min .AND. &
                   forward_quality >= ot_kp_schur_prediction_quality_min .AND. &
                   reverse_quality >= ot_kp_schur_prediction_quality_min .AND. &
                   forward_energy_quality >= ot_kp_schur_prediction_energy_quality_min .AND. &
                   reverse_energy_quality >= ot_kp_schur_prediction_energy_quality_min .AND. &
                   forward_alignment >= ot_kp_schur_prediction_alignment_min .AND. &
                   reverse_alignment >= ot_kp_schur_prediction_alignment_min .AND. &
                   forward_curvature_ratio >= ot_kp_schur_prediction_curvature_ratio_min .AND. &
                   reverse_curvature_ratio >= ot_kp_schur_prediction_curvature_ratio_min .AND. &
                   forward_curvature_ratio <= ot_kp_schur_prediction_curvature_ratio_max .AND. &
                   reverse_curvature_ratio <= ot_kp_schur_prediction_curvature_ratio_max

   END FUNCTION qs_scf_kp_coupled_prediction_consistent

! **************************************************************************************************
!> \brief Update the reduced rotation Schur block directly from coupled fixed-N secants.
!>
!>        For H=[A,-B^T;-B,E], an accepted coupled secant (s_R,s_e)->(y_R,y_e)
!>        implies (A-B^T E^-1 B)s_R = y_R+B^T E^-1 y_e.  Applying the multisecant update to this
!>        reduced relation avoids fitting a poorly conditioned full cross block before eliminating
!>        the fixed-N auxiliary-energy variables.
!> \param rotation_hessian ...
!> \param energy_hessian ...
!> \param energy_cross ...
!> \param rotation_steps ...
!> \param rotation_targets measured raw complex rotation-gradient changes
!> \param energy_targets ...
!> \param weight ...
!> \param updated_rotation_hessian ...
!> \param ready ...
!> \param independence ...
!> \param compatibility ...
!> \param correction_norm ...
!> \param residual_norm ...
!> \param updated_residual_norm ...
!> \param correction_ratio ...
!> \param energy_response optional already projected E^-1 B response defining the fixed-N gauge
!> \param response_metric optional fixed-N metric Gram matrix R^T M R for energy_response R
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_coupled_reduced_multisecant_update( &
      rotation_hessian, energy_hessian, energy_cross, rotation_steps, rotation_targets, &
      energy_targets, weight, updated_rotation_hessian, ready, independence, compatibility, &
      correction_norm, residual_norm, updated_residual_norm, correction_ratio, energy_response, &
      response_metric)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: rotation_hessian, energy_hessian, &
                                                            energy_cross, rotation_steps, &
                                                            rotation_targets, energy_targets
      REAL(KIND=dp), INTENT(IN)                          :: weight
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: updated_rotation_hessian
      LOGICAL, INTENT(OUT)                               :: ready
      REAL(KIND=dp), INTENT(OUT)                         :: independence, compatibility, &
                                                            correction_norm, residual_norm, &
                                                            updated_residual_norm, correction_ratio
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN), &
         OPTIONAL                                        :: energy_response, response_metric

      INTEGER                                            :: info, nener, nrot, nsec
      INTEGER, ALLOCATABLE, DIMENSION(:)                 :: ipiv
      REAL(KIND=dp)                                      :: reference_norm
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :) :: analytic_cross, analytic_energy, &
         analytic_metric, analytic_response, analytic_schur, reduced_targets, rhs, updated_schur

      nrot = SIZE(rotation_hessian, 1)
      nener = SIZE(energy_hessian, 1)
      nsec = SIZE(rotation_steps, 2)
      CPASSERT(ALL(SHAPE(rotation_hessian) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(energy_hessian) == [nener, nener]))
      CPASSERT(ALL(SHAPE(energy_cross) == [nener, nrot]))
      CPASSERT(SIZE(rotation_steps, 1) == nrot)
      CPASSERT(ALL(SHAPE(rotation_targets) == [nrot, nsec]))
      CPASSERT(ALL(SHAPE(energy_targets) == [nener, nsec]))
      CPASSERT(ALL(SHAPE(updated_rotation_hessian) == [nrot, nrot]))
      IF (PRESENT(energy_response)) THEN
         CPASSERT(ALL(SHAPE(energy_response) == [nener, nrot]))
      END IF
      IF (PRESENT(response_metric)) THEN
         CPASSERT(PRESENT(energy_response))
         CPASSERT(ALL(SHAPE(response_metric) == [nrot, nrot]))
      END IF

      updated_rotation_hessian(:, :) = rotation_hessian(:, :)
      ready = .FALSE.
      independence = 0.0_dp
      compatibility = 0.0_dp
      correction_norm = 0.0_dp
      residual_norm = 0.0_dp
      updated_residual_norm = 0.0_dp
      correction_ratio = 0.0_dp
      IF (nrot <= 0 .OR. nener <= 0 .OR. nsec <= 0) RETURN

      ALLOCATE (ipiv(nener), analytic_cross(nener, nrot), analytic_energy(nener, nener), &
                analytic_metric(nrot, nrot), analytic_response(nener, nrot), &
                analytic_schur(nrot, nrot), reduced_targets(nrot, nsec), &
                rhs(nener, nrot), updated_schur(nrot, nrot))
      analytic_energy(:, :) = 0.5_dp*(energy_hessian + TRANSPOSE(energy_hessian))
      analytic_cross(:, :) = energy_cross(:, :)
      info = 0
      IF (PRESENT(energy_response)) THEN
         analytic_response(:, :) = energy_response
         analytic_cross(:, :) = MATMUL(analytic_energy, energy_response)
      ELSE
         rhs(:, :) = analytic_cross(:, :)
         CALL dgesv(nener, nrot, analytic_energy, nener, ipiv, rhs, nener, info)
         IF (info == 0) analytic_response(:, :) = rhs(:, :)
      END IF
      IF (info == 0) THEN
         analytic_metric(:, :) = MATMUL(TRANSPOSE(analytic_cross), analytic_response)
         analytic_metric(:, :) = 0.5_dp*(analytic_metric + TRANSPOSE(analytic_metric))
         IF (PRESENT(response_metric)) &
            analytic_metric(:, :) = 0.5_dp*(response_metric + TRANSPOSE(response_metric))
         analytic_schur(:, :) = rotation_hessian - analytic_metric
         analytic_schur(:, :) = 0.5_dp*(analytic_schur + TRANSPOSE(analytic_schur))
         reduced_targets(:, :) = rotation_targets + &
                                 MATMUL(TRANSPOSE(analytic_response), energy_targets)
         CALL qs_scf_kp_symmetric_multisecant_update( &
            analytic_schur, rotation_steps, reduced_targets, weight, updated_schur, ready, &
            independence, compatibility, correction_norm, residual_norm, updated_residual_norm)
         reference_norm = SQRT(MAX(0.0_dp, SUM(analytic_schur**2)))
         correction_ratio = correction_norm/MAX(reference_norm, EPSILON(1.0_dp))
         IF (ready) THEN
            updated_rotation_hessian(:, :) = updated_schur + analytic_metric
            updated_rotation_hessian(:, :) = 0.5_dp* &
                                             (updated_rotation_hessian + &
                                              TRANSPOSE(updated_rotation_hessian))
            ready = ALL(updated_rotation_hessian == updated_rotation_hessian) .AND. &
                    correction_ratio == correction_ratio
         END IF
      END IF
      IF (.NOT. ready) updated_rotation_hessian(:, :) = rotation_hessian(:, :)
      DEALLOCATE (ipiv, analytic_cross, analytic_energy, analytic_metric, analytic_response, &
                  analytic_schur, reduced_targets, rhs, updated_schur)

   END SUBROUTINE qs_scf_kp_coupled_reduced_multisecant_update

! **************************************************************************************************
!> \brief Solve a symmetric rotation model in the measured low-rank secant subspace.
!>
!>        The supplied modes are orthonormalized before projecting the Hessian and gradient.  The
!>        coordinate curvature floor is projected into the same subspace; a uniform modal shift
!>        makes the projected Hessian no softer than that projected floor.  The returned direction
!>        therefore contains no component outside the measured secant span.
!> \param hessian symmetric full-space model
!> \param gradient full-space right-hand side
!> \param modes measured full-space secant modes
!> \param coordinate_floor nonnegative full-space diagonal curvature floor
!> \param step low-rank solution in the full coordinate space
!> \param ready whether a finite descent direction was obtained
!> \param rank numerical rank of the measured subspace
!> \param modal_shift uniform curvature shift applied in the orthonormal modal basis
!> \param projected_residual relative residual of the regularized projected solve
!> \param gradient_fraction fraction of the full gradient represented by the measured subspace
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_reduced_subspace_step(hessian, gradient, modes, coordinate_floor, step, &
                                              ready, rank, modal_shift, projected_residual, &
                                              gradient_fraction)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: hessian
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: gradient
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: modes
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: coordinate_floor
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: step
      LOGICAL, INTENT(OUT)                               :: ready
      INTEGER, INTENT(OUT)                               :: rank
      REAL(KIND=dp), INTENT(OUT)                         :: modal_shift, projected_residual, &
                                                            gradient_fraction

      INTEGER                                            :: i, info, j, mode_count, nrot, pass
      INTEGER, ALLOCATABLE, DIMENSION(:)                 :: ipiv
      REAL(KIND=dp) :: eigenvalue_min, gradient_norm, mode_norm, mode_scale, numerical_floor, &
         projected_gradient_norm, residual_norm
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: coefficients, projected_gradient, &
                                                            projected_solve_residual, work_mode
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: floor_projected, hessian_projected, &
                                                            hessian_solve, orthonormal_modes

      nrot = SIZE(gradient)
      mode_count = SIZE(modes, 2)
      CPASSERT(ALL(SHAPE(hessian) == [nrot, nrot]))
      CPASSERT(SIZE(modes, 1) == nrot)
      CPASSERT(SIZE(coordinate_floor) == nrot)
      CPASSERT(SIZE(step) == nrot)

      step(:) = 0.0_dp
      ready = .FALSE.
      rank = 0
      modal_shift = 0.0_dp
      projected_residual = 0.0_dp
      gradient_fraction = 0.0_dp
      IF (nrot <= 0 .OR. mode_count <= 0) RETURN

      ALLOCATE (orthonormal_modes(nrot, mode_count), work_mode(nrot))
      orthonormal_modes(:, :) = 0.0_dp
      mode_scale = 0.0_dp
      DO j = 1, mode_count
         mode_scale = MAX(mode_scale, SQRT(MAX(0.0_dp, DOT_PRODUCT(modes(:, j), modes(:, j)))))
      END DO
      IF (mode_scale <= TINY(1.0_dp)) THEN
         DEALLOCATE (orthonormal_modes, work_mode)
         RETURN
      END IF

      DO j = 1, mode_count
         work_mode(:) = modes(:, j)
         DO pass = 1, 2
            DO i = 1, rank
               work_mode(:) = work_mode - &
                              DOT_PRODUCT(orthonormal_modes(:, i), work_mode)* &
                              orthonormal_modes(:, i)
            END DO
         END DO
         mode_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(work_mode, work_mode)))
         IF (mode_norm <= 64.0_dp*SQRT(EPSILON(1.0_dp))*mode_scale) CYCLE
         rank = rank + 1
         orthonormal_modes(:, rank) = work_mode/mode_norm
      END DO
      IF (rank <= 0) THEN
         DEALLOCATE (orthonormal_modes, work_mode)
         RETURN
      END IF

      ALLOCATE (coefficients(rank), projected_gradient(rank), projected_solve_residual(rank), &
                ipiv(rank), floor_projected(rank, rank), hessian_projected(rank, rank), &
                hessian_solve(rank, rank))
      hessian_projected(:, :) = MATMUL(TRANSPOSE(orthonormal_modes(:, 1:rank)), &
                                       MATMUL(0.5_dp*(hessian + TRANSPOSE(hessian)), &
                                              orthonormal_modes(:, 1:rank)))
      floor_projected(:, :) = MATMUL(TRANSPOSE(orthonormal_modes(:, 1:rank)), &
                                     SPREAD(MAX(0.0_dp, coordinate_floor), 2, rank)* &
                                     orthonormal_modes(:, 1:rank))
      hessian_projected(:, :) = 0.5_dp*(hessian_projected + TRANSPOSE(hessian_projected))
      floor_projected(:, :) = 0.5_dp*(floor_projected + TRANSPOSE(floor_projected))
      hessian_solve(:, :) = hessian_projected - floor_projected
      IF (rank == 1) THEN
         eigenvalue_min = hessian_solve(1, 1)
      ELSE IF (rank == 2) THEN
         eigenvalue_min = 0.5_dp*(hessian_solve(1, 1) + hessian_solve(2, 2) - &
                                  SQRT((hessian_solve(1, 1) - hessian_solve(2, 2))**2 + &
                                       4.0_dp*hessian_solve(1, 2)**2))
      ELSE
         eigenvalue_min = MINVAL([ &
                                 (hessian_solve(i, i) - SUM(ABS(hessian_solve(i, :))) + &
                                  ABS(hessian_solve(i, i)), i=1, rank)])
      END IF
      numerical_floor = 64.0_dp*EPSILON(1.0_dp)* &
                        MAX(1.0_dp, MAXVAL(ABS(hessian_projected)), &
                            MAXVAL(ABS(floor_projected)))
      modal_shift = MAX(0.0_dp, numerical_floor - eigenvalue_min)
      hessian_solve(:, :) = hessian_projected(:, :)
      DO i = 1, rank
         hessian_solve(i, i) = hessian_solve(i, i) + modal_shift
      END DO
      projected_gradient(:) = MATMUL(TRANSPOSE(orthonormal_modes(:, 1:rank)), gradient)
      coefficients(:) = projected_gradient(:)
      CALL dgesv(rank, 1, hessian_solve, rank, ipiv, coefficients, rank, info)
      IF (info == 0 .AND. ALL(coefficients == coefficients)) THEN
         step(:) = MATMUL(orthonormal_modes(:, 1:rank), coefficients)
         projected_solve_residual(:) = &
            MATMUL(hessian_projected, coefficients) + modal_shift*coefficients - &
            projected_gradient
         projected_gradient_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(projected_gradient, &
                                                                projected_gradient)))
         residual_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(projected_solve_residual, &
                                                      projected_solve_residual)))
         projected_residual = residual_norm/MAX(projected_gradient_norm, EPSILON(1.0_dp))
         gradient_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(gradient, gradient)))
         gradient_fraction = projected_gradient_norm/MAX(gradient_norm, EPSILON(1.0_dp))
         ready = DOT_PRODUCT(gradient, step) > EPSILON(DOT_PRODUCT(gradient, step)) .AND. &
                 ALL(step == step) .AND. projected_residual == projected_residual .AND. &
                 gradient_fraction == gradient_fraction
      END IF
      IF (.NOT. ready) step(:) = 0.0_dp
      DEALLOCATE (coefficients, projected_gradient, projected_solve_residual, ipiv, &
                  floor_projected, hessian_projected, hessian_solve, orthonormal_modes, work_mode)

   END SUBROUTINE qs_scf_kp_reduced_subspace_step

! **************************************************************************************************
!> \brief Replace the component of a reference step in a measured low-rank subspace.
!>
!>        The reference component orthogonal to the measured modes is held fixed.  The projected
!>        solve includes the Hessian coupling to that complement.  Any curvature shift is centered
!>        on the reference component, so regularization damps only the proposed correction and
!>        cannot pull an accepted minimizer-history component back toward zero.
!> \param hessian symmetric full-space model
!> \param gradient full-space right-hand side
!> \param modes measured full-space secant modes
!> \param coordinate_floor nonnegative full-space diagonal curvature floor
!> \param reference_step established full-space candidate
!> \param step candidate with its measured-subspace component replaced
!> \param ready whether a finite descent direction was obtained
!> \param rank numerical rank of the measured subspace
!> \param modal_shift uniform curvature shift applied in the orthonormal modal basis
!> \param projected_residual relative residual of the regularized projected KKT equation
!> \param reference_residual_ratio projected residual of the reference step relative to the
!>        projected right-hand side after fixing its orthogonal complement
!> \param driving_fraction fraction of the reference residual in the measured span
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_reduced_subspace_replacement_step( &
      hessian, gradient, modes, coordinate_floor, reference_step, step, ready, rank, modal_shift, &
      projected_residual, reference_residual_ratio, driving_fraction)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: hessian
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: gradient
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: modes
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: coordinate_floor, reference_step
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: step
      LOGICAL, INTENT(OUT)                               :: ready
      INTEGER, INTENT(OUT)                               :: rank
      REAL(KIND=dp), INTENT(OUT)                         :: modal_shift, projected_residual, &
                                                            reference_residual_ratio, &
                                                            driving_fraction

      INTEGER                                            :: i, info, j, mode_count, nrot, pass
      INTEGER, ALLOCATABLE, DIMENSION(:)                 :: ipiv
      REAL(KIND=dp) :: complement_residual_norm, eigenvalue_min, mode_norm, mode_scale, &
         numerical_floor, projected_gradient_norm, reference_projected_residual_norm, &
         reference_residual_norm, residual_norm
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:) :: coefficients, complement_residual, &
         projected_gradient, projected_solve_residual, reference_complement, &
         reference_projected_residual, reference_residual, work_mode
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: floor_projected, hessian_projected, &
                                                            hessian_solve, hessian_symmetric, &
                                                            orthonormal_modes

      nrot = SIZE(gradient)
      mode_count = SIZE(modes, 2)
      CPASSERT(ALL(SHAPE(hessian) == [nrot, nrot]))
      CPASSERT(SIZE(modes, 1) == nrot)
      CPASSERT(SIZE(coordinate_floor) == nrot)
      CPASSERT(SIZE(reference_step) == nrot)
      CPASSERT(SIZE(step) == nrot)

      step(:) = 0.0_dp
      ready = .FALSE.
      rank = 0
      modal_shift = 0.0_dp
      projected_residual = 0.0_dp
      reference_residual_ratio = 0.0_dp
      driving_fraction = 0.0_dp
      IF (nrot <= 0 .OR. mode_count <= 0) RETURN

      ALLOCATE (hessian_symmetric(nrot, nrot), orthonormal_modes(nrot, mode_count), work_mode(nrot))
      hessian_symmetric(:, :) = 0.5_dp*(hessian + TRANSPOSE(hessian))
      orthonormal_modes(:, :) = 0.0_dp
      mode_scale = 0.0_dp
      DO j = 1, mode_count
         mode_scale = MAX(mode_scale, SQRT(MAX(0.0_dp, DOT_PRODUCT(modes(:, j), modes(:, j)))))
      END DO
      IF (mode_scale <= TINY(1.0_dp)) THEN
         DEALLOCATE (hessian_symmetric, orthonormal_modes, work_mode)
         RETURN
      END IF

      DO j = 1, mode_count
         work_mode(:) = modes(:, j)
         DO pass = 1, 2
            DO i = 1, rank
               work_mode(:) = work_mode - &
                              DOT_PRODUCT(orthonormal_modes(:, i), work_mode)* &
                              orthonormal_modes(:, i)
            END DO
         END DO
         mode_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(work_mode, work_mode)))
         IF (mode_norm <= 64.0_dp*SQRT(EPSILON(1.0_dp))*mode_scale) CYCLE
         rank = rank + 1
         orthonormal_modes(:, rank) = work_mode/mode_norm
      END DO
      IF (rank <= 0) THEN
         DEALLOCATE (hessian_symmetric, orthonormal_modes, work_mode)
         RETURN
      END IF

      ALLOCATE (coefficients(rank), complement_residual(nrot), projected_gradient(rank), &
                projected_solve_residual(rank), reference_complement(nrot), &
                reference_projected_residual(rank), reference_residual(nrot), ipiv(rank), &
                floor_projected(rank, rank), hessian_projected(rank, rank), hessian_solve(rank, rank))
      reference_complement(:) = reference_step - &
                                MATMUL(orthonormal_modes(:, 1:rank), &
                                       MATMUL(TRANSPOSE(orthonormal_modes(:, 1:rank)), reference_step))
      complement_residual(:) = gradient - MATMUL(hessian_symmetric, reference_complement)
      projected_gradient(:) = MATMUL(TRANSPOSE(orthonormal_modes(:, 1:rank)), complement_residual)
      projected_gradient_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(projected_gradient, projected_gradient)))
      complement_residual_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(complement_residual, &
                                                              complement_residual)))
      IF (projected_gradient_norm <= 64.0_dp*EPSILON(1.0_dp)* &
          MAX(1.0_dp, complement_residual_norm)) THEN
         DEALLOCATE (coefficients, complement_residual, projected_gradient, &
                     projected_solve_residual, reference_complement, reference_projected_residual, &
                     reference_residual, ipiv, floor_projected, hessian_projected, hessian_solve, &
                     hessian_symmetric, orthonormal_modes, work_mode)
         RETURN
      END IF
      hessian_projected(:, :) = MATMUL(TRANSPOSE(orthonormal_modes(:, 1:rank)), &
                                       MATMUL(hessian_symmetric, orthonormal_modes(:, 1:rank)))
      floor_projected(:, :) = MATMUL(TRANSPOSE(orthonormal_modes(:, 1:rank)), &
                                     SPREAD(MAX(0.0_dp, coordinate_floor), 2, rank)* &
                                     orthonormal_modes(:, 1:rank))
      hessian_projected(:, :) = 0.5_dp*(hessian_projected + TRANSPOSE(hessian_projected))
      floor_projected(:, :) = 0.5_dp*(floor_projected + TRANSPOSE(floor_projected))
      hessian_solve(:, :) = hessian_projected - floor_projected
      IF (rank == 1) THEN
         eigenvalue_min = hessian_solve(1, 1)
      ELSE IF (rank == 2) THEN
         eigenvalue_min = 0.5_dp*(hessian_solve(1, 1) + hessian_solve(2, 2) - &
                                  SQRT((hessian_solve(1, 1) - hessian_solve(2, 2))**2 + &
                                       4.0_dp*hessian_solve(1, 2)**2))
      ELSE
         eigenvalue_min = MINVAL([ &
                                 (hessian_solve(i, i) - SUM(ABS(hessian_solve(i, :))) + &
                                  ABS(hessian_solve(i, i)), i=1, rank)])
      END IF
      numerical_floor = 64.0_dp*EPSILON(1.0_dp)* &
                        MAX(1.0_dp, MAXVAL(ABS(hessian_projected)), &
                            MAXVAL(ABS(floor_projected)))
      modal_shift = MAX(0.0_dp, numerical_floor - eigenvalue_min)
      hessian_solve(:, :) = hessian_projected(:, :)
      DO i = 1, rank
         hessian_solve(i, i) = hessian_solve(i, i) + modal_shift
      END DO

      reference_projected_residual(:) = MATMUL(TRANSPOSE(orthonormal_modes(:, 1:rank)), &
                                               gradient - MATMUL(hessian_symmetric, reference_step))
      reference_projected_residual_norm = SQRT(MAX(0.0_dp, &
                                                   DOT_PRODUCT(reference_projected_residual, &
                                                               reference_projected_residual)))
      reference_residual_ratio = reference_projected_residual_norm/ &
                                 MAX(projected_gradient_norm, EPSILON(1.0_dp))
      reference_residual(:) = gradient - MATMUL(hessian_symmetric, reference_step)
      reference_residual_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(reference_residual, &
                                                             reference_residual)))
      driving_fraction = reference_projected_residual_norm/ &
                         MAX(reference_residual_norm, EPSILON(1.0_dp))
      IF (reference_projected_residual_norm <= 64.0_dp*EPSILON(1.0_dp)* &
          MAX(1.0_dp, reference_residual_norm)) THEN
         DEALLOCATE (coefficients, complement_residual, projected_gradient, &
                     projected_solve_residual, reference_complement, reference_projected_residual, &
                     reference_residual, ipiv, floor_projected, hessian_projected, hessian_solve, &
                     hessian_symmetric, orthonormal_modes, work_mode)
         RETURN
      END IF
      coefficients(:) = reference_projected_residual(:)
      CALL dgesv(rank, 1, hessian_solve, rank, ipiv, coefficients, rank, info)
      IF (info == 0 .AND. ALL(coefficients == coefficients)) THEN
         step(:) = reference_step + MATMUL(orthonormal_modes(:, 1:rank), coefficients)
         projected_solve_residual(:) = MATMUL(hessian_projected, coefficients) + &
                                       modal_shift*coefficients - reference_projected_residual
         residual_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(projected_solve_residual, &
                                                      projected_solve_residual)))
         projected_residual = residual_norm/ &
                              MAX(reference_projected_residual_norm, EPSILON(1.0_dp))
         ready = DOT_PRODUCT(reference_projected_residual, coefficients) > &
                 EPSILON(DOT_PRODUCT(reference_projected_residual, coefficients)) .AND. &
                 DOT_PRODUCT(gradient, step) > EPSILON(DOT_PRODUCT(gradient, step)) .AND. &
                 ALL(step == step) .AND. projected_residual == projected_residual .AND. &
                 reference_residual_ratio == reference_residual_ratio .AND. &
                 driving_fraction == driving_fraction
      END IF
      IF (.NOT. ready) step(:) = 0.0_dp
      DEALLOCATE (coefficients, complement_residual, projected_gradient, projected_solve_residual, &
                  reference_complement, reference_projected_residual, reference_residual, ipiv, &
                  floor_projected, hessian_projected, hessian_solve, hessian_symmetric, &
                  orthonormal_modes, work_mode)

   END SUBROUTINE qs_scf_kp_reduced_subspace_replacement_step

! **************************************************************************************************
!> \brief Build a sign-aware step for an indefinite reduced Schur model.
!>
!>        Positive modes use the ordinary inverse curvature. Negative modes use the absolute
!>        curvature only as a search metric, while their signed curvature remains in the Mermin
!>        model. Their common scale is the largest value for which the predicted reduced fixed-N
!>        residual is no worse than both the current residual and a supplied reference candidate.
!> \param hessian signed symmetric reduced Schur Hessian
!> \param gradient reduced fixed-N gradient/right-hand side
!> \param coordinate_floor nonnegative curvature floor in the original coordinates
!> \param reference_step established candidate used as the residual-quality reference
!> \param step residual-balanced sign-aware step
!> \param ready whether a finite descent step satisfying the residual bound was found
!> \param negative_scale common scale retained for negative-curvature modes
!> \param negative_gradient_fraction gradient fraction carried by negative modes
!> \param predicted_residual_ratio predicted step residual divided by the current residual
!> \param reference_residual_ratio corresponding ratio for the reference candidate
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_indefinite_residual_balanced_step( &
      hessian, gradient, coordinate_floor, reference_step, step, ready, negative_scale, &
      negative_gradient_fraction, predicted_residual_ratio, reference_residual_ratio)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: hessian
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: gradient, coordinate_floor, &
                                                            reference_step
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: step
      LOGICAL, INTENT(OUT)                               :: ready
      REAL(KIND=dp), INTENT(OUT)                         :: negative_scale, &
                                                            negative_gradient_fraction, &
                                                            predicted_residual_ratio, &
                                                            reference_residual_ratio

      INTEGER                                            :: i, nrot
      REAL(KIND=dp) :: discriminant, gradient_norm_sq, mode_floor, negative_gradient_norm_sq, &
         residual_a, residual_b, residual_c, residual_norm_sq, target_residual_norm_sq, tolerance
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:) :: coordinate_scale, eval, gradient_scaled, &
         mode_gradient, mode_step_negative, mode_step_positive, reference_residual, &
         reference_step_scaled, residual_delta, residual_positive, residual_trial, step_scaled
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: hessian_modes, hessian_scaled

      nrot = SIZE(gradient)
      CPASSERT(ALL(SHAPE(hessian) == [nrot, nrot]))
      CPASSERT(SIZE(coordinate_floor) == nrot)
      CPASSERT(SIZE(reference_step) == nrot)
      CPASSERT(SIZE(step) == nrot)

      step(:) = 0.0_dp
      ready = .FALSE.
      negative_scale = 0.0_dp
      negative_gradient_fraction = 0.0_dp
      predicted_residual_ratio = 1.0_dp
      reference_residual_ratio = 1.0_dp
      IF (nrot <= 0) RETURN

      ALLOCATE (coordinate_scale(nrot), eval(nrot), gradient_scaled(nrot), &
                hessian_modes(nrot, nrot), hessian_scaled(nrot, nrot), mode_gradient(nrot), &
                mode_step_negative(nrot), mode_step_positive(nrot), reference_residual(nrot), &
                reference_step_scaled(nrot), residual_delta(nrot), residual_positive(nrot), &
                residual_trial(nrot), step_scaled(nrot))
      DO i = 1, nrot
         coordinate_scale(i) = SQRT(MAX(ABS(hessian(i, i)), MAX(0.0_dp, coordinate_floor(i)), &
                                        SQRT(EPSILON(1.0_dp))*MAX(1.0_dp, ABS(hessian(i, i)))))
      END DO
      DO i = 1, nrot
         hessian_scaled(i, :) = hessian(i, :)/(coordinate_scale(i)*coordinate_scale(:))
      END DO
      hessian_scaled(:, :) = 0.5_dp*(hessian_scaled + TRANSPOSE(hessian_scaled))
      gradient_scaled(:) = gradient/coordinate_scale
      reference_step_scaled(:) = coordinate_scale*reference_step
      gradient_norm_sq = MAX(0.0_dp, DOT_PRODUCT(gradient_scaled, gradient_scaled))
      IF (gradient_norm_sq <= EPSILON(gradient_norm_sq)) THEN
         DEALLOCATE (coordinate_scale, eval, gradient_scaled, hessian_modes, hessian_scaled, &
                     mode_gradient, mode_step_negative, mode_step_positive, reference_residual, &
                     reference_step_scaled, residual_delta, residual_positive, residual_trial, &
                     step_scaled)
         RETURN
      END IF

      hessian_modes(:, :) = hessian_scaled
      CALL diamat_all(hessian_modes, eval)
      mode_gradient(:) = MATMUL(TRANSPOSE(hessian_modes), gradient_scaled)
      mode_step_positive(:) = 0.0_dp
      mode_step_negative(:) = 0.0_dp
      negative_gradient_norm_sq = 0.0_dp
      DO i = 1, nrot
         mode_floor = DOT_PRODUCT(hessian_modes(:, i)**2, &
                                  MAX(0.0_dp, coordinate_floor)/coordinate_scale**2)
         mode_floor = MAX(mode_floor, 64.0_dp*EPSILON(1.0_dp)* &
                          MAX(1.0_dp, MAXVAL(ABS(eval))))
         IF (eval(i) >= 0.0_dp) THEN
            mode_step_positive(i) = mode_gradient(i)/MAX(eval(i), mode_floor)
         ELSE
            mode_step_negative(i) = mode_gradient(i)/MAX(ABS(eval(i)), mode_floor)
            negative_gradient_norm_sq = negative_gradient_norm_sq + mode_gradient(i)**2
         END IF
      END DO
      negative_gradient_fraction = SQRT(MAX(0.0_dp, negative_gradient_norm_sq/gradient_norm_sq))

      step_scaled(:) = MATMUL(hessian_modes, mode_step_positive)
      residual_positive(:) = gradient_scaled - MATMUL(hessian_scaled, step_scaled)
      residual_delta(:) = -MATMUL(hessian_scaled, MATMUL(hessian_modes, mode_step_negative))
      reference_residual(:) = gradient_scaled - &
                              MATMUL(hessian_scaled, reference_step_scaled)
      residual_norm_sq = MAX(0.0_dp, DOT_PRODUCT(residual_positive, residual_positive))
      target_residual_norm_sq = MIN(gradient_norm_sq, &
                                    MAX(0.0_dp, DOT_PRODUCT(reference_residual, &
                                                            reference_residual)))
      reference_residual_ratio = SQRT(MAX(0.0_dp, DOT_PRODUCT(reference_residual, &
                                                              reference_residual))/ &
                                      gradient_norm_sq)
      tolerance = 256.0_dp*EPSILON(1.0_dp)*MAX(1.0_dp, gradient_norm_sq, &
                                               target_residual_norm_sq)
      IF (residual_norm_sq > target_residual_norm_sq + tolerance) THEN
         DEALLOCATE (coordinate_scale, eval, gradient_scaled, hessian_modes, hessian_scaled, &
                     mode_gradient, mode_step_negative, mode_step_positive, reference_residual, &
                     reference_step_scaled, residual_delta, residual_positive, residual_trial, &
                     step_scaled)
         RETURN
      END IF

      residual_a = MAX(0.0_dp, DOT_PRODUCT(residual_delta, residual_delta))
      residual_b = DOT_PRODUCT(residual_positive, residual_delta)
      residual_c = residual_norm_sq - target_residual_norm_sq
      IF (negative_gradient_norm_sq > EPSILON(negative_gradient_norm_sq) .AND. &
          residual_a > EPSILON(residual_a)) THEN
         discriminant = residual_b**2 - residual_a*residual_c
         IF (discriminant >= -tolerance) &
            negative_scale = MIN(1.0_dp, MAX(0.0_dp, &
                                             (-residual_b + SQRT(MAX(0.0_dp, discriminant)))/residual_a))
      END IF
      IF (negative_gradient_fraction > SQRT(EPSILON(1.0_dp)) .AND. &
          negative_scale <= SQRT(EPSILON(1.0_dp))) THEN
         DEALLOCATE (coordinate_scale, eval, gradient_scaled, hessian_modes, hessian_scaled, &
                     mode_gradient, mode_step_negative, mode_step_positive, reference_residual, &
                     reference_step_scaled, residual_delta, residual_positive, residual_trial, &
                     step_scaled)
         RETURN
      END IF

      step_scaled(:) = MATMUL(hessian_modes, &
                              mode_step_positive + negative_scale*mode_step_negative)
      residual_trial(:) = gradient_scaled - MATMUL(hessian_scaled, step_scaled)
      predicted_residual_ratio = SQRT(MAX(0.0_dp, DOT_PRODUCT(residual_trial, &
                                                              residual_trial))/gradient_norm_sq)
      step(:) = step_scaled/coordinate_scale
      ready = DOT_PRODUCT(gradient, step) > EPSILON(DOT_PRODUCT(gradient, step)) .AND. &
              predicted_residual_ratio <= MIN(1.0_dp, reference_residual_ratio) + &
              256.0_dp*EPSILON(1.0_dp) .AND. &
              ALL(step == step) .AND. negative_scale == negative_scale .AND. &
              predicted_residual_ratio == predicted_residual_ratio
      IF (.NOT. ready) step(:) = 0.0_dp
      DEALLOCATE (coordinate_scale, eval, gradient_scaled, hessian_modes, hessian_scaled, &
                  mode_gradient, mode_step_negative, mode_step_positive, reference_residual, &
                  reference_step_scaled, residual_delta, residual_positive, residual_trial, &
                  step_scaled)

   END SUBROUTINE qs_scf_kp_indefinite_residual_balanced_step

! **************************************************************************************************
!> \brief Minimize a residual in the span of paired measured step/response modes.
!>
!>        Each column pair (S(:,j),Y(:,j)) represents an accepted measured map Y=H*S.  Solving
!>        min_c ||r-Y*c||_W and returning S*c uses only observed response in the accepted subspace;
!>        no full-space Hessian extrapolation enters the residual prediction.  The diagonal metric
!>        W separates thermally active/gap rotations from occupation-gauge components.
!> \param residual current residual vector
!> \param modes accepted coordinate steps S
!> \param targets corresponding measured residual changes Y
!> \param weights nonnegative diagonal residual metric W
!> \param step least-squares coordinate correction in span(S)
!> \param residual_reduction predicted residual component Y*c removed by step
!> \param ready whether the measured correction strictly lowers the residual norm
!> \param rank number of nonzero measured target columns
!> \param residual_ratio predicted residual norm after the correction relative to the input norm
!> \param captured_fraction fraction of the residual norm captured by the measured target span
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_measured_residual_subspace_step( &
      residual, modes, targets, weights, step, residual_reduction, ready, rank, residual_ratio, &
      captured_fraction)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: residual
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: modes, targets
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: weights
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: step, residual_reduction
      LOGICAL, INTENT(OUT)                               :: ready
      INTEGER, INTENT(OUT)                               :: rank
      REAL(KIND=dp), INTENT(OUT)                         :: residual_ratio, captured_fraction

      INTEGER                                            :: info, j, mode_count, nres
      INTEGER, ALLOCATABLE, DIMENSION(:)                 :: ipiv
      REAL(KIND=dp)                                      :: residual_norm, residual_norm_sq, &
                                                            target_norm
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: coefficients, residual_after
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: gram, scaled_modes, scaled_targets

      nres = SIZE(residual)
      mode_count = SIZE(modes, 2)
      CPASSERT(SIZE(modes, 1) == SIZE(step))
      CPASSERT(ALL(SHAPE(targets) == [nres, mode_count]))
      CPASSERT(SIZE(weights) == nres)
      CPASSERT(SIZE(residual_reduction) == nres)
      CPASSERT(ALL(weights >= 0.0_dp))
      step(:) = 0.0_dp
      residual_reduction(:) = 0.0_dp
      ready = .FALSE.
      rank = 0
      residual_ratio = 1.0_dp
      captured_fraction = 0.0_dp
      IF (nres <= 0 .OR. mode_count <= 0) RETURN

      ALLOCATE (scaled_modes(SIZE(step), mode_count), scaled_targets(nres, mode_count))
      scaled_modes(:, :) = 0.0_dp
      scaled_targets(:, :) = 0.0_dp
      residual_norm_sq = DOT_PRODUCT(weights, residual*residual)
      residual_norm = SQRT(MAX(0.0_dp, residual_norm_sq))
      IF (residual_norm <= EPSILON(1.0_dp)) THEN
         DEALLOCATE (scaled_modes, scaled_targets)
         RETURN
      END IF
      DO j = 1, mode_count
         target_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(weights, targets(:, j)*targets(:, j))))
         IF (target_norm <= 64.0_dp*SQRT(EPSILON(1.0_dp))* &
             MAX(1.0_dp, residual_norm)) CYCLE
         rank = rank + 1
         scaled_targets(:, rank) = targets(:, j)/target_norm
         scaled_modes(:, rank) = modes(:, j)/target_norm
      END DO
      IF (rank <= 0) THEN
         DEALLOCATE (scaled_modes, scaled_targets)
         RETURN
      END IF

      ALLOCATE (coefficients(rank), residual_after(nres), ipiv(rank), gram(rank, rank))
      DO j = 1, rank
         gram(:, j) = MATMUL(TRANSPOSE(scaled_targets(:, 1:rank)), &
                             weights*scaled_targets(:, j))
      END DO
      coefficients(:) = MATMUL(TRANSPOSE(scaled_targets(:, 1:rank)), weights*residual)
      CALL dgesv(rank, 1, gram, rank, ipiv, coefficients, rank, info)
      IF (info == 0 .AND. ALL(coefficients == coefficients)) THEN
         step(:) = MATMUL(scaled_modes(:, 1:rank), coefficients)
         residual_reduction(:) = MATMUL(scaled_targets(:, 1:rank), coefficients)
         residual_after(:) = residual - residual_reduction
         residual_ratio = SQRT(MAX(0.0_dp, DOT_PRODUCT(weights, residual_after*residual_after)))/ &
                          MAX(residual_norm, EPSILON(1.0_dp))
         captured_fraction = SQRT(MAX(0.0_dp, 1.0_dp - residual_ratio**2))
         ready = residual_ratio < 1.0_dp - 64.0_dp*EPSILON(1.0_dp) .AND. &
                 ALL(step == step) .AND. captured_fraction == captured_fraction
      END IF
      IF (.NOT. ready) THEN
         step(:) = 0.0_dp
         residual_reduction(:) = 0.0_dp
      END IF
      DEALLOCATE (coefficients, residual_after, ipiv, gram, scaled_modes, scaled_targets)

   END SUBROUTINE qs_scf_kp_measured_residual_subspace_step

! **************************************************************************************************
!> \brief Add the analytic response of the coordinate component outside a measured secant span.
!>
!>        The measured response already contains Y*c for a projection S*c of active_vector.
!>        This routine adds H0*(active_vector-S*c) at the corresponding full-response indices.
!>        Hence accepted secants remain exact while an unresolved coordinate complement no longer
!>        implies zero physical response.
!> \param active_vector active-space coordinate vector
!> \param active_projection projection of active_vector into the measured secant span
!> \param baseline_hessian analytic active-space response Hessian H0
!> \param active_response_index full-response index of every active response coordinate
!> \param response measured response, completed in place
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_add_measured_response_complement( &
      active_vector, active_projection, baseline_hessian, active_response_index, response)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: active_vector, active_projection
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: baseline_hessian
      INTEGER, DIMENSION(:), INTENT(IN)                  :: active_response_index
      REAL(KIND=dp), DIMENSION(:), INTENT(INOUT)         :: response

      INTEGER                                            :: i, nactive
      REAL(KIND=dp), DIMENSION(SIZE(active_vector))      :: complement_response

      nactive = SIZE(active_vector)
      CPASSERT(SIZE(active_projection) == nactive)
      CPASSERT(ALL(SHAPE(baseline_hessian) == [nactive, nactive]))
      CPASSERT(SIZE(active_response_index) == nactive)
      CPASSERT(ALL(active_response_index > 0 .AND. active_response_index <= SIZE(response)))

      complement_response(:) = MATMUL(baseline_hessian, active_vector - active_projection)
      DO i = 1, nactive
         response(active_response_index(i)) = response(active_response_index(i)) + &
                                              complement_response(i)
      END DO

   END SUBROUTINE qs_scf_kp_add_measured_response_complement

! **************************************************************************************************
!> \brief Add an analytic full-output response outside a measured active-coordinate span.
!>
!>        The measured response is exact for the projected active step.  The rectangular analytic
!>        response operator supplies only the unresolved coordinate complement, preserving accepted
!>        secants while exposing their response in every full complex-rotation coordinate.
!> \param active_vector active-space coordinate vector
!> \param active_projection projection of active_vector into the measured secant span
!> \param full_response_hessian analytic map from active coordinates to the full response ordering
!> \param response measured full response, completed in place
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_add_full_response_complement( &
      active_vector, active_projection, full_response_hessian, response)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: active_vector, active_projection
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: full_response_hessian
      REAL(KIND=dp), DIMENSION(:), INTENT(INOUT)         :: response

      INTEGER                                            :: nactive

      nactive = SIZE(active_vector)
      CPASSERT(SIZE(active_projection) == nactive)
      CPASSERT(ALL(SHAPE(full_response_hessian) == [SIZE(response), nactive]))

      response(:) = response + MATMUL(full_response_hessian, active_vector - active_projection)

   END SUBROUTINE qs_scf_kp_add_full_response_complement

! **************************************************************************************************
!> \brief Combine an established quadratic model with an affine correction.
!>
!>        The established model belongs to the candidate already selected by the production
!>        preconditioner.  The correction curvature may come from a reduced measured-response
!>        model, so recomputing the base term in that metric would spuriously replace known
!>        line-search curvature.  Only the correction and cross terms are added here.
!> \param base_slope linear term of the established candidate
!> \param base_quadratic quadratic term of the established candidate
!> \param correction_slope linear term of the correction
!> \param correction_quadratic quadratic self-term of the correction
!> \param correction_cross symmetric base/correction quadratic cross-term
!> \param scale correction scale
!> \param slope combined linear term
!> \param quadratic combined quadratic term
!> \param drop predicted combined decrease
!> \param increment predicted change relative to the established decrease
!> \param ready whether the combined model is finite
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_affine_correction_model( &
      base_slope, base_quadratic, correction_slope, correction_quadratic, correction_cross, &
      scale, slope, quadratic, drop, increment, ready)
      REAL(KIND=dp), INTENT(IN)                          :: base_slope, base_quadratic, &
                                                            correction_slope, &
                                                            correction_quadratic, &
                                                            correction_cross, scale
      REAL(KIND=dp), INTENT(OUT)                         :: slope, quadratic, drop, increment
      LOGICAL, INTENT(OUT)                               :: ready

      slope = 0.0_dp
      quadratic = 0.0_dp
      drop = 0.0_dp
      increment = 0.0_dp
      ready = .FALSE.
      IF (scale < 0.0_dp) RETURN
      IF (.NOT. (base_slope == base_slope .AND. base_quadratic == base_quadratic .AND. &
                 correction_slope == correction_slope .AND. &
                 correction_quadratic == correction_quadratic .AND. &
                 correction_cross == correction_cross .AND. scale == scale)) RETURN

      slope = base_slope + scale*correction_slope
      quadratic = base_quadratic + 2.0_dp*scale*correction_cross + &
                  scale*scale*correction_quadratic
      drop = slope - 0.5_dp*quadratic
      increment = scale*(correction_slope - correction_cross) - &
                  0.5_dp*scale*scale*correction_quadratic
      ready = slope == slope .AND. quadratic == quadratic .AND. drop == drop .AND. &
              increment == increment .AND. ABS(slope) < HUGE(slope) .AND. &
              ABS(quadratic) < HUGE(quadratic) .AND. ABS(drop) < HUGE(drop) .AND. &
              ABS(increment) < HUGE(increment)
      IF (.NOT. ready) THEN
         slope = 0.0_dp
         quadratic = 0.0_dp
         drop = 0.0_dp
         increment = 0.0_dp
      END IF

   END SUBROUTINE qs_scf_kp_affine_correction_model

! **************************************************************************************************
!> \brief Compare an affine residual prediction with an accepted line-search endpoint.
!>
!>        The residual model is r(alpha)=r0+alpha*dr.  Keeping its three scalar products avoids
!>        storing a full k-point rotation vector across line-search calls and evaluates the model
!>        at the position that was actually accepted rather than assuming a unit step.
!> \param start_norm_sq <r0,r0> in the physical complex-rotation metric
!> \param delta_dot <r0,dr> in the same metric
!> \param delta_norm_sq <dr,dr> in the same metric
!> \param position accepted line-search position alpha
!> \param actual_norm_sq measured accepted-state physical rotation residual squared
!> \param predicted_ratio predicted accepted residual norm divided by the start norm
!> \param actual_ratio measured accepted residual norm divided by the start norm
!> \param quality prediction fidelity times the fraction of the current norm actually removed
!> \param ready whether the model predicts a finite resolvable decrease
! **************************************************************************************************
   PURE SUBROUTINE qs_scf_kp_affine_residual_quality( &
      start_norm_sq, delta_dot, delta_norm_sq, position, actual_norm_sq, predicted_ratio, &
      actual_ratio, quality, ready)
      REAL(KIND=dp), INTENT(IN)                          :: start_norm_sq, delta_dot, delta_norm_sq, &
                                                            position, actual_norm_sq
      REAL(KIND=dp), INTENT(OUT)                         :: predicted_ratio, actual_ratio, quality
      LOGICAL, INTENT(OUT)                               :: ready

      REAL(KIND=dp) :: actual_drop, actual_norm, predicted_drop, predicted_norm, &
         predicted_norm_sq, prediction_fidelity, start_norm, tolerance

      predicted_ratio = 1.0_dp
      actual_ratio = 1.0_dp
      quality = 0.0_dp
      ready = .FALSE.
      IF (.NOT. (start_norm_sq == start_norm_sq .AND. delta_dot == delta_dot .AND. &
                 delta_norm_sq == delta_norm_sq .AND. position == position .AND. &
                 actual_norm_sq == actual_norm_sq)) RETURN
      IF (start_norm_sq <= EPSILON(start_norm_sq) .OR. delta_norm_sq < 0.0_dp .OR. &
          position <= EPSILON(position) .OR. actual_norm_sq < 0.0_dp) RETURN

      start_norm = SQRT(start_norm_sq)
      predicted_norm_sq = start_norm_sq + 2.0_dp*position*delta_dot + &
                          position*position*delta_norm_sq
      tolerance = 64.0_dp*EPSILON(1.0_dp)*MAX(1.0_dp, start_norm)
      IF (predicted_norm_sq < -tolerance*MAX(1.0_dp, start_norm)) RETURN
      predicted_norm = SQRT(MAX(0.0_dp, predicted_norm_sq))
      actual_norm = SQRT(actual_norm_sq)
      predicted_ratio = predicted_norm/start_norm
      actual_ratio = actual_norm/start_norm
      predicted_drop = start_norm - predicted_norm
      IF (predicted_drop <= tolerance) THEN
         predicted_ratio = 1.0_dp
         actual_ratio = 1.0_dp
         RETURN
      END IF

      actual_drop = MAX(0.0_dp, start_norm - actual_norm)
      prediction_fidelity = MIN(1.0_dp, actual_drop/predicted_drop)
      quality = prediction_fidelity*MIN(1.0_dp, actual_drop/start_norm)
      ready = predicted_ratio == predicted_ratio .AND. actual_ratio == actual_ratio .AND. &
              quality == quality .AND. ABS(predicted_ratio) < HUGE(predicted_ratio) .AND. &
              ABS(actual_ratio) < HUGE(actual_ratio)
      IF (.NOT. ready) THEN
         predicted_ratio = 1.0_dp
         actual_ratio = 1.0_dp
         quality = 0.0_dp
      END IF

   END SUBROUTINE qs_scf_kp_affine_residual_quality

! **************************************************************************************************
!> \brief Separate prediction fidelity from physical gain for an accepted affine residual step.
!>
!>        The product returned by qs_scf_kp_affine_residual_quality is useful as a conservative
!>        one-number score, but it is not a fidelity: even an exact prediction is bounded by the
!>        fractional residual decrease. Candidate promotion needs the two quantities separately.
!> \param start_norm_sq physical residual norm squared before the candidate
!> \param delta_dot affine physical residual cross term
!> \param delta_norm_sq affine physical residual change norm squared
!> \param position accepted line-search position alpha
!> \param actual_norm_sq physical residual norm squared at the accepted endpoint
!> \param predicted_ratio predicted endpoint residual norm divided by the start norm
!> \param actual_ratio actual endpoint residual norm divided by the start norm
!> \param fidelity actual residual decrease divided by the predicted decrease, capped at one
!> \param gain fractional actual residual decrease
!> \param ready whether the model predicts a finite resolvable decrease
! **************************************************************************************************
   PURE SUBROUTINE qs_scf_kp_affine_residual_calibration( &
      start_norm_sq, delta_dot, delta_norm_sq, position, actual_norm_sq, predicted_ratio, &
      actual_ratio, fidelity, gain, ready)
      REAL(KIND=dp), INTENT(IN)                          :: start_norm_sq, delta_dot, delta_norm_sq, &
                                                            position, actual_norm_sq
      REAL(KIND=dp), INTENT(OUT)                         :: predicted_ratio, actual_ratio, fidelity, &
                                                            gain
      LOGICAL, INTENT(OUT)                               :: ready

      REAL(KIND=dp)                                      :: actual_norm, predicted_drop, &
                                                            predicted_norm, predicted_norm_sq, &
                                                            start_norm, tolerance

      predicted_ratio = 1.0_dp
      actual_ratio = 1.0_dp
      fidelity = 0.0_dp
      gain = 0.0_dp
      ready = .FALSE.
      IF (.NOT. (start_norm_sq == start_norm_sq .AND. delta_dot == delta_dot .AND. &
                 delta_norm_sq == delta_norm_sq .AND. position == position .AND. &
                 actual_norm_sq == actual_norm_sq)) RETURN
      IF (start_norm_sq <= EPSILON(start_norm_sq) .OR. delta_norm_sq < 0.0_dp .OR. &
          position <= EPSILON(position) .OR. actual_norm_sq < 0.0_dp) RETURN

      start_norm = SQRT(start_norm_sq)
      predicted_norm_sq = start_norm_sq + 2.0_dp*position*delta_dot + &
                          position*position*delta_norm_sq
      tolerance = 64.0_dp*EPSILON(1.0_dp)*MAX(1.0_dp, start_norm)
      IF (predicted_norm_sq < -tolerance*MAX(1.0_dp, start_norm)) RETURN
      predicted_norm = SQRT(MAX(0.0_dp, predicted_norm_sq))
      actual_norm = SQRT(actual_norm_sq)
      predicted_ratio = predicted_norm/start_norm
      actual_ratio = actual_norm/start_norm
      predicted_drop = start_norm - predicted_norm
      IF (predicted_drop <= tolerance) THEN
         predicted_ratio = 1.0_dp
         actual_ratio = 1.0_dp
         RETURN
      END IF

      gain = MAX(0.0_dp, 1.0_dp - actual_ratio)
      fidelity = MIN(1.0_dp, gain/MAX(1.0_dp - predicted_ratio, EPSILON(1.0_dp)))
      ready = predicted_ratio == predicted_ratio .AND. actual_ratio == actual_ratio .AND. &
              fidelity == fidelity .AND. gain == gain .AND. &
              ABS(predicted_ratio) < HUGE(predicted_ratio) .AND. &
              ABS(actual_ratio) < HUGE(actual_ratio)
      IF (.NOT. ready) THEN
         predicted_ratio = 1.0_dp
         actual_ratio = 1.0_dp
         fidelity = 0.0_dp
         gain = 0.0_dp
      END IF

   END SUBROUTINE qs_scf_kp_affine_residual_calibration

! **************************************************************************************************
!> \brief Test whether a candidate residual improvement exceeds its response-fit uncertainty.
!>
!>        A finite-response candidate must not replace an established direction when the difference
!>        between their predicted residual norms is smaller than the residual error of the fitted
!>        response map.  Such a replacement is an invasive experiment with no resolved physical
!>        advantage and can perturb otherwise useful minimizer history.
!> \param candidate_ratio predicted candidate residual norm divided by the current norm
!> \param reference_ratio best predicted residual ratio on the established direction
!> \param response_uncertainty relative residual error of the fitted response map
!> \return whether the candidate advantage is finite and resolved by the response model
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_residual_advantage_resolved( &
      candidate_ratio, reference_ratio, response_uncertainty) RESULT(resolved)
      REAL(KIND=dp), INTENT(IN)                          :: candidate_ratio, reference_ratio, &
                                                            response_uncertainty
      LOGICAL                                            :: resolved

      REAL(KIND=dp)                                      :: numerical_uncertainty

      resolved = .FALSE.
      IF (.NOT. (candidate_ratio == candidate_ratio .AND. reference_ratio == reference_ratio .AND. &
                 response_uncertainty == response_uncertainty)) RETURN
      IF (candidate_ratio < 0.0_dp .OR. reference_ratio < 0.0_dp .OR. &
          response_uncertainty < 0.0_dp) RETURN
      numerical_uncertainty = 64.0_dp*EPSILON(1.0_dp)* &
                              MAX(1.0_dp, candidate_ratio, reference_ratio)
      resolved = reference_ratio - candidate_ratio > &
                 MAX(response_uncertainty, numerical_uncertainty)

   END FUNCTION qs_scf_kp_residual_advantage_resolved

! **************************************************************************************************
!> \brief Maximize a residual correction while retaining a prescribed Mermin-model decrease.
!>
!>        For the affine correction model
!>          D(alpha)=D_base+alpha*l-0.5*alpha^2*q,
!>        return the largest alpha in [0,max_scale] for which
!>          D(alpha) >= retained_fraction*D_base.
!>        This exposes the model uncertainty to the residual solve instead of forcing the
!>        correction to stop at the much smaller pure-energy optimum l/q.
!> \param base_drop established candidate Mermin-model decrease
!> \param increment_slope affine correction slope l
!> \param correction_quadratic affine correction curvature q
!> \param max_scale largest scale allowed by response trust
!> \param retained_fraction minimum retained fraction of base_drop
!> \param scale largest admissible correction scale
!> \param retained_drop Mermin-model decrease at scale
!> \param ready whether a finite positive admissible scale exists
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_mermin_residual_pareto_scale( &
      base_drop, increment_slope, correction_quadratic, max_scale, retained_fraction, scale, &
      retained_drop, ready)
      REAL(KIND=dp), INTENT(IN)                          :: base_drop, increment_slope, &
                                                            correction_quadratic, max_scale, &
                                                            retained_fraction
      REAL(KIND=dp), INTENT(OUT)                         :: scale, retained_drop
      LOGICAL, INTENT(OUT)                               :: ready

      REAL(KIND=dp)                                      :: allowed_loss, boundary, discriminant, &
                                                            target_drop, tolerance

      CPASSERT(retained_fraction >= 0.0_dp .AND. retained_fraction <= 1.0_dp)
      scale = 0.0_dp
      retained_drop = MAX(0.0_dp, base_drop)
      ready = .FALSE.
      IF (base_drop <= EPSILON(base_drop) .OR. max_scale <= EPSILON(max_scale)) RETURN
      IF (.NOT. (base_drop == base_drop .AND. increment_slope == increment_slope .AND. &
                 correction_quadratic == correction_quadratic .AND. max_scale == max_scale)) RETURN

      target_drop = retained_fraction*base_drop
      allowed_loss = MAX(0.0_dp, base_drop - target_drop)
      boundary = max_scale
      IF (correction_quadratic > EPSILON(correction_quadratic)) THEN
         discriminant = increment_slope**2 + 2.0_dp*correction_quadratic*allowed_loss
         boundary = (increment_slope + SQRT(MAX(0.0_dp, discriminant)))/correction_quadratic
      ELSE IF (increment_slope < -EPSILON(increment_slope)) THEN
         boundary = allowed_loss/(-increment_slope)
      END IF
      scale = MIN(max_scale, MAX(0.0_dp, boundary))
      retained_drop = base_drop + scale*increment_slope - &
                      0.5_dp*scale**2*correction_quadratic
      tolerance = 64.0_dp*EPSILON(1.0_dp)*MAX(1.0_dp, ABS(base_drop), ABS(retained_drop))
      ready = scale > EPSILON(scale) .AND. retained_drop + tolerance >= target_drop .AND. &
              retained_drop == retained_drop .AND. ABS(retained_drop) < HUGE(retained_drop)
      IF (.NOT. ready) THEN
         scale = 0.0_dp
         retained_drop = MAX(0.0_dp, base_drop)
      END IF

   END SUBROUTINE qs_scf_kp_mermin_residual_pareto_scale

! **************************************************************************************************
!> \brief Minimize an affine residual while retaining a prescribed Mermin-model decrease.
!>
!>        The admissible interval is obtained from qs_scf_kp_mermin_residual_pareto_scale.
!>        Within that interval this routine minimizes
!>          ||r_base+alpha*dr||^2
!>        exactly. It therefore selects a genuine Pareto point between an established candidate
!>        and a finite-response candidate instead of comparing only their endpoints.
!> \param base_drop established candidate Mermin-model decrease
!> \param increment_slope affine correction slope
!> \param correction_quadratic affine correction curvature
!> \param residual_start_sq squared physical residual norm at the established candidate
!> \param residual_delta_dot physical residual cross term <r_base,dr>
!> \param residual_delta_sq squared physical residual change ||dr||^2
!> \param max_scale largest scale allowed by response trust
!> \param retained_fraction minimum retained fraction of base_drop
!> \param scale residual-minimizing admissible correction scale
!> \param retained_drop Mermin-model decrease at scale
!> \param residual_ratio residual norm at scale relative to the established candidate
!> \param ready whether a finite positive residual-reducing Pareto point exists
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_mermin_residual_pareto_blend( &
      base_drop, increment_slope, correction_quadratic, residual_start_sq, residual_delta_dot, &
      residual_delta_sq, max_scale, retained_fraction, scale, retained_drop, residual_ratio, ready)
      REAL(KIND=dp), INTENT(IN) :: base_drop, increment_slope, correction_quadratic, &
         residual_start_sq, residual_delta_dot, residual_delta_sq, max_scale, retained_fraction
      REAL(KIND=dp), INTENT(OUT)                         :: scale, retained_drop, residual_ratio
      LOGICAL, INTENT(OUT)                               :: ready

      LOGICAL                                            :: energy_ready, residual_ready
      REAL(KIND=dp)                                      :: energy_scale, residual_position, &
                                                            tolerance

      scale = 0.0_dp
      retained_drop = MAX(0.0_dp, base_drop)
      residual_ratio = 1.0_dp
      ready = .FALSE.
      CALL qs_scf_kp_mermin_residual_pareto_scale( &
         base_drop, increment_slope, correction_quadratic, max_scale, retained_fraction, &
         energy_scale, retained_drop, energy_ready)
      IF (.NOT. energy_ready) RETURN
      CALL qs_scf_kp_affine_residual_minimum( &
         residual_start_sq, residual_delta_dot, residual_delta_sq, energy_scale, &
         residual_position, residual_ratio, residual_ready)
      IF (.NOT. residual_ready) THEN
         retained_drop = MAX(0.0_dp, base_drop)
         RETURN
      END IF

      scale = residual_position
      retained_drop = base_drop + scale*increment_slope - &
                      0.5_dp*scale**2*correction_quadratic
      tolerance = 64.0_dp*EPSILON(1.0_dp)*MAX(1.0_dp, ABS(base_drop), ABS(retained_drop))
      ready = retained_drop + tolerance >= retained_fraction*base_drop .AND. &
              retained_drop == retained_drop .AND. ABS(retained_drop) < HUGE(retained_drop)
      IF (.NOT. ready) THEN
         scale = 0.0_dp
         retained_drop = MAX(0.0_dp, base_drop)
         residual_ratio = 1.0_dp
      END IF

   END SUBROUTINE qs_scf_kp_mermin_residual_pareto_blend

! **************************************************************************************************
!> \brief Complete an active Schur residual with a measured full-pair response.
!>
!>        The measured response supplies raw complex-rotation components outside the selected
!>        Schur subspace.  Active entries are replaced by the fixed-N reduced residual, which
!>        already contains the coupled energy response and must therefore not be counted twice.
!> \param full_residual current raw residual in the stable full-pair ordering
!> \param active_trial_residual fixed-N reduced residual after the candidate
!> \param active_full_index full-pair index of every active coordinate
!> \param measured_full_response measured raw full-pair response caused by the candidate
!> \param full_trial_residual completed candidate residual
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_full_residual_completion( &
      full_residual, active_trial_residual, active_full_index, measured_full_response, &
      full_trial_residual)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: full_residual, active_trial_residual
      INTEGER, DIMENSION(:), INTENT(IN)                  :: active_full_index
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: measured_full_response
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: full_trial_residual

      INTEGER                                            :: r

      CPASSERT(SIZE(measured_full_response) == SIZE(full_residual))
      CPASSERT(SIZE(full_trial_residual) == SIZE(full_residual))
      CPASSERT(SIZE(active_full_index) == SIZE(active_trial_residual))
      CPASSERT(ALL(active_full_index > 0 .AND. active_full_index <= SIZE(full_residual)))

      full_trial_residual(:) = full_residual - measured_full_response
      DO r = 1, SIZE(active_trial_residual)
         full_trial_residual(active_full_index(r)) = active_trial_residual(r)
      END DO

   END SUBROUTINE qs_scf_kp_full_residual_completion

! **************************************************************************************************
!> \brief Embed an active-space affine residual prediction in a stable full-pair ordering.
!>
!>        Full coordinates outside active_full_index are unchanged.  The returned coefficients
!>        therefore describe exactly
!>        ||r_full + alpha*(r_active_trial-r_active)||_weight^2
!>        when the active difference is scattered into the full ordering.
!> \param full_residual residual in the stable full-pair ordering
!> \param active_residual active-space residual before the candidate
!> \param active_trial_residual active-space residual after the full candidate
!> \param active_full_index full-pair index of every active coordinate
!> \param weight nonnegative diagonal physical residual metric in the full ordering
!> \param start_sq weighted full residual norm squared
!> \param delta_dot affine residual cross term
!> \param delta_sq weighted affine residual-change norm squared
!> \param trial_ratio weighted full residual ratio at alpha=1
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_active_residual_affine( &
      full_residual, active_residual, active_trial_residual, active_full_index, weight, &
      start_sq, delta_dot, delta_sq, trial_ratio)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: full_residual, active_residual, &
                                                            active_trial_residual
      INTEGER, DIMENSION(:), INTENT(IN)                  :: active_full_index
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: weight
      REAL(KIND=dp), INTENT(OUT)                         :: start_sq, delta_dot, delta_sq, &
                                                            trial_ratio

      INTEGER                                            :: ifull, r
      REAL(KIND=dp)                                      :: delta, trial_sq

      CPASSERT(SIZE(weight) == SIZE(full_residual))
      CPASSERT(SIZE(active_trial_residual) == SIZE(active_residual))
      CPASSERT(SIZE(active_full_index) == SIZE(active_residual))
      CPASSERT(ALL(weight >= 0.0_dp))
      CPASSERT(ALL(active_full_index > 0 .AND. active_full_index <= SIZE(full_residual)))

      start_sq = DOT_PRODUCT(weight, full_residual**2)
      delta_dot = 0.0_dp
      delta_sq = 0.0_dp
      DO r = 1, SIZE(active_residual)
         ifull = active_full_index(r)
         delta = active_trial_residual(r) - active_residual(r)
         delta_dot = delta_dot + weight(ifull)*full_residual(ifull)*delta
         delta_sq = delta_sq + weight(ifull)*delta*delta
      END DO
      trial_sq = MAX(0.0_dp, start_sq + 2.0_dp*delta_dot + delta_sq)
      trial_ratio = 1.0_dp
      IF (start_sq > EPSILON(start_sq)) trial_ratio = SQRT(trial_sq/start_sq)

   END SUBROUTINE qs_scf_kp_active_residual_affine

! **************************************************************************************************
!> \brief Find the minimum of an affine physical residual norm on a candidate ray.
!> \param start_sq weighted residual norm squared at the current state
!> \param delta_dot weighted affine residual cross term
!> \param delta_sq weighted affine residual-change norm squared
!> \param max_position largest position represented by the candidate ray
!> \param position residual-minimizing position in [0,max_position]
!> \param residual_ratio minimum residual norm relative to the current state
!> \param ready whether the ray contains a finite, resolvable residual decrease
! **************************************************************************************************
   PURE SUBROUTINE qs_scf_kp_affine_residual_minimum( &
      start_sq, delta_dot, delta_sq, max_position, position, residual_ratio, ready)
      REAL(KIND=dp), INTENT(IN)                          :: start_sq, delta_dot, delta_sq, &
                                                            max_position
      REAL(KIND=dp), INTENT(OUT)                         :: position, residual_ratio
      LOGICAL, INTENT(OUT)                               :: ready

      REAL(KIND=dp)                                      :: tolerance, trial_sq

      position = 0.0_dp
      residual_ratio = 1.0_dp
      ready = .FALSE.
      IF (.NOT. (start_sq == start_sq .AND. delta_dot == delta_dot .AND. &
                 delta_sq == delta_sq .AND. max_position == max_position)) RETURN
      IF (start_sq <= EPSILON(start_sq) .OR. delta_sq <= EPSILON(delta_sq) .OR. &
          max_position <= EPSILON(max_position)) RETURN

      position = MIN(max_position, MAX(0.0_dp, -delta_dot/delta_sq))
      IF (position <= EPSILON(position)) THEN
         position = 0.0_dp
         RETURN
      END IF
      trial_sq = MAX(0.0_dp, start_sq + 2.0_dp*position*delta_dot + &
                     position*position*delta_sq)
      residual_ratio = SQRT(trial_sq/start_sq)
      tolerance = 64.0_dp*EPSILON(1.0_dp)
      ready = residual_ratio < 1.0_dp - tolerance
      IF (.NOT. ready) THEN
         position = 0.0_dp
         residual_ratio = 1.0_dp
      END IF

   END SUBROUTINE qs_scf_kp_affine_residual_minimum

! **************************************************************************************************
!> \brief Restrict a candidate correction to the common energy/residual descent interval.
!>
!>        For r(alpha)=r_base+alpha*r_delta, the unconstrained residual least-squares minimizer is
!>        -dot(r_base,r_delta)/dot(r_delta,r_delta).  The returned scale is its intersection with
!>        [0,max_scale], where max_scale already carries the energy and trust-region restrictions.
!> \param base_residual residual after the established base step
!> \param delta_residual residual change generated by the candidate correction
!> \param max_scale largest correction scale allowed by the energy model
!> \param scale common energy/residual-compatible correction scale
!> \param optimal_scale unconstrained residual least-squares scale
!> \param residual_ratio predicted residual norm at scale relative to the base norm
!> \param ready whether a finite strictly residual-reducing scale exists
!> \param weight optional nonnegative diagonal physical residual metric
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_residual_compatible_scale(base_residual, delta_residual, max_scale, scale, &
                                                  optimal_scale, residual_ratio, ready, weight)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: base_residual, delta_residual
      REAL(KIND=dp), INTENT(IN)                          :: max_scale
      REAL(KIND=dp), INTENT(OUT)                         :: scale, optimal_scale, residual_ratio
      LOGICAL, INTENT(OUT)                               :: ready
      REAL(KIND=dp), DIMENSION(:), INTENT(IN), OPTIONAL  :: weight

      REAL(KIND=dp)                                      :: base_norm, cross, delta_norm_sq, &
                                                            trial_norm

      CPASSERT(SIZE(delta_residual) == SIZE(base_residual))
      IF (PRESENT(weight)) THEN
         CPASSERT(SIZE(weight) == SIZE(base_residual))
         CPASSERT(ALL(weight >= 0.0_dp))
      END IF
      scale = 0.0_dp
      optimal_scale = 0.0_dp
      residual_ratio = 1.0_dp
      ready = .FALSE.
      IF (SIZE(base_residual) <= 0 .OR. max_scale <= EPSILON(max_scale)) RETURN

      IF (PRESENT(weight)) THEN
         base_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(weight, base_residual**2)))
         delta_norm_sq = MAX(0.0_dp, DOT_PRODUCT(weight, delta_residual**2))
         cross = DOT_PRODUCT(weight, base_residual*delta_residual)
      ELSE
         base_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(base_residual, base_residual)))
         delta_norm_sq = MAX(0.0_dp, DOT_PRODUCT(delta_residual, delta_residual))
         cross = DOT_PRODUCT(base_residual, delta_residual)
      END IF
      IF (base_norm <= EPSILON(base_norm) .OR. delta_norm_sq <= EPSILON(delta_norm_sq)) RETURN

      optimal_scale = -cross/delta_norm_sq
      IF (optimal_scale <= EPSILON(optimal_scale)) RETURN
      scale = MIN(max_scale, optimal_scale)
      IF (PRESENT(weight)) THEN
         trial_norm = SQRT(MAX(0.0_dp, &
                               DOT_PRODUCT(weight, (base_residual + scale*delta_residual)**2)))
      ELSE
         trial_norm = SQRT(MAX(0.0_dp, &
                               DOT_PRODUCT(base_residual + scale*delta_residual, &
                                           base_residual + scale*delta_residual)))
      END IF
      residual_ratio = trial_norm/base_norm
      ready = scale == scale .AND. optimal_scale == optimal_scale .AND. &
              residual_ratio < 1.0_dp - 64.0_dp*EPSILON(1.0_dp)
      IF (.NOT. ready) scale = 0.0_dp

   END SUBROUTINE qs_scf_kp_residual_compatible_scale

! **************************************************************************************************
!> \brief Transport a full coupled response into the reduced rotation Schur block.
!> \param rotation_hessian analytic rotation block
!> \param energy_hessian analytic fixed-N energy block
!> \param energy_cross analytic signed cross block
!> \param response_rotation_hessian response-corrected rotation block
!> \param response_energy_hessian response-corrected energy block
!> \param response_energy_cross response-corrected signed cross block
!> \param transported_rotation_hessian analytic rotation block plus the reduced response correction
!> \param ready whether both energy blocks were invertible and the result finite
!> \param correction_ratio relative Frobenius norm of the reduced rotation correction
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_coupled_schur_transport(rotation_hessian, energy_hessian, energy_cross, &
                                                response_rotation_hessian, response_energy_hessian, &
                                                response_energy_cross, transported_rotation_hessian, &
                                                ready, correction_ratio)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN) :: rotation_hessian, energy_hessian, &
         energy_cross, response_rotation_hessian, response_energy_hessian, response_energy_cross
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: transported_rotation_hessian
      LOGICAL, INTENT(OUT)                               :: ready
      REAL(KIND=dp), INTENT(OUT)                         :: correction_ratio

      INTEGER                                            :: info, nener, nrot
      INTEGER, ALLOCATABLE, DIMENSION(:)                 :: ipiv
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: analytic_energy, analytic_response, &
                                                            response_energy, response_response

      nrot = SIZE(rotation_hessian, 1)
      nener = SIZE(energy_hessian, 1)
      CPASSERT(ALL(SHAPE(rotation_hessian) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(energy_hessian) == [nener, nener]))
      CPASSERT(ALL(SHAPE(energy_cross) == [nener, nrot]))
      CPASSERT(ALL(SHAPE(response_rotation_hessian) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(response_energy_hessian) == [nener, nener]))
      CPASSERT(ALL(SHAPE(response_energy_cross) == [nener, nrot]))
      CPASSERT(ALL(SHAPE(transported_rotation_hessian) == [nrot, nrot]))

      transported_rotation_hessian(:, :) = rotation_hessian(:, :)
      ready = .FALSE.
      correction_ratio = 0.0_dp
      IF (nrot <= 0 .OR. nener <= 0) RETURN
      ALLOCATE (ipiv(nener), analytic_energy(nener, nener), analytic_response(nener, nrot), &
                response_energy(nener, nener), response_response(nener, nrot))
      analytic_energy(:, :) = 0.5_dp*(energy_hessian + TRANSPOSE(energy_hessian))
      analytic_response(:, :) = energy_cross(:, :)
      CALL dgesv(nener, nrot, analytic_energy, nener, ipiv, analytic_response, nener, info)
      IF (info /= 0) THEN
         DEALLOCATE (ipiv, analytic_energy, analytic_response, response_energy, response_response)
         RETURN
      END IF
      response_energy(:, :) = 0.5_dp*(response_energy_hessian + &
                                      TRANSPOSE(response_energy_hessian))
      response_response(:, :) = response_energy_cross(:, :)
      CALL dgesv(nener, nrot, response_energy, nener, ipiv, response_response, nener, info)
      IF (info == 0) THEN
         transported_rotation_hessian(:, :) = response_rotation_hessian - &
                                              MATMUL(TRANSPOSE(response_energy_cross), &
                                                     response_response) + &
                                              MATMUL(TRANSPOSE(energy_cross), analytic_response)
         transported_rotation_hessian(:, :) = 0.5_dp* &
                                              (transported_rotation_hessian + &
                                               TRANSPOSE(transported_rotation_hessian))
         correction_ratio = SQRT(MAX(0.0_dp, &
                                     SUM((transported_rotation_hessian - rotation_hessian)**2)))/ &
                            MAX(SQRT(MAX(0.0_dp, SUM(rotation_hessian**2))), EPSILON(1.0_dp))
         ready = ALL(transported_rotation_hessian == transported_rotation_hessian) .AND. &
                 correction_ratio == correction_ratio
      END IF
      IF (.NOT. ready) transported_rotation_hessian(:, :) = rotation_hessian(:, :)
      DEALLOCATE (ipiv, analytic_energy, analytic_response, response_energy, response_response)

   END SUBROUTINE qs_scf_kp_coupled_schur_transport

! **************************************************************************************************
!> \brief Fit accepted self-consistent closure response in coupled rotation/energy space.
!>
!>        The measured closure targets are added to the analytic fixed-N Mermin model, fitted
!>        symmetrically in the two accepted full-space directions, and then transported through
!>        the fitted energy block.  The returned matrix is only the reduced closure correction;
!>        the analytic rotation Hessian itself is not duplicated.
!> \param rotation_hessian analytic complex-rotation block
!> \param energy_hessian analytic fixed-N auxiliary-energy block
!> \param energy_cross analytic signed cross block
!> \param rotation_steps two accepted complex-rotation steps
!> \param energy_steps corresponding fixed-N auxiliary-energy steps
!> \param closure_rotation_targets self-consistent rotation-gradient changes
!> \param closure_energy_targets self-consistent auxiliary-energy-gradient changes
!> \param response_correction reduced rotation-space closure correction
!> \param ready whether the fit and Schur transport succeeded
!> \param independence scaled full-step independence
!> \param compatibility symmetric-secant compatibility correction
!> \param response_capture fraction of the closure residual in the fitted subspace
!> \param residual_ratio fitted/full closure-residual norm ratio
!> \param transport_ratio relative reduced Schur correction
!> \param rotation_ratio relative fitted rotation-block correction
!> \param energy_ratio relative fitted energy-block correction
!> \param cross_ratio relative fitted cross-block correction
!> \param full_rotation_correction optional fitted rotation-block correction
!> \param full_energy_correction optional fitted auxiliary-energy-block correction
!> \param full_cross_correction optional fitted signed cross-block correction
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_coupled_closure_response( &
      rotation_hessian, energy_hessian, energy_cross, rotation_steps, energy_steps, &
      closure_rotation_targets, closure_energy_targets, response_correction, ready, &
      independence, compatibility, response_capture, residual_ratio, transport_ratio, &
      rotation_ratio, energy_ratio, cross_ratio, full_rotation_correction, &
      full_energy_correction, full_cross_correction)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN) :: rotation_hessian, energy_hessian, &
         energy_cross, rotation_steps, energy_steps, closure_rotation_targets, &
         closure_energy_targets
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: response_correction
      LOGICAL, INTENT(OUT)                               :: ready
      REAL(KIND=dp), INTENT(OUT) :: independence, compatibility, response_capture, residual_ratio, &
         transport_ratio, rotation_ratio, energy_ratio, cross_ratio
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT), &
         OPTIONAL                                        :: full_rotation_correction, &
                                                            full_energy_correction, &
                                                            full_cross_correction

      INTEGER                                            :: isample, nener, nrot
      LOGICAL                                            :: fit_ready, transport_ready
      REAL(KIND=dp)                                      :: correction_norm, &
                                                            projected_residual_norm, &
                                                            residual_norm, updated_residual_norm
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :) :: fitted_energy_cross, fitted_energy_hessian, &
         fitted_rotation_hessian, full_energy_targets, full_rotation_targets, &
         transported_rotation_hessian

      nrot = SIZE(rotation_hessian, 1)
      nener = SIZE(energy_hessian, 1)
      CPASSERT(ALL(SHAPE(rotation_hessian) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(energy_hessian) == [nener, nener]))
      CPASSERT(ALL(SHAPE(energy_cross) == [nener, nrot]))
      CPASSERT(ALL(SHAPE(rotation_steps) == [nrot, 2]))
      CPASSERT(ALL(SHAPE(energy_steps) == [nener, 2]))
      CPASSERT(ALL(SHAPE(closure_rotation_targets) == [nrot, 2]))
      CPASSERT(ALL(SHAPE(closure_energy_targets) == [nener, 2]))
      CPASSERT(ALL(SHAPE(response_correction) == [nrot, nrot]))
      IF (PRESENT(full_rotation_correction)) THEN
         CPASSERT(ALL(SHAPE(full_rotation_correction) == [nrot, nrot]))
      END IF
      IF (PRESENT(full_energy_correction)) THEN
         CPASSERT(ALL(SHAPE(full_energy_correction) == [nener, nener]))
      END IF
      IF (PRESENT(full_cross_correction)) THEN
         CPASSERT(ALL(SHAPE(full_cross_correction) == [nener, nrot]))
      END IF

      response_correction(:, :) = 0.0_dp
      IF (PRESENT(full_rotation_correction)) full_rotation_correction(:, :) = 0.0_dp
      IF (PRESENT(full_energy_correction)) full_energy_correction(:, :) = 0.0_dp
      IF (PRESENT(full_cross_correction)) full_cross_correction(:, :) = 0.0_dp
      ready = .FALSE.
      independence = 0.0_dp
      compatibility = 0.0_dp
      response_capture = 0.0_dp
      residual_ratio = 0.0_dp
      transport_ratio = 0.0_dp
      rotation_ratio = 0.0_dp
      energy_ratio = 0.0_dp
      cross_ratio = 0.0_dp
      IF (nrot <= 0 .OR. nener <= 0) RETURN

      ALLOCATE (fitted_energy_cross(nener, nrot), fitted_energy_hessian(nener, nener), &
                fitted_rotation_hessian(nrot, nrot), full_energy_targets(nener, 2), &
                full_rotation_targets(nrot, 2), transported_rotation_hessian(nrot, nrot))
      DO isample = 1, 2
         CALL qs_scf_kp_coupled_secant_model( &
            rotation_hessian, energy_hessian, energy_cross, rotation_steps(:, isample), &
            energy_steps(:, isample), full_rotation_targets(:, isample), &
            full_energy_targets(:, isample))
      END DO
      full_rotation_targets(:, :) = full_rotation_targets + closure_rotation_targets
      full_energy_targets(:, :) = full_energy_targets + closure_energy_targets
      CALL qs_scf_kp_coupled_subspace_multisecant_update( &
         rotation_hessian, energy_hessian, energy_cross, rotation_steps, energy_steps, &
         full_rotation_targets, full_energy_targets, 1.0_dp, fitted_rotation_hessian, &
         fitted_energy_hessian, fitted_energy_cross, fit_ready, independence, compatibility, &
         response_capture, correction_norm, residual_norm, updated_residual_norm, &
         projected_residual_norm, rotation_ratio, energy_ratio, cross_ratio)
      transport_ready = .FALSE.
      IF (fit_ready) &
         CALL qs_scf_kp_coupled_schur_transport( &
         rotation_hessian, energy_hessian, energy_cross, fitted_rotation_hessian, &
         fitted_energy_hessian, fitted_energy_cross, transported_rotation_hessian, &
         transport_ready, transport_ratio)
      ready = fit_ready .AND. transport_ready
      IF (ready) THEN
         response_correction(:, :) = transported_rotation_hessian - rotation_hessian
         response_correction(:, :) = 0.5_dp* &
                                     (response_correction + TRANSPOSE(response_correction))
         IF (PRESENT(full_rotation_correction)) &
            full_rotation_correction(:, :) = fitted_rotation_hessian - rotation_hessian
         IF (PRESENT(full_energy_correction)) &
            full_energy_correction(:, :) = fitted_energy_hessian - energy_hessian
         IF (PRESENT(full_cross_correction)) &
            full_cross_correction(:, :) = fitted_energy_cross - energy_cross
         residual_ratio = updated_residual_norm/MAX(residual_norm, EPSILON(1.0_dp))
      END IF
      DEALLOCATE (fitted_energy_cross, fitted_energy_hessian, fitted_rotation_hessian, &
                  full_energy_targets, full_rotation_targets, transported_rotation_hessian)

   END SUBROUTINE qs_scf_kp_coupled_closure_response

! **************************************************************************************************
!> \brief Predict one closure response from a normalized symmetric response-vector secant.
!>
!>        The exact yy^T/(s^Ty) secant is used for bidirectional response identification.  Its
!>        candidate correction is multiplied by |s^Ty|/(||s||||y||), yielding the bounded signed
!>        mode sign(s^Ty) yy^T/(||s||||y||).  This retains the observed response direction and block
!>        structure without turning a nearly orthogonal, nonconservative endpoint response into an
!>        unbounded Hessian curvature.
!> \param rotation_hessian ...
!> \param energy_hessian ...
!> \param training_rotation_step ...
!> \param training_energy_step ...
!> \param training_rotation_response ...
!> \param training_energy_response ...
!> \param validation_rotation_step ...
!> \param validation_energy_step ...
!> \param validation_rotation_response ...
!> \param validation_energy_response ...
!> \param rotation_correction ...
!> \param energy_correction ...
!> \param cross_correction ...
!> \param ready ...
!> \param step_overlap ...
!> \param training_capture ...
!> \param validation_quality ...
!> \param validation_rotation_quality ...
!> \param validation_energy_quality ...
!> \param strict_validation_quality ...
!> \param strict_validation_rotation_quality ...
!> \param strict_validation_energy_quality ...
!> \param validation_alignment ...
!> \param validation_curvature_ratio ...
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_coupled_response_secant_prediction( &
      rotation_hessian, energy_hessian, training_rotation_step, training_energy_step, &
      training_rotation_response, training_energy_response, validation_rotation_step, &
      validation_energy_step, validation_rotation_response, validation_energy_response, &
      rotation_correction, energy_correction, cross_correction, ready, step_overlap, &
      training_capture, validation_quality, validation_rotation_quality, &
      validation_energy_quality, strict_validation_quality, &
      strict_validation_rotation_quality, strict_validation_energy_quality, &
      validation_alignment, validation_curvature_ratio)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: rotation_hessian, energy_hessian
      REAL(KIND=dp), DIMENSION(:), INTENT(IN) :: training_rotation_step, training_energy_step, &
         training_rotation_response, training_energy_response, validation_rotation_step, &
         validation_energy_step, validation_rotation_response, validation_energy_response
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: rotation_correction, energy_correction, &
                                                            cross_correction
      LOGICAL, INTENT(OUT)                               :: ready
      REAL(KIND=dp), INTENT(OUT) :: step_overlap, training_capture, validation_quality, &
         validation_rotation_quality, validation_energy_quality, strict_validation_quality, &
         strict_validation_rotation_quality, strict_validation_energy_quality, &
         validation_alignment, validation_curvature_ratio

      INTEGER                                            :: i, j, nener, nfull, nrot
      REAL(KIND=dp) :: block_floor, block_max, component_floor, predicted_curvature, &
         predicted_energy_residual_sq, predicted_energy_response_sq, predicted_norm, &
         predicted_residual_sq, predicted_response_norm_sq, predicted_rotation_residual_sq, &
         predicted_rotation_response_sq, response_norm, rotation_residual_sq, secant_curvature, &
         step_norm, strict_component_floor, validation_curvature, validation_energy_residual_sq, &
         validation_norm, validation_residual_sq
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:) :: coordinate_scale, predicted_residual, &
         predicted_response, training_response, training_step, validation_response, validation_step
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: response_hessian

      nrot = SIZE(rotation_hessian, 1)
      nener = SIZE(energy_hessian, 1)
      nfull = nrot + nener
      CPASSERT(ALL(SHAPE(rotation_hessian) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(energy_hessian) == [nener, nener]))
      CPASSERT(SIZE(training_rotation_step) == nrot)
      CPASSERT(SIZE(training_energy_step) == nener)
      CPASSERT(SIZE(training_rotation_response) == nrot)
      CPASSERT(SIZE(training_energy_response) == nener)
      CPASSERT(SIZE(validation_rotation_step) == nrot)
      CPASSERT(SIZE(validation_energy_step) == nener)
      CPASSERT(SIZE(validation_rotation_response) == nrot)
      CPASSERT(SIZE(validation_energy_response) == nener)
      CPASSERT(ALL(SHAPE(rotation_correction) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(energy_correction) == [nener, nener]))
      CPASSERT(ALL(SHAPE(cross_correction) == [nener, nrot]))

      rotation_correction(:, :) = 0.0_dp
      energy_correction(:, :) = 0.0_dp
      cross_correction(:, :) = 0.0_dp
      ready = .FALSE.
      step_overlap = 0.0_dp
      training_capture = 0.0_dp
      validation_quality = 0.0_dp
      validation_rotation_quality = 0.0_dp
      validation_energy_quality = 0.0_dp
      strict_validation_quality = 0.0_dp
      strict_validation_rotation_quality = 0.0_dp
      strict_validation_energy_quality = 0.0_dp
      validation_alignment = 0.0_dp
      validation_curvature_ratio = 0.0_dp
      IF (nrot <= 0 .OR. nener <= 0) RETURN

      ALLOCATE (coordinate_scale(nfull), predicted_response(nfull), predicted_residual(nfull), &
                response_hessian(nfull, nfull), training_response(nfull), training_step(nfull), &
                validation_response(nfull), validation_step(nfull))
      block_max = MAXVAL(ABS([(rotation_hessian(i, i), i=1, nrot)]))
      IF (block_max > TINY(1.0_dp)) THEN
         block_floor = SQRT(EPSILON(1.0_dp))*block_max
         DO i = 1, nrot
            coordinate_scale(i) = SQRT(MAX(ABS(rotation_hessian(i, i)), block_floor))
         END DO
      ELSE
         coordinate_scale(1:nrot) = 1.0_dp
      END IF
      block_max = MAXVAL(ABS([(energy_hessian(i, i), i=1, nener)]))
      IF (block_max > TINY(1.0_dp)) THEN
         block_floor = SQRT(EPSILON(1.0_dp))*block_max
         DO i = 1, nener
            coordinate_scale(nrot + i) = SQRT(MAX(ABS(energy_hessian(i, i)), block_floor))
         END DO
      ELSE
         coordinate_scale(nrot + 1:nfull) = 1.0_dp
      END IF

      training_step(1:nrot) = training_rotation_step
      training_step(nrot + 1:nfull) = training_energy_step
      training_response(1:nrot) = training_rotation_response
      training_response(nrot + 1:nfull) = training_energy_response
      validation_step(1:nrot) = validation_rotation_step
      validation_step(nrot + 1:nfull) = validation_energy_step
      validation_response(1:nrot) = validation_rotation_response
      validation_response(nrot + 1:nfull) = validation_energy_response
      training_step(:) = coordinate_scale*training_step
      validation_step(:) = coordinate_scale*validation_step
      training_response(:) = training_response/coordinate_scale
      validation_response(:) = validation_response/coordinate_scale

      validation_residual_sq = MAX(0.0_dp, DOT_PRODUCT(validation_response, validation_response))
      rotation_residual_sq = MAX(0.0_dp, &
                                 DOT_PRODUCT(validation_response(1:nrot), &
                                             validation_response(1:nrot)))
      validation_energy_residual_sq = MAX(0.0_dp, &
                                          DOT_PRODUCT(validation_response(nrot + 1:nfull), &
                                                      validation_response(nrot + 1:nfull)))

      step_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(training_step, training_step)))
      validation_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(validation_step, validation_step)))
      response_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(training_response, training_response)))
      secant_curvature = DOT_PRODUCT(training_step, training_response)
      IF (step_norm <= SQRT(EPSILON(1.0_dp)) .OR. &
          validation_norm <= SQRT(EPSILON(1.0_dp)) .OR. &
          response_norm <= SQRT(EPSILON(1.0_dp)) .OR. &
          ABS(secant_curvature) <= SQRT(EPSILON(1.0_dp))*step_norm*response_norm) THEN
         DEALLOCATE (coordinate_scale, predicted_response, predicted_residual, response_hessian, &
                     training_response, training_step, validation_response, validation_step)
         RETURN
      END IF

      step_overlap = ABS(DOT_PRODUCT(training_step, validation_step))/(step_norm*validation_norm)
      training_capture = ABS(secant_curvature)/(step_norm*response_norm)
      DO j = 1, nfull
         DO i = 1, nfull
            response_hessian(i, j) = training_response(i)*training_response(j)/secant_curvature
         END DO
      END DO
      predicted_response(:) = MATMUL(response_hessian, validation_step)
      predicted_residual(:) = validation_response - predicted_response
      predicted_residual_sq = MAX(0.0_dp, DOT_PRODUCT(predicted_residual, predicted_residual))
      predicted_response_norm_sq = MAX(0.0_dp, DOT_PRODUCT(predicted_response, predicted_response))
      IF (MAX(validation_residual_sq, predicted_response_norm_sq) > &
          EPSILON(MAX(validation_residual_sq, predicted_response_norm_sq))) &
         validation_quality = 1.0_dp - predicted_residual_sq/ &
                              MAX(validation_residual_sq, predicted_response_norm_sq)
      IF (validation_residual_sq > EPSILON(validation_residual_sq)) &
         strict_validation_quality = 1.0_dp - predicted_residual_sq/validation_residual_sq
      predicted_rotation_residual_sq = MAX(0.0_dp, &
                                           DOT_PRODUCT(predicted_residual(1:nrot), &
                                                       predicted_residual(1:nrot)))
      predicted_rotation_response_sq = MAX(0.0_dp, &
                                           DOT_PRODUCT(predicted_response(1:nrot), &
                                                       predicted_response(1:nrot)))
      component_floor = 64.0_dp*EPSILON(1.0_dp)* &
                        MAX(validation_residual_sq, predicted_response_norm_sq, TINY(1.0_dp))
      IF (MAX(rotation_residual_sq, predicted_rotation_response_sq) > component_floor) THEN
         validation_rotation_quality = 1.0_dp - &
                                       predicted_rotation_residual_sq/ &
                                       MAX(rotation_residual_sq, predicted_rotation_response_sq)
      ELSE
         validation_rotation_quality = 1.0_dp
      END IF
      IF (rotation_residual_sq > EPSILON(rotation_residual_sq)) &
         strict_validation_rotation_quality = 1.0_dp - &
                                              predicted_rotation_residual_sq/rotation_residual_sq
      predicted_energy_residual_sq = MAX(0.0_dp, &
                                         DOT_PRODUCT(predicted_residual(nrot + 1:nfull), &
                                                     predicted_residual(nrot + 1:nfull)))
      predicted_energy_response_sq = MAX(0.0_dp, &
                                         DOT_PRODUCT(predicted_response(nrot + 1:nfull), &
                                                     predicted_response(nrot + 1:nfull)))
      IF (MAX(validation_energy_residual_sq, predicted_energy_response_sq) > component_floor) THEN
         validation_energy_quality = 1.0_dp - &
                                     predicted_energy_residual_sq/ &
                                     MAX(validation_energy_residual_sq, predicted_energy_response_sq)
      ELSE
         validation_energy_quality = 1.0_dp
      END IF
      strict_component_floor = 64.0_dp*EPSILON(1.0_dp)* &
                               MAX(validation_residual_sq, TINY(1.0_dp))
      IF (validation_energy_residual_sq > strict_component_floor) THEN
         strict_validation_energy_quality = 1.0_dp - &
                                            predicted_energy_residual_sq/ &
                                            validation_energy_residual_sq
      ELSE IF (predicted_energy_residual_sq <= strict_component_floor) THEN
         strict_validation_energy_quality = 1.0_dp
      ELSE
         strict_validation_energy_quality = 1.0_dp - &
                                            predicted_energy_residual_sq/strict_component_floor
      END IF
      predicted_norm = SQRT(predicted_response_norm_sq)
      IF (validation_residual_sq > EPSILON(validation_residual_sq) .AND. &
          predicted_norm > EPSILON(predicted_norm)) &
         validation_alignment = DOT_PRODUCT(validation_response, predicted_response)/ &
                                (SQRT(validation_residual_sq)*predicted_norm)
      predicted_curvature = DOT_PRODUCT(validation_step, predicted_response)
      validation_curvature = DOT_PRODUCT(validation_step, validation_response)
      IF (ABS(predicted_curvature) > SQRT(EPSILON(1.0_dp))* &
          validation_norm*MAX(predicted_norm, EPSILON(1.0_dp))) &
         validation_curvature_ratio = validation_curvature/predicted_curvature

      ready = ALL(response_hessian == response_hessian) .AND. &
              step_overlap == step_overlap .AND. training_capture == training_capture .AND. &
              validation_quality == validation_quality .AND. &
              validation_rotation_quality == validation_rotation_quality .AND. &
              validation_energy_quality == validation_energy_quality .AND. &
              strict_validation_quality == strict_validation_quality .AND. &
              strict_validation_rotation_quality == strict_validation_rotation_quality .AND. &
              strict_validation_energy_quality == strict_validation_energy_quality .AND. &
              validation_alignment == validation_alignment .AND. &
              validation_curvature_ratio == validation_curvature_ratio
      IF (ready) THEN
         DO j = 1, nfull
            DO i = 1, nfull
               response_hessian(i, j) = training_capture*response_hessian(i, j)* &
                                        coordinate_scale(i)*coordinate_scale(j)
            END DO
         END DO
         rotation_correction(:, :) = response_hessian(1:nrot, 1:nrot)
         energy_correction(:, :) = response_hessian(nrot + 1:nfull, nrot + 1:nfull)
         cross_correction(:, :) = -response_hessian(nrot + 1:nfull, 1:nrot)
      END IF
      DEALLOCATE (coordinate_scale, predicted_response, predicted_residual, response_hessian, &
                  training_response, training_step, validation_response, validation_step)

   END SUBROUTINE qs_scf_kp_coupled_response_secant_prediction

! **************************************************************************************************
!> \brief Predict closure work with a symmetric two-secant observable-subspace model.
!>
!>        In the dimensionally scaled joint rotation/auxiliary-energy space, only
!>        sym(S^T*Y) is observable as Hessian work.  The fitted low-rank operator
!>
!>          H = S (S^T S)^-1 sym(S^T Y) (S^T S)^-1 S^T
!>
!>        reproduces that work exactly while discarding response normal to the accepted-step
!>        subspace.  A response block below numerical resolution is removed from S as well, so an
!>        absent auxiliary-energy response cannot manufacture energy/cross curvature merely because
!>        the accepted step contained an ener_x displacement.  A third secant is used only for
!>        out-of-sample validation.
!> \param rotation_hessian ...
!> \param energy_hessian ...
!> \param training_rotation_steps ...
!> \param training_energy_steps ...
!> \param training_rotation_responses ...
!> \param training_energy_responses ...
!> \param validation_rotation_step ...
!> \param validation_energy_step ...
!> \param validation_rotation_response ...
!> \param validation_energy_response ...
!> \param rotation_correction ...
!> \param energy_correction ...
!> \param cross_correction ...
!> \param ready ...
!> \param independence ...
!> \param training_quality ...
!> \param validation_quality ...
!> \param validation_rotation_quality ...
!> \param validation_energy_quality ...
!> \param strict_validation_quality ...
!> \param strict_validation_rotation_quality ...
!> \param strict_validation_energy_quality ...
!> \param validation_alignment ...
!> \param validation_curvature_ratio ...
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_coupled_response_multisecant_prediction( &
      rotation_hessian, energy_hessian, training_rotation_steps, training_energy_steps, &
      training_rotation_responses, training_energy_responses, validation_rotation_step, &
      validation_energy_step, validation_rotation_response, validation_energy_response, &
      rotation_correction, energy_correction, cross_correction, ready, independence, &
      training_quality, validation_quality, validation_rotation_quality, &
      validation_energy_quality, strict_validation_quality, &
      strict_validation_rotation_quality, strict_validation_energy_quality, &
      validation_alignment, validation_curvature_ratio)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN) :: rotation_hessian, energy_hessian, &
         training_rotation_steps, training_energy_steps, training_rotation_responses, &
         training_energy_responses
      REAL(KIND=dp), DIMENSION(:), INTENT(IN) :: validation_rotation_step, validation_energy_step, &
         validation_rotation_response, validation_energy_response
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: rotation_correction, energy_correction, &
                                                            cross_correction
      LOGICAL, INTENT(OUT)                               :: ready
      REAL(KIND=dp), INTENT(OUT) :: independence, training_quality, validation_quality, &
         validation_rotation_quality, validation_energy_quality, strict_validation_quality, &
         strict_validation_rotation_quality, strict_validation_energy_quality, &
         validation_alignment, validation_curvature_ratio

      INTEGER                                            :: i, j, nener, nfull, nrot
      LOGICAL                                            :: fit_ready
      REAL(KIND=dp) :: block_floor, block_max, component_floor, determinant, &
         energy_response_norm_sq, gram_scale, predicted_curvature, predicted_energy_residual_sq, &
         predicted_energy_response_sq, predicted_norm, predicted_residual_sq, &
         predicted_response_norm_sq, predicted_rotation_residual_sq, &
         predicted_rotation_response_sq, rotation_response_norm_sq, strict_component_floor, &
         training_energy_response_sq, training_predicted_norm_sq, training_residual_sq, &
         training_response_norm_sq, training_rotation_response_sq, validation_curvature, &
         validation_norm_sq
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: coordinate_scale, predicted_residual, &
                                                            predicted_response, &
                                                            validation_response, validation_step
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: response_hessian, training_residual, &
                                                            training_responses, training_steps, &
                                                            work_steps
      REAL(KIND=dp), DIMENSION(2, 2)                     :: gram, gram_inverse, work_matrix, &
                                                            work_operator

      nrot = SIZE(rotation_hessian, 1)
      nener = SIZE(energy_hessian, 1)
      nfull = nrot + nener
      CPASSERT(ALL(SHAPE(rotation_hessian) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(energy_hessian) == [nener, nener]))
      CPASSERT(ALL(SHAPE(training_rotation_steps) == [nrot, 2]))
      CPASSERT(ALL(SHAPE(training_energy_steps) == [nener, 2]))
      CPASSERT(ALL(SHAPE(training_rotation_responses) == [nrot, 2]))
      CPASSERT(ALL(SHAPE(training_energy_responses) == [nener, 2]))
      CPASSERT(SIZE(validation_rotation_step) == nrot)
      CPASSERT(SIZE(validation_energy_step) == nener)
      CPASSERT(SIZE(validation_rotation_response) == nrot)
      CPASSERT(SIZE(validation_energy_response) == nener)
      CPASSERT(ALL(SHAPE(rotation_correction) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(energy_correction) == [nener, nener]))
      CPASSERT(ALL(SHAPE(cross_correction) == [nener, nrot]))

      rotation_correction(:, :) = 0.0_dp
      energy_correction(:, :) = 0.0_dp
      cross_correction(:, :) = 0.0_dp
      ready = .FALSE.
      independence = 0.0_dp
      training_quality = 0.0_dp
      validation_quality = 0.0_dp
      validation_rotation_quality = 0.0_dp
      validation_energy_quality = 0.0_dp
      strict_validation_quality = 0.0_dp
      strict_validation_rotation_quality = 0.0_dp
      strict_validation_energy_quality = 0.0_dp
      validation_alignment = 0.0_dp
      validation_curvature_ratio = 0.0_dp
      IF (nrot <= 0 .OR. nener <= 0) RETURN

      ALLOCATE (coordinate_scale(nfull), predicted_residual(nfull), predicted_response(nfull), &
                response_hessian(nfull, nfull), training_residual(nfull, 2), &
                training_responses(nfull, 2), training_steps(nfull, 2), &
                validation_response(nfull), validation_step(nfull), work_steps(nfull, 2))
      block_max = MAXVAL(ABS([(rotation_hessian(i, i), i=1, nrot)]))
      IF (block_max > TINY(1.0_dp)) THEN
         block_floor = SQRT(EPSILON(1.0_dp))*block_max
         DO i = 1, nrot
            coordinate_scale(i) = SQRT(MAX(ABS(rotation_hessian(i, i)), block_floor))
         END DO
      ELSE
         coordinate_scale(1:nrot) = 1.0_dp
      END IF
      block_max = MAXVAL(ABS([(energy_hessian(i, i), i=1, nener)]))
      IF (block_max > TINY(1.0_dp)) THEN
         block_floor = SQRT(EPSILON(1.0_dp))*block_max
         DO i = 1, nener
            coordinate_scale(nrot + i) = SQRT(MAX(ABS(energy_hessian(i, i)), block_floor))
         END DO
      ELSE
         coordinate_scale(nrot + 1:nfull) = 1.0_dp
      END IF

      training_steps(1:nrot, :) = training_rotation_steps
      training_steps(nrot + 1:nfull, :) = training_energy_steps
      training_responses(1:nrot, :) = training_rotation_responses
      training_responses(nrot + 1:nfull, :) = training_energy_responses
      validation_step(1:nrot) = validation_rotation_step
      validation_step(nrot + 1:nfull) = validation_energy_step
      validation_response(1:nrot) = validation_rotation_response
      validation_response(nrot + 1:nfull) = validation_energy_response
      DO i = 1, nfull
         training_steps(i, :) = coordinate_scale(i)*training_steps(i, :)
         training_responses(i, :) = training_responses(i, :)/coordinate_scale(i)
         validation_step(i) = coordinate_scale(i)*validation_step(i)
         validation_response(i) = validation_response(i)/coordinate_scale(i)
      END DO

      work_steps(:, :) = training_steps
      training_response_norm_sq = MAX(0.0_dp, SUM(training_responses**2))
      training_rotation_response_sq = MAX(0.0_dp, SUM(training_responses(1:nrot, :)**2))
      training_energy_response_sq = MAX(0.0_dp, &
                                        SUM(training_responses(nrot + 1:nfull, :)**2))
      component_floor = 64.0_dp*EPSILON(1.0_dp)* &
                        MAX(training_response_norm_sq, TINY(1.0_dp))
      IF (training_rotation_response_sq <= component_floor) work_steps(1:nrot, :) = 0.0_dp
      IF (training_energy_response_sq <= component_floor) work_steps(nrot + 1:nfull, :) = 0.0_dp

      gram(:, :) = MATMUL(TRANSPOSE(work_steps), work_steps)
      determinant = gram(1, 1)*gram(2, 2) - gram(1, 2)*gram(2, 1)
      gram_scale = MAX(gram(1, 1)*gram(2, 2), TINY(1.0_dp))
      independence = SQRT(MAX(0.0_dp, determinant/gram_scale))
      fit_ready = determinant > SQRT(EPSILON(1.0_dp))*gram_scale
      IF (fit_ready) THEN
         gram_inverse(1, 1) = gram(2, 2)/determinant
         gram_inverse(1, 2) = -gram(1, 2)/determinant
         gram_inverse(2, 1) = -gram(2, 1)/determinant
         gram_inverse(2, 2) = gram(1, 1)/determinant
         work_matrix(:, :) = MATMUL(TRANSPOSE(work_steps), training_responses)
         work_matrix(:, :) = 0.5_dp*(work_matrix + TRANSPOSE(work_matrix))
         work_operator(:, :) = MATMUL(gram_inverse, MATMUL(work_matrix, gram_inverse))
         response_hessian(:, :) = MATMUL(work_steps, &
                                         MATMUL(work_operator, TRANSPOSE(work_steps)))
         fit_ready = ALL(response_hessian == response_hessian)
      END IF
      IF (.NOT. fit_ready) THEN
         DEALLOCATE (coordinate_scale, predicted_residual, predicted_response, response_hessian, &
                     training_residual, training_responses, training_steps, validation_response, &
                     validation_step, work_steps)
         RETURN
      END IF

      training_residual(:, :) = training_responses - MATMUL(response_hessian, training_steps)
      training_residual_sq = MAX(0.0_dp, SUM(training_residual**2))
      training_predicted_norm_sq = MAX(0.0_dp, SUM((training_responses - training_residual)**2))
      IF (MAX(training_response_norm_sq, training_predicted_norm_sq) > &
          EPSILON(MAX(training_response_norm_sq, training_predicted_norm_sq))) &
         training_quality = 1.0_dp - training_residual_sq/ &
                            MAX(training_response_norm_sq, training_predicted_norm_sq)
      predicted_response(:) = MATMUL(response_hessian, validation_step)
      predicted_residual(:) = validation_response - predicted_response
      validation_norm_sq = MAX(0.0_dp, DOT_PRODUCT(validation_response, validation_response))
      predicted_residual_sq = MAX(0.0_dp, DOT_PRODUCT(predicted_residual, predicted_residual))
      predicted_response_norm_sq = MAX(0.0_dp, DOT_PRODUCT(predicted_response, predicted_response))
      IF (MAX(validation_norm_sq, predicted_response_norm_sq) > &
          EPSILON(MAX(validation_norm_sq, predicted_response_norm_sq))) &
         validation_quality = 1.0_dp - predicted_residual_sq/ &
                              MAX(validation_norm_sq, predicted_response_norm_sq)
      IF (validation_norm_sq > EPSILON(validation_norm_sq)) &
         strict_validation_quality = 1.0_dp - predicted_residual_sq/validation_norm_sq
      rotation_response_norm_sq = MAX(0.0_dp, &
                                      DOT_PRODUCT(validation_response(1:nrot), &
                                                  validation_response(1:nrot)))
      predicted_rotation_residual_sq = MAX(0.0_dp, &
                                           DOT_PRODUCT(predicted_residual(1:nrot), &
                                                       predicted_residual(1:nrot)))
      predicted_rotation_response_sq = MAX(0.0_dp, &
                                           DOT_PRODUCT(predicted_response(1:nrot), &
                                                       predicted_response(1:nrot)))
      component_floor = 64.0_dp*EPSILON(1.0_dp)* &
                        MAX(validation_norm_sq, predicted_response_norm_sq, TINY(1.0_dp))
      IF (MAX(rotation_response_norm_sq, predicted_rotation_response_sq) > component_floor) THEN
         validation_rotation_quality = 1.0_dp - &
                                       predicted_rotation_residual_sq/ &
                                       MAX(rotation_response_norm_sq, predicted_rotation_response_sq)
      ELSE
         validation_rotation_quality = 1.0_dp
      END IF
      IF (rotation_response_norm_sq > EPSILON(rotation_response_norm_sq)) &
         strict_validation_rotation_quality = 1.0_dp - &
                                              predicted_rotation_residual_sq/ &
                                              rotation_response_norm_sq
      energy_response_norm_sq = MAX(0.0_dp, &
                                    DOT_PRODUCT(validation_response(nrot + 1:nfull), &
                                                validation_response(nrot + 1:nfull)))
      predicted_energy_residual_sq = MAX(0.0_dp, &
                                         DOT_PRODUCT(predicted_residual(nrot + 1:nfull), &
                                                     predicted_residual(nrot + 1:nfull)))
      predicted_energy_response_sq = MAX(0.0_dp, &
                                         DOT_PRODUCT(predicted_response(nrot + 1:nfull), &
                                                     predicted_response(nrot + 1:nfull)))
      IF (MAX(energy_response_norm_sq, predicted_energy_response_sq) > component_floor) THEN
         validation_energy_quality = 1.0_dp - predicted_energy_residual_sq/ &
                                     MAX(energy_response_norm_sq, predicted_energy_response_sq)
      ELSE
         validation_energy_quality = 1.0_dp
      END IF
      strict_component_floor = 64.0_dp*EPSILON(1.0_dp)*MAX(validation_norm_sq, TINY(1.0_dp))
      IF (energy_response_norm_sq > strict_component_floor) THEN
         strict_validation_energy_quality = 1.0_dp - &
                                            predicted_energy_residual_sq/energy_response_norm_sq
      ELSE IF (predicted_energy_residual_sq <= strict_component_floor) THEN
         strict_validation_energy_quality = 1.0_dp
      ELSE
         strict_validation_energy_quality = 1.0_dp - &
                                            predicted_energy_residual_sq/strict_component_floor
      END IF
      predicted_norm = SQRT(predicted_response_norm_sq)
      IF (validation_norm_sq > EPSILON(validation_norm_sq) .AND. &
          predicted_norm > EPSILON(predicted_norm)) &
         validation_alignment = DOT_PRODUCT(validation_response, predicted_response)/ &
                                (SQRT(validation_norm_sq)*predicted_norm)
      predicted_curvature = DOT_PRODUCT(validation_step, predicted_response)
      validation_curvature = DOT_PRODUCT(validation_step, validation_response)
      IF (ABS(predicted_curvature) > SQRT(EPSILON(1.0_dp))* &
          SQRT(MAX(0.0_dp, DOT_PRODUCT(validation_step, validation_step)))* &
          MAX(predicted_norm, EPSILON(1.0_dp))) &
         validation_curvature_ratio = validation_curvature/predicted_curvature

      ready = ALL(response_hessian == response_hessian) .AND. &
              independence == independence .AND. training_quality == training_quality .AND. &
              validation_quality == validation_quality .AND. &
              validation_rotation_quality == validation_rotation_quality .AND. &
              validation_energy_quality == validation_energy_quality .AND. &
              strict_validation_quality == strict_validation_quality .AND. &
              strict_validation_rotation_quality == strict_validation_rotation_quality .AND. &
              strict_validation_energy_quality == strict_validation_energy_quality .AND. &
              validation_alignment == validation_alignment .AND. &
              validation_curvature_ratio == validation_curvature_ratio
      IF (ready) THEN
         DO j = 1, nfull
            DO i = 1, nfull
               response_hessian(i, j) = response_hessian(i, j)* &
                                        coordinate_scale(i)*coordinate_scale(j)
            END DO
         END DO
         rotation_correction(:, :) = response_hessian(1:nrot, 1:nrot)
         energy_correction(:, :) = response_hessian(nrot + 1:nfull, nrot + 1:nfull)
         cross_correction(:, :) = -response_hessian(nrot + 1:nfull, 1:nrot)
      END IF
      DEALLOCATE (coordinate_scale, predicted_residual, predicted_response, response_hessian, &
                  training_residual, training_responses, training_steps, validation_response, &
                  validation_step, work_steps)

   END SUBROUTINE qs_scf_kp_coupled_response_multisecant_prediction

! **************************************************************************************************
!> \brief Cross-validate a local full-space self-consistent closure response.
!>
!>        Three accepted secants use a symmetric two-secant observable-work fit with leave-one-out
!>        validation.  With only two secants the bounded response-vector model remains the bootstrap
!>        fallback.  All fits use the dimensionally scaled fixed-N rotation/auxiliary-energy space.
!> \param rotation_hessian analytic complex-rotation block
!> \param energy_hessian analytic fixed-N auxiliary-energy block
!> \param energy_cross analytic signed cross block
!> \param rotation_steps accepted complex-rotation steps, newest pair first
!> \param energy_steps corresponding fixed-N auxiliary-energy steps
!> \param closure_rotation_targets measured self-consistent rotation-gradient response
!> \param closure_energy_targets measured self-consistent auxiliary-energy-gradient response
!> \param rotation_correction newest-trained rotation-block correction
!> \param energy_correction newest-trained auxiliary-energy-block correction
!> \param cross_correction newest-trained signed cross-block correction
!> \param finite whether all available prediction audits are finite
!> \param consistent whether all predictions pass the strict measured-response gate
!> \param overlap minimum scaled step overlap or two-step independence
!> \param capture minimum training-response quality
!> \param quality minimum bounded full-residual audit quality
!> \param rotation_quality minimum bounded rotation-residual audit quality
!> \param energy_quality minimum bounded auxiliary-energy-residual audit quality
!> \param alignment minimum response alignment
!> \param curvature_ratio_min minimum bidirectional response-curvature ratio
!> \param curvature_ratio_max maximum bidirectional response-curvature ratio
!> \param promotion_quality optional strict full-residual promotion quality
!> \param promotion_rotation_quality optional strict rotation-residual promotion quality
!> \param promotion_energy_quality optional strict auxiliary-energy-residual promotion quality
!> \param observable_work_quality optional minimum leave-one-out Hessian-work quality
!> \param observable_consistent optional consistency of the observable Hessian work
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_coupled_closure_prediction( &
      rotation_hessian, energy_hessian, energy_cross, rotation_steps, energy_steps, &
      closure_rotation_targets, closure_energy_targets, rotation_correction, &
      energy_correction, cross_correction, finite, consistent, overlap, capture, quality, &
      rotation_quality, energy_quality, alignment, curvature_ratio_min, curvature_ratio_max, &
      promotion_quality, promotion_rotation_quality, promotion_energy_quality, &
      observable_work_quality, observable_consistent)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN) :: rotation_hessian, energy_hessian, &
         energy_cross, rotation_steps, energy_steps, closure_rotation_targets, &
         closure_energy_targets
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: rotation_correction, energy_correction, &
                                                            cross_correction
      LOGICAL, INTENT(OUT)                               :: finite, consistent
      REAL(KIND=dp), INTENT(OUT) :: overlap, capture, quality, rotation_quality, energy_quality, &
         alignment, curvature_ratio_min, curvature_ratio_max
      REAL(KIND=dp), INTENT(OUT), OPTIONAL               :: promotion_quality, &
                                                            promotion_rotation_quality, &
                                                            promotion_energy_quality, &
                                                            observable_work_quality
      LOGICAL, INTENT(OUT), OPTIONAL                     :: observable_consistent

      INTEGER                                            :: nener, nobs, nrot
      LOGICAL                                            :: forward_finite, reverse_finite, &
                                                            third_finite
      REAL(KIND=dp) :: forward_alignment, forward_capture, forward_curvature_ratio, &
         forward_energy_quality, forward_overlap, forward_quality, forward_rotation_quality, &
         forward_strict_energy_quality, forward_strict_quality, forward_strict_rotation_quality, &
         reverse_alignment, reverse_capture, reverse_curvature_ratio, reverse_energy_quality, &
         reverse_overlap, reverse_quality, reverse_rotation_quality, &
         reverse_strict_energy_quality, reverse_strict_quality, reverse_strict_rotation_quality, &
         strict_energy_quality, strict_quality, strict_rotation_quality, third_alignment, &
         third_capture
      REAL(KIND=dp) :: third_curvature_ratio, third_energy_quality, third_overlap, third_quality, &
         third_rotation_quality, third_strict_energy_quality, third_strict_quality, &
         third_strict_rotation_quality, work_quality
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :) :: fold_energy_responses, fold_energy_steps, &
         fold_rotation_responses, fold_rotation_steps, forward_energy_cross, &
         forward_energy_hessian, forward_rotation_hessian, reverse_energy_cross, &
         reverse_energy_hessian, reverse_rotation_hessian, third_energy_cross, &
         third_energy_hessian, third_rotation_hessian

      nrot = SIZE(rotation_hessian, 1)
      nener = SIZE(energy_hessian, 1)
      nobs = SIZE(rotation_steps, 2)
      CPASSERT(ALL(SHAPE(rotation_hessian) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(energy_hessian) == [nener, nener]))
      CPASSERT(ALL(SHAPE(energy_cross) == [nener, nrot]))
      CPASSERT(nobs == 2 .OR. nobs == 3)
      CPASSERT(ALL(SHAPE(rotation_steps) == [nrot, nobs]))
      CPASSERT(ALL(SHAPE(energy_steps) == [nener, nobs]))
      CPASSERT(ALL(SHAPE(closure_rotation_targets) == [nrot, nobs]))
      CPASSERT(ALL(SHAPE(closure_energy_targets) == [nener, nobs]))
      CPASSERT(ALL(SHAPE(rotation_correction) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(energy_correction) == [nener, nener]))
      CPASSERT(ALL(SHAPE(cross_correction) == [nener, nrot]))

      rotation_correction(:, :) = 0.0_dp
      energy_correction(:, :) = 0.0_dp
      cross_correction(:, :) = 0.0_dp
      finite = .FALSE.
      consistent = .FALSE.
      overlap = 0.0_dp
      capture = 0.0_dp
      quality = 0.0_dp
      rotation_quality = 0.0_dp
      energy_quality = 0.0_dp
      alignment = 0.0_dp
      curvature_ratio_min = 0.0_dp
      curvature_ratio_max = 0.0_dp
      strict_quality = 0.0_dp
      strict_rotation_quality = 0.0_dp
      strict_energy_quality = 0.0_dp
      work_quality = 0.0_dp
      IF (PRESENT(promotion_quality)) promotion_quality = 0.0_dp
      IF (PRESENT(promotion_rotation_quality)) promotion_rotation_quality = 0.0_dp
      IF (PRESENT(promotion_energy_quality)) promotion_energy_quality = 0.0_dp
      IF (PRESENT(observable_work_quality)) observable_work_quality = 0.0_dp
      IF (PRESENT(observable_consistent)) observable_consistent = .FALSE.
      IF (nrot <= 0 .OR. nener <= 0) RETURN

      ALLOCATE (forward_energy_cross(nener, nrot), forward_energy_hessian(nener, nener), &
                forward_rotation_hessian(nrot, nrot), reverse_energy_cross(nener, nrot), &
                reverse_energy_hessian(nener, nener), reverse_rotation_hessian(nrot, nrot))

      IF (nobs == 3) THEN
         ALLOCATE (fold_energy_responses(nener, 2), fold_energy_steps(nener, 2), &
                   fold_rotation_responses(nrot, 2), fold_rotation_steps(nrot, 2), &
                   third_energy_cross(nener, nrot), third_energy_hessian(nener, nener), &
                   third_rotation_hessian(nrot, nrot))
         CALL qs_scf_kp_coupled_response_multisecant_prediction( &
            rotation_hessian, energy_hessian, rotation_steps(:, 1:2), energy_steps(:, 1:2), &
            closure_rotation_targets(:, 1:2), closure_energy_targets(:, 1:2), &
            rotation_steps(:, 3), energy_steps(:, 3), closure_rotation_targets(:, 3), &
            closure_energy_targets(:, 3), forward_rotation_hessian, forward_energy_hessian, &
            forward_energy_cross, forward_finite, forward_overlap, forward_capture, &
            forward_quality, forward_rotation_quality, forward_energy_quality, &
            forward_strict_quality, forward_strict_rotation_quality, &
            forward_strict_energy_quality, forward_alignment, forward_curvature_ratio)
         fold_rotation_steps(:, :) = rotation_steps(:, 2:3)
         fold_energy_steps(:, :) = energy_steps(:, 2:3)
         fold_rotation_responses(:, :) = closure_rotation_targets(:, 2:3)
         fold_energy_responses(:, :) = closure_energy_targets(:, 2:3)
         CALL qs_scf_kp_coupled_response_multisecant_prediction( &
            rotation_hessian, energy_hessian, fold_rotation_steps, fold_energy_steps, &
            fold_rotation_responses, fold_energy_responses, rotation_steps(:, 1), &
            energy_steps(:, 1), closure_rotation_targets(:, 1), closure_energy_targets(:, 1), &
            reverse_rotation_hessian, reverse_energy_hessian, reverse_energy_cross, reverse_finite, &
            reverse_overlap, reverse_capture, reverse_quality, reverse_rotation_quality, &
            reverse_energy_quality, reverse_strict_quality, reverse_strict_rotation_quality, &
            reverse_strict_energy_quality, reverse_alignment, reverse_curvature_ratio)
         fold_rotation_steps(:, 1) = rotation_steps(:, 3)
         fold_rotation_steps(:, 2) = rotation_steps(:, 1)
         fold_energy_steps(:, 1) = energy_steps(:, 3)
         fold_energy_steps(:, 2) = energy_steps(:, 1)
         fold_rotation_responses(:, 1) = closure_rotation_targets(:, 3)
         fold_rotation_responses(:, 2) = closure_rotation_targets(:, 1)
         fold_energy_responses(:, 1) = closure_energy_targets(:, 3)
         fold_energy_responses(:, 2) = closure_energy_targets(:, 1)
         CALL qs_scf_kp_coupled_response_multisecant_prediction( &
            rotation_hessian, energy_hessian, fold_rotation_steps, fold_energy_steps, &
            fold_rotation_responses, fold_energy_responses, rotation_steps(:, 2), &
            energy_steps(:, 2), closure_rotation_targets(:, 2), closure_energy_targets(:, 2), &
            third_rotation_hessian, third_energy_hessian, third_energy_cross, third_finite, &
            third_overlap, third_capture, third_quality, third_rotation_quality, &
            third_energy_quality, third_strict_quality, third_strict_rotation_quality, &
            third_strict_energy_quality, third_alignment, third_curvature_ratio)
         finite = forward_finite .AND. reverse_finite .AND. third_finite
         IF (finite) THEN
            overlap = MIN(forward_overlap, reverse_overlap, third_overlap)
            capture = MIN(forward_capture, reverse_capture, third_capture)
            quality = MIN(forward_quality, reverse_quality, third_quality)
            rotation_quality = MIN(forward_rotation_quality, reverse_rotation_quality, &
                                   third_rotation_quality)
            energy_quality = MIN(forward_energy_quality, reverse_energy_quality, third_energy_quality)
            strict_quality = MIN(forward_strict_quality, reverse_strict_quality, &
                                 third_strict_quality)
            strict_rotation_quality = MIN(forward_strict_rotation_quality, &
                                          reverse_strict_rotation_quality, &
                                          third_strict_rotation_quality)
            strict_energy_quality = MIN(forward_strict_energy_quality, &
                                        reverse_strict_energy_quality, &
                                        third_strict_energy_quality)
            alignment = MIN(forward_alignment, reverse_alignment, third_alignment)
            curvature_ratio_min = MIN(forward_curvature_ratio, reverse_curvature_ratio, &
                                      third_curvature_ratio)
            curvature_ratio_max = MAX(forward_curvature_ratio, reverse_curvature_ratio, &
                                      third_curvature_ratio)
            work_quality = MIN(qs_scf_kp_observable_work_quality(forward_curvature_ratio), &
                               qs_scf_kp_observable_work_quality(reverse_curvature_ratio), &
                               qs_scf_kp_observable_work_quality(third_curvature_ratio))
            consistent = strict_quality >= ot_kp_schur_prediction_quality_min .AND. &
                         strict_rotation_quality >= ot_kp_schur_prediction_quality_min .AND. &
                         strict_energy_quality >= ot_kp_schur_prediction_energy_quality_min .AND. &
                         alignment >= ot_kp_schur_prediction_alignment_min .AND. &
                         curvature_ratio_min >= ot_kp_schur_prediction_curvature_ratio_min .AND. &
                         curvature_ratio_max <= ot_kp_schur_prediction_curvature_ratio_max
            IF (PRESENT(observable_consistent)) &
               observable_consistent = work_quality >= ot_kp_schur_prediction_quality_min .AND. &
                                       curvature_ratio_min >= &
                                       ot_kp_schur_prediction_curvature_ratio_min .AND. &
                                       curvature_ratio_max <= &
                                       ot_kp_schur_prediction_curvature_ratio_max
            rotation_correction(:, :) = forward_rotation_hessian
            energy_correction(:, :) = forward_energy_hessian
            cross_correction(:, :) = forward_energy_cross
         END IF
         IF (PRESENT(promotion_quality)) promotion_quality = strict_quality
         IF (PRESENT(promotion_rotation_quality)) &
            promotion_rotation_quality = strict_rotation_quality
         IF (PRESENT(promotion_energy_quality)) promotion_energy_quality = strict_energy_quality
         IF (PRESENT(observable_work_quality)) observable_work_quality = work_quality
         DEALLOCATE (fold_energy_responses, fold_energy_steps, fold_rotation_responses, &
                     fold_rotation_steps, third_energy_cross, third_energy_hessian, &
                     third_rotation_hessian)
         DEALLOCATE (forward_energy_cross, forward_energy_hessian, forward_rotation_hessian, &
                     reverse_energy_cross, reverse_energy_hessian, reverse_rotation_hessian)
         RETURN
      END IF

      CALL qs_scf_kp_coupled_response_secant_prediction( &
         rotation_hessian, energy_hessian, rotation_steps(:, 1), energy_steps(:, 1), &
         closure_rotation_targets(:, 1), closure_energy_targets(:, 1), rotation_steps(:, 2), &
         energy_steps(:, 2), closure_rotation_targets(:, 2), closure_energy_targets(:, 2), &
         forward_rotation_hessian, forward_energy_hessian, forward_energy_cross, forward_finite, &
         forward_overlap, forward_capture, forward_quality, forward_rotation_quality, &
         forward_energy_quality, forward_strict_quality, forward_strict_rotation_quality, &
         forward_strict_energy_quality, forward_alignment, forward_curvature_ratio)
      CALL qs_scf_kp_coupled_response_secant_prediction( &
         rotation_hessian, energy_hessian, rotation_steps(:, 2), energy_steps(:, 2), &
         closure_rotation_targets(:, 2), closure_energy_targets(:, 2), rotation_steps(:, 1), &
         energy_steps(:, 1), closure_rotation_targets(:, 1), closure_energy_targets(:, 1), &
         reverse_rotation_hessian, reverse_energy_hessian, reverse_energy_cross, reverse_finite, &
         reverse_overlap, reverse_capture, reverse_quality, reverse_rotation_quality, &
         reverse_energy_quality, reverse_strict_quality, reverse_strict_rotation_quality, &
         reverse_strict_energy_quality, reverse_alignment, reverse_curvature_ratio)

      finite = forward_finite .AND. reverse_finite
      IF (finite) THEN
         overlap = MIN(forward_overlap, reverse_overlap)
         capture = MIN(forward_capture, reverse_capture)
         quality = MIN(forward_quality, reverse_quality)
         rotation_quality = MIN(forward_rotation_quality, reverse_rotation_quality)
         energy_quality = MIN(forward_energy_quality, reverse_energy_quality)
         strict_quality = MIN(forward_strict_quality, reverse_strict_quality)
         strict_rotation_quality = MIN(forward_strict_rotation_quality, &
                                       reverse_strict_rotation_quality)
         strict_energy_quality = MIN(forward_strict_energy_quality, reverse_strict_energy_quality)
         alignment = MIN(forward_alignment, reverse_alignment)
         curvature_ratio_min = MIN(forward_curvature_ratio, reverse_curvature_ratio)
         curvature_ratio_max = MAX(forward_curvature_ratio, reverse_curvature_ratio)
         work_quality = MIN(qs_scf_kp_observable_work_quality(forward_curvature_ratio), &
                            qs_scf_kp_observable_work_quality(reverse_curvature_ratio))
         ! The response-vector secant is identified by its measured y directions.  Unlike the
         ! older step-direction update it does not require nearly parallel accepted steps or a
         ! large projection of y onto s: exact out-of-sample response, component quality and
         ! curvature consistency are the relevant observability tests.
         consistent = forward_strict_quality >= ot_kp_schur_prediction_quality_min .AND. &
                      reverse_strict_quality >= ot_kp_schur_prediction_quality_min .AND. &
                      forward_strict_rotation_quality >= ot_kp_schur_prediction_quality_min .AND. &
                      reverse_strict_rotation_quality >= ot_kp_schur_prediction_quality_min .AND. &
                      forward_strict_energy_quality >= &
                      ot_kp_schur_prediction_energy_quality_min .AND. &
                      reverse_strict_energy_quality >= &
                      ot_kp_schur_prediction_energy_quality_min .AND. &
                      forward_alignment >= ot_kp_schur_prediction_alignment_min .AND. &
                      reverse_alignment >= ot_kp_schur_prediction_alignment_min .AND. &
                      forward_curvature_ratio >= ot_kp_schur_prediction_curvature_ratio_min .AND. &
                      reverse_curvature_ratio >= ot_kp_schur_prediction_curvature_ratio_min .AND. &
                      forward_curvature_ratio <= ot_kp_schur_prediction_curvature_ratio_max .AND. &
                      reverse_curvature_ratio <= ot_kp_schur_prediction_curvature_ratio_max
         IF (PRESENT(observable_consistent)) &
            observable_consistent = work_quality >= ot_kp_schur_prediction_quality_min .AND. &
                                    curvature_ratio_min >= &
                                    ot_kp_schur_prediction_curvature_ratio_min .AND. &
                                    curvature_ratio_max <= &
                                    ot_kp_schur_prediction_curvature_ratio_max
         rotation_correction(:, :) = reverse_rotation_hessian
         energy_correction(:, :) = reverse_energy_hessian
         cross_correction(:, :) = reverse_energy_cross
      END IF
      IF (PRESENT(promotion_quality)) promotion_quality = strict_quality
      IF (PRESENT(promotion_rotation_quality)) promotion_rotation_quality = strict_rotation_quality
      IF (PRESENT(promotion_energy_quality)) promotion_energy_quality = strict_energy_quality
      IF (PRESENT(observable_work_quality)) observable_work_quality = work_quality
      DEALLOCATE (forward_energy_cross, forward_energy_hessian, forward_rotation_hessian, &
                  reverse_energy_cross, reverse_energy_hessian, reverse_rotation_hessian)

   END SUBROUTINE qs_scf_kp_coupled_closure_prediction

! **************************************************************************************************
!> \brief Cross-validate a low-rank correction to the analytic coupled fixed-N Hessian.
!>
!>        The measured total finite secants are reduced to residual responses
!>
!>          R = Y - [H_RR,-B^T;-B,H_ee] S .
!>
!>        Fitting R rather than the raw self-consistent closure preserves the analytic Hessian in
!>        the unobserved complement and prevents an already represented curvature from being added
!>        a second time.  The returned blocks are corrections, not complete Hessian blocks.
!> \param rotation_hessian analytic complex-rotation block
!> \param energy_hessian analytic fixed-N auxiliary-energy block
!> \param energy_cross analytic signed cross block
!> \param rotation_steps accepted complex-rotation steps
!> \param energy_steps accepted auxiliary-energy steps
!> \param total_rotation_targets measured total rotation-gradient secants
!> \param total_energy_targets measured total auxiliary-energy-gradient secants
!> \param rotation_correction fitted residual rotation block
!> \param energy_correction fitted residual auxiliary-energy block
!> \param cross_correction fitted residual signed cross block
!> \param finite whether all prediction audits are finite
!> \param consistent whether strict residual-vector prediction is consistent
!> \param overlap minimum step observability
!> \param capture minimum residual-response capture
!> \param quality bounded full-residual prediction quality
!> \param rotation_quality bounded rotation-residual prediction quality
!> \param energy_quality bounded auxiliary-energy-residual prediction quality
!> \param alignment minimum residual-response alignment
!> \param curvature_ratio_min minimum residual-work ratio
!> \param curvature_ratio_max maximum residual-work ratio
!> \param promotion_quality optional strict full-residual promotion quality
!> \param promotion_rotation_quality optional strict rotation-residual promotion quality
!> \param promotion_energy_quality optional strict auxiliary-energy-residual promotion quality
!> \param observable_work_quality optional minimum observable residual-work quality
!> \param observable_consistent optional consistency of observable residual work
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_coupled_residual_prediction( &
      rotation_hessian, energy_hessian, energy_cross, rotation_steps, energy_steps, &
      total_rotation_targets, total_energy_targets, rotation_correction, energy_correction, &
      cross_correction, finite, consistent, overlap, capture, quality, rotation_quality, &
      energy_quality, alignment, curvature_ratio_min, curvature_ratio_max, promotion_quality, &
      promotion_rotation_quality, promotion_energy_quality, observable_work_quality, &
      observable_consistent)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN) :: rotation_hessian, energy_hessian, &
         energy_cross, rotation_steps, energy_steps, total_rotation_targets, total_energy_targets
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: rotation_correction, energy_correction, &
                                                            cross_correction
      LOGICAL, INTENT(OUT)                               :: finite, consistent
      REAL(KIND=dp), INTENT(OUT) :: overlap, capture, quality, rotation_quality, energy_quality, &
         alignment, curvature_ratio_min, curvature_ratio_max
      REAL(KIND=dp), INTENT(OUT), OPTIONAL               :: promotion_quality, &
                                                            promotion_rotation_quality, &
                                                            promotion_energy_quality, &
                                                            observable_work_quality
      LOGICAL, INTENT(OUT), OPTIONAL                     :: observable_consistent

      INTEGER                                            :: iobs, nener, nobs, nrot
      LOGICAL                                            :: work_consistent
      REAL(KIND=dp)                                      :: strict_energy_quality, strict_quality, &
                                                            strict_rotation_quality, work_quality
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: residual_energy_targets, &
                                                            residual_rotation_targets

      nrot = SIZE(rotation_hessian, 1)
      nener = SIZE(energy_hessian, 1)
      nobs = SIZE(rotation_steps, 2)
      CPASSERT(ALL(SHAPE(rotation_hessian) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(energy_hessian) == [nener, nener]))
      CPASSERT(ALL(SHAPE(energy_cross) == [nener, nrot]))
      CPASSERT(ALL(SHAPE(rotation_steps) == [nrot, nobs]))
      CPASSERT(ALL(SHAPE(energy_steps) == [nener, nobs]))
      CPASSERT(ALL(SHAPE(total_rotation_targets) == [nrot, nobs]))
      CPASSERT(ALL(SHAPE(total_energy_targets) == [nener, nobs]))
      CPASSERT(ALL(SHAPE(rotation_correction) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(energy_correction) == [nener, nener]))
      CPASSERT(ALL(SHAPE(cross_correction) == [nener, nrot]))

      ALLOCATE (residual_rotation_targets(nrot, nobs), residual_energy_targets(nener, nobs))
      DO iobs = 1, nobs
         residual_rotation_targets(:, iobs) = total_rotation_targets(:, iobs) - &
                                              MATMUL(rotation_hessian, rotation_steps(:, iobs)) + &
                                              MATMUL(TRANSPOSE(energy_cross), energy_steps(:, iobs))
         residual_energy_targets(:, iobs) = total_energy_targets(:, iobs) - &
                                            MATMUL(energy_hessian, energy_steps(:, iobs)) + &
                                            MATMUL(energy_cross, rotation_steps(:, iobs))
      END DO
      CALL qs_scf_kp_coupled_closure_prediction( &
         rotation_hessian, energy_hessian, energy_cross, rotation_steps, energy_steps, &
         residual_rotation_targets, residual_energy_targets, rotation_correction, &
         energy_correction, cross_correction, finite, consistent, overlap, capture, quality, &
         rotation_quality, energy_quality, alignment, curvature_ratio_min, curvature_ratio_max, &
         strict_quality, strict_rotation_quality, strict_energy_quality, work_quality, &
         work_consistent)
      IF (PRESENT(promotion_quality)) promotion_quality = strict_quality
      IF (PRESENT(promotion_rotation_quality)) promotion_rotation_quality = strict_rotation_quality
      IF (PRESENT(promotion_energy_quality)) promotion_energy_quality = strict_energy_quality
      IF (PRESENT(observable_work_quality)) observable_work_quality = work_quality
      IF (PRESENT(observable_consistent)) observable_consistent = work_consistent
      DEALLOCATE (residual_rotation_targets, residual_energy_targets)

   END SUBROUTINE qs_scf_kp_coupled_residual_prediction

! **************************************************************************************************
!> \brief Return a scale-invariant quality for an observed/predicted scalar Hessian work ratio.
!>
!>        The response-vector audit can see endpoint gauge components perpendicular to the tested
!>        step.  Those components do not contribute to the physically observable quadratic work
!>        s^T*H*s.  This scalar audit is one for exact work, 0.75 for a factor-two mismatch, and
!>        nonpositive for an opposite-sign prediction.  A zero ratio remains uninformative.
!> \param curvature_ratio ...
!> \return ...
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_observable_work_quality(curvature_ratio) RESULT(quality)
      REAL(KIND=dp), INTENT(IN)                          :: curvature_ratio
      REAL(KIND=dp)                                      :: quality

      quality = 0.0_dp
      IF (curvature_ratio /= curvature_ratio .OR. curvature_ratio == 0.0_dp) RETURN
      IF (ABS(curvature_ratio) <= 1.0_dp) THEN
         quality = 1.0_dp - (1.0_dp - curvature_ratio)**2
      ELSE
         quality = 1.0_dp - (1.0_dp - 1.0_dp/curvature_ratio)**2
      END IF

   END FUNCTION qs_scf_kp_observable_work_quality

! **************************************************************************************************
!> \brief Evaluate a coupled rotation/energy Hessian on one fixed-N Mermin step.
!> \param rotation_gradient rotation gradient in descent-vector convention
!> \param energy_gradient auxiliary-energy gradient in descent-vector convention
!> \param rotation_hessian rotation block H_RR
!> \param energy_hessian fixed-N auxiliary-energy block H_ee
!> \param energy_cross signed block B for the full Hessian [H_RR,-B^T;-B,H_ee]
!> \param rotation_step accepted rotation step
!> \param energy_step accepted auxiliary-energy step
!> \param model_slope linear predicted decrease g^T x
!> \param model_quadratic quadratic curvature x^T H x
!> \param model_drop quadratic predicted Mermin decrease
!> \param ready whether all model values are finite
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_coupled_step_model(rotation_gradient, energy_gradient, &
                                           rotation_hessian, energy_hessian, energy_cross, &
                                           rotation_step, energy_step, model_slope, &
                                           model_quadratic, model_drop, ready)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: rotation_gradient, energy_gradient
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: rotation_hessian, energy_hessian, &
                                                            energy_cross
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: rotation_step, energy_step
      REAL(KIND=dp), INTENT(OUT)                         :: model_slope, model_quadratic, model_drop
      LOGICAL, INTENT(OUT)                               :: ready

      INTEGER                                            :: nener, nrot

      nrot = SIZE(rotation_step)
      nener = SIZE(energy_step)
      CPASSERT(SIZE(rotation_gradient) == nrot)
      CPASSERT(SIZE(energy_gradient) == nener)
      CPASSERT(ALL(SHAPE(rotation_hessian) == [nrot, nrot]))
      CPASSERT(ALL(SHAPE(energy_hessian) == [nener, nener]))
      CPASSERT(ALL(SHAPE(energy_cross) == [nener, nrot]))

      model_slope = DOT_PRODUCT(rotation_gradient, rotation_step) + &
                    DOT_PRODUCT(energy_gradient, energy_step)
      model_quadratic = DOT_PRODUCT(rotation_step, MATMUL(rotation_hessian, rotation_step)) + &
                        DOT_PRODUCT(energy_step, MATMUL(energy_hessian, energy_step)) - &
                        2.0_dp*DOT_PRODUCT(energy_step, MATMUL(energy_cross, rotation_step))
      model_drop = MAX(0.0_dp, model_slope - 0.5_dp*model_quadratic)
      ready = model_slope == model_slope .AND. model_quadratic == model_quadratic .AND. &
              model_drop == model_drop .AND. ABS(model_slope) < HUGE(model_slope) .AND. &
              ABS(model_quadratic) < HUGE(model_quadratic) .AND. model_drop < HUGE(model_drop)
      IF (.NOT. ready) THEN
         model_slope = 0.0_dp
         model_quadratic = 0.0_dp
         model_drop = 0.0_dp
      END IF

   END SUBROUTINE qs_scf_kp_coupled_step_model

! **************************************************************************************************
!> \brief Decide whether accepted Mermin drops promote a secant candidate.
!> \param samples number of accepted candidate probes
!> \param min_samples minimum number of probes
!> \param predicted_sum accumulated predicted Mermin drop
!> \param measured_sum accumulated accepted Mermin drop
!> \param quality most recent accepted/predicted drop ratio
!> \param quality_ema exponential average of the drop ratio
!> \param residual_quality most recent accepted residual improvement
!> \param residual_quality_ema exponential average of residual improvement
!> \param min_quality minimum aggregate and averaged quality
!> \return whether the candidate has repeatable accepted-step support
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_secant_candidate_promoted(samples, min_samples, predicted_sum, measured_sum, &
                                                     quality, quality_ema, residual_quality, &
                                                     residual_quality_ema, min_quality) RESULT(promoted)
      INTEGER, INTENT(IN)                                :: samples, min_samples
      REAL(KIND=dp), INTENT(IN)                          :: predicted_sum, measured_sum, quality, &
                                                            quality_ema, residual_quality, &
                                                            residual_quality_ema, min_quality
      LOGICAL                                            :: promoted

      promoted = samples >= min_samples .AND. predicted_sum > EPSILON(1.0_dp) .AND. &
                 measured_sum > 0.0_dp .AND. measured_sum/predicted_sum >= min_quality .AND. &
                 quality_ema >= min_quality .AND. quality >= 0.5_dp*min_quality .AND. &
                 residual_quality_ema >= min_quality .AND. &
                 residual_quality >= 0.5_dp*min_quality

   END FUNCTION qs_scf_kp_secant_candidate_promoted

! **************************************************************************************************
!> \brief Admit one uncalibrated measured-response candidate without weakening later promotion.
!> \param samples number of already accepted candidate probes
!> \param measured_response whether the candidate is built only from accepted response pairs
!> \param trust_quality response/trust compatibility in [0,1]
!> \param predicted_residual_ratio minimum physical rotation residual on the candidate ray,
!>        relative to the current state
!> \param expected_drop calibrated candidate Mermin decrease
!> \param reference_drop calibrated decrease of the established candidate
!> \return whether this is a strict first Pareto probe
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_secant_bootstrap_probe( &
      samples, measured_response, trust_quality, predicted_residual_ratio, expected_drop, &
      reference_drop) RESULT(probe)
      INTEGER, INTENT(IN)                                :: samples
      LOGICAL, INTENT(IN)                                :: measured_response
      REAL(KIND=dp), INTENT(IN)                          :: trust_quality, predicted_residual_ratio, &
                                                            expected_drop, reference_drop
      LOGICAL                                            :: probe

      probe = samples == 0 .AND. measured_response .AND. trust_quality >= 0.9_dp .AND. &
              predicted_residual_ratio >= 0.0_dp .AND. &
              predicted_residual_ratio < 1.0_dp - 64.0_dp*EPSILON(1.0_dp) .AND. &
              reference_drop > EPSILON(reference_drop) .AND. expected_drop >= reference_drop

   END FUNCTION qs_scf_kp_secant_bootstrap_probe

! **************************************************************************************************
!> \brief Continue measured-response calibration only after a successful accepted probe.
!> \param samples number of already accepted candidate probes
!> \param min_samples number of accepted probes required for promotion
!> \param measured_response whether the candidate is built only from accepted response pairs
!> \param quality most recent accepted/predicted Mermin-drop ratio
!> \param quality_ema exponential average of the Mermin-drop ratio
!> \param residual_quality most recent accepted physical-residual quality
!> \param residual_quality_ema exponential average of physical-residual quality
!> \param trust_quality response/trust compatibility in [0,1]
!> \param predicted_residual_ratio predicted physical rotation residual relative to the current state
!> \param expected_drop calibrated candidate Mermin decrease
!> \param reference_drop calibrated decrease of the established candidate
!> \param min_quality minimum accepted calibration quality
!> \return whether another pre-promotion calibration probe is justified
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_secant_calibration_probe( &
      samples, min_samples, measured_response, quality, quality_ema, residual_quality, &
      residual_quality_ema, trust_quality, predicted_residual_ratio, expected_drop, &
      reference_drop, min_quality) RESULT(probe)
      INTEGER, INTENT(IN)                                :: samples, min_samples
      LOGICAL, INTENT(IN)                                :: measured_response
      REAL(KIND=dp), INTENT(IN) :: quality, quality_ema, residual_quality, residual_quality_ema, &
         trust_quality, predicted_residual_ratio, expected_drop, reference_drop, min_quality
      LOGICAL                                            :: probe

      probe = samples > 0 .AND. samples < min_samples .AND. measured_response .AND. &
              quality >= min_quality .AND. quality_ema >= min_quality .AND. &
              residual_quality >= min_quality .AND. residual_quality_ema >= min_quality .AND. &
              trust_quality >= 0.9_dp .AND. predicted_residual_ratio >= 0.0_dp .AND. &
              predicted_residual_ratio < 1.0_dp - 64.0_dp*EPSILON(1.0_dp) .AND. &
              reference_drop > EPSILON(reference_drop) .AND. &
              expected_drop >= reference_drop

   END FUNCTION qs_scf_kp_secant_calibration_probe

! **************************************************************************************************
!> \brief Stage the coupled occupation response only inside its local metallic basin.
!> \param requested user requested OCCUPATION_PRECONDITIONER
!> \param complex_state complex k-point channel rather than real/Gamma OT
!> \param at_search_boundary current point can start a fresh search model
!> \param closure_rejected current coupled search failed its residual closure
!> \param closure_reference_safe rejected search returned to a stationary fixed-N tail reference
!> \param residual_delta effective residual of the accepted reference state
!> \param previous_active previous runtime state
!> \param previous_samples consecutive bootstrap samples already collected
!> \param active updated runtime state
!> \param samples updated consecutive bootstrap samples
!> \param changed whether the runtime model changed
! **************************************************************************************************
   PURE SUBROUTINE qs_scf_kp_occ_preconditioner_transition(requested, complex_state, &
                                                           at_search_boundary, closure_rejected, &
                                                           closure_reference_safe, &
                                                           residual_delta, previous_active, &
                                                           previous_samples, active, samples, changed)
      LOGICAL, INTENT(IN)                                :: requested, complex_state, &
                                                            at_search_boundary, closure_rejected, &
                                                            closure_reference_safe
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta
      LOGICAL, INTENT(IN)                                :: previous_active
      INTEGER, INTENT(IN)                                :: previous_samples
      LOGICAL, INTENT(OUT)                               :: active
      INTEGER, INTENT(OUT)                               :: samples
      LOGICAL, INTENT(OUT)                               :: changed

      active = previous_active
      samples = MAX(0, previous_samples)

      IF (.NOT. requested) THEN
         active = .FALSE.
         samples = 0
      ELSE IF (.NOT. complex_state) THEN
         active = .TRUE.
         samples = 0
      ELSE IF (active) THEN
         IF ((closure_rejected .AND. .NOT. closure_reference_safe) .OR. &
             (at_search_boundary .AND. residual_delta > ot_kp_occ_preconditioner_release_delta)) THEN
            active = .FALSE.
            samples = 0
         END IF
      ELSE IF (closure_rejected) THEN
         samples = 0
      ELSE IF (at_search_boundary) THEN
         IF (residual_delta > 0.0_dp .AND. &
             residual_delta <= ot_kp_occ_preconditioner_bootstrap_delta) THEN
            samples = MIN(samples + 1, ot_kp_occ_preconditioner_bootstrap_samples)
            active = samples >= ot_kp_occ_preconditioner_bootstrap_samples
         ELSE
            samples = 0
         END IF
      END IF

      changed = active .NEQV. previous_active

   END SUBROUTINE qs_scf_kp_occ_preconditioner_transition

! **************************************************************************************************
!> \brief Remove the spin-degeneracy scale already carried by a k-point OT orbital gradient.
!> \param maxocc maximum occupation of one spatial orbital
!> \return objective normalization for a state-selective orbital Hessian inverse
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_full_all_spin_normalization(maxocc) RESULT(scale)
      REAL(KIND=dp), INTENT(IN)                          :: maxocc
      REAL(KIND=dp)                                      :: scale

      scale = 1.0_dp
      IF (maxocc > EPSILON(maxocc)) scale = 1.0_dp/maxocc

   END FUNCTION qs_scf_kp_full_all_spin_normalization

! **************************************************************************************************
!> \brief Continue from the physical occupation-weighted orbital metric to full unweighting.
!> \param full_scale exact inverse-occupation scale requested by the local Hessian model
!> \param accepted_samples number of accepted Mermin model-quality samples
!> \param accepted_quality_ema accepted/predicted Mermin-drop quality
!> \param residual_quality_ema accepted residual-improvement quality
!> \return history-calibrated metric scale
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_occ_metric_continuation(full_scale, accepted_samples, &
                                                   accepted_quality_ema, residual_quality_ema) &
      RESULT(scale)
      REAL(KIND=dp), INTENT(IN)                          :: full_scale
      INTEGER, INTENT(IN)                                :: accepted_samples
      REAL(KIND=dp), INTENT(IN)                          :: accepted_quality_ema, &
                                                            residual_quality_ema
      REAL(KIND=dp)                                      :: scale

      REAL(KIND=dp)                                      :: progress, quality

      scale = 1.0_dp
      IF (full_scale <= 1.0_dp .OR. accepted_samples <= 0) RETURN

      quality = MAX(0.0_dp, MIN(1.0_dp, accepted_quality_ema, residual_quality_ema))
      progress = MIN(1.0_dp, REAL(accepted_samples, KIND=dp)/ &
                     REAL(ot_kp_occ_metric_continuation_samples, KIND=dp))
      progress = progress*quality
      scale = EXP(progress*LOG(full_scale))

   END FUNCTION qs_scf_kp_occ_metric_continuation

! **************************************************************************************************
!> \brief Remove thermally inactive equal-occupation gauge coordinates from a dense Schur solve.
!> \param hessian symmetric rotation Schur block
!> \param rhs rotation gradient after fixed-N energy elimination
!> \param occupation_gap normalized occupation difference of each rotation coordinate
!> \param thermal_activity normalized f(1-f) response of each rotation coordinate
!> \param gauge_gap_max largest occupation gap classified as gauge-like
!> \param activity_max largest thermal response classified as inactive
!> \param gauge_diagonal positive diagonal assigned to projected coordinates
!> \param nprojected number of removed gauge coordinates
!> \param info zero on success, negative for inconsistent input
! **************************************************************************************************
   SUBROUTINE qs_scf_kp_decouple_inactive_gauge(hessian, rhs, occupation_gap, thermal_activity, &
                                                gauge_gap_max, activity_max, gauge_diagonal, &
                                                nprojected, info)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(INOUT)      :: hessian
      REAL(KIND=dp), DIMENSION(:), INTENT(INOUT)         :: rhs
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: occupation_gap, thermal_activity
      REAL(KIND=dp), INTENT(IN)                          :: gauge_gap_max, activity_max, &
                                                            gauge_diagonal
      INTEGER, INTENT(OUT)                               :: nprojected, info

      INTEGER                                            :: i, n
      REAL(KIND=dp)                                      :: diagonal

      n = SIZE(rhs)
      nprojected = 0
      info = 0
      IF (n <= 0 .OR. SIZE(hessian, 1) /= n .OR. SIZE(hessian, 2) /= n .OR. &
          SIZE(occupation_gap) /= n .OR. SIZE(thermal_activity) /= n) THEN
         info = -1
         RETURN
      END IF

      diagonal = MAX(gauge_diagonal, SQRT(EPSILON(1.0_dp)))
      DO i = 1, n
         IF (occupation_gap(i) > gauge_gap_max .OR. thermal_activity(i) > activity_max) CYCLE
         hessian(i, :) = 0.0_dp
         hessian(:, i) = 0.0_dp
         hessian(i, i) = diagonal
         rhs(i) = 0.0_dp
         nprojected = nprojected + 1
      END DO

   END SUBROUTINE qs_scf_kp_decouple_inactive_gauge

! **************************************************************************************************
!> \brief post-resize convergence gate length for k-point ADDED_MOS AUTO
!> \return number of SCF iterations kept open after a k-point AUTO resize
! **************************************************************************************************
   FUNCTION qs_scf_kp_added_mos_auto_post_resize_steps() RESULT(nsteps)

      INTEGER                                            :: nsteps

      nsteps = ot_kp_added_mos_auto_tail_probe_steps

   END FUNCTION qs_scf_kp_added_mos_auto_post_resize_steps

! **************************************************************************************************
!> \brief Classify loss of a thermally resolved Fermi-window occupation.
!> \param max_partial_fraction largest min(f,1-f) over represented bands
!> \return true when the represented subspace no longer resolves the thermal frontier
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_subspace_is_collapsed(max_partial_fraction) RESULT(collapsed)
      REAL(KIND=dp), INTENT(IN)                          :: max_partial_fraction
      LOGICAL                                            :: collapsed

      collapsed = max_partial_fraction < &
                  MAX(ot_kp_fermi_window_min_frac, 0.25_dp*ot_kp_fermi_window_tail_fraction)

   END FUNCTION qs_scf_kp_subspace_is_collapsed

! **************************************************************************************************
!> \brief Check whether ADDED_MOS AUTO has left its small-buffer bootstrap before density closure.
!> \param added_mos_auto whether the channel uses adaptive virtual-space growth
!> \param current_added current added-MO buffer
!> \param nmo total represented MOs
!> \return true when density closure cannot preempt the AUTO bootstrap probe
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_density_closure_buffer_ready( &
      added_mos_auto, current_added, nmo) RESULT(ready)

      LOGICAL, INTENT(IN)                                :: added_mos_auto
      INTEGER, INTENT(IN)                                :: current_added, nmo
      LOGICAL                                            :: ready

      INTEGER                                            :: base_nmo, nonedge_probe_limit

      ready = .TRUE.
      IF (.NOT. added_mos_auto) RETURN
      base_nmo = MAX(0, nmo - MAX(0, current_added))
      nonedge_probe_limit = MAX(8, (base_nmo + 3)/4)
      ready = current_added > nonedge_probe_limit

   END FUNCTION qs_scf_kp_density_closure_buffer_ready

! **************************************************************************************************
!> \brief Decide when canonical density closure is the dominant asymptotic k-point OT block.
!>
!>        The physical OT residual need not already satisfy EPS_SCF. It must, however, lie below
!>        the geometric transition sqrt(EPS_SCF*density_delta), so that its remaining error is
!>        higher order relative to the independently measured canonical fixed-N density block.
!> \param physical_delta complete physical OT residual
!> \param density_delta canonical fixed-N density stationarity residual
!> \param eps_scf requested SCF threshold
!> \return true when canonical density closure is the dominant asymptotic block
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_density_closure_refresh_ready( &
      physical_delta, density_delta, eps_scf) RESULT(ready)

      REAL(KIND=dp), INTENT(IN)                          :: physical_delta, density_delta, eps_scf
      LOGICAL                                            :: ready

      REAL(KIND=dp)                                      :: asymptotic_delta, closure_crossover, eps

      eps = MAX(eps_scf, EPSILON(1.0_dp))
      asymptotic_delta = MAX(eps, SQRT(eps))
      closure_crossover = SQRT(eps*MAX(density_delta, 0.0_dp))
      ready = physical_delta >= 0.0_dp .AND. density_delta > eps .AND. &
              physical_delta <= MIN(asymptotic_delta, closure_crossover)

   END FUNCTION qs_scf_kp_density_closure_refresh_ready

! **************************************************************************************************
!> \brief Detect a density-dominant accepted tail which the current OT subspace cannot close.
!>
!>        Density stationarity quality is the accepted fractional reduction
!>        (density_old-density_new)/density_old. After one complete accepted-history window, an EMA
!>        no larger than EPS_SCF/density_delta means that another step is expected to remove at most
!>        one convergence tolerance. The same mature history is extrapolated geometrically to
!>        EPS_SCF: history is stale when closing the density would take longer than another complete
!>        window. A complete density audit and a raw residual already inside the coupled tail are
!>        required. The full window rejects noisy restart transients while still catching a positive
!>        but unusably slow density rate.
!> \param density_ready canonical fixed-N density audit is valid for the current orbitals
!> \param density_delta canonical fixed-N density stationarity residual
!> \param raw_delta raw residual of the previous accepted OT state
!> \param eps_scf requested SCF threshold
!> \param quality_samples accepted density-stationarity quality samples
!> \param quality_ema EMA of the accepted fractional density-residual reduction
!> \return true when accepted progress cannot close the unresolved canonical density efficiently
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_density_closure_history_refresh_ready( &
      density_ready, density_delta, raw_delta, eps_scf, quality_samples, quality_ema) RESULT(ready)

      LOGICAL, INTENT(IN)                                :: density_ready
      REAL(KIND=dp), INTENT(IN)                          :: density_delta, raw_delta, eps_scf
      INTEGER, INTENT(IN)                                :: quality_samples
      REAL(KIND=dp), INTENT(IN)                          :: quality_ema
      LOGICAL                                            :: ready

      LOGICAL                                            :: age_limited, history_mature, rate_limited
      REAL(KIND=dp)                                      :: contraction, eps, projected_steps, &
                                                            target_fraction

      eps = MAX(eps_scf, EPSILON(1.0_dp))
      target_fraction = eps/MAX(density_delta, eps)
      projected_steps = 0.0_dp
      rate_limited = .FALSE.
      history_mature = quality_samples >= ot_kp_density_closure_tail_max_samples
      IF (density_delta > eps .AND. history_mature) THEN
         contraction = 1.0_dp - quality_ema
         IF (contraction >= 1.0_dp) THEN
            rate_limited = .TRUE.
         ELSE IF (contraction > EPSILON(contraction)) THEN
            projected_steps = LOG(eps/density_delta)/LOG(contraction)
            rate_limited = projected_steps > REAL(ot_kp_density_closure_tail_max_samples, KIND=dp)
         END IF
      END IF
      ! A long accepted tail is independent evidence that the represented
      ! orbital subspace cannot close a bounded, density-dominant residual.
      ! Keep the budget inactive outside the asymptotic fixed-N basin.
      age_limited = history_mature .AND. &
                    raw_delta <= MIN(ot_kp_density_closure_tail_raw_eps_factor*eps, &
                                     ot_kp_density_closure_tail_raw_max) .AND. &
                    density_delta <= MIN(ot_kp_density_closure_tail_density_eps_factor*eps, &
                                         ot_kp_density_closure_tail_density_max)
      ready = qs_scf_kp_density_pair_activation_ready( &
              density_ready, density_delta, raw_delta, eps_scf) .AND. &
              density_delta > raw_delta .AND. &
              density_delta > 10.0_dp*eps .AND. &
              history_mature .AND. &
              (quality_ema <= target_fraction .OR. rate_limited .OR. age_limited)

   END FUNCTION qs_scf_kp_density_closure_history_refresh_ready

! **************************************************************************************************
!> \brief Detect an asymptotic orbital tail after canonical density closure.
!>
!>        Once the canonical fixed-N density is converged, a larger physical residual identifies
!>        the represented orbital subspace as the limiting block.  A complete accepted-history
!>        window is used to project the measured geometric contraction to EPS_SCF.  Rebuild only
!>        when that projection takes longer than another complete window.  The broad sqrt(EPS_SCF)
!>        upper bound keeps the decision in the asymptotic basin without delaying it until the
!>        orbital residual is already within a small scalar multiple of EPS_SCF.
!> \param density_ready canonical fixed-N density audit is valid for the current orbitals
!> \param density_delta canonical fixed-N density stationarity residual
!> \param physical_delta complete physical OT residual
!> \param eps_scf requested SCF threshold
!> \param quality_samples accepted physical-residual quality samples
!> \param quality_ema EMA of the accepted fractional physical-residual reduction
!> \return true when a canonical orbital-subspace rebase is warranted
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_orbital_tail_rebase_ready( &
      density_ready, density_delta, physical_delta, eps_scf, quality_samples, quality_ema) &
      RESULT(ready)

      LOGICAL, INTENT(IN)                                :: density_ready
      REAL(KIND=dp), INTENT(IN)                          :: density_delta, physical_delta, eps_scf
      INTEGER, INTENT(IN)                                :: quality_samples
      REAL(KIND=dp), INTENT(IN)                          :: quality_ema
      LOGICAL                                            :: ready

      LOGICAL                                            :: history_mature, rate_limited
      REAL(KIND=dp)                                      :: asymptotic_delta, contraction, eps, &
                                                            projected_steps

      eps = MAX(eps_scf, EPSILON(1.0_dp))
      asymptotic_delta = MAX(eps, SQRT(eps))
      history_mature = quality_samples >= ot_kp_orbital_tail_max_samples
      projected_steps = 0.0_dp
      rate_limited = .FALSE.
      IF (physical_delta > eps .AND. history_mature) THEN
         contraction = 1.0_dp - quality_ema
         IF (contraction >= 1.0_dp) THEN
            rate_limited = .TRUE.
         ELSE IF (contraction > EPSILON(contraction)) THEN
            projected_steps = LOG(eps/physical_delta)/LOG(contraction)
            rate_limited = projected_steps > REAL(ot_kp_orbital_tail_max_samples, KIND=dp)
         END IF
      END IF
      ready = density_ready .AND. density_delta >= 0.0_dp .AND. &
              density_delta <= ot_kp_orbital_tail_rebase_density_eps_factor*eps .AND. &
              physical_delta > eps .AND. &
              physical_delta <= asymptotic_delta .AND. &
              physical_delta >= density_delta .AND. &
              history_mature .AND. rate_limited

   END FUNCTION qs_scf_kp_orbital_tail_rebase_ready

! **************************************************************************************************
!> \brief scalar decision gate for a collapsed metallic k-point OT subspace refresh
!> \param allow_refresh whether this SCF invocation may still refresh once
!> \param fermi_window_guarded whether the current state is a projected Fermi-window sample
!> \param collapsed whether no represented band has a significant fractional occupation
!> \param residual_delta current physical/global OT residual
!> \param eps_scf requested SCF threshold
!> \param step_ready whether enough history or a restart is available
!> \param base_state whether the sample is an accepted/base line-search state
!> \param high_residual_stagnant optional flag for a collapsed line search below SCF resolution
!> \param density_closure_stagnant optional flag for a converged OT residual with an unresolved
!>        canonical fixed-N density residual
!> \return true when a full subspace rebuild is warranted
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_subspace_refresh_gate(allow_refresh, fermi_window_guarded, collapsed, &
                                                 residual_delta, eps_scf, step_ready, base_state, &
                                                 high_residual_stagnant, density_closure_stagnant) &
      RESULT(refresh)

      LOGICAL, INTENT(IN)                                :: allow_refresh, fermi_window_guarded, &
                                                            collapsed
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta, eps_scf
      LOGICAL, INTENT(IN)                                :: step_ready, base_state
      LOGICAL, INTENT(IN), OPTIONAL                      :: high_residual_stagnant, &
                                                            density_closure_stagnant
      LOGICAL                                            :: refresh

      LOGICAL                                            :: catastrophic_stagnation, density_closure
      REAL(KIND=dp)                                      :: eps, residual_upper

      eps = MAX(eps_scf, EPSILON(1.0_dp))
      residual_upper = SQRT(eps)
      catastrophic_stagnation = .FALSE.
      IF (PRESENT(high_residual_stagnant)) &
         catastrophic_stagnation = high_residual_stagnant .AND. residual_delta > residual_upper
      density_closure = .FALSE.
      IF (PRESENT(density_closure_stagnant)) density_closure = density_closure_stagnant
      refresh = allow_refresh .AND. .NOT. fermi_window_guarded .AND. step_ready .AND. &
                (base_state .OR. catastrophic_stagnation) .AND. &
                ((collapsed .AND. residual_delta > 10.0_dp*eps .AND. &
                  (residual_delta <= residual_upper .OR. catastrophic_stagnation)) .OR. &
                 density_closure)

   END FUNCTION qs_scf_kp_subspace_refresh_gate

! **************************************************************************************************
!> \brief require accepted post-rebase history before another k-point OT subspace refresh
!> \param restart_valid whether the supplied state is an unevaluated restart boundary
!> \param ot_count accepted minimizer directions since the last state reset
!> \param accepted_samples accepted Mermin line-search samples in the current orbital subspace
!> \param min_steps minimum independent progress samples before a repeated refresh
!> \return true when a refresh has enough post-rebase evidence
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_subspace_refresh_step_ready( &
      restart_valid, ot_count, accepted_samples, min_steps) RESULT(ready)
      LOGICAL, INTENT(IN)                                :: restart_valid
      INTEGER, INTENT(IN)                                :: ot_count, accepted_samples, min_steps
      LOGICAL                                            :: ready

      ready = restart_valid .OR. ot_count >= MAX(1, min_steps) .OR. &
              accepted_samples >= MAX(1, min_steps)

   END FUNCTION qs_scf_kp_subspace_refresh_step_ready

! **************************************************************************************************
!> \brief retain only a bootstrap prior when a unitary k-point OT basis is rebuilt
!>
!>        Scalar accepted-drop quality is basis independent, but carrying its full statistical
!>        weight would prevent the refreshed model from adapting.  Keep exactly the maturity
!>        needed to evaluate the first covariant candidate; vector and accumulated-drop history
!>        remain invalid across the rebuild.
!> \param accepted_samples accepted quality samples in the previous orbital basis
!> \return bounded number of scalar prior samples retained in the refreshed basis
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_rebased_calibration_samples(accepted_samples) RESULT(prior_samples)
      INTEGER, INTENT(IN)                                :: accepted_samples
      INTEGER                                            :: prior_samples

      prior_samples = MIN(MAX(0, accepted_samples), ot_kp_schur_calibration_min_samples)

   END FUNCTION qs_scf_kp_rebased_calibration_samples

! **************************************************************************************************
!> \brief computes properties for a given hamiltonian using the current wfn
!> \param scf_env ...
!> \param diis_step ...
!> \param energy_only ...
!> \param just_energy ...
!> \param exit_inner_loop ...
! **************************************************************************************************
   SUBROUTINE qs_scf_set_loop_flags(scf_env, diis_step, &
                                    energy_only, just_energy, exit_inner_loop)

      TYPE(qs_scf_env_type), POINTER                     :: scf_env
      LOGICAL                                            :: diis_step, energy_only, just_energy, &
                                                            exit_inner_loop

! Some flags needed to be set at the beginning of the loop

      diis_step = .FALSE.
      energy_only = .FALSE.
      just_energy = .FALSE.

      ! SCF loop, optimisation of the wfn coefficients
      ! qs_env%rho%rho_r and qs_env%rho%rho_g should be up to date here

      scf_env%iter_count = 0
      exit_inner_loop = .FALSE.

   END SUBROUTINE qs_scf_set_loop_flags

! **************************************************************************************************
!> \brief takes known energy and derivatives and produces new wfns
!>        and or density matrix
!> \param qs_env ...
!> \param scf_env ...
!> \param scf_control ...
!> \param scf_section ...
!> \param diis_step ...
!> \param energy_only ...
!> \param probe ...
!> \param added_mos_auto_grow ...
! **************************************************************************************************
   SUBROUTINE qs_scf_new_mos(qs_env, scf_env, scf_control, scf_section, diis_step, &
                             energy_only, probe, added_mos_auto_grow)
      TYPE(qs_environment_type), POINTER                 :: qs_env
      TYPE(qs_scf_env_type), POINTER                     :: scf_env
      TYPE(scf_control_type), POINTER                    :: scf_control
      TYPE(section_vals_type), POINTER                   :: scf_section
      LOGICAL                                            :: diis_step, energy_only
      TYPE(hairy_probes_type), DIMENSION(:), OPTIONAL, &
         POINTER                                         :: probe
      LOGICAL, INTENT(OUT), OPTIONAL                     :: added_mos_auto_grow

      CHARACTER(LEN=*), PARAMETER                        :: routineN = 'qs_scf_new_mos'

      INTEGER                                            :: handle, ispin
      LOGICAL                                            :: disable_diis, has_unit_metric, &
                                                            my_added_mos_auto_grow, skip_diag_sub
      REAL(KIND=dp)                                      :: saved_eps_diis
      TYPE(dbcsr_p_type), DIMENSION(:), POINTER          :: matrix_ks, matrix_s
      TYPE(dft_control_type), POINTER                    :: dft_control
      TYPE(mo_set_type), DIMENSION(:), POINTER           :: mos
      TYPE(qs_energy_type), POINTER                      :: energy
      TYPE(qs_ks_env_type), POINTER                      :: ks_env
      TYPE(qs_rho_type), POINTER                         :: rho

      CALL timeset(routineN, handle)

      NULLIFY (energy, ks_env, matrix_ks, matrix_s, rho, mos, dft_control)
      my_added_mos_auto_grow = .FALSE.
      IF (PRESENT(added_mos_auto_grow)) added_mos_auto_grow = .FALSE.

      CALL get_qs_env(qs_env=qs_env, &
                      matrix_s=matrix_s, energy=energy, &
                      ks_env=ks_env, &
                      matrix_ks=matrix_ks, rho=rho, mos=mos, &
                      dft_control=dft_control, &
                      has_unit_metric=has_unit_metric)
      scf_env%iter_param = 0.0_dp
      disable_diis = dft_control%qs_control%xtb_control%do_tblite .AND. &
                     tb_native_scc_mixer_active(dft_control)
      IF (disable_diis) THEN
         saved_eps_diis = scf_control%eps_diis
         scf_control%eps_diis = 0.0_dp
      END IF

      ! transfer total_zeff_corr from qs_env to scf_env only if
      ! correct_el_density_dip is switched on [SGh]
      IF (dft_control%correct_el_density_dip) THEN
         scf_env%sum_zeff_corr = qs_env%total_zeff_corr
         IF (ABS(qs_env%total_zeff_corr) > 0.0_dp) THEN
            IF (scf_env%method /= general_diag_method_nr) THEN
               CALL cp_abort(__LOCATION__, &
                             "Please use ALGORITHM STANDARD in "// &
                             "SCF%DIAGONALIZATION if "// &
                             "CORE_CORRECTION /= 0.0 and "// &
                             "SURFACE_DIPOLE_CORRECTION TRUE ")
            ELSE IF (dft_control%roks) THEN
               CALL cp_abort(__LOCATION__, &
                             "Combination of "// &
                             "CORE_CORRECTION /= 0.0 and "// &
                             "SURFACE_DIPOLE_CORRECTION TRUE "// &
                             "is not implemented with ROKS")
            ELSE IF (scf_control%diagonalization%mom) THEN
               CALL cp_abort(__LOCATION__, &
                             "Combination of "// &
                             "CORE_CORRECTION /= 0.0 and "// &
                             "SURFACE_DIPOLE_CORRECTION TRUE "// &
                             "is not implemented with SCF%MOM")
            END IF
         END IF
      END IF

      SELECT CASE (scf_env%method)
      CASE DEFAULT
         CALL cp_abort(__LOCATION__, &
                       "unknown scf method: "// &
                       cp_to_string(scf_env%method))

         ! *************************************************************************
         ! Filter matrix diagonalisation: ugly implementation at this point of time
         ! *************************************************************************
      CASE (filter_matrix_diag_method_nr)

         IF (ABS(qs_env%total_zeff_corr) > 0.0_dp) THEN
            CALL cp_abort(__LOCATION__, &
                          "CORE_CORRECTION /= 0.0 plus SURFACE_DIPOLE_CORRECTION TRUE "// &
                          "requires SCF%DIAGONALIZATION: ALGORITHM STANDARD")
         END IF
         CALL fb_env_do_diag(scf_env%filter_matrix_env, qs_env, &
                             matrix_ks, matrix_s, scf_section, diis_step)

         ! Diagonlization in non orthonormal case
      CASE (general_diag_method_nr)
         IF (dft_control%roks) THEN
            CALL do_roks_diag(scf_env, mos, matrix_ks, matrix_s, &
                              scf_control, scf_section, diis_step, &
                              has_unit_metric)
         ELSE
            IF (scf_control%diagonalization%mom) THEN
               CALL do_mom_diag(scf_env, mos, matrix_ks, &
                                matrix_s, scf_control, scf_section, &
                                diis_step)
            ELSE
               IF (dft_control%hairy_probes .EQV. .TRUE.) THEN
                  CALL do_general_diag(scf_env, mos, matrix_ks, &
                                       matrix_s, scf_control, scf_section, &
                                       diis_step, &
                                       probe)
               ELSE
                  CALL do_general_diag(scf_env, mos, matrix_ks, &
                                       matrix_s, scf_control, scf_section, &
                                       diis_step)
               END IF
            END IF
            IF (scf_control%do_diag_sub) THEN
               skip_diag_sub = (scf_env%subspace_env%eps_diag_sub > 0.0_dp) .AND. &
                               (scf_env%iter_count == 1 .OR. scf_env%iter_delta > scf_env%subspace_env%eps_diag_sub)
               IF (.NOT. skip_diag_sub) THEN
                  CALL do_scf_diag_subspace(qs_env, scf_env, scf_env%subspace_env, mos, rho, &
                                            ks_env, scf_section, scf_control)
               END IF
            END IF
         END IF
         ! Diagonlization in orthonormal case
      CASE (special_diag_method_nr)
         IF (dft_control%roks) THEN
            CALL do_roks_diag(scf_env, mos, matrix_ks, matrix_s, &
                              scf_control, scf_section, diis_step, &
                              has_unit_metric)
         ELSE
            CALL do_special_diag(scf_env, mos, matrix_ks, &
                                 scf_control, scf_section, &
                                 diis_step)
         END IF
         ! OT diagonalization
      CASE (ot_diag_method_nr)
         CALL do_ot_diag(scf_env, mos, matrix_ks, matrix_s, &
                         scf_control, scf_section, diis_step)
         ! Block Krylov diagonlization
      CASE (block_krylov_diag_method_nr)
         IF ((scf_env%krylov_space%eps_std_diag > 0.0_dp) .AND. &
             (scf_env%iter_count == 1 .OR. scf_env%iter_delta > scf_env%krylov_space%eps_std_diag)) THEN
            IF (scf_env%krylov_space%always_check_conv) THEN
               CALL do_block_krylov_diag(scf_env, mos, matrix_ks, &
                                         scf_control, scf_section, check_moconv_only=.TRUE.)
            END IF
            CALL do_general_diag(scf_env, mos, matrix_ks, &
                                 matrix_s, scf_control, scf_section, diis_step)
         ELSE
            CALL do_block_krylov_diag(scf_env, mos, matrix_ks, &
                                      scf_control, scf_section)
         END IF
         IF (scf_control%do_diag_sub) THEN
            skip_diag_sub = (scf_env%subspace_env%eps_diag_sub > 0.0_dp) .AND. &
                            (scf_env%iter_count == 1 .OR. scf_env%iter_delta > scf_env%subspace_env%eps_diag_sub)
            IF (.NOT. skip_diag_sub) THEN
               CALL do_scf_diag_subspace(qs_env, scf_env, scf_env%subspace_env, mos, rho, &
                                         ks_env, scf_section, scf_control)
            END IF
         END IF
         ! Block Davidson diagonlization
      CASE (block_davidson_diag_method_nr)
         CALL do_block_davidson_diag(qs_env, scf_env, mos, matrix_ks, matrix_s, scf_control, &
                                     scf_section, .FALSE.)
         ! OT without diagonlization. Needs special treatment for SCP runs
      CASE (ot_method_nr)
         CALL qs_scf_loop_do_ot(qs_env, scf_env, scf_control%smear, mos, rho, &
                                qs_env%mo_derivs, energy%total, &
                                matrix_s, energy_only=energy_only, has_unit_metric=has_unit_metric, &
                                added_mos_auto_grow=my_added_mos_auto_grow)
      END SELECT
      IF (disable_diis) scf_control%eps_diis = saved_eps_diis
      IF (my_added_mos_auto_grow) THEN
         IF (PRESENT(added_mos_auto_grow)) added_mos_auto_grow = .TRUE.
         CALL timestop(handle)
         RETURN
      END IF

      energy%kTS = 0.0_dp
      energy%efermi = 0.0_dp
      CALL get_qs_env(qs_env, mos=mos)
      DO ispin = 1, SIZE(mos)
         energy%kTS = energy%kTS + mos(ispin)%kTS
         energy%efermi = energy%efermi + mos(ispin)%mu
      END DO
      energy%efermi = energy%efermi/REAL(SIZE(mos), KIND=dp)

      CALL timestop(handle)

   END SUBROUTINE qs_scf_new_mos

! **************************************************************************************************
!> \brief Updates MOs and density matrix using diagonalization
!>        Kpoint code
!> \param qs_env ...
!> \param scf_env ...
!> \param scf_control ...
!> \param diis_step ...
!> \param probe ...
!> \param added_mos_auto_grow ...
!> \param ot_kp_subspace_refresh ...
!> \param allow_ot_kp_subspace_refresh ...
!> \param allow_ot_kp_orbital_tail_rebase ...
!> \param settle_ot_kp_subspace ...
! **************************************************************************************************
   SUBROUTINE qs_scf_new_mos_kp(qs_env, scf_env, scf_control, diis_step, probe, added_mos_auto_grow, &
                                ot_kp_subspace_refresh, allow_ot_kp_subspace_refresh, &
                                allow_ot_kp_orbital_tail_rebase, settle_ot_kp_subspace)
      TYPE(qs_environment_type), POINTER                 :: qs_env
      TYPE(qs_scf_env_type), POINTER                     :: scf_env
      TYPE(scf_control_type), POINTER                    :: scf_control
      LOGICAL                                            :: diis_step
      TYPE(hairy_probes_type), DIMENSION(:), OPTIONAL, &
         POINTER                                         :: probe
      LOGICAL, INTENT(OUT), OPTIONAL                     :: added_mos_auto_grow, &
                                                            ot_kp_subspace_refresh
      LOGICAL, INTENT(IN), OPTIONAL :: allow_ot_kp_subspace_refresh, &
         allow_ot_kp_orbital_tail_rebase, settle_ot_kp_subspace

      CHARACTER(LEN=*), PARAMETER                        :: routineN = 'qs_scf_new_mos_kp'

      INTEGER                                            :: canonical_mu_count, handle, ispin, &
                                                            ot_channel
      LOGICAL :: allow_orbital_tail_rebase, allow_subspace_refresh, disable_diis, has_unit_metric, &
         my_added_mos_auto_grow, my_ot_kp_subspace_refresh, settle_subspace
      REAL(dp)                                           :: canonical_mu_sum, diis_error, old_kTS, &
                                                            saved_eps_diis
      TYPE(dbcsr_p_type), DIMENSION(:, :), POINTER       :: matrix_ks, matrix_s
      TYPE(dft_control_type), POINTER                    :: dft_control
      TYPE(kpoint_type), POINTER                         :: kpoints
      TYPE(mo_set_type), DIMENSION(:, :), POINTER        :: mos
      TYPE(qs_energy_type), POINTER                      :: energy

      CALL timeset(routineN, handle)

      NULLIFY (dft_control, kpoints, matrix_ks, matrix_s)
      my_added_mos_auto_grow = .FALSE.
      my_ot_kp_subspace_refresh = .FALSE.
      allow_subspace_refresh = .TRUE.
      settle_subspace = .FALSE.
      IF (PRESENT(allow_ot_kp_subspace_refresh)) &
         allow_subspace_refresh = allow_ot_kp_subspace_refresh
      allow_orbital_tail_rebase = allow_subspace_refresh
      IF (PRESENT(allow_ot_kp_orbital_tail_rebase)) &
         allow_orbital_tail_rebase = allow_ot_kp_orbital_tail_rebase
      IF (PRESENT(settle_ot_kp_subspace)) settle_subspace = settle_ot_kp_subspace
      IF (PRESENT(added_mos_auto_grow)) added_mos_auto_grow = .FALSE.
      IF (PRESENT(ot_kp_subspace_refresh)) ot_kp_subspace_refresh = .FALSE.

      CALL get_qs_env(qs_env=qs_env, dft_control=dft_control, kpoints=kpoints)
      scf_env%iter_param = 0.0_dp
      disable_diis = dft_control%qs_control%xtb_control%do_tblite .AND. &
                     tb_native_scc_mixer_active(dft_control)
      IF (disable_diis) THEN
         saved_eps_diis = scf_control%eps_diis
         scf_control%eps_diis = 0.0_dp
      END IF

      IF (dft_control%roks) THEN
         CPABORT("KP code: ROKS method not available: ")
      END IF

      SELECT CASE (scf_env%method)
      CASE DEFAULT
         CALL cp_abort(__LOCATION__, &
                       "KP code: Unknown scf method: "// &
                       cp_to_string(scf_env%method))
      CASE (general_diag_method_nr)
         ! Diagonlization in non orthonormal case
         CALL get_qs_env(qs_env, matrix_ks_kp=matrix_ks, matrix_s_kp=matrix_s)
         IF (dft_control%hairy_probes .EQV. .TRUE.) THEN
            scf_control%smear%do_smear = .FALSE.
            CALL do_general_diag_kp(matrix_ks, matrix_s, kpoints, scf_env, scf_control, .TRUE., &
                                    diis_step, diis_error, qs_env, probe)
         ELSE
            CALL do_general_diag_kp(matrix_ks, matrix_s, kpoints, scf_env, scf_control, .TRUE., &
                                    diis_step, diis_error, qs_env, &
                                    added_mos_auto_grow=my_added_mos_auto_grow)
         END IF
         IF (my_added_mos_auto_grow) THEN
            IF (PRESENT(added_mos_auto_grow)) added_mos_auto_grow = .TRUE.
            IF (disable_diis) scf_control%eps_diis = saved_eps_diis
            CALL timestop(handle)
            RETURN
         END IF
         IF (diis_step) THEN
            scf_env%iter_param = diis_error
            scf_env%iter_method = "DIIS/Diag."
         ELSE
            IF (scf_env%mixing_method == 0) THEN
               scf_env%iter_method = "NoMix/Diag."
            ELSE IF (scf_env%mixing_method == 1) THEN
               scf_env%iter_param = scf_env%p_mix_alpha
               scf_env%iter_method = "P_Mix/Diag."
            ELSE IF (scf_env%mixing_method > 1) THEN
               scf_env%iter_param = scf_env%mixing_store%alpha
               scf_env%iter_method = TRIM(scf_env%mixing_store%iter_method)//"/Diag."
            END IF
         END IF
      CASE (special_diag_method_nr)
         CALL get_qs_env(qs_env=qs_env, has_unit_metric=has_unit_metric)
         CPASSERT(has_unit_metric)
         ! Diagonlization in orthonormal case
         CALL cp_abort(__LOCATION__, &
                       "KP code: Scf method not available: "// &
                       cp_to_string(scf_env%method))
      CASE (ot_diag_method_nr, &
            block_krylov_diag_method_nr, &
            block_davidson_diag_method_nr)
         CALL cp_abort(__LOCATION__, &
                       "KP code: Scf method not available: "// &
                       cp_to_string(scf_env%method))
      CASE (ot_method_nr)
         CALL get_qs_env(qs_env, matrix_ks_kp=matrix_ks, matrix_s_kp=matrix_s)
         CALL qs_scf_loop_do_ot_kp(qs_env, scf_env, scf_control, matrix_ks, matrix_s, &
                                   added_mos_auto_grow=my_added_mos_auto_grow, &
                                   ot_kp_subspace_refresh=my_ot_kp_subspace_refresh, &
                                   allow_ot_kp_subspace_refresh=allow_subspace_refresh, &
                                   allow_ot_kp_orbital_tail_rebase=allow_orbital_tail_rebase, &
                                   settle_ot_kp_subspace=settle_subspace)
         IF (my_ot_kp_subspace_refresh) THEN
            IF (PRESENT(ot_kp_subspace_refresh)) ot_kp_subspace_refresh = .TRUE.
            IF (disable_diis) scf_control%eps_diis = saved_eps_diis
            CALL timestop(handle)
            RETURN
         END IF
         IF (my_added_mos_auto_grow) THEN
            IF (PRESENT(added_mos_auto_grow)) added_mos_auto_grow = .TRUE.
            IF (disable_diis) scf_control%eps_diis = saved_eps_diis
            CALL timestop(handle)
            RETURN
         END IF
      CASE (smeagol_method_nr)
         ! SMEAGOL interface
         diis_step = .FALSE.
         IF (scf_env%mixing_method == 0) THEN
            scf_env%iter_method = "NoMix/SMGL"
         ELSE IF (scf_env%mixing_method == 1) THEN
            scf_env%iter_param = scf_env%p_mix_alpha
            scf_env%iter_method = "P_Mix/SMGL"
         ELSE IF (scf_env%mixing_method > 1) THEN
            scf_env%iter_param = scf_env%mixing_store%alpha
            scf_env%iter_method = TRIM(scf_env%mixing_store%iter_method)//"/SMGL"
         END IF
         CALL run_smeagol_emtrans(qs_env, last=.FALSE., iter=scf_env%iter_count, rho_ao_kp=scf_env%p_mix_new)
      END SELECT
      IF (disable_diis) scf_control%eps_diis = saved_eps_diis

      CALL get_qs_env(qs_env=qs_env, energy=energy)
      old_kTS = energy%kTS
      energy%kTS = 0.0_dp
      energy%efermi = 0.0_dp
      mos => kpoints%kp_env(1)%kpoint_env%mos
      DO ispin = 1, SIZE(mos, 2)
         energy%kTS = energy%kTS + mos(1, ispin)%kTS
         energy%efermi = energy%efermi + mos(1, ispin)%mu
      END DO
      energy%efermi = energy%efermi/REAL(SIZE(mos, 2), KIND=dp)
      IF (scf_env%method == ot_method_nr .AND. ASSOCIATED(scf_env%qs_ot_env)) THEN
         ! ener_x has a fixed-N constant-shift gauge.  Keep that gauge inside
         ! the minimizer, but report the chemical potential obtained from the
         ! canonical C(k)^H H(k) C(k) spectrum when every spin has such an audit.
         canonical_mu_sum = 0.0_dp
         canonical_mu_count = 0
         DO ispin = 1, SIZE(mos, 2)
            DO ot_channel = 1, SIZE(scf_env%qs_ot_env)
               IF (scf_env%qs_ot_env(ot_channel)%spin_index /= ispin) CYCLE
               IF (.NOT. scf_env%qs_ot_env(ot_channel)%kpoint_canonical_occupation_ready) CYCLE
               canonical_mu_sum = canonical_mu_sum + &
                                  scf_env%qs_ot_env(ot_channel)%kpoint_canonical_mu
               canonical_mu_count = canonical_mu_count + 1
               EXIT
            END DO
         END DO
         IF (canonical_mu_count == SIZE(mos, 2)) &
            energy%efermi = canonical_mu_sum/REAL(canonical_mu_count, KIND=dp)
      END IF
      energy%total = energy%total - old_kTS + energy%kTS

      CALL timestop(handle)

   END SUBROUTINE qs_scf_new_mos_kp

! **************************************************************************************************
!> \brief K-point OT driver for local complex spin/k-point channels
!> \param qs_env ...
!> \param scf_env ...
!> \param scf_control ...
!> \param matrix_ks ...
!> \param matrix_s ...
!> \param added_mos_auto_grow ...
!> \param ot_kp_subspace_refresh ...
!> \param allow_ot_kp_subspace_refresh ...
!> \param allow_ot_kp_orbital_tail_rebase ...
!> \param settle_ot_kp_subspace ...
! **************************************************************************************************
   SUBROUTINE qs_scf_loop_do_ot_kp(qs_env, scf_env, scf_control, matrix_ks, matrix_s, &
                                   added_mos_auto_grow, ot_kp_subspace_refresh, &
                                   allow_ot_kp_subspace_refresh, allow_ot_kp_orbital_tail_rebase, &
                                   settle_ot_kp_subspace)

      TYPE(qs_environment_type), POINTER                 :: qs_env
      TYPE(qs_scf_env_type), POINTER                     :: scf_env
      TYPE(scf_control_type), POINTER                    :: scf_control
      TYPE(dbcsr_p_type), DIMENSION(:, :), POINTER       :: matrix_ks, matrix_s
      LOGICAL, INTENT(OUT)                               :: added_mos_auto_grow, &
                                                            ot_kp_subspace_refresh
      LOGICAL, INTENT(IN) :: allow_ot_kp_subspace_refresh, allow_ot_kp_orbital_tail_rebase, &
         settle_ot_kp_subspace

      CHARACTER(LEN=*), PARAMETER :: routineN = 'qs_scf_loop_do_ot_kp'

      INTEGER :: first_channel, handle, ikpoint, imo, ispin, local_channel, local_kpoint, &
         max_ener_nmo, nkpoint, nlocal_channels, nmo, nspin_ot, ref_guard_attempt
      INTEGER, ALLOCATABLE, DIMENSION(:, :)              :: unweighted_residual_mult
      INTEGER, DIMENSION(2)                              :: kp_range
      LOGICAL :: fermi_window_guarded, initial_density_rebase, initial_density_reference, &
         minimizer_step_taken, post_fermi_window_guarded, protect_mermin_ls_sample, ref_guard_ok, &
         ref_guarded, shared_ref_update, transfer_step, update_ot_energy_state, &
         update_ot_energy_state_after, use_real_wfn
      REAL(KIND=dp) :: ener_nondiag, full_all_spin_scale, maxocc, occupation_floor, &
         occupation_floor_fraction, occupation_scale_full, ref_guard_max, ref_guard_min, &
         ref_guard_scale, trial_kTS, unweighted_residual_im2, unweighted_residual_re2
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: orbital_response_scale, &
                                                            orbital_scaling_factor, trial_mu
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: ener_x_old
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :, :)     :: trial_eigenvalues, trial_occupation, &
                                                            unweighted_residual_sq
      REAL(KIND=dp), DIMENSION(:), POINTER               :: eigenvalues, wkp
      TYPE(cp_fm_type)                                   :: hc_im, hc_re
      TYPE(cp_fm_type), DIMENSION(:), POINTER            :: fmwork
      TYPE(cp_fm_type), POINTER                          :: mo_coeff, mo_coeff_im
      TYPE(cp_logger_type), POINTER                      :: logger
      TYPE(dbcsr_p_type), DIMENSION(:), POINTER :: matrix_h_cache_im, matrix_h_cache_re, &
         matrix_hc, matrix_hc_im, matrix_s_cache_im, matrix_s_cache_re, matrix_x_old, &
         matrix_x_old_im, rot_mat_x_old, rot_mat_x_old_im
      TYPE(dbcsr_p_type), DIMENSION(:, :), POINTER       :: density_target, rho_ao_kp
      TYPE(dbcsr_type)                                   :: density_hc_im, density_hc_re
      TYPE(dbcsr_type), POINTER                          :: matrix_s_im, matrix_s_re
      TYPE(dft_control_type), POINTER                    :: dft_control
      TYPE(kpoint_env_type), POINTER                     :: kp
      TYPE(kpoint_type), POINTER                         :: kpoints
      TYPE(mp_para_env_type), POINTER                    :: para_env_inter_kp
      TYPE(neighbor_list_set_p_type), DIMENSION(:), &
         POINTER                                         :: sab_nl
      TYPE(qs_energy_type), POINTER                      :: energy
      TYPE(qs_ot_type), DIMENSION(:), POINTER            :: local_ot_env
      TYPE(qs_rho_type), POINTER                         :: rho

      CALL timeset(routineN, handle)

      NULLIFY (density_target, dft_control, eigenvalues, &
               energy, fmwork, kpoints, local_ot_env, logger, matrix_h_cache_im, &
               matrix_h_cache_re, matrix_hc, matrix_hc_im, matrix_s_cache_im, &
               matrix_s_cache_re, matrix_s_im, &
               matrix_s_re, matrix_x_old, matrix_x_old_im, mo_coeff, &
               mo_coeff_im, para_env_inter_kp, rho, rho_ao_kp, sab_nl, wkp)
      NULLIFY (rot_mat_x_old, rot_mat_x_old_im)
      added_mos_auto_grow = .FALSE.
      ot_kp_subspace_refresh = .FALSE.
      minimizer_step_taken = .FALSE.

      CPASSERT(ASSOCIATED(scf_env%qs_ot_env))
      CALL get_qs_env(qs_env=qs_env, dft_control=dft_control, energy=energy, kpoints=kpoints, rho=rho)
      logger => cp_get_default_logger()
      CALL get_kpoint_info(kpoints, nkp=nkpoint, wkp=wkp, use_real_wfn=use_real_wfn, &
                           kp_range=kp_range, para_env_inter_kp=para_env_inter_kp, &
                           sab_nl=sab_nl)
      CPASSERT(ASSOCIATED(sab_nl))
      CPASSERT(ASSOCIATED(matrix_ks))
      CPASSERT(ASSOCIATED(matrix_s))

      IF (use_real_wfn) THEN
         CALL cp_abort(__LOCATION__, &
                       "K-point OT driver currently supports complex k-point wavefunctions only.")
      END IF
      IF (scf_env%qs_ot_env(1)%settings%ot_algorithm /= "REF") THEN
         CALL cp_abort(__LOCATION__, &
                       "K-point OT driver currently supports OT%ALGORITHM REF only.")
      END IF
      transfer_step = .FALSE.
      CALL do_general_diag_kp(matrix_ks, matrix_s, kpoints, scf_env, scf_control, .FALSE., &
                              transfer_step, store_ot_matrices=.TRUE., transfer_only=.TRUE.)
      kp => kpoints%kp_env(1)%kpoint_env
      nspin_ot = SIZE(kp%mos, 2)
      CALL qs_ot_check_channel_context(scf_env%qs_ot_env, nspin_ot, &
                                       nkpoint=nkpoint, &
                                       restricted=ANY(scf_env%qs_ot_env(:)%restricted), &
                                       require_kpoint=.TRUE., &
                                       kp_range=kp_range, &
                                       wkp=wkp, &
                                       require_local_state=.TRUE., &
                                       require_complex_state=.TRUE.)

      first_channel = qs_ot_channel_index(1, kp_range(1), nspin_ot)
      nlocal_channels = SIZE(kpoints%kp_env)*nspin_ot
      local_ot_env => scf_env%qs_ot_env(first_channel:first_channel + nlocal_channels - 1)
      ener_nondiag = 0.0_dp
      initial_density_reference = scf_env%iter_count <= 1 .AND. &
                                  .NOT. scf_env%qs_ot_restart%valid .AND. &
                                  local_ot_env(1)%OT_count <= 0
      initial_density_rebase = initial_density_reference .AND. nkpoint > 1
      IF (initial_density_reference .AND. .NOT. settle_ot_kp_subspace .AND. &
          allow_ot_kp_subspace_refresh) THEN
         ! Initial SCF-loop setup precedes the first real KS build.  Re-enter
         ! initialization once H(k) exists so the REF virtual subspace and its
         ! preconditioner come from the physical Hamiltonian rather than the
         ! zero/placeholder matrices.
         ot_kp_subspace_refresh = .TRUE.
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A)') &
            " OT k-point initial physical-subspace rebuild requested."
         CALL timestop(handle)
         RETURN
      END IF

      ALLOCATE (matrix_hc(nlocal_channels))
      ALLOCATE (matrix_hc_im(nlocal_channels))
      ALLOCATE (matrix_h_cache_re(nlocal_channels))
      ALLOCATE (matrix_h_cache_im(nlocal_channels))
      ALLOCATE (matrix_x_old(nlocal_channels))
      ALLOCATE (matrix_x_old_im(nlocal_channels))
      ALLOCATE (rot_mat_x_old(nlocal_channels))
      ALLOCATE (rot_mat_x_old_im(nlocal_channels))
      ALLOCATE (matrix_s_cache_re(SIZE(kpoints%kp_env)))
      ALLOCATE (matrix_s_cache_im(SIZE(kpoints%kp_env)))
      DO local_kpoint = 1, SIZE(kpoints%kp_env)
         NULLIFY (matrix_s_cache_re(local_kpoint)%matrix)
         NULLIFY (matrix_s_cache_im(local_kpoint)%matrix)
      END DO
      max_ener_nmo = 1
      DO local_channel = 1, nlocal_channels
         NULLIFY (matrix_h_cache_re(local_channel)%matrix)
         NULLIFY (matrix_h_cache_im(local_channel)%matrix)
         NULLIFY (matrix_hc(local_channel)%matrix)
         NULLIFY (matrix_hc_im(local_channel)%matrix)
         NULLIFY (matrix_x_old(local_channel)%matrix)
         NULLIFY (matrix_x_old_im(local_channel)%matrix)
         NULLIFY (rot_mat_x_old(local_channel)%matrix)
         NULLIFY (rot_mat_x_old_im(local_channel)%matrix)
         ALLOCATE (matrix_hc(local_channel)%matrix)
         ALLOCATE (matrix_hc_im(local_channel)%matrix)
         CALL dbcsr_copy(matrix_hc(local_channel)%matrix, local_ot_env(local_channel)%matrix_x, name="matrix_hc")
         CALL dbcsr_copy(matrix_hc_im(local_channel)%matrix, local_ot_env(local_channel)%matrix_x_im, &
                         name="matrix_hc_im")
         CALL dbcsr_set(matrix_hc(local_channel)%matrix, 0.0_dp)
         CALL dbcsr_set(matrix_hc_im(local_channel)%matrix, 0.0_dp)
         ALLOCATE (matrix_x_old(local_channel)%matrix)
         ALLOCATE (matrix_x_old_im(local_channel)%matrix)
         CALL dbcsr_copy(matrix_x_old(local_channel)%matrix, local_ot_env(local_channel)%matrix_x, &
                         name="ot_kp_ref_guard_x_old")
         CALL dbcsr_copy(matrix_x_old_im(local_channel)%matrix, local_ot_env(local_channel)%matrix_x_im, &
                         name="ot_kp_ref_guard_x_old_im")
         IF (ASSOCIATED(local_ot_env(local_channel)%rot_mat_x)) THEN
            ALLOCATE (rot_mat_x_old(local_channel)%matrix)
            CALL dbcsr_copy(rot_mat_x_old(local_channel)%matrix, local_ot_env(local_channel)%rot_mat_x, &
                            name="ot_kp_ref_guard_rot_old")
         END IF
         IF (ASSOCIATED(local_ot_env(local_channel)%rot_mat_x_im)) THEN
            ALLOCATE (rot_mat_x_old_im(local_channel)%matrix)
            CALL dbcsr_copy(rot_mat_x_old_im(local_channel)%matrix, local_ot_env(local_channel)%rot_mat_x_im, &
                            name="ot_kp_ref_guard_rot_old_im")
         END IF
         IF (ASSOCIATED(local_ot_env(local_channel)%ener_x)) &
            max_ener_nmo = MAX(max_ener_nmo, SIZE(local_ot_env(local_channel)%ener_x))
      END DO
      ALLOCATE (ener_x_old(max_ener_nmo, nlocal_channels))
      ener_x_old(:, :) = 0.0_dp
      DO local_channel = 1, nlocal_channels
         IF (ASSOCIATED(local_ot_env(local_channel)%ener_x)) &
            ener_x_old(1:SIZE(local_ot_env(local_channel)%ener_x), local_channel) = &
            local_ot_env(local_channel)%ener_x(:)
      END DO
      protect_mermin_ls_sample = local_ot_env(1)%mermin_ls_sample_pending .AND. &
                                 local_ot_env(1)%line_search_might_be_done .AND. &
                                 .NOT. local_ot_env(1)%energy_only
      update_ot_energy_state = .NOT. local_ot_env(1)%energy_only .AND. &
                               .NOT. protect_mermin_ls_sample
      IF (protect_mermin_ls_sample) THEN
         logger => cp_get_default_logger()
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) THEN
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I5,4(1X,ES16.8))') &
               " OT Mermin LS accepted-sample projection guard idx ref best bdrop bpos:", &
               local_ot_env(1)%mermin_ls_best_sample_index, &
               local_ot_env(1)%mermin_ls_reference_energy, &
               local_ot_env(1)%mermin_ls_best_sample_energy, &
               local_ot_env(1)%mermin_ls_best_sample_drop, &
               local_ot_env(1)%mermin_ls_best_sample_pos
         END IF
      END IF

      shared_ref_update = qs_ot_ref_update_required(local_ot_env(1))
      DO local_kpoint = 1, SIZE(kpoints%kp_env)
         kp => kpoints%kp_env(local_kpoint)%kpoint_env
         ikpoint = kp%nkpoint
         CPASSERT(ASSOCIATED(kp%ot_smat))
         CPASSERT(SIZE(kp%ot_smat) >= 2)
         CALL dbcsr_init_p(matrix_s_cache_re(local_kpoint)%matrix)
         CALL dbcsr_init_p(matrix_s_cache_im(local_kpoint)%matrix)
         CALL copy_fm_to_dbcsr_bc(kp%ot_smat(1), matrix_s_cache_re(local_kpoint)%matrix)
         CALL copy_fm_to_dbcsr_bc(kp%ot_smat(2), matrix_s_cache_im(local_kpoint)%matrix)
         matrix_s_re => matrix_s_cache_re(local_kpoint)%matrix
         matrix_s_im => matrix_s_cache_im(local_kpoint)%matrix
         DO ispin = 1, nspin_ot
            local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
            CALL dbcsr_init_p(matrix_h_cache_re(local_channel)%matrix)
            CALL dbcsr_init_p(matrix_h_cache_im(local_channel)%matrix)
            CALL copy_fm_to_dbcsr_bc(kp%ot_hmat(1, ispin), matrix_h_cache_re(local_channel)%matrix)
            CALL copy_fm_to_dbcsr_bc(kp%ot_hmat(2, ispin), matrix_h_cache_im(local_channel)%matrix)
            CALL get_mo_set(kp%mos(1, ispin), mo_coeff=mo_coeff)
            CALL get_mo_set(kp%mos(2, ispin), mo_coeff=mo_coeff_im)
            IF (local_channel == 1) THEN
               CALL qs_ot_get_orbitals_ref_complex(matrix_hc(local_channel)%matrix, &
                                                   matrix_hc_im(local_channel)%matrix, &
                                                   matrix_s_re, matrix_s_im, &
                                                   local_ot_env(local_channel))
            ELSE
               CALL qs_ot_get_orbitals_ref_complex(matrix_hc(local_channel)%matrix, &
                                                   matrix_hc_im(local_channel)%matrix, &
                                                   matrix_s_re, matrix_s_im, &
                                                   local_ot_env(local_channel), &
                                                   ref_update=shared_ref_update)
            END IF
            CALL copy_dbcsr_to_fm(matrix_hc(local_channel)%matrix, mo_coeff)
            CALL copy_dbcsr_to_fm(matrix_hc_im(local_channel)%matrix, mo_coeff_im)
         END DO
      END DO

      DO local_kpoint = 1, SIZE(kpoints%kp_env)
         kp => kpoints%kp_env(local_kpoint)%kpoint_env
         ikpoint = kp%nkpoint
         CPASSERT(ASSOCIATED(kp%ot_hmat))
         CPASSERT(SIZE(kp%ot_hmat, 1) >= 2)
         DO ispin = 1, nspin_ot
            local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
            CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, mo_coeff=mo_coeff, nmo=nmo)
            CALL get_mo_set(kp%mos(2, ispin), mo_coeff=mo_coeff_im)
            CALL cp_fm_create(hc_re, mo_coeff%matrix_struct)
            CALL cp_fm_create(hc_im, mo_coeff%matrix_struct)
            CALL cp_dbcsr_sm_fm_multiply(matrix_h_cache_re(local_channel)%matrix, &
                                         mo_coeff, hc_re, nmo)
            CALL cp_dbcsr_sm_fm_multiply(matrix_h_cache_im(local_channel)%matrix, &
                                         mo_coeff_im, hc_re, nmo, alpha=-1.0_dp, beta=1.0_dp)
            CALL cp_dbcsr_sm_fm_multiply(matrix_h_cache_re(local_channel)%matrix, &
                                         mo_coeff_im, hc_im, nmo)
            CALL cp_dbcsr_sm_fm_multiply(matrix_h_cache_im(local_channel)%matrix, &
                                         mo_coeff, hc_im, nmo, alpha=1.0_dp, beta=1.0_dp)

            CALL copy_fm_to_dbcsr(hc_re, matrix_hc(local_channel)%matrix)
            CALL copy_fm_to_dbcsr(hc_im, matrix_hc_im(local_channel)%matrix)

            CALL qs_scf_loop_prepare_ot_kp_energy_chc(local_ot_env(local_channel), &
                                                      matrix_hc(local_channel)%matrix, &
                                                      matrix_hc_im(local_channel)%matrix, &
                                                      scf_control%smear)

            CALL cp_fm_release(hc_re)
            CALL cp_fm_release(hc_im)
         END DO
      END DO
      IF (initial_density_reference) THEN
         CALL qs_scf_loop_reset_ot_kp_guard_state(local_ot_env)
         DO local_channel = 1, nlocal_channels
            CALL dbcsr_copy(matrix_x_old(local_channel)%matrix, &
                            local_ot_env(local_channel)%matrix_x)
            CALL dbcsr_copy(matrix_x_old_im(local_channel)%matrix, &
                            local_ot_env(local_channel)%matrix_x_im)
            IF (ASSOCIATED(rot_mat_x_old(local_channel)%matrix)) &
               CALL dbcsr_copy(rot_mat_x_old(local_channel)%matrix, &
                               local_ot_env(local_channel)%rot_mat_x)
            IF (ASSOCIATED(rot_mat_x_old_im(local_channel)%matrix)) &
               CALL dbcsr_copy(rot_mat_x_old_im(local_channel)%matrix, &
                               local_ot_env(local_channel)%rot_mat_x_im)
            IF (ASSOCIATED(local_ot_env(local_channel)%ener_x)) &
               ener_x_old(1:SIZE(local_ot_env(local_channel)%ener_x), local_channel) = &
               local_ot_env(local_channel)%ener_x(:)
         END DO
      END IF
      CALL qs_scf_loop_collect_ot_kp_trial_smearing(kpoints, local_ot_env, first_channel, nspin_ot, &
                                                    kp_range, wkp, para_env_inter_kp, scf_control%smear, &
                                                    trial_eigenvalues, trial_occupation, trial_mu, trial_kTS)
      fermi_window_guarded = .FALSE.
      IF (update_ot_energy_state .OR. protect_mermin_ls_sample) THEN
         CALL qs_scf_loop_guard_ot_kp_trial_fermi_window(kpoints, local_ot_env, first_channel, &
                                                         nspin_ot, kp_range, wkp, para_env_inter_kp, &
                                                         scf_control%smear, trial_eigenvalues, &
                                                         trial_occupation, trial_mu, scf_control%eps_scf, &
                                                         fermi_window_guarded)
      END IF
      IF (fermi_window_guarded) THEN
         CALL qs_scf_loop_smear_ot_kp_trial_eigenvalues(kpoints, nspin_ot, wkp, scf_control%smear, &
                                                        trial_eigenvalues, trial_occupation, trial_mu, trial_kTS)
      END IF
      ot_kp_subspace_refresh = qs_scf_loop_ot_kp_subspace_refresh_needed( &
                               kpoints, local_ot_env, nspin_ot, wkp, para_env_inter_kp, scf_control%smear, &
                               scf_control%added_mos_auto, scf_control%added_mos, &
                               trial_occupation, scf_env%iter_count, scf_env%iter_delta, scf_control%eps_scf, &
                               scf_env%qs_ot_restart%valid, protect_mermin_ls_sample, fermi_window_guarded, &
                               allow_ot_kp_subspace_refresh, allow_ot_kp_orbital_tail_rebase)
      IF (ot_kp_subspace_refresh) THEN
         local_ot_env(:)%kpoint_energy_closure_attempted = .FALSE.
         GOTO 900
      END IF
      CALL qs_scf_loop_update_ot_kp_occ_preconditioner(local_ot_env)
      IF (logger%iter_info%print_level >= debug_print_level) THEN
         ALLOCATE (unweighted_residual_sq(2, nkpoint, nspin_ot), &
                   unweighted_residual_mult(nkpoint, nspin_ot))
         unweighted_residual_sq(:, :, :) = 0.0_dp
         unweighted_residual_mult(:, :) = 0
      END IF
      DO local_kpoint = 1, SIZE(kpoints%kp_env)
         kp => kpoints%kp_env(local_kpoint)%kpoint_env
         ikpoint = kp%nkpoint
         DO ispin = 1, nspin_ot
            local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
            CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, nmo=nmo)

            full_all_spin_scale = 1.0_dp
            IF (ASSOCIATED(local_ot_env(local_channel)%preconditioner)) THEN
               IF (ASSOCIATED(local_ot_env(local_channel)%preconditioner%complex_fm)) &
                  full_all_spin_scale = qs_scf_kp_full_all_spin_normalization(maxocc)
            END IF
            IF (ASSOCIATED(local_ot_env(local_channel)%matrix_occ_precond_scale)) &
               local_ot_env(local_channel)%matrix_occ_precond_scale(:) = full_all_spin_scale
            IF (ASSOCIATED(local_ot_env(local_channel)%matrix_occ_precond_scale) .AND. &
                qs_ot_occupation_preconditioner_active(local_ot_env(local_channel)) .AND. &
                scf_control%smear%do_smear .AND. &
                (scf_control%smear%method == smear_fermi_dirac .OR. &
                 scf_control%smear%method == smear_gaussian)) THEN
               ! The subspace Hessian for column i carries the same f_i factor
               ! as H*C*diag(2*w_k*f).  Remove it from the preconditioned
               ! direction.  Nearly empty columns are regularized at the
               ! density accuracy implied by EPS_SCF.
               occupation_floor_fraction = MAX(1.0E-4_dp, MIN(1.0E-1_dp, &
                                                              SQRT(MAX(scf_control%eps_scf, 0.0_dp))))
               occupation_floor = maxocc*occupation_floor_fraction
               DO imo = 1, SIZE(local_ot_env(local_channel)%matrix_occ_precond_scale)
                  occupation_scale_full = &
                     maxocc/MAX(trial_occupation(imo, ikpoint, ispin), occupation_floor)
                  local_ot_env(local_channel)%matrix_occ_precond_scale(imo) = &
                     full_all_spin_scale*qs_scf_kp_occ_metric_continuation( &
                     occupation_scale_full, &
                     local_ot_env(1)%mermin_ls_accepted_quality_samples, &
                     local_ot_env(1)%mermin_ls_accepted_quality_ema, &
                     local_ot_env(1)%kpoint_occ_metric_residual_quality_ema)
               END DO
            END IF

            IF (logger%iter_info%print_level >= debug_print_level) THEN
               CALL qs_ot_get_derivative_ref_complex(matrix_hc(local_channel)%matrix, &
                                                     matrix_hc_im(local_channel)%matrix, &
                                                     local_ot_env(local_channel))
               CALL dbcsr_dot(local_ot_env(local_channel)%matrix_gx, &
                              local_ot_env(local_channel)%matrix_gx, unweighted_residual_re2)
               CALL dbcsr_dot(local_ot_env(local_channel)%matrix_gx_im, &
                              local_ot_env(local_channel)%matrix_gx_im, unweighted_residual_im2)
               unweighted_residual_sq(1, ikpoint, ispin) = unweighted_residual_re2
               unweighted_residual_sq(2, ikpoint, ispin) = unweighted_residual_im2
               unweighted_residual_mult(ikpoint, ispin) = &
                  local_ot_env(local_channel)%kpoint_multiplicity
            END IF

            CALL qs_scf_loop_prepare_ot_kp_channel_gradient(local_ot_env(local_channel), &
                                                            matrix_hc(local_channel)%matrix, &
                                                            matrix_hc_im(local_channel)%matrix, &
                                                            trial_occupation(1:nmo, ikpoint, ispin), &
                                                            trial_eigenvalues(1:nmo, ikpoint, ispin), &
                                                            maxocc, trial_mu(ispin), &
                                                            wkp(ikpoint), scf_control%smear, &
                                                            ener_nondiag)

            local_ot_env(local_channel)%orbital_schur_response_ready = .FALSE.
            IF (qs_ot_occupation_preconditioner_active(local_ot_env(local_channel)) .AND. &
                ASSOCIATED(local_ot_env(local_channel)%preconditioner) .AND. &
                ASSOCIATED(local_ot_env(local_channel)%preconditioner%complex_fm) .AND. &
                ASSOCIATED(local_ot_env(local_channel)%matrix_occ_precond_scale)) THEN
               ! The rotation/REF cross Hessian needs the unweighted complement
               ! residual R_base.  Reuse the exact complex REF derivative before
               ! H*C is occupation-weighted for the ordinary OT minimizer.
               CALL qs_ot_get_derivative_ref_complex(matrix_hc(local_channel)%matrix, &
                                                     matrix_hc_im(local_channel)%matrix, &
                                                     local_ot_env(local_channel))
               ALLOCATE (orbital_response_scale(nmo))
               orbital_response_scale(:) = &
                  local_ot_env(local_channel)%matrix_occ_precond_scale(:)/ &
                  REAL(MAX(1, local_ot_env(local_channel)%kpoint_multiplicity), KIND=dp)
               CALL full_all_response_metric_dbcsr_complex( &
                  local_ot_env(local_channel)%preconditioner, &
                  local_ot_env(local_channel)%matrix_gx, local_ot_env(local_channel)%matrix_gx_im, &
                  local_ot_env(local_channel)%orbital_schur_response_metric, orbital_response_scale)
               local_ot_env(local_channel)%orbital_schur_response_ready = .TRUE.
               DEALLOCATE (orbital_response_scale)
            END IF

            ALLOCATE (orbital_scaling_factor(nmo))
            ! Keep orbital gradients on the fixed-N Mermin surface.  The spectral
            ! preconditioner removes maxocc once, and the optional occupation metric
            ! continues separately from f/maxocc to an unweighted orbital direction.
            orbital_scaling_factor(:) = 2.0_dp*wkp(ikpoint)*trial_occupation(1:nmo, ikpoint, ispin)
            CALL dbcsr_scale_by_vector(matrix_hc(local_channel)%matrix, &
                                       alpha=orbital_scaling_factor, side='right')
            CALL dbcsr_scale_by_vector(matrix_hc_im(local_channel)%matrix, &
                                       alpha=orbital_scaling_factor, side='right')
            DEALLOCATE (orbital_scaling_factor)
         END DO
      END DO
      IF (logger%iter_info%print_level >= debug_print_level) THEN
         CALL para_env_inter_kp%sum(unweighted_residual_sq)
         CALL para_env_inter_kp%sum(unweighted_residual_mult)
         IF (logger%para_env%is_source()) THEN
            DO ispin = 1, nspin_ot
               DO ikpoint = 1, nkpoint
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,3(1X,I4),3(1X,ES16.8))') &
                     " OT k-point unweighted REF residual spin k mult re im total:", &
                     ispin, ikpoint, unweighted_residual_mult(ikpoint, ispin), &
                     SQRT(MAX(0.0_dp, unweighted_residual_sq(1, ikpoint, ispin))), &
                     SQRT(MAX(0.0_dp, unweighted_residual_sq(2, ikpoint, ispin))), &
                     SQRT(MAX(0.0_dp, SUM(unweighted_residual_sq(:, ikpoint, ispin))))
               END DO
            END DO
         END IF
         DEALLOCATE (unweighted_residual_sq, unweighted_residual_mult)
      END IF

      CALL para_env_inter_kp%sum(ener_nondiag)
      IF (initial_density_reference) THEN
         ! The first energy belongs to the supplied atomic/restart density, not
         ! yet to the orbitals just diagonalized in that Hamiltonian.  Replacing
         ! only its entropy would create a mixed, non-variational reference.
         local_ot_env(1)%etotal = energy%total + ener_nondiag
      ELSE
         ! All rebased and ordinary samples compare the current fixed-N Mermin
         ! state, including the entropy solved from the trial auxiliary energies.
         local_ot_env(1)%etotal = energy%total - energy%kTS + trial_kTS + ener_nondiag
      END IF

      CALL qs_scf_loop_prepare_ot_kp_energy_gradient(kpoints, local_ot_env, first_channel, nspin_ot, &
                                                     kp_range, wkp, para_env_inter_kp, scf_control%smear, &
                                                     scf_control%added_mos_auto, scf_control%added_mos, &
                                                     scf_control%eps_scf, &
                                                     trial_eigenvalues, trial_occupation, trial_mu)
      CALL qs_scf_loop_prepare_ot_kp_energy_trust(kpoints, local_ot_env, first_channel, nspin_ot, &
                                                  wkp, para_env_inter_kp, scf_control%smear, &
                                                  scf_control%eps_scf, &
                                                  trial_eigenvalues, trial_occupation, trial_mu)

      IF (initial_density_rebase) THEN
         ! The supplied atomic density and the freshly diagonalized multi-k-point
         ! orbitals are not one variational state.  Build H[rho(C,f)] once before
         ! exposing those coordinates to a Mermin line search.
         CALL qs_scf_loop_reset_ot_kp_guard_state(local_ot_env)
         DO local_channel = 1, SIZE(local_ot_env)
            local_ot_env(local_channel)%OT_METHOD_FULL = "OT INIT"
            local_ot_env(local_channel)%delta = &
               MAX(local_ot_env(local_channel)%delta, 10.0_dp*scf_control%eps_scf)
            local_ot_env(local_channel)%energy_only = .FALSE.
         END DO
         protect_mermin_ls_sample = .FALSE.
         update_ot_energy_state_after = .TRUE.
      ELSE IF (settle_ot_kp_subspace) THEN
         ! A full diagonalization changes the density by a finite amount.  Build
         ! that density once before starting a line search, so H[rho] response is
         ! not misidentified as curvature along the first OT direction.
         DO local_channel = 1, SIZE(local_ot_env)
            local_ot_env(local_channel)%OT_METHOD_FULL = "OT SUB"
            local_ot_env(local_channel)%delta = &
               MAX(local_ot_env(local_channel)%delta, 10.0_dp*scf_control%eps_scf)
            local_ot_env(local_channel)%energy_only = .FALSE.
            IF (local_ot_env(local_channel)%settings%occupation_preconditioner .AND. &
                scf_control%smear%do_smear .AND. &
                (scf_control%smear%method == smear_fermi_dirac .OR. &
                 scf_control%smear%method == smear_gaussian)) &
               local_ot_env(local_channel)%kpoint_occ_preconditioner_ready_samples = &
               MAX(local_ot_env(local_channel)%kpoint_occ_preconditioner_ready_samples, &
                   ot_kp_occ_preconditioner_bootstrap_samples - 1)
         END DO
         protect_mermin_ls_sample = .FALSE.
         update_ot_energy_state_after = .TRUE.
      ELSE IF (fermi_window_guarded) THEN
         ! A frontier projection is not an affine step along the current OT
         ! direction.  Evaluate its density and Hamiltonian as a separate base
         ! point instead of mixing it into an accepted line-search endpoint.
         CALL qs_scf_loop_reset_ot_kp_guard_state(local_ot_env)
         DO local_channel = 1, SIZE(local_ot_env)
            local_ot_env(local_channel)%OT_METHOD_FULL = "OT FER"
            local_ot_env(local_channel)%delta = &
               MAX(local_ot_env(local_channel)%delta, 2.0_dp*scf_control%eps_scf)
            local_ot_env(local_channel)%energy_only = .FALSE.
         END DO
         protect_mermin_ls_sample = .FALSE.
         update_ot_energy_state_after = .TRUE.
      ELSE
         minimizer_step_taken = .TRUE.
         CALL ot_mini(local_ot_env, matrix_hc, matrix_hc_im=matrix_hc_im, &
                      para_env_inter_kp=para_env_inter_kp)
         ! ot_mini constructs globally reduced scalar residuals on the
         ! distributed channel roots.  Propagate the accepted endpoint before
         ! the outer SCF exit test consumes readiness and its matching delta.
         CALL sync_kpoint_minimizer_control(local_ot_env, para_env_inter_kp)
         protect_mermin_ls_sample = local_ot_env(1)%mermin_ls_sample_pending .AND. &
                                    local_ot_env(1)%line_search_might_be_done .AND. &
                                    .NOT. local_ot_env(1)%energy_only
         update_ot_energy_state_after = .NOT. local_ot_env(1)%energy_only .AND. &
                                        .NOT. local_ot_env(1)%mermin_ls_closure_rejected
      END IF
      ref_guard_ok = qs_scf_loop_ot_kp_ref_overlap_guard_ok( &
                     kpoints, local_ot_env, first_channel, nspin_ot, &
                     matrix_s_cache_re, matrix_s_cache_im, para_env_inter_kp, &
                     ref_guard_min, ref_guard_max)
      ref_guarded = .FALSE.
      ref_guard_scale = 1.0_dp
      IF (.NOT. ref_guard_ok) THEN
         DO ref_guard_attempt = 1, ot_kp_ref_overlap_guard_max_attempts
            CALL qs_scf_loop_blend_ot_kp_ref_step(local_ot_env, matrix_x_old, matrix_x_old_im, &
                                                  rot_mat_x_old, rot_mat_x_old_im, ener_x_old, &
                                                  ot_kp_ref_overlap_guard_backtrack)
            ref_guard_scale = ref_guard_scale*ot_kp_ref_overlap_guard_backtrack
            ref_guard_ok = qs_scf_loop_ot_kp_ref_overlap_guard_ok(kpoints, local_ot_env, first_channel, &
                                                                  nspin_ot, matrix_s_cache_re, &
                                                                  matrix_s_cache_im, para_env_inter_kp, &
                                                                  ref_guard_min, &
                                                                  ref_guard_max)
            IF (ref_guard_ok) EXIT
         END DO
         IF (.NOT. ref_guard_ok) THEN
            CALL qs_scf_loop_blend_ot_kp_ref_step(local_ot_env, matrix_x_old, matrix_x_old_im, &
                                                  rot_mat_x_old, rot_mat_x_old_im, ener_x_old, 0.0_dp)
            ref_guard_scale = 0.0_dp
            ref_guard_ok = qs_scf_loop_ot_kp_ref_overlap_guard_ok(kpoints, local_ot_env, first_channel, &
                                                                  nspin_ot, matrix_s_cache_re, &
                                                                  matrix_s_cache_im, para_env_inter_kp, &
                                                                  ref_guard_min, &
                                                                  ref_guard_max)
         END IF
         IF (.NOT. ref_guard_ok) THEN
            CALL cp_abort(__LOCATION__, &
                          "K-point OT REF-overlap guard could not restore a positive overlap. "// &
                          "Minimum/maximum eigenvalue: "// &
                          TRIM(ADJUSTL(cp_to_string(ref_guard_min)))//" "// &
                          TRIM(ADJUSTL(cp_to_string(ref_guard_max))))
         END IF
         ref_guarded = .TRUE.
         CALL qs_scf_loop_reset_ot_kp_guard_state(local_ot_env)
      END IF
      IF (ref_guarded) THEN
         logger => cp_get_default_logger()
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) THEN
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I4,3(1X,ES16.8))') &
               " OT k-point REF-overlap guard attempts scale min max:", &
               ref_guard_attempt, ref_guard_scale, ref_guard_min, ref_guard_max
         END IF
      END IF
      post_fermi_window_guarded = .FALSE.
      IF (minimizer_step_taken) THEN
         ! Every OT line-search trial moves ener_x, including the first trial for
         ! which energy_only describes the *next* evaluation. Guard it before
         ! occupations are installed; one iteration later the old fractional
         ! frontier is no longer available as the transition reference.
         CALL qs_scf_loop_collect_ot_kp_trial_smearing(kpoints, local_ot_env, first_channel, nspin_ot, &
                                                       kp_range, wkp, para_env_inter_kp, &
                                                       scf_control%smear, trial_eigenvalues, &
                                                       trial_occupation, trial_mu, trial_kTS)
         CALL qs_scf_loop_guard_ot_kp_trial_fermi_window(kpoints, local_ot_env, first_channel, &
                                                         nspin_ot, kp_range, wkp, para_env_inter_kp, &
                                                         scf_control%smear, trial_eigenvalues, &
                                                         trial_occupation, trial_mu, scf_control%eps_scf, &
                                                         post_fermi_window_guarded)
         IF (post_fermi_window_guarded) THEN
            fermi_window_guarded = .TRUE.
            CALL qs_scf_loop_smear_ot_kp_trial_eigenvalues(kpoints, nspin_ot, wkp, &
                                                           scf_control%smear, trial_eigenvalues, &
                                                           trial_occupation, trial_mu, trial_kTS)
            CALL qs_scf_loop_reset_ot_kp_guard_state(local_ot_env)
            DO local_channel = 1, SIZE(local_ot_env)
               local_ot_env(local_channel)%OT_METHOD_FULL = "OT FER"
               local_ot_env(local_channel)%delta = &
                  MAX(local_ot_env(local_channel)%delta, 2.0_dp*scf_control%eps_scf)
               local_ot_env(local_channel)%energy_only = .FALSE.
            END DO
            protect_mermin_ls_sample = .FALSE.
            update_ot_energy_state_after = .TRUE.
         END IF
      END IF
      CALL qs_scf_loop_sync_ot_kp_global_delta(local_ot_env, para_env_inter_kp, scf_env%iter_delta)

      shared_ref_update = qs_ot_ref_update_required(local_ot_env(1))
      DO local_kpoint = 1, SIZE(kpoints%kp_env)
         kp => kpoints%kp_env(local_kpoint)%kpoint_env
         ikpoint = kp%nkpoint
         matrix_s_re => matrix_s_cache_re(local_kpoint)%matrix
         matrix_s_im => matrix_s_cache_im(local_kpoint)%matrix
         DO ispin = 1, nspin_ot
            local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
            CALL get_mo_set(kp%mos(1, ispin), mo_coeff=mo_coeff, eigenvalues=eigenvalues, &
                            nmo=nmo)
            CALL get_mo_set(kp%mos(2, ispin), mo_coeff=mo_coeff_im)
            IF (local_channel == 1) THEN
               CALL qs_ot_get_orbitals_ref_complex(matrix_hc(local_channel)%matrix, &
                                                   matrix_hc_im(local_channel)%matrix, &
                                                   matrix_s_re, matrix_s_im, &
                                                   local_ot_env(local_channel))
            ELSE
               CALL qs_ot_get_orbitals_ref_complex(matrix_hc(local_channel)%matrix, &
                                                   matrix_hc_im(local_channel)%matrix, &
                                                   matrix_s_re, matrix_s_im, &
                                                   local_ot_env(local_channel), &
                                                   ref_update=shared_ref_update)
            END IF
            CALL copy_dbcsr_to_fm(matrix_hc(local_channel)%matrix, mo_coeff)
            CALL copy_dbcsr_to_fm(matrix_hc_im(local_channel)%matrix, mo_coeff_im)
            IF (kpoint_ot_project_energy_subproblem(local_ot_env(local_channel), scf_control%smear)) THEN
               CPASSERT(ASSOCIATED(kp%ot_hmat))
               CPASSERT(SIZE(kp%ot_hmat, 1) >= 2)
               CALL cp_fm_create(hc_re, mo_coeff%matrix_struct)
               CALL cp_fm_create(hc_im, mo_coeff%matrix_struct)
               CALL cp_dbcsr_sm_fm_multiply(matrix_h_cache_re(local_channel)%matrix, &
                                            mo_coeff, hc_re, nmo)
               CALL cp_dbcsr_sm_fm_multiply(matrix_h_cache_im(local_channel)%matrix, &
                                            mo_coeff_im, hc_re, nmo, alpha=-1.0_dp, beta=1.0_dp)
               CALL cp_dbcsr_sm_fm_multiply(matrix_h_cache_re(local_channel)%matrix, &
                                            mo_coeff_im, hc_im, nmo)
               CALL cp_dbcsr_sm_fm_multiply(matrix_h_cache_im(local_channel)%matrix, &
                                            mo_coeff, hc_im, nmo, alpha=1.0_dp, beta=1.0_dp)

               CALL dbcsr_copy(density_hc_re, matrix_hc(local_channel)%matrix, name="ot_kp_density_hc_re")
               CALL dbcsr_copy(density_hc_im, matrix_hc_im(local_channel)%matrix, name="ot_kp_density_hc_im")
               CALL copy_fm_to_dbcsr(hc_re, density_hc_re)
               CALL copy_fm_to_dbcsr(hc_im, density_hc_im)
               CALL qs_scf_loop_prepare_ot_kp_final_chc(local_ot_env(local_channel), &
                                                        density_hc_re, density_hc_im, &
                                                        scf_control%smear)
               CALL dbcsr_release(density_hc_re)
               CALL dbcsr_release(density_hc_im)
               CALL cp_fm_release(hc_re)
               CALL cp_fm_release(hc_im)
            END IF
            IF (local_ot_env(local_channel)%settings%do_ener) THEN
               eigenvalues(:) = local_ot_env(local_channel)%ener_x(:)
               kp%mos(2, ispin)%eigenvalues(:) = local_ot_env(local_channel)%ener_x(:)
            END IF
         END DO
      END DO
      CALL kpoint_set_mo_occupation(kpoints, scf_control%smear, &
                                    added_mos_auto=scf_control%added_mos_auto, &
                                    added_mos_auto_grow=added_mos_auto_grow, &
                                    electron_tolerance=ot_kp_electron_tolerance)
      IF (.NOT. added_mos_auto_grow .AND. update_ot_energy_state_after) THEN
         IF (.NOT. added_mos_auto_grow) &
            added_mos_auto_grow = qs_scf_loop_ot_kp_added_mos_auto_tail_grow(kpoints, scf_env, &
                                                                             scf_control, nspin_ot)
      END IF
      CALL qs_scf_loop_print_ot_kp_smearing(kpoints, local_ot_env, wkp, para_env_inter_kp, &
                                            scf_control%smear)
      IF (.NOT. added_mos_auto_grow) THEN
         fmwork => scf_env%scf_work1
         IF (ASSOCIATED(scf_env%p_mix_new)) THEN
            density_target => scf_env%p_mix_new
         ELSE
            CALL qs_rho_get(rho, rho_ao_kp=rho_ao_kp)
            density_target => rho_ao_kp
         END IF
         CALL kpoint_density_matrices(kpoints)
         ! Keep Mermin line-search samples variational: the density is generated
         ! only by the sampled OT orbitals and occupations. Canonical density
         ! response belongs in the coupled rotation/energy Schur direction, not
         ! in an independent post-step density map.
         CALL kpoint_density_transform(kpoints, density_target, .FALSE., &
                                       matrix_s(1, 1)%matrix, sab_nl, fmwork, &
                                       overlap_rs=matrix_s, &
                                       qs_ot_env=scf_env%qs_ot_env)
         scf_env%iter_method = scf_env%qs_ot_env(first_channel)%OT_METHOD_FULL
         scf_env%iter_param = scf_env%qs_ot_env(first_channel)%ds_min
         qs_env%broyden_adaptive_sigma = scf_env%qs_ot_env(first_channel)%broyden_adaptive_sigma
      END IF

900   CONTINUE
      IF (ALLOCATED(trial_eigenvalues)) DEALLOCATE (trial_eigenvalues)
      IF (ALLOCATED(trial_occupation)) DEALLOCATE (trial_occupation)
      IF (ALLOCATED(trial_mu)) DEALLOCATE (trial_mu)

      DO local_kpoint = 1, SIZE(matrix_s_cache_re)
         CALL dbcsr_release_p(matrix_s_cache_re(local_kpoint)%matrix)
         CALL dbcsr_release_p(matrix_s_cache_im(local_kpoint)%matrix)
      END DO
      DEALLOCATE (matrix_s_cache_re, matrix_s_cache_im)

      DO local_channel = 1, nlocal_channels
         CALL dbcsr_release_p(matrix_h_cache_re(local_channel)%matrix)
         CALL dbcsr_release_p(matrix_h_cache_im(local_channel)%matrix)
         CALL dbcsr_release(matrix_hc(local_channel)%matrix)
         CALL dbcsr_release(matrix_hc_im(local_channel)%matrix)
         CALL dbcsr_release(matrix_x_old(local_channel)%matrix)
         CALL dbcsr_release(matrix_x_old_im(local_channel)%matrix)
         IF (ASSOCIATED(rot_mat_x_old(local_channel)%matrix)) THEN
            CALL dbcsr_release(rot_mat_x_old(local_channel)%matrix)
            DEALLOCATE (rot_mat_x_old(local_channel)%matrix)
         END IF
         IF (ASSOCIATED(rot_mat_x_old_im(local_channel)%matrix)) THEN
            CALL dbcsr_release(rot_mat_x_old_im(local_channel)%matrix)
            DEALLOCATE (rot_mat_x_old_im(local_channel)%matrix)
         END IF
         DEALLOCATE (matrix_hc(local_channel)%matrix)
         DEALLOCATE (matrix_hc_im(local_channel)%matrix)
         DEALLOCATE (matrix_x_old(local_channel)%matrix)
         DEALLOCATE (matrix_x_old_im(local_channel)%matrix)
      END DO
      DEALLOCATE (ener_x_old, matrix_h_cache_im, matrix_h_cache_re, matrix_hc, matrix_hc_im, &
                  matrix_x_old, matrix_x_old_im, rot_mat_x_old, rot_mat_x_old_im)

      CALL timestop(handle)

   END SUBROUTINE qs_scf_loop_do_ot_kp

! **************************************************************************************************
!> \brief separate the OT model residual from an outer SCF exit floor
!> \param optimizer_delta globally synchronized intrinsic minimizer residual
!> \param exit_floor_delta additional physical/raw residual floor for SCF exit
!> \param model_delta residual retained by the OT minimizer and response model
!> \param outer_delta residual exposed to the outer SCF convergence check
! **************************************************************************************************
   PURE SUBROUTINE qs_scf_kp_residual_split(optimizer_delta, exit_floor_delta, model_delta, outer_delta)

      REAL(KIND=dp), INTENT(IN)                          :: optimizer_delta, exit_floor_delta
      REAL(KIND=dp), INTENT(OUT)                         :: model_delta, outer_delta

      model_delta = MAX(0.0_dp, optimizer_delta)
      outer_delta = MAX(model_delta, MAX(0.0_dp, exit_floor_delta))

   END SUBROUTINE qs_scf_kp_residual_split

! **************************************************************************************************
!> \brief combine the unchanged search residual with independent physical exit guards
!> \param search_delta residual used by the minimizer and subspace-refresh control
!> \param physical_delta complete fixed-N Mermin residual
!> \param physical_ready whether the physical residual is complete
!> \param density_delta fixed-N canonical-density stationarity residual
!> \param density_ready whether the density residual is complete
!> \param calibrated_floor additional calibrated raw/physical exit floor
!> \return residual used only by the final SCF convergence decision
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_exit_residual(search_delta, physical_delta, physical_ready, &
                                         density_delta, density_ready, calibrated_floor) RESULT(exit_delta)
      REAL(KIND=dp), INTENT(IN)                          :: search_delta, physical_delta
      LOGICAL, INTENT(IN)                                :: physical_ready
      REAL(KIND=dp), INTENT(IN)                          :: density_delta
      LOGICAL, INTENT(IN)                                :: density_ready
      REAL(KIND=dp), INTENT(IN)                          :: calibrated_floor
      REAL(KIND=dp)                                      :: exit_delta

      exit_delta = MAX(0.0_dp, search_delta, calibrated_floor)
      IF (physical_ready) exit_delta = MAX(exit_delta, physical_delta)
      IF (density_ready) exit_delta = MAX(exit_delta, density_delta)

   END FUNCTION qs_scf_kp_exit_residual

! **************************************************************************************************
!> \brief Calibrate the conservative raw-residual guard used before fixed-N audits are complete.
!> \param accepted_samples accepted Mermin model-quality samples
!> \param accepted_quality_ema accepted/predicted Mermin-drop quality
!> \param accepted_gap_ema accepted Mermin model-gap quality
!> \return fraction of the raw residual used by the outer SCF convergence test
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_raw_exit_floor_ratio(accepted_samples, accepted_quality_ema, &
                                                accepted_gap_ema) RESULT(ratio)

      INTEGER, INTENT(IN)                                :: accepted_samples
      REAL(KIND=dp), INTENT(IN)                          :: accepted_quality_ema, accepted_gap_ema
      REAL(KIND=dp)                                      :: ratio

      REAL(KIND=dp)                                      :: gap_weight, quality_weight, tail_weight

      ratio = ot_kp_schur_physical_exit_raw_floor_ratio
      IF (accepted_samples >= ot_kp_schur_calibration_min_samples .AND. &
          accepted_quality_ema >= ot_kp_schur_physical_exit_raw_floor_quality .AND. &
          accepted_gap_ema <= ot_kp_schur_physical_exit_raw_floor_gap) THEN
         quality_weight = (accepted_quality_ema - ot_kp_schur_physical_exit_raw_floor_quality)/ &
                          MAX(EPSILON(1.0_dp), &
                              1.0_dp - ot_kp_schur_physical_exit_raw_floor_quality)
         quality_weight = MIN(1.0_dp, MAX(0.0_dp, quality_weight))
         gap_weight = 1.0_dp - accepted_gap_ema/ &
                      MAX(EPSILON(1.0_dp), ot_kp_schur_physical_exit_raw_floor_gap)
         gap_weight = MIN(1.0_dp, MAX(0.0_dp, gap_weight))
         tail_weight = SQRT(quality_weight*gap_weight)
         ratio = (1.0_dp - tail_weight)*ot_kp_schur_physical_exit_raw_floor_ratio + &
                 tail_weight*ot_kp_schur_physical_exit_raw_floor_min_ratio
      END IF

   END FUNCTION qs_scf_kp_raw_exit_floor_ratio

! **************************************************************************************************
!> \brief retain the raw exit floor until both independent fixed-N residuals are complete
!> \param raw_delta preconditioned minimizer residual
!> \param floor_ratio history-calibrated raw-residual fraction
!> \param physical_ready complete projected fixed-N Mermin residual is available
!> \param density_ready complete canonical-density stationarity residual is available
!> \return raw contribution to the final SCF exit residual
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_raw_exit_floor(raw_delta, floor_ratio, physical_ready, density_ready) &
      RESULT(floor_delta)

      REAL(KIND=dp), INTENT(IN)                          :: raw_delta, floor_ratio
      LOGICAL, INTENT(IN)                                :: physical_ready, density_ready
      REAL(KIND=dp)                                      :: floor_delta

      floor_delta = 0.0_dp
      IF (.NOT. (physical_ready .AND. density_ready)) &
         floor_delta = MAX(0.0_dp, floor_ratio)*MAX(0.0_dp, raw_delta)

   END FUNCTION qs_scf_kp_raw_exit_floor

! **************************************************************************************************
!> \brief synchronize k-point OT residual over distributed k-point groups
!> \param local_ot_env ...
!> \param para_env_inter_kp ...
!> \param residual_delta ...
!> \param eps_scf apply the raw-residual exit floor when synchronizing the outer SCF residual;
!>        omit it for internal minimizer/model evaluations
! **************************************************************************************************
   SUBROUTINE qs_scf_loop_sync_ot_kp_global_delta(local_ot_env, para_env_inter_kp, residual_delta, eps_scf)

      TYPE(qs_ot_type), DIMENSION(:), POINTER            :: local_ot_env
      TYPE(mp_para_env_type), POINTER                    :: para_env_inter_kp
      REAL(KIND=dp), INTENT(OUT)                         :: residual_delta
      REAL(KIND=dp), INTENT(IN), OPTIONAL                :: eps_scf

      INTEGER                                            :: local_channel
      REAL(KIND=dp) :: density_stationarity_delta, exit_floor_delta, model_delta, ot_delta, &
         physical_delta, physical_exit_floor_delta, physical_model_delta, raw_delta, &
         raw_floor_ratio

      CPASSERT(SIZE(local_ot_env) > 0)

      ! ot_mini stores the scalar minimizer residual for the complete local
      ! spin/k-point set in channel 1.  The other channel slots only mirror this
      ! value for restart and model diagnostics, and may still contain older
      ! values before this synchronization point.
      ot_delta = local_ot_env(1)%delta
      CALL para_env_inter_kp%max(ot_delta)
      exit_floor_delta = 0.0_dp
      raw_delta = 0.0_dp
      physical_delta = 0.0_dp
      density_stationarity_delta = 0.0_dp
      IF (local_ot_env(1)%kpoint_raw_delta > 0.0_dp) raw_delta = local_ot_env(1)%kpoint_raw_delta
      IF (local_ot_env(1)%kpoint_physical_delta > 0.0_dp) &
         physical_delta = local_ot_env(1)%kpoint_physical_delta
      IF (local_ot_env(1)%kpoint_density_stationarity_ready .AND. &
          local_ot_env(1)%kpoint_density_stationarity_delta > 0.0_dp) &
         density_stationarity_delta = local_ot_env(1)%kpoint_density_stationarity_delta
      CALL para_env_inter_kp%max(raw_delta)
      CALL para_env_inter_kp%max(physical_delta)
      CALL para_env_inter_kp%max(density_stationarity_delta)
      IF (PRESENT(eps_scf)) THEN
         CALL ot_kpoint_physical_residual_split( &
            raw_delta, physical_delta, local_ot_env(1)%kpoint_physical_delta_ready, &
            eps_scf, local_ot_env(1)%mermin_ls_accepted_quality_samples, &
            local_ot_env(1)%mermin_ls_accepted_quality_ema, local_ot_env(1)%mermin_ls_accepted_gap_ema, &
            physical_model_delta, physical_exit_floor_delta)
         CALL para_env_inter_kp%max(physical_exit_floor_delta)
         exit_floor_delta = MAX(exit_floor_delta, physical_exit_floor_delta)
         ! P = f(C^H H C - mu) is the finite-temperature fixed-N
         ! stationarity condition.  Keep its bounded density residual
         ! independent of the optional occupation preconditioner so a
         ! low-entropy auxiliary-energy plateau cannot report convergence.
         exit_floor_delta = MAX(exit_floor_delta, density_stationarity_delta)
         IF (eps_scf > 0.0_dp .AND. raw_delta > ot_delta .AND. &
             local_ot_env(1)%kpoint_physical_delta_ready) THEN
            raw_floor_ratio = qs_scf_kp_raw_exit_floor_ratio( &
                              local_ot_env(1)%mermin_ls_accepted_quality_samples, &
                              local_ot_env(1)%mermin_ls_accepted_quality_ema, &
                              local_ot_env(1)%mermin_ls_accepted_gap_ema)
            ! The preconditioned search metric remains a conservative bootstrap
            ! guard while either fixed-N residual is incomplete.  Once the
            ! projected Mermin gradient and canonical density stationarity are
            ! both available, retaining its inactive-gauge contribution would
            ! make formal convergence coordinate dependent.
            CALL para_env_inter_kp%max(raw_floor_ratio)
            exit_floor_delta = MAX( &
                               exit_floor_delta, &
                               qs_scf_kp_raw_exit_floor( &
                               raw_delta, raw_floor_ratio, &
                               local_ot_env(1)%kpoint_physical_delta_ready, &
                               local_ot_env(1)%kpoint_density_stationarity_ready))
         END IF
      END IF
      CALL qs_scf_kp_residual_split(ot_delta, exit_floor_delta, model_delta, residual_delta)
      DO local_channel = 1, SIZE(local_ot_env)
         local_ot_env(local_channel)%delta = model_delta
      END DO

   END SUBROUTINE qs_scf_loop_sync_ot_kp_global_delta

! **************************************************************************************************
!> \brief apply physical k-point OT residuals only to the final SCF exit decision
!> \param local_ot_env local spin/k-point OT channels
!> \param para_env_inter_kp communicator spanning the distributed k-point groups
!> \param eps_scf requested SCF threshold
!> \param residual_delta on input the search residual, on output the exit residual
! **************************************************************************************************
   SUBROUTINE qs_scf_loop_ot_kp_exit_delta(local_ot_env, para_env_inter_kp, eps_scf, residual_delta)
      TYPE(qs_ot_type), DIMENSION(:), POINTER            :: local_ot_env
      TYPE(mp_para_env_type), POINTER                    :: para_env_inter_kp
      REAL(KIND=dp), INTENT(IN)                          :: eps_scf
      REAL(KIND=dp), INTENT(INOUT)                       :: residual_delta

      INTEGER :: density_stationarity_ready_i, line_search_pending_i, physical_audit_required_i, &
         physical_delta_ready_i, quality_samples
      LOGICAL                                            :: density_stationarity_ready, &
                                                            physical_delta_ready
      REAL(KIND=dp) :: calibrated_floor_delta, density_stationarity_delta, model_delta, ot_delta, &
         physical_delta, quality_ema, quality_gap_ema, raw_delta, raw_floor_ratio
      TYPE(cp_logger_type), POINTER                      :: logger

      ot_delta = 0.0_dp
      raw_delta = 0.0_dp
      physical_delta = 0.0_dp
      density_stationarity_delta = 0.0_dp
      ! These flags mark availability of audits whose metrics have already
      ! been reduced over every spin/k-point channel.  Process replicas that
      ! do not execute the audit therefore contribute the neutral false value.
      physical_delta_ready_i = 0
      density_stationarity_ready_i = 0
      physical_audit_required_i = 0
      line_search_pending_i = 0
      quality_samples = 0
      quality_ema = 0.0_dp
      quality_gap_ema = 0.0_dp
      IF (ASSOCIATED(local_ot_env)) THEN
         IF (SIZE(local_ot_env) > 0) THEN
            ot_delta = MAX(0.0_dp, local_ot_env(1)%delta)
            raw_delta = MAX(0.0_dp, local_ot_env(1)%kpoint_raw_delta)
            physical_delta = MAX(0.0_dp, local_ot_env(1)%kpoint_physical_delta)
            IF (local_ot_env(1)%kpoint_density_stationarity_ready) &
               density_stationarity_delta = &
               MAX(0.0_dp, local_ot_env(1)%kpoint_density_stationarity_delta)
            physical_audit_required_i = MERGE( &
                                        1, 0, local_ot_env(1)%has_complex_kpoint_state .AND. &
                                        local_ot_env(1)%settings%occupation_preconditioner .AND. &
                                        local_ot_env(1)%settings%do_rotation .AND. local_ot_env(1)%settings%do_ener)
            IF (physical_audit_required_i > 0) THEN
               physical_delta_ready_i = MERGE(1, 0, local_ot_env(1)%kpoint_physical_delta_ready)
               density_stationarity_ready_i = &
                  MERGE(1, 0, local_ot_env(1)%kpoint_density_stationarity_ready)
            END IF
            line_search_pending_i = MERGE(1, 0, &
                                          local_ot_env(1)%has_complex_kpoint_state .AND. &
                                          qs_ot_occupation_preconditioner_active(local_ot_env(1)) .AND. &
                                          local_ot_env(1)%settings%do_rotation .AND. &
                                          local_ot_env(1)%settings%do_ener .AND. &
                                          local_ot_env(1)%line_search_count > 0)
            quality_samples = local_ot_env(1)%mermin_ls_accepted_quality_samples
            quality_ema = MAX(0.0_dp, local_ot_env(1)%mermin_ls_accepted_quality_ema)
            quality_gap_ema = MAX(0.0_dp, local_ot_env(1)%mermin_ls_accepted_gap_ema)
         END IF
      END IF
      CALL para_env_inter_kp%max(residual_delta)
      CALL para_env_inter_kp%max(ot_delta)
      CALL para_env_inter_kp%max(raw_delta)
      CALL para_env_inter_kp%max(physical_delta)
      CALL para_env_inter_kp%max(density_stationarity_delta)
      CALL para_env_inter_kp%max(physical_delta_ready_i)
      CALL para_env_inter_kp%max(density_stationarity_ready_i)
      CALL para_env_inter_kp%max(physical_audit_required_i)
      CALL para_env_inter_kp%max(line_search_pending_i)
      CALL para_env_inter_kp%max(quality_samples)
      CALL para_env_inter_kp%max(quality_ema)
      CALL para_env_inter_kp%max(quality_gap_ema)
      physical_delta_ready = physical_delta_ready_i > 0
      density_stationarity_ready = density_stationarity_ready_i > 0

      calibrated_floor_delta = 0.0_dp
      CALL ot_kpoint_physical_residual_split( &
         raw_delta, physical_delta, physical_delta_ready, eps_scf, quality_samples, &
         quality_ema, quality_gap_ema, &
         model_delta, calibrated_floor_delta)
      ! The complete fixed-N residual is an exit condition independent of the
      ! preconditioned search metric.  Applying it here avoids feeding an
      ! exit-only quantity back into subspace refresh and CG/history control.
      IF (physical_delta_ready) &
         calibrated_floor_delta = MAX(calibrated_floor_delta, physical_delta)
      IF (eps_scf > 0.0_dp .AND. raw_delta > ot_delta .AND. &
          physical_delta_ready) THEN
         raw_floor_ratio = qs_scf_kp_raw_exit_floor_ratio( &
                           quality_samples, quality_ema, quality_gap_ema)
         CALL para_env_inter_kp%max(raw_floor_ratio)
         calibrated_floor_delta = MAX( &
                                  calibrated_floor_delta, &
                                  qs_scf_kp_raw_exit_floor( &
                                  raw_delta, raw_floor_ratio, &
                                  physical_delta_ready, density_stationarity_ready))
      END IF
      CALL para_env_inter_kp%max(calibrated_floor_delta)

      residual_delta = qs_scf_kp_exit_residual( &
                       residual_delta, physical_delta, &
                       physical_delta_ready, &
                       density_stationarity_delta, &
                       density_stationarity_ready, &
                       calibrated_floor_delta)
      ! A subspace refresh invalidates the reduced Schur audit until the new
      ! gradient has traversed every fixed-N group.  Missing physical data is
      ! therefore a convergence veto for metallic complex OT, not a zero
      ! residual.  The same rule applies to the canonical-density audit.
      IF (physical_audit_required_i > 0 .AND. &
          (.NOT. physical_delta_ready .OR. .NOT. density_stationarity_ready) .AND. &
          eps_scf > 0.0_dp) &
         residual_delta = MAX(residual_delta, eps_scf*(1.0_dp + 10.0_dp*EPSILON(1.0_dp)))
      ! A residual sampled at an unfinished Mermin line-search probe is not an
      ! accepted variational state. Complete the interpolation before allowing
      ! the outer SCF loop to declare convergence.
      IF (line_search_pending_i > 0 .AND. eps_scf > 0.0_dp) &
         residual_delta = MAX(residual_delta, eps_scf*(1.0_dp + 10.0_dp*EPSILON(1.0_dp)))

      logger => cp_get_default_logger()
      IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
         WRITE (cp_logger_get_default_unit_nr(logger), '(A,4(1X,L1),8(1X,ES16.8),3(1X,I6))') &
         " OT k-point outer exit audit physical density required pending search raw physical density floor exit eps "// &
         "qema samples pready dready:", &
         physical_delta_ready, density_stationarity_ready, physical_audit_required_i > 0, &
         line_search_pending_i > 0, ot_delta, raw_delta, physical_delta, density_stationarity_delta, &
         calibrated_floor_delta, residual_delta, eps_scf, quality_ema, quality_samples, &
         physical_delta_ready_i, density_stationarity_ready_i

   END SUBROUTINE qs_scf_loop_ot_kp_exit_delta

! **************************************************************************************************
!> \brief check the complex REF overlap spectrum after a k-point OT step
!> \param kpoints ...
!> \param local_ot_env ...
!> \param first_channel ...
!> \param nspin_ot ...
!> \param matrix_s_cache_re cached real overlap matrices for local k-points
!> \param matrix_s_cache_im cached imaginary overlap matrices for local k-points
!> \param para_env_inter_kp ...
!> \param ref_overlap_min ...
!> \param ref_overlap_max ...
!> \return true if all local/global REF overlaps remain safely positive
! **************************************************************************************************
   FUNCTION qs_scf_loop_ot_kp_ref_overlap_guard_ok(kpoints, local_ot_env, first_channel, nspin_ot, &
                                                   matrix_s_cache_re, matrix_s_cache_im, &
                                                   para_env_inter_kp, &
                                                   ref_overlap_min, ref_overlap_max) RESULT(ok)

      TYPE(kpoint_type), POINTER                         :: kpoints
      TYPE(qs_ot_type), DIMENSION(:), POINTER            :: local_ot_env
      INTEGER, INTENT(IN)                                :: first_channel, nspin_ot
      TYPE(dbcsr_p_type), DIMENSION(:), POINTER          :: matrix_s_cache_re, matrix_s_cache_im
      TYPE(mp_para_env_type), POINTER                    :: para_env_inter_kp
      REAL(KIND=dp), INTENT(OUT)                         :: ref_overlap_min, ref_overlap_max
      LOGICAL                                            :: ok

      INTEGER                                            :: ikpoint, ispin, local_channel, &
                                                            local_kpoint
      REAL(KIND=dp)                                      :: channel_max, channel_min
      TYPE(dbcsr_type), POINTER                          :: matrix_s_im, matrix_s_re
      TYPE(kpoint_env_type), POINTER                     :: kp

      NULLIFY (matrix_s_im, matrix_s_re)
      ref_overlap_min = HUGE(1.0_dp)
      ref_overlap_max = -HUGE(1.0_dp)
      DO local_kpoint = 1, SIZE(kpoints%kp_env)
         kp => kpoints%kp_env(local_kpoint)%kpoint_env
         ikpoint = kp%nkpoint
         matrix_s_re => matrix_s_cache_re(local_kpoint)%matrix
         matrix_s_im => matrix_s_cache_im(local_kpoint)%matrix
         DO ispin = 1, nspin_ot
            local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
            CALL qs_scf_loop_ot_ref_overlap_bounds(local_ot_env(local_channel), matrix_s_re, matrix_s_im, &
                                                   channel_min, channel_max)
            ref_overlap_min = MIN(ref_overlap_min, channel_min)
            ref_overlap_max = MAX(ref_overlap_max, channel_max)
         END DO
      END DO
      CALL para_env_inter_kp%min(ref_overlap_min)
      CALL para_env_inter_kp%max(ref_overlap_max)
      ok = ref_overlap_min > ot_kp_ref_overlap_guard_floor

   END FUNCTION qs_scf_loop_ot_kp_ref_overlap_guard_ok

! **************************************************************************************************
!> \brief compute min/max eigenvalues of C(k)^H S(k) C(k) for one OT channel
!> \param qs_ot_env ...
!> \param matrix_s ...
!> \param matrix_s_im ...
!> \param ref_overlap_min ...
!> \param ref_overlap_max ...
! **************************************************************************************************
   SUBROUTINE qs_scf_loop_ot_ref_overlap_bounds(qs_ot_env, matrix_s, matrix_s_im, &
                                                ref_overlap_min, ref_overlap_max)

      TYPE(qs_ot_type)                                   :: qs_ot_env
      TYPE(dbcsr_type), POINTER                          :: matrix_s, matrix_s_im
      REAL(KIND=dp), INTENT(OUT)                         :: ref_overlap_min, ref_overlap_max

      INTEGER                                            :: k, n
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: eig
      TYPE(dbcsr_type)                                   :: evec_im, evec_re
      TYPE(dbcsr_type), POINTER                          :: c_im, c_re, f_re, p_im, p_re, sc_im, &
                                                            sc_re, tmp

      ref_overlap_min = 1.0_dp
      ref_overlap_max = 1.0_dp
      CPASSERT(qs_ot_env%has_complex_kpoint_state)
      c_re => qs_ot_env%matrix_x
      c_im => qs_ot_env%matrix_x_im
      sc_re => qs_ot_env%matrix_sx
      sc_im => qs_ot_env%matrix_sx_im
      tmp => qs_ot_env%buf1_n_k
      p_re => qs_ot_env%p_k_k_sym
      p_im => qs_ot_env%buf1_k_k_sym
      f_re => qs_ot_env%buf2_k_k_sym

      CALL dbcsr_get_info(c_re, nfullrows_total=n, nfullcols_total=k)
      IF (k == 0) RETURN

      CALL dbcsr_multiply('N', 'N', 1.0_dp, matrix_s, c_re, 0.0_dp, sc_re)
      CALL dbcsr_multiply('N', 'N', 1.0_dp, matrix_s_im, c_im, 0.0_dp, tmp)
      CALL dbcsr_add(sc_re, tmp, alpha_scalar=1.0_dp, beta_scalar=-1.0_dp)

      CALL dbcsr_multiply('N', 'N', 1.0_dp, matrix_s, c_im, 0.0_dp, sc_im)
      CALL dbcsr_multiply('N', 'N', 1.0_dp, matrix_s_im, c_re, 0.0_dp, tmp)
      CALL dbcsr_add(sc_im, tmp, alpha_scalar=1.0_dp, beta_scalar=1.0_dp)

      CALL dbcsr_multiply('T', 'N', 1.0_dp, c_re, sc_re, 0.0_dp, p_re)
      CALL dbcsr_multiply('T', 'N', 1.0_dp, c_im, sc_im, 0.0_dp, f_re)
      CALL dbcsr_add(p_re, f_re, alpha_scalar=1.0_dp, beta_scalar=1.0_dp)

      CALL dbcsr_multiply('T', 'N', 1.0_dp, c_re, sc_im, 0.0_dp, p_im)
      CALL dbcsr_multiply('T', 'N', 1.0_dp, c_im, sc_re, 0.0_dp, f_re)
      CALL dbcsr_add(p_im, f_re, alpha_scalar=1.0_dp, beta_scalar=-1.0_dp)

      ALLOCATE (eig(k))
      CALL dbcsr_copy(evec_re, p_re, name="ot_kp_ref_overlap_evec_re")
      CALL dbcsr_copy(evec_im, p_im, name="ot_kp_ref_overlap_evec_im")
      CALL cp_dbcsr_heevd(matrix_re=p_re, &
                          matrix_im=p_im, &
                          eigenvectors_re=evec_re, &
                          eigenvectors_im=evec_im, &
                          eigenvalues=eig, &
                          para_env=qs_ot_env%para_env, &
                          blacs_env=qs_ot_env%blacs_env)
      ref_overlap_min = MINVAL(eig)
      ref_overlap_max = MAXVAL(eig)
      CALL dbcsr_release(evec_re)
      CALL dbcsr_release(evec_im)
      DEALLOCATE (eig)

   END SUBROUTINE qs_scf_loop_ot_ref_overlap_bounds

! **************************************************************************************************
!> \brief blend an unsafe k-point OT step back toward the previous accepted state
!> \param local_ot_env ...
!> \param matrix_x_old ...
!> \param matrix_x_old_im ...
!> \param rot_mat_x_old ...
!> \param rot_mat_x_old_im ...
!> \param ener_x_old ...
!> \param scale_new ...
! **************************************************************************************************
   SUBROUTINE qs_scf_loop_blend_ot_kp_ref_step(local_ot_env, matrix_x_old, matrix_x_old_im, &
                                               rot_mat_x_old, rot_mat_x_old_im, ener_x_old, scale_new)

      TYPE(qs_ot_type), DIMENSION(:), POINTER            :: local_ot_env
      TYPE(dbcsr_p_type), DIMENSION(:), POINTER          :: matrix_x_old, matrix_x_old_im, &
                                                            rot_mat_x_old, rot_mat_x_old_im
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: ener_x_old
      REAL(KIND=dp), INTENT(IN)                          :: scale_new

      INTEGER                                            :: local_channel, ncoef

      DO local_channel = 1, SIZE(local_ot_env)
         CALL dbcsr_add(local_ot_env(local_channel)%matrix_x, matrix_x_old(local_channel)%matrix, &
                        alpha_scalar=scale_new, beta_scalar=1.0_dp - scale_new)
         CALL dbcsr_add(local_ot_env(local_channel)%matrix_x_im, matrix_x_old_im(local_channel)%matrix, &
                        alpha_scalar=scale_new, beta_scalar=1.0_dp - scale_new)
         IF (ASSOCIATED(local_ot_env(local_channel)%rot_mat_x) .AND. &
             ASSOCIATED(rot_mat_x_old(local_channel)%matrix)) THEN
            CALL dbcsr_add(local_ot_env(local_channel)%rot_mat_x, rot_mat_x_old(local_channel)%matrix, &
                           alpha_scalar=scale_new, beta_scalar=1.0_dp - scale_new)
         END IF
         IF (ASSOCIATED(local_ot_env(local_channel)%rot_mat_x_im) .AND. &
             ASSOCIATED(rot_mat_x_old_im(local_channel)%matrix)) THEN
            CALL dbcsr_add(local_ot_env(local_channel)%rot_mat_x_im, rot_mat_x_old_im(local_channel)%matrix, &
                           alpha_scalar=scale_new, beta_scalar=1.0_dp - scale_new)
         END IF
         IF (ASSOCIATED(local_ot_env(local_channel)%ener_x)) THEN
            ncoef = SIZE(local_ot_env(local_channel)%ener_x)
            local_ot_env(local_channel)%ener_x(:) = &
               scale_new*local_ot_env(local_channel)%ener_x(:) + &
               (1.0_dp - scale_new)*ener_x_old(1:ncoef, local_channel)
         END IF
      END DO

   END SUBROUTINE qs_scf_loop_blend_ot_kp_ref_step

! **************************************************************************************************
!> \brief update the staged complex k-point occupation-preconditioner runtime state
!> \param local_ot_env ...
! **************************************************************************************************
   SUBROUTINE qs_scf_loop_update_ot_kp_occ_preconditioner(local_ot_env)

      TYPE(qs_ot_type), DIMENSION(:), POINTER            :: local_ot_env

      INTEGER                                            :: local_channel, previous_samples, samples
      LOGICAL                                            :: active, at_search_boundary, changed, &
                                                            closure_reference_safe, complex_state, &
                                                            previous_active
      TYPE(cp_logger_type), POINTER                      :: logger

      complex_state = .FALSE.
      DO local_channel = 1, SIZE(local_ot_env)
         complex_state = complex_state .OR. local_ot_env(local_channel)%has_complex_kpoint_state
      END DO
      previous_active = local_ot_env(1)%kpoint_occ_preconditioner_active
      previous_samples = local_ot_env(1)%kpoint_occ_preconditioner_ready_samples
      at_search_boundary = local_ot_env(1)%line_search_count == 0 .OR. &
                           local_ot_env(1)%line_search_might_be_done
      closure_reference_safe = at_search_boundary .AND. &
                               local_ot_env(1)%mermin_ls_closure_rejected .AND. &
                               local_ot_env(1)%kpoint_eps_scf > 0.0_dp .AND. &
                               local_ot_env(1)%mermin_ls_reference_delta > 0.0_dp .AND. &
                               local_ot_env(1)%mermin_ls_reference_delta <= &
                               ot_kp_schur_projector_coupled_tail_delta .AND. &
                               local_ot_env(1)%schur_model_density_stationarity_delta >= 0.0_dp .AND. &
                               local_ot_env(1)%schur_model_density_stationarity_delta <= &
                               local_ot_env(1)%kpoint_eps_scf

      CALL qs_scf_kp_occ_preconditioner_transition( &
         local_ot_env(1)%settings%occupation_preconditioner, complex_state, at_search_boundary, &
         local_ot_env(1)%mermin_ls_closure_rejected, closure_reference_safe, &
         local_ot_env(1)%delta, previous_active, previous_samples, active, samples, changed)

      IF (changed) CALL qs_scf_loop_reset_ot_kp_guard_state(local_ot_env)
      DO local_channel = 1, SIZE(local_ot_env)
         local_ot_env(local_channel)%kpoint_occ_preconditioner_active = active
         local_ot_env(local_channel)%kpoint_occ_preconditioner_ready_samples = samples
         IF (changed) &
            local_ot_env(local_channel)%kpoint_occ_metric_residual_quality_ema = 0.0_dp
      END DO
      IF (changed) THEN
         local_ot_env(1)%schur_vector_secant_candidate_enabled = .FALSE.
         local_ot_env(1)%schur_vector_secant_quality_samples = 0
         local_ot_env(1)%schur_vector_secant_quality = 0.0_dp
         local_ot_env(1)%schur_vector_secant_quality_ema = 0.0_dp
         local_ot_env(1)%schur_vector_secant_residual_quality = 0.0_dp
         local_ot_env(1)%schur_vector_secant_residual_quality_ema = 0.0_dp
         local_ot_env(1)%schur_vector_secant_drop_sum = 0.0_dp
         local_ot_env(1)%schur_vector_secant_measured_sum = 0.0_dp
         local_ot_env(1)%schur_multisecant_candidate_enabled = .FALSE.
         local_ot_env(1)%schur_multisecant_quality_samples = 0
         local_ot_env(1)%schur_multisecant_quality = 0.0_dp
         local_ot_env(1)%schur_multisecant_quality_ema = 0.0_dp
         local_ot_env(1)%schur_multisecant_residual_quality = 0.0_dp
         local_ot_env(1)%schur_multisecant_residual_quality_ema = 0.0_dp
         local_ot_env(1)%schur_multisecant_drop_sum = 0.0_dp
         local_ot_env(1)%schur_multisecant_measured_sum = 0.0_dp
         local_ot_env(1)%schur_prediction_candidate_enabled = .FALSE.
         local_ot_env(1)%schur_prediction_quality_samples = 0
         local_ot_env(1)%schur_prediction_quality = 0.0_dp
         local_ot_env(1)%schur_prediction_quality_ema = 0.0_dp
         local_ot_env(1)%schur_prediction_residual_quality = 0.0_dp
         local_ot_env(1)%schur_prediction_residual_quality_ema = 0.0_dp
         local_ot_env(1)%schur_prediction_drop_sum = 0.0_dp
         local_ot_env(1)%schur_prediction_measured_sum = 0.0_dp
         local_ot_env(1)%schur_reduced_secant_shadow_validated = .FALSE.
         local_ot_env(1)%schur_reduced_secant_quality_samples = 0
         local_ot_env(1)%schur_reduced_secant_quality = 0.0_dp
         local_ot_env(1)%schur_reduced_secant_quality_ema = 0.0_dp
         local_ot_env(1)%schur_reduced_secant_residual_quality = 0.0_dp
         local_ot_env(1)%schur_reduced_secant_residual_quality_ema = 0.0_dp
         local_ot_env(1)%schur_reduced_secant_drop_sum = 0.0_dp
         local_ot_env(1)%schur_reduced_secant_measured_sum = 0.0_dp
         local_ot_env(1)%schur_closure_candidate_validated = .FALSE.
         local_ot_env(1)%schur_closure_candidate_quality_samples = 0
         local_ot_env(1)%schur_closure_candidate_quality = 0.0_dp
         local_ot_env(1)%schur_closure_candidate_quality_ema = 0.0_dp
         local_ot_env(1)%schur_closure_candidate_residual_quality = 0.0_dp
         local_ot_env(1)%schur_closure_candidate_residual_quality_ema = 0.0_dp
         local_ot_env(1)%schur_closure_candidate_residual_gain = 0.0_dp
         local_ot_env(1)%schur_closure_candidate_residual_gain_ema = 0.0_dp
         local_ot_env(1)%schur_closure_candidate_residual_coverage = 0.0_dp
         local_ot_env(1)%schur_closure_candidate_residual_coverage_ema = 0.0_dp
         local_ot_env(1)%schur_closure_candidate_drop_sum = 0.0_dp
         local_ot_env(1)%schur_closure_candidate_measured_sum = 0.0_dp
      END IF

      IF (changed .OR. samples /= previous_samples) THEN
         logger => cp_get_default_logger()
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,3(1X,L1),2(1X,I3),1X,ES16.8)') &
            " OT k-point occupation preconditioner boundary active changed ready previous delta:", &
            at_search_boundary, active, changed, samples, previous_samples, local_ot_env(1)%delta
      END IF

   END SUBROUTINE qs_scf_loop_update_ot_kp_occ_preconditioner

! **************************************************************************************************
!> \brief invalidate k-point OT line-search and pending model state after accepted-state projection
!> \param local_ot_env ...
! **************************************************************************************************
   SUBROUTINE qs_scf_loop_reset_ot_kp_guard_state(local_ot_env)

      TYPE(qs_ot_type), DIMENSION(:), POINTER            :: local_ot_env

      INTEGER                                            :: local_channel

      local_ot_env(1)%ot_pos(:) = 0.0_dp
      local_ot_env(1)%ot_energy(:) = 0.0_dp
      local_ot_env(1)%ot_grad(:) = 0.0_dp
      local_ot_env(1)%line_search_left = -1
      local_ot_env(1)%line_search_right = -1
      local_ot_env(1)%line_search_mid = -1
      local_ot_env(1)%line_search_count = 0
      local_ot_env(1)%line_search_might_be_done = .FALSE.
      local_ot_env(1)%mermin_ls_sample_pending = .FALSE.
      local_ot_env(1)%mermin_ls_closure_rejected = .FALSE.
      local_ot_env(1)%energy_only = .FALSE.
      local_ot_env(1)%ds_min = local_ot_env(1)%settings%ds_min
      local_ot_env(1)%schur_model_pending = .FALSE.
      local_ot_env(1)%schur_constrained_pending = .FALSE.
      local_ot_env(1)%schur_split_shadow_pending = .FALSE.
      local_ot_env(1)%schur_occgap_shadow_pending = .FALSE.
      local_ot_env(1)%schur_vector_secant_pending = .FALSE.
      local_ot_env(1)%schur_multisecant_pending = .FALSE.
      local_ot_env(1)%schur_prediction_pending = .FALSE.
      local_ot_env(1)%schur_reduced_secant_pending = .FALSE.
      local_ot_env(1)%schur_reduced_secant_model_groups = 0
      local_ot_env(1)%schur_reduced_secant_selected_groups = 0
      local_ot_env(1)%schur_reduced_secant_rot_residual_start_sq = 0.0_dp
      local_ot_env(1)%schur_reduced_secant_rot_residual_delta_dot = 0.0_dp
      local_ot_env(1)%schur_reduced_secant_rot_residual_delta_sq = 0.0_dp
      local_ot_env(1)%schur_closure_candidate_pending = .FALSE.
      local_ot_env(1)%schur_closure_candidate_model_groups = 0
      local_ot_env(1)%schur_closure_candidate_selected_groups = 0
      local_ot_env(1)%schur_closure_candidate_rot_residual_start_sq = 0.0_dp
      local_ot_env(1)%schur_closure_candidate_rot_residual_delta_dot = 0.0_dp
      local_ot_env(1)%schur_closure_candidate_rot_residual_delta_sq = 0.0_dp
      local_ot_env(1)%schur_dense_metric_shadow_pending = .FALSE.
      local_ot_env(1)%schur_projector_mode_pending = .FALSE.
      local_ot_env(1)%schur_projector_offdiag_pending = .FALSE.
      local_ot_env(1)%schur_projector_inactive_offdiag_pending = .FALSE.
      local_ot_env(1)%schur_projector_response_pending = .FALSE.
      local_ot_env(1)%schur_projector_plateau_gap_pending = .FALSE.
      local_ot_env(1)%schur_projector_physical_pending = .FALSE.
      local_ot_env(1)%schur_projector_mixed_direct_pending = .FALSE.
      local_ot_env(1)%schur_projector_spectral_pending = .FALSE.
      local_ot_env(1)%schur_projector_diagref_pending = .FALSE.
      local_ot_env(1)%schur_projector_density_pending = .FALSE.
      local_ot_env(1)%schur_projector_density_audit_pending = .FALSE.
      local_ot_env(1)%schur_projector_density_descent_pending = .FALSE.
      local_ot_env(1)%schur_projector_density_full_pending = .FALSE.
      local_ot_env(1)%schur_projector_density_full_direct_pending = .FALSE.
      local_ot_env(1)%schur_projector_density_full_global_pending = .FALSE.
      local_ot_env(1)%schur_history_mixed = .FALSE.
      local_ot_env(1)%schur_model_attempt = 0
      local_ot_env(1)%schur_model_flavor = 0
      local_ot_env(1)%schur_model_drop = 0.0_dp
      local_ot_env(1)%schur_model_calibrated_drop = 0.0_dp
      local_ot_env(1)%schur_model_slope = 0.0_dp
      local_ot_env(1)%schur_model_quadratic = 0.0_dp
      local_ot_env(1)%schur_model_gap_ratio = 0.0_dp
      local_ot_env(1)%schur_model_control_delta = 0.0_dp
      local_ot_env(1)%schur_closure_response_pending = .FALSE.
      local_ot_env(1)%schur_closure_response_model_delta = 0.0_dp
      local_ot_env(1)%schur_closure_response_model_density_delta = -1.0_dp
      local_ot_env(1)%schur_closure_shadow_pending = .FALSE.
      local_ot_env(1)%schur_closure_shadow_baseline_quadratic = 0.0_dp
      local_ot_env(1)%schur_closure_shadow_quadratic = 0.0_dp
      local_ot_env(1)%schur_closure_full_shadow_pending = .FALSE.
      local_ot_env(1)%schur_closure_full_shadow_baseline_quadratic = 0.0_dp
      local_ot_env(1)%schur_closure_full_shadow_quadratic = 0.0_dp
      local_ot_env(1)%schur_closure_vector_shadow_pending = .FALSE.
      local_ot_env(1)%schur_closure_vector_shadow_consistent = .FALSE.
      local_ot_env(1)%schur_closure_vector_shadow_work_consistent = .FALSE.
      local_ot_env(1)%schur_closure_vector_shadow_baseline_quadratic = 0.0_dp
      local_ot_env(1)%schur_closure_vector_shadow_quadratic = 0.0_dp
      local_ot_env(1)%schur_residual_history_reset_pending = .FALSE.
      local_ot_env(1)%schur_residual_history_quality = 1.0_dp
      local_ot_env(1)%gnorm = 0.0_dp
      local_ot_env(1)%gnorm_old = 1.0_dp
      DO local_channel = 1, SIZE(local_ot_env)
         IF (ASSOCIATED(local_ot_env(local_channel)%matrix_dx)) &
            CALL dbcsr_set(local_ot_env(local_channel)%matrix_dx, 0.0_dp)
         IF (ASSOCIATED(local_ot_env(local_channel)%matrix_dx_im)) &
            CALL dbcsr_set(local_ot_env(local_channel)%matrix_dx_im, 0.0_dp)
         IF (ASSOCIATED(local_ot_env(local_channel)%matrix_gx_old)) &
            CALL dbcsr_set(local_ot_env(local_channel)%matrix_gx_old, 0.0_dp)
         IF (ASSOCIATED(local_ot_env(local_channel)%matrix_gx_old_im)) &
            CALL dbcsr_set(local_ot_env(local_channel)%matrix_gx_old_im, 0.0_dp)
         IF (ASSOCIATED(local_ot_env(local_channel)%rot_mat_dx)) &
            CALL dbcsr_set(local_ot_env(local_channel)%rot_mat_dx, 0.0_dp)
         IF (ASSOCIATED(local_ot_env(local_channel)%rot_mat_dx_im)) &
            CALL dbcsr_set(local_ot_env(local_channel)%rot_mat_dx_im, 0.0_dp)
         IF (ASSOCIATED(local_ot_env(local_channel)%rot_mat_gx_old)) &
            CALL dbcsr_set(local_ot_env(local_channel)%rot_mat_gx_old, 0.0_dp)
         IF (ASSOCIATED(local_ot_env(local_channel)%rot_mat_gx_old_im)) &
            CALL dbcsr_set(local_ot_env(local_channel)%rot_mat_gx_old_im, 0.0_dp)
         IF (ASSOCIATED(local_ot_env(local_channel)%ener_dx)) &
            local_ot_env(local_channel)%ener_dx(:) = 0.0_dp
         IF (ASSOCIATED(local_ot_env(local_channel)%ener_gx_old)) &
            local_ot_env(local_channel)%ener_gx_old(:) = 0.0_dp
         local_ot_env(local_channel)%mermin_ls_component_slope_valid = .FALSE.
         local_ot_env(local_channel)%ener_direction_linear = .FALSE.
         local_ot_env(local_channel)%ener_x_fermi_guard_position_max = -1.0_dp
         local_ot_env(local_channel)%ener_x_line_search_position = 0.0_dp
         local_ot_env(local_channel)%ener_x_line_search_tangent = 1.0_dp
         local_ot_env(local_channel)%kpoint_preconditioned_direction_ready = .FALSE.
      END DO

   END SUBROUTINE qs_scf_loop_reset_ot_kp_guard_state

! **************************************************************************************************
!> \brief request one full-kernel subspace refresh after metallic occupations have collapsed
!> \param kpoints ...
!> \param local_ot_env ...
!> \param nspin_ot ...
!> \param wkp ...
!> \param para_env_inter_kp ...
!> \param smear ...
!> \param added_mos_auto whether each spin channel uses adaptive virtual-space growth
!> \param added_mos current added-MO buffer for each spin channel
!> \param trial_occupation ...
!> \param scf_iteration ...
!> \param scf_residual ...
!> \param eps_scf ...
!> \param restart_valid ...
!> \param accepted_sample ...
!> \param fermi_window_guarded ...
!> \param allow_refresh ...
!> \param allow_orbital_tail_rebase ...
!> \return true when the current OT virtual subspace must be rebuilt by diagonalization
! **************************************************************************************************
   FUNCTION qs_scf_loop_ot_kp_subspace_refresh_needed( &
      kpoints, local_ot_env, nspin_ot, wkp, para_env_inter_kp, smear, &
      added_mos_auto, added_mos, trial_occupation, &
      scf_iteration, scf_residual, eps_scf, restart_valid, accepted_sample, &
      fermi_window_guarded, allow_refresh, allow_orbital_tail_rebase) RESULT(refresh)

      TYPE(kpoint_type), POINTER                         :: kpoints
      TYPE(qs_ot_type), DIMENSION(:), POINTER            :: local_ot_env
      INTEGER, INTENT(IN)                                :: nspin_ot
      REAL(KIND=dp), DIMENSION(:), POINTER               :: wkp
      TYPE(mp_para_env_type), POINTER                    :: para_env_inter_kp
      TYPE(smear_type), INTENT(IN)                       :: smear
      LOGICAL, DIMENSION(:), INTENT(IN)                  :: added_mos_auto
      INTEGER, DIMENSION(:), INTENT(IN)                  :: added_mos
      REAL(KIND=dp), DIMENSION(:, :, :), INTENT(IN)      :: trial_occupation
      INTEGER, INTENT(IN)                                :: scf_iteration
      REAL(KIND=dp), INTENT(IN)                          :: scf_residual, eps_scf
      LOGICAL, INTENT(IN)                                :: restart_valid, accepted_sample, &
                                                            fermi_window_guarded, allow_refresh, &
                                                            allow_orbital_tail_rebase
      LOGICAL                                            :: refresh

      INTEGER                                            :: density_buffer_ready_i, ikpoint, imo, &
                                                            ispin, local_kpoint, nmo
      LOGICAL :: base_state, collapsed, defer_energy_closure, density_buffer_ready, &
         density_closure_stagnant, density_history_stagnant, high_residual_stagnant, &
         orbital_tail_rebase, step_ready
      REAL(KIND=dp)                                      :: fractional_weight, max_partial_fraction, &
                                                            maxocc, occ_tail, residual_delta, &
                                                            weight
      TYPE(cp_logger_type), POINTER                      :: logger
      TYPE(kpoint_env_type), POINTER                     :: kp

      refresh = .FALSE.
      IF ((.NOT. allow_refresh .AND. .NOT. allow_orbital_tail_rebase) .OR. &
          fermi_window_guarded) RETURN
      IF (.NOT. smear%do_smear .OR. .NOT. kpoint_ot_monotone_smearing(smear%method)) RETURN
      IF (kpoint_ot_smearing_width(smear) <= 1.0E-14_dp) RETURN
      IF (.NOT. kpoint_ot_project_energy_subproblem(local_ot_env(1), smear)) RETURN
      IF (local_ot_env(1)%energy_only) RETURN

      fractional_weight = 0.0_dp
      max_partial_fraction = 0.0_dp
      density_buffer_ready_i = 1
      DO local_kpoint = 1, SIZE(kpoints%kp_env)
         kp => kpoints%kp_env(local_kpoint)%kpoint_env
         ikpoint = kp%nkpoint
         DO ispin = 1, nspin_ot
            CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, nmo=nmo)
            IF (maxocc <= EPSILON(maxocc)) CYCLE
            IF (ispin <= SIZE(added_mos_auto) .AND. ispin <= SIZE(added_mos)) THEN
               IF (.NOT. qs_scf_kp_density_closure_buffer_ready( &
                   added_mos_auto(ispin), added_mos(ispin), nmo)) density_buffer_ready_i = 0
            END IF
            weight = ABS(wkp(ikpoint))
            DO imo = 1, MIN(nmo, SIZE(trial_occupation, 1))
               occ_tail = MAX(0.0_dp, MIN(trial_occupation(imo, ikpoint, ispin), &
                                          maxocc - trial_occupation(imo, ikpoint, ispin)))
               fractional_weight = fractional_weight + weight*occ_tail/maxocc
               max_partial_fraction = MAX(max_partial_fraction, occ_tail/maxocc)
            END DO
         END DO
      END DO
      CALL para_env_inter_kp%sum(fractional_weight)
      CALL para_env_inter_kp%max(max_partial_fraction)
      CALL para_env_inter_kp%min(density_buffer_ready_i)
      density_buffer_ready = density_buffer_ready_i > 0

      collapsed = qs_scf_kp_subspace_is_collapsed(max_partial_fraction)
      residual_delta = MAX(scf_residual, local_ot_env(1)%delta)
      step_ready = qs_scf_kp_subspace_refresh_step_ready( &
                   restart_valid, local_ot_env(1)%OT_count, &
                   local_ot_env(1)%kpoint_subspace_accepted_samples, &
                   ot_kp_subspace_refresh_min_steps)
      base_state = local_ot_env(1)%line_search_count == 0 .OR. accepted_sample .OR. &
                   (restart_valid .AND. scf_iteration <= 1)
      high_residual_stagnant = residual_delta > SQRT(MAX(eps_scf, EPSILON(1.0_dp))) .AND. &
                               local_ot_env(1)%ds_min <= &
                               MAX(eps_scf, SQRT(EPSILON(1.0_dp)))
      defer_energy_closure = qs_scf_kp_energy_occupation_plateau_ready( &
                             local_ot_env(1)%kpoint_density_stationarity_ready, &
                             local_ot_env(1)%kpoint_density_stationarity_diag, &
                             local_ot_env(1)%kpoint_density_stationarity_offdiag, &
                             local_ot_env(1)%mermin_ls_accepted_quality_samples) .AND. &
                             .NOT. local_ot_env(1)%kpoint_energy_closure_attempted .AND. &
                             .NOT. high_residual_stagnant
      density_closure_stagnant = local_ot_env(1)%kpoint_density_stationarity_ready .AND. &
                                 density_buffer_ready .AND. &
                                 qs_scf_kp_density_closure_refresh_ready( &
                                 residual_delta, &
                                 local_ot_env(1)%kpoint_density_stationarity_delta, eps_scf)
      density_history_stagnant = density_buffer_ready .AND. &
                                 qs_scf_kp_density_closure_history_refresh_ready( &
                                 local_ot_env(1)%kpoint_density_stationarity_ready, &
                                 local_ot_env(1)%kpoint_density_stationarity_delta, &
                                 local_ot_env(1)%kpoint_raw_delta, eps_scf, &
                                 local_ot_env(1)%schur_density_stationarity_quality_samples, &
                                 local_ot_env(1)%schur_density_stationarity_quality_ema)
      orbital_tail_rebase = density_buffer_ready .AND. &
                            local_ot_env(1)%kpoint_complete_physical_delta >= 0.0_dp .AND. &
                            qs_scf_kp_orbital_tail_rebase_ready( &
                            local_ot_env(1)%kpoint_density_stationarity_ready, &
                            local_ot_env(1)%kpoint_density_stationarity_delta, &
                            local_ot_env(1)%kpoint_complete_physical_delta, eps_scf, &
                            local_ot_env(1)%schur_closure_response_samples, &
                            local_ot_env(1)%schur_closure_response_quality_ema)
      density_closure_stagnant = density_closure_stagnant .OR. density_history_stagnant
      ! Reserve one search direction for the diagonal fixed-N energy closure before
      ! replacing the orbital subspace; a later refresh re-arms this one-shot attempt.
      IF (defer_energy_closure) RETURN
      refresh = qs_scf_kp_subspace_refresh_gate(allow_refresh, fermi_window_guarded, collapsed, &
                                                residual_delta, eps_scf, step_ready, base_state, &
                                                high_residual_stagnant, density_closure_stagnant)
      IF (.NOT. refresh .AND. allow_orbital_tail_rebase .AND. orbital_tail_rebase) &
         refresh = qs_scf_kp_subspace_refresh_gate(.TRUE., fermi_window_guarded, .FALSE., &
                                                   residual_delta, eps_scf, step_ready, base_state, &
                                                   density_closure_stagnant=.TRUE.)

      logger => cp_get_default_logger()
      IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source() .AND. &
          (collapsed .OR. density_closure_stagnant .OR. orbital_tail_rebase) .AND. step_ready) &
         WRITE (cp_logger_get_default_unit_nr(logger), '(A,7(1X,L1),2(1X,I6),7(1X,ES16.8))') &
         " OT k-point subspace refresh ready restart stagnant buffer closure history "// &
         "orbital step epoch residual physical density dqema pqema frac max:", &
         refresh, restart_valid, high_residual_stagnant, density_buffer_ready, density_closure_stagnant, &
         density_history_stagnant, orbital_tail_rebase, local_ot_env(1)%OT_count, &
         local_ot_env(1)%kpoint_subspace_accepted_samples, residual_delta, &
         local_ot_env(1)%kpoint_complete_physical_delta, &
         local_ot_env(1)%kpoint_density_stationarity_delta, &
         local_ot_env(1)%schur_density_stationarity_quality_ema, &
         local_ot_env(1)%schur_closure_response_quality_ema, fractional_weight, max_partial_fraction

   END FUNCTION qs_scf_loop_ot_kp_subspace_refresh_needed

! **************************************************************************************************
!> \brief request ADDED_MOS AUTO growth for a stalled metallic k-point OT tail
!> \param kpoints ...
!> \param scf_env ...
!> \param scf_control ...
!> \param nspin_ot ...
!> \return true if the existing AUTO grow/rebuild path should be used
! **************************************************************************************************
   FUNCTION qs_scf_loop_ot_kp_added_mos_auto_tail_grow(kpoints, scf_env, scf_control, nspin_ot) &
      RESULT(grow)

      TYPE(kpoint_type), POINTER                         :: kpoints
      TYPE(qs_scf_env_type), POINTER                     :: scf_env
      TYPE(scf_control_type), POINTER                    :: scf_control
      INTEGER, INTENT(IN)                                :: nspin_ot
      LOGICAL                                            :: grow

      INTEGER :: accepted_response_support_i, base_nmo, current_added, &
         density_stationarity_ready_i, edge_start, edge_width, ikpoint, imo, ispin, local_kpoint, &
         nmo, nonedge_probe_limit, trigger_step
      LOGICAL :: accepted_response_tail_support, active_tail, basis_limited, basis_probe_limited, &
         coherent_fractional_tail, edge_limited, expandable, fractional_density_enrichment, &
         fractional_tail_limited, integer_density_enrichment, nonedge_bootstrap_probe, &
         nonedge_residual_probe, nonedge_tail_supported, relaxed_nonedge_probe, residual_ready, &
         residual_spike, residual_tail_limited, strong_tail_limited
      REAL(KIND=dp) :: accepted_response_quality, accepted_response_residual_gap, basis_signal, &
         density_stationarity_delta, edge_fractional_weight, edge_grow_limit, edge_tail_occ_min, &
         fractional_weight, grow_limit, max_edge_fractional, max_fractional, maxocc, occ_tail, &
         residual_model_delta, response_quality, response_residual_gap, tail_occ_min, weight
      REAL(KIND=dp), DIMENSION(:), POINTER               :: occupation_numbers, wkp
      TYPE(cp_logger_type), POINTER                      :: logger
      TYPE(kpoint_env_type), POINTER                     :: kp
      TYPE(mp_para_env_type), POINTER                    :: para_env_inter_kp

      grow = .FALSE.
      IF (.NOT. ANY(scf_control%added_mos_auto)) RETURN
      IF (.NOT. scf_control%smear%do_smear) RETURN
      IF (scf_control%eps_scf <= 0.0_dp) RETURN
      grow_limit = MAX(ot_kp_added_mos_auto_tail_eps_factor*scf_control%eps_scf, &
                       ot_kp_added_mos_auto_tail_probe_factor*SQRT(scf_control%eps_scf))
      edge_grow_limit = MAX(grow_limit, ot_kp_added_mos_auto_edge_probe_factor*SQRT(scf_control%eps_scf))

      trigger_step = MIN(ot_kp_added_mos_auto_tail_min_steps, ot_kp_added_mos_auto_tail_probe_steps)
      IF (scf_env%iter_count < trigger_step) RETURN
      trigger_step = ot_kp_added_mos_auto_tail_min_steps

      NULLIFY (occupation_numbers, para_env_inter_kp, wkp)
      CALL get_kpoint_info(kpoints, wkp=wkp, para_env_inter_kp=para_env_inter_kp)
      residual_model_delta = scf_env%iter_delta
      IF (ASSOCIATED(scf_env%qs_ot_env)) &
         residual_model_delta = kpoint_ot_canonical_density_projector_delta(scf_env%qs_ot_env(1), scf_env%iter_delta)
      CALL para_env_inter_kp%max(residual_model_delta)
      density_stationarity_delta = 0.0_dp
      density_stationarity_ready_i = 0
      IF (ASSOCIATED(scf_env%qs_ot_env)) THEN
         DO ispin = 1, SIZE(scf_env%qs_ot_env)
            IF (.NOT. scf_env%qs_ot_env(ispin)%kpoint_density_stationarity_ready) CYCLE
            density_stationarity_ready_i = 1
            density_stationarity_delta = MAX( &
                                         density_stationarity_delta, &
                                         MAX(0.0_dp, scf_env%qs_ot_env(ispin)%kpoint_density_stationarity_delta))
         END DO
      END IF
      CALL para_env_inter_kp%max(density_stationarity_ready_i)
      CALL para_env_inter_kp%max(density_stationarity_delta)
      basis_signal = 0.0_dp
      accepted_response_quality = 0.0_dp
      accepted_response_residual_gap = 0.0_dp
      accepted_response_support_i = 0
      IF (ASSOCIATED(scf_env%qs_ot_env)) THEN
         DO ispin = 1, SIZE(scf_env%qs_ot_env)
            basis_signal = MAX(basis_signal, scf_env%qs_ot_env(ispin)%added_mos_auto_basis_signal)
            IF (scf_env%qs_ot_env(ispin)%schur_model_quality_samples >= &
                ot_kp_schur_calibration_min_samples) THEN
               response_quality = MAX(0.0_dp, scf_env%qs_ot_env(ispin)%schur_model_quality_ema)
               response_residual_gap = MAX(0.0_dp, &
                                           1.0_dp - scf_env%qs_ot_env(ispin)%schur_step_gauge_residual_quality_ema)
               accepted_response_quality = MAX(accepted_response_quality, response_quality)
               accepted_response_residual_gap = MAX(accepted_response_residual_gap, &
                                                    response_residual_gap)
               IF (response_quality >= ot_kp_schur_quality_min_ratio .AND. &
                   scf_env%qs_ot_env(ispin)%schur_step_gauge_residual_quality_ema <= &
                   ot_kp_schur_residual_tail_plateau_quality) accepted_response_support_i = 1
            END IF
         END DO
      END IF
      CALL para_env_inter_kp%max(basis_signal)
      CALL para_env_inter_kp%max(accepted_response_quality)
      CALL para_env_inter_kp%max(accepted_response_residual_gap)
      CALL para_env_inter_kp%max(accepted_response_support_i)
      accepted_response_tail_support = accepted_response_support_i > 0
      basis_limited = basis_signal >= ot_kp_added_mos_auto_basis_signal_min

      expandable = .FALSE.
      edge_fractional_weight = 0.0_dp
      fractional_weight = 0.0_dp
      max_edge_fractional = 0.0_dp
      max_fractional = 0.0_dp
      nonedge_bootstrap_probe = .FALSE.
      nonedge_residual_probe = .FALSE.
      DO local_kpoint = 1, SIZE(kpoints%kp_env)
         kp => kpoints%kp_env(local_kpoint)%kpoint_env
         ikpoint = kp%nkpoint
         DO ispin = 1, MIN(nspin_ot, SIZE(scf_control%added_mos_auto))
            IF (.NOT. scf_control%added_mos_auto(ispin)) CYCLE
            CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, nmo=nmo, &
                            occupation_numbers=occupation_numbers)
            IF (nmo < kp%mos(1, ispin)%nao) expandable = .TRUE.
            current_added = MAX(0, scf_control%added_mos(ispin))
            base_nmo = MAX(0, nmo - current_added)
            nonedge_probe_limit = MAX(8, (base_nmo + 3)/4)
            IF (current_added <= nonedge_probe_limit) nonedge_residual_probe = .TRUE.
            IF (current_added <= ot_kp_added_mos_auto_direct_veto_max_added) &
               nonedge_bootstrap_probe = .TRUE.
            IF (.NOT. ASSOCIATED(occupation_numbers)) CYCLE
            IF (ikpoint < 1 .OR. ikpoint > SIZE(wkp)) CYCLE
            weight = ABS(wkp(ikpoint))
            edge_width = MAX(1, MIN(nmo, MAX(2, scf_control%added_mos(ispin)/2)))
            edge_start = MAX(1, nmo - edge_width + 1)
            DO imo = 1, SIZE(occupation_numbers)
               occ_tail = MAX(0.0_dp, MIN(occupation_numbers(imo), maxocc - occupation_numbers(imo)))
               fractional_weight = fractional_weight + weight*occ_tail
               max_fractional = MAX(max_fractional, occ_tail)
               IF (imo >= edge_start) THEN
                  edge_fractional_weight = edge_fractional_weight + weight*occ_tail
                  max_edge_fractional = MAX(max_edge_fractional, occ_tail)
               END IF
            END DO
         END DO
      END DO
      CALL para_env_inter_kp%sum(edge_fractional_weight)
      CALL para_env_inter_kp%sum(fractional_weight)
      CALL para_env_inter_kp%max(max_edge_fractional)
      CALL para_env_inter_kp%max(max_fractional)

      tail_occ_min = 10.0_dp*MAX(scf_control%smear%eps_fermi_dirac, EPSILON(1.0_dp))
      edge_tail_occ_min = MAX(ot_kp_fermi_window_min_frac, tail_occ_min)
      active_tail = fractional_weight > ot_kp_fermi_window_min_frac .OR. max_fractional > tail_occ_min
      edge_limited = edge_fractional_weight > ot_kp_fermi_window_min_frac .OR. &
                     max_edge_fractional > edge_tail_occ_min
      integer_density_enrichment = density_stationarity_ready_i > 0 .AND. &
         qs_scf_kp_added_mos_integer_density_ready( &
         scf_env%iter_delta, density_stationarity_delta, scf_control%eps_scf, &
         grow_limit, edge_grow_limit, expandable, active_tail)
      IF (scf_env%iter_delta <= scf_control%eps_scf .AND. .NOT. integer_density_enrichment) RETURN
      coherent_fractional_tail = fractional_weight >= ot_kp_fermi_window_tail_fraction .AND. &
                                 max_fractional >= ot_kp_fermi_window_tail_fraction
      fractional_density_enrichment = density_stationarity_ready_i > 0 .AND. &
                                      qs_scf_kp_added_mos_fractional_density_ready( &
                                      MAX(scf_env%iter_delta, residual_model_delta), &
                                      density_stationarity_delta, scf_control%eps_scf, &
                                      edge_grow_limit, &
                                      edge_grow_limit, expandable, active_tail, coherent_fractional_tail, &
                                      edge_limited .OR. &
                                      basis_signal >= ot_kp_added_mos_auto_fractional_tail_basis_frac* &
                                      ot_kp_added_mos_auto_basis_signal_min, &
                                      edge_limited .OR. nonedge_residual_probe)
      basis_probe_limited = integer_density_enrichment .OR. fractional_density_enrichment .OR. &
                            (basis_signal >= 0.6_dp*ot_kp_added_mos_auto_basis_signal_min .AND. &
                             scf_env%iter_delta <= edge_grow_limit)
      relaxed_nonedge_probe = .NOT. nonedge_bootstrap_probe .AND. .NOT. edge_limited .AND. &
                              basis_signal >= ot_kp_added_mos_auto_fractional_tail_basis_frac* &
                              ot_kp_added_mos_auto_basis_signal_min .AND. &
                              qs_scf_kp_added_mos_fractional_tail_ready( &
                              MAX(scf_env%iter_delta, residual_model_delta), &
                              scf_control%eps_scf, edge_grow_limit, .FALSE., .FALSE.)
      nonedge_tail_supported = nonedge_bootstrap_probe .OR. accepted_response_tail_support .OR. &
                               relaxed_nonedge_probe .OR. &
                               basis_signal >= ot_kp_added_mos_auto_strong_tail_basis_frac* &
                               ot_kp_added_mos_auto_basis_signal_min
      fractional_tail_limited = nonedge_residual_probe .AND. &
                                nonedge_tail_supported .AND. &
                                max_fractional >= ot_kp_fermi_window_tail_fraction .AND. &
                                (max_fractional >= ot_kp_added_mos_auto_fractional_tail_peak_frac .OR. &
                                 coherent_fractional_tail) .AND. &
                                basis_signal >= ot_kp_added_mos_auto_fractional_tail_basis_frac* &
                                ot_kp_added_mos_auto_basis_signal_min
      IF (fractional_tail_limited) THEN
         fractional_tail_limited = qs_scf_kp_added_mos_fractional_tail_ready( &
                                   MAX(scf_env%iter_delta, residual_model_delta), scf_control%eps_scf, edge_grow_limit, &
                                   nonedge_bootstrap_probe, edge_limited)
      END IF
      residual_ready = scf_env%iter_delta <= grow_limit
      ! A residual-limited grow must see occupation at the virtual edge.  The
      ! non-edge probe is only a basis-signal bootstrap; otherwise ordinary
      ! metallic occupations below the Fermi edge can trigger late, unnecessary
      ! AUTO growth after the edge itself is already empty.
      residual_tail_limited = residual_ready .AND. edge_limited .AND. &
                              basis_signal >= ot_kp_added_mos_auto_strong_tail_basis_frac* &
                              ot_kp_added_mos_auto_basis_signal_min
      residual_spike = scf_env%iter_delta > &
                       ot_kp_added_mos_auto_residual_spike_factor* &
                       MAX(residual_model_delta, scf_control%eps_scf)
      strong_tail_limited = (max_edge_fractional >= ot_kp_added_mos_auto_strong_tail_frac .OR. &
                             (nonedge_residual_probe .AND. &
                              max_fractional >= ot_kp_added_mos_auto_strong_tail_frac)) .AND. &
                            basis_signal >= ot_kp_added_mos_auto_strong_tail_basis_frac* &
                            ot_kp_added_mos_auto_basis_signal_min .AND. &
                            scf_env%iter_delta <= edge_grow_limit
      IF (integer_density_enrichment .OR. &
          basis_signal >= 0.6_dp*ot_kp_added_mos_auto_basis_signal_min .OR. &
          strong_tail_limited .OR. fractional_tail_limited) THEN
         trigger_step = MIN(trigger_step, ot_kp_added_mos_auto_tail_probe_steps)
      END IF
      IF (fractional_density_enrichment .AND. .NOT. nonedge_bootstrap_probe) &
         trigger_step = MIN(trigger_step, ot_kp_added_mos_auto_fractional_density_min_steps)
      IF (scf_env%iter_count < trigger_step) RETURN

      logger => cp_get_default_logger()
      IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) THEN
         WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I6,12(1X,ES20.10E3),14(1X,L1))') &
            " OT k-point ADDED_MOS AUTO tail:", &
            scf_env%iter_count, scf_env%iter_delta, residual_model_delta, grow_limit, edge_grow_limit, basis_signal, &
            density_stationarity_delta, accepted_response_quality, accepted_response_residual_gap, fractional_weight, &
            edge_fractional_weight, max_fractional, max_edge_fractional, active_tail, edge_limited, &
            basis_probe_limited, basis_limited, integer_density_enrichment, fractional_density_enrichment, &
            fractional_tail_limited, residual_spike, nonedge_residual_probe, nonedge_bootstrap_probe, &
            accepted_response_tail_support, &
            relaxed_nonedge_probe, nonedge_tail_supported, expandable
      END IF

      IF (.NOT. expandable) RETURN
      IF (.NOT. qs_scf_kp_added_mos_basis_bootstrap_ready( &
          active_tail, basis_probe_limited, &
          edge_limited .OR. nonedge_residual_probe .OR. integer_density_enrichment .OR. &
          fractional_density_enrichment, &
          residual_spike)) RETURN
      IF (.NOT. residual_tail_limited .AND. .NOT. basis_limited .AND. .NOT. basis_probe_limited .AND. &
          .NOT. strong_tail_limited .AND. .NOT. fractional_tail_limited) THEN
         IF (.NOT. edge_limited) RETURN
         IF (scf_env%iter_delta > edge_grow_limit) RETURN
      END IF

      grow = .TRUE.

   END FUNCTION qs_scf_loop_ot_kp_added_mos_auto_tail_grow

! **************************************************************************************************
!> \brief collect the fixed-N trial occupations used by k-point OT
!> \param kpoints ...
!> \param local_ot_env ...
!> \param first_channel ...
!> \param nspin_ot ...
!> \param kp_range ...
!> \param wkp ...
!> \param para_env_inter_kp ...
!> \param smear ...
!> \param trial_eigenvalues ...
!> \param trial_occupation ...
!> \param trial_mu ...
!> \param trial_kTS ...
! **************************************************************************************************
   SUBROUTINE qs_scf_loop_collect_ot_kp_trial_smearing(kpoints, local_ot_env, first_channel, nspin_ot, &
                                                       kp_range, wkp, para_env_inter_kp, smear, &
                                                       trial_eigenvalues, trial_occupation, trial_mu, trial_kTS)

      TYPE(kpoint_type), POINTER                         :: kpoints
      TYPE(qs_ot_type), DIMENSION(:), POINTER            :: local_ot_env
      INTEGER, INTENT(IN)                                :: first_channel, nspin_ot
      INTEGER, DIMENSION(2), INTENT(IN)                  :: kp_range
      REAL(KIND=dp), DIMENSION(:), POINTER               :: wkp
      TYPE(mp_para_env_type), POINTER                    :: para_env_inter_kp
      TYPE(smear_type), INTENT(IN)                       :: smear
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :, :), &
         INTENT(OUT)                                     :: trial_eigenvalues, trial_occupation
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:), &
         INTENT(OUT)                                     :: trial_mu
      REAL(KIND=dp), INTENT(OUT)                         :: trial_kTS

      INTEGER                                            :: ikpoint, ispin, local_channel, &
                                                            local_kpoint, nkpoint, nmo
      REAL(KIND=dp), DIMENSION(:), POINTER               :: eigenvalues
      TYPE(kpoint_env_type), POINTER                     :: kp

      NULLIFY (eigenvalues)

      CALL get_kpoint_info(kpoints, nkp=nkpoint)
      kp => kpoints%kp_env(1)%kpoint_env
      CALL get_mo_set(kp%mos(1, 1), nmo=nmo)

      ALLOCATE (trial_eigenvalues(nmo, nkpoint, nspin_ot))
      ALLOCATE (trial_occupation(nmo, nkpoint, nspin_ot))
      ALLOCATE (trial_mu(nspin_ot))
      trial_eigenvalues(:, :, :) = 0.0_dp
      trial_occupation(:, :, :) = 0.0_dp
      trial_mu(:) = 0.0_dp

      DO local_kpoint = 1, SIZE(kpoints%kp_env)
         kp => kpoints%kp_env(local_kpoint)%kpoint_env
         ikpoint = kp%nkpoint
         CPASSERT(ikpoint >= kp_range(1) .AND. ikpoint <= kp_range(2))
         DO ispin = 1, nspin_ot
            local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
            CALL get_mo_set(kp%mos(1, ispin), eigenvalues=eigenvalues)
            IF (local_ot_env(local_channel)%settings%do_ener) THEN
               trial_eigenvalues(1:nmo, ikpoint, ispin) = local_ot_env(local_channel)%ener_x(1:nmo)
            ELSE
               trial_eigenvalues(1:nmo, ikpoint, ispin) = eigenvalues(1:nmo)
            END IF
         END DO
      END DO
      CALL para_env_inter_kp%sum(trial_eigenvalues)

      CALL qs_scf_loop_smear_ot_kp_trial_eigenvalues(kpoints, nspin_ot, wkp, smear, &
                                                     trial_eigenvalues, trial_occupation, trial_mu, trial_kTS)

   END SUBROUTINE qs_scf_loop_collect_ot_kp_trial_smearing

! **************************************************************************************************
!> \brief solve the fixed-N smearing problem for supplied k-point trial energies
!> \param kpoints ...
!> \param nspin_ot ...
!> \param wkp ...
!> \param smear ...
!> \param trial_eigenvalues ...
!> \param trial_occupation ...
!> \param trial_mu ...
!> \param trial_kTS ...
! **************************************************************************************************
   SUBROUTINE qs_scf_loop_smear_ot_kp_trial_eigenvalues(kpoints, nspin_ot, wkp, smear, &
                                                        trial_eigenvalues, trial_occupation, trial_mu, trial_kTS)

      TYPE(kpoint_type), POINTER                         :: kpoints
      INTEGER, INTENT(IN)                                :: nspin_ot
      REAL(KIND=dp), DIMENSION(:), POINTER               :: wkp
      TYPE(smear_type), INTENT(IN)                       :: smear
      REAL(KIND=dp), DIMENSION(:, :, :), INTENT(IN)      :: trial_eigenvalues
      REAL(KIND=dp), DIMENSION(:, :, :), INTENT(OUT)     :: trial_occupation
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: trial_mu
      REAL(KIND=dp), INTENT(OUT)                         :: trial_kTS

      INTEGER                                            :: method, ne_a, ne_b, nelectron
      REAL(KIND=dp)                                      :: kTS, kTS_total, mu, nel, nel_a_target, &
                                                            nel_b_target, sigma
      REAL(KIND=dp), DIMENSION(2)                        :: mus
      TYPE(kpoint_env_type), POINTER                     :: kp

      CPASSERT(SIZE(trial_eigenvalues, 2) == SIZE(wkp))
      CPASSERT(SIZE(trial_eigenvalues, 3) == nspin_ot)
      CPASSERT(SIZE(trial_occupation, 1) == SIZE(trial_eigenvalues, 1))
      CPASSERT(SIZE(trial_occupation, 2) == SIZE(trial_eigenvalues, 2))
      CPASSERT(SIZE(trial_occupation, 3) == nspin_ot)
      CPASSERT(SIZE(trial_mu) == nspin_ot)

      kp => kpoints%kp_env(1)%kpoint_env
      CALL get_mo_set(kp%mos(1, 1), nelectron=nelectron)
      ne_a = nelectron
      ne_b = 0
      IF (nspin_ot == 2) CALL get_mo_set(kp%mos(1, 2), nelectron=ne_b)
      nel_a_target = REAL(ne_a, KIND=dp)
      nel_b_target = REAL(ne_b, KIND=dp)
      IF (nspin_ot == 2 .AND. smear%fixed_mag_mom >= 0.0_dp) &
         CALL kpoint_fixed_spin_targets(REAL(ne_a + ne_b, KIND=dp), smear%fixed_mag_mom, &
                                        nel_a_target, nel_b_target)
      trial_occupation(:, :, :) = 0.0_dp
      trial_mu(:) = 0.0_dp
      mus(:) = 0.0_dp
      kTS_total = 0.0_dp

      IF (smear%do_smear) THEN
         SELECT CASE (smear%method)
         CASE (smear_fermi_dirac)
            sigma = smear%electronic_temperature
            method = smear_fermi_dirac
         CASE (smear_gaussian, smear_mp, smear_mv)
            sigma = smear%smearing_width
            method = smear%method
         CASE DEFAULT
            CPABORT("kpoints: Selected smearing not (yet) supported")
         END SELECT
      ELSE
         sigma = 0.0_dp
         method = smear_gaussian
      END IF

      IF (nspin_ot == 1) THEN
         nel = REAL(nelectron, KIND=dp)
         CALL Smearkp(trial_occupation(:, :, 1), mus(1), kTS, trial_eigenvalues(:, :, 1), nel, wkp, &
                      sigma, 2.0_dp, method, electron_tolerance=ot_kp_electron_tolerance)
         kTS_total = kTS
      ELSE IF (smear%fixed_mag_mom >= 0.0_dp .OR. .NOT. smear%do_smear) THEN
         nel = nel_a_target
         CALL Smearkp(trial_occupation(:, :, 1), mus(1), kTS, trial_eigenvalues(:, :, 1), nel, wkp, &
                      sigma, 1.0_dp, method, electron_tolerance=ot_kp_electron_tolerance)
         kTS_total = kTS_total + kTS
         nel = nel_b_target
         CALL Smearkp(trial_occupation(:, :, 2), mus(2), kTS, trial_eigenvalues(:, :, 2), nel, wkp, &
                      sigma, 1.0_dp, method, electron_tolerance=ot_kp_electron_tolerance)
         kTS_total = kTS_total + kTS
      ELSE
         nel = REAL(ne_a, KIND=dp) + REAL(ne_b, KIND=dp)
         CALL Smearkp2(trial_occupation(:, :, :), mu, kTS, trial_eigenvalues(:, :, :), nel, wkp, &
                       sigma, method, electron_tolerance=ot_kp_electron_tolerance)
         mus(1:2) = mu
         kTS_total = kTS
      END IF
      trial_mu(:) = mus(1:nspin_ot)
      trial_kTS = kTS_total

   END SUBROUTINE qs_scf_loop_smear_ot_kp_trial_eigenvalues

! **************************************************************************************************
!> \brief keep trial k-point OT auxiliary energies inside a finite-temperature frontier window
!> \param kpoints ...
!> \param local_ot_env ...
!> \param first_channel ...
!> \param nspin_ot ...
!> \param kp_range ...
!> \param wkp ...
!> \param para_env_inter_kp ...
!> \param smear ...
!> \param trial_eigenvalues ...
!> \param trial_occupation ...
!> \param trial_mu ...
!> \param eps_scf ...
!> \param guarded ...
! **************************************************************************************************
   SUBROUTINE qs_scf_loop_guard_ot_kp_trial_fermi_window(kpoints, local_ot_env, first_channel, &
                                                         nspin_ot, kp_range, wkp, para_env_inter_kp, &
                                                         smear, trial_eigenvalues, trial_occupation, &
                                                         trial_mu, eps_scf, guarded)

      TYPE(kpoint_type), POINTER                         :: kpoints
      TYPE(qs_ot_type), DIMENSION(:), POINTER            :: local_ot_env
      INTEGER, INTENT(IN)                                :: first_channel, nspin_ot
      INTEGER, DIMENSION(2), INTENT(IN)                  :: kp_range
      REAL(KIND=dp), DIMENSION(:), POINTER               :: wkp
      TYPE(mp_para_env_type), POINTER                    :: para_env_inter_kp
      TYPE(smear_type), INTENT(IN)                       :: smear
      REAL(KIND=dp), DIMENSION(:, :, :), INTENT(INOUT)   :: trial_eigenvalues
      REAL(KIND=dp), DIMENSION(:, :, :), INTENT(IN)      :: trial_occupation
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: trial_mu
      REAL(KIND=dp), INTENT(IN)                          :: eps_scf
      LOGICAL, INTENT(OUT)                               :: guarded

      REAL(KIND=dp), PARAMETER                           :: restore_factor = 0.8_dp

      INTEGER :: adjusted, calibration_samples, current_nmo, group, ikpoint, imo, ispin, &
         local_channel, local_kpoint, ncopy, ngroups, nkpoint, trial_nmo
      INTEGER, ALLOCATABLE, DIMENSION(:)                 :: frontier_armed
      LOGICAL                                            :: fractional_support_lost, guard_group, &
                                                            lower_frontier, upper_frontier
      REAL(KIND=dp)                                      :: anchor_window, distance_tol, eps, &
                                                            frontier_dist, maxocc, occ_tail, &
                                                            residual_delta, sigma
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:) :: canonical_max_partial, current_max_partial, &
         frac_weight, lower_dist, max_partial, maxocc_group, min_abs_eps_mu, release_current, &
         release_trial, upper_dist
      REAL(KIND=dp), DIMENSION(:), POINTER               :: occupation_numbers
      TYPE(cp_logger_type), POINTER                      :: logger
      TYPE(kpoint_env_type), POINTER                     :: kp

      guarded = .FALSE.
      IF (.NOT. local_ot_env(1)%settings%do_ener) RETURN
      IF (.NOT. local_ot_env(1)%settings%occupation_preconditioner) RETURN
      IF (.NOT. smear%do_smear .OR. .NOT. kpoint_ot_monotone_smearing(smear%method)) RETURN
      ! Protect a pre-existing thermal frontier only during initial response
      ! calibration.  Later occupation changes must follow the physical Mermin
      ! minimization, including a legitimately gapped coarse k mesh.
      calibration_samples = local_ot_env(1)%mermin_ls_accepted_quality_samples
      CALL para_env_inter_kp%min(calibration_samples)
      IF (smear%method == smear_gaussian .AND. calibration_samples <= 0) RETURN
      residual_delta = qs_scf_kp_fermi_guard_control_delta( &
                       local_ot_env(1)%delta, local_ot_env(1)%kpoint_raw_delta)
      DO local_channel = 2, SIZE(local_ot_env)
         residual_delta = MAX(residual_delta, qs_scf_kp_fermi_guard_control_delta( &
                              local_ot_env(local_channel)%delta, &
                              local_ot_env(local_channel)%kpoint_raw_delta))
      END DO
      CALL para_env_inter_kp%max(residual_delta)
      IF (qs_scf_kp_fermi_guard_release_ready(calibration_samples, residual_delta, eps_scf)) RETURN

      sigma = kpoint_ot_smearing_width(smear)
      IF (sigma <= 1.0E-14_dp) RETURN
      anchor_window = kpoint_ot_fermi_window_anchor(sigma, smear%method)

      trial_nmo = SIZE(trial_eigenvalues, 1)
      nkpoint = SIZE(trial_eigenvalues, 2)
      ! A shared chemical potential couples the fixed-N constraint, but each
      ! spin channel still needs finite local support for inter-spin charge
      ! transfer.  Do not let one fractional spin hide collapse of the other.
      ngroups = nspin_ot
      ALLOCATE (frontier_armed(ngroups), canonical_max_partial(ngroups), &
                current_max_partial(ngroups), frac_weight(ngroups), lower_dist(ngroups), &
                max_partial(ngroups), maxocc_group(ngroups), min_abs_eps_mu(ngroups), &
                release_current(ngroups), release_trial(ngroups), upper_dist(ngroups))
      frontier_armed(:) = 0
      canonical_max_partial(:) = 0.0_dp
      current_max_partial(:) = 0.0_dp
      frac_weight(:) = 0.0_dp
      lower_dist(:) = HUGE(1.0_dp)
      max_partial(:) = 0.0_dp
      maxocc_group(:) = 0.0_dp
      min_abs_eps_mu(:) = HUGE(1.0_dp)
      release_current(:) = 0.0_dp
      release_trial(:) = 0.0_dp
      upper_dist(:) = HUGE(1.0_dp)

      ! Preserve an existing finite-temperature frontier. An initially integer
      ! auxiliary state may also be armed when the exact canonical audit
      ! independently resolves fractional support; a genuinely gapped
      ! canonical state remains untouched.
      DO local_kpoint = 1, SIZE(kpoints%kp_env)
         kp => kpoints%kp_env(local_kpoint)%kpoint_env
         DO ispin = 1, nspin_ot
            group = MERGE(ispin, 1, ngroups == nspin_ot)
            local_channel = qs_ot_channel_index(ispin, kp%nkpoint, nspin_ot) - first_channel + 1
            IF (local_ot_env(local_channel)%ener_x_fermi_frontier_armed) &
               frontier_armed(group) = 1
            CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, nmo=current_nmo, &
                            occupation_numbers=occupation_numbers)
            maxocc_group(group) = MAX(maxocc_group(group), maxocc)
            IF (.NOT. ASSOCIATED(occupation_numbers)) CYCLE
            DO imo = 1, current_nmo
               occ_tail = MAX(0.0_dp, MIN(occupation_numbers(imo), maxocc - occupation_numbers(imo)))
               current_max_partial(group) = MAX(current_max_partial(group), occ_tail)
            END DO
            IF (local_ot_env(local_channel)%kpoint_canonical_occupation_ready .AND. &
                ALLOCATED(local_ot_env(local_channel)%kpoint_canonical_occupation)) THEN
               DO imo = 1, MIN(current_nmo, &
                               SIZE(local_ot_env(local_channel)%kpoint_canonical_occupation))
                  occ_tail = MAX(0.0_dp, &
                                 MIN(local_ot_env(local_channel)%kpoint_canonical_occupation(imo), &
                                     maxocc - local_ot_env(local_channel)%kpoint_canonical_occupation(imo)))
                  canonical_max_partial(group) = MAX(canonical_max_partial(group), occ_tail)
               END DO
            END IF
         END DO
      END DO
      DO group = 1, ngroups
         CALL para_env_inter_kp%max(canonical_max_partial(group))
         CALL para_env_inter_kp%max(current_max_partial(group))
         CALL para_env_inter_kp%max(maxocc_group(group))
         CALL para_env_inter_kp%max(frontier_armed(group))
         IF (qs_scf_kp_fermi_frontier_armed(current_max_partial(group), &
                                            canonical_max_partial(group), &
                                            maxocc_group(group), frontier_armed(group) > 0, &
                                            smear%method /= smear_gaussian .OR. &
                                            calibration_samples > 0)) &
            frontier_armed(group) = 1
      END DO
      DO local_channel = 1, SIZE(local_ot_env)
         group = MAX(1, MIN(ngroups, local_ot_env(local_channel)%spin_index))
         local_ot_env(local_channel)%ener_x_fermi_frontier_armed = frontier_armed(group) > 0
      END DO

      DO ikpoint = 1, nkpoint
         DO ispin = 1, nspin_ot
            group = MERGE(ispin, 1, ngroups == nspin_ot)
            maxocc = maxocc_group(group)
            DO imo = 1, trial_nmo
               occ_tail = MAX(0.0_dp, MIN(trial_occupation(imo, ikpoint, ispin), &
                                          maxocc - trial_occupation(imo, ikpoint, ispin)))
               frac_weight(group) = frac_weight(group) + wkp(ikpoint)*occ_tail
               max_partial(group) = MAX(max_partial(group), occ_tail)
               min_abs_eps_mu(group) = MIN(min_abs_eps_mu(group), &
                                           ABS(trial_eigenvalues(imo, ikpoint, ispin) - trial_mu(ispin)))
               IF (trial_eigenvalues(imo, ikpoint, ispin) <= trial_mu(ispin)) &
                  lower_dist(group) = MIN(lower_dist(group), &
                                          trial_mu(ispin) - trial_eigenvalues(imo, ikpoint, ispin))
               IF (trial_eigenvalues(imo, ikpoint, ispin) >= trial_mu(ispin)) &
                  upper_dist(group) = MIN(upper_dist(group), &
                                          trial_eigenvalues(imo, ikpoint, ispin) - trial_mu(ispin))
            END DO
         END DO
      END DO

      DO group = 1, ngroups
         release_current(group) = kpoint_ot_fermi_window_release_weight(current_max_partial(group), &
                                                                        maxocc_group(group))
         release_trial(group) = kpoint_ot_fermi_window_release_weight(max_partial(group), &
                                                                      maxocc_group(group))
      END DO

      adjusted = 0
      ! trial_eigenvalues is replicated after collection.  Apply the guard to
      ! the complete array on every k-point rank so the subsequent common-mu
      ! smearing sees exactly the same spectrum independently of ownership.
      DO ikpoint = 1, nkpoint
         DO ispin = 1, nspin_ot
            group = MERGE(ispin, 1, ngroups == nspin_ot)
            fractional_support_lost = qs_scf_kp_fermi_guard_transition( &
                                      current_max_partial(group), max_partial(group), &
                                      maxocc_group(group), frontier_armed(group) > 0)
            guard_group = lower_dist(group) < HUGE(1.0_dp) .AND. &
                          upper_dist(group) < HUGE(1.0_dp) .AND. &
                          min_abs_eps_mu(group) > anchor_window .AND. &
                          fractional_support_lost
            IF (.NOT. guard_group) CYCLE

            distance_tol = MAX(1.0E-10_dp, 1.0E-8_dp*MAX(lower_dist(group), upper_dist(group)))
            DO imo = 1, trial_nmo
               lower_frontier = trial_eigenvalues(imo, ikpoint, ispin) <= trial_mu(ispin) .AND. &
                                ABS(trial_mu(ispin) - trial_eigenvalues(imo, ikpoint, ispin) - &
                                    lower_dist(group)) <= distance_tol
               upper_frontier = trial_eigenvalues(imo, ikpoint, ispin) >= trial_mu(ispin) .AND. &
                                ABS(trial_eigenvalues(imo, ikpoint, ispin) - trial_mu(ispin) - &
                                    upper_dist(group)) <= distance_tol
               IF (lower_frontier .AND. lower_dist(group) > anchor_window) THEN
                  frontier_dist = restore_factor*anchor_window
                  eps = trial_mu(ispin) - frontier_dist
               ELSEIF (upper_frontier .AND. upper_dist(group) > anchor_window) THEN
                  frontier_dist = restore_factor*anchor_window
                  eps = trial_mu(ispin) + frontier_dist
               ELSE
                  CYCLE
               END IF
               trial_eigenvalues(imo, ikpoint, ispin) = eps
               adjusted = adjusted + 1
            END DO
         END DO
      END DO

      guarded = adjusted > 0
      IF (guarded) THEN
         DO local_kpoint = 1, SIZE(kpoints%kp_env)
            kp => kpoints%kp_env(local_kpoint)%kpoint_env
            ikpoint = kp%nkpoint
            CPASSERT(ikpoint >= kp_range(1) .AND. ikpoint <= kp_range(2))
            DO ispin = 1, nspin_ot
               local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
               ncopy = MIN(trial_nmo, SIZE(local_ot_env(local_channel)%ener_x))
               local_ot_env(local_channel)%ener_x(1:ncopy) = &
                  trial_eigenvalues(1:ncopy, ikpoint, ispin)
            END DO
         END DO
      END IF

      logger => cp_get_default_logger()
      IF (guarded .AND. logger%iter_info%print_level >= debug_print_level .AND. &
          logger%para_env%is_source()) THEN
         WRITE (cp_logger_get_default_unit_nr(logger), '(A,7(1X,ES16.8),1X,I5)') &
            " OT k-point trial frontier-window guard sigma anchor frac min_abs current trial release adjusted:", &
            sigma, anchor_window, MINVAL(frac_weight), MINVAL(min_abs_eps_mu), &
            MINVAL(release_current), MINVAL(release_trial), MINVAL(release_trial), adjusted
      END IF

      DEALLOCATE (frontier_armed, canonical_max_partial, current_max_partial, frac_weight, &
                  lower_dist, max_partial, maxocc_group, &
                  min_abs_eps_mu, release_current, release_trial, upper_dist)

   END SUBROUTINE qs_scf_loop_guard_ot_kp_trial_fermi_window

! **************************************************************************************************
!> \brief whether k-point OT should eliminate auxiliary energies by exact fixed-N Mermin projection
!> \param qs_ot_env ...
!> \param smear ...
!> \return ...
! **************************************************************************************************
   FUNCTION kpoint_ot_project_energy_subproblem(qs_ot_env, smear) RESULT(do_projection)
      TYPE(qs_ot_type), INTENT(IN)                       :: qs_ot_env
      TYPE(smear_type), INTENT(IN)                       :: smear
      LOGICAL                                            :: do_projection

      do_projection = qs_ot_env%settings%do_ener .AND. &
                      qs_ot_env%settings%do_rotation .AND. &
                      smear%do_smear .AND. kpoint_ot_monotone_smearing(smear%method)

   END FUNCTION kpoint_ot_project_energy_subproblem

! **************************************************************************************************
!> \brief whether a smearing method has a strictly non-negative occupation response
!> \param method smearing method selector
!> \return true for the monotone methods supported by metallic OT
! **************************************************************************************************
   PURE FUNCTION kpoint_ot_monotone_smearing(method) RESULT(monotone)
      INTEGER, INTENT(IN)                                :: method
      LOGICAL                                            :: monotone

      monotone = method == smear_fermi_dirac .OR. method == smear_gaussian

   END FUNCTION kpoint_ot_monotone_smearing

! **************************************************************************************************
!> \brief active width for a configured smearing method
!> \param smear smearing settings
!> \return smearing width in Hartree
! **************************************************************************************************
   PURE FUNCTION kpoint_ot_smearing_width(smear) RESULT(sigma)
      TYPE(smear_type), INTENT(IN)                       :: smear
      REAL(KIND=dp)                                      :: sigma

      SELECT CASE (smear%method)
      CASE (smear_fermi_dirac)
         sigma = smear%electronic_temperature
      CASE (smear_gaussian, smear_mp, smear_mv)
         sigma = smear%smearing_width
      CASE DEFAULT
         sigma = 0.0_dp
      END SELECT

   END FUNCTION kpoint_ot_smearing_width

! **************************************************************************************************
!> \brief maximum fixed-mu occupation response for a monotone smearing method
!> \param sigma smearing width
!> \param maxocc maximum occupation
!> \param method smearing method selector
!> \return peak value of -df/de
! **************************************************************************************************
   PURE FUNCTION kpoint_ot_smearing_peak_response(sigma, maxocc, method) RESULT(peak)
      REAL(KIND=dp), INTENT(IN)                          :: sigma, maxocc
      INTEGER, INTENT(IN)                                :: method
      REAL(KIND=dp)                                      :: peak

      peak = 0.0_dp
      IF (sigma <= 1.0E-14_dp .OR. maxocc <= EPSILON(maxocc)) RETURN
      SELECT CASE (method)
      CASE (smear_fermi_dirac)
         peak = maxocc/(4.0_dp*sigma)
      CASE (smear_gaussian)
         peak = maxocc/(sigma*rootpi)
      END SELECT

   END FUNCTION kpoint_ot_smearing_peak_response

! **************************************************************************************************
!> \brief frontier-window guard anchor for the minimum resolved occupation tail
!> \param sigma ...
!> \param method optional smearing method, defaults to Fermi-Dirac
!> \return ...
! **************************************************************************************************
   PURE FUNCTION kpoint_ot_fermi_window_anchor(sigma, method) RESULT(anchor)
      REAL(KIND=dp), INTENT(IN)                          :: sigma
      INTEGER, INTENT(IN), OPTIONAL                      :: method
      REAL(KIND=dp)                                      :: anchor

      INTEGER                                            :: iter, method_active
      REAL(KIND=dp)                                      :: lower, mid, min_fraction, &
                                                            target_fraction, upper

      min_fraction = MIN(0.5_dp - EPSILON(1.0_dp), &
                         MAX(EPSILON(1.0_dp), ot_kp_fermi_window_min_frac))
      method_active = smear_fermi_dirac
      IF (PRESENT(method)) method_active = method
      SELECT CASE (method_active)
      CASE (smear_fermi_dirac)
         anchor = sigma*LOG((1.0_dp - min_fraction)/min_fraction)
      CASE (smear_gaussian)
         lower = 0.0_dp
         upper = 8.0_dp
         target_fraction = 2.0_dp*min_fraction
         DO iter = 1, 80
            mid = 0.5_dp*(lower + upper)
            IF (ERFC(mid) > target_fraction) THEN
               lower = mid
            ELSE
               upper = mid
            END IF
         END DO
         anchor = sigma*0.5_dp*(lower + upper)
      CASE DEFAULT
         anchor = 0.0_dp
      END SELECT

   END FUNCTION kpoint_ot_fermi_window_anchor

! **************************************************************************************************
!> \brief smooth release of the artificial frontier support as a physical metallic tail develops
!> \param max_partial ...
!> \param maxocc ...
!> \return ...
! **************************************************************************************************
   FUNCTION kpoint_ot_fermi_window_release_weight(max_partial, maxocc) RESULT(weight)
      REAL(KIND=dp), INTENT(IN)                          :: max_partial, maxocc
      REAL(KIND=dp)                                      :: weight

      REAL(KIND=dp)                                      :: support, TARGET

      TARGET = MAX(maxocc*ot_kp_fermi_window_min_frac, EPSILON(1.0_dp))
      support = MAX(0.0_dp, max_partial)/TARGET
      weight = (support - ot_kp_fermi_window_release_start)/ &
               (ot_kp_fermi_window_release_end - ot_kp_fermi_window_release_start)
      weight = MAX(0.0_dp, MIN(1.0_dp, weight))
      weight = weight*weight*(3.0_dp - 2.0_dp*weight)

   END FUNCTION kpoint_ot_fermi_window_release_weight

! **************************************************************************************************
!> \brief whether measured or canonical fractional support arms the frontier guard
!> \param current_max_partial largest fractional support in the current auxiliary state
!> \param canonical_max_partial largest fractional support in the canonical physical state
!> \param maxocc maximum orbital occupation
!> \param previously_armed optional persistent frontier state
!> \param current_mature optional evidence that the current state has passed an OT step
!> \return true when physical fractional support has been established
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_fermi_frontier_armed(current_max_partial, canonical_max_partial, &
                                                maxocc, previously_armed, current_mature) RESULT(armed)
      REAL(KIND=dp), INTENT(IN)                          :: current_max_partial, &
                                                            canonical_max_partial, maxocc
      LOGICAL, INTENT(IN), OPTIONAL                      :: previously_armed, current_mature
      LOGICAL                                            :: armed

      LOGICAL                                            :: use_current
      REAL(KIND=dp)                                      :: support_threshold

      armed = .FALSE.
      IF (maxocc <= EPSILON(1.0_dp)) RETURN
      IF (PRESENT(previously_armed)) armed = previously_armed
      use_current = .TRUE.
      IF (PRESENT(current_mature)) use_current = current_mature
      support_threshold = maxocc*ot_kp_fermi_window_min_frac
      armed = armed .OR. (use_current .AND. current_max_partial >= support_threshold) .OR. &
              canonical_max_partial >= support_threshold

   END FUNCTION qs_scf_kp_fermi_frontier_armed

! **************************************************************************************************
!> \brief whether a trial loses an already established finite-temperature occupation frontier
!> \param current_max_partial largest min(f,maxocc-f) in the accepted state
!> \param trial_max_partial largest min(f,maxocc-f) in the trial state
!> \param maxocc maximum orbital occupation
!> \param frontier_armed whether this spin previously resolved a physical thermal frontier
!> \return true only for loss of physical fractional support
! **************************************************************************************************
   FUNCTION qs_scf_kp_fermi_guard_transition(current_max_partial, trial_max_partial, maxocc, &
                                             frontier_armed) &
      RESULT(guard)
      REAL(KIND=dp), INTENT(IN)                          :: current_max_partial, trial_max_partial, &
                                                            maxocc
      LOGICAL, INTENT(IN), OPTIONAL                      :: frontier_armed
      LOGICAL                                            :: guard

      LOGICAL                                            :: armed
      REAL(KIND=dp)                                      :: current_release, support_threshold, &
                                                            trial_release

      guard = .FALSE.
      IF (maxocc <= EPSILON(1.0_dp)) RETURN
      armed = .FALSE.
      IF (PRESENT(frontier_armed)) armed = frontier_armed
      support_threshold = maxocc*ot_kp_fermi_window_min_frac
      IF (armed .AND. trial_max_partial < support_threshold) THEN
         guard = .TRUE.
         RETURN
      END IF
      IF (current_max_partial < support_threshold) RETURN

      current_release = kpoint_ot_fermi_window_release_weight(current_max_partial, maxocc)
      trial_release = kpoint_ot_fermi_window_release_weight(trial_max_partial, maxocc)
      guard = trial_release + 10.0_dp*EPSILON(1.0_dp) < current_release

   END FUNCTION qs_scf_kp_fermi_guard_transition

! **************************************************************************************************
!> \brief conservative residual controlling release of the metallic Fermi-window guard
!> \param projected_delta minimizer residual after physical/projected control
!> \param raw_delta unprojected coupled OT residual, or a negative unavailable marker
!> \return residual that must be converged before the guard can be released
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_fermi_guard_control_delta(projected_delta, raw_delta) RESULT(delta)
      REAL(KIND=dp), INTENT(IN)                          :: projected_delta, raw_delta
      REAL(KIND=dp)                                      :: delta

      delta = MAX(0.0_dp, projected_delta, raw_delta)

   END FUNCTION qs_scf_kp_fermi_guard_control_delta

! **************************************************************************************************
!> \brief whether accepted response history and SCF residual make frontier release physically safe
!> \param calibration_samples accepted Mermin model-quality samples
!> \param residual_delta current physical OT residual
!> \param eps_scf requested SCF convergence threshold
!> \return true only after calibration and entry into the converged residual basin
! **************************************************************************************************
   FUNCTION qs_scf_kp_fermi_guard_release_ready(calibration_samples, residual_delta, eps_scf) &
      RESULT(release_ready)
      INTEGER, INTENT(IN)                                :: calibration_samples
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta, eps_scf
      LOGICAL                                            :: release_ready

      REAL(KIND=dp)                                      :: residual_limit

      residual_limit = MAX(10.0_dp*MAX(eps_scf, 0.0_dp), SQRT(MAX(eps_scf, 0.0_dp)))
      release_ready = calibration_samples >= ot_kp_schur_calibration_min_samples .AND. &
                      residual_delta <= residual_limit

   END FUNCTION qs_scf_kp_fermi_guard_release_ready

! **************************************************************************************************
!> \brief residual-gated canonical projector blend weight for k-point OT
!> \param delta ...
!> \param max_weight ...
!> \return ...
! **************************************************************************************************
   FUNCTION kpoint_ot_canonical_projector_weight(delta, max_weight) RESULT(projector_weight)
      REAL(KIND=dp), INTENT(IN)                          :: delta, max_weight
      REAL(KIND=dp)                                      :: projector_weight

      REAL(KIND=dp)                                      :: delta_scale

      projector_weight = 0.0_dp
      IF (delta > 0.0_dp .AND. max_weight > 0.0_dp) THEN
         delta_scale = ot_kp_canonical_projector_delta/MAX(delta, ot_kp_canonical_projector_delta)
         projector_weight = max_weight*delta_scale**2
      END IF

   END FUNCTION kpoint_ot_canonical_projector_weight

! **************************************************************************************************
!> \brief fixed-point consistent canonical density blend weight for k-point OT
!> \param delta ...
!> \param max_weight ...
!> \return ...
! **************************************************************************************************
   FUNCTION kpoint_ot_canonical_density_projector_weight(delta, max_weight) RESULT(projector_weight)
      REAL(KIND=dp), INTENT(IN)                          :: delta
      REAL(KIND=dp), INTENT(IN), OPTIONAL                :: max_weight
      REAL(KIND=dp)                                      :: projector_weight

      REAL(KIND=dp)                                      :: density_max_weight, tail_scale

      density_max_weight = ot_kp_canonical_density_max_weight
      IF (PRESENT(max_weight)) density_max_weight = MAX(0.0_dp, max_weight)
      projector_weight = kpoint_ot_canonical_projector_weight(delta, density_max_weight)
      IF (projector_weight <= 0.0_dp) RETURN

      IF (delta < ot_kp_schur_projector_response_full_delta) THEN
         ! Keep the canonical-density projector active through the residual tail.
         ! Quadratic damping makes the projector itself the limiting fixed-point
         ! error just above tight SCF thresholds.
         tail_scale = MAX(0.0_dp, delta/ot_kp_schur_projector_response_full_delta)
         projector_weight = projector_weight*tail_scale**2
      END IF

   END FUNCTION kpoint_ot_canonical_density_projector_weight

! **************************************************************************************************
!> \brief line-search consistent residual for the k-point canonical density projector
!> \param qs_ot_env ...
!> \param delta ...
!> \return ...
! **************************************************************************************************
   FUNCTION kpoint_ot_canonical_density_projector_delta(qs_ot_env, delta) RESULT(model_delta)
      TYPE(qs_ot_type), INTENT(IN)                       :: qs_ot_env
      REAL(KIND=dp), INTENT(IN)                          :: delta
      REAL(KIND=dp)                                      :: model_delta

      model_delta = MAX(0.0_dp, delta)
      ! Cap only true follow-up probes of the same line search.  The first
      ! point of a new search direction must see a fresh residual; otherwise
      ! CG spikes keep the canonical density projector on a stale smaller delta.
      IF (qs_ot_env%line_search_count > 1 .AND. qs_ot_env%schur_model_pending .AND. &
          qs_ot_env%schur_model_delta > 0.0_dp) THEN
         model_delta = MIN(model_delta, qs_ot_env%schur_model_delta)
      END IF

   END FUNCTION kpoint_ot_canonical_density_projector_delta

! **************************************************************************************************
!> \brief residual-like control variable for the k-point canonical density projector
!> \param physical_delta accepted fixed-N residual
!> \param raw_delta raw preconditioned residual
!> \param trusted_energy_step largest trusted auxiliary-energy step
!> \return projector control residual
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_density_control_delta(physical_delta, raw_delta, trusted_energy_step) &
      RESULT(control_delta)
      REAL(KIND=dp), INTENT(IN)                          :: physical_delta, raw_delta, &
                                                            trusted_energy_step
      REAL(KIND=dp)                                      :: control_delta

      REAL(KIND=dp)                                      :: raw_control_delta

      control_delta = MAX(0.0_dp, physical_delta)
      raw_control_delta = MAX(0.0_dp, raw_delta)
      IF (raw_control_delta <= 0.0_dp) RETURN

      IF (control_delta > 0.0_dp) &
         raw_control_delta = MIN(raw_control_delta, &
                                 ot_kp_canonical_density_control_raw_max_ratio*control_delta)
      ! Once both the accepted residual and the auxiliary-energy motion are in
      ! the tight tail, keep the density map on that accepted branch.  Letting
      ! a preconditioned raw spike restore the full projector creates a
      ! non-variational two-point cycle between otherwise equivalent searches.
      IF (control_delta <= ot_kp_schur_projector_response_full_delta .AND. &
          trusted_energy_step <= ot_kp_schur_projector_response_full_delta) &
         raw_control_delta = MIN(raw_control_delta, control_delta)
      control_delta = MAX(control_delta, raw_control_delta)

   END FUNCTION qs_scf_kp_density_control_delta

! **************************************************************************************************
!> \brief residual-like control variable for the k-point canonical density projector
!> \param qs_ot_env ...
!> \param delta ...
!> \return ...
! **************************************************************************************************
   FUNCTION kpoint_ot_canonical_density_projector_control_delta(qs_ot_env, delta) RESULT(model_delta)
      TYPE(qs_ot_type), INTENT(IN)                       :: qs_ot_env
      REAL(KIND=dp), INTENT(IN)                          :: delta
      REAL(KIND=dp)                                      :: model_delta

      REAL(KIND=dp)                                      :: raw_control_delta

      model_delta = qs_scf_kp_density_control_delta(delta, qs_ot_env%kpoint_raw_delta, &
                                                    qs_ot_env%ener_x_trusted_step_max)
      raw_control_delta = MIN(MAX(0.0_dp, qs_ot_env%kpoint_raw_delta), model_delta)
      IF (qs_ot_env%line_search_count > 1 .AND. qs_ot_env%schur_model_pending .AND. &
          qs_ot_env%schur_model_control_delta > 0.0_dp) THEN
         model_delta = MIN(model_delta, MAX(qs_ot_env%schur_model_control_delta, &
                                            raw_control_delta))
      END IF

   END FUNCTION kpoint_ot_canonical_density_projector_control_delta

! **************************************************************************************************
!> \brief occupation-window projector weight for one rotation pair
!> \param projector_weight ...
!> \param curv_i ...
!> \param curv_j ...
!> \param curv_max ...
!> \return ...
! **************************************************************************************************
   FUNCTION kpoint_ot_pair_projector_weight(projector_weight, curv_i, curv_j, curv_max) RESULT(pair_weight)
      REAL(KIND=dp), INTENT(IN)                          :: projector_weight, curv_i, curv_j, &
                                                            curv_max
      REAL(KIND=dp)                                      :: pair_weight

      REAL(KIND=dp)                                      :: active_fraction

      pair_weight = 0.0_dp
      IF (projector_weight <= 0.0_dp) RETURN
      IF (curv_max <= EPSILON(curv_max)) RETURN

      active_fraction = kpoint_ot_shared_occ_slope(curv_i, curv_j)/(2.0_dp*curv_max)
      active_fraction = MIN(1.0_dp, MAX(0.0_dp, active_fraction))
      pair_weight = projector_weight*active_fraction

   END FUNCTION kpoint_ot_pair_projector_weight

! **************************************************************************************************
!> \brief physical density-norm weight for inactive rotation residuals
!> \param occ_gap occupation-number difference scaled to [0, 1]
!> \return squared occupation-gap weight
! **************************************************************************************************
   FUNCTION kpoint_ot_residual_occ_gap_weight(occ_gap) RESULT(gap_weight)
      REAL(KIND=dp), INTENT(IN)                          :: occ_gap
      REAL(KIND=dp)                                      :: gap_weight

      gap_weight = MIN(1.0_dp, MAX(0.0_dp, occ_gap))**2

   END FUNCTION kpoint_ot_residual_occ_gap_weight

! **************************************************************************************************
!> \brief history-qualified physical projector weight for one rotation variable
!> \param projector_weight ...
!> \param active_weight ...
!> \param occ_gap_weight ...
!> \param density_weight ...
!> \param density_response_weight optional fixed-N density-response character
!> \return ...
! **************************************************************************************************
   FUNCTION kpoint_ot_physical_pair_projector_weight(projector_weight, active_weight, occ_gap_weight, &
                                                     density_weight, density_response_weight) RESULT(pair_weight)
      REAL(KIND=dp), INTENT(IN)                          :: projector_weight, active_weight, &
                                                            occ_gap_weight, density_weight
      REAL(KIND=dp), INTENT(IN), OPTIONAL                :: density_response_weight
      REAL(KIND=dp)                                      :: pair_weight

      REAL(KIND=dp)                                      :: gap_fraction, qualified_response_weight, &
                                                            response_character, response_weight

      pair_weight = MAX(0.0_dp, active_weight)
      IF (projector_weight <= 0.0_dp) RETURN

      gap_fraction = MIN(1.0_dp, MAX(0.0_dp, occ_gap_weight))
      response_character = gap_fraction
      IF (PRESENT(density_response_weight)) &
         response_character = MAX(response_character, &
                                  MIN(1.0_dp, MAX(0.0_dp, density_response_weight)))
      response_weight = MIN(1.0_dp, MAX(0.0_dp, density_weight))
      qualified_response_weight = SQRT(SQRT(response_weight))
      pair_weight = MAX(pair_weight, projector_weight*response_character*qualified_response_weight)
      pair_weight = MIN(projector_weight, MAX(0.0_dp, pair_weight))

   END FUNCTION kpoint_ot_physical_pair_projector_weight

! **************************************************************************************************
!> \brief finite response-character weight from a squared Mermin response signal
!> \param response_signal nonnegative curvature-weighted squared response amplitude
!> \return square-root response amplitude without an absolute machine-epsilon floor
! **************************************************************************************************
   FUNCTION kpoint_ot_projector_response_signal_weight(response_signal) RESULT(response_weight)
      REAL(KIND=dp), INTENT(IN)                          :: response_signal
      REAL(KIND=dp)                                      :: response_weight

      response_weight = 0.0_dp
      IF (response_signal <= 0.0_dp) RETURN
      response_weight = SQRT(response_signal)

   END FUNCTION kpoint_ot_projector_response_signal_weight

! **************************************************************************************************
!> \brief robust scale for finite projector density-response character
!> \param response_max largest positive channel response amplitude
!> \param response_mean mean positive channel response amplitude
!> \return response scale used to map amplitudes to [0,1] character weights
! **************************************************************************************************
   FUNCTION kpoint_ot_projector_response_character_scale(response_max, response_mean) RESULT(response_scale)
      REAL(KIND=dp), INTENT(IN)                          :: response_max, response_mean
      REAL(KIND=dp)                                      :: response_scale

      response_scale = MAX(0.0_dp, response_max)
      IF (response_scale <= EPSILON(response_scale)) RETURN
      response_scale = MAX(0.50_dp*response_scale, MAX(0.0_dp, response_mean))
      response_scale = MIN(MAX(0.0_dp, response_max), response_scale)

   END FUNCTION kpoint_ot_projector_response_character_scale

! **************************************************************************************************
!> \brief control variable for the global fixed-N low-curvature density lift
!> \param eps_scf_channel SCF convergence threshold of the local OT channel
!> \param residual_delta current physical k-point OT residual
!> \return lift control which follows the residual tail but vanishes at the final floor
! **************************************************************************************************
   FUNCTION kpoint_ot_density_global_lift_control(eps_scf_channel, residual_delta) RESULT(lift_control)
      REAL(KIND=dp), INTENT(IN)                          :: eps_scf_channel, residual_delta
      REAL(KIND=dp)                                      :: lift_control

      lift_control = MAX(0.0_dp, eps_scf_channel)
      IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) &
         lift_control = MAX(lift_control, &
                            MIN(MAX(0.0_dp, residual_delta), &
                                ot_kp_density_global_lift_eps_full))

   END FUNCTION kpoint_ot_density_global_lift_control

! **************************************************************************************************
!> \brief gauge-free physical diagonal projector-density response
!> \param density_projector_response finite projector eigenvalue response
!> \param density_safe_response gauge-safe dP/occupation-curvature response
!> \param occ_curv ...
!> \param occ_curv_max ...
!> \param density_projector_centered_response ...
!> \param density_safe_centered_response ...
!> \param density_response_alignment ...
!> \param density_global_lift_weight ...
!> \return floor-limited eigenvalue response without projector-basis dP gauge amplification
! **************************************************************************************************
   FUNCTION kpoint_ot_physical_density_response(density_projector_response, density_safe_response, &
                                                occ_curv, occ_curv_max, &
                                                density_projector_centered_response, &
                                                density_safe_centered_response, &
                                                density_response_alignment, &
                                                density_global_lift_weight) RESULT(density_response)
      REAL(KIND=dp), INTENT(IN)                          :: density_projector_response, &
                                                            density_safe_response, occ_curv, &
                                                            occ_curv_max
      REAL(KIND=dp), INTENT(IN), OPTIONAL :: density_projector_centered_response, &
         density_safe_centered_response, density_response_alignment, density_global_lift_weight
      REAL(KIND=dp)                                      :: density_response

      LOGICAL                                            :: anti_aligned_safe_response, &
                                                            globally_aligned_safe_response, &
                                                            locally_aligned_safe_response
      REAL(KIND=dp) :: active_fraction, alignment, bounded_safe_component, density_shape, &
         density_shape_full, density_shape_geometric, global_cap_lift, global_response_shape, &
         global_response_support, global_safe_cap, lift_support, lift_weight, projector_abs, &
         projector_component, projector_response_weight, response_root, response_shape, safe_abs, &
         safe_blend, safe_blend_floor, safe_cap, safe_component, safe_response_weight, &
         sign_projector_response, sign_safe_response, supported_lift_weight

      density_response = 0.0_dp
      IF (occ_curv <= EPSILON(occ_curv)) RETURN
      IF (occ_curv_max <= EPSILON(occ_curv_max)) RETURN

      active_fraction = occ_curv/MAX(occ_curv, &
                                     ot_kp_schur_projector_response_ratio_gate*occ_curv_max)
      active_fraction = MIN(1.0_dp, MAX(0.0_dp, active_fraction))
      response_shape = 2.0_dp*active_fraction - active_fraction*active_fraction
      response_root = SQRT(MAX(0.0_dp, response_shape))
      density_shape = response_shape
      lift_weight = 0.0_dp
      IF (PRESENT(density_global_lift_weight)) &
         lift_weight = MIN(1.0_dp, MAX(0.0_dp, density_global_lift_weight))
      projector_component = density_projector_response
      sign_projector_response = density_projector_response
      sign_safe_response = density_safe_response
      IF (PRESENT(density_projector_centered_response)) THEN
         projector_component = density_projector_centered_response
         sign_projector_response = density_projector_centered_response
      END IF
      IF (PRESENT(density_safe_centered_response)) &
         sign_safe_response = density_safe_centered_response
      safe_component = projector_component
      projector_abs = ABS(projector_component)
      safe_abs = ABS(sign_safe_response)
      alignment = 0.0_dp
      IF (PRESENT(density_response_alignment)) &
         alignment = MIN(1.0_dp, MAX(-1.0_dp, density_response_alignment))
      locally_aligned_safe_response = sign_projector_response*sign_safe_response > 0.0_dp .OR. &
                                      (ABS(sign_projector_response) <= EPSILON(sign_projector_response) .AND. &
                                       ABS(sign_safe_response) > EPSILON(sign_safe_response))
      globally_aligned_safe_response = alignment > 0.25_dp .AND. &
                                       safe_abs > EPSILON(safe_abs) .AND. &
                                       (sign_projector_response*sign_safe_response > 0.0_dp .OR. &
                                        projector_abs <= alignment*safe_abs)
      anti_aligned_safe_response = PRESENT(density_projector_centered_response) .AND. &
                                   PRESENT(density_safe_centered_response) .AND. &
                                   sign_projector_response*sign_safe_response < 0.0_dp .AND. &
                                   safe_abs > EPSILON(safe_abs) .AND. &
                                   projector_abs > EPSILON(projector_abs)
      IF (locally_aligned_safe_response .OR. globally_aligned_safe_response) THEN
         IF (globally_aligned_safe_response) THEN
            lift_support = 0.0_dp
            IF (safe_abs > EPSILON(safe_abs) .AND. response_root > EPSILON(response_root)) &
               lift_support = projector_abs/(response_root*safe_abs)
            lift_support = MIN(1.0_dp, MAX(0.0_dp, lift_support))
            supported_lift_weight = lift_weight*lift_support
            global_cap_lift = supported_lift_weight
            global_response_shape = response_shape + lift_support*(response_root - response_shape)
            global_response_support = global_response_shape + lift_support*(1.0_dp - global_response_shape)
            global_safe_cap = (global_response_shape + &
                               global_cap_lift*(1.0_dp - global_response_shape))*safe_abs
            safe_cap = MAX(4.0_dp*projector_abs, global_safe_cap)
         ELSE
            safe_cap = MAX(4.0_dp*projector_abs, response_shape*safe_abs)
         END IF
         bounded_safe_component = SIGN(MIN(safe_abs, safe_cap), sign_safe_response)
         safe_component = bounded_safe_component
         safe_blend = active_fraction
         IF (globally_aligned_safe_response) THEN
            safe_blend_floor = MIN(1.0_dp, alignment)*global_response_shape*global_response_support
            safe_blend = MAX(safe_blend, safe_blend_floor)
            density_shape_geometric = MAX(density_shape, SQRT(response_shape*safe_blend_floor))
            density_shape_full = MAX(density_shape, safe_blend_floor)
            density_shape = density_shape_geometric + &
                            supported_lift_weight*(density_shape_full - density_shape_geometric)
         END IF
         safe_component = (1.0_dp - safe_blend)*projector_component + &
                          safe_blend*bounded_safe_component
         IF (globally_aligned_safe_response) THEN
            ! Let globally coherent fixed-N occupation response enter through
            ! the finite projector support only.  This keeps basis-gauge dP
            ! noise out of low-curvature tails while retaining supported
            ! occupation response.
            projector_response_weight = (1.0_dp - safe_blend)*density_shape
            safe_response_weight = safe_blend*(density_shape + &
                                               supported_lift_weight*(1.0_dp - density_shape))
            density_response = projector_response_weight*projector_component + &
                               safe_response_weight*bounded_safe_component
            RETURN
         END IF
      ELSE IF (anti_aligned_safe_response) THEN
         safe_component = SIGN(MIN(projector_abs, safe_abs), sign_safe_response)
      END IF
      ! The density channel follows the finite spectral response, but once the
      ! fixed-N centered columns are available they also set the response
      ! magnitude.  This keeps channel-uniform dP gauge shifts out of the
      ! physical Schur curvature while the raw full-density columns remain
      ! available for audit/Direct models.
      density_response = density_shape*safe_component

   END FUNCTION kpoint_ot_physical_density_response

! **************************************************************************************************
!> \brief residual-aware filter for unsupported projector-density gauge response
!> \param density_response physical density response before accepted-history filtering
!> \param density_projector_response finite projector eigenvalue response
!> \param density_safe_response gauge-safe dP/occupation-curvature response
!> \param occ_curv ...
!> \param occ_curv_max ...
!> \param step_gauge_quality accepted residual quality of recent gauge-like steps
!> \param density_projector_centered_response ...
!> \param density_safe_centered_response ...
!> \param density_response_alignment ...
!> \return density response with unsupported gauge-like pieces softly suppressed
! **************************************************************************************************
   FUNCTION kpoint_ot_residual_gauge_density_response(density_response, density_projector_response, &
                                                      density_safe_response, occ_curv, occ_curv_max, &
                                                      step_gauge_quality, density_projector_centered_response, &
                                                      density_safe_centered_response, density_response_alignment) &
      RESULT(filtered_response)
      REAL(KIND=dp), INTENT(IN) :: density_response, density_projector_response, &
         density_safe_response, occ_curv, occ_curv_max, step_gauge_quality
      REAL(KIND=dp), INTENT(IN), OPTIONAL :: density_projector_centered_response, &
         density_safe_centered_response, density_response_alignment
      REAL(KIND=dp)                                      :: filtered_response

      LOGICAL                                            :: globally_supported_response, &
                                                            locally_supported_response
      REAL(KIND=dp) :: active_fraction, alignment, damping, finite_support, &
         global_response_support, global_support, projector_abs, residual_weight, response_root, &
         response_shape, response_support, safe_abs, sign_projector_response, sign_safe_response

      filtered_response = density_response
      IF (occ_curv <= EPSILON(occ_curv)) RETURN
      IF (occ_curv_max <= EPSILON(occ_curv_max)) RETURN

      residual_weight = 1.0_dp - MIN(1.0_dp, MAX(0.0_dp, step_gauge_quality))
      IF (residual_weight <= EPSILON(residual_weight)) RETURN

      active_fraction = occ_curv/MAX(occ_curv, &
                                     ot_kp_schur_projector_response_ratio_gate*occ_curv_max)
      active_fraction = MIN(1.0_dp, MAX(0.0_dp, active_fraction))
      response_shape = 2.0_dp*active_fraction - active_fraction*active_fraction
      response_root = SQRT(MAX(0.0_dp, response_shape))
      sign_projector_response = density_projector_response
      sign_safe_response = density_safe_response
      IF (PRESENT(density_projector_centered_response)) &
         sign_projector_response = density_projector_centered_response
      IF (PRESENT(density_safe_centered_response)) &
         sign_safe_response = density_safe_centered_response
      alignment = 0.0_dp
      IF (PRESENT(density_response_alignment)) &
         alignment = MIN(1.0_dp, MAX(-1.0_dp, density_response_alignment))

      projector_abs = ABS(sign_projector_response)
      safe_abs = ABS(sign_safe_response)
      locally_supported_response = sign_projector_response*sign_safe_response > 0.0_dp
      globally_supported_response = alignment > 0.25_dp .AND. &
                                    safe_abs > EPSILON(safe_abs) .AND. &
                                    (sign_projector_response*sign_safe_response > 0.0_dp .OR. &
                                     projector_abs <= alignment*safe_abs)
      response_support = 0.0_dp
      IF (locally_supported_response .OR. globally_supported_response) THEN
         IF (locally_supported_response) &
            response_support = MIN(1.0_dp, safe_abs/MAX(projector_abs, EPSILON(1.0_dp)))
         IF (globally_supported_response) THEN
            global_support = MIN(1.0_dp, MAX(0.0_dp, alignment))
            IF (sign_projector_response*sign_safe_response <= 0.0_dp .AND. &
                safe_abs > EPSILON(safe_abs) .AND. response_root > EPSILON(response_root)) THEN
               finite_support = projector_abs/(response_root*safe_abs)
               finite_support = MIN(1.0_dp, MAX(0.0_dp, finite_support))
               global_response_support = response_root + finite_support*(1.0_dp - response_root)
               global_support = global_support*finite_support*global_response_support
            END IF
            response_support = MAX(response_support, global_support)
         END IF
      END IF

      damping = 1.0_dp - residual_weight*(1.0_dp - response_support)* &
                (1.0_dp - active_fraction)**2
      filtered_response = MAX(0.0_dp, MIN(1.0_dp, damping))*density_response

   END FUNCTION kpoint_ot_residual_gauge_density_response

! **************************************************************************************************
!> \brief shadow-only finite-floor physical diagonal projector-density response
!> \param density_projector_response finite projector eigenvalue response
!> \param density_safe_response gauge-safe dP/occupation-curvature response, audit only
!> \param occ_curv ...
!> \param occ_curv_max ...
!> \return floor-limited finite spectral response for density-response shadow calibration
! **************************************************************************************************
   FUNCTION kpoint_ot_physical_density_floor_audit_response(density_projector_response, density_safe_response, &
                                                            occ_curv, occ_curv_max) RESULT(density_response)
      REAL(KIND=dp), INTENT(IN)                          :: density_projector_response, &
                                                            density_safe_response, occ_curv, &
                                                            occ_curv_max
      REAL(KIND=dp)                                      :: density_response

      LOGICAL                                            :: collapsed_projector_response
      REAL(KIND=dp)                                      :: active_fraction, projector_abs, &
                                                            response_shape, safe_abs

      density_response = 0.0_dp
      IF (occ_curv <= EPSILON(occ_curv)) RETURN
      IF (occ_curv_max <= EPSILON(occ_curv_max)) RETURN

      active_fraction = occ_curv/MAX(occ_curv, &
                                     ot_kp_schur_projector_response_ratio_gate*occ_curv_max)
      active_fraction = MIN(1.0_dp, MAX(0.0_dp, active_fraction))
      response_shape = 2.0_dp*active_fraction - active_fraction*active_fraction
      density_response = response_shape*density_projector_response
      safe_abs = ABS(density_safe_response)
      projector_abs = ABS(density_projector_response)
      collapsed_projector_response = safe_abs > EPSILON(safe_abs) .AND. &
                                     projector_abs <= SQRT(EPSILON(1.0_dp))*MAX(1.0_dp, safe_abs)
      IF (collapsed_projector_response) &
         density_response = response_shape*density_safe_response

   END FUNCTION kpoint_ot_physical_density_floor_audit_response

! **************************************************************************************************
!> \brief shadow-only fixed-N safe density response for collapsed finite-projector floor modes
!> \param density_projector_response finite projector eigenvalue response
!> \param density_safe_response gauge-safe dP/occupation-curvature response
!> \param occ_curv ...
!> \param occ_curv_max ...
!> \return safe response only when the finite-projector response is numerically collapsed
! **************************************************************************************************
   FUNCTION kpoint_ot_collapsed_safe_density_floor_response(density_projector_response, density_safe_response, &
                                                            occ_curv, occ_curv_max) RESULT(density_response)
      REAL(KIND=dp), INTENT(IN)                          :: density_projector_response, &
                                                            density_safe_response, occ_curv, &
                                                            occ_curv_max
      REAL(KIND=dp)                                      :: density_response

      REAL(KIND=dp)                                      :: active_fraction, projector_abs, &
                                                            response_shape, safe_abs

      density_response = 0.0_dp
      IF (occ_curv <= EPSILON(occ_curv)) RETURN
      IF (occ_curv_max <= EPSILON(occ_curv_max)) RETURN

      safe_abs = ABS(density_safe_response)
      projector_abs = ABS(density_projector_response)
      IF (safe_abs <= EPSILON(safe_abs)) RETURN
      IF (projector_abs > SQRT(EPSILON(1.0_dp))*MAX(1.0_dp, safe_abs)) RETURN

      active_fraction = occ_curv/MAX(occ_curv, &
                                     ot_kp_schur_projector_response_ratio_gate*occ_curv_max)
      active_fraction = MIN(1.0_dp, MAX(0.0_dp, active_fraction))
      response_shape = 2.0_dp*active_fraction - active_fraction*active_fraction
      density_response = response_shape*density_safe_response

   END FUNCTION kpoint_ot_collapsed_safe_density_floor_response

! **************************************************************************************************
!> \brief selected-history retry gate for the physical spectral projector Schur candidate
!> \param selected_failures accepted-line-search probes that overpredicted too strongly
!> \param selected_quality_ema selected accepted-drop quality EMA
!> \param selected_residual_quality_ema selected residual-quality EMA
!> \param shadow_quality current independent shadow accepted-drop quality
!> \param shadow_quality_ema independent shadow accepted-drop quality EMA
!> \param shadow_dot_ema independent shadow linear response signal EMA
!> \param shadow_norm_ema independent shadow metric response signal EMA
!> \param shadow_floor_ema independent shadow finite spectral floor EMA
!> \return true if selected spectral probes may continue collecting accepted history
! **************************************************************************************************
   FUNCTION kpoint_ot_spectral_probe_history_ready(selected_failures, selected_quality_ema, &
                                                   selected_residual_quality_ema, shadow_quality, &
                                                   shadow_quality_ema, shadow_dot_ema, &
                                                   shadow_norm_ema, shadow_floor_ema) &
      RESULT(history_ready)
      INTEGER, INTENT(IN)                                :: selected_failures
      REAL(KIND=dp), INTENT(IN) :: selected_quality_ema, selected_residual_quality_ema, &
         shadow_quality, shadow_quality_ema, shadow_dot_ema, shadow_norm_ema, shadow_floor_ema
      LOGICAL                                            :: history_ready

      LOGICAL                                            :: shadow_signal_ok

      history_ready = .FALSE.
      IF (selected_failures >= ot_kp_schur_projector_spectral_probe_max_failures) RETURN
      IF (selected_failures == 0) THEN
         history_ready = .TRUE.
         RETURN
      END IF

      IF (selected_quality_ema >= 0.5_dp*ot_kp_schur_projector_response_quality_min_ratio .OR. &
          selected_residual_quality_ema >= 0.5_dp*ot_kp_schur_projector_response_quality_min_ratio) THEN
         history_ready = .TRUE.
         RETURN
      END IF

      shadow_signal_ok = shadow_floor_ema > EPSILON(shadow_floor_ema) .AND. &
                         shadow_dot_ema >= shadow_floor_ema .AND. &
                         shadow_norm_ema >= shadow_floor_ema
      history_ready = shadow_signal_ok .AND. &
                      shadow_quality >= ot_kp_schur_projector_spectral_probe_quality_min .AND. &
                      shadow_quality_ema >= ot_kp_schur_projector_spectral_probe_quality_min

   END FUNCTION kpoint_ot_spectral_probe_history_ready

! **************************************************************************************************
!> \brief quality gate for conservative but mature spectral-shadow probe bootstrap
!> \param shadow_quality current independent shadow accepted-drop quality
!> \param shadow_quality_ema independent shadow accepted-drop quality EMA
!> \param shadow_samples number of accepted shadow-history samples
!> \param shadow_drop_sum accumulated shadow predicted Mermin drop
!> \param shadow_measured_sum accumulated shadow measured Mermin drop
!> \param shadow_dot_ema independent shadow linear response signal EMA
!> \param shadow_norm_ema independent shadow metric response signal EMA
!> \param shadow_floor_ema independent shadow finite spectral floor EMA
!> \return true if mature spectral shadow history may collect selected probe history
! **************************************************************************************************
   FUNCTION kpoint_ot_spectral_shadow_probe_quality_ready(shadow_quality, shadow_quality_ema, &
                                                          shadow_samples, shadow_drop_sum, &
                                                          shadow_measured_sum, shadow_dot_ema, &
                                                          shadow_norm_ema, shadow_floor_ema) &
      RESULT(quality_ready)
      REAL(KIND=dp), INTENT(IN)                          :: shadow_quality, shadow_quality_ema
      INTEGER, INTENT(IN)                                :: shadow_samples
      REAL(KIND=dp), INTENT(IN)                          :: shadow_drop_sum, shadow_measured_sum, &
                                                            shadow_dot_ema, shadow_norm_ema, &
                                                            shadow_floor_ema
      LOGICAL                                            :: quality_ready

      REAL(KIND=dp)                                      :: quality_floor, quality_total_floor, &
                                                            shadow_signal_ratio, total_quality

      quality_ready = .FALSE.
      IF (shadow_samples < ot_kp_schur_projector_response_min_samples) RETURN
      IF (shadow_drop_sum <= EPSILON(shadow_drop_sum)) RETURN
      IF (shadow_measured_sum <= 0.0_dp) RETURN
      IF (shadow_dot_ema <= 0.0_dp) RETURN
      IF (shadow_norm_ema <= EPSILON(shadow_norm_ema)) RETURN
      IF (shadow_floor_ema <= EPSILON(shadow_floor_ema)) RETURN

      total_quality = shadow_measured_sum/shadow_drop_sum
      quality_floor = 0.5_dp*ot_kp_schur_projector_spectral_probe_quality_min
      quality_total_floor = 0.5_dp*quality_floor
      IF (shadow_quality_ema >= ot_kp_schur_projector_spectral_probe_quality_min .AND. &
          shadow_quality >= quality_floor) THEN
         quality_ready = .TRUE.
         RETURN
      END IF

      shadow_signal_ratio = shadow_dot_ema/MAX(shadow_norm_ema, EPSILON(shadow_norm_ema))
      quality_ready = shadow_quality_ema >= quality_floor .AND. &
                      shadow_quality >= quality_floor .AND. &
                      total_quality >= quality_total_floor .AND. &
                      shadow_signal_ratio >= shadow_floor_ema

   END FUNCTION kpoint_ot_spectral_shadow_probe_quality_ready

! **************************************************************************************************
!> \brief update selected spectral-probe failure count from Mermin and residual quality
!> \param selected_failures current selected-probe failure count
!> \param selected_quality accepted Mermin-drop quality of the selected spectral probe
!> \param residual_quality physical residual quality of the accepted spectral probe
!> \return updated selected-probe failure count
! **************************************************************************************************
   FUNCTION kpoint_ot_spectral_selected_failure_count(selected_failures, selected_quality, residual_quality) &
      RESULT(updated_failures)
      INTEGER, INTENT(IN)                                :: selected_failures
      REAL(KIND=dp), INTENT(IN)                          :: selected_quality, residual_quality
      INTEGER                                            :: updated_failures

      updated_failures = selected_failures
      IF (residual_quality < 0.25_dp*ot_kp_schur_projector_response_quality_min_ratio) THEN
         updated_failures = ot_kp_schur_projector_spectral_probe_max_failures
      ELSE IF (selected_quality < &
               0.5_dp*ot_kp_schur_projector_response_quality_min_ratio .AND. &
               residual_quality < ot_kp_schur_projector_response_quality_min_ratio) THEN
         updated_failures = MIN(selected_failures + 1, HUGE(updated_failures) - 1)
      END IF

   END FUNCTION kpoint_ot_spectral_selected_failure_count

! **************************************************************************************************
!> \brief residual-aware bootstrap gate for selected spectral probes from shadow history
!> \param shadow_quality_ready true if independent spectral-shadow quality is mature
!> \param residual_quality physical residual quality of the latest accepted step
!> \return true if spectral shadow history may bootstrap a selected probe
! **************************************************************************************************
   FUNCTION kpoint_ot_spectral_shadow_probe_bootstrap_ready(shadow_quality_ready, residual_quality) &
      RESULT(bootstrap_ready)
      LOGICAL, INTENT(IN)                                :: shadow_quality_ready
      REAL(KIND=dp), INTENT(IN)                          :: residual_quality
      LOGICAL                                            :: bootstrap_ready

      bootstrap_ready = shadow_quality_ready .AND. &
                        residual_quality >= &
                        0.5_dp*ot_kp_schur_projector_response_quality_min_ratio

   END FUNCTION kpoint_ot_spectral_shadow_probe_bootstrap_ready

! **************************************************************************************************
!> \brief tail bootstrap gate for the physical Direct k-point Schur candidate
!> \param candidate_used ...
!> \param promoted ...
!> \param candidate_enabled ...
!> \param residual_delta ...
!> \param coupled_quality_samples ...
!> \param selected_quality_samples ...
!> \param selected_quality_ema ...
!> \param selected_quality ...
!> \param selected_residual_quality_ema ...
!> \param selected_residual_quality ...
!> \param shadow_quality ...
!> \param coupled_residual_quality_ema ...
!> \param weighted_trust_ratio ...
!> \param abs_trust_ratio ...
!> \param model_gap_ratio ...
!> \return true if a trust-safe Direct tail probe may collect selected history
! **************************************************************************************************
   FUNCTION kpoint_ot_direct_tail_probe_ready(candidate_used, promoted, candidate_enabled, residual_delta, &
                                              coupled_quality_samples, selected_quality_samples, &
                                              selected_quality_ema, selected_quality, &
                                              selected_residual_quality_ema, selected_residual_quality, &
                                              shadow_quality, &
                                              coupled_residual_quality_ema, weighted_trust_ratio, abs_trust_ratio, &
                                              model_gap_ratio) &
      RESULT(probe_ready)
      LOGICAL, INTENT(IN)                                :: candidate_used, promoted, &
                                                            candidate_enabled
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta
      INTEGER, INTENT(IN)                                :: coupled_quality_samples, &
                                                            selected_quality_samples
      REAL(KIND=dp), INTENT(IN) :: selected_quality_ema, selected_quality, &
         selected_residual_quality_ema, selected_residual_quality, shadow_quality, &
         coupled_residual_quality_ema, weighted_trust_ratio, abs_trust_ratio, model_gap_ratio
      LOGICAL                                            :: probe_ready

      INTEGER                                            :: sparse_probe_interval
      LOGICAL                                            :: residual_tail_stalled, &
                                                            selected_quality_positive

      probe_ready = .FALSE.
      IF (.NOT. candidate_used) RETURN
      IF (promoted .OR. candidate_enabled) RETURN
      IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) RETURN
      IF (coupled_quality_samples < ot_kp_schur_calibration_min_samples) RETURN
      IF (shadow_quality < ot_kp_schur_projector_response_quality_min_ratio) RETURN
      IF (weighted_trust_ratio > ot_kp_schur_projector_spectral_probe_trust_fraction) RETURN
      IF (abs_trust_ratio > ot_kp_schur_projector_spectral_probe_trust_fraction) RETURN
      IF (model_gap_ratio > ot_kp_schur_projector_spectral_probe_trust_fraction) RETURN

      IF (selected_quality_samples < ot_kp_schur_calibration_min_samples) THEN
         probe_ready = .TRUE.
         RETURN
      END IF

      selected_quality_positive = &
         selected_quality_ema >= 0.5_dp*ot_kp_schur_projector_response_quality_min_ratio .AND. &
         selected_quality >= 0.5_dp*ot_kp_schur_projector_response_quality_min_ratio .AND. &
         selected_residual_quality_ema >= &
         0.5_dp*ot_kp_schur_projector_response_quality_min_ratio .AND. &
         selected_residual_quality >= &
         0.5_dp*ot_kp_schur_projector_response_quality_min_ratio
      sparse_probe_interval = MAX(1, 4*ot_kp_schur_calibration_min_samples)
      probe_ready = selected_quality_positive .AND. MOD(coupled_quality_samples, sparse_probe_interval) == 0
      IF (.NOT. probe_ready) THEN
         residual_tail_stalled = coupled_residual_quality_ema < 0.25_dp
         selected_quality_positive = &
            selected_quality_ema >= 0.5_dp*ot_kp_schur_projector_response_quality_min_ratio .AND. &
            selected_quality >= 0.25_dp*ot_kp_schur_projector_response_quality_min_ratio .AND. &
            selected_residual_quality_ema >= &
            0.25_dp*ot_kp_schur_projector_response_quality_min_ratio .AND. &
            selected_residual_quality >= &
            0.25_dp*ot_kp_schur_projector_response_quality_min_ratio
         probe_ready = residual_tail_stalled .AND. selected_quality_positive .AND. &
                       MOD(coupled_quality_samples, MAX(1, 2*ot_kp_schur_calibration_min_samples)) == 0
      END IF

   END FUNCTION kpoint_ot_direct_tail_probe_ready

! **************************************************************************************************
!> \brief close-call residual-tail probe for promoted physical Direct candidates
!> \param residual_delta current OT residual
!> \param candidate_expected_drop calibrated Direct expected Mermin drop
!> \param reference_expected_drop currently selected dense-coupled expected drop
!> \param quality_for_selection calibrated Direct selection quality
!> \param promoted whether the physical Direct candidate has accepted shadow evidence
!> \param mixed_enabled whether the mixed active/physical Direct model is enabled
!> \param tail_probe_ready sparse tail-probe bootstrap from selected history
!> \param weighted_trust_ratio curvature-weighted response trust ratio
!> \param abs_trust_ratio absolute response trust ratio
!> \param model_gap_ratio response-model mismatch trust ratio
!> \param dense_residual_quality residual quality of the dense-coupled baseline
!> \return true if a trust-safe Direct close call may collect selected history
! **************************************************************************************************
   FUNCTION kpoint_ot_direct_tail_close_call(residual_delta, candidate_expected_drop, reference_expected_drop, &
                                             quality_for_selection, promoted, mixed_enabled, tail_probe_ready, &
                                             weighted_trust_ratio, abs_trust_ratio, model_gap_ratio, &
                                             dense_residual_quality) RESULT(do_probe)
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta, candidate_expected_drop, &
                                                            reference_expected_drop, &
                                                            quality_for_selection
      LOGICAL, INTENT(IN)                                :: promoted, mixed_enabled, tail_probe_ready
      REAL(KIND=dp), INTENT(IN)                          :: weighted_trust_ratio, abs_trust_ratio, &
                                                            model_gap_ratio, dense_residual_quality
      LOGICAL                                            :: do_probe

      REAL(KIND=dp)                                      :: required_drop_ratio

      do_probe = .FALSE.
      IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) RETURN
      IF (.NOT. (promoted .OR. mixed_enabled .OR. tail_probe_ready)) RETURN
      IF (candidate_expected_drop <= ot_kp_schur_projector_density_full_min_drop) RETURN
      IF (quality_for_selection < ot_kp_schur_projector_response_quality_min_ratio) RETURN
      IF (weighted_trust_ratio > ot_kp_schur_projector_spectral_probe_trust_fraction) RETURN
      IF (abs_trust_ratio > ot_kp_schur_projector_spectral_probe_trust_fraction) RETURN
      IF (model_gap_ratio > ot_kp_schur_projector_spectral_probe_trust_fraction) RETURN

      required_drop_ratio = ot_kp_schur_projector_density_fdir_probe_ratio
      IF (dense_residual_quality <= ot_kp_schur_calibrated_quality_min_ratio) &
         required_drop_ratio = MIN(required_drop_ratio, &
                                   0.5_dp + dense_residual_quality)
      ! tail_probe_ready is already sparse, response-trust checked, and is the
      ! only route for completing selected Direct history.  Do not make that
      ! bootstrap impossible merely because the conservative physical model
      ! predicts a smaller drop than the over-optimistic dense candidate.
      IF (tail_probe_ready) &
         required_drop_ratio = MIN(required_drop_ratio, &
                                   ot_kp_schur_projector_response_quality_min_ratio)
      IF (candidate_expected_drop < required_drop_ratio* &
          MAX(reference_expected_drop, ot_kp_schur_projector_density_full_min_drop)) RETURN

      do_probe = .TRUE.

   END FUNCTION kpoint_ot_direct_tail_close_call

! **************************************************************************************************
!> \brief whether a norm-limited Direct tail step may replace the over-norm raw Direct step
!> \param normcap_ready normcap shadow is finite and response-trust safe
!> \param promoted accepted Direct shadow history is mature enough for production use
!> \param residual_delta current OT residual
!> \param normcap_norm_ratio norm ratio of the capped step
!> \param max_norm_ratio active norm-ratio limit
!> \param normcap_scale scale applied to the raw Direct step
!> \param min_scale minimum line-search scale considered useful
!> \param density_audit_quality consistency of the density-response audit
!> \return true if the norm-limited step may enter the Direct candidate path
! **************************************************************************************************
   FUNCTION kpoint_ot_direct_normcap_tail_ready(normcap_ready, promoted, residual_delta, &
                                                normcap_norm_ratio, max_norm_ratio, normcap_scale, &
                                                min_scale, density_audit_quality) RESULT(use_step)
      LOGICAL, INTENT(IN)                                :: normcap_ready, promoted
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta, normcap_norm_ratio, &
                                                            max_norm_ratio, normcap_scale, &
                                                            min_scale, density_audit_quality
      LOGICAL                                            :: use_step

      use_step = .FALSE.
      IF (.NOT. normcap_ready) RETURN
      IF (.NOT. promoted) RETURN
      IF (residual_delta > 0.25_dp*ot_kp_schur_projector_coupled_tail_delta) RETURN
      IF (max_norm_ratio <= 0.0_dp) RETURN
      IF (normcap_norm_ratio > max_norm_ratio) RETURN
      IF (normcap_scale < min_scale) RETURN
      IF (density_audit_quality < 0.5_dp*ot_kp_schur_projector_response_quality_min_ratio) RETURN

      use_step = .TRUE.

   END FUNCTION kpoint_ot_direct_normcap_tail_ready

! **************************************************************************************************
!> \brief selected-history drop for accepted neighbouring candidates sharing the Direct rotation
!> \param source_selected accepted neighbouring candidate used this step
!> \param source_ready neighbouring candidate was ready before selection
!> \param direct_ready physical Direct candidate was ready before selection
!> \param direct_drop physical Direct calibrated drop for the same search point
!> \param source_drop neighbouring calibrated drop tied to the same Direct rotation
!> \param accepted_drop calibrated drop of the actually accepted step
!> \param min_ratio minimum overlap between Direct and source model drops
!> \return conservative drop that may seed Direct selected-history
! **************************************************************************************************
   FUNCTION kpoint_ot_direct_selected_bridge_drop(source_selected, source_ready, direct_ready, &
                                                  direct_drop, source_drop, accepted_drop, &
                                                  min_ratio) RESULT(bridge_drop)
      LOGICAL, INTENT(IN)                                :: source_selected, source_ready, &
                                                            direct_ready
      REAL(KIND=dp), INTENT(IN)                          :: direct_drop, source_drop, accepted_drop, &
                                                            min_ratio
      REAL(KIND=dp)                                      :: bridge_drop

      REAL(KIND=dp)                                      :: overlap_ratio

      bridge_drop = 0.0_dp
      IF (.NOT. source_selected) RETURN
      IF (.NOT. source_ready) RETURN
      IF (.NOT. direct_ready) RETURN
      IF (direct_drop <= EPSILON(direct_drop)) RETURN
      IF (source_drop <= EPSILON(source_drop)) RETURN
      IF (accepted_drop <= EPSILON(accepted_drop)) RETURN

      overlap_ratio = MIN(direct_drop, source_drop)/MAX(direct_drop, source_drop)
      IF (overlap_ratio < min_ratio) RETURN

      bridge_drop = MIN(accepted_drop, direct_drop, source_drop)

   END FUNCTION kpoint_ot_direct_selected_bridge_drop

! **************************************************************************************************
!> \brief shared pair slope for near-degenerate occupation-gauge filtering
!> \param occ_curv_i ...
!> \param occ_curv_j ...
!> \return ...
! **************************************************************************************************
   FUNCTION kpoint_ot_shared_occ_slope(occ_curv_i, occ_curv_j) RESULT(slope)
      REAL(KIND=dp), INTENT(IN)                          :: occ_curv_i, occ_curv_j
      REAL(KIND=dp)                                      :: slope

      slope = 2.0_dp*SQRT(MAX(0.0_dp, occ_curv_i)*MAX(0.0_dp, occ_curv_j))

   END FUNCTION kpoint_ot_shared_occ_slope

! **************************************************************************************************
!> \brief local energy gap used to separate projector gauge noise from physical Fermi response
!> \param gauge_gap ...
!> \param occ_curv_i ...
!> \param occ_curv_j ...
!> \param occ_curv_max ...
!> \param projector_window_gap ...
!> \return thermally widened gap for active occupation-response pairs
! **************************************************************************************************
   FUNCTION kpoint_ot_projector_occupation_pair_gap(gauge_gap, occ_curv_i, occ_curv_j, &
                                                    occ_curv_max, projector_window_gap) RESULT(pair_gap)
      REAL(KIND=dp), INTENT(IN)                          :: gauge_gap, occ_curv_i, occ_curv_j, &
                                                            occ_curv_max
      REAL(KIND=dp), INTENT(IN), OPTIONAL                :: projector_window_gap
      REAL(KIND=dp)                                      :: pair_gap

      REAL(KIND=dp)                                      :: active_fraction, max_gap, pair_slope, &
                                                            physical_gap, thermal_gap

      pair_gap = gauge_gap
      IF (gauge_gap <= EPSILON(gauge_gap)) RETURN
      IF (occ_curv_max <= EPSILON(occ_curv_max)) RETURN

      physical_gap = gauge_gap
      IF (PRESENT(projector_window_gap)) physical_gap = MAX(physical_gap, projector_window_gap)
      max_gap = MAX(ot_kp_projector_occupation_thermal_gap_max_factor*gauge_gap, physical_gap)
      thermal_gap = ot_kp_projector_occupation_thermal_gap_fraction/occ_curv_max
      thermal_gap = MAX(thermal_gap, physical_gap)
      thermal_gap = MIN(max_gap, thermal_gap)

      pair_slope = kpoint_ot_shared_occ_slope(occ_curv_i, occ_curv_j)
      active_fraction = pair_slope/occ_curv_max
      active_fraction = MIN(1.0_dp, MAX(0.0_dp, active_fraction))
      thermal_gap = MAX(gauge_gap, thermal_gap)
      pair_gap = gauge_gap + active_fraction*(thermal_gap - gauge_gap)

   END FUNCTION kpoint_ot_projector_occupation_pair_gap

! **************************************************************************************************
!> \brief bounded divided-difference slope for finite occupation-projector response pairs
!> \param denom ...
!> \param gauge_gap ...
!> \param occ_curv_i ...
!> \param occ_curv_j ...
!> \param occ_curv_max ...
!> \param projector_window_gap ...
!> \return slope cap preserving far projector response but filtering near thermal gauge noise
! **************************************************************************************************
   FUNCTION kpoint_ot_projector_pair_slope_cap(denom, gauge_gap, occ_curv_i, occ_curv_j, occ_curv_max, &
                                               projector_window_gap) RESULT(slope_cap)
      REAL(KIND=dp), INTENT(IN)                          :: denom, gauge_gap, occ_curv_i, &
                                                            occ_curv_j, occ_curv_max
      REAL(KIND=dp), INTENT(IN), OPTIONAL                :: projector_window_gap
      REAL(KIND=dp)                                      :: slope_cap

      REAL(KIND=dp)                                      :: local_gap

      slope_cap = 2.0_dp*MAX(0.0_dp, MAX(occ_curv_i, occ_curv_j))
      IF (slope_cap <= EPSILON(slope_cap)) RETURN

      IF (PRESENT(projector_window_gap)) THEN
         local_gap = kpoint_ot_projector_occupation_pair_gap(gauge_gap, occ_curv_i, occ_curv_j, &
                                                             occ_curv_max, projector_window_gap)
      ELSE
         local_gap = kpoint_ot_projector_occupation_pair_gap(gauge_gap, occ_curv_i, occ_curv_j, &
                                                             occ_curv_max)
      END IF
      IF (ABS(denom) <= local_gap) &
         slope_cap = MIN(slope_cap, kpoint_ot_shared_occ_slope(occ_curv_i, occ_curv_j))

   END FUNCTION kpoint_ot_projector_pair_slope_cap

! **************************************************************************************************
!> \brief thermally widened response gap for one occupation-projector cluster
!> \param evals ...
!> \param occ_curv_channel ...
!> \param first ...
!> \param last ...
!> \param gauge_gap ...
!> \param occ_curv_max ...
!> \param projector_window_gap ...
!> \return maximum local pair gap inside the cluster
! **************************************************************************************************
   FUNCTION kpoint_ot_projector_cluster_response_gap(evals, occ_curv_channel, first, last, gauge_gap, &
                                                     occ_curv_max, projector_window_gap) RESULT(cluster_gap)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: evals, occ_curv_channel
      INTEGER, INTENT(IN)                                :: first, last
      REAL(KIND=dp), INTENT(IN)                          :: gauge_gap, occ_curv_max
      REAL(KIND=dp), INTENT(IN), OPTIONAL                :: projector_window_gap
      REAL(KIND=dp)                                      :: cluster_gap

      INTEGER                                            :: i

      cluster_gap = SQRT(EPSILON(1.0_dp))*MAX(1.0_dp, MAXVAL(ABS(evals(:))))
      DO i = first, last - 1
         IF (PRESENT(projector_window_gap)) THEN
            cluster_gap = MAX(cluster_gap, &
                              kpoint_ot_projector_occupation_pair_gap(gauge_gap, occ_curv_channel(i), &
                                                                      occ_curv_channel(i + 1), occ_curv_max, &
                                                                      projector_window_gap))
         ELSE
            cluster_gap = MAX(cluster_gap, &
                              kpoint_ot_projector_occupation_pair_gap(gauge_gap, occ_curv_channel(i), &
                                                                      occ_curv_channel(i + 1), occ_curv_max))
         END IF
      END DO

   END FUNCTION kpoint_ot_projector_cluster_response_gap

! **************************************************************************************************
!> \brief resolved fraction of physical occupation response inside one Projector cluster
!> \param cluster_span energy span of the near-degenerate cluster
!> \param cluster_gap thermally widened response gap for the cluster
!> \param gap_tol numerical exact-degeneracy threshold
!> \return 0 for pure gauge degeneracy, 1 for thermally resolved clusters
! **************************************************************************************************
   FUNCTION kpoint_ot_projector_cluster_resolution_weight(cluster_span, cluster_gap, gap_tol) RESULT(weight)
      REAL(KIND=dp), INTENT(IN)                          :: cluster_span, cluster_gap, gap_tol
      REAL(KIND=dp)                                      :: weight

      weight = 0.0_dp
      IF (cluster_gap <= gap_tol) RETURN
      weight = (cluster_span - gap_tol)/MAX(EPSILON(1.0_dp), cluster_gap - gap_tol)
      weight = MIN(1.0_dp, MAX(0.0_dp, weight))

   END FUNCTION kpoint_ot_projector_cluster_resolution_weight

! **************************************************************************************************
!> \brief Direct-model trace compensation for the physical Projector Schur correction
!> \param coupled_weight ...
!> \param direct_delta_diag_avg ...
!> \param reference_delta_diag_avg ...
!> \return ...
! **************************************************************************************************
   FUNCTION kpoint_ot_direct_trace_compensation(coupled_weight, direct_delta_diag_avg, &
                                                reference_delta_diag_avg) RESULT(compensation)
      REAL(KIND=dp), INTENT(IN)                          :: coupled_weight, direct_delta_diag_avg, &
                                                            reference_delta_diag_avg
      REAL(KIND=dp)                                      :: compensation

      REAL(KIND=dp)                                      :: positive_reference

      positive_reference = MAX(0.0_dp, reference_delta_diag_avg)
      compensation = MAX(0.0_dp, -coupled_weight*direct_delta_diag_avg)
      IF (direct_delta_diag_avg > positive_reference) &
         compensation = MAX(compensation, coupled_weight*(direct_delta_diag_avg - positive_reference))

   END FUNCTION kpoint_ot_direct_trace_compensation

! **************************************************************************************************
!> \brief Quadratic trace metrics for physical Projector Schur response models.
!> \param sol rotation-space trial direction
!> \param actual_delta measured finite Projector curvature relative to the base model
!> \param base_hessian base rotation Hessian
!> \param full_hessian full physical Projector Hessian
!> \param invariant_hessian gauge-invariant Projector Hessian
!> \param active_hessian active-pair physical Projector Hessian
!> \return total, diagonal, off-diagonal, and normalized quadratic metrics
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_projector_trace_metrics( &
      sol, actual_delta, base_hessian, full_hessian, invariant_hessian, active_hessian) &
      RESULT(metrics)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: sol
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: actual_delta, base_hessian, &
                                                            full_hessian, invariant_hessian, &
                                                            active_hessian
      TYPE(qs_scf_kp_projector_trace_metrics_type)       :: metrics

      INTEGER                                            :: r, s
      REAL(KIND=dp)                                      :: active_term, actual_term, full_term, &
                                                            invariant_term, sol_norm, sol_sq

      DO s = 1, SIZE(sol)
         DO r = 1, SIZE(sol)
            actual_term = 0.5_dp*(actual_delta(r, s) + actual_delta(s, r))
            full_term = 0.5_dp*((full_hessian(r, s) - base_hessian(r, s)) + &
                                (full_hessian(s, r) - base_hessian(s, r)))
            invariant_term = 0.5_dp*((invariant_hessian(r, s) - base_hessian(r, s)) + &
                                     (invariant_hessian(s, r) - base_hessian(s, r)))
            active_term = 0.5_dp*((active_hessian(r, s) - base_hessian(r, s)) + &
                                  (active_hessian(s, r) - base_hessian(s, r)))
            metrics%actual_quad = metrics%actual_quad + sol(r)*actual_term*sol(s)
            metrics%full_quad = metrics%full_quad + sol(r)*full_term*sol(s)
            metrics%invariant_quad = metrics%invariant_quad + sol(r)*invariant_term*sol(s)
            metrics%active_quad = metrics%active_quad + sol(r)*active_term*sol(s)
         END DO
      END DO

      metrics%excess_quad = metrics%full_quad - metrics%active_quad
      IF (ABS(metrics%full_quad) > EPSILON(metrics%full_quad)) &
         metrics%active_full_ratio = metrics%active_quad/metrics%full_quad
      IF (ABS(metrics%actual_quad) > EPSILON(metrics%actual_quad)) &
         metrics%active_actual_ratio = metrics%active_quad/metrics%actual_quad
      metrics%invariant_gap_quad = metrics%invariant_quad - metrics%full_quad
      IF (ABS(metrics%invariant_quad) > EPSILON(metrics%invariant_quad)) &
         metrics%full_invariant_ratio = metrics%full_quad/metrics%invariant_quad

      sol_norm = DOT_PRODUCT(sol, sol)
      IF (sol_norm > EPSILON(sol_norm)) THEN
         DO r = 1, SIZE(sol)
            sol_sq = sol(r)*sol(r)
            metrics%actual_diag_quad = metrics%actual_diag_quad + sol_sq*actual_delta(r, r)
            metrics%full_diag_quad = metrics%full_diag_quad + &
                                     sol_sq*(full_hessian(r, r) - base_hessian(r, r))
            metrics%invariant_diag_quad = metrics%invariant_diag_quad + &
                                          sol_sq*(invariant_hessian(r, r) - base_hessian(r, r))
            metrics%active_diag_quad = metrics%active_diag_quad + &
                                       sol_sq*(active_hessian(r, r) - base_hessian(r, r))
         END DO
         metrics%actual_free_quad = metrics%actual_quad - metrics%actual_diag_quad
         metrics%full_free_quad = metrics%full_quad - metrics%full_diag_quad
         metrics%invariant_free_quad = metrics%invariant_quad - metrics%invariant_diag_quad
         metrics%active_free_quad = metrics%active_quad - metrics%active_diag_quad
         metrics%actual_norm = metrics%actual_quad/sol_norm
         metrics%full_norm = metrics%full_quad/sol_norm
         metrics%invariant_norm = metrics%invariant_quad/sol_norm
         metrics%active_norm = metrics%active_quad/sol_norm
      END IF

   END FUNCTION qs_scf_kp_projector_trace_metrics

! **************************************************************************************************
!> \brief quadratic model uncertainty from a mismatched Direct trace curvature
!> \param trace_actual_quad ...
!> \param trace_model_quad ...
!> \param scale ...
!> \return ...
! **************************************************************************************************
   FUNCTION kpoint_ot_direct_trace_model_gap_drop(trace_actual_quad, trace_model_quad, scale) RESULT(drop)
      REAL(KIND=dp), INTENT(IN)                          :: trace_actual_quad, trace_model_quad, &
                                                            scale
      REAL(KIND=dp)                                      :: drop

      drop = 0.5_dp*scale*scale*ABS(trace_actual_quad - trace_model_quad)

   END FUNCTION kpoint_ot_direct_trace_model_gap_drop

! **************************************************************************************************
!> \brief accepted-history trust for a Direct trace mismatch audit
!> \param model_drop candidate Mermin drop before this trace-mismatch trust factor
!> \param trace_gap_drop trace-mismatch quadratic drop for the same step length
!> \param history_quality accepted Mermin-drop quality of this trace channel
!> \param samples number of accepted physical Direct quality samples
!> \return trust factor in [0,1], neutral until mature accepted history exists
! **************************************************************************************************
   FUNCTION kpoint_ot_direct_trace_mismatch_trust(model_drop, trace_gap_drop, history_quality, samples) &
      RESULT(trust_quality)
      REAL(KIND=dp), INTENT(IN)                          :: model_drop, trace_gap_drop, &
                                                            history_quality
      INTEGER, INTENT(IN)                                :: samples
      REAL(KIND=dp)                                      :: trust_quality

      REAL(KIND=dp)                                      :: history_weight

      trust_quality = 1.0_dp
      IF (samples < ot_kp_schur_projector_response_min_samples) RETURN
      IF (model_drop <= EPSILON(model_drop)) RETURN
      IF (trace_gap_drop <= EPSILON(trace_gap_drop)) RETURN

      history_weight = 1.0_dp - MIN(1.0_dp, MAX(0.0_dp, history_quality))
      IF (history_weight <= EPSILON(history_weight)) RETURN
      trust_quality = model_drop/(model_drop + history_weight*trace_gap_drop)
      trust_quality = MIN(1.0_dp, MAX(0.0_dp, trust_quality))

   END FUNCTION kpoint_ot_direct_trace_mismatch_trust

! **************************************************************************************************
!> \brief assemble CHC for the coupled fixed-N k-point OT energy subproblem
!> \param qs_ot_env ...
!> \param matrix_hc ...
!> \param matrix_hc_im ...
!> \param smear ...
! **************************************************************************************************
   SUBROUTINE qs_scf_loop_prepare_ot_kp_energy_chc(qs_ot_env, matrix_hc, matrix_hc_im, smear)

      TYPE(qs_ot_type)                                   :: qs_ot_env
      TYPE(dbcsr_type), POINTER                          :: matrix_hc, matrix_hc_im
      TYPE(smear_type), INTENT(IN)                       :: smear

      TYPE(dbcsr_type), POINTER                          :: b_im, b_re, c_im, c_re, chc_im, chc_re, &
                                                            tmp

      IF (.NOT. kpoint_ot_project_energy_subproblem(qs_ot_env, smear)) RETURN

      CPASSERT(qs_ot_env%has_complex_kpoint_state)
      CPASSERT(ASSOCIATED(matrix_hc))
      CPASSERT(ASSOCIATED(matrix_hc_im))
      CPASSERT(ASSOCIATED(qs_ot_env%rot_mat_chc))
      CPASSERT(ASSOCIATED(qs_ot_env%rot_mat_chc_im))
      CPASSERT(ASSOCIATED(qs_ot_env%rot_mat_u_im))
      CPASSERT(ASSOCIATED(qs_ot_env%matrix_ref_orth))
      CPASSERT(ASSOCIATED(qs_ot_env%matrix_ref_orth_im))

      c_re => qs_ot_env%matrix_ref_orth
      c_im => qs_ot_env%matrix_ref_orth_im
      chc_re => qs_ot_env%rot_mat_chc
      chc_im => qs_ot_env%rot_mat_chc_im
      b_re => qs_ot_env%matrix_buf1
      b_im => qs_ot_env%buf2_k_k_nosym
      tmp => qs_ot_env%buf3_k_k_nosym

      CALL qs_ot_generate_rotation_complex(qs_ot_env)

      ! K = C_orth(k)^H * H(k)C_current(k).
      CALL dbcsr_multiply('T', 'N', 1.0_dp, c_re, matrix_hc, 0.0_dp, chc_re)
      CALL dbcsr_multiply('T', 'N', 1.0_dp, c_im, matrix_hc_im, 0.0_dp, tmp)
      CALL dbcsr_add(chc_re, tmp, alpha_scalar=1.0_dp, beta_scalar=1.0_dp)

      CALL dbcsr_multiply('T', 'N', 1.0_dp, c_re, matrix_hc_im, 0.0_dp, chc_im)
      CALL dbcsr_multiply('T', 'N', 1.0_dp, c_im, matrix_hc, 0.0_dp, tmp)
      CALL dbcsr_add(chc_im, tmp, alpha_scalar=1.0_dp, beta_scalar=-1.0_dp)

      ! CHC = C_current(k)^H * H(k)C_current(k) = U(k)^H * K.
      CALL dbcsr_multiply('T', 'N', 1.0_dp, qs_ot_env%rot_mat_u, chc_re, 0.0_dp, b_re)
      CALL dbcsr_multiply('T', 'N', 1.0_dp, qs_ot_env%rot_mat_u_im, chc_im, 0.0_dp, tmp)
      CALL dbcsr_add(b_re, tmp, alpha_scalar=1.0_dp, beta_scalar=1.0_dp)

      CALL dbcsr_multiply('T', 'N', 1.0_dp, qs_ot_env%rot_mat_u, chc_im, 0.0_dp, b_im)
      CALL dbcsr_multiply('T', 'N', 1.0_dp, qs_ot_env%rot_mat_u_im, chc_re, 0.0_dp, tmp)
      CALL dbcsr_add(b_im, tmp, alpha_scalar=1.0_dp, beta_scalar=-1.0_dp)

      CALL dbcsr_copy(chc_re, b_re)
      CALL dbcsr_copy(chc_im, b_im)

   END SUBROUTINE qs_scf_loop_prepare_ot_kp_energy_chc

! **************************************************************************************************
!> \brief assemble final CHC after the accepted coupled k-point OT step
!> \param qs_ot_env ...
!> \param matrix_hc ...
!> \param matrix_hc_im ...
!> \param smear ...
! **************************************************************************************************
   SUBROUTINE qs_scf_loop_prepare_ot_kp_final_chc(qs_ot_env, matrix_hc, matrix_hc_im, smear)

      TYPE(qs_ot_type)                                   :: qs_ot_env
      TYPE(dbcsr_type)                                   :: matrix_hc, matrix_hc_im
      TYPE(smear_type), INTENT(IN)                       :: smear

      TYPE(dbcsr_type), POINTER                          :: b_im, b_re, c_im, c_re, chc_im, chc_re, &
                                                            tmp

      IF (.NOT. kpoint_ot_project_energy_subproblem(qs_ot_env, smear)) RETURN

      CPASSERT(qs_ot_env%has_complex_kpoint_state)
      CPASSERT(ASSOCIATED(qs_ot_env%rot_mat_chc))
      CPASSERT(ASSOCIATED(qs_ot_env%rot_mat_chc_im))
      CPASSERT(ASSOCIATED(qs_ot_env%rot_mat_u_im))
      CPASSERT(ASSOCIATED(qs_ot_env%matrix_ref_orth))
      CPASSERT(ASSOCIATED(qs_ot_env%matrix_ref_orth_im))

      c_re => qs_ot_env%matrix_ref_orth
      c_im => qs_ot_env%matrix_ref_orth_im
      chc_re => qs_ot_env%rot_mat_chc
      chc_im => qs_ot_env%rot_mat_chc_im
      b_re => qs_ot_env%matrix_buf1
      b_im => qs_ot_env%buf2_k_k_nosym
      tmp => qs_ot_env%buf3_k_k_nosym

      CALL qs_ot_generate_rotation_complex(qs_ot_env)

      ! K = C_orth(k)^H * H(k)C_current(k).
      CALL dbcsr_multiply('T', 'N', 1.0_dp, c_re, matrix_hc, 0.0_dp, chc_re)
      CALL dbcsr_multiply('T', 'N', 1.0_dp, c_im, matrix_hc_im, 0.0_dp, tmp)
      CALL dbcsr_add(chc_re, tmp, alpha_scalar=1.0_dp, beta_scalar=1.0_dp)

      CALL dbcsr_multiply('T', 'N', 1.0_dp, c_re, matrix_hc_im, 0.0_dp, chc_im)
      CALL dbcsr_multiply('T', 'N', 1.0_dp, c_im, matrix_hc, 0.0_dp, tmp)
      CALL dbcsr_add(chc_im, tmp, alpha_scalar=1.0_dp, beta_scalar=-1.0_dp)

      ! CHC = C_current(k)^H * H(k)C_current(k) = U(k)^H * K.
      CALL dbcsr_multiply('T', 'N', 1.0_dp, qs_ot_env%rot_mat_u, chc_re, 0.0_dp, b_re)
      CALL dbcsr_multiply('T', 'N', 1.0_dp, qs_ot_env%rot_mat_u_im, chc_im, 0.0_dp, tmp)
      CALL dbcsr_add(b_re, tmp, alpha_scalar=1.0_dp, beta_scalar=1.0_dp)

      CALL dbcsr_multiply('T', 'N', 1.0_dp, qs_ot_env%rot_mat_u, chc_im, 0.0_dp, b_im)
      CALL dbcsr_multiply('T', 'N', 1.0_dp, qs_ot_env%rot_mat_u_im, chc_re, 0.0_dp, tmp)
      CALL dbcsr_add(b_im, tmp, alpha_scalar=1.0_dp, beta_scalar=-1.0_dp)

      CALL dbcsr_copy(chc_re, b_re)
      CALL dbcsr_copy(chc_im, b_im)

   END SUBROUTINE qs_scf_loop_prepare_ot_kp_final_chc

! **************************************************************************************************
!> \brief debug-print diagnostic for k-point OT smearing quality
!> \param kpoints ...
!> \param local_ot_env ...
!> \param wkp ...
!> \param para_env_inter_kp ...
!> \param smear ...
! **************************************************************************************************
   SUBROUTINE qs_scf_loop_print_ot_kp_smearing(kpoints, local_ot_env, wkp, para_env_inter_kp, smear)

      TYPE(kpoint_type), POINTER                         :: kpoints
      TYPE(qs_ot_type), DIMENSION(:), POINTER            :: local_ot_env
      REAL(KIND=dp), DIMENSION(:), POINTER               :: wkp
      TYPE(mp_para_env_type), POINTER                    :: para_env_inter_kp
      TYPE(smear_type), INTENT(IN)                       :: smear

      INTEGER                                            :: ikpoint, imo, ispin, local_channel, &
                                                            local_kpoint, nmo, nspin
      REAL(KIND=dp) :: density_projector_fraction, density_projector_model_delta, &
         density_projector_weight, fractional_weight, kTS, max_partial, maxocc, min_fermi_dist, &
         min_trust_scale, mu, occ_fraction, occ_tail, residual_delta, sigma, tether_energy, &
         tether_grad_max, tether_strength_max, trusted_step_max, weighted_electrons
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: spin_fractional_weight, spin_kTS, &
                                                            spin_max_partial, spin_min_fermi_dist, &
                                                            spin_mu, spin_weighted_electrons
      REAL(KIND=dp), DIMENSION(:), POINTER               :: eigenvalues, occupation_numbers
      TYPE(cp_logger_type), POINTER                      :: logger
      TYPE(kpoint_env_type), POINTER                     :: kp

      logger => cp_get_default_logger()
      IF (logger%iter_info%print_level < debug_print_level) RETURN

      fractional_weight = 0.0_dp
      weighted_electrons = 0.0_dp
      max_partial = 0.0_dp
      min_fermi_dist = HUGE(1.0_dp)
      kTS = 0.0_dp
      mu = 0.0_dp
      residual_delta = 0.0_dp
      tether_energy = 0.0_dp
      tether_grad_max = 0.0_dp
      tether_strength_max = 0.0_dp
      trusted_step_max = 0.0_dp
      min_trust_scale = 1.0_dp

      kp => kpoints%kp_env(1)%kpoint_env
      nspin = SIZE(kp%mos, 2)
      ALLOCATE (spin_fractional_weight(nspin), spin_kTS(nspin), spin_max_partial(nspin), &
                spin_min_fermi_dist(nspin), spin_mu(nspin), spin_weighted_electrons(nspin))
      spin_fractional_weight = 0.0_dp
      spin_kTS = 0.0_dp
      spin_max_partial = 0.0_dp
      spin_min_fermi_dist = HUGE(1.0_dp)
      spin_mu = 0.0_dp
      spin_weighted_electrons = 0.0_dp
      DO ispin = 1, nspin
         spin_mu(ispin) = kp%mos(1, ispin)%mu
         mu = mu + spin_mu(ispin)
      END DO
      IF (smear%method /= smear_fermi_dirac) THEN
         DO ispin = 1, nspin
            spin_kTS(ispin) = kp%mos(1, ispin)%kTS
         END DO
      END IF
      mu = mu/REAL(nspin, KIND=dp)
      sigma = kpoint_ot_smearing_width(smear)

      DO local_kpoint = 1, SIZE(kpoints%kp_env)
         kp => kpoints%kp_env(local_kpoint)%kpoint_env
         ikpoint = kp%nkpoint
         DO ispin = 1, nspin
            CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, nmo=nmo, eigenvalues=eigenvalues, &
                            occupation_numbers=occupation_numbers)
            DO imo = 1, nmo
               occ_tail = MAX(0.0_dp, MIN(occupation_numbers(imo), maxocc - occupation_numbers(imo)))
               max_partial = MAX(max_partial, occ_tail)
               fractional_weight = fractional_weight + wkp(ikpoint)*occ_tail
               weighted_electrons = weighted_electrons + wkp(ikpoint)*occupation_numbers(imo)
               min_fermi_dist = MIN(min_fermi_dist, ABS(eigenvalues(imo) - kp%mos(1, ispin)%mu))
               spin_max_partial(ispin) = MAX(spin_max_partial(ispin), occ_tail)
               spin_fractional_weight(ispin) = spin_fractional_weight(ispin) + wkp(ikpoint)*occ_tail
               spin_weighted_electrons(ispin) = &
                  spin_weighted_electrons(ispin) + wkp(ikpoint)*occupation_numbers(imo)
               spin_min_fermi_dist(ispin) = &
                  MIN(spin_min_fermi_dist(ispin), ABS(eigenvalues(imo) - kp%mos(1, ispin)%mu))
               IF (smear%method == smear_fermi_dirac .AND. sigma > 1.0E-14_dp .AND. &
                   maxocc > EPSILON(maxocc)) THEN
                  occ_fraction = MAX(0.0_dp, MIN(1.0_dp, occupation_numbers(imo)/maxocc))
                  IF (occ_fraction > 0.0_dp .AND. occ_fraction < 1.0_dp) &
                     spin_kTS(ispin) = spin_kTS(ispin) + wkp(ikpoint)* &
                                       qs_scf_kp_fermi_entropy_state(occupation_numbers(imo), &
                                                                     maxocc, sigma)
               END IF
            END DO
         END DO
      END DO

      CALL para_env_inter_kp%sum(fractional_weight)
      CALL para_env_inter_kp%sum(weighted_electrons)
      CALL para_env_inter_kp%max(max_partial)
      CALL para_env_inter_kp%min(min_fermi_dist)
      DO ispin = 1, nspin
         CALL para_env_inter_kp%sum(spin_fractional_weight(ispin))
         CALL para_env_inter_kp%sum(spin_weighted_electrons(ispin))
         CALL para_env_inter_kp%max(spin_max_partial(ispin))
         CALL para_env_inter_kp%min(spin_min_fermi_dist(ispin))
         IF (smear%method == smear_fermi_dirac) CALL para_env_inter_kp%sum(spin_kTS(ispin))
      END DO
      kTS = SUM(spin_kTS)

      DO local_channel = 1, SIZE(local_ot_env)
         residual_delta = MAX(residual_delta, local_ot_env(local_channel)%delta)
         tether_energy = tether_energy + local_ot_env(local_channel)%canonical_tether_energy
         tether_grad_max = MAX(tether_grad_max, local_ot_env(local_channel)%canonical_tether_grad_max)
         tether_strength_max = MAX(tether_strength_max, &
                                   local_ot_env(local_channel)%canonical_tether_strength)
         trusted_step_max = MAX(trusted_step_max, local_ot_env(local_channel)%ener_x_trusted_step_max)
         IF (local_ot_env(local_channel)%ener_x_trust_radius > 0.0_dp) &
            min_trust_scale = MIN(min_trust_scale, local_ot_env(local_channel)%ener_x_trust_scale)
      END DO
      CALL para_env_inter_kp%max(residual_delta)
      CALL para_env_inter_kp%sum(tether_energy)
      CALL para_env_inter_kp%max(tether_grad_max)
      CALL para_env_inter_kp%max(tether_strength_max)
      CALL para_env_inter_kp%max(trusted_step_max)
      CALL para_env_inter_kp%min(min_trust_scale)

      density_projector_model_delta = &
         kpoint_ot_canonical_density_projector_control_delta(local_ot_env(1), residual_delta)
      density_projector_weight = kpoint_ot_canonical_density_projector_weight(density_projector_model_delta)
      density_projector_fraction = 0.0_dp
      IF (ot_kp_canonical_density_max_weight > 0.0_dp) &
         density_projector_fraction = density_projector_weight/ot_kp_canonical_density_max_weight

      IF (logger%para_env%is_source()) THEN
         WRITE (cp_logger_get_default_unit_nr(logger), '(A,6(1X,ES16.8))') &
            " OT k-point smearing kTS mu weighted_N frac_weight max_partial min_abs_eps_mu:", &
            kTS, mu, weighted_electrons, fractional_weight, max_partial, min_fermi_dist
         IF (nspin > 1) THEN
            DO ispin = 1, nspin
               WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I2,6(1X,ES16.8))') &
                  " OT k-point smearing spin kTS mu weighted_N frac_weight max_partial min_abs_eps_mu:", &
                  ispin, spin_kTS(ispin), spin_mu(ispin), spin_weighted_electrons(ispin), &
                  spin_fractional_weight(ispin), spin_max_partial(ispin), spin_min_fermi_dist(ispin)
            END DO
         END IF
         WRITE (cp_logger_get_default_unit_nr(logger), '(A,9(1X,ES16.8),1X,I5)') &
            " OT k-point residual model delta pdelta dproj frac trusted scale tether_E tether_g tether_s ls:", &
            residual_delta, density_projector_model_delta, density_projector_weight, &
            density_projector_fraction, trusted_step_max, min_trust_scale, tether_energy, &
            tether_grad_max, tether_strength_max, local_ot_env(1)%line_search_count
      END IF

      DEALLOCATE (spin_fractional_weight, spin_kTS, spin_max_partial, spin_min_fermi_dist, &
                  spin_mu, spin_weighted_electrons)

   END SUBROUTINE qs_scf_loop_print_ot_kp_smearing

! **************************************************************************************************
!> \brief one-state Fermi-Dirac contribution to the Mermin smearing correction
!> \param occupation orbital occupation in [0,maxocc]
!> \param maxocc maximum orbital occupation
!> \param sigma electronic temperature in Hartree
!> \return negative T*S contribution for one state before its k-point weight
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_fermi_entropy_state(occupation, maxocc, sigma) RESULT(kTS)
      REAL(KIND=dp), INTENT(IN)                          :: occupation, maxocc, sigma
      REAL(KIND=dp)                                      :: kTS

      REAL(KIND=dp)                                      :: occ_fraction

      kTS = 0.0_dp
      IF (maxocc <= EPSILON(maxocc) .OR. sigma <= 1.0E-14_dp) RETURN
      occ_fraction = MAX(0.0_dp, MIN(1.0_dp, occupation/maxocc))
      IF (occ_fraction <= 0.0_dp .OR. occ_fraction >= 1.0_dp) RETURN
      kTS = sigma*maxocc*(occ_fraction*LOG(occ_fraction) + &
                          (1.0_dp - occ_fraction)*LOG(1.0_dp - occ_fraction))

   END FUNCTION qs_scf_kp_fermi_entropy_state

! **************************************************************************************************
!> \brief prepare per-channel Fermi-window trust data for k-point OT energy variables
!> \param kpoints ...
!> \param local_ot_env ...
!> \param first_channel ...
!> \param nspin_ot ...
!> \param wkp ...
!> \param para_env_inter_kp ...
!> \param smear ...
!> \param eps_scf ...
!> \param trial_eigenvalues ...
!> \param trial_occupation ...
!> \param trial_mu ...
! **************************************************************************************************
   SUBROUTINE qs_scf_loop_prepare_ot_kp_energy_trust(kpoints, local_ot_env, first_channel, nspin_ot, &
                                                     wkp, para_env_inter_kp, smear, eps_scf, &
                                                     trial_eigenvalues, trial_occupation, trial_mu)

      TYPE(kpoint_type), POINTER                         :: kpoints
      TYPE(qs_ot_type), DIMENSION(:), POINTER            :: local_ot_env
      INTEGER, INTENT(IN)                                :: first_channel, nspin_ot
      REAL(KIND=dp), DIMENSION(:), POINTER               :: wkp
      TYPE(mp_para_env_type), POINTER                    :: para_env_inter_kp
      TYPE(smear_type), INTENT(IN)                       :: smear
      REAL(KIND=dp), INTENT(IN)                          :: eps_scf
      REAL(KIND=dp), DIMENSION(:, :, :), INTENT(IN)      :: trial_eigenvalues, trial_occupation
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: trial_mu

      REAL(KIND=dp), PARAMETER                           :: edge_window_factor = 8.0_dp, &
                                                            partial_tol = 1.0E-8_dp, &
                                                            trust_radius_factor = 4.0_dp

      INTEGER                                            :: calibration_samples, ikpoint, imo, &
                                                            ispin, local_channel, local_kpoint, nmo
      LOGICAL                                            :: active, fermi_guard_active, &
                                                            has_trust_weight
      REAL(KIND=dp) :: edge_window, fermi_guard_anchor, frac_weight, gvalue, maxocc, &
         min_abs_eps_mu, mu, occ_tail, rayleigh_edge_gap, rayleigh_gap, residual_delta, sigma, &
         trust_radius
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: rayleigh_diag
      TYPE(kpoint_env_type), POINTER                     :: kp

      DO local_channel = 1, SIZE(local_ot_env)
         local_ot_env(local_channel)%ener_x_trust_radius = -1.0_dp
         local_ot_env(local_channel)%ener_x_trust_edge_window = -1.0_dp
         local_ot_env(local_channel)%ener_x_trust_mu = 0.0_dp
         local_ot_env(local_channel)%ener_x_trust_sigma = 0.0_dp
         local_ot_env(local_channel)%ener_x_trust_frac_weight = 0.0_dp
         local_ot_env(local_channel)%ener_x_trust_entropy = 0.0_dp
         local_ot_env(local_channel)%ener_x_trust_min_abs_eps_mu = HUGE(1.0_dp)
         local_ot_env(local_channel)%ener_x_trust_rayleigh_gap = 0.0_dp
         local_ot_env(local_channel)%ener_x_trust_rayleigh_edge_gap = 0.0_dp
         local_ot_env(local_channel)%ener_x_step_max = 0.0_dp
         local_ot_env(local_channel)%ener_x_trusted_step_max = 0.0_dp
         local_ot_env(local_channel)%ener_x_trust_scale = 1.0_dp
         local_ot_env(local_channel)%ener_x_fermi_guard_active = .FALSE.
         local_ot_env(local_channel)%ener_x_fermi_guard_anchor = -1.0_dp
         IF (ASSOCIATED(local_ot_env(local_channel)%ener_x_trust_weight)) &
            local_ot_env(local_channel)%ener_x_trust_weight(:) = 0.0_dp
      END DO

      IF (.NOT. local_ot_env(1)%settings%do_ener) RETURN
      IF (smear%method /= smear_gaussian .AND. &
          .NOT. qs_ot_occupation_preconditioner_active(local_ot_env(1))) RETURN
      IF (.NOT. smear%do_smear .OR. .NOT. kpoint_ot_monotone_smearing(smear%method)) RETURN

      sigma = kpoint_ot_smearing_width(smear)
      IF (sigma <= 1.0E-14_dp) RETURN
      trust_radius = trust_radius_factor*sigma
      edge_window = edge_window_factor*sigma
      fermi_guard_anchor = kpoint_ot_fermi_window_anchor(sigma, smear%method)
      calibration_samples = local_ot_env(1)%mermin_ls_accepted_quality_samples
      CALL para_env_inter_kp%min(calibration_samples)
      residual_delta = 0.0_dp
      DO local_channel = 1, SIZE(local_ot_env)
         residual_delta = MAX(residual_delta, qs_scf_kp_fermi_guard_control_delta( &
                              local_ot_env(local_channel)%delta, &
                              local_ot_env(local_channel)%kpoint_raw_delta))
      END DO
      CALL para_env_inter_kp%max(residual_delta)
      fermi_guard_active = .NOT. qs_scf_kp_fermi_guard_release_ready( &
                           calibration_samples, residual_delta, eps_scf)

      DO local_channel = 1, SIZE(local_ot_env)
         local_ot_env(local_channel)%ener_x_fermi_guard_active = fermi_guard_active
         local_ot_env(local_channel)%ener_x_fermi_guard_anchor = fermi_guard_anchor
         IF (.NOT. fermi_guard_active) &
            local_ot_env(local_channel)%ener_x_fermi_frontier_armed = .FALSE.
      END DO

      DO local_kpoint = 1, SIZE(kpoints%kp_env)
         kp => kpoints%kp_env(local_kpoint)%kpoint_env
         ikpoint = kp%nkpoint
         DO ispin = 1, nspin_ot
            local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
            CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, nmo=nmo)
            mu = trial_mu(ispin)
            has_trust_weight = .FALSE.
            IF (ASSOCIATED(local_ot_env(local_channel)%ener_x_trust_weight)) &
               has_trust_weight = SIZE(local_ot_env(local_channel)%ener_x_trust_weight) >= nmo
            local_ot_env(local_channel)%ener_x_trust_radius = trust_radius
            local_ot_env(local_channel)%ener_x_trust_edge_window = edge_window
            local_ot_env(local_channel)%ener_x_trust_mu = mu
            local_ot_env(local_channel)%ener_x_trust_sigma = sigma
            local_ot_env(local_channel)%ener_x_trust_entropy = kp%mos(1, ispin)%kTS
            frac_weight = 0.0_dp
            min_abs_eps_mu = HUGE(1.0_dp)
            rayleigh_gap = 0.0_dp
            rayleigh_edge_gap = 0.0_dp
            ALLOCATE (rayleigh_diag(nmo))
            CALL get_replicated_kpoint_ot_diag(local_ot_env(local_channel)%rot_mat_chc, &
                                               local_ot_env(local_channel), rayleigh_diag)

            DO imo = 1, nmo
               occ_tail = MAX(0.0_dp, MIN(trial_occupation(imo, ikpoint, ispin), &
                                          maxocc - trial_occupation(imo, ikpoint, ispin)))
               frac_weight = frac_weight + wkp(ikpoint)*occ_tail
               min_abs_eps_mu = MIN(min_abs_eps_mu, ABS(trial_eigenvalues(imo, ikpoint, ispin) - mu))
               rayleigh_gap = MAX(rayleigh_gap, ABS(rayleigh_diag(imo) - local_ot_env(local_channel)%ener_x(imo)))
               active = occ_tail > partial_tol*MAX(maxocc, 1.0_dp) .OR. &
                        ABS(trial_eigenvalues(imo, ikpoint, ispin) - mu) < edge_window
               IF (active) rayleigh_edge_gap = MAX(rayleigh_edge_gap, &
                                                   ABS(rayleigh_diag(imo) - local_ot_env(local_channel)%ener_x(imo)))
               IF (active .AND. has_trust_weight) THEN
                  gvalue = SmearingDerivative(trial_occupation(imo, ikpoint, ispin), &
                                              trial_eigenvalues(imo, ikpoint, ispin), mu, &
                                              sigma, maxocc, smear%method)
                  local_ot_env(local_channel)%ener_x_trust_weight(imo) = wkp(ikpoint)*MAX(gvalue, 0.0_dp)
               END IF
            END DO
            DEALLOCATE (rayleigh_diag)
            local_ot_env(local_channel)%ener_x_trust_frac_weight = frac_weight
            local_ot_env(local_channel)%ener_x_trust_min_abs_eps_mu = min_abs_eps_mu
            local_ot_env(local_channel)%ener_x_trust_rayleigh_gap = rayleigh_gap
            local_ot_env(local_channel)%ener_x_trust_rayleigh_edge_gap = rayleigh_edge_gap
            local_ot_env(local_channel)%ener_x_step_max = rayleigh_gap
            local_ot_env(local_channel)%ener_x_trusted_step_max = rayleigh_edge_gap
            IF (rayleigh_edge_gap > trust_radius .AND. trust_radius > EPSILON(trust_radius)) THEN
               local_ot_env(local_channel)%ener_x_trust_scale = trust_radius/rayleigh_edge_gap
               local_ot_env(local_channel)%ener_x_trusted_step_max = trust_radius
            END IF
         END DO
      END DO

   END SUBROUTINE qs_scf_loop_prepare_ot_kp_energy_trust

! **************************************************************************************************
!> \brief active frontier response for the k-point OT canonical tether
!> \param occupation ...
!> \param eigenvalue ...
!> \param mu ...
!> \param sigma ...
!> \param maxocc ...
!> \param method ...
!> \return ...
! **************************************************************************************************
   FUNCTION kpoint_ot_canonical_tether_response(occupation, eigenvalue, mu, sigma, maxocc, method) RESULT(response)
      REAL(KIND=dp), INTENT(IN)                          :: occupation, eigenvalue, mu, sigma, maxocc
      INTEGER, INTENT(IN)                                :: method
      REAL(KIND=dp)                                      :: response

      REAL(KIND=dp), PARAMETER :: edge_window_factor = 8.0_dp, partial_tol = 1.0E-8_dp, &
         response_floor_fraction = 4.0E-2_dp

      LOGICAL                                            :: active
      REAL(KIND=dp)                                      :: edge_window, gvalue, occ_tail, &
                                                            response_floor, tail_scale

      response = 0.0_dp
      IF (sigma <= 1.0E-14_dp .OR. maxocc <= EPSILON(maxocc)) RETURN

      edge_window = edge_window_factor*sigma
      occ_tail = MAX(0.0_dp, MIN(occupation, maxocc - occupation))
      active = occ_tail > partial_tol*MAX(maxocc, 1.0_dp) .OR. ABS(eigenvalue - mu) < edge_window
      IF (.NOT. active) RETURN

      gvalue = SmearingDerivative(occupation, eigenvalue, mu, sigma, maxocc, method)
      response_floor = response_floor_fraction* &
                       kpoint_ot_smearing_peak_response(sigma, maxocc, method)
      tail_scale = occ_tail/MAX(ot_kp_fermi_window_tail_fraction*maxocc, EPSILON(maxocc))
      response_floor = response_floor*MIN(1.0_dp, MAX(0.0_dp, tail_scale))
      response = MAX(gvalue, response_floor)

   END FUNCTION kpoint_ot_canonical_tether_response

! **************************************************************************************************
!> \brief release the auxiliary canonical tether as the exact fixed-N density residual converges
!> \param density_delta canonical-density stationarity residual
!> \param density_ready whether density_delta is complete
!> \param eps_scf requested SCF threshold
!> \return smooth tether scale between the exact tail (zero) and bootstrap region (one)
! **************************************************************************************************
   PURE FUNCTION qs_scf_kp_canonical_tether_tail_scale(density_delta, density_ready, eps_scf) &
      RESULT(scale)
      REAL(KIND=dp), INTENT(IN)                          :: density_delta
      LOGICAL, INTENT(IN)                                :: density_ready
      REAL(KIND=dp), INTENT(IN)                          :: eps_scf
      REAL(KIND=dp)                                      :: scale

      REAL(KIND=dp)                                      :: full_delta

      scale = 1.0_dp
      IF (.NOT. density_ready .OR. eps_scf <= 0.0_dp) RETURN
      full_delta = ot_kp_canonical_tether_release_full_eps_factor*eps_scf
      scale = (MAX(0.0_dp, density_delta) - eps_scf)/MAX(EPSILON(1.0_dp), full_delta - eps_scf)
      scale = MIN(1.0_dp, MAX(0.0_dp, scale))

   END FUNCTION qs_scf_kp_canonical_tether_tail_scale

! **************************************************************************************************
!> \brief adaptive prefactor for the k-point OT canonical tether
!> \param qs_ot_env ...
!> \param edge_gap ...
!> \param sigma ...
!> \return ...
! **************************************************************************************************
   FUNCTION kpoint_ot_canonical_tether_strength(qs_ot_env, edge_gap, sigma) RESULT(strength)
      TYPE(qs_ot_type), INTENT(IN)                       :: qs_ot_env
      REAL(KIND=dp), INTENT(IN)                          :: edge_gap, sigma
      REAL(KIND=dp)                                      :: strength

      REAL(KIND=dp)                                      :: base_strength, gap_scale, max_strength, &
                                                            tail_scale

      strength = 0.0_dp
      IF (.NOT. qs_ot_env%settings%canonical_tether) RETURN

      base_strength = qs_ot_env%settings%canonical_tether_strength
      max_strength = qs_ot_env%settings%canonical_tether_max_strength
      IF (base_strength <= 0.0_dp .OR. max_strength <= 0.0_dp) RETURN

      strength = MIN(base_strength, max_strength)
      IF (.NOT. qs_ot_env%settings%canonical_tether_adaptive) RETURN

      ! The tether is part of the local Mermin model.  Determine it at the
      ! accepted-gradient point and keep it fixed for every trial point in the
      ! ensuing line search.
      IF (qs_ot_env%line_search_count > 0) THEN
         strength = MIN(max_strength, MAX(0.0_dp, qs_ot_env%canonical_tether_strength))
         RETURN
      END IF
      IF (sigma > 1.0E-14_dp .AND. edge_gap > 0.0_dp) THEN
         gap_scale = SQRT(MAX(1.0_dp, edge_gap/MAX(16.0_dp*sigma, EPSILON(sigma))))
         strength = MIN(max_strength, base_strength*gap_scale)
      END IF
      tail_scale = qs_scf_kp_canonical_tether_tail_scale( &
                   qs_ot_env%kpoint_density_stationarity_delta, &
                   qs_ot_env%kpoint_density_stationarity_ready, qs_ot_env%kpoint_eps_scf)
      strength = tail_scale*strength

   END FUNCTION kpoint_ot_canonical_tether_strength

! **************************************************************************************************
!> \brief response-weighted frontier tether for k-point OT auxiliary energies
!> \param occupation ...
!> \param eigenvalue ...
!> \param mu ...
!> \param sigma ...
!> \param maxocc ...
!> \param method ...
!> \param kpoint_weight ...
!> \param tether_strength ...
!> \return ...
! **************************************************************************************************
   FUNCTION kpoint_ot_canonical_tether_weight(occupation, eigenvalue, mu, sigma, maxocc, method, &
                                              kpoint_weight, tether_strength) RESULT(weight)
      REAL(KIND=dp), INTENT(IN)                          :: occupation, eigenvalue, mu, sigma, maxocc
      INTEGER, INTENT(IN)                                :: method
      REAL(KIND=dp), INTENT(IN)                          :: kpoint_weight, tether_strength
      REAL(KIND=dp)                                      :: weight

      weight = tether_strength*kpoint_weight* &
               kpoint_ot_canonical_tether_response(occupation, eigenvalue, mu, sigma, maxocc, method)

   END FUNCTION kpoint_ot_canonical_tether_weight

! **************************************************************************************************
!> \brief gather a distributed k-point OT matrix diagonal on its local subgroup
!> \param matrix ...
!> \param qs_ot_env ...
!> \param diagonal ...
! **************************************************************************************************
   SUBROUTINE get_replicated_kpoint_ot_diag(matrix, qs_ot_env, diagonal)
      TYPE(dbcsr_type), INTENT(IN)                       :: matrix
      TYPE(qs_ot_type), INTENT(IN)                       :: qs_ot_env
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: diagonal

      CALL dbcsr_get_diag(matrix, diagonal)
      IF (ASSOCIATED(qs_ot_env%para_env)) CALL qs_ot_env%para_env%sum(diagonal)

   END SUBROUTINE get_replicated_kpoint_ot_diag

! **************************************************************************************************
!> \brief prepare complex rotation and band-energy gradients for one local k-point OT channel
!> \param qs_ot_env ...
!> \param matrix_hc ...
!> \param matrix_hc_im ...
!> \param occupation_numbers ...
!> \param eigenvalues ...
!> \param maxocc ...
!> \param mu ...
!> \param kpoint_weight ...
!> \param smear ...
!> \param nondiag_energy ...
! **************************************************************************************************
   SUBROUTINE qs_scf_loop_prepare_ot_kp_channel_gradient(qs_ot_env, matrix_hc, matrix_hc_im, &
                                                         occupation_numbers, eigenvalues, maxocc, mu, &
                                                         kpoint_weight, smear, nondiag_energy)

      TYPE(qs_ot_type)                                   :: qs_ot_env
      TYPE(dbcsr_type), POINTER                          :: matrix_hc, matrix_hc_im
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: occupation_numbers, eigenvalues
      REAL(KIND=dp), INTENT(IN)                          :: maxocc, mu, kpoint_weight
      TYPE(smear_type), INTENT(IN)                       :: smear
      REAL(KIND=dp), INTENT(INOUT)                       :: nondiag_energy

      INTEGER                                            :: imo, nmo
      LOGICAL                                            :: project_energy_subproblem
      REAL(KIND=dp) :: canonical_tether_energy, delta, nondiag_trace_im, nondiag_trace_re, &
         nondiag_weight, rayleigh_edge_gap, sigma, tether_response, tether_shift, tether_strength, &
         tether_weight, tether_weight_sum
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: diagonal, orbital_scaling_factor, &
                                                            tether_diag
      TYPE(dbcsr_type), POINTER                          :: b_im, b_re, c_im, c_re, chc_im, chc_re, &
                                                            tmp, tmp2

      IF (.NOT. qs_ot_env%settings%do_rotation) RETURN

      CPASSERT(qs_ot_env%has_complex_kpoint_state)
      CPASSERT(ASSOCIATED(matrix_hc))
      CPASSERT(ASSOCIATED(matrix_hc_im))
      CPASSERT(ASSOCIATED(qs_ot_env%rot_mat_chc))
      CPASSERT(ASSOCIATED(qs_ot_env%rot_mat_chc_im))
      CPASSERT(ASSOCIATED(qs_ot_env%rot_mat_u_im))
      CPASSERT(ASSOCIATED(qs_ot_env%matrix_ref_orth))
      CPASSERT(ASSOCIATED(qs_ot_env%matrix_ref_orth_im))

      c_re => qs_ot_env%matrix_ref_orth
      c_im => qs_ot_env%matrix_ref_orth_im
      chc_re => qs_ot_env%rot_mat_chc
      chc_im => qs_ot_env%rot_mat_chc_im
      b_re => qs_ot_env%matrix_buf1
      b_im => qs_ot_env%buf2_k_k_nosym
      tmp => qs_ot_env%buf3_k_k_nosym
      tmp2 => qs_ot_env%buf4_k_k_nosym
      project_energy_subproblem = kpoint_ot_project_energy_subproblem(qs_ot_env, smear)

      CALL qs_ot_generate_rotation_complex(qs_ot_env)

      ! K = C_orth(k)^H * H(k)C_current(k).
      CALL dbcsr_multiply('T', 'N', 1.0_dp, c_re, matrix_hc, 0.0_dp, chc_re)
      CALL dbcsr_multiply('T', 'N', 1.0_dp, c_im, matrix_hc_im, 0.0_dp, tmp)
      CALL dbcsr_add(chc_re, tmp, alpha_scalar=1.0_dp, beta_scalar=1.0_dp)

      CALL dbcsr_multiply('T', 'N', 1.0_dp, c_re, matrix_hc_im, 0.0_dp, chc_im)
      CALL dbcsr_multiply('T', 'N', 1.0_dp, c_im, matrix_hc, 0.0_dp, tmp)
      CALL dbcsr_add(chc_im, tmp, alpha_scalar=1.0_dp, beta_scalar=-1.0_dp)

      ! CHC = C_current(k)^H * H(k)C_current(k) = U(k)^H * K.
      CALL dbcsr_multiply('T', 'N', 1.0_dp, qs_ot_env%rot_mat_u, chc_re, 0.0_dp, b_re)
      CALL dbcsr_multiply('T', 'N', 1.0_dp, qs_ot_env%rot_mat_u_im, chc_im, 0.0_dp, tmp)
      CALL dbcsr_add(b_re, tmp, alpha_scalar=1.0_dp, beta_scalar=1.0_dp)

      CALL dbcsr_multiply('T', 'N', 1.0_dp, qs_ot_env%rot_mat_u, chc_im, 0.0_dp, b_im)
      CALL dbcsr_multiply('T', 'N', 1.0_dp, qs_ot_env%rot_mat_u_im, chc_re, 0.0_dp, tmp)
      CALL dbcsr_add(b_im, tmp, alpha_scalar=1.0_dp, beta_scalar=-1.0_dp)

      CALL dbcsr_copy(chc_re, b_re)
      CALL dbcsr_copy(chc_im, b_im)

      IF (qs_ot_env%settings%do_ener) THEN
         CALL get_replicated_kpoint_ot_diag(chc_re, qs_ot_env, qs_ot_env%ener_gx)
      END IF

      ! At fixed auxiliary energies the Mermin occupations belong to the
      ! current orbital labels.  The exact partial derivative is therefore
      ! H*C*diag(2*w_k*f).  A spectral V*diag(f)*V^H projector without the
      ! matching finite orbital transport is a different functional and must
      ! remain a Hessian/shadow model, never part of the production gradient.
      CALL dbcsr_copy(b_re, chc_re)
      CALL dbcsr_copy(b_im, chc_im)
      ALLOCATE (orbital_scaling_factor(SIZE(occupation_numbers)))
      orbital_scaling_factor(:) = 2.0_dp*kpoint_weight*occupation_numbers(:)
      CALL dbcsr_scale_by_vector(b_re, alpha=orbital_scaling_factor, side='right')
      CALL dbcsr_scale_by_vector(b_im, alpha=orbital_scaling_factor, side='right')
      DEALLOCATE (orbital_scaling_factor)

      ! dF/dU for the complex occupied-space rotation U(k).  The finite anti-Hermitian
      ! Frechet derivative below consumes the complete real/imaginary payload.
      CALL dbcsr_multiply('N', 'N', 1.0_dp, qs_ot_env%rot_mat_u, b_re, 0.0_dp, qs_ot_env%rot_mat_dedu)
      IF (ASSOCIATED(qs_ot_env%rot_mat_u_im)) THEN
         CALL dbcsr_multiply('N', 'N', 1.0_dp, qs_ot_env%rot_mat_u_im, b_im, 0.0_dp, tmp)
         CALL dbcsr_add(qs_ot_env%rot_mat_dedu, tmp, alpha_scalar=1.0_dp, beta_scalar=-1.0_dp)

         CALL dbcsr_multiply('N', 'N', 1.0_dp, qs_ot_env%rot_mat_u, b_im, 0.0_dp, qs_ot_env%rot_mat_dedu_im)
         CALL dbcsr_multiply('N', 'N', 1.0_dp, qs_ot_env%rot_mat_u_im, b_re, 0.0_dp, tmp2)
         CALL dbcsr_add(qs_ot_env%rot_mat_dedu_im, tmp2, alpha_scalar=1.0_dp, beta_scalar=1.0_dp)
      END IF

      qs_ot_env%canonical_tether_energy = 0.0_dp
      qs_ot_env%canonical_tether_weight_sum = 0.0_dp
      qs_ot_env%canonical_tether_shift = 0.0_dp
      qs_ot_env%canonical_tether_grad_max = 0.0_dp

      IF (qs_ot_env%settings%do_ener .AND. &
          qs_ot_occupation_preconditioner_active(qs_ot_env) .AND. &
          qs_ot_env%settings%canonical_tether .AND. &
          .NOT. project_energy_subproblem .AND. &
          smear%do_smear .AND. kpoint_ot_monotone_smearing(smear%method)) THEN
         sigma = kpoint_ot_smearing_width(smear)
         nmo = SIZE(qs_ot_env%ener_x)
         IF (sigma > 1.0E-14_dp .AND. SIZE(eigenvalues) >= nmo .AND. SIZE(occupation_numbers) >= nmo) THEN
            ALLOCATE (diagonal(nmo), tether_diag(nmo))
            CALL get_replicated_kpoint_ot_diag(chc_re, qs_ot_env, diagonal)
            tether_diag(:) = 0.0_dp
            tether_shift = 0.0_dp
            rayleigh_edge_gap = 0.0_dp
            tether_weight_sum = 0.0_dp
            DO imo = 1, nmo
               tether_response = kpoint_ot_canonical_tether_response(occupation_numbers(imo), eigenvalues(imo), &
                                                                     mu, sigma, maxocc, smear%method)
               IF (tether_response > 0.0_dp) &
                  rayleigh_edge_gap = MAX(rayleigh_edge_gap, ABS(diagonal(imo) - qs_ot_env%ener_x(imo)))
            END DO
            tether_strength = kpoint_ot_canonical_tether_strength(qs_ot_env, rayleigh_edge_gap, sigma)
            DO imo = 1, nmo
               tether_weight = kpoint_ot_canonical_tether_weight(occupation_numbers(imo), eigenvalues(imo), &
                                                                 mu, sigma, maxocc, smear%method, kpoint_weight, &
                                                                 tether_strength)
               IF (tether_weight <= 0.0_dp) CYCLE
               delta = diagonal(imo) - qs_ot_env%ener_x(imo)
               tether_shift = tether_shift + tether_weight*delta
               tether_weight_sum = tether_weight_sum + tether_weight
            END DO
            IF (tether_weight_sum > EPSILON(tether_weight_sum)) THEN
               tether_shift = tether_shift/tether_weight_sum
               canonical_tether_energy = 0.0_dp
               DO imo = 1, nmo
                  tether_weight = kpoint_ot_canonical_tether_weight(occupation_numbers(imo), eigenvalues(imo), &
                                                                    mu, sigma, maxocc, smear%method, kpoint_weight, &
                                                                    tether_strength)
                  IF (tether_weight <= 0.0_dp) CYCLE
                  delta = diagonal(imo) - qs_ot_env%ener_x(imo) - tether_shift
                  tether_diag(imo) = tether_weight*delta
                  canonical_tether_energy = canonical_tether_energy + 0.5_dp*tether_weight*delta**2
               END DO
               nondiag_energy = nondiag_energy + canonical_tether_energy
               qs_ot_env%canonical_tether_energy = canonical_tether_energy
               qs_ot_env%canonical_tether_strength = tether_strength
               qs_ot_env%canonical_tether_weight_sum = tether_weight_sum
               qs_ot_env%canonical_tether_shift = tether_shift
               qs_ot_env%canonical_tether_grad_max = MAXVAL(ABS(tether_diag))

               CALL dbcsr_copy(b_re, chc_re)
               CALL dbcsr_set(b_re, 0.0_dp)
               CALL dbcsr_set_diag(b_re, tether_diag)
               CALL dbcsr_multiply('N', 'N', 1.0_dp, qs_ot_env%rot_mat_u, chc_re, 0.0_dp, tmp)
               CALL dbcsr_multiply('N', 'N', -1.0_dp, qs_ot_env%rot_mat_u_im, chc_im, 1.0_dp, tmp)
               CALL dbcsr_multiply('N', 'N', 1.0_dp, qs_ot_env%rot_mat_u, chc_im, 0.0_dp, tmp2)
               CALL dbcsr_multiply('N', 'N', 1.0_dp, qs_ot_env%rot_mat_u_im, chc_re, 1.0_dp, tmp2)
               CALL dbcsr_multiply('N', 'N', 2.0_dp, tmp, b_re, 1.0_dp, qs_ot_env%rot_mat_dedu)
               CALL dbcsr_multiply('N', 'N', 2.0_dp, tmp2, b_re, 1.0_dp, qs_ot_env%rot_mat_dedu_im)
            END IF
            DEALLOCATE (diagonal, tether_diag)
         END IF
      END IF

      IF (qs_ot_env%settings%add_nondiag_energy) THEN
         CPASSERT(qs_ot_env%settings%do_ener)
         nondiag_weight = qs_ot_env%settings%nondiag_energy_strength*kpoint_weight

         CALL dbcsr_copy(b_re, chc_re)
         CALL dbcsr_copy(b_im, chc_im)
         ALLOCATE (diagonal(SIZE(qs_ot_env%ener_x)))
         CALL get_replicated_kpoint_ot_diag(b_re, qs_ot_env, diagonal)
         diagonal(:) = diagonal(:) - qs_ot_env%ener_x(:)
         CALL dbcsr_set_diag(b_re, diagonal)
         DEALLOCATE (diagonal)

         CALL dbcsr_dot(b_re, b_re, nondiag_trace_re)
         CALL dbcsr_dot(b_im, b_im, nondiag_trace_im)
         nondiag_energy = nondiag_energy + &
                          0.5_dp*nondiag_weight*(nondiag_trace_re + nondiag_trace_im)

         ! Complex version of the Gamma-point NONDIAG_ENERGY tether:
         ! d/dU 0.5*k*||U^H A U - eps||^2 = 2*k*A*U*(U^H A U - eps).
         ! Since CHC=U^H A U, A*U is recovered as U*CHC for unitary U.
         CALL dbcsr_multiply('N', 'N', 1.0_dp, qs_ot_env%rot_mat_u, chc_re, 0.0_dp, tmp)
         CALL dbcsr_multiply('N', 'N', -1.0_dp, qs_ot_env%rot_mat_u_im, chc_im, 1.0_dp, tmp)
         CALL dbcsr_multiply('N', 'N', 1.0_dp, qs_ot_env%rot_mat_u, chc_im, 0.0_dp, tmp2)
         CALL dbcsr_multiply('N', 'N', 1.0_dp, qs_ot_env%rot_mat_u_im, chc_re, 1.0_dp, tmp2)

         CALL dbcsr_multiply('N', 'N', 2.0_dp*nondiag_weight, tmp, b_re, 1.0_dp, &
                             qs_ot_env%rot_mat_dedu)
         CALL dbcsr_multiply('N', 'N', -2.0_dp*nondiag_weight, tmp2, b_im, 1.0_dp, &
                             qs_ot_env%rot_mat_dedu)
         CALL dbcsr_multiply('N', 'N', 2.0_dp*nondiag_weight, tmp, b_im, 1.0_dp, &
                             qs_ot_env%rot_mat_dedu_im)
         CALL dbcsr_multiply('N', 'N', 2.0_dp*nondiag_weight, tmp2, b_re, 1.0_dp, &
                             qs_ot_env%rot_mat_dedu_im)
      END IF

      CALL qs_ot_rot_mat_derivative_complex(qs_ot_env)
      ! The k-point gradient is assembled for the C_orth*U channel convention.
      ! Convert the complex rotation adjoint to the minimizer variable convention.
      CALL dbcsr_scale(qs_ot_env%rot_mat_gx, -1.0_dp)
      CALL dbcsr_scale(qs_ot_env%rot_mat_gx_im, -1.0_dp)
      CALL prepare_kpoint_mermin_frozen_endpoint(qs_ot_env, occupation_numbers, eigenvalues, &
                                                 maxocc, mu, kpoint_weight, smear)

   END SUBROUTINE qs_scf_loop_prepare_ot_kp_channel_gradient

! **************************************************************************************************
!> \brief Evaluate the current rotation gradient once with the line-search-start Hamiltonian.
!> \param qs_ot_env local complex k-point OT channel
!> \param occupation_numbers current occupations
!> \param eigenvalues current auxiliary energies
!> \param maxocc maximum orbital occupation
!> \param mu current fixed-N chemical potential
!> \param kpoint_weight irreducible-k-point weight
!> \param smear smearing settings
! **************************************************************************************************
   SUBROUTINE prepare_kpoint_mermin_frozen_endpoint(qs_ot_env, occupation_numbers, eigenvalues, &
                                                    maxocc, mu, kpoint_weight, smear)
      TYPE(qs_ot_type)                                   :: qs_ot_env
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: occupation_numbers, eigenvalues
      REAL(KIND=dp), INTENT(IN)                          :: maxocc, mu, kpoint_weight
      TYPE(smear_type), INTENT(IN)                       :: smear

      INTEGER                                            :: imo, nmo
      LOGICAL                                            :: project_energy_subproblem
      REAL(KIND=dp) :: delta, nondiag_weight, rayleigh_edge_gap, sigma, tether_response, &
         tether_shift, tether_strength, tether_weight, tether_weight_sum
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: diagonal, occupation_scale, tether_diag
      TYPE(dbcsr_type)                                   :: b_im, b_re, chc_im, chc_re, dedu_im, &
                                                            dedu_re, hu_im, hu_re, saved_dedu_im, &
                                                            saved_dedu_re, saved_gx_im, &
                                                            saved_gx_re, tmp

      qs_ot_env%mermin_frozen_endpoint_valid = .FALSE.
      IF (.NOT. qs_ot_env%mermin_frozen_h_valid) RETURN
      IF (.NOT. qs_ot_env%settings%do_rotation) RETURN
      IF (.NOT. ASSOCIATED(qs_ot_env%rot_mat_mermin_h0_ref) .OR. &
          .NOT. ASSOCIATED(qs_ot_env%rot_mat_mermin_h0_ref_im) .OR. &
          .NOT. ASSOCIATED(qs_ot_env%rot_mat_mermin_frozen_g1) .OR. &
          .NOT. ASSOCIATED(qs_ot_env%rot_mat_mermin_frozen_g1_im)) RETURN

      nmo = SIZE(occupation_numbers)
      IF (SIZE(eigenvalues) < nmo) RETURN
      IF (qs_ot_env%settings%do_ener) THEN
         IF (.NOT. ASSOCIATED(qs_ot_env%ener_x) .OR. &
             .NOT. ASSOCIATED(qs_ot_env%ener_mermin_frozen_diag) .OR. &
             SIZE(qs_ot_env%ener_x) /= nmo .OR. &
             SIZE(qs_ot_env%ener_mermin_frozen_diag) /= nmo) RETURN
      END IF

      CALL dbcsr_copy(hu_re, qs_ot_env%rot_mat_mermin_h0_ref, name="mermin_frozen_hu_re")
      CALL dbcsr_copy(hu_im, qs_ot_env%rot_mat_mermin_h0_ref, name="mermin_frozen_hu_im")
      CALL dbcsr_copy(chc_re, qs_ot_env%rot_mat_mermin_h0_ref, name="mermin_frozen_chc_re")
      CALL dbcsr_copy(chc_im, qs_ot_env%rot_mat_mermin_h0_ref, name="mermin_frozen_chc_im")
      CALL dbcsr_copy(tmp, qs_ot_env%rot_mat_mermin_h0_ref, name="mermin_frozen_tmp")

      ! H0*U in the fixed REF basis.
      CALL dbcsr_multiply('N', 'N', 1.0_dp, qs_ot_env%rot_mat_mermin_h0_ref, &
                          qs_ot_env%rot_mat_u, 0.0_dp, hu_re)
      CALL dbcsr_multiply('N', 'N', -1.0_dp, qs_ot_env%rot_mat_mermin_h0_ref_im, &
                          qs_ot_env%rot_mat_u_im, 1.0_dp, hu_re)
      CALL dbcsr_multiply('N', 'N', 1.0_dp, qs_ot_env%rot_mat_mermin_h0_ref, &
                          qs_ot_env%rot_mat_u_im, 0.0_dp, hu_im)
      CALL dbcsr_multiply('N', 'N', 1.0_dp, qs_ot_env%rot_mat_mermin_h0_ref_im, &
                          qs_ot_env%rot_mat_u, 1.0_dp, hu_im)

      ! U^H*H0*U supplies the frozen Rayleigh energies and tether residual.
      CALL dbcsr_multiply('T', 'N', 1.0_dp, qs_ot_env%rot_mat_u, hu_re, 0.0_dp, chc_re)
      CALL dbcsr_multiply('T', 'N', 1.0_dp, qs_ot_env%rot_mat_u_im, hu_im, 0.0_dp, tmp)
      CALL dbcsr_add(chc_re, tmp, alpha_scalar=1.0_dp, beta_scalar=1.0_dp)
      CALL dbcsr_multiply('T', 'N', 1.0_dp, qs_ot_env%rot_mat_u, hu_im, 0.0_dp, chc_im)
      CALL dbcsr_multiply('T', 'N', 1.0_dp, qs_ot_env%rot_mat_u_im, hu_re, 0.0_dp, tmp)
      CALL dbcsr_add(chc_im, tmp, alpha_scalar=1.0_dp, beta_scalar=-1.0_dp)

      ALLOCATE (occupation_scale(nmo))
      occupation_scale(:) = 2.0_dp*kpoint_weight*occupation_numbers(:)
      CALL dbcsr_copy(dedu_re, hu_re, name="mermin_frozen_dedu_re")
      CALL dbcsr_copy(dedu_im, hu_im, name="mermin_frozen_dedu_im")
      CALL dbcsr_scale_by_vector(dedu_re, alpha=occupation_scale, side='right')
      CALL dbcsr_scale_by_vector(dedu_im, alpha=occupation_scale, side='right')
      DEALLOCATE (occupation_scale)

      IF (qs_ot_env%settings%do_ener) THEN
         CALL get_replicated_kpoint_ot_diag(chc_re, qs_ot_env, qs_ot_env%ener_mermin_frozen_diag)
      END IF

      project_energy_subproblem = kpoint_ot_project_energy_subproblem(qs_ot_env, smear)
      IF (qs_ot_env%settings%do_ener .AND. &
          qs_ot_occupation_preconditioner_active(qs_ot_env) .AND. &
          qs_ot_env%settings%canonical_tether .AND. &
          .NOT. project_energy_subproblem .AND. &
          smear%do_smear .AND. kpoint_ot_monotone_smearing(smear%method)) THEN
         sigma = kpoint_ot_smearing_width(smear)
         IF (sigma > 1.0E-14_dp) THEN
            ALLOCATE (tether_diag(nmo))
            tether_diag(:) = 0.0_dp
            tether_shift = 0.0_dp
            rayleigh_edge_gap = 0.0_dp
            tether_weight_sum = 0.0_dp
            DO imo = 1, nmo
               tether_response = kpoint_ot_canonical_tether_response(occupation_numbers(imo), &
                                                                     eigenvalues(imo), mu, sigma, &
                                                                     maxocc, smear%method)
               IF (tether_response > 0.0_dp) &
                  rayleigh_edge_gap = MAX(rayleigh_edge_gap, &
                                          ABS(qs_ot_env%ener_mermin_frozen_diag(imo) - &
                                              qs_ot_env%ener_x(imo)))
            END DO
            tether_strength = kpoint_ot_canonical_tether_strength(qs_ot_env, rayleigh_edge_gap, sigma)
            DO imo = 1, nmo
               tether_weight = kpoint_ot_canonical_tether_weight(occupation_numbers(imo), eigenvalues(imo), &
                                                                 mu, sigma, maxocc, smear%method, kpoint_weight, &
                                                                 tether_strength)
               IF (tether_weight <= 0.0_dp) CYCLE
               delta = qs_ot_env%ener_mermin_frozen_diag(imo) - qs_ot_env%ener_x(imo)
               tether_shift = tether_shift + tether_weight*delta
               tether_weight_sum = tether_weight_sum + tether_weight
            END DO
            IF (tether_weight_sum > EPSILON(tether_weight_sum)) THEN
               tether_shift = tether_shift/tether_weight_sum
               DO imo = 1, nmo
                  tether_weight = kpoint_ot_canonical_tether_weight(occupation_numbers(imo), eigenvalues(imo), &
                                                                    mu, sigma, maxocc, smear%method, kpoint_weight, &
                                                                    tether_strength)
                  IF (tether_weight <= 0.0_dp) CYCLE
                  tether_diag(imo) = tether_weight* &
                                     (qs_ot_env%ener_mermin_frozen_diag(imo) - &
                                      qs_ot_env%ener_x(imo) - tether_shift)
               END DO
               CALL dbcsr_copy(b_re, hu_re, name="mermin_frozen_tether_re")
               CALL dbcsr_copy(b_im, hu_im, name="mermin_frozen_tether_im")
               CALL dbcsr_scale_by_vector(b_re, alpha=2.0_dp*tether_diag, side='right')
               CALL dbcsr_scale_by_vector(b_im, alpha=2.0_dp*tether_diag, side='right')
               CALL dbcsr_add(dedu_re, b_re, alpha_scalar=1.0_dp, beta_scalar=1.0_dp)
               CALL dbcsr_add(dedu_im, b_im, alpha_scalar=1.0_dp, beta_scalar=1.0_dp)
               CALL dbcsr_release(b_re)
               CALL dbcsr_release(b_im)
            END IF
            DEALLOCATE (tether_diag)
         END IF
      END IF

      IF (qs_ot_env%settings%add_nondiag_energy) THEN
         nondiag_weight = qs_ot_env%settings%nondiag_energy_strength*kpoint_weight
         ALLOCATE (diagonal(nmo))
         diagonal(:) = qs_ot_env%ener_mermin_frozen_diag(:) - qs_ot_env%ener_x(:)
         CALL dbcsr_copy(b_re, chc_re, name="mermin_frozen_nondiag_re")
         CALL dbcsr_copy(b_im, chc_im, name="mermin_frozen_nondiag_im")
         CALL dbcsr_set_diag(b_re, diagonal)
         DEALLOCATE (diagonal)
         CALL dbcsr_multiply('N', 'N', 2.0_dp*nondiag_weight, hu_re, b_re, 1.0_dp, dedu_re)
         CALL dbcsr_multiply('N', 'N', -2.0_dp*nondiag_weight, hu_im, b_im, 1.0_dp, dedu_re)
         CALL dbcsr_multiply('N', 'N', 2.0_dp*nondiag_weight, hu_re, b_im, 1.0_dp, dedu_im)
         CALL dbcsr_multiply('N', 'N', 2.0_dp*nondiag_weight, hu_im, b_re, 1.0_dp, dedu_im)
         CALL dbcsr_release(b_re)
         CALL dbcsr_release(b_im)
      END IF

      ! Reuse the production Fréchet implementation, then restore its live matrices.
      CALL dbcsr_copy(saved_dedu_re, qs_ot_env%rot_mat_dedu, name="mermin_saved_dedu_re")
      CALL dbcsr_copy(saved_dedu_im, qs_ot_env%rot_mat_dedu_im, name="mermin_saved_dedu_im")
      CALL dbcsr_copy(saved_gx_re, qs_ot_env%rot_mat_gx, name="mermin_saved_gx_re")
      CALL dbcsr_copy(saved_gx_im, qs_ot_env%rot_mat_gx_im, name="mermin_saved_gx_im")
      CALL dbcsr_copy(qs_ot_env%rot_mat_dedu, dedu_re)
      CALL dbcsr_copy(qs_ot_env%rot_mat_dedu_im, dedu_im)
      CALL qs_ot_rot_mat_derivative_complex(qs_ot_env)
      CALL dbcsr_scale(qs_ot_env%rot_mat_gx, -1.0_dp)
      CALL dbcsr_scale(qs_ot_env%rot_mat_gx_im, -1.0_dp)
      CALL dbcsr_copy(qs_ot_env%rot_mat_mermin_frozen_g1, qs_ot_env%rot_mat_gx)
      CALL dbcsr_copy(qs_ot_env%rot_mat_mermin_frozen_g1_im, qs_ot_env%rot_mat_gx_im)
      CALL dbcsr_copy(qs_ot_env%rot_mat_dedu, saved_dedu_re)
      CALL dbcsr_copy(qs_ot_env%rot_mat_dedu_im, saved_dedu_im)
      CALL dbcsr_copy(qs_ot_env%rot_mat_gx, saved_gx_re)
      CALL dbcsr_copy(qs_ot_env%rot_mat_gx_im, saved_gx_im)
      qs_ot_env%mermin_frozen_endpoint_valid = .TRUE.

      CALL dbcsr_release(chc_im)
      CALL dbcsr_release(chc_re)
      CALL dbcsr_release(dedu_im)
      CALL dbcsr_release(dedu_re)
      CALL dbcsr_release(hu_im)
      CALL dbcsr_release(hu_re)
      CALL dbcsr_release(saved_dedu_im)
      CALL dbcsr_release(saved_dedu_re)
      CALL dbcsr_release(saved_gx_im)
      CALL dbcsr_release(saved_gx_re)
      CALL dbcsr_release(tmp)

   END SUBROUTINE prepare_kpoint_mermin_frozen_endpoint

! **************************************************************************************************
!> \brief convert k-point band-energy derivatives to fixed-N Mermin free-energy gradients
!> \param kpoints ...
!> \param local_ot_env ...
!> \param first_channel ...
!> \param nspin_ot ...
!> \param kp_range ...
!> \param wkp ...
!> \param para_env_inter_kp ...
!> \param smear ...
!> \param added_mos_auto ...
!> \param added_mos ...
!> \param eps_scf ...
!> \param trial_eigenvalues ...
!> \param trial_occupation ...
!> \param trial_mu ...
! **************************************************************************************************
   SUBROUTINE qs_scf_loop_prepare_ot_kp_energy_gradient(kpoints, local_ot_env, first_channel, nspin_ot, &
                                                        kp_range, wkp, para_env_inter_kp, smear, added_mos_auto, &
                                                        added_mos, eps_scf, &
                                                        trial_eigenvalues, trial_occupation, trial_mu)

      TYPE(kpoint_type), POINTER                         :: kpoints
      TYPE(qs_ot_type), DIMENSION(:), POINTER            :: local_ot_env
      INTEGER, INTENT(IN)                                :: first_channel, nspin_ot
      INTEGER, DIMENSION(2), INTENT(IN)                  :: kp_range
      REAL(KIND=dp), DIMENSION(:), POINTER               :: wkp
      TYPE(mp_para_env_type), POINTER                    :: para_env_inter_kp
      TYPE(smear_type), INTENT(IN)                       :: smear
      LOGICAL, DIMENSION(:), INTENT(IN)                  :: added_mos_auto
      INTEGER, DIMENSION(:), INTENT(IN)                  :: added_mos
      REAL(KIND=dp), INTENT(IN)                          :: eps_scf
      REAL(KIND=dp), DIMENSION(:, :, :), INTENT(IN)      :: trial_eigenvalues, trial_occupation
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: trial_mu

      INTEGER                                            :: group, ikpoint, imo, ispin, local_channel, &
                                                            local_kpoint, ngroups, nmo
      ! Keep the auxiliary-energy regularization separate from the rotation
      ! Schur floor; later metallic calibration can then tune one channel
      ! without silently changing the other.
      REAL(KIND=dp), PARAMETER                           :: rotation_curvature_floor = 1.0_dp

      REAL(KIND=dp)                                      :: delta, gvalue, maxocc, mu, rot_generator_norm, &
                                                            rot_generator_re, rot_generator_im, sigma, tmp_norm, &
                                                            rayleigh_edge_gap, tether_response, &
                                                            tether_shift, tether_strength, &
                                                            tether_weight, tether_weight_sum, v
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: canonical_diag, gdotv, gsum, &
                                                            nondiag_diag, precond_count, &
                                                            precond_shift, precond_sum
      LOGICAL :: active_preconditioner, audit_preconditioner, global_schur_replicated
      LOGICAL, ALLOCATABLE, DIMENSION(:)                 :: schur_group_done
      REAL(KIND=dp), DIMENSION(:), POINTER               :: vector_swap
      TYPE(cp_logger_type), POINTER                      :: logger
      TYPE(dbcsr_type), POINTER                          :: matrix_swap
      TYPE(kpoint_env_type), POINTER                     :: kp

      IF (.NOT. local_ot_env(1)%settings%do_ener) RETURN

      logger => cp_get_default_logger()

      ngroups = 1
      IF (nspin_ot == 2 .AND. smear%fixed_mag_mom >= 0.0_dp) ngroups = 2
      ALLOCATE (gsum(ngroups), gdotv(ngroups), precond_count(ngroups), &
                precond_shift(ngroups), precond_sum(ngroups), schur_group_done(ngroups))
      gsum(:) = 0.0_dp
      gdotv(:) = 0.0_dp
      precond_count(:) = 0.0_dp
      precond_shift(:) = 0.0_dp
      precond_sum(:) = 0.0_dp
      schur_group_done(:) = .FALSE.
      active_preconditioner = qs_ot_occupation_preconditioner_active(local_ot_env(1)) .AND. &
                              smear%do_smear .AND. &
                              (smear%method == smear_fermi_dirac .OR. &
                               smear%method == smear_gaussian)
      audit_preconditioner = local_ot_env(1)%settings%occupation_preconditioner .AND. &
                             smear%do_smear .AND. &
                             (smear%method == smear_fermi_dirac .OR. &
                              smear%method == smear_gaussian)
      global_schur_replicated = para_env_inter_kp%num_pe > 1

      CALL audit_kpoint_ot_canonical_density()

      rot_generator_re = 0.0_dp
      rot_generator_im = 0.0_dp
      IF (local_ot_env(1)%settings%do_rotation) THEN
         DO local_channel = 1, SIZE(local_ot_env)
            CALL dbcsr_dot(local_ot_env(local_channel)%rot_mat_x, &
                           local_ot_env(local_channel)%rot_mat_x, tmp_norm)
            rot_generator_re = rot_generator_re + &
                               tmp_norm/REAL(MAX(1, local_ot_env(local_channel)%kpoint_multiplicity), KIND=dp)
            IF (ASSOCIATED(local_ot_env(local_channel)%rot_mat_x_im)) THEN
               CALL dbcsr_dot(local_ot_env(local_channel)%rot_mat_x_im, &
                              local_ot_env(local_channel)%rot_mat_x_im, tmp_norm)
               rot_generator_im = rot_generator_im + &
                                  tmp_norm/REAL(MAX(1, local_ot_env(local_channel)%kpoint_multiplicity), KIND=dp)
            END IF
         END DO
         CALL para_env_inter_kp%sum(rot_generator_re)
         CALL para_env_inter_kp%sum(rot_generator_im)
         rot_generator_norm = SQRT(MAX(0.0_dp, rot_generator_re + rot_generator_im))
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,3(1X,ES16.8))') &
            " OT k-point accumulated complex rotation norm re2 im2 total:", &
            rot_generator_re, rot_generator_im, rot_generator_norm
      END IF

      IF (smear%do_smear) THEN
         SELECT CASE (smear%method)
         CASE (smear_fermi_dirac)
            sigma = smear%electronic_temperature
         CASE (smear_gaussian, smear_mp, smear_mv)
            sigma = smear%smearing_width
         CASE DEFAULT
            sigma = 0.0_dp
         END SELECT
      ELSE
         sigma = 0.0_dp
      END IF

      ! For FD smearing, g_i = -df_i/deps_i. Fixed electron number removes the
      ! chemical-potential mode, giving the projected response
      ! w_i*g_i*(<v>_g - v_i) with <v>_g = sum(w_i*g_i*v_i)/sum(w_i*g_i).
      DO local_kpoint = 1, SIZE(kpoints%kp_env)
         kp => kpoints%kp_env(local_kpoint)%kpoint_env
         ikpoint = kp%nkpoint
         DO ispin = 1, nspin_ot
            group = MERGE(ispin, 1, ngroups == nspin_ot)
            local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
            local_ot_env(local_channel)%occupation_group_index = group
            CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, nmo=nmo)
            mu = trial_mu(ispin)
            DO imo = 1, nmo
               gvalue = SmearingDerivative(trial_occupation(imo, ikpoint, ispin), &
                                           trial_eigenvalues(imo, ikpoint, ispin), mu, &
                                           sigma, maxocc, smear%method)
               v = local_ot_env(local_channel)%ener_gx(imo) - trial_eigenvalues(imo, ikpoint, ispin) + mu
               gsum(group) = gsum(group) + wkp(ikpoint)*gvalue
               gdotv(group) = gdotv(group) + wkp(ikpoint)*gvalue*v
            END DO
         END DO
      END DO

      CALL para_env_inter_kp%sum(gsum)
      CALL para_env_inter_kp%sum(gdotv)

      DO local_kpoint = 1, SIZE(kpoints%kp_env)
         kp => kpoints%kp_env(local_kpoint)%kpoint_env
         ikpoint = kp%nkpoint
         DO ispin = 1, nspin_ot
            group = MERGE(ispin, 1, ngroups == nspin_ot)
            local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
            CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, nmo=nmo)
            mu = trial_mu(ispin)
            DO imo = 1, nmo
               gvalue = SmearingDerivative(trial_occupation(imo, ikpoint, ispin), &
                                           trial_eigenvalues(imo, ikpoint, ispin), mu, &
                                           sigma, maxocc, smear%method)
               IF (ABS(gsum(group)) > EPSILON(gsum(group))) THEN
                  v = local_ot_env(local_channel)%ener_gx(imo) - trial_eigenvalues(imo, ikpoint, ispin) + mu
                  local_ot_env(local_channel)%ener_gx(imo) = &
                     wkp(ikpoint)*gvalue*(gdotv(group)/gsum(group) - v)
               ELSE
                  local_ot_env(local_channel)%ener_gx(imo) = 0.0_dp
               END IF
            END DO
         END DO
      END DO

      IF (local_ot_env(1)%settings%add_nondiag_energy) THEN
         DO local_kpoint = 1, SIZE(kpoints%kp_env)
            kp => kpoints%kp_env(local_kpoint)%kpoint_env
            ikpoint = kp%nkpoint
            DO ispin = 1, nspin_ot
               local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
               CALL get_mo_set(kp%mos(1, ispin), nmo=nmo)
               ALLOCATE (nondiag_diag(nmo))
               CALL get_replicated_kpoint_ot_diag(local_ot_env(local_channel)%rot_mat_chc, &
                                                  local_ot_env(local_channel), nondiag_diag)
               nondiag_diag(:) = nondiag_diag(:) - local_ot_env(local_channel)%ener_x(:)
               local_ot_env(local_channel)%ener_gx(:) = local_ot_env(local_channel)%ener_gx(:) - &
                                           local_ot_env(local_channel)%settings%nondiag_energy_strength*wkp(ikpoint)*nondiag_diag(:)
               DEALLOCATE (nondiag_diag)
            END DO
         END DO
      END IF

      IF (active_preconditioner .AND. local_ot_env(1)%settings%canonical_tether) THEN
         DO local_kpoint = 1, SIZE(kpoints%kp_env)
            kp => kpoints%kp_env(local_kpoint)%kpoint_env
            ikpoint = kp%nkpoint
            DO ispin = 1, nspin_ot
               local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
               CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, nmo=nmo)
               mu = trial_mu(ispin)
               ALLOCATE (canonical_diag(nmo))
               CALL get_replicated_kpoint_ot_diag(local_ot_env(local_channel)%rot_mat_chc, &
                                                  local_ot_env(local_channel), canonical_diag)
               tether_shift = 0.0_dp
               rayleigh_edge_gap = 0.0_dp
               tether_weight_sum = 0.0_dp
               DO imo = 1, nmo
                  tether_response = kpoint_ot_canonical_tether_response(trial_occupation(imo, ikpoint, ispin), &
                                                                        trial_eigenvalues(imo, ikpoint, ispin), mu, &
                                                                        sigma, maxocc, smear%method)
                  IF (tether_response > 0.0_dp) &
                     rayleigh_edge_gap = MAX(rayleigh_edge_gap, &
                                             ABS(canonical_diag(imo) - local_ot_env(local_channel)%ener_x(imo)))
               END DO
               tether_strength = kpoint_ot_canonical_tether_strength(local_ot_env(local_channel), &
                                                                     rayleigh_edge_gap, sigma)
               local_ot_env(local_channel)%canonical_tether_strength = tether_strength
               DO imo = 1, nmo
                  tether_weight = kpoint_ot_canonical_tether_weight(trial_occupation(imo, ikpoint, ispin), &
                                                                    trial_eigenvalues(imo, ikpoint, ispin), &
                                                                    mu, sigma, maxocc, smear%method, wkp(ikpoint), &
                                                                    tether_strength)
                  IF (tether_weight <= 0.0_dp) CYCLE
                  delta = canonical_diag(imo) - local_ot_env(local_channel)%ener_x(imo)
                  tether_shift = tether_shift + tether_weight*delta
                  tether_weight_sum = tether_weight_sum + tether_weight
               END DO
               IF (tether_weight_sum > EPSILON(tether_weight_sum)) THEN
                  tether_shift = tether_shift/tether_weight_sum
                  DO imo = 1, nmo
                     tether_weight = kpoint_ot_canonical_tether_weight(trial_occupation(imo, ikpoint, ispin), &
                                                                       trial_eigenvalues(imo, ikpoint, ispin), &
                                                                       mu, sigma, maxocc, smear%method, wkp(ikpoint), &
                                                                       tether_strength)
                     IF (tether_weight <= 0.0_dp) CYCLE
                     delta = canonical_diag(imo) - local_ot_env(local_channel)%ener_x(imo) - tether_shift
                     local_ot_env(local_channel)%ener_gx(imo) = &
                        local_ot_env(local_channel)%ener_gx(imo) - tether_weight*delta
                  END DO
               END IF
               DEALLOCATE (canonical_diag)
            END DO
         END DO
      END IF

      CALL prepare_kpoint_mermin_frozen_energy_gradient()

      IF (audit_preconditioner) THEN
         DO local_channel = 1, SIZE(local_ot_env)
            local_ot_env(local_channel)%kpoint_preconditioned_direction_ready = .FALSE.
            IF (local_ot_env(local_channel)%settings%do_rotation) THEN
               CPASSERT(ASSOCIATED(local_ot_env(local_channel)%rot_mat_pgx))
               CPASSERT(ASSOCIATED(local_ot_env(local_channel)%rot_mat_pgx_im))
               CALL dbcsr_copy(local_ot_env(local_channel)%rot_mat_pgx, &
                               local_ot_env(local_channel)%rot_mat_gx)
               CALL dbcsr_copy(local_ot_env(local_channel)%rot_mat_pgx_im, &
                               local_ot_env(local_channel)%rot_mat_gx_im)
            END IF
            IF (local_ot_env(local_channel)%settings%do_ener) THEN
               CPASSERT(ASSOCIATED(local_ot_env(local_channel)%ener_pgx))
               local_ot_env(local_channel)%ener_pgx(:) = local_ot_env(local_channel)%ener_gx(:)
            END IF
         END DO
         CALL precondition_kpoint_ot_schur(schur_group_done, ANY(added_mos_auto), &
                                           MAXVAL(added_mos), eps_scf)
         CALL precondition_kpoint_ot_energy_diagonal(schur_group_done)
         DO local_channel = 1, SIZE(local_ot_env)
            IF (local_ot_env(local_channel)%settings%do_rotation) THEN
               matrix_swap => local_ot_env(local_channel)%rot_mat_gx
               local_ot_env(local_channel)%rot_mat_gx => local_ot_env(local_channel)%rot_mat_pgx
               local_ot_env(local_channel)%rot_mat_pgx => matrix_swap
               matrix_swap => local_ot_env(local_channel)%rot_mat_gx_im
               local_ot_env(local_channel)%rot_mat_gx_im => local_ot_env(local_channel)%rot_mat_pgx_im
               local_ot_env(local_channel)%rot_mat_pgx_im => matrix_swap
            END IF
            IF (local_ot_env(local_channel)%settings%do_ener) THEN
               vector_swap => local_ot_env(local_channel)%ener_gx
               local_ot_env(local_channel)%ener_gx => local_ot_env(local_channel)%ener_pgx
               local_ot_env(local_channel)%ener_pgx => vector_swap
            END IF
            local_ot_env(local_channel)%kpoint_preconditioned_direction_ready = active_preconditioner
         END DO
      END IF

      DEALLOCATE (gsum, gdotv, precond_count, precond_shift, precond_sum, schur_group_done)

      CPASSERT(kp_range(2) - kp_range(1) + 1 == SIZE(kpoints%kp_env))

   CONTAINS

! **************************************************************************************************
!> \brief Complete the frozen-H endpoint with the globally projected fixed-N energy gradient.
! **************************************************************************************************
      SUBROUTINE prepare_kpoint_mermin_frozen_energy_gradient()

      INTEGER                                            :: frozen_valid_i
      LOGICAL                                            :: frozen_valid
      REAL(KIND=dp) :: frozen_delta, frozen_edge_gap, frozen_shift, frozen_strength, &
         frozen_weight, frozen_weight_sum, response_weight_value
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: frozen_gdotv, frozen_gsum, &
                                                            frozen_response_weight

         frozen_valid = .TRUE.
         DO local_channel = 1, SIZE(local_ot_env)
            frozen_valid = frozen_valid .AND. local_ot_env(local_channel)%mermin_frozen_endpoint_valid .AND. &
                           ASSOCIATED(local_ot_env(local_channel)%ener_mermin_frozen_diag) .AND. &
                           ASSOCIATED(local_ot_env(local_channel)%ener_mermin_frozen_g1)
         END DO
         frozen_valid_i = MERGE(1, 0, frozen_valid)
         CALL para_env_inter_kp%min(frozen_valid_i)
         frozen_valid = frozen_valid_i > 0
         IF (.NOT. frozen_valid) THEN
            DO local_channel = 1, SIZE(local_ot_env)
               local_ot_env(local_channel)%mermin_frozen_endpoint_valid = .FALSE.
            END DO
            RETURN
         END IF

         ALLOCATE (frozen_gsum(ngroups), frozen_gdotv(ngroups))
         frozen_gsum(:) = 0.0_dp
         frozen_gdotv(:) = 0.0_dp
         DO local_kpoint = 1, SIZE(kpoints%kp_env)
            kp => kpoints%kp_env(local_kpoint)%kpoint_env
            ikpoint = kp%nkpoint
            DO ispin = 1, nspin_ot
               group = MERGE(ispin, 1, ngroups == nspin_ot)
               local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
               CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, nmo=nmo)
               mu = trial_mu(ispin)
               DO imo = 1, nmo
                  gvalue = SmearingDerivative(trial_occupation(imo, ikpoint, ispin), &
                                              trial_eigenvalues(imo, ikpoint, ispin), mu, &
                                              sigma, maxocc, smear%method)
                  response_weight_value = wkp(ikpoint)*gvalue
                  frozen_gsum(group) = frozen_gsum(group) + response_weight_value
                  frozen_gdotv(group) = frozen_gdotv(group) + response_weight_value* &
                                        (local_ot_env(local_channel)%ener_mermin_frozen_diag(imo) - &
                                         local_ot_env(local_channel)%ener_x(imo))
               END DO
            END DO
         END DO
         CALL para_env_inter_kp%sum(frozen_gsum)
         CALL para_env_inter_kp%sum(frozen_gdotv)

         DO local_kpoint = 1, SIZE(kpoints%kp_env)
            kp => kpoints%kp_env(local_kpoint)%kpoint_env
            ikpoint = kp%nkpoint
            DO ispin = 1, nspin_ot
               group = MERGE(ispin, 1, ngroups == nspin_ot)
               local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
               CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, nmo=nmo)
               mu = trial_mu(ispin)
               ALLOCATE (frozen_response_weight(nmo))
               DO imo = 1, nmo
                  gvalue = SmearingDerivative(trial_occupation(imo, ikpoint, ispin), &
                                              trial_eigenvalues(imo, ikpoint, ispin), mu, &
                                              sigma, maxocc, smear%method)
                  frozen_response_weight(imo) = wkp(ikpoint)*gvalue
               END DO
               CALL qs_scf_kp_fixed_n_frozen_energy_gradient( &
                  local_ot_env(local_channel)%ener_mermin_frozen_diag, &
                  local_ot_env(local_channel)%ener_x, frozen_response_weight, frozen_gsum(group), &
                  frozen_gdotv(group), local_ot_env(local_channel)%ener_mermin_frozen_g1)
               DEALLOCATE (frozen_response_weight)

               IF (local_ot_env(local_channel)%settings%add_nondiag_energy) THEN
                  local_ot_env(local_channel)%ener_mermin_frozen_g1(:) = &
                     local_ot_env(local_channel)%ener_mermin_frozen_g1(:) - &
                     local_ot_env(local_channel)%settings%nondiag_energy_strength*wkp(ikpoint)* &
                     (local_ot_env(local_channel)%ener_mermin_frozen_diag(:) - &
                      local_ot_env(local_channel)%ener_x(:))
               END IF

               IF (active_preconditioner .AND. local_ot_env(local_channel)%settings%canonical_tether) THEN
                  frozen_shift = 0.0_dp
                  frozen_edge_gap = 0.0_dp
                  frozen_weight_sum = 0.0_dp
                  DO imo = 1, nmo
                     tether_response = kpoint_ot_canonical_tether_response( &
                                       trial_occupation(imo, ikpoint, ispin), trial_eigenvalues(imo, ikpoint, ispin), &
                                       mu, sigma, maxocc, smear%method)
                     IF (tether_response > 0.0_dp) &
                        frozen_edge_gap = MAX(frozen_edge_gap, &
                                              ABS(local_ot_env(local_channel)%ener_mermin_frozen_diag(imo) - &
                                                  local_ot_env(local_channel)%ener_x(imo)))
                  END DO
                  frozen_strength = kpoint_ot_canonical_tether_strength( &
                                    local_ot_env(local_channel), frozen_edge_gap, sigma)
                  DO imo = 1, nmo
                     frozen_weight = kpoint_ot_canonical_tether_weight( &
                                     trial_occupation(imo, ikpoint, ispin), trial_eigenvalues(imo, ikpoint, ispin), &
                                     mu, sigma, maxocc, smear%method, wkp(ikpoint), frozen_strength)
                     IF (frozen_weight <= 0.0_dp) CYCLE
                     frozen_delta = local_ot_env(local_channel)%ener_mermin_frozen_diag(imo) - &
                                    local_ot_env(local_channel)%ener_x(imo)
                     frozen_shift = frozen_shift + frozen_weight*frozen_delta
                     frozen_weight_sum = frozen_weight_sum + frozen_weight
                  END DO
                  IF (frozen_weight_sum > EPSILON(frozen_weight_sum)) THEN
                     frozen_shift = frozen_shift/frozen_weight_sum
                     DO imo = 1, nmo
                        frozen_weight = kpoint_ot_canonical_tether_weight( &
                                        trial_occupation(imo, ikpoint, ispin), trial_eigenvalues(imo, ikpoint, ispin), &
                                        mu, sigma, maxocc, smear%method, wkp(ikpoint), frozen_strength)
                        IF (frozen_weight <= 0.0_dp) CYCLE
                        frozen_delta = local_ot_env(local_channel)%ener_mermin_frozen_diag(imo) - &
                                       local_ot_env(local_channel)%ener_x(imo) - frozen_shift
                        local_ot_env(local_channel)%ener_mermin_frozen_g1(imo) = &
                           local_ot_env(local_channel)%ener_mermin_frozen_g1(imo) - &
                           frozen_weight*frozen_delta
                     END DO
                  END IF
               END IF
            END DO
         END DO

         DEALLOCATE (frozen_gdotv, frozen_gsum)

      END SUBROUTINE prepare_kpoint_mermin_frozen_energy_gradient

! **************************************************************************************************
!> \brief Evaluate P-current minus the canonical fixed-N Fermi projector of C^H H C.
! **************************************************************************************************
      SUBROUTINE audit_kpoint_ot_canonical_density()

      COMPLEX(KIND=dp), ALLOCATABLE, DIMENSION(:, :)     :: chc, evec
      COMPLEX(KIND=dp), ALLOCATABLE, DIMENSION(:, :, :)  :: channel_evec
      INTEGER                                            :: ikpoint, imo, ispin, jmo, local_channel, &
                                                            local_kpoint, max_i, max_j, nmo
      INTEGER, ALLOCATABLE, DIMENSION(:, :)              :: channel_pair_i, channel_pair_j
      LOGICAL                                            :: audit_ready
      REAL(KIND=dp) :: canonical_kTS, channel_max, channel_metric, channel_metric_diag, &
         channel_metric_offdiag, channel_pair_max, channel_weight, density_delta, density_diag, &
         density_max, density_metric, density_offdiag, density_weight, maxocc, sigma
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: canonical_mu, evals
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :) :: channel_density_diag, channel_density_max, &
         channel_density_metric, channel_density_offdiag, channel_density_weight, h_im, h_re
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :, :) :: canonical_eigenvalues, &
         canonical_occupation, channel_pair_canonical_occ, channel_pair_current_occ, &
         channel_pair_eigenvalue

         audit_ready = local_ot_env(1)%settings%do_rotation .AND. &
                       local_ot_env(1)%settings%do_ener .AND. smear%do_smear .AND. &
                       kpoint_ot_monotone_smearing(smear%method) .AND. &
                       kpoint_ot_smearing_width(smear) > 0.0_dp
         DO local_channel = 1, SIZE(local_ot_env)
            local_ot_env(local_channel)%kpoint_density_stationarity_ready = .FALSE.
            local_ot_env(local_channel)%kpoint_density_stationarity_delta = -1.0_dp
            local_ot_env(local_channel)%kpoint_density_stationarity_diag = -1.0_dp
            local_ot_env(local_channel)%kpoint_density_stationarity_offdiag = -1.0_dp
            local_ot_env(local_channel)%kpoint_density_stationarity_max = -1.0_dp
            local_ot_env(local_channel)%kpoint_canonical_occupation_ready = .FALSE.
            local_ot_env(local_channel)%kpoint_canonical_mu = 0.0_dp
            IF (ALLOCATED(local_ot_env(local_channel)%kpoint_canonical_occupation)) &
               local_ot_env(local_channel)%kpoint_canonical_occupation(:) = 0.0_dp
            IF (ALLOCATED(local_ot_env(local_channel)%kpoint_canonical_eigenvalue)) &
               local_ot_env(local_channel)%kpoint_canonical_eigenvalue(:) = 0.0_dp
         END DO
         IF (.NOT. audit_ready) RETURN

         sigma = kpoint_ot_smearing_width(smear)
         nmo = SIZE(trial_eigenvalues, 1)
         ALLOCATE (canonical_eigenvalues, MOLD=trial_eigenvalues)
         ALLOCATE (canonical_occupation, MOLD=trial_occupation)
         ALLOCATE (canonical_mu(SIZE(trial_mu)))
         ALLOCATE (channel_evec(nmo, nmo, SIZE(local_ot_env)))
         ALLOCATE (channel_pair_i(SIZE(wkp), nspin_ot), channel_pair_j(SIZE(wkp), nspin_ot), &
                   channel_pair_canonical_occ(2, SIZE(wkp), nspin_ot), &
                   channel_pair_current_occ(2, SIZE(wkp), nspin_ot), &
                   channel_pair_eigenvalue(2, SIZE(wkp), nspin_ot))
         ALLOCATE (channel_density_diag(SIZE(wkp), nspin_ot), &
                   channel_density_max(SIZE(wkp), nspin_ot), &
                   channel_density_metric(SIZE(wkp), nspin_ot), &
                   channel_density_offdiag(SIZE(wkp), nspin_ot), &
                   channel_density_weight(SIZE(wkp), nspin_ot))
         canonical_eigenvalues(:, :, :) = 0.0_dp
         canonical_occupation(:, :, :) = 0.0_dp
         canonical_mu(:) = 0.0_dp
         channel_evec(:, :, :) = CMPLX(0.0_dp, 0.0_dp, KIND=dp)
         channel_pair_i(:, :) = 0
         channel_pair_j(:, :) = 0
         channel_pair_canonical_occ(:, :, :) = 0.0_dp
         channel_pair_current_occ(:, :, :) = 0.0_dp
         channel_pair_eigenvalue(:, :, :) = 0.0_dp
         channel_density_diag(:, :) = 0.0_dp
         channel_density_max(:, :) = 0.0_dp
         channel_density_metric(:, :) = 0.0_dp
         channel_density_offdiag(:, :) = 0.0_dp
         channel_density_weight(:, :) = 0.0_dp

         DO local_kpoint = 1, SIZE(kpoints%kp_env)
            kp => kpoints%kp_env(local_kpoint)%kpoint_env
            ikpoint = kp%nkpoint
            DO ispin = 1, nspin_ot
               local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
               ALLOCATE (h_re(nmo, nmo), h_im(nmo, nmo), chc(nmo, nmo), evec(nmo, nmo), evals(nmo))
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_chc, h_re)
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_chc_im, h_im)
               CALL local_ot_env(local_channel)%para_env%sum(h_re)
               CALL local_ot_env(local_channel)%para_env%sum(h_im)
               chc(:, :) = CMPLX(h_re, h_im, KIND=dp)
               chc(:, :) = 0.5_dp*(chc(:, :) + CONJG(TRANSPOSE(chc(:, :))))
               CALL diag_complex(chc, evec, evals)
               canonical_eigenvalues(:, ikpoint, ispin) = evals(:)
               channel_evec(:, :, local_channel) = evec(:, :)
               DEALLOCATE (h_re, h_im, chc, evec, evals)
            END DO
         END DO
         CALL para_env_inter_kp%sum(canonical_eigenvalues)
         CALL qs_scf_loop_smear_ot_kp_trial_eigenvalues( &
            kpoints, nspin_ot, wkp, smear, canonical_eigenvalues, canonical_occupation, &
            canonical_mu, canonical_kTS)

         density_metric = 0.0_dp
         density_weight = 0.0_dp
         density_max = 0.0_dp
         DO local_kpoint = 1, SIZE(kpoints%kp_env)
            kp => kpoints%kp_env(local_kpoint)%kpoint_env
            ikpoint = kp%nkpoint
            DO ispin = 1, nspin_ot
               local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
               CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc)
               CPASSERT(ALLOCATED(local_ot_env(local_channel)%kpoint_canonical_occupation))
               audit_ready = &
                  SIZE(local_ot_env(local_channel)%kpoint_canonical_occupation) == nmo
               CPASSERT(audit_ready)
               CPASSERT(ALLOCATED(local_ot_env(local_channel)%kpoint_canonical_eigenvalue))
               audit_ready = &
                  SIZE(local_ot_env(local_channel)%kpoint_canonical_eigenvalue) == nmo
               CPASSERT(audit_ready)
               local_ot_env(local_channel)%kpoint_canonical_occupation(:) = &
                  canonical_occupation(:, ikpoint, ispin)
               local_ot_env(local_channel)%kpoint_canonical_eigenvalue(:) = &
                  canonical_eigenvalues(:, ikpoint, ispin)
               local_ot_env(local_channel)%kpoint_canonical_mu = canonical_mu(ispin)
               local_ot_env(local_channel)%kpoint_canonical_occupation_ready = .TRUE.
               CALL qs_scf_kp_canonical_density_residual( &
                  channel_evec(:, :, local_channel), trial_occupation(:, ikpoint, ispin), &
                  canonical_occupation(:, ikpoint, ispin), sigma, maxocc, wkp(ikpoint), &
                  channel_metric, channel_weight, channel_max, channel_metric_diag, &
                  channel_metric_offdiag, &
                  local_ot_env(local_channel)%kpoint_density_pair_residual, smear%method)
               channel_density_diag(ikpoint, ispin) = channel_metric_diag
               channel_density_max(ikpoint, ispin) = channel_max
               channel_density_metric(ikpoint, ispin) = channel_metric
               channel_density_offdiag(ikpoint, ispin) = channel_metric_offdiag
               channel_density_weight(ikpoint, ispin) = channel_weight
               channel_pair_max = -1.0_dp
               max_i = 0
               max_j = 0
               DO jmo = 2, nmo
                  DO imo = 1, jmo - 1
                     IF (local_ot_env(local_channel)%kpoint_density_pair_residual(imo, jmo) > &
                         channel_pair_max) THEN
                        channel_pair_max = &
                           local_ot_env(local_channel)%kpoint_density_pair_residual(imo, jmo)
                        max_i = imo
                        max_j = jmo
                     END IF
                  END DO
               END DO
               channel_pair_i(ikpoint, ispin) = max_i
               channel_pair_j(ikpoint, ispin) = max_j
               IF (max_i > 0 .AND. max_j > 0) THEN
                  channel_pair_current_occ(:, ikpoint, ispin) = &
                     [trial_occupation(max_i, ikpoint, ispin), trial_occupation(max_j, ikpoint, ispin)]
                  channel_pair_canonical_occ(:, ikpoint, ispin) = &
                     [canonical_occupation(max_i, ikpoint, ispin), &
                      canonical_occupation(max_j, ikpoint, ispin)]
                  channel_pair_eigenvalue(:, ikpoint, ispin) = &
                     [canonical_eigenvalues(max_i, ikpoint, ispin), &
                      canonical_eigenvalues(max_j, ikpoint, ispin)]
               END IF
               density_metric = density_metric + channel_metric
               density_weight = density_weight + channel_weight
               density_max = MAX(density_max, channel_max)
            END DO
         END DO
         CALL para_env_inter_kp%sum(density_metric)
         CALL para_env_inter_kp%sum(density_weight)
         CALL para_env_inter_kp%max(density_max)
         CALL para_env_inter_kp%sum(channel_density_diag)
         CALL para_env_inter_kp%sum(channel_density_metric)
         CALL para_env_inter_kp%sum(channel_density_offdiag)
         CALL para_env_inter_kp%sum(channel_density_weight)
         CALL para_env_inter_kp%sum(channel_pair_i)
         CALL para_env_inter_kp%sum(channel_pair_j)
         CALL para_env_inter_kp%sum(channel_pair_current_occ)
         CALL para_env_inter_kp%sum(channel_pair_canonical_occ)
         CALL para_env_inter_kp%sum(channel_pair_eigenvalue)
         DO ispin = 1, nspin_ot
            DO ikpoint = 1, SIZE(wkp)
               CALL para_env_inter_kp%max(channel_density_max(ikpoint, ispin))
            END DO
         END DO
         density_delta = 0.0_dp
         density_diag = 0.0_dp
         density_offdiag = 0.0_dp
         IF (density_weight > 0.0_dp) THEN
            density_delta = SQRT(MAX(0.0_dp, density_metric)/density_weight)
            density_diag = SQRT(MAX(0.0_dp, SUM(channel_density_diag))/density_weight)
            density_offdiag = SQRT(MAX(0.0_dp, SUM(channel_density_offdiag))/density_weight)
         END IF

         DO local_channel = 1, SIZE(local_ot_env)
            local_ot_env(local_channel)%kpoint_density_stationarity_ready = .TRUE.
            local_ot_env(local_channel)%kpoint_density_stationarity_delta = density_delta
            local_ot_env(local_channel)%kpoint_density_stationarity_diag = density_diag
            local_ot_env(local_channel)%kpoint_density_stationarity_offdiag = density_offdiag
            local_ot_env(local_channel)%kpoint_density_stationarity_max = density_max
         END DO
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,6(1X,ES16.8))') &
            " OT k-point canonical density stationarity rms diag offdiag max mu kTS:", &
            density_delta, density_diag, density_offdiag, density_max, canonical_mu(1), canonical_kTS
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) THEN
            DO ispin = 1, nspin_ot
               DO ikpoint = 1, SIZE(wkp)
                  channel_metric = 0.0_dp
                  channel_metric_diag = 0.0_dp
                  channel_metric_offdiag = 0.0_dp
                  IF (channel_density_weight(ikpoint, ispin) > 0.0_dp) THEN
                     channel_metric = SQRT(MAX(0.0_dp, channel_density_metric(ikpoint, ispin))/ &
                                           channel_density_weight(ikpoint, ispin))
                     channel_metric_diag = SQRT(MAX(0.0_dp, channel_density_diag(ikpoint, ispin))/ &
                                                channel_density_weight(ikpoint, ispin))
                     channel_metric_offdiag = SQRT(MAX(0.0_dp, channel_density_offdiag(ikpoint, ispin))/ &
                                                   channel_density_weight(ikpoint, ispin))
                  END IF
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,2(1X,I4),4(1X,ES16.8))') &
                     " OT k-point canonical density channel spin k rms diag offdiag max:", &
                     ispin, ikpoint, channel_metric, channel_metric_diag, channel_metric_offdiag, &
                     channel_density_max(ikpoint, ispin)
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,4(1X,I4),7(1X,ES16.8))') &
                     " OT k-point canonical density max-pair spin k i j residual "// &
                     "occ_i occ_j can_i can_j eps_i eps_j:", &
                     ispin, ikpoint, channel_pair_i(ikpoint, ispin), channel_pair_j(ikpoint, ispin), &
                     channel_density_max(ikpoint, ispin), &
                     channel_pair_current_occ(:, ikpoint, ispin), &
                     channel_pair_canonical_occ(:, ikpoint, ispin), &
                     channel_pair_eigenvalue(:, ikpoint, ispin)
               END DO
            END DO
         END IF

         DEALLOCATE (canonical_eigenvalues, canonical_occupation, canonical_mu, channel_evec, &
                     channel_pair_i, channel_pair_j, channel_pair_canonical_occ, &
                     channel_pair_current_occ, channel_pair_eigenvalue, &
                     channel_density_diag, channel_density_max, channel_density_metric, &
                     channel_density_offdiag, channel_density_weight)

      END SUBROUTINE audit_kpoint_ot_canonical_density

! **************************************************************************************************
!> \brief ...
! **************************************************************************************************
      SUBROUTINE update_kpoint_ot_schur_line_search_quality()

      INTEGER                                            :: local_channel, samples
      LOGICAL :: closure_vector_shadow_quality_ready, density_stationarity_quality_ready, &
         mermin_search, projector_plateau_gap_quality_ready, spectral_selected_ema_ok, &
         spectral_selected_recent_ok, spectral_shadow_probe_quality_ready
      REAL(KIND=dp) :: calibrated_predicted_drop, calibrated_quality_ratio, &
         closure_candidate_predicted_drop, closure_candidate_quality_ratio, &
         closure_full_shadow_advantage, closure_full_shadow_baseline_error, &
         closure_full_shadow_baseline_predicted_drop, closure_full_shadow_predicted_drop, &
         closure_full_shadow_quality_ratio, closure_full_shadow_relative_error, &
         closure_shadow_advantage, closure_shadow_baseline_error, &
         closure_shadow_baseline_predicted_drop, closure_shadow_predicted_drop, &
         closure_shadow_quality_ratio, closure_shadow_relative_error, &
         closure_vector_shadow_advantage
      REAL(KIND=dp) :: closure_vector_shadow_baseline_error, &
         closure_vector_shadow_baseline_predicted_drop, closure_vector_shadow_candidate_error, &
         closure_vector_shadow_predicted_drop, closure_vector_shadow_quality_ratio, &
         constrained_calibrated_predicted_drop, constrained_calibrated_quality_ratio, &
         constrained_predicted_drop, constrained_quality_ratio, &
         dense_metric_shadow_predicted_drop, dense_metric_shadow_quality_ratio, &
         density_candidate_residual_quality_ratio, density_stationarity_quality_ratio, &
         gauge_residual_quality_ratio, line_search_model_drop, line_search_model_position
      REAL(KIND=dp) :: line_search_model_scale, measured_drop, metric_residual_quality, &
         multisecant_predicted_drop, multisecant_quality_ratio, occgap_shadow_predicted_drop, &
         occgap_shadow_quality_ratio, predicted_drop, prediction_predicted_drop, &
         prediction_quality_ratio, projector_density_audit_amplification_quality, &
         projector_density_audit_lowcurv_quality, projector_density_audit_quality_ratio, &
         projector_density_descent_base_predicted_drop, &
         projector_density_descent_incremental_measured_drop, &
         projector_density_descent_incremental_predicted_drop
      REAL(KIND=dp) :: projector_density_descent_incremental_quality_ratio, &
         projector_density_descent_predicted_drop, projector_density_descent_quality_ratio, &
         projector_density_descent_selected_predicted_drop, &
         projector_density_descent_selected_quality_ratio, projector_density_descent_support, &
         projector_density_full_direct_predicted_drop, &
         projector_density_full_direct_quality_ratio, &
         projector_density_full_direct_selected_predicted_drop, &
         projector_density_full_direct_selected_quality_ratio, &
         projector_density_full_global_predicted_drop, projector_density_full_global_quality_ratio
      REAL(KIND=dp) :: projector_density_full_global_selected_predicted_drop, &
         projector_density_full_global_selected_quality_ratio, projector_density_full_min_drop, &
         projector_density_full_predicted_drop, projector_density_full_quality_ratio, &
         projector_density_full_selected_predicted_drop, &
         projector_density_full_selected_quality_ratio, projector_density_lowcurv_quality, &
         projector_density_lowcurv_ratio, projector_density_predicted_drop, &
         projector_density_quality_ratio, projector_diagref_correction_ratio, &
         projector_diagref_predicted_drop, projector_diagref_quality_ratio
      REAL(KIND=dp) :: projector_inactive_offdiag_abs_ratio, projector_inactive_offdiag_negative, &
         projector_inactive_offdiag_predicted_drop, projector_inactive_offdiag_quality_ratio, &
         projector_inactive_offdiag_selected_predicted_drop, &
         projector_inactive_offdiag_selected_quality_ratio, &
         projector_inactive_offdiag_signed_ratio, projector_inactive_offdiag_step_negative, &
         projector_mixed_direct_predicted_drop, projector_mixed_direct_quality_ratio, &
         projector_mode_predicted_drop, projector_mode_quality_ratio, &
         projector_mode_response_drop_ratio, projector_mode_response_negative
      REAL(KIND=dp) :: projector_mode_step_negative, projector_mode_trust, &
         projector_offdiag_abs_ratio, projector_offdiag_negative, &
         projector_offdiag_predicted_drop, projector_offdiag_quality_ratio, &
         projector_offdiag_selected_predicted_drop, projector_offdiag_selected_quality_ratio, &
         projector_offdiag_signed_ratio, projector_offdiag_step_negative, &
         projector_physical_compensation_quality, projector_physical_compensation_ratio, &
         projector_physical_correction_quality, projector_physical_correction_ratio, &
         projector_physical_direct_density_cshadow_coverage
      REAL(KIND=dp) :: projector_physical_direct_density_cshadow_predicted_drop, &
         projector_physical_direct_density_cshadow_quality_ratio, &
         projector_physical_direct_density_fshadow_coverage, &
         projector_physical_direct_density_fshadow_predicted_drop, &
         projector_physical_direct_density_fshadow_quality_ratio, &
         projector_physical_direct_density_selected_predicted_drop, &
         projector_physical_direct_density_selected_quality_ratio, &
         projector_physical_direct_predicted_drop, projector_physical_direct_quality, &
         projector_physical_direct_quality_ratio, projector_physical_direct_ratio
      REAL(KIND=dp) :: projector_physical_direct_selected_predicted_drop, &
         projector_physical_direct_selected_quality_ratio, projector_physical_metric_quality, &
         projector_physical_metric_ratio, projector_physical_negative_quality, &
         projector_physical_predicted_drop, projector_physical_quality_ratio, &
         projector_physical_selected_predicted_drop, projector_physical_selected_quality, &
         projector_physical_selected_quality_ratio, projector_physical_selected_ratio, &
         projector_physical_shift_quality, projector_physical_shift_ratio, &
         projector_physical_trace_active_avg, projector_physical_trace_active_diag_avg
      REAL(KIND=dp) :: projector_physical_trace_active_diag_quality, &
         projector_physical_trace_active_free_avg, projector_physical_trace_active_free_quality, &
         projector_physical_trace_active_quality, projector_physical_trace_actual_avg, &
         projector_physical_trace_actual_diag_avg, projector_physical_trace_actual_diag_quality, &
         projector_physical_trace_actual_free_avg, projector_physical_trace_actual_free_quality, &
         projector_physical_trace_actual_quality, projector_physical_trace_invariant_avg, &
         projector_physical_trace_invariant_diag_avg, &
         projector_physical_trace_invariant_diag_quality
      REAL(KIND=dp) :: projector_physical_trace_invariant_free_avg, &
         projector_physical_trace_invariant_free_quality, &
         projector_physical_trace_invariant_quality, projector_physical_trace_raw_avg, &
         projector_physical_trace_raw_diag_avg, projector_physical_trace_raw_diag_quality, &
         projector_physical_trace_raw_free_avg, projector_physical_trace_raw_free_quality, &
         projector_physical_trace_raw_quality, projector_physical_weight_quality, &
         projector_plateau_gap_advantage, projector_plateau_gap_baseline_error, &
         projector_plateau_gap_baseline_predicted_drop, projector_plateau_gap_candidate_error
      REAL(KIND=dp) :: projector_plateau_gap_predicted_drop, projector_plateau_gap_quality_ratio, &
         projector_response_predicted_drop, projector_response_quality_ratio, &
         projector_response_selected_predicted_drop, projector_response_selected_quality_ratio, &
         projector_spectral_predicted_drop, projector_spectral_quality_ratio, &
         projector_spectral_selected_predicted_drop, projector_spectral_selected_quality_ratio, &
         quality_ratio, raw_residual_quality_ratio, reduced_secant_predicted_drop, &
         reduced_secant_quality_ratio, residual_current_delta, residual_drop, &
         residual_quality_ratio, sample_accepted_drop
      REAL(KIND=dp) :: sample_gap, sample_gap_ratio, sample_quality, sample_reference_drop, &
         split_shadow_calibrated_predicted_drop, split_shadow_calibrated_quality_ratio, &
         split_shadow_predicted_drop, split_shadow_quality_ratio, vector_secant_predicted_drop, &
         vector_secant_quality_ratio
      TYPE(cp_logger_type), POINTER                      :: logger

         IF (.NOT. local_ot_env(1)%schur_model_pending) RETURN
         IF (local_ot_env(1)%line_search_count <= 0) RETURN
         IF (.NOT. local_ot_env(1)%line_search_might_be_done) RETURN

         mermin_search = qs_ot_occupation_preconditioner_active(local_ot_env(1))
         IF (mermin_search) THEN
            mermin_search = .FALSE.
            DO local_channel = 1, SIZE(local_ot_env)
               IF (local_ot_env(local_channel)%has_complex_kpoint_state) THEN
                  mermin_search = .TRUE.
                  EXIT
               END IF
            END DO
         END IF

         predicted_drop = local_ot_env(1)%schur_model_drop
         calibrated_predicted_drop = local_ot_env(1)%schur_model_calibrated_drop
         line_search_model_position = MAX(0.0_dp, local_ot_env(1)%mermin_ls_next_pos)
         IF (line_search_model_position <= EPSILON(line_search_model_position) .AND. &
             local_ot_env(1)%mermin_ls_best_sample_index > 0) &
            line_search_model_position = MAX(0.0_dp, local_ot_env(1)%mermin_ls_best_sample_pos)
         line_search_model_drop = qs_scf_kp_quadratic_position_drop( &
                                  local_ot_env(1)%schur_model_slope, &
                                  local_ot_env(1)%schur_model_quadratic, &
                                  line_search_model_position)
         line_search_model_scale = 1.0_dp
         IF (predicted_drop > EPSILON(predicted_drop) .AND. &
             line_search_model_position > EPSILON(line_search_model_position) .AND. &
             line_search_model_drop > 0.0_dp) THEN
            line_search_model_scale = line_search_model_drop/predicted_drop
            predicted_drop = line_search_model_drop
            calibrated_predicted_drop = line_search_model_scale*calibrated_predicted_drop
         END IF
         IF (calibrated_predicted_drop <= EPSILON(calibrated_predicted_drop)) &
            calibrated_predicted_drop = predicted_drop
         local_ot_env(1)%schur_residual_history_reset_pending = .FALSE.
         local_ot_env(1)%schur_residual_history_quality = 1.0_dp
         measured_drop = local_ot_env(1)%OT_energy(1) - local_ot_env(1)%etotal
         local_ot_env(1)%schur_model_measured_drop = measured_drop
         local_ot_env(1)%schur_last_accepted_flavor = 0
         IF (mermin_search .AND. measured_drop > 0.0_dp .AND. &
             local_ot_env(1)%schur_model_flavor > 0) &
            local_ot_env(1)%schur_last_accepted_flavor = local_ot_env(1)%schur_model_flavor
         logger => cp_get_default_logger()
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I4,6(1X,ES16.8))') &
            " OT Schur accepted-position model flavor pos slope quad unit_drop pos_drop scale:", &
            local_ot_env(1)%schur_model_flavor, line_search_model_position, &
            local_ot_env(1)%schur_model_slope, local_ot_env(1)%schur_model_quadratic, &
            local_ot_env(1)%schur_model_drop, line_search_model_drop, line_search_model_scale
         CALL qs_scf_loop_sync_ot_kp_global_delta(local_ot_env, para_env_inter_kp, residual_current_delta)
         residual_current_delta = MAX(residual_current_delta, 0.0_dp)
         residual_drop = MAX(0.0_dp, local_ot_env(1)%schur_model_delta - residual_current_delta)
         local_ot_env(1)%schur_model_residual_drop = residual_drop
         residual_quality_ratio = 0.0_dp
         IF (mermin_search .AND. local_ot_env(1)%schur_model_delta > EPSILON(residual_current_delta)) &
            residual_quality_ratio = residual_drop/local_ot_env(1)%schur_model_delta
         density_stationarity_quality_ready = mermin_search .AND. measured_drop > 0.0_dp .AND. &
                                              local_ot_env(1)%kpoint_density_stationarity_ready .AND. &
                                              local_ot_env(1)%schur_model_density_stationarity_delta > &
                                              EPSILON(1.0_dp)
         density_stationarity_quality_ratio = 0.0_dp
         IF (density_stationarity_quality_ready) THEN
            density_stationarity_quality_ratio = qs_scf_kp_density_stationarity_quality( &
                                                 local_ot_env(1)%schur_model_density_stationarity_delta, &
                                                 local_ot_env(1)%kpoint_density_stationarity_delta)
            local_ot_env(1)%schur_density_stationarity_quality = &
               density_stationarity_quality_ratio
            samples = MIN(local_ot_env(1)%schur_density_stationarity_quality_samples + 1, &
                          HUGE(samples) - 1)
            local_ot_env(1)%schur_density_stationarity_quality_samples = samples
            IF (samples == 1) THEN
               local_ot_env(1)%schur_density_stationarity_quality_ema = &
                  density_stationarity_quality_ratio
            ELSE
               local_ot_env(1)%schur_density_stationarity_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_density_stationarity_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*density_stationarity_quality_ratio
            END IF
         END IF
         density_candidate_residual_quality_ratio = &
            qs_scf_kp_density_candidate_residual_quality( &
            residual_quality_ratio, density_stationarity_quality_ratio, &
            density_stationarity_quality_ready)
         raw_residual_quality_ratio = residual_quality_ratio
         sample_gap = 0.0_dp
         sample_quality = 1.0_dp
         sample_reference_drop = 0.0_dp
         IF (mermin_search .AND. local_ot_env(1)%mermin_ls_sample_pending) THEN
            sample_reference_drop = local_ot_env(1)%mermin_ls_best_sample_drop
            IF (sample_reference_drop > EPSILON(sample_reference_drop)) THEN
               sample_accepted_drop = local_ot_env(1)%mermin_ls_reference_energy - local_ot_env(1)%etotal
               sample_gap = local_ot_env(1)%etotal - local_ot_env(1)%mermin_ls_best_sample_energy
               sample_quality = sample_accepted_drop/sample_reference_drop
               sample_quality = MAX(0.0_dp, MIN(1.0_dp, sample_quality))
               sample_gap_ratio = MAX(0.0_dp, sample_gap/sample_reference_drop)
               sample_gap_ratio = MIN(1.0_dp, sample_gap_ratio)

               local_ot_env(1)%mermin_ls_accepted_quality = sample_quality
               local_ot_env(1)%mermin_ls_accepted_gap = sample_gap_ratio
               samples = MIN(local_ot_env(1)%mermin_ls_accepted_quality_samples + 1, HUGE(samples) - 1)
               local_ot_env(1)%mermin_ls_accepted_quality_samples = samples
               local_ot_env(1)%kpoint_subspace_accepted_samples = &
                  MIN(local_ot_env(1)%kpoint_subspace_accepted_samples + 1, HUGE(samples) - 1)
               metric_residual_quality = MAX(0.0_dp, MIN(1.0_dp, raw_residual_quality_ratio))
               IF (samples == 1) THEN
                  local_ot_env(1)%mermin_ls_accepted_quality_ema = sample_quality
                  local_ot_env(1)%mermin_ls_accepted_gap_ema = sample_gap_ratio
                  local_ot_env(1)%kpoint_occ_metric_residual_quality_ema = metric_residual_quality
               ELSE
                  local_ot_env(1)%mermin_ls_accepted_quality_ema = &
                     (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                     local_ot_env(1)%mermin_ls_accepted_quality_ema + &
                     ot_kp_schur_quality_ema_alpha*sample_quality
                  local_ot_env(1)%mermin_ls_accepted_gap_ema = &
                     (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                     local_ot_env(1)%mermin_ls_accepted_gap_ema + &
                     ot_kp_schur_quality_ema_alpha*sample_gap_ratio
                  local_ot_env(1)%kpoint_occ_metric_residual_quality_ema = &
                     (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                     local_ot_env(1)%kpoint_occ_metric_residual_quality_ema + &
                     ot_kp_schur_quality_ema_alpha*metric_residual_quality
               END IF

               IF (sample_gap > 0.0_dp) residual_quality_ratio = MIN(residual_quality_ratio, sample_quality)
               logger => cp_get_default_logger()
               IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) THEN
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I6,9(1X,ES16.8))') &
                     " OT Schur Mermin LS accepted-state calibration n q qema gap gema raw_res rema resid adrop bdrop:", &
                     local_ot_env(1)%mermin_ls_accepted_quality_samples, &
                     sample_quality, local_ot_env(1)%mermin_ls_accepted_quality_ema, &
                     sample_gap_ratio, local_ot_env(1)%mermin_ls_accepted_gap_ema, &
                     raw_residual_quality_ratio, &
                     local_ot_env(1)%kpoint_occ_metric_residual_quality_ema, residual_quality_ratio, &
                     sample_accepted_drop, sample_reference_drop
               END IF
            END IF
         END IF
         IF (mermin_search .AND. .NOT. local_ot_env(1)%schur_history_mixed .AND. &
             sample_reference_drop > EPSILON(sample_reference_drop) .AND. &
             measured_drop > 0.0_dp .AND. &
             local_ot_env(1)%schur_model_delta > EPSILON(local_ot_env(1)%schur_model_delta)) THEN
            local_ot_env(1)%schur_closure_response_pending = .TRUE.
            local_ot_env(1)%schur_closure_response_model_delta = &
               local_ot_env(1)%schur_model_delta
            local_ot_env(1)%schur_closure_response_model_density_delta = &
               local_ot_env(1)%schur_model_density_stationarity_delta
         END IF
         closure_shadow_baseline_predicted_drop = 0.0_dp
         closure_shadow_predicted_drop = 0.0_dp
         closure_shadow_quality_ratio = 0.0_dp
         closure_shadow_advantage = 0.0_dp
         closure_shadow_baseline_error = 1.0_dp
         closure_shadow_relative_error = 1.0_dp
         IF (mermin_search .AND. local_ot_env(1)%schur_closure_shadow_pending) THEN
            closure_shadow_baseline_predicted_drop = qs_scf_kp_quadratic_position_drop( &
                                                     local_ot_env(1)%schur_model_slope, &
                                                     local_ot_env(1)%schur_model_quadratic + &
                                                     local_ot_env(1)% &
                                                     schur_closure_shadow_baseline_quadratic, &
                                                     line_search_model_position)
            closure_shadow_predicted_drop = qs_scf_kp_quadratic_position_drop( &
                                            local_ot_env(1)%schur_model_slope, &
                                            local_ot_env(1)%schur_model_quadratic + &
                                            local_ot_env(1)%schur_closure_shadow_quadratic, &
                                            line_search_model_position)
            IF (closure_shadow_predicted_drop > EPSILON(closure_shadow_predicted_drop) .AND. &
                closure_shadow_baseline_predicted_drop > &
                EPSILON(closure_shadow_baseline_predicted_drop) .AND. measured_drop > 0.0_dp) THEN
               closure_shadow_quality_ratio = measured_drop/closure_shadow_predicted_drop
               closure_shadow_baseline_error = &
                  ABS(measured_drop - closure_shadow_baseline_predicted_drop)/ &
                  MAX(measured_drop, closure_shadow_baseline_predicted_drop)
               closure_shadow_relative_error = ABS(measured_drop - closure_shadow_predicted_drop)/ &
                                               MAX(measured_drop, closure_shadow_predicted_drop)
               closure_shadow_advantage = closure_shadow_baseline_error - closure_shadow_relative_error
               samples = MIN(local_ot_env(1)%schur_closure_shadow_quality_samples + 1, &
                             HUGE(samples) - 1)
               local_ot_env(1)%schur_closure_shadow_quality_samples = samples
               local_ot_env(1)%schur_closure_shadow_quality = closure_shadow_quality_ratio
               local_ot_env(1)%schur_closure_shadow_advantage = closure_shadow_advantage
               local_ot_env(1)%schur_closure_shadow_residual_quality = raw_residual_quality_ratio
               IF (samples == 1) THEN
                  local_ot_env(1)%schur_closure_shadow_quality_ema = closure_shadow_quality_ratio
                  local_ot_env(1)%schur_closure_shadow_advantage_ema = closure_shadow_advantage
                  local_ot_env(1)%schur_closure_shadow_residual_quality_ema = raw_residual_quality_ratio
               ELSE
                  local_ot_env(1)%schur_closure_shadow_quality_ema = &
                     (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                     local_ot_env(1)%schur_closure_shadow_quality_ema + &
                     ot_kp_schur_quality_ema_alpha*closure_shadow_quality_ratio
                  local_ot_env(1)%schur_closure_shadow_advantage_ema = &
                     (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                     local_ot_env(1)%schur_closure_shadow_advantage_ema + &
                     ot_kp_schur_quality_ema_alpha*closure_shadow_advantage
                  local_ot_env(1)%schur_closure_shadow_residual_quality_ema = &
                     (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                     local_ot_env(1)%schur_closure_shadow_residual_quality_ema + &
                     ot_kp_schur_quality_ema_alpha*raw_residual_quality_ratio
               END IF
               local_ot_env(1)%schur_closure_shadow_drop_sum = &
                  local_ot_env(1)%schur_closure_shadow_drop_sum + closure_shadow_predicted_drop
               local_ot_env(1)%schur_closure_shadow_measured_sum = &
                  local_ot_env(1)%schur_closure_shadow_measured_sum + measured_drop
            END IF
            logger => cp_get_default_logger()
            IF (logger%iter_info%print_level >= debug_print_level .AND. &
                logger%para_env%is_source()) &
               WRITE (cp_logger_get_default_unit_nr(logger), &
                      '(A,1X,I6,9(1X,ES16.8))') &
               " OT Schur closure shadow history n base shadow measured q qema berr serr adv aema:", &
               local_ot_env(1)%schur_closure_shadow_quality_samples, &
               closure_shadow_baseline_predicted_drop, &
               closure_shadow_predicted_drop, measured_drop, closure_shadow_quality_ratio, &
               local_ot_env(1)%schur_closure_shadow_quality_ema, closure_shadow_baseline_error, &
               closure_shadow_relative_error, closure_shadow_advantage, &
               local_ot_env(1)%schur_closure_shadow_advantage_ema
         END IF
         closure_full_shadow_baseline_predicted_drop = 0.0_dp
         closure_full_shadow_predicted_drop = 0.0_dp
         closure_full_shadow_quality_ratio = 0.0_dp
         closure_full_shadow_advantage = 0.0_dp
         closure_full_shadow_baseline_error = 1.0_dp
         closure_full_shadow_relative_error = 1.0_dp
         IF (mermin_search .AND. local_ot_env(1)%schur_closure_full_shadow_pending) THEN
            closure_full_shadow_baseline_predicted_drop = qs_scf_kp_quadratic_position_drop( &
                                                          local_ot_env(1)%schur_model_slope, &
                                                          local_ot_env(1)%schur_model_quadratic + &
                                                          local_ot_env(1)% &
                                                          schur_closure_full_shadow_baseline_quadratic, &
                                                          line_search_model_position)
            closure_full_shadow_predicted_drop = qs_scf_kp_quadratic_position_drop( &
                                                 local_ot_env(1)%schur_model_slope, &
                                                 local_ot_env(1)%schur_model_quadratic + &
                                                 local_ot_env(1)% &
                                                 schur_closure_full_shadow_quadratic, &
                                                 line_search_model_position)
            IF (closure_full_shadow_predicted_drop > &
                EPSILON(closure_full_shadow_predicted_drop) .AND. &
                closure_full_shadow_baseline_predicted_drop > &
                EPSILON(closure_full_shadow_baseline_predicted_drop) .AND. measured_drop > 0.0_dp) THEN
               closure_full_shadow_quality_ratio = measured_drop/closure_full_shadow_predicted_drop
               closure_full_shadow_baseline_error = &
                  ABS(measured_drop - closure_full_shadow_baseline_predicted_drop)/ &
                  MAX(measured_drop, closure_full_shadow_baseline_predicted_drop)
               closure_full_shadow_relative_error = &
                  ABS(measured_drop - closure_full_shadow_predicted_drop)/ &
                  MAX(measured_drop, closure_full_shadow_predicted_drop)
               closure_full_shadow_advantage = closure_full_shadow_baseline_error - &
                                               closure_full_shadow_relative_error
               samples = MIN(local_ot_env(1)%schur_closure_full_shadow_quality_samples + 1, &
                             HUGE(samples) - 1)
               local_ot_env(1)%schur_closure_full_shadow_quality_samples = samples
               local_ot_env(1)%schur_closure_full_shadow_quality = closure_full_shadow_quality_ratio
               local_ot_env(1)%schur_closure_full_shadow_advantage = closure_full_shadow_advantage
               IF (samples == 1) THEN
                  local_ot_env(1)%schur_closure_full_shadow_quality_ema = &
                     closure_full_shadow_quality_ratio
                  local_ot_env(1)%schur_closure_full_shadow_advantage_ema = &
                     closure_full_shadow_advantage
               ELSE
                  local_ot_env(1)%schur_closure_full_shadow_quality_ema = &
                     (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                     local_ot_env(1)%schur_closure_full_shadow_quality_ema + &
                     ot_kp_schur_quality_ema_alpha*closure_full_shadow_quality_ratio
                  local_ot_env(1)%schur_closure_full_shadow_advantage_ema = &
                     (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                     local_ot_env(1)%schur_closure_full_shadow_advantage_ema + &
                     ot_kp_schur_quality_ema_alpha*closure_full_shadow_advantage
               END IF
            END IF
            logger => cp_get_default_logger()
            IF (logger%iter_info%print_level >= debug_print_level .AND. &
                logger%para_env%is_source()) &
               WRITE (cp_logger_get_default_unit_nr(logger), &
                      '(A,1X,I6,9(1X,ES16.8))') &
               " OT Schur full closure shadow history n base candidate measured q qema "// &
               "berr cerr adv aema:", &
               local_ot_env(1)%schur_closure_full_shadow_quality_samples, &
               closure_full_shadow_baseline_predicted_drop, &
               closure_full_shadow_predicted_drop, measured_drop, &
               closure_full_shadow_quality_ratio, &
               local_ot_env(1)%schur_closure_full_shadow_quality_ema, &
               closure_full_shadow_baseline_error, closure_full_shadow_relative_error, &
               closure_full_shadow_advantage, &
               local_ot_env(1)%schur_closure_full_shadow_advantage_ema
         END IF
         closure_vector_shadow_baseline_predicted_drop = 0.0_dp
         closure_vector_shadow_predicted_drop = 0.0_dp
         closure_vector_shadow_quality_ratio = 0.0_dp
         closure_vector_shadow_advantage = 0.0_dp
         closure_vector_shadow_baseline_error = 1.0_dp
         closure_vector_shadow_candidate_error = 1.0_dp
         closure_vector_shadow_quality_ready = .FALSE.
         IF (mermin_search .AND. local_ot_env(1)%schur_closure_vector_shadow_pending) THEN
            closure_vector_shadow_baseline_predicted_drop = qs_scf_kp_quadratic_position_drop( &
                                                            local_ot_env(1)%schur_model_slope, &
                                                            local_ot_env(1)%schur_model_quadratic + &
                                                            local_ot_env(1)% &
                                                            schur_closure_vector_shadow_baseline_quadratic, &
                                                            line_search_model_position)
            closure_vector_shadow_predicted_drop = qs_scf_kp_quadratic_position_drop( &
                                                   local_ot_env(1)%schur_model_slope, &
                                                   local_ot_env(1)%schur_model_quadratic + &
                                                   local_ot_env(1)% &
                                                   schur_closure_vector_shadow_quadratic, &
                                                   line_search_model_position)
            CALL qs_scf_kp_shadow_prediction_quality( &
               closure_vector_shadow_baseline_predicted_drop, &
               closure_vector_shadow_predicted_drop, measured_drop, &
               closure_vector_shadow_quality_ratio, closure_vector_shadow_baseline_error, &
               closure_vector_shadow_candidate_error, closure_vector_shadow_advantage, &
               closure_vector_shadow_quality_ready)
            IF (closure_vector_shadow_quality_ready) THEN
               samples = MIN(local_ot_env(1)%schur_closure_vector_shadow_quality_samples + 1, &
                             HUGE(samples) - 1)
               local_ot_env(1)%schur_closure_vector_shadow_quality_samples = samples
               local_ot_env(1)%schur_closure_vector_shadow_quality = &
                  closure_vector_shadow_quality_ratio
               local_ot_env(1)%schur_closure_vector_shadow_advantage = &
                  closure_vector_shadow_advantage
               IF (samples == 1) THEN
                  local_ot_env(1)%schur_closure_vector_shadow_quality_ema = &
                     closure_vector_shadow_quality_ratio
                  local_ot_env(1)%schur_closure_vector_shadow_advantage_ema = &
                     closure_vector_shadow_advantage
               ELSE
                  local_ot_env(1)%schur_closure_vector_shadow_quality_ema = &
                     (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                     local_ot_env(1)%schur_closure_vector_shadow_quality_ema + &
                     ot_kp_schur_quality_ema_alpha*closure_vector_shadow_quality_ratio
                  local_ot_env(1)%schur_closure_vector_shadow_advantage_ema = &
                     (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                     local_ot_env(1)%schur_closure_vector_shadow_advantage_ema + &
                     ot_kp_schur_quality_ema_alpha*closure_vector_shadow_advantage
               END IF
            END IF
            IF (closure_vector_shadow_quality_ready .AND. &
                local_ot_env(1)%schur_closure_vector_shadow_work_consistent) THEN
               samples = MIN(local_ot_env(1)%schur_closure_work_shadow_quality_samples + 1, &
                             HUGE(samples) - 1)
               local_ot_env(1)%schur_closure_work_shadow_quality_samples = samples
               local_ot_env(1)%schur_closure_work_shadow_quality = &
                  closure_vector_shadow_quality_ratio
               local_ot_env(1)%schur_closure_work_shadow_advantage = &
                  closure_vector_shadow_advantage
               IF (samples == 1) THEN
                  local_ot_env(1)%schur_closure_work_shadow_quality_ema = &
                     closure_vector_shadow_quality_ratio
                  local_ot_env(1)%schur_closure_work_shadow_advantage_ema = &
                     closure_vector_shadow_advantage
               ELSE
                  local_ot_env(1)%schur_closure_work_shadow_quality_ema = &
                     (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                     local_ot_env(1)%schur_closure_work_shadow_quality_ema + &
                     ot_kp_schur_quality_ema_alpha*closure_vector_shadow_quality_ratio
                  local_ot_env(1)%schur_closure_work_shadow_advantage_ema = &
                     (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                     local_ot_env(1)%schur_closure_work_shadow_advantage_ema + &
                     ot_kp_schur_quality_ema_alpha*closure_vector_shadow_advantage
               END IF
            END IF
            logger => cp_get_default_logger()
            IF (logger%iter_info%print_level >= debug_print_level .AND. &
                logger%para_env%is_source()) &
               WRITE (cp_logger_get_default_unit_nr(logger), &
                      '(A,1X,I6,3(1X,L1),9(1X,ES16.8))') &
               " OT Schur response-vector shadow history n eligible work_eligible ready "// &
               "base candidate measured q qema "// &
               "berr cerr adv aema:", &
               local_ot_env(1)%schur_closure_vector_shadow_quality_samples, &
               local_ot_env(1)%schur_closure_vector_shadow_consistent, &
               local_ot_env(1)%schur_closure_vector_shadow_work_consistent, &
               closure_vector_shadow_quality_ready, &
               closure_vector_shadow_baseline_predicted_drop, &
               closure_vector_shadow_predicted_drop, measured_drop, &
               closure_vector_shadow_quality_ratio, &
               local_ot_env(1)%schur_closure_vector_shadow_quality_ema, &
               closure_vector_shadow_baseline_error, closure_vector_shadow_candidate_error, &
               closure_vector_shadow_advantage, &
               local_ot_env(1)%schur_closure_vector_shadow_advantage_ema
            IF (logger%iter_info%print_level >= debug_print_level .AND. &
                logger%para_env%is_source()) &
               WRITE (cp_logger_get_default_unit_nr(logger), &
                      '(A,1X,I6,2(1X,L1),4(1X,ES16.8))') &
               " OT Schur observable-work shadow history n eligible ready q qema adv aema:", &
               local_ot_env(1)%schur_closure_work_shadow_quality_samples, &
               local_ot_env(1)%schur_closure_vector_shadow_work_consistent, &
               closure_vector_shadow_quality_ready, closure_vector_shadow_quality_ratio, &
               local_ot_env(1)%schur_closure_work_shadow_quality_ema, &
               closure_vector_shadow_advantage, &
               local_ot_env(1)%schur_closure_work_shadow_advantage_ema
         END IF
         IF (mermin_search .AND. measured_drop > 0.0_dp .AND. &
             residual_quality_ratio <= EPSILON(1.0_dp) .AND. &
             local_ot_env(1)%schur_model_delta > EPSILON(local_ot_env(1)%schur_model_delta) .AND. &
             local_ot_env(1)%schur_model_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
             residual_current_delta <= (1.0_dp + ot_kp_schur_residual_tail_plateau_slack)* &
             local_ot_env(1)%schur_model_delta .AND. &
             local_ot_env(1)%mermin_ls_accepted_quality_samples >= ot_kp_schur_calibration_min_samples .AND. &
             local_ot_env(1)%mermin_ls_accepted_quality_ema >= 0.8_dp .AND. &
             sample_quality >= 0.8_dp) THEN
            residual_quality_ratio = ot_kp_schur_residual_tail_plateau_quality* &
                                     MIN(sample_quality, local_ot_env(1)%mermin_ls_accepted_quality_ema)
            logger => cp_get_default_logger()
            IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) THEN
               WRITE (cp_logger_get_default_unit_nr(logger), '(A,5(1X,ES16.8))') &
                  " OT Schur residual-tail plateau quality q raw_q delta current mermin_q:", &
                  residual_quality_ratio, raw_residual_quality_ratio, &
                  local_ot_env(1)%schur_model_delta, residual_current_delta, &
                  local_ot_env(1)%mermin_ls_accepted_quality_ema
            END IF
         END IF
         IF (mermin_search .AND. measured_drop > 0.0_dp .AND. &
             local_ot_env(1)%schur_model_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
             qs_scf_kp_residual_history_reset_needed( &
             local_ot_env(1)%schur_model_delta, residual_current_delta, &
             ot_kp_schur_residual_tail_plateau_slack)) THEN
            local_ot_env(1)%schur_residual_history_reset_pending = .TRUE.
            local_ot_env(1)%schur_residual_history_quality = residual_quality_ratio
            logger => cp_get_default_logger()
            IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) THEN
               WRITE (cp_logger_get_default_unit_nr(logger), '(A,4(1X,ES16.8))') &
                  " OT Schur residual-aware CG reset marked q raw_q delta current:", &
                  residual_quality_ratio, raw_residual_quality_ratio, &
                  local_ot_env(1)%schur_model_delta, residual_current_delta
            END IF
         END IF
         IF (local_ot_env(1)%schur_history_mixed) THEN
            logger => cp_get_default_logger()
            IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) THEN
               WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I6,3(1X,ES16.8))') &
                  " OT Schur LS quality skipped mixed CG history attempt pred cal meas:", &
                  local_ot_env(1)%schur_model_attempt, predicted_drop, &
                  calibrated_predicted_drop, measured_drop
            END IF
            local_ot_env(1)%schur_model_pending = .FALSE.
            local_ot_env(1)%schur_constrained_pending = .FALSE.
            local_ot_env(1)%schur_split_shadow_pending = .FALSE.
            local_ot_env(1)%schur_occgap_shadow_pending = .FALSE.
            local_ot_env(1)%schur_vector_secant_pending = .FALSE.
            local_ot_env(1)%schur_multisecant_pending = .FALSE.
            local_ot_env(1)%schur_prediction_pending = .FALSE.
            local_ot_env(1)%schur_reduced_secant_pending = .FALSE.
            local_ot_env(1)%schur_closure_shadow_pending = .FALSE.
            local_ot_env(1)%schur_closure_shadow_baseline_quadratic = 0.0_dp
            local_ot_env(1)%schur_closure_shadow_quadratic = 0.0_dp
            local_ot_env(1)%schur_closure_full_shadow_pending = .FALSE.
            local_ot_env(1)%schur_closure_full_shadow_baseline_quadratic = 0.0_dp
            local_ot_env(1)%schur_closure_full_shadow_quadratic = 0.0_dp
            local_ot_env(1)%schur_closure_vector_shadow_pending = .FALSE.
            local_ot_env(1)%schur_closure_vector_shadow_consistent = .FALSE.
            local_ot_env(1)%schur_closure_vector_shadow_work_consistent = .FALSE.
            local_ot_env(1)%schur_closure_vector_shadow_baseline_quadratic = 0.0_dp
            local_ot_env(1)%schur_closure_vector_shadow_quadratic = 0.0_dp
            local_ot_env(1)%schur_reduced_secant_model_groups = 0
            local_ot_env(1)%schur_reduced_secant_selected_groups = 0
            local_ot_env(1)%schur_reduced_secant_rot_residual_start_sq = 0.0_dp
            local_ot_env(1)%schur_reduced_secant_rot_residual_delta_dot = 0.0_dp
            local_ot_env(1)%schur_reduced_secant_rot_residual_delta_sq = 0.0_dp
            local_ot_env(1)%schur_closure_candidate_pending = .FALSE.
            local_ot_env(1)%schur_closure_candidate_model_groups = 0
            local_ot_env(1)%schur_closure_candidate_selected_groups = 0
            local_ot_env(1)%schur_closure_candidate_rot_residual_start_sq = 0.0_dp
            local_ot_env(1)%schur_closure_candidate_rot_residual_delta_dot = 0.0_dp
            local_ot_env(1)%schur_closure_candidate_rot_residual_delta_sq = 0.0_dp
            local_ot_env(1)%schur_projector_mode_pending = .FALSE.
            local_ot_env(1)%schur_projector_offdiag_pending = .FALSE.
            local_ot_env(1)%schur_projector_inactive_offdiag_pending = .FALSE.
            local_ot_env(1)%schur_projector_response_pending = .FALSE.
            local_ot_env(1)%schur_projector_plateau_gap_pending = .FALSE.
            local_ot_env(1)%schur_projector_physical_pending = .FALSE.
            local_ot_env(1)%schur_projector_mixed_direct_pending = .FALSE.
            local_ot_env(1)%schur_projector_spectral_pending = .FALSE.
            local_ot_env(1)%schur_projector_diagref_pending = .FALSE.
            local_ot_env(1)%schur_projector_density_pending = .FALSE.
            local_ot_env(1)%schur_projector_density_audit_pending = .FALSE.
            local_ot_env(1)%schur_projector_density_descent_pending = .FALSE.
            local_ot_env(1)%schur_projector_density_full_pending = .FALSE.
            local_ot_env(1)%schur_projector_density_full_direct_pending = .FALSE.
            local_ot_env(1)%schur_projector_density_full_global_pending = .FALSE.
            local_ot_env(1)%schur_dense_metric_shadow_pending = .FALSE.
            local_ot_env(1)%schur_history_mixed = .FALSE.
            local_ot_env(1)%schur_model_flavor = 0
            RETURN
         END IF
         gauge_residual_quality_ratio = &
            kpoint_ot_step_gauge_residual_quality(raw_residual_quality_ratio, residual_quality_ratio)
         quality_ratio = 0.0_dp
         calibrated_quality_ratio = 0.0_dp
         IF (mermin_search .AND. predicted_drop > EPSILON(predicted_drop)) &
            quality_ratio = measured_drop/predicted_drop
         IF (mermin_search .AND. calibrated_predicted_drop > EPSILON(calibrated_predicted_drop)) &
            calibrated_quality_ratio = measured_drop/calibrated_predicted_drop
         IF (mermin_search .AND. sample_gap > 0.0_dp .AND. &
             sample_reference_drop > EPSILON(sample_reference_drop)) THEN
            quality_ratio = MIN(quality_ratio, sample_quality)
            calibrated_quality_ratio = MIN(calibrated_quality_ratio, sample_quality)
         END IF

         IF (mermin_search .AND. predicted_drop > EPSILON(predicted_drop) .AND. measured_drop > 0.0_dp) THEN
            local_ot_env(1)%schur_model_quality = quality_ratio
            local_ot_env(1)%schur_model_calibrated_quality = calibrated_quality_ratio
            samples = MIN(local_ot_env(1)%schur_model_quality_samples + 1, HUGE(samples) - 1)
            local_ot_env(1)%schur_model_quality_samples = samples
            IF (samples == 1) THEN
               local_ot_env(1)%schur_model_quality_ema = quality_ratio
               local_ot_env(1)%schur_model_calibrated_quality_ema = calibrated_quality_ratio
            ELSE
               local_ot_env(1)%schur_model_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)*local_ot_env(1)%schur_model_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*quality_ratio
               local_ot_env(1)%schur_model_calibrated_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_model_calibrated_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*calibrated_quality_ratio
            END IF
            ! Ratios above one mean the accepted Mermin drop was larger than
            ! predicted.  Treat that as conservative calibration evidence; the
            ! step-size model below still clamps how much of it can be used.
            local_ot_env(1)%schur_model_quality_ready = &
               samples >= ot_kp_schur_quality_min_samples .AND. &
               local_ot_env(1)%schur_model_quality_ema >= ot_kp_schur_quality_min_ratio .AND. &
               quality_ratio >= 0.5_dp*ot_kp_schur_quality_min_ratio
         ELSE
            local_ot_env(1)%schur_model_quality = 0.0_dp
            local_ot_env(1)%schur_model_quality_ema = 0.0_dp
            local_ot_env(1)%schur_model_calibrated_quality = 0.0_dp
            local_ot_env(1)%schur_model_calibrated_quality_ema = 0.0_dp
            local_ot_env(1)%schur_model_quality_samples = 0
            local_ot_env(1)%schur_model_quality_ready = .FALSE.
         END IF
         IF (mermin_search .AND. predicted_drop > EPSILON(predicted_drop) .AND. measured_drop > 0.0_dp .AND. &
             local_ot_env(1)%schur_step_gauge_ratio > EPSILON(local_ot_env(1)%schur_step_gauge_ratio)) THEN
            samples = MIN(local_ot_env(1)%schur_step_gauge_quality_samples + 1, HUGE(samples) - 1)
            local_ot_env(1)%schur_step_gauge_quality_samples = samples
            local_ot_env(1)%schur_step_gauge_residual_quality = gauge_residual_quality_ratio
            IF (samples == 1) THEN
               local_ot_env(1)%schur_step_gauge_ratio_ema = local_ot_env(1)%schur_step_gauge_ratio
               local_ot_env(1)%schur_step_gauge_residual_quality_ema = gauge_residual_quality_ratio
            ELSE
               local_ot_env(1)%schur_step_gauge_ratio_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_step_gauge_ratio_ema + &
                  ot_kp_schur_quality_ema_alpha*local_ot_env(1)%schur_step_gauge_ratio
               local_ot_env(1)%schur_step_gauge_residual_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_step_gauge_residual_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*gauge_residual_quality_ratio
            END IF
         END IF
         constrained_predicted_drop = local_ot_env(1)%schur_constrained_drop
         constrained_calibrated_predicted_drop = local_ot_env(1)%schur_constrained_calibrated_drop
         IF (constrained_calibrated_predicted_drop <= EPSILON(constrained_calibrated_predicted_drop)) &
            constrained_calibrated_predicted_drop = constrained_predicted_drop
         constrained_quality_ratio = 0.0_dp
         constrained_calibrated_quality_ratio = 0.0_dp
         IF (mermin_search .AND. local_ot_env(1)%schur_constrained_pending .AND. &
             constrained_predicted_drop > EPSILON(constrained_predicted_drop) .AND. measured_drop > 0.0_dp) THEN
            constrained_quality_ratio = measured_drop/constrained_predicted_drop
            IF (constrained_calibrated_predicted_drop > EPSILON(constrained_calibrated_predicted_drop)) &
               constrained_calibrated_quality_ratio = measured_drop/constrained_calibrated_predicted_drop
            local_ot_env(1)%schur_constrained_quality = constrained_quality_ratio
            local_ot_env(1)%schur_constrained_calibrated_quality = constrained_calibrated_quality_ratio
            samples = MIN(local_ot_env(1)%schur_constrained_quality_samples + 1, HUGE(samples) - 1)
            local_ot_env(1)%schur_constrained_quality_samples = samples
            IF (samples == 1) THEN
               local_ot_env(1)%schur_constrained_quality_ema = constrained_quality_ratio
               local_ot_env(1)%schur_constrained_calibrated_quality_ema = constrained_calibrated_quality_ratio
            ELSE
               local_ot_env(1)%schur_constrained_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)*local_ot_env(1)%schur_constrained_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*constrained_quality_ratio
               local_ot_env(1)%schur_constrained_calibrated_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_constrained_calibrated_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*constrained_calibrated_quality_ratio
            END IF
            local_ot_env(1)%schur_constrained_drop_sum = &
               local_ot_env(1)%schur_constrained_drop_sum + constrained_predicted_drop
            local_ot_env(1)%schur_constrained_calibrated_drop_sum = &
               local_ot_env(1)%schur_constrained_calibrated_drop_sum + constrained_calibrated_predicted_drop
            local_ot_env(1)%schur_constrained_measured_sum = &
               local_ot_env(1)%schur_constrained_measured_sum + measured_drop
         ELSE IF (local_ot_env(1)%schur_constrained_pending) THEN
            local_ot_env(1)%schur_constrained_quality = 0.0_dp
            local_ot_env(1)%schur_constrained_quality_ema = 0.0_dp
            local_ot_env(1)%schur_constrained_calibrated_quality = 0.0_dp
            local_ot_env(1)%schur_constrained_calibrated_quality_ema = 0.0_dp
            local_ot_env(1)%schur_constrained_quality_samples = 0
         END IF
         split_shadow_predicted_drop = local_ot_env(1)%schur_split_shadow_drop
         split_shadow_calibrated_predicted_drop = local_ot_env(1)%schur_split_shadow_calibrated_drop
         IF (split_shadow_calibrated_predicted_drop <= EPSILON(split_shadow_calibrated_predicted_drop)) &
            split_shadow_calibrated_predicted_drop = split_shadow_predicted_drop
         split_shadow_quality_ratio = 0.0_dp
         split_shadow_calibrated_quality_ratio = 0.0_dp
         IF (mermin_search .AND. local_ot_env(1)%schur_split_shadow_pending .AND. &
             split_shadow_predicted_drop > EPSILON(split_shadow_predicted_drop) .AND. measured_drop > 0.0_dp) THEN
            split_shadow_quality_ratio = measured_drop/split_shadow_predicted_drop
            IF (split_shadow_calibrated_predicted_drop > EPSILON(split_shadow_calibrated_predicted_drop)) &
               split_shadow_calibrated_quality_ratio = measured_drop/split_shadow_calibrated_predicted_drop
            local_ot_env(1)%schur_split_shadow_quality = split_shadow_quality_ratio
            local_ot_env(1)%schur_split_shadow_calibrated_quality = split_shadow_calibrated_quality_ratio
            samples = MIN(local_ot_env(1)%schur_split_shadow_quality_samples + 1, HUGE(samples) - 1)
            local_ot_env(1)%schur_split_shadow_quality_samples = samples
            IF (samples == 1) THEN
               local_ot_env(1)%schur_split_shadow_quality_ema = split_shadow_quality_ratio
               local_ot_env(1)%schur_split_shadow_calibrated_quality_ema = split_shadow_calibrated_quality_ratio
            ELSE
               local_ot_env(1)%schur_split_shadow_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)*local_ot_env(1)%schur_split_shadow_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*split_shadow_quality_ratio
               local_ot_env(1)%schur_split_shadow_calibrated_quality_ema = &
                  (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                  local_ot_env(1)%schur_split_shadow_calibrated_quality_ema + &
                  ot_kp_schur_quality_ema_alpha*split_shadow_calibrated_quality_ratio
            END IF
            local_ot_env(1)%schur_split_shadow_drop_sum = &
               local_ot_env(1)%schur_split_shadow_drop_sum + split_shadow_predicted_drop
            local_ot_env(1)%schur_split_shadow_calibrated_drop_sum = &
               local_ot_env(1)%schur_split_shadow_calibrated_drop_sum + split_shadow_calibrated_predicted_drop
            local_ot_env(1)%schur_split_shadow_measured_sum = &
               local_ot_env(1)%schur_split_shadow_measured_sum + measured_drop
         END IF
         occgap_shadow_predicted_drop = local_ot_env(1)%schur_occgap_shadow_drop
