               local_ot_env(1)%schur_coupled_calibrated_quality = calibrated_quality_ratio
               samples = MIN(local_ot_env(1)%schur_coupled_quality_samples + 1, HUGE(samples) - 1)
               local_ot_env(1)%schur_coupled_quality_samples = samples
