            IF (measured_drop > 0.0_dp) THEN
               projector_spectral_selected_quality_ratio = &
                  measured_drop/projector_spectral_selected_predicted_drop
               local_ot_env(1)%schur_projector_spectral_selected_quality = &
                  projector_spectral_selected_quality_ratio
               local_ot_env(1)%schur_projector_spectral_selected_residual_quality = &
                  residual_quality_ratio
               samples = MIN(local_ot_env(1)%schur_projector_spectral_selected_quality_samples + 1, &
                             HUGE(samples) - 1)
               local_ot_env(1)%schur_projector_spectral_selected_quality_samples = samples
               IF (samples == 1) THEN
                  local_ot_env(1)%schur_projector_spectral_selected_quality_ema = &
                     projector_spectral_selected_quality_ratio
                  local_ot_env(1)%schur_projector_spectral_selected_residual_quality_ema = &
                     residual_quality_ratio
               ELSE
                  local_ot_env(1)%schur_projector_spectral_selected_quality_ema = &
                     (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                     local_ot_env(1)%schur_projector_spectral_selected_quality_ema + &
                     ot_kp_schur_quality_ema_alpha*projector_spectral_selected_quality_ratio
                  local_ot_env(1)%schur_projector_spectral_selected_residual_quality_ema = &
                     (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
                     local_ot_env(1)%schur_projector_spectral_selected_residual_quality_ema + &
                     ot_kp_schur_quality_ema_alpha*residual_quality_ratio
               END IF
               local_ot_env(1)%schur_projector_spectral_selected_drop_sum = &
                  local_ot_env(1)%schur_projector_spectral_selected_drop_sum + &
                  projector_spectral_selected_predicted_drop
               local_ot_env(1)%schur_projector_spectral_selected_measured_sum = &
                  local_ot_env(1)%schur_projector_spectral_selected_measured_sum + measured_drop
               ! Mermin-drop quality alone is not enough in the residual tail:
               ! a severe residual miss disables selected spectral probes until
               ! the independent shadow path rebuilds evidence.
               local_ot_env(1)%schur_projector_spectral_selected_failure_samples = &
                  kpoint_ot_spectral_selected_failure_count( &
                  local_ot_env(1)%schur_projector_spectral_selected_failure_samples, &
                  projector_spectral_selected_quality_ratio, residual_quality_ratio)
            ELSE
               local_ot_env(1)%schur_projector_spectral_selected_failure_samples = &
                  ot_kp_schur_projector_spectral_probe_max_failures
               local_ot_env(1)%schur_projector_spectral_selected_quality = 0.0_dp
               local_ot_env(1)%schur_projector_spectral_selected_quality_ema = 0.0_dp
               local_ot_env(1)%schur_projector_spectral_selected_residual_quality = 0.0_dp
               local_ot_env(1)%schur_projector_spectral_selected_residual_quality_ema = 0.0_dp
            END IF
         END IF
         ! A too-large physical quality ratio means the shadow model is
         ! conservative, not unstable; selection still uses the clamped
         ! expected-drop quality below.
         local_ot_env(1)%schur_projector_physical_candidate_enabled = &
            local_ot_env(1)%schur_projector_physical_quality_samples >= &
            ot_kp_schur_projector_response_min_samples .AND. &
            local_ot_env(1)%schur_projector_physical_quality_ema >= &
            ot_kp_schur_projector_response_quality_min_ratio .AND. &
            local_ot_env(1)%schur_projector_physical_quality >= &
            0.5_dp*ot_kp_schur_projector_response_quality_min_ratio
         ! Keep the independent spectral shadow diagnostic separate from
         ! active candidate promotion; the Al residual tail shows that
         ! shadow-only promotion can be Mermin-positive but residual-bad.
         spectral_shadow_probe_quality_ready = &
            kpoint_ot_spectral_shadow_probe_quality_ready( &
            local_ot_env(1)%schur_projector_spectral_quality, &
            local_ot_env(1)%schur_projector_spectral_quality_ema, &
            local_ot_env(1)%schur_projector_spectral_quality_samples, &
            local_ot_env(1)%schur_projector_spectral_drop_sum, &
            local_ot_env(1)%schur_projector_spectral_measured_sum, &
            local_ot_env(1)%schur_projector_spectral_dot_ema, &
            local_ot_env(1)%schur_projector_spectral_norm_ema, &
            local_ot_env(1)%schur_projector_spectral_floor_ema)
         spectral_shadow_probe_quality_ready = &
            kpoint_ot_spectral_shadow_probe_bootstrap_ready( &
            spectral_shadow_probe_quality_ready, residual_quality_ratio)
         spectral_selected_ema_ok = &
            local_ot_env(1)%schur_projector_spectral_selected_quality_ema >= &
            ot_kp_schur_projector_response_quality_min_ratio .OR. &
            local_ot_env(1)%schur_projector_spectral_selected_residual_quality_ema >= &
            ot_kp_schur_projector_response_quality_min_ratio
         spectral_selected_recent_ok = &
            local_ot_env(1)%schur_projector_spectral_selected_quality >= &
            0.5_dp*ot_kp_schur_projector_response_quality_min_ratio .OR. &
            local_ot_env(1)%schur_projector_spectral_selected_residual_quality >= &
            ot_kp_schur_projector_response_quality_min_ratio
         local_ot_env(1)%schur_projector_spectral_candidate_enabled = &
            local_ot_env(1)%schur_projector_spectral_selected_failure_samples < &
            ot_kp_schur_projector_spectral_probe_max_failures .AND. &
            local_ot_env(1)%schur_projector_spectral_dot_ema > 0.0_dp .AND. &
            local_ot_env(1)%schur_projector_spectral_norm_ema > 0.0_dp .AND. &
            ((local_ot_env(1)%schur_projector_spectral_selected_quality_samples >= &
              ot_kp_schur_projector_response_min_samples .AND. &
              local_ot_env(1)%schur_projector_spectral_selected_drop_sum > &
              EPSILON(local_ot_env(1)%schur_projector_spectral_selected_drop_sum) .AND. &
              local_ot_env(1)%schur_projector_spectral_selected_measured_sum > 0.0_dp .AND. &
              spectral_selected_ema_ok .AND. spectral_selected_recent_ok) .OR. &
             (local_ot_env(1)%schur_projector_spectral_selected_quality_samples >= &
              ot_kp_schur_projector_spectral_selected_min_samples .AND. &
              local_ot_env(1)%schur_projector_spectral_selected_drop_sum > &
              EPSILON(local_ot_env(1)%schur_projector_spectral_selected_drop_sum) .AND. &
              local_ot_env(1)%schur_projector_spectral_selected_measured_sum > 0.0_dp .AND. &
              local_ot_env(1)%schur_projector_spectral_selected_residual_quality_ema >= &
              ot_kp_schur_projector_response_quality_min_ratio .AND. &
              local_ot_env(1)%schur_projector_spectral_selected_residual_quality >= &
              ot_kp_schur_projector_response_quality_min_ratio .AND. &
              spectral_selected_ema_ok .AND. spectral_selected_recent_ok) .OR. &
             (local_ot_env(1)%schur_projector_spectral_selected_quality_samples > 0 .AND. &
              local_ot_env(1)%schur_projector_spectral_selected_drop_sum > &
              EPSILON(local_ot_env(1)%schur_projector_spectral_selected_drop_sum) .AND. &
              local_ot_env(1)%schur_projector_spectral_selected_measured_sum > 0.0_dp .AND. &
              spectral_selected_ema_ok .AND. spectral_selected_recent_ok .AND. &
              local_ot_env(1)%schur_projector_spectral_quality_samples >= &
              ot_kp_schur_projector_response_min_samples .AND. &
              local_ot_env(1)%schur_projector_spectral_drop_sum > &
              EPSILON(local_ot_env(1)%schur_projector_spectral_drop_sum) .AND. &
              local_ot_env(1)%schur_projector_spectral_measured_sum > 0.0_dp .AND. &
              local_ot_env(1)%schur_projector_spectral_floor_ema > &
              EPSILON(local_ot_env(1)%schur_projector_spectral_floor_ema) .AND. &
              local_ot_env(1)%schur_projector_spectral_quality_ema >= &
              ot_kp_schur_projector_spectral_probe_quality_min .AND. &
              local_ot_env(1)%schur_projector_spectral_quality >= &
              0.5_dp*ot_kp_schur_projector_spectral_probe_quality_min))

         local_ot_env(1)%schur_split_candidate_enabled = local_ot_env(1)%schur_model_quality_ready
         IF (local_ot_env(1)%schur_split_quality_samples >= ot_kp_schur_calibration_min_samples) &
            local_ot_env(1)%schur_split_candidate_enabled = local_ot_env(1)%schur_split_candidate_enabled .AND. &
                                                            local_ot_env(1)%schur_split_calibrated_quality_ema >= &
                                                            ot_kp_schur_calibrated_quality_min_ratio .AND. &
                                                            local_ot_env(1)%schur_split_calibrated_quality >= &
                                                            0.5_dp*ot_kp_schur_calibrated_quality_min_ratio
         local_ot_env(1)%schur_constrained_candidate_enabled = &
            local_ot_env(1)%schur_split_candidate_enabled .AND. &
            local_ot_env(1)%schur_constrained_quality_samples >= ot_kp_schur_constrained_min_samples .AND. &
            local_ot_env(1)%schur_constrained_calibrated_quality_ema >= &
            ot_kp_schur_constrained_advantage_ratio* &
            MAX(ot_kp_schur_calibrated_quality_min_ratio, local_ot_env(1)%schur_split_calibrated_quality_ema) .AND. &
            local_ot_env(1)%schur_constrained_calibrated_quality_ema <= &
            ot_kp_schur_calibrated_quality_max_ratio .AND. &
            local_ot_env(1)%schur_constrained_calibrated_quality >= &
            0.5_dp*ot_kp_schur_calibrated_quality_min_ratio .AND. &
            local_ot_env(1)%schur_constrained_calibrated_quality <= &
            2.0_dp*ot_kp_schur_calibrated_quality_max_ratio
         local_ot_env(1)%schur_model_pending = .FALSE.
         local_ot_env(1)%schur_constrained_pending = .FALSE.
         local_ot_env(1)%schur_split_shadow_pending = .FALSE.
         local_ot_env(1)%schur_occgap_shadow_pending = .FALSE.
         local_ot_env(1)%schur_vector_secant_pending = .FALSE.
         local_ot_env(1)%schur_multisecant_pending = .FALSE.
         local_ot_env(1)%schur_prediction_pending = .FALSE.
         local_ot_env(1)%schur_reduced_secant_pending = .FALSE.
         local_ot_env(1)%schur_closure_shadow_pending = .FALSE.
         local_ot_env(1)%schur_closure_shadow_baseline_quadratic = 0.0_dp
         local_ot_env(1)%schur_closure_shadow_quadratic = 0.0_dp
         local_ot_env(1)%schur_closure_full_shadow_pending = .FALSE.
         local_ot_env(1)%schur_closure_full_shadow_baseline_quadratic = 0.0_dp
         local_ot_env(1)%schur_closure_full_shadow_quadratic = 0.0_dp
         local_ot_env(1)%schur_closure_vector_shadow_pending = .FALSE.
         local_ot_env(1)%schur_closure_vector_shadow_consistent = .FALSE.
         local_ot_env(1)%schur_closure_vector_shadow_work_consistent = .FALSE.
         local_ot_env(1)%schur_closure_vector_shadow_baseline_quadratic = 0.0_dp
         local_ot_env(1)%schur_closure_vector_shadow_quadratic = 0.0_dp
         local_ot_env(1)%schur_reduced_secant_model_groups = 0
         local_ot_env(1)%schur_reduced_secant_selected_groups = 0
         local_ot_env(1)%schur_reduced_secant_rot_residual_start_sq = 0.0_dp
         local_ot_env(1)%schur_reduced_secant_rot_residual_delta_dot = 0.0_dp
         local_ot_env(1)%schur_reduced_secant_rot_residual_delta_sq = 0.0_dp
         local_ot_env(1)%schur_closure_candidate_pending = .FALSE.
         local_ot_env(1)%schur_closure_candidate_model_groups = 0
         local_ot_env(1)%schur_closure_candidate_selected_groups = 0
         local_ot_env(1)%schur_closure_candidate_rot_residual_start_sq = 0.0_dp
         local_ot_env(1)%schur_closure_candidate_rot_residual_delta_dot = 0.0_dp
         local_ot_env(1)%schur_closure_candidate_rot_residual_delta_sq = 0.0_dp
         local_ot_env(1)%schur_dense_metric_shadow_pending = .FALSE.
         local_ot_env(1)%schur_projector_mode_pending = .FALSE.
         local_ot_env(1)%schur_projector_offdiag_pending = .FALSE.
         local_ot_env(1)%schur_projector_inactive_offdiag_pending = .FALSE.
         local_ot_env(1)%schur_projector_response_pending = .FALSE.
         local_ot_env(1)%schur_projector_plateau_gap_pending = .FALSE.
         local_ot_env(1)%schur_projector_physical_pending = .FALSE.
         local_ot_env(1)%schur_projector_mixed_direct_pending = .FALSE.
         local_ot_env(1)%schur_projector_spectral_pending = .FALSE.
         local_ot_env(1)%schur_projector_diagref_pending = .FALSE.
         local_ot_env(1)%schur_projector_density_pending = .FALSE.
         local_ot_env(1)%schur_projector_density_audit_pending = .FALSE.
         local_ot_env(1)%schur_projector_density_descent_pending = .FALSE.
         local_ot_env(1)%schur_projector_density_full_pending = .FALSE.
         local_ot_env(1)%schur_projector_density_full_direct_pending = .FALSE.
         local_ot_env(1)%schur_projector_density_full_global_pending = .FALSE.
         local_ot_env(1)%schur_model_flavor = 0

         logger => cp_get_default_logger()
         projector_physical_weight_quality = 0.0_dp
         projector_physical_metric_quality = 0.0_dp
         projector_physical_compensation_quality = 0.0_dp
         projector_physical_correction_quality = 0.0_dp
         projector_physical_negative_quality = 0.0_dp
         projector_physical_direct_quality = 0.0_dp
         projector_physical_selected_quality = 0.0_dp
         projector_physical_shift_quality = 0.0_dp
         IF (local_ot_env(1)%schur_projector_physical_weight_ema > &
             EPSILON(local_ot_env(1)%schur_projector_physical_weight_ema)) &
            projector_physical_weight_quality = &
            local_ot_env(1)%schur_projector_physical_weight_quality_ema/ &
            local_ot_env(1)%schur_projector_physical_weight_ema
         IF (local_ot_env(1)%schur_projector_physical_metric_ema > &
             EPSILON(local_ot_env(1)%schur_projector_physical_metric_ema)) &
            projector_physical_metric_quality = &
            local_ot_env(1)%schur_projector_physical_metric_quality_ema/ &
            local_ot_env(1)%schur_projector_physical_metric_ema
         IF (local_ot_env(1)%schur_projector_physical_compensation_ema > &
             EPSILON(local_ot_env(1)%schur_projector_physical_compensation_ema)) &
            projector_physical_compensation_quality = &
            local_ot_env(1)%schur_projector_physical_compensation_quality_ema/ &
            local_ot_env(1)%schur_projector_physical_compensation_ema
         IF (local_ot_env(1)%schur_projector_physical_correction_ratio_ema > &
             EPSILON(local_ot_env(1)%schur_projector_physical_correction_ratio_ema)) &
            projector_physical_correction_quality = &
            local_ot_env(1)%schur_projector_physical_correction_quality_ema/ &
            local_ot_env(1)%schur_projector_physical_correction_ratio_ema
         IF (local_ot_env(1)%schur_projector_physical_negative_ema > &
             EPSILON(local_ot_env(1)%schur_projector_physical_negative_ema)) &
            projector_physical_negative_quality = &
            local_ot_env(1)%schur_projector_physical_negative_quality_ema/ &
            local_ot_env(1)%schur_projector_physical_negative_ema
         IF (local_ot_env(1)%schur_projector_physical_direct_ema > &
             EPSILON(local_ot_env(1)%schur_projector_physical_direct_ema)) &
            projector_physical_direct_quality = &
            local_ot_env(1)%schur_projector_physical_direct_quality_ema/ &
            local_ot_env(1)%schur_projector_physical_direct_ema
         IF (local_ot_env(1)%schur_projector_physical_selected_ema > &
             EPSILON(local_ot_env(1)%schur_projector_physical_selected_ema)) &
            projector_physical_selected_quality = &
            local_ot_env(1)%schur_projector_physical_selected_quality_ema/ &
            local_ot_env(1)%schur_projector_physical_selected_ema
         IF (local_ot_env(1)%schur_projector_physical_shift_ema > &
             EPSILON(local_ot_env(1)%schur_projector_physical_shift_ema)) &
            projector_physical_shift_quality = &
            local_ot_env(1)%schur_projector_physical_shift_quality_ema/ &
            local_ot_env(1)%schur_projector_physical_shift_ema

      END SUBROUTINE update_kpoint_ot_schur_line_search_quality

! **************************************************************************************************
!> \brief Calibrate a reduced-secant probe against the rebuilt accepted-endpoint rotation residual.
!>
!>        The line-search quality update runs before the current Schur groups are rebuilt.  Its
!>        physical residual audit would therefore see the preceding sampled point.  This deferred
!>        update is called after every current (spin,k-point) group has contributed its residual.
!> \param model_groups ...
!> \param selected_groups ...
!> \param actual_groups ...
!> \param start_norm_sq ...
!> \param delta_dot ...
!> \param delta_norm_sq ...
!> \param position ...
!> \param predicted_drop ...
!> \param measured_drop ...
! **************************************************************************************************
      SUBROUTINE update_kpoint_ot_reduced_secant_endpoint_quality( &
         model_groups, selected_groups, actual_groups, start_norm_sq, delta_dot, delta_norm_sq, &
         position, predicted_drop, measured_drop)
      INTEGER, INTENT(IN)                                :: model_groups, selected_groups, &
                                                            actual_groups
      REAL(KIND=dp), INTENT(IN)                          :: start_norm_sq, delta_dot, delta_norm_sq, &
                                                            position, predicted_drop, measured_drop

      INTEGER                                            :: samples
      LOGICAL                                            :: quality_ready
      REAL(KIND=dp)                                      :: actual_ratio, aggregate_ratio, &
                                                            predicted_ratio, quality
      TYPE(cp_logger_type), POINTER                      :: logger

         predicted_ratio = 1.0_dp
         actual_ratio = 1.0_dp
         quality = 0.0_dp
         quality_ready = selected_groups > 0 .AND. selected_groups == model_groups .AND. &
                         actual_groups == model_groups
         IF (quality_ready) &
            CALL qs_scf_kp_affine_residual_quality( &
            start_norm_sq, delta_dot, delta_norm_sq, position, &
            local_ot_env(1)%kpoint_full_physical_rot_gnorm, predicted_ratio, actual_ratio, quality, &
            quality_ready)
         local_ot_env(1)%schur_reduced_secant_residual_quality = &
            MERGE(quality, 0.0_dp, quality_ready)
         samples = local_ot_env(1)%schur_reduced_secant_quality_samples
         IF (samples == 1) THEN
            local_ot_env(1)%schur_reduced_secant_residual_quality_ema = &
               local_ot_env(1)%schur_reduced_secant_residual_quality
         ELSE IF (samples > 1) THEN
            local_ot_env(1)%schur_reduced_secant_residual_quality_ema = &
               (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
               local_ot_env(1)%schur_reduced_secant_residual_quality_ema + &
               ot_kp_schur_quality_ema_alpha* &
               local_ot_env(1)%schur_reduced_secant_residual_quality
         END IF
         local_ot_env(1)%schur_reduced_secant_shadow_validated = &
            qs_scf_kp_secant_candidate_promoted( &
            samples, ot_kp_schur_calibration_min_samples, &
            local_ot_env(1)%schur_reduced_secant_drop_sum, &
            local_ot_env(1)%schur_reduced_secant_measured_sum, &
            local_ot_env(1)%schur_reduced_secant_quality, &
            local_ot_env(1)%schur_reduced_secant_quality_ema, &
            local_ot_env(1)%schur_reduced_secant_residual_quality, &
            local_ot_env(1)%schur_reduced_secant_residual_quality_ema, &
            ot_kp_schur_calibrated_quality_min_ratio)
         aggregate_ratio = local_ot_env(1)%schur_reduced_secant_measured_sum/ &
                           MAX(local_ot_env(1)%schur_reduced_secant_drop_sum, EPSILON(1.0_dp))
         logger => cp_get_default_logger()
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), &
                   '(A,1X,L1,3(1X,I4),6(1X,ES16.8))') &
            " OT Schur LS reduced-secant accepted residual ready selected model actual groups "// &
            "start delta_dot delta_sq pos pred actual:", &
            quality_ready, selected_groups, model_groups, actual_groups, start_norm_sq, delta_dot, &
            delta_norm_sq, position, predicted_ratio, actual_ratio
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I6,1X,L1,7(1X,ES16.8))') &
            " OT Schur LS reduced-secant accepted history samples validated q qema rq rqema pred meas ratio:", &
            samples, local_ot_env(1)%schur_reduced_secant_shadow_validated, &
            local_ot_env(1)%schur_reduced_secant_quality, &
            local_ot_env(1)%schur_reduced_secant_quality_ema, &
            local_ot_env(1)%schur_reduced_secant_residual_quality, &
            local_ot_env(1)%schur_reduced_secant_residual_quality_ema, &
            predicted_drop, measured_drop, aggregate_ratio

      END SUBROUTINE update_kpoint_ot_reduced_secant_endpoint_quality

! **************************************************************************************************
!> \brief Calibrate a closure-response probe against the rebuilt active physical residual.
!>
!>        The finite closure Hessian is fitted only in the active physical density subspace.
!>        Its own accepted-step history must therefore use the matching active rotation norm,
!>        independently of the full-pair reduced-secant calibration.
!> \param model_groups ...
!> \param selected_groups ...
!> \param actual_groups ...
!> \param start_norm_sq ...
!> \param delta_dot ...
!> \param delta_norm_sq ...
!> \param position ...
!> \param predicted_drop ...
!> \param measured_drop ...
! **************************************************************************************************
      SUBROUTINE update_kpoint_ot_closure_candidate_endpoint_quality( &
         model_groups, selected_groups, actual_groups, start_norm_sq, delta_dot, delta_norm_sq, &
         position, predicted_drop, measured_drop)
      INTEGER, INTENT(IN)                                :: model_groups, selected_groups, &
                                                            actual_groups
      REAL(KIND=dp), INTENT(IN)                          :: start_norm_sq, delta_dot, delta_norm_sq, &
                                                            position, predicted_drop, measured_drop

      INTEGER                                            :: samples
      LOGICAL                                            :: full_gain_ready, quality_ready
      REAL(KIND=dp)                                      :: actual_ratio, aggregate_ratio, coverage, &
                                                            full_gain_position, full_gain_ratio, &
                                                            gain, predicted_ratio, quality
      TYPE(cp_logger_type), POINTER                      :: logger

         predicted_ratio = 1.0_dp
         actual_ratio = 1.0_dp
         quality = 0.0_dp
         gain = 0.0_dp
         coverage = 0.0_dp
         quality_ready = selected_groups > 0 .AND. selected_groups == model_groups .AND. &
                         actual_groups == model_groups
         IF (quality_ready) &
            CALL qs_scf_kp_affine_residual_calibration( &
            start_norm_sq, delta_dot, delta_norm_sq, position, &
            local_ot_env(1)%kpoint_physical_rot_gnorm, predicted_ratio, actual_ratio, quality, gain, &
            quality_ready)
         local_ot_env(1)%schur_closure_candidate_residual_quality = &
            MERGE(quality, 0.0_dp, quality_ready)
         local_ot_env(1)%schur_closure_candidate_residual_gain = &
            MERGE(gain, 0.0_dp, quality_ready)
         full_gain_ratio = 1.0_dp
         full_gain_ready = quality_ready
         IF (full_gain_ready) &
            CALL qs_scf_kp_affine_residual_minimum( &
            start_norm_sq, delta_dot, delta_norm_sq, 1.0_dp, full_gain_position, &
            full_gain_ratio, full_gain_ready)
         IF (full_gain_ready .AND. 1.0_dp - full_gain_ratio > EPSILON(1.0_dp)) &
            coverage = MIN(1.0_dp, gain/(1.0_dp - full_gain_ratio))
         local_ot_env(1)%schur_closure_candidate_residual_coverage = &
            MERGE(coverage, 0.0_dp, full_gain_ready)
         samples = local_ot_env(1)%schur_closure_candidate_quality_samples
         IF (samples == 1) THEN
            local_ot_env(1)%schur_closure_candidate_residual_quality_ema = &
               local_ot_env(1)%schur_closure_candidate_residual_quality
            local_ot_env(1)%schur_closure_candidate_residual_gain_ema = &
               local_ot_env(1)%schur_closure_candidate_residual_gain
            local_ot_env(1)%schur_closure_candidate_residual_coverage_ema = &
               local_ot_env(1)%schur_closure_candidate_residual_coverage
         ELSE IF (samples > 1) THEN
            local_ot_env(1)%schur_closure_candidate_residual_quality_ema = &
               (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
               local_ot_env(1)%schur_closure_candidate_residual_quality_ema + &
               ot_kp_schur_quality_ema_alpha* &
               local_ot_env(1)%schur_closure_candidate_residual_quality
            local_ot_env(1)%schur_closure_candidate_residual_gain_ema = &
               (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
               local_ot_env(1)%schur_closure_candidate_residual_gain_ema + &
               ot_kp_schur_quality_ema_alpha* &
               local_ot_env(1)%schur_closure_candidate_residual_gain
            local_ot_env(1)%schur_closure_candidate_residual_coverage_ema = &
               (1.0_dp - ot_kp_schur_quality_ema_alpha)* &
               local_ot_env(1)%schur_closure_candidate_residual_coverage_ema + &
               ot_kp_schur_quality_ema_alpha* &
               local_ot_env(1)%schur_closure_candidate_residual_coverage
         END IF
         local_ot_env(1)%schur_closure_candidate_validated = &
            qs_scf_kp_secant_candidate_promoted( &
            samples, ot_kp_schur_calibration_min_samples, &
            local_ot_env(1)%schur_closure_candidate_drop_sum, &
            local_ot_env(1)%schur_closure_candidate_measured_sum, &
            local_ot_env(1)%schur_closure_candidate_quality, &
            local_ot_env(1)%schur_closure_candidate_quality_ema, &
            local_ot_env(1)%schur_closure_candidate_residual_quality, &
            local_ot_env(1)%schur_closure_candidate_residual_quality_ema, &
            ot_kp_schur_calibrated_quality_min_ratio) .AND. &
            local_ot_env(1)%schur_closure_candidate_residual_coverage >= &
            ot_kp_schur_calibrated_quality_min_ratio .AND. &
            local_ot_env(1)%schur_closure_candidate_residual_coverage_ema >= &
            ot_kp_schur_calibrated_quality_min_ratio
         aggregate_ratio = local_ot_env(1)%schur_closure_candidate_measured_sum/ &
                           MAX(local_ot_env(1)%schur_closure_candidate_drop_sum, EPSILON(1.0_dp))
         logger => cp_get_default_logger()
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), &
                   '(A,1X,L1,3(1X,I4),6(1X,ES16.8))') &
            " OT Schur LS closure candidate accepted residual ready selected model actual groups "// &
            "start delta_dot delta_sq pos pred actual:", &
            quality_ready, selected_groups, model_groups, actual_groups, start_norm_sq, delta_dot, &
            delta_norm_sq, position, predicted_ratio, actual_ratio
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I6,1X,L1,12(1X,ES16.8))') &
            " OT Schur LS closure candidate accepted history samples validated "// &
            "q qema rf rfema rg rgema rc rcema fullr pred meas ratio:", &
            samples, local_ot_env(1)%schur_closure_candidate_validated, &
            local_ot_env(1)%schur_closure_candidate_quality, &
            local_ot_env(1)%schur_closure_candidate_quality_ema, &
            local_ot_env(1)%schur_closure_candidate_residual_quality, &
            local_ot_env(1)%schur_closure_candidate_residual_quality_ema, &
            local_ot_env(1)%schur_closure_candidate_residual_gain, &
            local_ot_env(1)%schur_closure_candidate_residual_gain_ema, &
            local_ot_env(1)%schur_closure_candidate_residual_coverage, &
            local_ot_env(1)%schur_closure_candidate_residual_coverage_ema, full_gain_ratio, &
            predicted_drop, measured_drop, aggregate_ratio

      END SUBROUTINE update_kpoint_ot_closure_candidate_endpoint_quality

! **************************************************************************************************
!> \brief ...
!> \param skip_group ...
! **************************************************************************************************
      SUBROUTINE precondition_kpoint_ot_energy_diagonal(skip_group)
      LOGICAL, DIMENSION(:), INTENT(IN)                  :: skip_group

      INTEGER                                            :: group, ikpoint, imo, ispin, &
                                                            local_channel, local_kpoint, nmo
      REAL(KIND=dp) :: curvature, gvalue, maxocc, mu, occ_curvature, precond_weight, &
         rayleigh_edge_gap, tether_response, tether_strength, tether_weight
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:) :: channel_diag, energy_curvature_floor, &
         floor_count, floor_curv_sum, occ_curv_max, occ_curv_sum, tether_curv_max, &
         tether_curv_sum, total_curv_max, total_curv_sum
      TYPE(cp_logger_type), POINTER                      :: logger
      TYPE(kpoint_env_type), POINTER                     :: kp

         precond_count(:) = 0.0_dp
         precond_shift(:) = 0.0_dp
         precond_sum(:) = 0.0_dp
         ALLOCATE (energy_curvature_floor(ngroups), floor_count(ngroups), floor_curv_sum(ngroups), &
                   occ_curv_max(ngroups), occ_curv_sum(ngroups), tether_curv_max(ngroups), &
                   tether_curv_sum(ngroups), total_curv_max(ngroups), total_curv_sum(ngroups))
         energy_curvature_floor(:) = 0.0_dp
         floor_count(:) = 0.0_dp
         floor_curv_sum(:) = 0.0_dp
         occ_curv_max(:) = 0.0_dp
         occ_curv_sum(:) = 0.0_dp
         tether_curv_max(:) = 0.0_dp
         tether_curv_sum(:) = 0.0_dp
         total_curv_max(:) = 0.0_dp
         total_curv_sum(:) = 0.0_dp

         DO local_kpoint = 1, SIZE(kpoints%kp_env)
            kp => kpoints%kp_env(local_kpoint)%kpoint_env
            ikpoint = kp%nkpoint
            DO ispin = 1, nspin_ot
               group = MERGE(ispin, 1, ngroups == nspin_ot)
               IF (skip_group(group)) CYCLE
               local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
               CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, nmo=nmo)
               mu = trial_mu(ispin)
               tether_strength = 0.0_dp
               IF (local_ot_env(local_channel)%settings%canonical_tether) THEN
                  ALLOCATE (channel_diag(nmo))
                  CALL get_replicated_kpoint_ot_diag(local_ot_env(local_channel)%rot_mat_chc, &
                                                     local_ot_env(local_channel), channel_diag)
                  rayleigh_edge_gap = 0.0_dp
                  DO imo = 1, nmo
                     tether_response = kpoint_ot_canonical_tether_response(trial_occupation(imo, ikpoint, ispin), &
                                                                           trial_eigenvalues(imo, ikpoint, ispin), mu, &
                                                                           sigma, maxocc, smear%method)
                     IF (tether_response > 0.0_dp) &
                        rayleigh_edge_gap = MAX(rayleigh_edge_gap, &
                                                ABS(channel_diag(imo) - local_ot_env(local_channel)%ener_x(imo)))
                  END DO
                  tether_strength = kpoint_ot_canonical_tether_strength(local_ot_env(local_channel), &
                                                                        rayleigh_edge_gap, sigma)
                  DEALLOCATE (channel_diag)
               END IF
               DO imo = 1, nmo
                  gvalue = SmearingDerivative(trial_occupation(imo, ikpoint, ispin), &
                                              trial_eigenvalues(imo, ikpoint, ispin), mu, &
                                              sigma, maxocc, smear%method)
                  tether_weight = kpoint_ot_canonical_tether_weight(trial_occupation(imo, ikpoint, ispin), &
                                                                    trial_eigenvalues(imo, ikpoint, ispin), &
                                                                    mu, sigma, maxocc, smear%method, &
                                                                    wkp(ikpoint), tether_strength)
                  occ_curvature = wkp(ikpoint)*gvalue
                  curvature = occ_curvature + tether_weight
                  occ_curv_sum(group) = occ_curv_sum(group) + occ_curvature
                  occ_curv_max(group) = MAX(occ_curv_max(group), occ_curvature)
                  tether_curv_sum(group) = tether_curv_sum(group) + tether_weight
                  tether_curv_max(group) = MAX(tether_curv_max(group), tether_weight)
                  total_curv_sum(group) = total_curv_sum(group) + curvature
                  total_curv_max(group) = MAX(total_curv_max(group), curvature)
               END DO
            END DO
         END DO

         CALL para_env_inter_kp%sum(occ_curv_sum)
         CALL para_env_inter_kp%sum(tether_curv_sum)
         CALL para_env_inter_kp%sum(total_curv_sum)
         DO group = 1, ngroups
            CALL para_env_inter_kp%max(occ_curv_max(group))
            CALL para_env_inter_kp%max(tether_curv_max(group))
            CALL para_env_inter_kp%max(total_curv_max(group))
            ! Keep the ordinary coupled bootstrap conservative.  A separate
            ! energy-closure candidate below uses the exact susceptibility
            ! pseudoinverse once a physical occupation plateau is established.
            energy_curvature_floor(group) = ot_kp_energy_curvature_absolute_cap
         END DO

         ! Apply one common fixed-N metric on all distributed k-point channels.  The preliminary
         ! pass above is required because a rank-local maximum would make this response depend on
         ! the k-point distribution.
         DO local_kpoint = 1, SIZE(kpoints%kp_env)
            kp => kpoints%kp_env(local_kpoint)%kpoint_env
            ikpoint = kp%nkpoint
            DO ispin = 1, nspin_ot
               group = MERGE(ispin, 1, ngroups == nspin_ot)
               IF (skip_group(group)) CYCLE
               local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
               CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, nmo=nmo)
               mu = trial_mu(ispin)
               tether_strength = 0.0_dp
               IF (local_ot_env(local_channel)%settings%canonical_tether) THEN
                  ALLOCATE (channel_diag(nmo))
                  CALL get_replicated_kpoint_ot_diag(local_ot_env(local_channel)%rot_mat_chc, &
                                                     local_ot_env(local_channel), channel_diag)
                  rayleigh_edge_gap = 0.0_dp
                  DO imo = 1, nmo
                     tether_response = kpoint_ot_canonical_tether_response(trial_occupation(imo, ikpoint, ispin), &
                                                                           trial_eigenvalues(imo, ikpoint, ispin), mu, &
                                                                           sigma, maxocc, smear%method)
                     IF (tether_response > 0.0_dp) &
                        rayleigh_edge_gap = MAX(rayleigh_edge_gap, &
                                                ABS(channel_diag(imo) - local_ot_env(local_channel)%ener_x(imo)))
                  END DO
                  tether_strength = kpoint_ot_canonical_tether_strength(local_ot_env(local_channel), &
                                                                        rayleigh_edge_gap, sigma)
                  DEALLOCATE (channel_diag)
               END IF
               DO imo = 1, nmo
                  gvalue = SmearingDerivative(trial_occupation(imo, ikpoint, ispin), &
                                              trial_eigenvalues(imo, ikpoint, ispin), mu, &
                                              sigma, maxocc, smear%method)
                  tether_weight = kpoint_ot_canonical_tether_weight(trial_occupation(imo, ikpoint, ispin), &
                                                                    trial_eigenvalues(imo, ikpoint, ispin), &
                                                                    mu, sigma, maxocc, smear%method, &
                                                                    wkp(ikpoint), tether_strength)
                  curvature = wkp(ikpoint)*gvalue + tether_weight
                  IF (curvature > EPSILON(curvature)) THEN
                     IF (curvature < energy_curvature_floor(group)) THEN
                        floor_count(group) = floor_count(group) + 1.0_dp
                        floor_curv_sum(group) = floor_curv_sum(group) + curvature
                     END IF
                     precond_weight = MAX(curvature, energy_curvature_floor(group))
                     local_ot_env(local_channel)%ener_gx(imo) = &
                        local_ot_env(local_channel)%ener_gx(imo)/precond_weight
                     precond_sum(group) = precond_sum(group) + &
                                          wkp(ikpoint)*gvalue* &
                                          local_ot_env(local_channel)%ener_gx(imo)
                     precond_count(group) = precond_count(group) + wkp(ikpoint)*gvalue
                  ELSE
                     local_ot_env(local_channel)%ener_gx(imo) = 0.0_dp
                  END IF
               END DO
            END DO
         END DO

         CALL para_env_inter_kp%sum(precond_sum)
         CALL para_env_inter_kp%sum(precond_count)
         CALL para_env_inter_kp%sum(floor_count)
         CALL para_env_inter_kp%sum(floor_curv_sum)
         DO group = 1, ngroups
            IF (skip_group(group)) CYCLE
            IF (precond_count(group) > 0.0_dp) precond_shift(group) = precond_sum(group)/precond_count(group)
         END DO

         logger => cp_get_default_logger()
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) THEN
            DO group = 1, ngroups
               IF (skip_group(group)) CYCLE
               WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,6(1X,ES16.8))') &
                  " OT k-point occupation preconditioner group occ_sum occ_max tether_sum tether_max total_sum total_max:", &
                  group, occ_curv_sum(group), occ_curv_max(group), tether_curv_sum(group), &
                  tether_curv_max(group), total_curv_sum(group), total_curv_max(group)
               WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,3(1X,ES16.8))') &
                  " OT k-point occupation preconditioner floor group count curv_sum floor:", &
                  group, floor_count(group), floor_curv_sum(group), energy_curvature_floor(group)
            END DO
         END IF

         DO local_kpoint = 1, SIZE(kpoints%kp_env)
            kp => kpoints%kp_env(local_kpoint)%kpoint_env
            ikpoint = kp%nkpoint
            DO ispin = 1, nspin_ot
               group = MERGE(ispin, 1, ngroups == nspin_ot)
               IF (skip_group(group)) CYCLE
               local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
               CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, nmo=nmo)
               mu = trial_mu(ispin)
               tether_strength = 0.0_dp
               IF (local_ot_env(local_channel)%settings%canonical_tether) THEN
                  ALLOCATE (channel_diag(nmo))
                  CALL get_replicated_kpoint_ot_diag(local_ot_env(local_channel)%rot_mat_chc, &
                                                     local_ot_env(local_channel), channel_diag)
                  rayleigh_edge_gap = 0.0_dp
                  DO imo = 1, nmo
                     tether_response = kpoint_ot_canonical_tether_response(trial_occupation(imo, ikpoint, ispin), &
                                                                           trial_eigenvalues(imo, ikpoint, ispin), mu, &
                                                                           sigma, maxocc, smear%method)
                     IF (tether_response > 0.0_dp) &
                        rayleigh_edge_gap = MAX(rayleigh_edge_gap, &
                                                ABS(channel_diag(imo) - local_ot_env(local_channel)%ener_x(imo)))
                  END DO
                  tether_strength = kpoint_ot_canonical_tether_strength(local_ot_env(local_channel), &
                                                                        rayleigh_edge_gap, sigma)
                  DEALLOCATE (channel_diag)
               END IF
               DO imo = 1, nmo
                  gvalue = SmearingDerivative(trial_occupation(imo, ikpoint, ispin), &
                                              trial_eigenvalues(imo, ikpoint, ispin), mu, &
                                              sigma, maxocc, smear%method)
                  tether_weight = kpoint_ot_canonical_tether_weight(trial_occupation(imo, ikpoint, ispin), &
                                                                    trial_eigenvalues(imo, ikpoint, ispin), &
                                                                    mu, sigma, maxocc, smear%method, &
                                                                    wkp(ikpoint), tether_strength)
                  curvature = wkp(ikpoint)*gvalue + tether_weight
                  IF (curvature >= energy_curvature_floor(group) .AND. &
                      curvature > EPSILON(curvature)) &
                     local_ot_env(local_channel)%ener_gx(imo) = &
                     local_ot_env(local_channel)%ener_gx(imo) - precond_shift(group)
               END DO
            END DO
         END DO
         DEALLOCATE (energy_curvature_floor, floor_count, floor_curv_sum, occ_curv_max, occ_curv_sum, &
                     tether_curv_max, tether_curv_sum, total_curv_max, total_curv_sum)
      END SUBROUTINE precondition_kpoint_ot_energy_diagonal

! **************************************************************************************************
!> \brief ...
!> \param group_done ...
!> \param added_mos_auto_channel ...
!> \param added_mos_current ...
!> \param eps_scf_channel ...
! **************************************************************************************************
      SUBROUTINE precondition_kpoint_ot_schur(group_done, added_mos_auto_channel, &
                                              added_mos_current, eps_scf_channel)
      LOGICAL, DIMENSION(:), INTENT(OUT)                 :: group_done
      LOGICAL, INTENT(IN)                                :: added_mos_auto_channel
      INTEGER, INTENT(IN)                                :: added_mos_current
      REAL(KIND=dp), INTENT(IN)                          :: eps_scf_channel

      INTEGER :: closure_candidate_endpoint_model_groups, &
         closure_candidate_endpoint_selected_groups, group, reduced_secant_endpoint_model_groups, &
         reduced_secant_endpoint_selected_groups
      LOGICAL :: added_mos_auto_tail_enabled, closure_candidate_endpoint_pending, &
         reduced_secant_endpoint_pending
      REAL(KIND=dp) :: added_mos_auto_tail_residual_limit, closure_candidate_endpoint_delta_dot, &
         closure_candidate_endpoint_delta_sq, closure_candidate_endpoint_measured_drop, &
         closure_candidate_endpoint_position, closure_candidate_endpoint_predicted_drop, &
         closure_candidate_endpoint_start_sq, reduced_secant_endpoint_delta_dot, &
         reduced_secant_endpoint_delta_sq, reduced_secant_endpoint_measured_drop, &
         reduced_secant_endpoint_position, reduced_secant_endpoint_predicted_drop, &
         reduced_secant_endpoint_start_sq, response_raw_delta

         group_done(:) = .FALSE.
         IF (.NOT. local_ot_env(1)%settings%do_rotation) RETURN
         added_mos_auto_tail_enabled = .FALSE.
         added_mos_auto_tail_residual_limit = 0.0_dp
         IF (added_mos_auto_channel .AND. &
             added_mos_current <= ot_kp_added_mos_auto_direct_veto_max_added .AND. &
             smear%do_smear .AND. eps_scf_channel > 0.0_dp) THEN
            added_mos_auto_tail_enabled = .TRUE.
            added_mos_auto_tail_residual_limit = &
               ot_kp_added_mos_auto_fractional_tail_residual_factor* &
               MAX(MAX(ot_kp_added_mos_auto_tail_eps_factor*eps_scf_channel, &
                       ot_kp_added_mos_auto_tail_probe_factor*SQRT(eps_scf_channel)), &
                   ot_kp_added_mos_auto_edge_probe_factor*SQRT(eps_scf_channel))
         END IF
         reduced_secant_endpoint_pending = local_ot_env(1)%schur_model_pending .AND. &
                                           local_ot_env(1)%line_search_count > 0 .AND. &
                                           local_ot_env(1)%line_search_might_be_done .AND. &
                                           .NOT. local_ot_env(1)%schur_history_mixed .AND. &
                                           local_ot_env(1)%schur_reduced_secant_pending
         reduced_secant_endpoint_model_groups = &
            local_ot_env(1)%schur_reduced_secant_model_groups
         reduced_secant_endpoint_selected_groups = &
            local_ot_env(1)%schur_reduced_secant_selected_groups
         reduced_secant_endpoint_start_sq = &
            local_ot_env(1)%schur_reduced_secant_rot_residual_start_sq
         reduced_secant_endpoint_delta_dot = &
            local_ot_env(1)%schur_reduced_secant_rot_residual_delta_dot
         reduced_secant_endpoint_delta_sq = &
            local_ot_env(1)%schur_reduced_secant_rot_residual_delta_sq
         reduced_secant_endpoint_position = MAX(0.0_dp, local_ot_env(1)%mermin_ls_next_pos)
         IF (reduced_secant_endpoint_position <= EPSILON(reduced_secant_endpoint_position) .AND. &
             local_ot_env(1)%mermin_ls_best_sample_index > 0) &
            reduced_secant_endpoint_position = &
            MAX(0.0_dp, local_ot_env(1)%mermin_ls_best_sample_pos)
         reduced_secant_endpoint_predicted_drop = qs_scf_kp_candidate_position_drop( &
                                                  local_ot_env(1)%schur_reduced_secant_drop, &
                                                  local_ot_env(1)%schur_model_drop, &
                                                  local_ot_env(1)%schur_model_slope, &
                                                  local_ot_env(1)%schur_model_quadratic, &
                                                  reduced_secant_endpoint_position)
         closure_candidate_endpoint_pending = local_ot_env(1)%schur_model_pending .AND. &
                                              local_ot_env(1)%line_search_count > 0 .AND. &
                                              local_ot_env(1)%line_search_might_be_done .AND. &
                                              .NOT. local_ot_env(1)%schur_history_mixed .AND. &
                                              local_ot_env(1)%schur_closure_candidate_pending
         closure_candidate_endpoint_model_groups = &
            local_ot_env(1)%schur_closure_candidate_model_groups
         closure_candidate_endpoint_selected_groups = &
            local_ot_env(1)%schur_closure_candidate_selected_groups
         closure_candidate_endpoint_start_sq = &
            local_ot_env(1)%schur_closure_candidate_rot_residual_start_sq
         closure_candidate_endpoint_delta_dot = &
            local_ot_env(1)%schur_closure_candidate_rot_residual_delta_dot
         closure_candidate_endpoint_delta_sq = &
            local_ot_env(1)%schur_closure_candidate_rot_residual_delta_sq
         closure_candidate_endpoint_position = reduced_secant_endpoint_position
         closure_candidate_endpoint_predicted_drop = qs_scf_kp_candidate_position_drop( &
                                                     local_ot_env(1)%schur_closure_candidate_drop, &
                                                     local_ot_env(1)%schur_model_drop, &
                                                     local_ot_env(1)%schur_model_slope, &
                                                     local_ot_env(1)%schur_model_quadratic, &
                                                     closure_candidate_endpoint_position)
         CALL update_kpoint_ot_schur_line_search_quality()
         reduced_secant_endpoint_measured_drop = local_ot_env(1)%schur_model_measured_drop
         closure_candidate_endpoint_measured_drop = local_ot_env(1)%schur_model_measured_drop
         response_raw_delta = MAX(0.0_dp, local_ot_env(1)%kpoint_raw_delta)
         CALL para_env_inter_kp%max(response_raw_delta)
         IF (.NOT. local_ot_env(1)%energy_only .AND. &
             (local_ot_env(1)%line_search_count == 0 .OR. local_ot_env(1)%line_search_might_be_done)) THEN
            local_ot_env(1)%schur_model_pending = .FALSE.
            local_ot_env(1)%schur_constrained_pending = .FALSE.
            local_ot_env(1)%schur_split_shadow_pending = .FALSE.
            local_ot_env(1)%schur_occgap_shadow_pending = .FALSE.
            local_ot_env(1)%schur_vector_secant_pending = .FALSE.
            local_ot_env(1)%schur_vector_secant_drop = 0.0_dp
            local_ot_env(1)%schur_multisecant_pending = .FALSE.
            local_ot_env(1)%schur_multisecant_drop = 0.0_dp
