      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :) :: response_density_basis_audit_exact, &
         response_density_basis_curvfloor_audit_exact, response_density_basis_damped_audit, &
         response_density_basis_damped_audit_exact, response_density_basis_filtered_audit, &
         response_density_basis_filtered_audit_exact, &
         response_density_basis_selective_audit_exact, response_density_direct_exact, &
         response_density_exact, response_density_floor_audit, response_density_floor_audit_exact, &
         response_density_floor_safe_audit, response_density_floor_safe_audit_exact, &
         response_density_full, response_density_full_audit
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :) :: response_density_full_audit_exact, &
         response_density_full_exact, response_density_full_global, &
         response_density_full_global_exact, response_density_physical, response_density_plateau, &
         response_density_plateau_exact, response_exact, response_exact_active, &
         response_exact_physical, response_exact_raw, response_multisecant, response_occ, &
         response_occ_canonical, response_occ_physical, response_physical_model, &
         response_prediction, response_split, rot_hessian, rot_hessian_closure_baseline, &
         rot_hessian_closure_candidate
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :) :: &
         rot_hessian_closure_coupled_fullrank_response, rot_hessian_closure_coupled_response, &
         rot_hessian_closure_fullrank_response, rot_hessian_closure_probe_response, &
         rot_hessian_closure_reduced_response, rot_hessian_closure_response, rot_hessian_coupled, &
         rot_hessian_multisecant, rot_hessian_orbital_schur, rot_hessian_prediction, &
         rot_hessian_projector, rot_hessian_projector_physical, &
         rot_hessian_projector_physical_active, rot_hessian_projector_physical_diagref, &
         rot_hessian_projector_physical_offdiag, rot_hessian_projector_physical_offdiag_active
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :) :: &
         rot_hessian_projector_physical_offdiag_plateau, &
         rot_hessian_projector_physical_offdiag_plateau_active, rot_hessian_reduced_secant, &
         rot_hessian_secant, schur, schur_metric
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :, :)     :: channel_density_pair_residual, &
                                                            channel_residual_pair_score
      TYPE(cp_logger_type), POINTER                      :: logger
      TYPE(kpoint_env_type), POINTER                     :: kp
      TYPE(qs_scf_kp_projector_trace_metrics_type)       :: projector_trace_metrics

         group_done = .FALSE.
         logger => cp_get_default_logger()
         IF (ABS(gsum(target_group)) <= EPSILON(gsum(target_group))) RETURN

         new_search_point = .NOT. local_ot_env(1)%energy_only .AND. &
                            (local_ot_env(1)%line_search_count == 0 .OR. &
                             local_ot_env(1)%line_search_might_be_done)
         energy_closure_tail_ready = .FALSE.
         IF (new_search_point) &
            local_ot_env(1)%schur_reduced_secant_model_groups = &
            local_ot_env(1)%schur_reduced_secant_model_groups + 1
         IF (new_search_point) &
            local_ot_env(1)%schur_closure_candidate_model_groups = &
            local_ot_env(1)%schur_closure_candidate_model_groups + 1
         projector_physical_shadow_enabled = local_ot_env(1)%schur_projector_physical_candidate_enabled
         IF (new_search_point) &
            projector_physical_shadow_enabled = projector_physical_shadow_enabled .OR. &
                                                local_ot_env(1)%schur_projector_physical_quality_samples > 0 .OR. &
                                                local_ot_env(1)%schur_projector_mode_quality_samples >= &
                                                ot_kp_schur_calibration_min_samples .OR. &
                                                local_ot_env(1)%schur_projector_density_full_quality_samples >= &
                                                ot_kp_schur_projector_response_min_samples .OR. &
                                                local_ot_env(1)%schur_projector_density_full_direct_quality_samples >= &
                                                ot_kp_schur_projector_response_min_samples .OR. &
                                                local_ot_env(1)%schur_projector_density_full_global_quality_samples >= &
                                                ot_kp_schur_projector_response_min_samples .OR. &
                                                local_ot_env(1)%schur_projector_density_fdir_sel_quality_samples >= &
                                                ot_kp_schur_calibration_min_samples
         ! Bootstrap the physical fixed-N response as a shadow in the
         ! residual tail.  Requiring prior shadow samples here creates a
         ! closed loop: samples are recorded only after this model is built.
         ! Candidate selection still requires measured Mermin/residual
         ! quality, so this does not promote an uncalibrated direction.
         IF (new_search_point .AND. &
             residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
             local_ot_env(1)%kpoint_density_stationarity_ready) &
            projector_physical_shadow_enabled = .TRUE.
         projector_physical_direct_shadow_quality_for_promotion = 0.0_dp
         projector_physical_direct_promoted = .FALSE.
         IF (new_search_point .AND. &
             local_ot_env(1)%schur_projector_physical_direct_selected_quality_samples >= &
             ot_kp_schur_calibration_min_samples .AND. &
             local_ot_env(1)%schur_projector_physical_direct_selected_drop_sum > &
             EPSILON(local_ot_env(1)%schur_projector_physical_direct_selected_drop_sum) .AND. &
             local_ot_env(1)%schur_projector_physical_direct_selected_measured_sum > 0.0_dp) THEN
            projector_physical_direct_promoted = &
               local_ot_env(1)%schur_projector_physical_direct_selected_measured_sum/ &
               local_ot_env(1)%schur_projector_physical_direct_selected_drop_sum >= &
               ot_kp_schur_projector_response_quality_min_ratio .AND. &
               local_ot_env(1)%schur_projector_physical_direct_selected_quality_ema >= &
               ot_kp_schur_projector_response_quality_min_ratio .AND. &
               local_ot_env(1)%schur_projector_physical_direct_selected_quality >= &
               0.5_dp*ot_kp_schur_projector_response_quality_min_ratio .AND. &
               local_ot_env(1)%schur_projector_physical_direct_selected_residual_quality_ema >= &
               ot_kp_schur_projector_response_quality_min_ratio .AND. &
               local_ot_env(1)%schur_projector_physical_direct_selected_residual_quality >= &
               0.5_dp*ot_kp_schur_projector_response_quality_min_ratio
         END IF
         IF (.NOT. projector_physical_direct_promoted .AND. new_search_point .AND. &
             local_ot_env(1)%schur_projector_physical_direct_selected_quality_samples < &
             ot_kp_schur_calibration_min_samples .AND. &
             local_ot_env(1)%schur_projector_physical_direct_quality_samples >= &
             ot_kp_schur_projector_response_min_samples .AND. &
             local_ot_env(1)%schur_projector_physical_direct_drop_sum > &
             EPSILON(local_ot_env(1)%schur_projector_physical_direct_drop_sum) .AND. &
             local_ot_env(1)%schur_projector_physical_direct_measured_sum > 0.0_dp) THEN
            projector_physical_direct_shadow_quality_for_promotion = &
               kpoint_ot_schur_history_quality( &
               local_ot_env(1)%schur_projector_physical_direct_drop_sum, &
               local_ot_env(1)%schur_projector_physical_direct_measured_sum, &
               local_ot_env(1)%schur_projector_physical_direct_quality_shadow_ema, &
               local_ot_env(1)%schur_projector_physical_direct_quality_samples, &
               ot_kp_schur_projector_response_min_samples, 0.0_dp, &
               ot_kp_schur_projector_response_quality_min_ratio, &
               ot_kp_schur_projector_response_quality_max_ratio)
            ! Bootstrap the first selected direct-physical samples from its
            ! shadow history.  Once selected samples exist the stricter
            ! block above controls promotion.
            projector_physical_direct_promoted = &
               local_ot_env(1)%schur_projector_physical_direct_measured_sum/ &
               local_ot_env(1)%schur_projector_physical_direct_drop_sum >= &
               ot_kp_schur_projector_response_quality_min_ratio .AND. &
               local_ot_env(1)%schur_projector_physical_direct_quality_shadow_ema >= &
               ot_kp_schur_projector_response_quality_min_ratio .AND. &
               local_ot_env(1)%schur_projector_physical_direct_quality >= &
               0.5_dp*ot_kp_schur_projector_response_quality_min_ratio
         END IF
         projector_physical_direct_shadow_enabled = projector_physical_shadow_enabled
         IF (new_search_point) &
            projector_physical_direct_shadow_enabled = projector_physical_direct_shadow_enabled .OR. &
                                                       projector_physical_direct_promoted
         projector_density_full_history_enabled = projector_physical_shadow_enabled
         projector_density_full_audit_enabled = projector_density_full_history_enabled

         ! Dense Schur variables use one replicated global ordering.  A local
         ! k-point group contributes only its owned channel blocks; the
         ! inter-kpoint communicator assembles them below before the solve.
         nchannels = nspin_ot*SIZE(wkp)
         ALLOCATE (canonical_density_cauchy_channel(nchannels), &
                   channel_full_var_offset(nchannels), &
                   channel_multiplicity(nchannels), channel_nmo(nchannels), &
                   channel_nrot(nchannels), channel_var_offset(nchannels), &
                   channel_maxocc(nchannels), e_offset(nchannels))
         canonical_density_cauchy_channel(:) = 0
         channel_full_var_offset(:) = 0
         channel_multiplicity(:) = 0
         channel_nmo(:) = 0
         channel_nrot(:) = 0
         channel_var_offset(:) = 0
         channel_maxocc(:) = 0.0_dp
         e_offset(:) = 0

         DO local_kpoint = 1, SIZE(kpoints%kp_env)
            kp => kpoints%kp_env(local_kpoint)%kpoint_env
            ikpoint = kp%nkpoint
            DO ispin = 1, nspin_ot
               group = MERGE(ispin, 1, ngroups == nspin_ot)
               IF (group /= target_group) CYCLE
               local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
               global_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot)
               CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, nmo=nmo)
               channel_nmo(global_channel) = nmo
               channel_multiplicity(global_channel) = &
                  MAX(1, local_ot_env(local_channel)%kpoint_multiplicity)
               channel_maxocc(global_channel) = maxocc
            END DO
         END DO
         IF (global_schur_replicated) THEN
            CALL para_env_inter_kp%sum(channel_multiplicity)
            CALL para_env_inter_kp%sum(channel_nmo)
            CALL para_env_inter_kp%sum(channel_maxocc)
         END IF
         max_channel_nmo = MAX(1, MAXVAL(channel_nmo))
         ALLOCATE (channel_density_pair_residual(max_channel_nmo, max_channel_nmo, nchannels), &
                   channel_density_pair_active(max_channel_nmo, max_channel_nmo, nchannels), &
                   channel_density_pair_candidate(max_channel_nmo, max_channel_nmo, nchannels), &
                   channel_fermi_pair_active(max_channel_nmo, max_channel_nmo, nchannels), &
                   channel_residual_pair_active(max_channel_nmo, max_channel_nmo, nchannels), &
                   channel_residual_pair_candidate(max_channel_nmo, max_channel_nmo, nchannels), &
                   channel_residual_pair_score(max_channel_nmo, max_channel_nmo, nchannels))
         channel_density_pair_residual(:, :, :) = 0.0_dp
         channel_density_pair_active(:, :, :) = .FALSE.
         channel_density_pair_candidate(:, :, :) = .FALSE.
         channel_fermi_pair_active(:, :, :) = .FALSE.
         channel_residual_pair_active(:, :, :) = .FALSE.
         channel_residual_pair_candidate(:, :, :) = .FALSE.
         channel_residual_pair_score(:, :, :) = 0.0_dp
         DO local_kpoint = 1, SIZE(kpoints%kp_env)
            kp => kpoints%kp_env(local_kpoint)%kpoint_env
            ikpoint = kp%nkpoint
            DO ispin = 1, nspin_ot
               group = MERGE(ispin, 1, ngroups == nspin_ot)
               IF (group /= target_group) CYCLE
               local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
               global_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot)
               nmo = channel_nmo(global_channel)
               IF (nmo <= 0) CYCLE
               density_pair_shape_ok = &
                  ALLOCATED(local_ot_env(local_channel)%kpoint_density_pair_residual)
               CPASSERT(density_pair_shape_ok)
               density_pair_shape_ok = &
                  SIZE(local_ot_env(local_channel)%kpoint_density_pair_residual, 1) == nmo .AND. &
                  SIZE(local_ot_env(local_channel)%kpoint_density_pair_residual, 2) == nmo
               CPASSERT(density_pair_shape_ok)
               channel_density_pair_residual(1:nmo, 1:nmo, global_channel) = &
                  local_ot_env(local_channel)%kpoint_density_pair_residual(:, :)

               ! Score every complex MO pair in the same physical metric used
               ! by the final fixed-N convergence audit.  This score is kept
               ! separate from canonical-density pair selection: it completes
               ! the reduced rotation basis when an omitted physical gradient,
               ! rather than density stationarity, controls the tail.
               ALLOCATE (canonical_occ_curv_channel(nmo), grad_re(nmo, nmo), grad_im(nmo, nmo))
               canonical_occ_curv_channel(:) = 0.0_dp
               IF (kpoint_ot_monotone_smearing(smear%method) .AND. sigma > EPSILON(sigma) .AND. &
                   maxocc > EPSILON(maxocc)) THEN
                  DO imo = 1, nmo
                     canonical_occ_curv_channel(imo) = wkp(ikpoint)* &
                                                       SmearingDerivative( &
                                                       trial_occupation(imo, ikpoint, ispin), &
                                                       trial_eigenvalues(imo, ikpoint, ispin), &
                                                       trial_mu(ispin), sigma, maxocc, smear%method)
                  END DO
               END IF
               channel_occ_curv_max = MAXVAL(canonical_occ_curv_channel)
               channel_projector_weight = &
                  kpoint_ot_canonical_projector_weight(local_ot_env(local_channel)%delta, &
                                                       ot_kp_canonical_projector_max_weight)
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_gx, grad_re)
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_gx_im, grad_im)
               CALL local_ot_env(local_channel)%para_env%sum(grad_re)
               CALL local_ot_env(local_channel)%para_env%sum(grad_im)
               rot_grad_norm_weight = 1.0_dp/ &
                                      REAL(MAX(1, local_ot_env(local_channel)%kpoint_multiplicity), KIND=dp)
               DO imo = 1, nmo - 1
                  DO jmo = imo + 1, nmo
                     pair_projector_weight = kpoint_ot_pair_projector_weight( &
                                             channel_projector_weight, &
                                             canonical_occ_curv_channel(imo), &
                                             canonical_occ_curv_channel(jmo), channel_occ_curv_max)
                     pair_occ_gap = MIN(1.0_dp, &
                                        ABS(trial_occupation(imo, ikpoint, ispin) - &
                                            trial_occupation(jmo, ikpoint, ispin))/ &
                                        MAX(maxocc, EPSILON(maxocc)))
                     rot_grad_pair_fraction = 0.0_dp
                     IF (channel_projector_weight > EPSILON(channel_projector_weight)) &
                        rot_grad_pair_fraction = pair_projector_weight/channel_projector_weight
                     rot_grad_pair_fraction = MIN(1.0_dp, MAX(0.0_dp, rot_grad_pair_fraction))
                     rot_grad_gap_fraction = kpoint_ot_residual_occ_gap_weight(pair_occ_gap)
                     channel_residual_pair_score(imo, jmo, global_channel) = &
                        rot_grad_norm_weight* &
                        (rot_grad_pair_fraction + &
                         (1.0_dp - rot_grad_pair_fraction)*rot_grad_gap_fraction)* &
                        ((2.0_dp*grad_re(imo, jmo))**2 + (2.0_dp*grad_im(imo, jmo))**2)
                  END DO
               END DO
               DEALLOCATE (canonical_occ_curv_channel, grad_re, grad_im)
            END DO
         END DO
         IF (global_schur_replicated) THEN
            CALL para_env_inter_kp%sum(channel_density_pair_residual)
            CALL para_env_inter_kp%sum(channel_residual_pair_score)
         END IF

         ne = 0
         nrot = 0
         nrot_active = 0
         nrot_density = 0
         nrot_full = 0
         nrot_residual = 0
         residual_pair_full_nvar = 0.0_dp
         schur_active_occ_min = ot_kp_fermi_window_min_frac
         schur_active_subspace = .FALSE.
         schur_energy_window = ot_kp_fermi_window_outer_factor*MAX(sigma, EPSILON(sigma))
         projector_occupation_window_gap = schur_energy_window
         density_pair_activation_threshold = MAX(eps_scf_channel, response_raw_delta)
         density_pair_activation_ready = qs_scf_kp_density_pair_activation_ready( &
                                         local_ot_env(1)%kpoint_density_stationarity_ready, &
                                         local_ot_env(1)%kpoint_density_stationarity_delta, &
                                         response_raw_delta, eps_scf_channel)
         DO global_channel = 1, nchannels
            IF (channel_nmo(global_channel) <= 0) CYCLE
            schur_active_occ_min = MAX(schur_active_occ_min, &
                                       ot_kp_fermi_window_min_frac* &
                                       MAX(channel_maxocc(global_channel), 1.0_dp))
         END DO
         DO global_channel = 1, nchannels
            nmo = channel_nmo(global_channel)
            IF (nmo <= 0) CYCLE
            global_spin = MOD(global_channel - 1, nspin_ot) + 1
            global_kpoint = (global_channel - 1)/nspin_ot + 1
            group = MERGE(global_spin, 1, ngroups == nspin_ot)
            IF (group /= target_group) CYCLE
            maxocc = channel_maxocc(global_channel)
            e_offset(global_channel) = ne + 1
            ne = ne + nmo
            channel_full_var_offset(global_channel) = nrot_full + 1
            nrot_full = nrot_full + nmo*(nmo - 1)
            residual_pair_full_nvar = residual_pair_full_nvar + &
                                      REAL(MAX(1, channel_multiplicity(global_channel)), KIND=dp)* &
                                      REAL(nmo*(nmo - 1), KIND=dp)
            DO imo = 1, nmo - 1
               DO jmo = imo + 1, nmo
                  occ_tail_i = MAX(0.0_dp, MIN(trial_occupation(imo, global_kpoint, global_spin), &
                                               maxocc - trial_occupation(imo, global_kpoint, global_spin)))
                  occ_tail_j = MAX(0.0_dp, MIN(trial_occupation(jmo, global_kpoint, global_spin), &
                                               maxocc - trial_occupation(jmo, global_kpoint, global_spin)))
                  fermi_active_pair = MAX(occ_tail_i, occ_tail_j) >= schur_active_occ_min .OR. &
                                      ABS(trial_eigenvalues(imo, global_kpoint, global_spin) - &
                                          trial_mu(global_spin)) <= schur_energy_window .OR. &
                                      ABS(trial_eigenvalues(jmo, global_kpoint, global_spin) - &
                                          trial_mu(global_spin)) <= schur_energy_window
                  channel_fermi_pair_active(imo, jmo, global_channel) = fermi_active_pair
                  IF (.NOT. fermi_active_pair .AND. density_pair_activation_ready .AND. &
                      channel_density_pair_residual(imo, jmo, global_channel) > &
                      density_pair_activation_threshold) THEN
                     channel_density_pair_candidate(imo, jmo, global_channel) = .TRUE.
                  END IF
               END DO
            END DO
         END DO
         nrot_active = 2*COUNT(channel_fermi_pair_active)
         schur_active_subspace = nrot_full > max_schur_rot
         density_pair_available = MAX(0, (max_schur_rot - nrot_active)/2)
         density_pair_candidates = COUNT(channel_density_pair_candidate)
         IF (density_pair_candidates <= density_pair_available) THEN
            channel_density_pair_active(:, :, :) = channel_density_pair_candidate(:, :, :)
         ELSE
            DO r = 1, density_pair_available
               density_pair_location = MAXLOC(channel_density_pair_residual, &
                                              MASK=channel_density_pair_candidate)
               channel_density_pair_active(density_pair_location(1), density_pair_location(2), &
                                           density_pair_location(3)) = .TRUE.
               channel_density_pair_candidate(density_pair_location(1), density_pair_location(2), &
                                              density_pair_location(3)) = .FALSE.
            END DO
         END IF
         nrot_density = 2*COUNT(channel_density_pair_active)
         nrot_active = nrot_active + nrot_density

         residual_pair_selection_ready = schur_active_subspace .AND. eps_scf_channel > 0.0_dp
         residual_pair_strict_tail = residual_pair_selection_ready .AND. &
                                     response_raw_delta <= &
                                     ot_kp_schur_residual_pair_tail_eps_factor*eps_scf_channel
         IF (residual_pair_selection_ready) THEN
            DO global_channel = 1, nchannels
               nmo = channel_nmo(global_channel)
               IF (nmo <= 0) CYCLE
               DO imo = 1, nmo - 1
                  DO jmo = imo + 1, nmo
                     channel_residual_pair_candidate(imo, jmo, global_channel) = &
                        .NOT. channel_fermi_pair_active(imo, jmo, global_channel) .AND. &
                        .NOT. channel_density_pair_active(imo, jmo, global_channel) .AND. &
                        channel_residual_pair_score(imo, jmo, global_channel) > 0.0_dp
                  END DO
               END DO
            END DO
         END IF
         residual_pair_available = MAX(0, (max_schur_rot - nrot_active)/2)
         residual_pair_candidates = COUNT(channel_residual_pair_candidate)
         residual_pair_active_score = SUM(channel_residual_pair_score, &
                                          MASK=channel_fermi_pair_active .OR. &
                                          channel_density_pair_active)
         residual_pair_total_score = SUM(channel_residual_pair_score, &
                                         MASK=channel_residual_pair_candidate)
         residual_pair_omitted_score = residual_pair_total_score
         residual_pair_omitted_limit = qs_scf_kp_residual_pair_capture_limit( &
                                       eps_scf_channel, residual_pair_full_nvar, &
                                       residual_pair_active_score, residual_pair_strict_tail)
         DO r = 1, MIN(residual_pair_candidates, residual_pair_available)
            IF (residual_pair_omitted_score <= residual_pair_omitted_limit) EXIT
            residual_pair_location = MAXLOC(channel_residual_pair_score, &
                                            MASK=channel_residual_pair_candidate)
            channel_residual_pair_active(residual_pair_location(1), residual_pair_location(2), &
                                         residual_pair_location(3)) = .TRUE.
            channel_residual_pair_candidate(residual_pair_location(1), residual_pair_location(2), &
                                            residual_pair_location(3)) = .FALSE.
            residual_pair_omitted_score = MAX( &
                                          0.0_dp, residual_pair_omitted_score - &
                                          channel_residual_pair_score(residual_pair_location(1), &
                                                                      residual_pair_location(2), &
                                                                      residual_pair_location(3)))
         END DO
         nrot_residual = 2*COUNT(channel_residual_pair_active)
         nrot_active = nrot_active + nrot_residual
         nrot = MERGE(nrot_active, nrot_full, schur_active_subspace)
         IF (schur_active_subspace) THEN
            CALL qs_scf_kp_pair_mask_moments( &
               channel_fermi_pair_active, channel_density_pair_active, &
               channel_residual_pair_active, channel_nmo, pair_identity_count, &
               pair_identity_moment, pair_identity_square_moment)
         END IF

         ivar = 0
         DO global_channel = 1, nchannels
            nmo = channel_nmo(global_channel)
            IF (nmo <= 0) CYCLE
            global_spin = MOD(global_channel - 1, nspin_ot) + 1
            global_kpoint = (global_channel - 1)/nspin_ot + 1
            group = MERGE(global_spin, 1, ngroups == nspin_ot)
            IF (group /= target_group) CYCLE
            maxocc = channel_maxocc(global_channel)
            channel_var_offset(global_channel) = ivar + 1
            DO imo = 1, nmo - 1
               DO jmo = imo + 1, nmo
                  IF (schur_active_subspace) THEN
                     occ_tail_i = MAX(0.0_dp, MIN(trial_occupation(imo, global_kpoint, global_spin), &
                                                  maxocc - trial_occupation(imo, global_kpoint, global_spin)))
                     occ_tail_j = MAX(0.0_dp, MIN(trial_occupation(jmo, global_kpoint, global_spin), &
                                                  maxocc - trial_occupation(jmo, global_kpoint, global_spin)))
                     active_pair = MAX(occ_tail_i, occ_tail_j) >= schur_active_occ_min .OR. &
                                   ABS(trial_eigenvalues(imo, global_kpoint, global_spin) - &
                                       trial_mu(global_spin)) <= schur_energy_window .OR. &
                                   ABS(trial_eigenvalues(jmo, global_kpoint, global_spin) - &
                                       trial_mu(global_spin)) <= schur_energy_window .OR. &
                                   channel_density_pair_active(imo, jmo, global_channel) .OR. &
                                   channel_residual_pair_active(imo, jmo, global_channel)
                     IF (.NOT. active_pair) CYCLE
                  END IF
                  channel_nrot(global_channel) = channel_nrot(global_channel) + 2
                  ivar = ivar + 2
               END DO
            END DO
         END DO
         CPASSERT(ivar == nrot)

         IF (ne == 0 .OR. nrot == 0 .OR. nrot > max_schur_rot) THEN
            IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
               WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,4(1X,I8),1(1X,L1))') &
               " OT Schur skipped group ne nrot full max active:", &
               target_group, ne, nrot, nrot_full, max_schur_rot, schur_active_subspace
            DEALLOCATE (canonical_density_cauchy_channel, channel_full_var_offset, &
                        channel_multiplicity, channel_nmo, &
                        channel_nrot, channel_var_offset, channel_maxocc, e_offset, &
                        channel_density_pair_residual, &
                        channel_density_pair_active, channel_density_pair_candidate, &
                        channel_fermi_pair_active, channel_residual_pair_active, &
                        channel_residual_pair_candidate, channel_residual_pair_score)
            RETURN
         END IF
         IF (schur_active_subspace .AND. logger%iter_info%print_level >= debug_print_level .AND. &
             logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,4(1X,I8),2(1X,ES16.8))') &
            " OT Schur active subspace group ne nrot full max occ ewin:", &
            target_group, ne, nrot, nrot_full, max_schur_rot, schur_active_occ_min, schur_energy_window
         IF (schur_active_subspace .AND. logger%iter_info%print_level >= debug_print_level .AND. &
             logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,3(1X,I8),1X,L1,3(1X,ES16.8))') &
            " OT Schur density-pair activation group selected candidates capacity ready density raw threshold:", &
            target_group, nrot_density/2, density_pair_candidates, density_pair_available, &
            density_pair_activation_ready, local_ot_env(1)%kpoint_density_stationarity_delta, &
            response_raw_delta, density_pair_activation_threshold
         IF (schur_active_subspace .AND. logger%iter_info%print_level >= debug_print_level .AND. &
             logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,3(1X,I8),2(1X,L1),4(1X,ES16.8))') &
            " OT Schur residual-pair completion group selected candidates capacity ready strict represented total omitted limit:", &
            target_group, nrot_residual/2, residual_pair_candidates, residual_pair_available, &
            residual_pair_selection_ready, residual_pair_strict_tail, residual_pair_active_score, &
            residual_pair_total_score, residual_pair_omitted_score, residual_pair_omitted_limit
         IF (schur_active_subspace .AND. logger%iter_info%print_level >= debug_print_level .AND. &
             logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,3(1X,I18),1X,L1)') &
            " OT Schur active-pair identity group count moment square new_search:", &
            target_group, pair_identity_count, pair_identity_moment, &
            pair_identity_square_moment, new_search_point

         ALLOCATE (canonical_occ_curv(ne), curv(ne), grad_e(ne), occ_curv(ne), tether_curv(ne), &
                   z_e(ne), accepted_z_e(ne), &
                   density_basis_selective_floor_weight(ne), energy_grad_metric_weight(ne), &
                   energy_step_weight(ne), z_exact_raw_trial(ne), &
                   z_exact_active_trial(ne), z_exact_physical_trial(ne), z_exact_trial(ne), &
                   z_multisecant(ne), z_trial(ne), &
                   rx_e(ne), rx_model(ne), &
                   constrained_z_e(ne), projector_physical_direct_curv_eval(nrot), &
                   projector_physical_direct_model_e(ne), &
                   direct_pg_base_e(ne), direct_pg_rx_e(ne), &
                   projector_physical_direct_response_rx_e(ne), &
                   projector_physical_direct_diagref_rx_e(ne), &
                   projector_physical_direct_effective_rx_e(ne), &
                   projector_physical_direct_density_rx_e(ne), &
                   projector_physical_direct_density_sol(nrot), &
                   projector_physical_direct_density_z_e(ne), &
                   density_descent_rx_e(ne), &
                   density_descent_sol(nrot), &
                   density_descent_z_e(ne), &
                   density_full_rx_e(ne), &
                   density_full_global_rx_e(ne), &
                   density_full_global_sol(nrot), &
                   density_full_sol(nrot), &
                   density_full_z_e(ne), &
                   density_gap_projected_e(ne), &
                   density_gap_rx_e(ne), &
                   density_gap_trial_basis_e(ne), &
                   density_gap_trial_projected_e(ne), &
                   density_plateau_rx_e(ne), density_plateau_z_e(ne), &
                   projector_physical_direct_rx_e(ne), projector_physical_direct_schur_eval(nrot), &
                   projector_physical_direct_spectral_model_e(ne), &
                   projector_physical_direct_spectral_rx_e(ne), &
                   z_density_basis_audit_trial(ne), z_density_basis_curvfloor_audit_trial(ne), &
                   z_density_basis_selective_audit_trial(ne), &
                   z_density_basis_damped_audit_trial(ne), &
                   z_density_basis_filtered_audit_trial(ne), &
                   z_density_plateau_trial(ne), z_density_floor_audit_trial(ne), &
                   z_density_floor_safe_audit_trial(ne), z_density_full_audit_trial(ne), &
                   z_density_full_global_trial(ne), &
                   z_density_full_trial(ne), z_density_trial(ne), &
                   projector_physical_direct_z_e(ne), &
                   projector_physical_direct_spectral_z_e(ne), &
                   projector_offdiag_rx_e(ne), projector_offdiag_z_e(ne), &
                   projector_inactive_offdiag_rx_e(ne), &
                   projector_inactive_offdiag_z_e(ne), &
                   projector_physical_model_e(ne), projector_physical_rx_e(ne), &
                   projector_physical_z_e(ne), projector_response_rx_e(ne), &
                   projector_response_z_e(ne), prediction_z_base(ne), prediction_z_e(ne), &
                   reduced_secant_response_step(ne), reduced_secant_z_e(ne), &
                   closure_candidate_z_e(ne), split_z_e(ne))
         ALLOCATE (full_grad_rot(nrot_full), &
                   full_var_physical_grad_metric_weight(nrot_full), &
                   grad_rot(nrot), rhs(nrot), rtd(nrot), sol(nrot), accepted_sol(nrot), &
                   canonical_density_tangent(nrot), canonical_density_trial_sol(nrot), constrained_sol(nrot), &
                   projector_physical_direct_sol(nrot), projector_physical_sol(nrot), &
                   projector_physical_direct_spectral_sol(nrot), &
                   projector_offdiag_sol(nrot), projector_inactive_offdiag_sol(nrot), &
                   projector_response_sol(nrot), prediction_sol(nrot), reduced_secant_sol(nrot), &
                   closure_candidate_sol(nrot), split_sol(nrot), &
                   var_grad_metric_weight(nrot), var_occ_gap_weight(nrot), &
                   var_physical_grad_metric_weight(nrot), &
                   var_projector_active_weight(nrot), var_projector_response_weight(nrot), &
                   var_projector_weight(nrot), var_step_weight(nrot), var_thermal_activity(nrot))
         ALLOCATE (canonical_density_mode_alpha(nchannels), canonical_density_mode_curvature(nchannels), &
                   canonical_density_mode_linear(nchannels), canonical_density_tangent_modes(nrot, nchannels))
         ALLOCATE (canonical_density_trial_raw_rx_e(ne))
         ALLOCATE (var_channel(nrot), var_ei(nrot), var_ej(nrot), var_i(nrot), var_j(nrot), &
                   var_kind(nrot), var_full_index(nrot))
         ALLOCATE (rot_floor(nrot), row_floor_shift(nrot), projector_physical_direct_active_lcomp(nrot))
         ALLOCATE (energy_cross(ne, nrot), energy_cross_active(ne, nrot), &
                   energy_cross_canonical(ne, nrot), energy_cross_density(ne, nrot), &
                   energy_cross_density_direct(ne, nrot), &
                   energy_cross_density_basis_audit(ne, nrot), &
                   energy_cross_density_basis_curvfloor_audit(ne, nrot), &
                   energy_cross_density_basis_damped_audit(ne, nrot), &
                   energy_cross_density_basis_filtered_audit(ne, nrot), &
                   energy_cross_density_basis_selective_audit(ne, nrot), &
                   energy_cross_density_floor_audit(ne, nrot), &
                   energy_cross_density_floor_safe_audit(ne, nrot), &
                   energy_cross_density_full(ne, nrot), &
                   energy_cross_density_full_audit(ne, nrot), &
                   energy_cross_density_full_global(ne, nrot), energy_cross_density_plateau(ne, nrot), &
                   energy_cross_multisecant(ne, nrot), &
                   energy_cross_prediction(ne, nrot), &
                   energy_cross_physical_model(ne, nrot), &
                   energy_cross_raw(ne, nrot), energy_hessian(ne, ne), &
                   energy_hessian_multisecant(ne, ne), energy_hessian_prediction(ne, ne), &
                   energy_hessian_reference(ne, ne), &
                   response(ne, nrot), response_coupled(ne, nrot), &
                   response_density_direct_exact(ne, nrot), &
                   response_density_exact(ne, nrot), response_density_physical(ne, nrot), &
                   response_density_basis_audit(ne, nrot), response_density_basis_audit_exact(ne, nrot), &
                   response_density_basis_curvfloor_audit_exact(ne, nrot), &
                   response_density_basis_damped_audit(ne, nrot), &
                   response_density_basis_damped_audit_exact(ne, nrot), &
                   response_density_basis_filtered_audit(ne, nrot), &
                   response_density_basis_filtered_audit_exact(ne, nrot), &
                   response_density_basis_selective_audit_exact(ne, nrot), &
                   response_density_floor_audit(ne, nrot), &
                   response_density_floor_safe_audit(ne, nrot), &
                   response_density_full(ne, nrot), response_density_plateau(ne, nrot), &
                   response_density_full_audit(ne, nrot), response_density_full_audit_exact(ne, nrot), &
                   response_density_floor_audit_exact(ne, nrot), &
                   response_density_floor_safe_audit_exact(ne, nrot), &
                   response_density_full_exact(ne, nrot), &
                   response_density_full_global(ne, nrot), response_density_full_global_exact(ne, nrot), &
                   response_density_plateau_exact(ne, nrot), &
                   response_exact(ne, nrot), response_exact_active(ne, nrot), &
                   response_exact_physical(ne, nrot), &
                   response_exact_raw(ne, nrot), response_multisecant(ne, nrot), &
                   response_occ(ne, nrot), response_occ_canonical(ne, nrot), &
                   response_occ_physical(ne, nrot), &
                   response_physical_model(ne, nrot), &
                   response_prediction(ne, nrot), &
                   response_split(ne, nrot), &
                   rot_hessian(nrot, nrot), closure_response_steps(nrot, 3), &
                   closure_response_targets(nrot, 3), closure_density_probe_steps(nrot, 3), &
                   closure_density_probe_targets(nrot, 3), &
                   closure_coupled_full_cross_correction(ne, nrot), &
