         density_basis_selective_history_gap_drop = 0.0_dp
         density_basis_selective_history_quality = 0.0_dp
         density_basis_selective_history_trust_quality = 1.0_dp
         density_basis_selective_history_weighted_step = 0.0_dp
         density_basis_selective_history_weighted_trust_ratio = 0.0_dp
         density_basis_filtered_history_abs_step = 0.0_dp
         density_basis_filtered_history_abs_trust_ratio = 0.0_dp
         density_basis_filtered_history_drop = 0.0_dp
         density_basis_filtered_history_gap_drop = 0.0_dp
         density_basis_filtered_history_quality = 0.0_dp
         density_basis_filtered_history_trust_quality = 1.0_dp
         density_basis_filtered_history_weighted_step = 0.0_dp
         density_basis_filtered_history_weighted_trust_ratio = 0.0_dp
         density_basis_damped_history_abs_step = 0.0_dp
         density_basis_damped_history_abs_trust_ratio = 0.0_dp
         density_basis_damped_history_drop = 0.0_dp
         density_basis_damped_history_gap_drop = 0.0_dp
         density_basis_damped_history_quality = 0.0_dp
         density_basis_damped_history_trust_quality = 1.0_dp
         density_basis_damped_history_weighted_step = 0.0_dp
         density_basis_damped_history_weighted_trust_ratio = 0.0_dp
         exact_density_plateau_response_ready = .FALSE.
         exact_density_response_ready = .FALSE.
         exact_density_direct_response_ready = .FALSE.
         exact_density_basis_audit_ready = .FALSE.
         exact_density_basis_curvfloor_audit_ready = .FALSE.
         exact_density_basis_damped_audit_ready = .FALSE.
         exact_density_basis_filtered_audit_ready = .FALSE.
         exact_density_basis_selective_audit_ready = .FALSE.
         exact_density_full_audit_ready = .FALSE.
         exact_density_floor_audit_ready = .FALSE.
         exact_density_floor_safe_audit_ready = .FALSE.
         exact_density_full_response_ready = .FALSE.
         density_full_candidate_ready = .FALSE.
         density_full_candidate_selected = .FALSE.
         density_full_direct_candidate_ready = .FALSE.
         density_full_direct_candidate_selected = .FALSE.
         density_full_direct_coupled_model_ready = .FALSE.
         density_full_direct_closure_ready = .FALSE.
         density_full_direct_tail_probe_ready = .FALSE.
         density_full_global_bootstrap_ready = .FALSE.
         density_full_global_candidate_ready = .FALSE.
         density_full_global_candidate_selected = .FALSE.
         density_full_global_history_ready = .FALSE.
         density_full_global_tail_prefer = .FALSE.
         density_full_global_tail_probe_ready = .FALSE.
         density_full_tail_probe_ready = .FALSE.
         density_descent_candidate_ready = .FALSE.
         density_descent_candidate_selected = .FALSE.
         density_descent_tail_probe_ready = .FALSE.
         exact_active_response_ready = .FALSE.
         exact_physical_response_ready = .FALSE.
         failed = .FALSE.
         constrained_candidate_ready = .FALSE.
         constrained_candidate_selected = .FALSE.
         projector_physical_candidate_ready = .FALSE.
         projector_physical_candidate_selected = .FALSE.
         projector_physical_direct_candidate_ready = .FALSE.
         projector_physical_direct_candidate_selected = .FALSE.
         projector_physical_direct_candidate_used = .FALSE.
         projector_physical_direct_density_candidate_ready = .FALSE.
         projector_physical_direct_density_candidate_selected = .FALSE.
         projector_physical_direct_density_override_protected = .FALSE.
         projector_physical_direct_density_quality_ready = .FALSE.
         projector_physical_direct_density_residual_bad = .FALSE.
         projector_physical_direct_density_selected_probe_ready = .FALSE.
         projector_physical_direct_density_tail_probe_ready = .FALSE.
         projector_physical_direct_spectral_candidate_ready = .FALSE.
         projector_physical_direct_spectral_candidate_selected = .FALSE.
         projector_physical_direct_spectral_probe_ready = .FALSE.
         projector_physical_direct_spectral_probe_selected = .FALSE.
         projector_offdiag_candidate_ready = .FALSE.
         projector_offdiag_candidate_selected = .FALSE.
         projector_offdiag_candidate_inactive = .FALSE.
         projector_inactive_offdiag_candidate_ready = .FALSE.
         projector_inactive_offdiag_tail_refresh_probe = .FALSE.
         projector_inactive_offdiag_tail_refresh_ready = .FALSE.
         projector_response_candidate_ready = .FALSE.
         projector_response_candidate_selected = .FALSE.
         split_candidate_ready = .FALSE.
         split_candidate_selected = .FALSE.
         projector_fd_cluster_derivatives = 0
         projector_fd_cluster_replacements = 0
         projector_kernel_cluster_groups = 0
         split_selected_attempt = 0

         ! A rotation perturbation is local to one irreducible k point, while
         ! its fixed-N chemical-potential response is shared by the complete
         ! spin/k-point group.  Build that global susceptibility before any
         ! channel-local finite Projector derivative is formed.
         canonical_fixed_n_curv_sum = 0.0_dp
         DO local_kpoint = 1, SIZE(kpoints%kp_env)
            kp => kpoints%kp_env(local_kpoint)%kpoint_env
            ikpoint = kp%nkpoint
            DO ispin = 1, nspin_ot
               group = MERGE(ispin, 1, ngroups == nspin_ot)
               IF (group /= target_group) CYCLE
               local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
               CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, nmo=nmo)
               ALLOCATE (canonical_eigenvalue_channel(nmo), canonical_occupation_channel(nmo), &
                         canonical_occ_curv_channel(nmo))
               canonical_eigenvalue_channel(:) = trial_eigenvalues(1:nmo, ikpoint, ispin)
               canonical_occupation_channel(:) = trial_occupation(1:nmo, ikpoint, ispin)
               canonical_mu_channel = trial_mu(ispin)
               IF (local_ot_env(local_channel)%kpoint_canonical_occupation_ready) THEN
                  density_pair_shape_ok = &
                     ALLOCATED(local_ot_env(local_channel)%kpoint_canonical_occupation)
                  CPASSERT(density_pair_shape_ok)
                  density_pair_shape_ok = &
                     SIZE(local_ot_env(local_channel)%kpoint_canonical_occupation) == nmo
                  CPASSERT(density_pair_shape_ok)
                  density_pair_shape_ok = &
                     ALLOCATED(local_ot_env(local_channel)%kpoint_canonical_eigenvalue)
                  CPASSERT(density_pair_shape_ok)
                  density_pair_shape_ok = &
                     SIZE(local_ot_env(local_channel)%kpoint_canonical_eigenvalue) == nmo
                  CPASSERT(density_pair_shape_ok)
                  canonical_occupation_channel(:) = &
                     local_ot_env(local_channel)%kpoint_canonical_occupation(:)
                  canonical_eigenvalue_channel(:) = &
                     local_ot_env(local_channel)%kpoint_canonical_eigenvalue(:)
                  canonical_mu_channel = local_ot_env(local_channel)%kpoint_canonical_mu
               END IF
               canonical_occ_curv_channel(:) = 0.0_dp
               IF (kpoint_ot_monotone_smearing(smear%method) .AND. sigma > EPSILON(sigma) .AND. &
                   maxocc > EPSILON(maxocc)) THEN
                  DO imo = 1, nmo
                     canonical_occ_curv_channel(imo) = wkp(ikpoint)* &
                                                       SmearingDerivative(canonical_occupation_channel(imo), &
                                                                          canonical_eigenvalue_channel(imo), &
                                                                          canonical_mu_channel, sigma, maxocc, &
                                                                          smear%method)
                  END DO
               END IF
               WHERE (canonical_occ_curv_channel <= &
                      SQRT(EPSILON(1.0_dp))*MAXVAL(canonical_occ_curv_channel))
                  canonical_occ_curv_channel = 0.0_dp
               END WHERE
               canonical_fixed_n_curv_sum = canonical_fixed_n_curv_sum + &
                                            SUM(canonical_occ_curv_channel)
               DEALLOCATE (canonical_eigenvalue_channel, canonical_occupation_channel, &
                           canonical_occ_curv_channel)
            END DO
         END DO
         IF (global_schur_replicated) &
            CALL para_env_inter_kp%sum(canonical_fixed_n_curv_sum)

         ivar = 0
         constrained_sol(:) = 0.0_dp
         constrained_z_e(:) = 0.0_dp
         projector_physical_direct_sol(:) = 0.0_dp
         projector_physical_direct_z_e(:) = 0.0_dp
         projector_physical_direct_density_sol(:) = 0.0_dp
         projector_physical_sol(:) = 0.0_dp
         projector_physical_z_e(:) = 0.0_dp
         split_sol(:) = 0.0_dp
         split_z_e(:) = 0.0_dp
         energy_closure_candidate_selected = .FALSE.

         DO local_kpoint = 1, SIZE(kpoints%kp_env)
            kp => kpoints%kp_env(local_kpoint)%kpoint_env
            ikpoint = kp%nkpoint
            DO ispin = 1, nspin_ot
               group = MERGE(ispin, 1, ngroups == nspin_ot)
               IF (group /= target_group) CYCLE
               local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
               global_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot)
               channel_projector_weight = &
                  kpoint_ot_canonical_projector_weight(local_ot_env(local_channel)%delta, &
                                                       ot_kp_canonical_projector_max_weight)
               CALL get_mo_set(kp%mos(1, ispin), maxocc=maxocc, nmo=nmo)
               mu = trial_mu(ispin)
               ALLOCATE (h_re(nmo, nmo), h_im(nmo, nmo), grad_re(nmo, nmo), grad_im(nmo, nmo), &
                         canonical_eigenvalue_channel(nmo), canonical_occupation_channel(nmo), &
                         canonical_occ_curv_channel(nmo))
               canonical_eigenvalue_channel(:) = trial_eigenvalues(1:nmo, ikpoint, ispin)
               canonical_occupation_channel(:) = trial_occupation(1:nmo, ikpoint, ispin)
               canonical_mu_channel = mu
               IF (local_ot_env(local_channel)%kpoint_canonical_occupation_ready) THEN
                  density_pair_shape_ok = &
                     ALLOCATED(local_ot_env(local_channel)%kpoint_canonical_occupation)
                  CPASSERT(density_pair_shape_ok)
                  density_pair_shape_ok = &
                     SIZE(local_ot_env(local_channel)%kpoint_canonical_occupation) == nmo
                  CPASSERT(density_pair_shape_ok)
                  canonical_occupation_channel(:) = &
                     local_ot_env(local_channel)%kpoint_canonical_occupation(:)
                  density_pair_shape_ok = &
                     ALLOCATED(local_ot_env(local_channel)%kpoint_canonical_eigenvalue)
                  CPASSERT(density_pair_shape_ok)
                  density_pair_shape_ok = &
                     SIZE(local_ot_env(local_channel)%kpoint_canonical_eigenvalue) == nmo
                  CPASSERT(density_pair_shape_ok)
                  canonical_eigenvalue_channel(:) = &
                     local_ot_env(local_channel)%kpoint_canonical_eigenvalue(:)
                  canonical_mu_channel = local_ot_env(local_channel)%kpoint_canonical_mu
               END IF
               canonical_occ_curv_channel(:) = 0.0_dp
               IF (kpoint_ot_monotone_smearing(smear%method) .AND. sigma > EPSILON(sigma) .AND. &
                   maxocc > EPSILON(maxocc)) THEN
                  DO imo = 1, nmo
                     canonical_occ_curv_channel(imo) = wkp(ikpoint)* &
                                                       SmearingDerivative(canonical_occupation_channel(imo), &
                                                                          canonical_eigenvalue_channel(imo), &
                                                                          canonical_mu_channel, sigma, maxocc, &
                                                                          smear%method)
                  END DO
               END IF
               WHERE (canonical_occ_curv_channel <= &
                      SQRT(EPSILON(1.0_dp))*MAXVAL(canonical_occ_curv_channel))
                  canonical_occ_curv_channel = 0.0_dp
               END WHERE
               canonical_occ_curv(e_offset(global_channel):e_offset(global_channel) + nmo - 1) = &
                  canonical_occ_curv_channel(:)
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_chc, h_re)
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_chc_im, h_im)
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_gx, grad_re)
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_gx_im, grad_im)
               CALL local_ot_env(local_channel)%para_env%sum(h_re)
               CALL local_ot_env(local_channel)%para_env%sum(h_im)
               CALL local_ot_env(local_channel)%para_env%sum(grad_re)
               CALL local_ot_env(local_channel)%para_env%sum(grad_im)
               rot_grad_norm_weight = 1.0_dp/ &
                                      REAL(MAX(1, local_ot_env(local_channel)%kpoint_multiplicity), KIND=dp)

               tether_strength = 0.0_dp
               IF (local_ot_env(local_channel)%settings%canonical_tether) THEN
                  rayleigh_edge_gap = 0.0_dp
                  DO imo = 1, nmo
                     tether_response = kpoint_ot_canonical_tether_response(trial_occupation(imo, ikpoint, ispin), &
                                                                           trial_eigenvalues(imo, ikpoint, ispin), mu, &
                                                                           sigma, maxocc, smear%method)
                     IF (tether_response > 0.0_dp) &
                        rayleigh_edge_gap = MAX(rayleigh_edge_gap, &
                                                ABS(h_re(imo, imo) - local_ot_env(local_channel)%ener_x(imo)))
                  END DO
                  tether_strength = kpoint_ot_canonical_tether_strength(local_ot_env(local_channel), &
                                                                        rayleigh_edge_gap, sigma)
               END IF

               DO imo = 1, nmo
                  ie = e_offset(global_channel) + imo - 1
                  gvalue = SmearingDerivative(trial_occupation(imo, ikpoint, ispin), &
                                              trial_eigenvalues(imo, ikpoint, ispin), mu, &
                                              sigma, maxocc, smear%method)
                  tether_weight = kpoint_ot_canonical_tether_weight(trial_occupation(imo, ikpoint, ispin), &
                                                                    trial_eigenvalues(imo, ikpoint, ispin), &
                                                                    mu, sigma, maxocc, smear%method, &
                                                                    wkp(ikpoint), tether_strength)
                  occ_curv(ie) = wkp(ikpoint)*gvalue
                  tether_curv(ie) = tether_weight
                  curv(ie) = occ_curv(ie) + tether_curv(ie)
                  grad_e(ie) = local_ot_env(local_channel)%ener_gx(imo)
                  energy_grad_metric_weight(ie) = rot_grad_norm_weight
                  energy_step_weight(ie) = 1.0_dp/rot_grad_norm_weight
               END DO
               channel_occ_curv_max = MAXVAL(occ_curv(e_offset(global_channel): &
                                                      e_offset(global_channel) + nmo - 1))

               ! The dense Schur solve may use only a thermal/density-selected subset of MO
               ! pairs.  Keep a stable full-pair ordering for accepted-response prediction so
               ! that a response which leaves that subset is still visible at the endpoint.
               ifull = channel_full_var_offset(global_channel) - 1
               DO imo = 1, nmo - 1
                  DO jmo = imo + 1, nmo
                     pair_projector_weight = kpoint_ot_pair_projector_weight( &
                                             channel_projector_weight, &
                                             occ_curv(e_offset(global_channel) + imo - 1), &
                                             occ_curv(e_offset(global_channel) + jmo - 1), &
                                             channel_occ_curv_max)
                     pair_occ_gap = MIN(1.0_dp, &
                                        ABS(trial_occupation(imo, ikpoint, ispin) - &
                                            trial_occupation(jmo, ikpoint, ispin))/ &
                                        MAX(maxocc, EPSILON(maxocc)))
                     rot_grad_pair_fraction = 0.0_dp
                     IF (channel_projector_weight > EPSILON(channel_projector_weight)) &
                        rot_grad_pair_fraction = pair_projector_weight/channel_projector_weight
                     rot_grad_pair_fraction = MIN(1.0_dp, MAX(0.0_dp, rot_grad_pair_fraction))
                     rot_grad_gap_fraction = kpoint_ot_residual_occ_gap_weight(pair_occ_gap)
                     ifull = ifull + 1
                     full_grad_rot(ifull) = 2.0_dp*grad_re(imo, jmo)
                     full_var_physical_grad_metric_weight(ifull) = rot_grad_norm_weight* &
                                                                   (rot_grad_pair_fraction + &
                                                                    (1.0_dp - rot_grad_pair_fraction)*rot_grad_gap_fraction)
                     ifull = ifull + 1
                     full_grad_rot(ifull) = 2.0_dp*grad_im(imo, jmo)
                     full_var_physical_grad_metric_weight(ifull) = &
                        full_var_physical_grad_metric_weight(ifull - 1)
                  END DO
               END DO
               failed_i = ifull - channel_full_var_offset(global_channel) + 1
               CPASSERT(failed_i == nmo*(nmo - 1))

               ivar = channel_var_offset(global_channel) - 1
               channel_var_start = ivar + 1
               ifull = channel_full_var_offset(global_channel) - 1
               DO imo = 1, nmo - 1
                  DO jmo = imo + 1, nmo
                     ifull = ifull + 2
                     IF (schur_active_subspace) THEN
                        occ_tail_i = MAX(0.0_dp, MIN(trial_occupation(imo, ikpoint, ispin), &
                                                     maxocc - trial_occupation(imo, ikpoint, ispin)))
                        occ_tail_j = MAX(0.0_dp, MIN(trial_occupation(jmo, ikpoint, ispin), &
                                                     maxocc - trial_occupation(jmo, ikpoint, ispin)))
                        active_pair = MAX(occ_tail_i, occ_tail_j) >= schur_active_occ_min .OR. &
                                      ABS(trial_eigenvalues(imo, ikpoint, ispin) - trial_mu(ispin)) <= &
                                      schur_energy_window .OR. &
                                      ABS(trial_eigenvalues(jmo, ikpoint, ispin) - trial_mu(ispin)) <= &
                                      schur_energy_window .OR. &
                                      channel_density_pair_active(imo, jmo, global_channel) .OR. &
                                      channel_residual_pair_active(imo, jmo, global_channel)
                        IF (.NOT. active_pair) CYCLE
                     END IF
                     ivar = ivar + 1
                     var_channel(ivar) = global_channel
                     var_i(ivar) = imo
                     var_j(ivar) = jmo
                     var_kind(ivar) = 1
                     var_full_index(ivar) = ifull - 1
                     var_ei(ivar) = e_offset(global_channel) + imo - 1
                     var_ej(ivar) = e_offset(global_channel) + jmo - 1
                     pair_projector_weight = kpoint_ot_pair_projector_weight(channel_projector_weight, &
                                                                             occ_curv(var_ei(ivar)), &
                                                                             occ_curv(var_ej(ivar)), &
                                                                             channel_occ_curv_max)
                     pair_occ_gap = MIN(1.0_dp, &
                                        ABS(trial_occupation(imo, ikpoint, ispin) - &
                                            trial_occupation(jmo, ikpoint, ispin))/ &
                                        MAX(maxocc, EPSILON(maxocc)))
                     pair_thermal_activity = 0.0_dp
                     IF (kpoint_ot_monotone_smearing(smear%method) .AND. &
                         sigma > EPSILON(sigma) .AND. &
                         wkp(ikpoint) > EPSILON(wkp(ikpoint)) .AND. maxocc > EPSILON(maxocc)) &
                        pair_thermal_activity = MIN(1.0_dp, MAX(0.0_dp, &
                                                                MAX(occ_curv(var_ei(ivar)), occ_curv(var_ej(ivar)))/ &
                                                      (wkp(ikpoint)*kpoint_ot_smearing_peak_response(sigma, maxocc, smear%method))))
                     var_projector_active_weight(ivar) = pair_projector_weight
                     var_projector_weight(ivar) = channel_projector_weight
                     var_occ_gap_weight(ivar) = pair_occ_gap
                     var_thermal_activity(ivar) = pair_thermal_activity
                     var_grad_metric_weight(ivar) = rot_grad_norm_weight
                     var_step_weight(ivar) = 1.0_dp/rot_grad_norm_weight
                     grad_rot(ivar) = 2.0_dp*grad_re(imo, jmo)
                     rot_floor(ivar) = rotation_curvature_floor
                     IF (MAX(curv(var_ei(ivar)), curv(var_ej(ivar))) > EPSILON(1.0_dp)) &
                        rot_floor(ivar) = schur_frontier_curvature_floor
                     IF (MAX(curv(var_ei(ivar)), curv(var_ej(ivar))) <= EPSILON(1.0_dp) .AND. &
                         pair_occ_gap <= schur_gauge_occ_gap_max) &
                        rot_floor(ivar) = schur_gauge_curvature_floor

                     ivar = ivar + 1
                     var_channel(ivar) = global_channel
                     var_i(ivar) = imo
                     var_j(ivar) = jmo
                     var_kind(ivar) = 2
                     var_full_index(ivar) = ifull
                     var_ei(ivar) = e_offset(global_channel) + imo - 1
                     var_ej(ivar) = e_offset(global_channel) + jmo - 1
                     var_projector_active_weight(ivar) = pair_projector_weight
                     var_projector_weight(ivar) = channel_projector_weight
                     var_occ_gap_weight(ivar) = pair_occ_gap
                     var_thermal_activity(ivar) = pair_thermal_activity
                     var_grad_metric_weight(ivar) = rot_grad_norm_weight
                     var_step_weight(ivar) = 1.0_dp/rot_grad_norm_weight
                     grad_rot(ivar) = 2.0_dp*grad_im(imo, jmo)
                     rot_floor(ivar) = rotation_curvature_floor
                     IF (MAX(curv(var_ei(ivar)), curv(var_ej(ivar))) > EPSILON(1.0_dp)) &
                        rot_floor(ivar) = schur_frontier_curvature_floor
                     IF (MAX(curv(var_ei(ivar)), curv(var_ej(ivar))) <= EPSILON(1.0_dp) .AND. &
                         pair_occ_gap <= schur_gauge_occ_gap_max) &
                        rot_floor(ivar) = schur_gauge_curvature_floor
                  END DO
               END DO
               failed_i = ivar - channel_var_offset(global_channel) + 1
               CPASSERT(failed_i == channel_nrot(global_channel))
               failed_i = ifull - channel_full_var_offset(global_channel) + 1
               CPASSERT(failed_i == nmo*(nmo - 1))
               density_global_lift_control = &
                  kpoint_ot_density_global_lift_control(eps_scf_channel, residual_delta)
               channel_canonical_cauchy_used = .FALSE.
               CALL build_finite_ref_rotation_model(local_channel, nmo, channel_var_start, ivar, &
                                                    channel_full_var_offset(global_channel), &
                                                    e_offset(global_channel), h_re, h_im, grad_re, grad_im, &
                                                    trial_occupation(1:nmo, ikpoint, ispin), wkp(ikpoint), &
                                                    projector_occupation_window_gap, &
                                                    occ_curv(e_offset(global_channel):e_offset(global_channel) + nmo - 1), &
                                                    canonical_occupation_channel, &
                                                    canonical_occ_curv_channel, &
                                                    canonical_fixed_n_curv_sum, &
                                                    var_i, var_j, var_kind, &
                                                    projector_physical_shadow_enabled, &
                                                    projector_density_full_audit_enabled, &
                                                    projector_plateau_gap_model_enabled, &
                                                    step_gauge_quality, density_global_lift_control, &
                                                    rot_hessian, rot_hessian_coupled, &
                                                    full_rot_hessian_coupled, &
                                                    rot_hessian_orbital_schur, rot_hessian_projector, &
                                                    rot_hessian_projector_physical, &
                                                    rot_hessian_projector_physical_offdiag, &
                                                    rot_hessian_projector_physical_offdiag_plateau, response, &
                                                    response_occ, response_occ_canonical, response_occ_physical, &
                                                    response_density_physical, &
                                                    response_density_floor_audit, &
                                                    response_density_floor_safe_audit, response_density_full, &
                                                    response_density_full_audit, &
                                                    response_density_basis_audit, &
                                                    response_density_plateau, &
                                                    canonical_density_tangent, &
                                                    projector_fd_cluster_derivatives, &
                                                    projector_fd_cluster_replacements, &
                                                    projector_kernel_cluster_groups, &
                                                    channel_canonical_cauchy_used, failed)
               canonical_density_cauchy_channel(global_channel) = &
                  MERGE(1, 0, channel_canonical_cauchy_used)
               DEALLOCATE (h_re, h_im, grad_re, grad_im, canonical_eigenvalue_channel, &
                           canonical_occupation_channel, canonical_occ_curv_channel)
            END DO
         END DO

         IF (global_schur_replicated) THEN
            CALL para_env_inter_kp%sum(curv)
            CALL para_env_inter_kp%sum(grad_e)
            CALL para_env_inter_kp%sum(occ_curv)
            CALL para_env_inter_kp%sum(canonical_occ_curv)
            CALL para_env_inter_kp%sum(tether_curv)
            CALL para_env_inter_kp%sum(energy_grad_metric_weight)
            CALL para_env_inter_kp%sum(energy_step_weight)
            CALL para_env_inter_kp%sum(full_grad_rot)
            CALL para_env_inter_kp%sum(full_var_physical_grad_metric_weight)
            CALL para_env_inter_kp%sum(grad_rot)
            CALL para_env_inter_kp%sum(rot_floor)
            CALL para_env_inter_kp%sum(var_channel)
            CALL para_env_inter_kp%sum(var_ei)
            CALL para_env_inter_kp%sum(var_ej)
            CALL para_env_inter_kp%sum(var_i)
            CALL para_env_inter_kp%sum(var_j)
            CALL para_env_inter_kp%sum(var_kind)
            CALL para_env_inter_kp%sum(var_full_index)
            CALL para_env_inter_kp%sum(var_grad_metric_weight)
            CALL para_env_inter_kp%sum(var_occ_gap_weight)
            CALL para_env_inter_kp%sum(var_projector_active_weight)
            CALL para_env_inter_kp%sum(var_projector_weight)
            CALL para_env_inter_kp%sum(var_step_weight)
            CALL para_env_inter_kp%sum(var_thermal_activity)
            CALL para_env_inter_kp%sum(response)
            CALL para_env_inter_kp%sum(response_occ)
            CALL para_env_inter_kp%sum(response_occ_canonical)
            CALL para_env_inter_kp%sum(response_occ_physical)
            CALL para_env_inter_kp%sum(response_density_physical)
            CALL para_env_inter_kp%sum(response_density_floor_audit)
            CALL para_env_inter_kp%sum(response_density_floor_safe_audit)
            CALL para_env_inter_kp%sum(response_density_full)
            CALL para_env_inter_kp%sum(response_density_full_audit)
            CALL para_env_inter_kp%sum(response_density_basis_audit)
            CALL para_env_inter_kp%sum(response_density_plateau)
            CALL para_env_inter_kp%sum(canonical_density_tangent)
            CALL para_env_inter_kp%sum(canonical_density_cauchy_channel)
            CALL para_env_inter_kp%sum(rot_hessian)
            CALL para_env_inter_kp%sum(rot_hessian_coupled)
            CALL para_env_inter_kp%sum(full_rot_hessian_coupled)
            CALL para_env_inter_kp%sum(rot_hessian_orbital_schur)
            CALL para_env_inter_kp%sum(rot_hessian_projector)
            CALL para_env_inter_kp%sum(rot_hessian_projector_physical)
            CALL para_env_inter_kp%sum(rot_hessian_projector_physical_offdiag)
            CALL para_env_inter_kp%sum(rot_hessian_projector_physical_offdiag_plateau)
            CALL para_env_inter_kp%sum(projector_fd_cluster_derivatives)
            CALL para_env_inter_kp%sum(projector_fd_cluster_replacements)
            CALL para_env_inter_kp%sum(projector_kernel_cluster_groups)
            failed_i = MERGE(1, 0, failed)
            CALL para_env_inter_kp%max(failed_i)
            failed = failed_i /= 0
         ELSE
            CPASSERT(ivar == nrot)
         END IF
         CPASSERT(ALL(var_channel > 0))
         CPASSERT(ALL(var_i > 0))
         CPASSERT(ALL(var_j > 0))
         CPASSERT(ALL(var_kind > 0))
         CPASSERT(ALL(var_full_index > 0 .AND. var_full_index <= nrot_full))
         full_rot_grad_physical_norm = &
            DOT_PRODUCT(full_var_physical_grad_metric_weight, full_grad_rot**2)
         rot_grad_active_re = 0.0_dp
         rot_grad_active_im = 0.0_dp
         rot_grad_inactive_re = 0.0_dp
         rot_grad_inactive_im = 0.0_dp
         rot_grad_gap_re = 0.0_dp
         rot_grad_gap_im = 0.0_dp
         rot_grad_gauge_re = 0.0_dp
         rot_grad_gauge_im = 0.0_dp
         rot_grad_active_weight_sum = 0.0_dp
         rot_grad_inactive_weight_sum = 0.0_dp
         rot_grad_gap_weight = 0.0_dp
         rot_grad_gauge_weight = 0.0_dp
         rot_grad_active_fraction_max = 0.0_dp
         physical_delta_nvar = 0.0_dp
         IF (schur_active_subspace) THEN
            DO global_channel = 1, nchannels
               IF (channel_nmo(global_channel) <= 0) CYCLE
               physical_delta_nvar = physical_delta_nvar + &
                                     REAL(MAX(1, channel_multiplicity(global_channel)), KIND=dp)* &
                                     REAL(channel_nmo(global_channel)* &
                                          (channel_nmo(global_channel) - 1), KIND=dp)
            END DO
         END IF
         DO r = 1, nrot
            rot_grad_norm_weight = 1.0_dp/ &
                                   REAL(MAX(1, channel_multiplicity(var_channel(r))), KIND=dp)
            IF (.NOT. schur_active_subspace) &
               physical_delta_nvar = physical_delta_nvar + &
                                     REAL(MAX(1, channel_multiplicity(var_channel(r))), KIND=dp)
            rot_grad_pair_fraction = 0.0_dp
            IF (var_projector_weight(r) > EPSILON(var_projector_weight(r))) &
               rot_grad_pair_fraction = var_projector_active_weight(r)/var_projector_weight(r)
            rot_grad_pair_fraction = MIN(1.0_dp, MAX(0.0_dp, rot_grad_pair_fraction))
            rot_grad_rest_fraction = 1.0_dp - rot_grad_pair_fraction
            rot_grad_fermi_weight = rot_grad_pair_fraction
            rot_grad_gap_fraction = kpoint_ot_residual_occ_gap_weight(var_occ_gap_weight(r))
            var_physical_grad_metric_weight(r) = rot_grad_norm_weight* &
                                                 (rot_grad_pair_fraction + &
                                                  rot_grad_rest_fraction*rot_grad_gap_fraction)
            rot_grad_sq = rot_grad_norm_weight*grad_rot(r)*grad_rot(r)
            rot_grad_gap_weight = rot_grad_gap_weight + &
                                  rot_grad_rest_fraction*rot_grad_gap_fraction
            rot_grad_gauge_weight = rot_grad_gauge_weight + &
                                    rot_grad_rest_fraction*(1.0_dp - rot_grad_gap_fraction)
            IF (var_kind(r) == 1) THEN
               rot_grad_active_re = rot_grad_active_re + rot_grad_pair_fraction*rot_grad_sq
               rot_grad_inactive_re = rot_grad_inactive_re + rot_grad_rest_fraction*rot_grad_sq
               rot_grad_gap_re = rot_grad_gap_re + &
                                 rot_grad_rest_fraction*rot_grad_gap_fraction*rot_grad_sq
               rot_grad_gauge_re = rot_grad_gauge_re + &
                                   rot_grad_rest_fraction*(1.0_dp - rot_grad_gap_fraction)*rot_grad_sq
            ELSE
               rot_grad_active_im = rot_grad_active_im + rot_grad_pair_fraction*rot_grad_sq
               rot_grad_inactive_im = rot_grad_inactive_im + rot_grad_rest_fraction*rot_grad_sq
               rot_grad_gap_im = rot_grad_gap_im + &
                                 rot_grad_rest_fraction*rot_grad_gap_fraction*rot_grad_sq
               rot_grad_gauge_im = rot_grad_gauge_im + &
                                   rot_grad_rest_fraction*(1.0_dp - rot_grad_gap_fraction)*rot_grad_sq
            END IF
            rot_grad_active_weight_sum = rot_grad_active_weight_sum + rot_grad_fermi_weight
            rot_grad_inactive_weight_sum = rot_grad_inactive_weight_sum + rot_grad_rest_fraction
            rot_grad_active_fraction_max = MAX(rot_grad_active_fraction_max, rot_grad_pair_fraction)
         END DO
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(rot_grad_active_re)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(rot_grad_active_im)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(rot_grad_inactive_re)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(rot_grad_inactive_im)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(rot_grad_gap_re)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(rot_grad_gap_im)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(rot_grad_gauge_re)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(rot_grad_gauge_im)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(rot_grad_active_weight_sum)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(rot_grad_inactive_weight_sum)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(rot_grad_gap_weight)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(rot_grad_gauge_weight)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%max(rot_grad_active_fraction_max)
         rot_grad_active_fraction_avg = 0.0_dp
         IF (rot_grad_active_weight_sum + rot_grad_inactive_weight_sum > EPSILON(1.0_dp)) &
            rot_grad_active_fraction_avg = rot_grad_active_weight_sum/ &
                                           (rot_grad_active_weight_sum + rot_grad_inactive_weight_sum)
         rot_grad_physical_norm = rot_grad_active_re + rot_grad_active_im + &
                                  rot_grad_gap_re + rot_grad_gap_im
         rot_grad_gauge_norm = rot_grad_gauge_re + rot_grad_gauge_im
         rot_grad_energy_norm = 0.0_dp
         DO local_channel = 1, nchannels
            IF (channel_nmo(local_channel) <= 0) CYCLE
            rot_grad_norm_weight = 1.0_dp/ &
                                   REAL(MAX(1, channel_multiplicity(local_channel)), KIND=dp)
            physical_delta_nvar = physical_delta_nvar + &
                                  REAL(MAX(1, channel_multiplicity(local_channel)), KIND=dp)* &
                                  REAL(channel_nmo(local_channel), KIND=dp)
            DO imo = 1, channel_nmo(local_channel)
               ie = e_offset(local_channel) + imo - 1
               rot_grad_energy_norm = rot_grad_energy_norm + rot_grad_norm_weight*grad_e(ie)*grad_e(ie)
            END DO
         END DO
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(rot_grad_energy_norm)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(physical_delta_nvar)
         rot_grad_total_physical_norm = qs_scf_kp_complete_physical_gradient_norm( &
                                        rot_grad_physical_norm, full_rot_grad_physical_norm, &
                                        rot_grad_energy_norm, schur_active_subspace)
         ! With a complete rotation audit the raw physical gradient is a safer
         ! convergence metric than the preconditioned Schur search direction.
         physical_delta_raw_tail_ready = eps_scf_channel > 0.0_dp .AND. &
                                         response_raw_delta > 0.0_dp .AND. &
                                         response_raw_delta <= &
                                         ot_kp_schur_physical_tail_eps_factor*eps_scf_channel
         physical_delta_norm = 0.0_dp
         IF (physical_delta_nvar > 0.0_dp) &
            physical_delta_norm = SQRT(MAX(0.0_dp, rot_grad_total_physical_norm)/ &
                                       physical_delta_nvar)
         local_ot_env(1)%kpoint_complete_physical_delta = &
            MAX(local_ot_env(1)%kpoint_complete_physical_delta, physical_delta_norm)
         energy_closure_tail_ready = qs_scf_kp_energy_closure_tail_ready( &
                                     residual_delta, physical_delta_norm, &
                                     local_ot_env(1)%kpoint_density_stationarity_delta, &
                                     local_ot_env(1)%mermin_ls_accepted_quality_samples)
         energy_occupation_plateau_ready = qs_scf_kp_energy_occupation_plateau_ready( &
                                           local_ot_env(1)%kpoint_density_stationarity_ready, &
                                           local_ot_env(1)%kpoint_density_stationarity_diag, &
                                           local_ot_env(1)%kpoint_density_stationarity_offdiag, &
                                           local_ot_env(1)%mermin_ls_accepted_quality_samples)
         energy_closure_tail_ready = energy_closure_tail_ready .OR. energy_occupation_plateau_ready
         physical_delta_norm_limit = &
            ot_kp_schur_physical_norm_tail_factor*ot_kp_schur_physical_tail_eps_factor* &
            eps_scf_channel
         physical_delta_norm_ready = qs_scf_kp_complete_physical_audit_ready( &
                                     physical_delta_norm, physical_delta_norm_limit, &
                                     physical_delta_nvar)
         physical_delta_plateau_ready = residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
                                        physical_delta_norm <= physical_delta_norm_limit .AND. &
                                        rot_grad_total_physical_norm <= &
                                        MAX(rot_grad_gauge_norm, residual_delta*residual_delta) .AND. &
                                        local_ot_env(1)%mermin_ls_accepted_quality_samples >= &
                                        ot_kp_schur_calibration_min_samples .AND. &
                                        local_ot_env(1)%mermin_ls_accepted_quality_ema >= 0.8_dp .AND. &
                                        local_ot_env(1)%mermin_ls_accepted_gap_ema <= &
                                        ot_kp_schur_residual_tail_plateau_slack
         physical_delta_group_ready = residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
                                      (.NOT. schur_active_subspace .OR. &
                                       rot_grad_gauge_norm > &
                                       MAX(rot_grad_total_physical_norm, EPSILON(1.0_dp)) .OR. &
                                       physical_delta_norm_ready .OR. &
                                       physical_delta_plateau_ready)
         CALL qs_scf_kp_physical_audit_add_group( &
            local_ot_env(1), physical_delta_group_ready, rot_grad_total_physical_norm, &
            rot_grad_physical_norm, full_rot_grad_physical_norm, rot_grad_energy_norm, &
            rot_grad_gauge_norm)
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,3(1X,ES16.8))') &
            " OT Schur physical rotation residual group active full ratio:", &
            target_group, rot_grad_physical_norm, full_rot_grad_physical_norm, &
            rot_grad_physical_norm/MAX(full_rot_grad_physical_norm, EPSILON(1.0_dp))
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,8(1X,ES16.8))') &
            " OT Schur rotation gradient active audit group re im inactive_re inactive_im favg fmax wact winact:", &
            target_group, rot_grad_active_re, rot_grad_active_im, rot_grad_inactive_re, &
            rot_grad_inactive_im, rot_grad_active_fraction_avg, rot_grad_active_fraction_max, &
            rot_grad_active_weight_sum, rot_grad_inactive_weight_sum
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,8(1X,ES16.8))') &
            " OT Schur rotgrad occ audit grp gap_re gap_im gauge_re gauge_im wgap wgauge fermi_re fermi_im:", &
            target_group, rot_grad_gap_re, rot_grad_gap_im, rot_grad_gauge_re, &
            rot_grad_gauge_im, rot_grad_gap_weight, rot_grad_gauge_weight, &
            rot_grad_active_re, rot_grad_active_im
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,1X,L1,5(1X,ES16.8))') &
            " OT Schur physical residual audit group ready energy rot gauge total raw_delta:", &
            target_group, physical_delta_group_ready, rot_grad_energy_norm, rot_grad_physical_norm, &
            rot_grad_gauge_norm, rot_grad_total_physical_norm, residual_delta
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,4(1X,L1),8(1X,ES16.8),1X,I6)') &
            " OT Schur physical residual plateau audit group ready plateau norm rawtail qema gema "// &
            "phys pdelta raw resp neps eps samples:", &
            target_group, physical_delta_group_ready, physical_delta_plateau_ready, &
            physical_delta_norm_ready, physical_delta_raw_tail_ready, &
            local_ot_env(1)%mermin_ls_accepted_quality_ema, &
            local_ot_env(1)%mermin_ls_accepted_gap_ema, &
            rot_grad_total_physical_norm, physical_delta_norm, residual_delta, response_raw_delta, &
            physical_delta_norm_limit, &
            ot_kp_schur_physical_tail_eps_factor*eps_scf_channel, &
            local_ot_env(1)%mermin_ls_accepted_quality_samples
         IF (failed) THEN
            DEALLOCATE (canonical_occ_curv, curv, grad_e, occ_curv, tether_curv, energy_grad_metric_weight, &
                        energy_step_weight, z_e, accepted_z_e, z_density_plateau_trial, &
                        z_density_floor_audit_trial, z_density_floor_safe_audit_trial, &
                        z_density_full_audit_trial, &
                        z_density_full_global_trial, &
                        z_density_full_trial, z_density_trial, &
                        z_exact_active_trial, z_exact_physical_trial, z_exact_raw_trial, &
                        z_exact_trial, z_multisecant, z_trial, rx_e, rx_model, constrained_z_e, &
                        canonical_density_trial_raw_rx_e, &
                        projector_physical_direct_curv_eval, projector_physical_direct_model_e, &
                        projector_physical_direct_response_rx_e, &
                        projector_physical_direct_diagref_rx_e, &
                        projector_physical_direct_density_rx_e, &
                        projector_physical_direct_density_z_e, &
                        density_descent_rx_e, &
                        density_descent_sol, &
                        density_descent_z_e, &
                        density_full_rx_e, &
                        density_full_global_rx_e, &
                        density_full_global_sol, &
                        density_full_sol, &
                        density_full_z_e, &
                        density_gap_projected_e, &
                        density_gap_rx_e, &
                        density_gap_trial_basis_e, &
                        density_gap_trial_projected_e, &
                        density_plateau_rx_e, density_plateau_z_e, &
                        projector_physical_direct_rx_e, &
                        projector_physical_direct_schur_eval, &
                        projector_physical_direct_z_e, projector_physical_model_e, &
                        projector_offdiag_rx_e, projector_offdiag_z_e, &
                        projector_inactive_offdiag_rx_e, &
                        projector_inactive_offdiag_z_e, &
                        projector_physical_rx_e, projector_physical_z_e, &
                        projector_response_rx_e, projector_response_z_e, &
                        prediction_z_base, prediction_z_e, reduced_secant_z_e, &
                        closure_candidate_z_e, split_z_e)
            DEALLOCATE (full_grad_rot, full_var_physical_grad_metric_weight, &
                        grad_rot, rhs, rtd, sol, accepted_sol, canonical_density_tangent, &
                        canonical_density_mode_alpha, canonical_density_mode_curvature, &
                        canonical_density_mode_linear, canonical_density_tangent_modes, &
                        canonical_density_trial_sol, constrained_sol, &
                        projector_physical_direct_sol, &
                        projector_physical_sol, projector_offdiag_sol, &
                        projector_inactive_offdiag_sol, projector_response_sol, &
                        prediction_sol, reduced_secant_sol, closure_candidate_sol, split_sol, &
                        var_grad_metric_weight, var_occ_gap_weight, var_physical_grad_metric_weight, &
                        var_projector_active_weight, &
                        var_projector_response_weight, var_projector_weight, var_step_weight, &
                        var_thermal_activity)
            DEALLOCATE (var_channel, var_ei, var_ej, var_i, var_j, var_kind, var_full_index)
            DEALLOCATE (rot_floor, row_floor_shift, projector_physical_direct_active_lcomp, &
                        energy_cross, energy_cross_active, energy_cross_canonical, energy_cross_density, &
                        energy_cross_density_floor_audit, energy_cross_density_floor_safe_audit, &
                        energy_cross_density_full, &
                        energy_cross_density_full_audit, energy_cross_density_full_global, &
                        energy_cross_density_plateau, &
                        energy_cross_multisecant, energy_cross_prediction, &
                        energy_cross_physical_model, energy_cross_raw, &
                        energy_hessian, energy_hessian_multisecant, energy_hessian_prediction, &
                        energy_hessian_reference, response, response_coupled, response_multisecant, &
                        response_density_exact, &
                        response_density_floor_audit, response_density_floor_audit_exact, &
                        response_density_floor_safe_audit, response_density_floor_safe_audit_exact, &
                        response_density_full, response_density_full_audit, &
                        response_density_full_audit_exact, response_density_full_exact, &
                        response_density_full_global, response_density_full_global_exact, response_density_physical, &
                        response_density_plateau, response_density_plateau_exact, &
                        response_exact, response_exact_active, response_exact_physical, &
                        response_exact_raw, response_occ, response_occ_canonical, response_occ_physical, &
                        response_prediction, response_split, rot_hessian, &
                        projector_physical_direct_base_delta, projector_physical_direct_curv_vec, &
                        projector_physical_direct_delta, &
                        closure_response_steps, closure_response_targets, &
                        closure_density_probe_steps, closure_density_probe_targets, &
                        closure_response_metric, &
                        rot_hessian_closure_baseline, rot_hessian_closure_candidate, &
                        rot_hessian_closure_probe_response, rot_hessian_closure_response, &
                        rot_hessian_coupled, &
                        full_rot_hessian_coupled, &
                        rot_hessian_multisecant, rot_hessian_prediction, &
                        reduced_secant_full_targets, reduced_secant_modes, reduced_secant_targets, &
                        reduced_response_metric, &
                        rot_hessian_reduced_secant, rot_hessian_secant, &
                        rot_hessian_orbital_schur, &
                        rot_hessian_projector, &
                        projector_physical_direct_schur_mat, projector_physical_direct_schur_vec, &
                        rot_hessian_projector_physical, &
                        rot_hessian_projector_physical_active, rot_hessian_projector_physical_diagref, &
                        rot_hessian_projector_physical_offdiag_active, &
                        rot_hessian_projector_physical_offdiag, &
                        rot_hessian_projector_physical_offdiag_plateau, &
                        rot_hessian_projector_physical_offdiag_plateau_active, &
                        schur, schur_metric, ipiv, ipiv_energy, &
                        canonical_density_cauchy_channel, channel_full_var_offset, &
                        channel_multiplicity, channel_nmo, &
                        channel_nrot, channel_var_offset, channel_maxocc, e_offset, &
                        channel_density_pair_residual, channel_density_pair_active, &
                        channel_density_pair_candidate, channel_fermi_pair_active, &
                        channel_residual_pair_active, channel_residual_pair_candidate, &
                        channel_residual_pair_score)
            RETURN
         END IF

         occ_curv_diag_sum = SUM(occ_curv(:))
         tether_curv_diag_sum = SUM(tether_curv(:))
         total_curv_diag_sum = SUM(curv(:))
         occ_curv_diag_max = MAXVAL(occ_curv(:))
         tether_curv_diag_max = MAXVAL(tether_curv(:))
         total_curv_diag_max = MAXVAL(curv(:))
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(occ_curv_diag_sum)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(tether_curv_diag_sum)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(total_curv_diag_sum)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%max(occ_curv_diag_max)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%max(tether_curv_diag_max)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%max(total_curv_diag_max)
         relative_energy_metric_ready = qs_scf_kp_energy_relative_metric_ready( &
                                        physical_delta_group_ready, residual_delta, &
                                        eps_scf_channel)
         energy_curvature_floor = ot_kp_energy_curvature_absolute_cap
         IF (relative_energy_metric_ready) &
            energy_curvature_floor = qs_scf_kp_energy_curvature_floor(total_curv_diag_max)
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) THEN
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,6(1X,ES16.8))') &
               " OT Schur occupation preconditioner group occ_sum occ_max tether_sum tether_max total_sum total_max:", &
               target_group, occ_curv_diag_sum, occ_curv_diag_max, tether_curv_diag_sum, &
               tether_curv_diag_max, total_curv_diag_sum, total_curv_diag_max
         END IF

         energy_active_occ_sum = 0.0_dp
         energy_active_shift = 0.0_dp
         energy_floor_count = 0.0_dp
         energy_floor_curv_sum = 0.0_dp
         curv_projection_sum = SUM(curv)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(curv_projection_sum)
         occ_curv_projection_sum = SUM(occ_curv)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(occ_curv_projection_sum)
         DO ie = 1, ne
            IF (curv(ie) > EPSILON(curv(ie))) THEN
               IF (curv(ie) < energy_curvature_floor) THEN
                  energy_floor_count = energy_floor_count + 1.0_dp
                  energy_floor_curv_sum = energy_floor_curv_sum + curv(ie)
               END IF
               IF (relative_energy_metric_ready .AND. curv(ie) < energy_curvature_floor) THEN
                  ! Thermally inactive tail coordinates are gauge-like once
                  ! the complete fixed-N residual has converged.
                  z_e(ie) = 0.0_dp
                  CYCLE
               END IF
               z_e(ie) = grad_e(ie)/MAX(curv(ie), energy_curvature_floor)
               energy_active_occ_sum = energy_active_occ_sum + occ_curv(ie)
               energy_active_shift = energy_active_shift + occ_curv(ie)*z_e(ie)
            END IF
         END DO
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(energy_active_occ_sum)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(energy_active_shift)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(energy_floor_count)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(energy_floor_curv_sum)
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,3(1X,ES16.8))') &
            " OT Schur occupation preconditioner energy-floor group count curv_sum floor:", &
            target_group, energy_floor_count, energy_floor_curv_sum, energy_curvature_floor
         IF (energy_active_occ_sum > EPSILON(energy_active_occ_sum)) THEN
            energy_active_shift = energy_active_shift/energy_active_occ_sum
            DO ie = 1, ne
               IF (curv(ie) > EPSILON(curv(ie)) .AND. &
                   (.NOT. relative_energy_metric_ready .OR. &
                    curv(ie) >= energy_curvature_floor)) &
                  z_e(ie) = z_e(ie) - energy_active_shift
            END DO
         ELSE
            z_e(:) = 0.0_dp
         END IF

         z_trial(:) = z_e(:)
         rot_hessian(:, :) = 0.5_dp*(rot_hessian(:, :) + TRANSPOSE(rot_hessian(:, :)))
         rot_hessian_coupled(:, :) = 0.5_dp*(rot_hessian_coupled(:, :) + &
                                             TRANSPOSE(rot_hessian_coupled(:, :)))
         rot_hessian_orbital_schur(:, :) = 0.5_dp*(rot_hessian_orbital_schur(:, :) + &
                                                   TRANSPOSE(rot_hessian_orbital_schur(:, :)))
         orbital_schur_diag_sum = 0.0_dp
         DO r = 1, nrot
            orbital_schur_diag_sum = orbital_schur_diag_sum + rot_hessian_orbital_schur(r, r)
         END DO
         orbital_schur_diag_max = MAXVAL([(rot_hessian_orbital_schur(r, r), r=1, nrot)])
         orbital_schur_abs_avg = SUM(ABS(rot_hessian_orbital_schur))/REAL(nrot*nrot, KIND=dp)
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,3(1X,ES16.8))') &
            " OT Schur orbital-complement shadow group diag_sum diag_max abs_avg:", &
            target_group, orbital_schur_diag_sum, orbital_schur_diag_max, orbital_schur_abs_avg
         rot_hessian_projector(:, :) = 0.5_dp*(rot_hessian_projector(:, :) + &
                                               TRANSPOSE(rot_hessian_projector(:, :)))
         rot_hessian_projector_physical(:, :) = 0.5_dp*(rot_hessian_projector_physical(:, :) + &
                                                        TRANSPOSE(rot_hessian_projector_physical(:, :)))
         rot_hessian_projector_physical_offdiag(:, :) = 0.5_dp* &
                                                        (rot_hessian_projector_physical_offdiag(:, :) + &
                                                         TRANSPOSE(rot_hessian_projector_physical_offdiag(:, :)))
         rot_hessian_projector_physical_offdiag_plateau(:, :) = 0.5_dp* &
                                                                (rot_hessian_projector_physical_offdiag_plateau(:, :) + &
                                                                 TRANSPOSE(rot_hessian_projector_physical_offdiag_plateau(:, :)))
         rot_hessian_projector_physical_offdiag_active(:, :) = 0.0_dp
         rot_hessian_projector_physical_offdiag_plateau_active(:, :) = 0.0_dp
         DO s = 1, nrot
            DO r = 1, nrot
               IF (var_channel(r) /= var_channel(s)) CYCLE
               projector_offdiag_active_weight = 0.0_dp
               IF (var_projector_weight(r) + var_projector_weight(s) > &
                   EPSILON(projector_offdiag_active_weight)) THEN
                  projector_offdiag_active_weight = &
                     (var_projector_active_weight(r) + var_projector_active_weight(s))/ &
                     MAX(var_projector_weight(r) + var_projector_weight(s), EPSILON(1.0_dp))
                  projector_offdiag_active_weight = &
                     MIN(1.0_dp, MAX(0.0_dp, projector_offdiag_active_weight))
               END IF
               rot_hessian_projector_physical_offdiag_active(r, s) = &
                  projector_offdiag_active_weight*rot_hessian_projector_physical_offdiag(r, s)
               rot_hessian_projector_physical_offdiag_plateau_active(r, s) = &
                  projector_offdiag_active_weight*rot_hessian_projector_physical_offdiag_plateau(r, s)
            END DO
         END DO
         rot_hessian_projector_physical_offdiag_active(:, :) = 0.5_dp* &
                                                               (rot_hessian_projector_physical_offdiag_active(:, :) + &
                                                                TRANSPOSE(rot_hessian_projector_physical_offdiag_active(:, :)))
         rot_hessian_projector_physical_offdiag_plateau_active(:, :) = 0.5_dp* &
                                                                    (rot_hessian_projector_physical_offdiag_plateau_active(:, :) + &
                                                             TRANSPOSE(rot_hessian_projector_physical_offdiag_plateau_active(:, :)))
         projector_physical_offdiag_active_abs_avg = &
            SUM(ABS(rot_hessian_projector_physical_offdiag_active(:, :)))
         projector_physical_offdiag_inactive_abs_avg = &
            SUM(ABS(rot_hessian_projector_physical_offdiag(:, :) - &
                    rot_hessian_projector_physical_offdiag_active(:, :)))
         projector_physical_offdiag_plateau_gap_active_abs_avg = &
            SUM(ABS(rot_hessian_projector_physical_offdiag_plateau_active(:, :) - &
                    rot_hessian_projector_physical_offdiag_active(:, :)))
         projector_physical_offdiag_plateau_gap_inactive_abs_avg = &
            SUM(ABS((rot_hessian_projector_physical_offdiag_plateau(:, :) - &
                     rot_hessian_projector_physical_offdiag(:, :)) - &
                    (rot_hessian_projector_physical_offdiag_plateau_active(:, :) - &
                     rot_hessian_projector_physical_offdiag_active(:, :))))
         rot_hessian_projector_physical_diagref(:, :) = 0.0_dp
         DO s = 1, nrot
            DO r = 1, nrot
               IF (var_channel(r) /= var_channel(s)) CYCLE
               projector_diagref_weight = 0.5_dp*(var_projector_weight(r) + var_projector_weight(s))
               rot_hessian_projector_physical_diagref(r, s) = &
                  (1.0_dp - projector_diagref_weight)*rot_hessian_coupled(r, s)
            END DO
         END DO
         rot_hessian_projector_physical_diagref(:, :) = 0.5_dp* &
                                                        (rot_hessian_projector_physical_diagref(:, :) + &
                                                         TRANSPOSE(rot_hessian_projector_physical_diagref(:, :)))
         projector_density_floor_audit_abs_avg = SUM(ABS(response_density_floor_audit(:, :)))
         projector_density_floor_safe_audit_abs_avg = SUM(ABS(response_density_floor_safe_audit(:, :)))
         projector_density_floor_audit_gap_abs_avg = &
            SUM(ABS(response_density_floor_audit(:, :) - response_density_physical(:, :)))
         projector_physical_density_full_abs_avg = SUM(ABS(response_density_full(:, :)))
         projector_density_full_audit_abs_avg = SUM(ABS(response_density_full_audit(:, :)))
         projector_density_basis_audit_abs_avg = SUM(ABS(response_density_basis_audit(:, :)))
         projector_density_basis_raw_gap_abs_avg = &
            SUM(ABS(response_density_basis_audit(:, :) - response_density_full_audit(:, :)))
         projector_density_basis_raw_gap_abs_max = &
            MAXVAL(ABS(response_density_basis_audit(:, :) - response_density_full_audit(:, :)))
         projector_density_basis_physical_gap_abs_avg = &
            SUM(ABS(response_density_basis_audit(:, :) - response_density_physical(:, :)))
         projector_density_basis_physical_gap_abs_max = &
            MAXVAL(ABS(response_density_basis_audit(:, :) - response_density_physical(:, :)))
         IF (local_ot_env(1)%schur_projector_density_full_global_sel_quality_samples >= &
             ot_kp_schur_calibration_min_samples) THEN
            IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) THEN
               density_full_global_selected_residual_quality = &
                  kpoint_ot_selected_tail_residual_quality( &
                  local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality, &
                  local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality_ema)
               density_full_global_selected_mix_residual_quality = &
                  kpoint_ot_selected_tail_mix_residual_quality( &
                  local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality, &
                  local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality_ema)
            END IF
            density_full_global_selected_response_scale = &
               kpoint_ot_density_full_global_selected_response_scale( &
               residual_delta, local_ot_env(1)%schur_projector_density_full_global_sel_quality, &
               local_ot_env(1)%schur_projector_density_full_global_sel_quality_ema, &
               local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality, &
               local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality_ema, &
               local_ot_env(1)%schur_projector_density_full_global_sel_quality_samples)
         END IF
         projector_density_full_global_floor_mix_weight = &
            kpoint_ot_density_full_global_floor_source_weight( &
            residual_delta, local_ot_env(1)%schur_projector_density_full_global_sel_quality, &
            local_ot_env(1)%schur_projector_density_full_global_sel_quality_ema, &
            local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality, &
            local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality_ema, &
            local_ot_env(1)%schur_projector_density_full_global_sel_quality_samples)
         IF (projector_density_full_audit_enabled .AND. projector_density_basis_audit_abs_avg > &
             EPSILON(projector_density_basis_audit_abs_avg)) THEN
            density_basis_selective_floor_weight(:) = 0.0_dp
            density_basis_source_abs_sum = 0.0_dp
            density_basis_unsupported_abs_sum = 0.0_dp
            DO ie = 1, ne
               density_basis_row_basis_abs = SUM(ABS(response_density_basis_audit(ie, :)))
               density_basis_row_physical_abs = SUM(ABS(response_density_physical(ie, :)))
               density_basis_row_basis_norm = SQRT(SUM(response_density_basis_audit(ie, :)**2))
               density_basis_row_physical_norm = SQRT(SUM(response_density_physical(ie, :)**2))
               density_basis_row_dot = SUM(response_density_basis_audit(ie, :)*response_density_physical(ie, :))
               density_basis_physical_support = 0.0_dp
               IF (density_basis_row_basis_abs <= EPSILON(density_basis_row_basis_abs)) THEN
                  density_basis_physical_support = 1.0_dp
               ELSE IF (density_basis_row_basis_norm > EPSILON(density_basis_row_basis_norm) .AND. &
                        density_basis_row_physical_norm > EPSILON(density_basis_row_physical_norm) .AND. &
                        density_basis_row_dot > 0.0_dp) THEN
                  density_basis_physical_support = density_basis_row_dot/ &
                                                   (density_basis_row_basis_norm*density_basis_row_physical_norm)
                  density_basis_physical_support = MIN(1.0_dp, MAX(0.0_dp, density_basis_physical_support))
                  density_basis_physical_support = density_basis_physical_support* &
                                                   MIN(1.0_dp, density_basis_row_physical_abs/ &
                                                       MAX(density_basis_row_basis_abs, EPSILON(density_basis_row_basis_abs)))
               END IF
               density_basis_lowcurv_weight = 0.0_dp
               IF (0.1_dp*total_curv_diag_max > EPSILON(total_curv_diag_max)) THEN
                  density_basis_lowcurv_weight = &
                     1.0_dp - MIN(1.0_dp, MAX(0.0_dp, occ_curv(ie) + tether_curv(ie))/ &
                                  (0.1_dp*total_curv_diag_max))
               END IF
               density_basis_floor_weight = (1.0_dp - density_basis_physical_support)* &
                                            density_basis_lowcurv_weight
               density_basis_floor_weight = MIN(1.0_dp, MAX(0.0_dp, density_basis_floor_weight))
               density_basis_selective_floor_weight(ie) = density_basis_floor_weight
               projector_density_basis_selective_audit_floor_avg = &
                  projector_density_basis_selective_audit_floor_avg + density_basis_floor_weight
               projector_density_basis_selective_audit_floor_max = &
                  MAX(projector_density_basis_selective_audit_floor_max, density_basis_floor_weight)
               projector_density_basis_selective_audit_support_avg = &
                  projector_density_basis_selective_audit_support_avg + density_basis_physical_support
               density_basis_source_abs_sum = density_basis_source_abs_sum + density_basis_row_basis_abs
               density_basis_unsupported_abs_sum = density_basis_unsupported_abs_sum + &
                                                   density_basis_floor_weight*density_basis_row_basis_abs
            END DO
            projector_density_basis_selective_audit_floor_avg = &
               projector_density_basis_selective_audit_floor_avg/REAL(MAX(1, ne), KIND=dp)
            projector_density_basis_selective_audit_support_avg = &
               projector_density_basis_selective_audit_support_avg/REAL(MAX(1, ne), KIND=dp)
            IF (density_basis_source_abs_sum > EPSILON(density_basis_source_abs_sum)) &
               projector_density_basis_selective_audit_unsupported_fraction = &
               density_basis_unsupported_abs_sum/density_basis_source_abs_sum
         END IF
         projector_density_full_global_selective_mix_weight = &
            projector_density_full_global_floor_mix_weight* &
            MIN(1.0_dp, MAX(0.0_dp, projector_density_basis_selective_audit_unsupported_fraction))
         density_full_global_floor_solver_fraction = 0.1_dp* &
                                                     MIN(1.0_dp, MAX(0.0_dp, projector_density_full_global_floor_mix_weight))
         ! Use the active-window, gauge-safe physical density response for the
         ! global fixed-N candidate.  Once selected global-history repeatedly
         ! underpredicts accepted Mermin drops, admit a tiny piece of the
         ! floor-limited finite-projector source before the fixed-N projection.
         ! The selective density-basis unsafe-subspace weight is used below for
         ! the exact response metric, but the raw density-basis source itself
         ! stays shadow-only until its accepted-step history is good enough.
         response_density_full_global(:, :) = response_density_physical(:, :)
         IF (projector_density_full_global_floor_mix_weight > &
             EPSILON(projector_density_full_global_floor_mix_weight)) &
            response_density_full_global(:, :) = &
            response_density_full_global(:, :) + projector_density_full_global_floor_mix_weight* &
            (response_density_floor_audit(:, :) - response_density_physical(:, :))
         DO s = 1, nrot
            CALL project_kpoint_ot_schur_response(response_density_full_global(:, s), occ_curv, tether_curv, &
                                                  occ_curv_projection_sum, channel_nmo, e_offset)
         END DO
         projector_response_signal_max = 0.0_dp
         projector_response_signal_sum = 0.0_dp
         projector_response_signal_count = 0.0_dp
         var_projector_response_weight(:) = 0.0_dp
         DO r = 1, nrot
            projector_response_signal = 0.0_dp
            DO ie = 1, ne
               projector_response_signal = projector_response_signal + &
                                           MAX(0.0_dp, occ_curv(ie))*response_density_full_global(ie, r)**2
            END DO
            projector_response_signal_weight = &
               kpoint_ot_projector_response_signal_weight(projector_response_signal)
            IF (projector_response_signal_weight > 0.0_dp) THEN
               var_projector_response_weight(r) = projector_response_signal_weight
               projector_response_signal_max = MAX(projector_response_signal_max, &
                                                   var_projector_response_weight(r))
               projector_response_signal_sum = projector_response_signal_sum + &
                                               var_projector_response_weight(r)
               projector_response_signal_count = projector_response_signal_count + 1.0_dp
            END IF
         END DO
         IF (projector_response_signal_max > EPSILON(projector_response_signal_max)) THEN
            projector_response_signal_mean = projector_response_signal_sum/ &
                                             MAX(1.0_dp, projector_response_signal_count)
            projector_response_signal_ref = &
               kpoint_ot_projector_response_character_scale(projector_response_signal_max, &
                                                            projector_response_signal_mean)
            var_projector_response_weight(:) = &
               MIN(1.0_dp, MAX(0.0_dp, var_projector_response_weight(:)/projector_response_signal_ref))
         END IF
         projector_response_character_abs_avg = SUM(var_projector_response_weight(:))
         projector_response_character_max = MAXVAL(var_projector_response_weight(:))
         projector_response_character_fraction = &
            REAL(COUNT(var_projector_response_weight(:) > EPSILON(1.0_dp)), KIND=dp)
         projector_density_full_global_abs_avg = SUM(ABS(response_density_full_global(:, :)))
         projector_physical_density_active_abs_avg = SUM(ABS(response_density_physical(:, :)))
         projector_physical_density_gap_abs_avg = &
            SUM(ABS(response_density_full(:, :) - response_density_physical(:, :)))
         projector_physical_density_gap_abs_max = &
            MAXVAL(ABS(response_density_full(:, :) - response_density_physical(:, :)))
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(projector_density_floor_audit_abs_avg)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(projector_density_floor_safe_audit_abs_avg)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(projector_density_floor_audit_gap_abs_avg)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(projector_physical_density_full_abs_avg)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(projector_density_full_audit_abs_avg)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(projector_density_basis_audit_abs_avg)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(projector_density_basis_raw_gap_abs_avg)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(projector_density_basis_physical_gap_abs_avg)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(projector_density_full_global_abs_avg)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(projector_physical_density_active_abs_avg)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(projector_physical_density_gap_abs_avg)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(projector_response_character_abs_avg)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(projector_response_character_fraction)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%max(projector_response_character_max)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%max(projector_physical_density_gap_abs_max)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%max(projector_density_basis_raw_gap_abs_max)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%max(projector_density_basis_physical_gap_abs_max)
         projector_density_floor_audit_abs_avg = projector_density_floor_audit_abs_avg/ &
                                                 REAL(MAX(1, ne*nrot), KIND=dp)
         projector_density_floor_safe_audit_abs_avg = projector_density_floor_safe_audit_abs_avg/ &
                                                      REAL(MAX(1, ne*nrot), KIND=dp)
         projector_density_floor_audit_gap_abs_avg = projector_density_floor_audit_gap_abs_avg/ &
                                                     REAL(MAX(1, ne*nrot), KIND=dp)
         projector_physical_density_full_abs_avg = projector_physical_density_full_abs_avg/ &
                                                   REAL(MAX(1, ne*nrot), KIND=dp)
         projector_density_full_audit_abs_avg = projector_density_full_audit_abs_avg/ &
                                                REAL(MAX(1, ne*nrot), KIND=dp)
         projector_density_basis_audit_abs_avg = projector_density_basis_audit_abs_avg/ &
                                                 REAL(MAX(1, ne*nrot), KIND=dp)
         projector_density_basis_raw_gap_abs_avg = projector_density_basis_raw_gap_abs_avg/ &
                                                   REAL(MAX(1, ne*nrot), KIND=dp)
         projector_density_basis_physical_gap_abs_avg = &
            projector_density_basis_physical_gap_abs_avg/REAL(MAX(1, ne*nrot), KIND=dp)
         projector_density_full_global_abs_avg = projector_density_full_global_abs_avg/ &
                                                 REAL(MAX(1, ne*nrot), KIND=dp)
         projector_physical_density_active_abs_avg = projector_physical_density_active_abs_avg/ &
                                                     REAL(MAX(1, ne*nrot), KIND=dp)
         projector_physical_density_gap_abs_avg = projector_physical_density_gap_abs_avg/ &
                                                  REAL(MAX(1, ne*nrot), KIND=dp)
         projector_response_character_abs_avg = projector_response_character_abs_avg/ &
                                                REAL(MAX(1, nrot), KIND=dp)
         projector_response_character_fraction = projector_response_character_fraction/ &
                                                 REAL(MAX(1, nrot), KIND=dp)
         IF (projector_physical_density_full_abs_avg > &
             EPSILON(projector_physical_density_full_abs_avg)) &
            projector_physical_density_active_fraction = &
            projector_physical_density_active_abs_avg/projector_physical_density_full_abs_avg
         exact_density_response_ready = .FALSE.
         IF (projector_physical_shadow_enabled) THEN
            ! The density source for the exact Mermin response must live in the
            ! same fixed-N/tether gauge as the solved energy response.
            IF (projector_density_full_global_selective_mix_weight > &
                EPSILON(projector_density_full_global_selective_mix_weight)) THEN
               CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response_density_full_global, &
                                                          0.0_dp*response_density_full_global, 0.0_dp*grad_e, &
                                                          channel_nmo, e_offset, energy_hessian, &
                                                          energy_cross_density, response_density_exact, &
                                                          z_density_trial, ipiv_energy, exact_density_response_ready, &
                                                          energy_gauge_weight, &
                                                          curv_floor_fraction= &
                                                          density_full_global_floor_solver_fraction, &
                                                          curv_floor_weight= &
                                                          density_basis_selective_floor_weight)
            ELSE IF (projector_density_full_global_floor_mix_weight > &
                     EPSILON(projector_density_full_global_floor_mix_weight)) THEN
               CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response_density_full_global, &
                                                          0.0_dp*response_density_full_global, 0.0_dp*grad_e, &
                                                          channel_nmo, e_offset, energy_hessian, &
                                                          energy_cross_density, response_density_exact, &
                                                          z_density_trial, ipiv_energy, exact_density_response_ready, &
                                                          energy_gauge_weight, &
                                                          curv_floor_fraction= &
                                                          density_full_global_floor_solver_fraction)
            ELSE
               CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response_density_full_global, &
                                                          0.0_dp*response_density_full_global, 0.0_dp*grad_e, &
                                                          channel_nmo, e_offset, energy_hessian, &
                                                          energy_cross_density, response_density_exact, &
                                                          z_density_trial, ipiv_energy, exact_density_response_ready, &
                                                          energy_gauge_weight)
            END IF
            IF (exact_density_response_ready) THEN
               projector_physical_density_rhs_abs_avg = &
                  SUM(ABS(energy_cross_density(:, :)))/REAL(MAX(1, ne*nrot), KIND=dp)
               projector_physical_density_rhs_abs_max = MAXVAL(ABS(energy_cross_density(:, :)))
               projector_physical_density_response_abs_avg = &
                  SUM(ABS(response_density_exact(:, :)))/REAL(MAX(1, ne*nrot), KIND=dp)
               projector_physical_density_response_abs_max = MAXVAL(ABS(response_density_exact(:, :)))
               DO s = 1, nrot
                  DO r = 1, nrot
                     projected_term = 0.5_dp* &
                                      (DOT_PRODUCT(energy_cross_density(:, r), response_density_exact(:, s)) + &
                                       DOT_PRODUCT(energy_cross_density(:, s), response_density_exact(:, r)))
                     rot_hessian_projector_physical(r, s) = rot_hessian_projector_physical(r, s) + &
                                                            projected_term
                     rot_hessian_projector_physical_diagref(r, s) = &
                        rot_hessian_projector_physical_diagref(r, s) + projected_term
                     projector_physical_density_abs_avg = projector_physical_density_abs_avg + ABS(projected_term)
                     projector_physical_density_delta_max = MAX(projector_physical_density_delta_max, &
                                                                ABS(projected_term))
                     IF (r == s) THEN
                        projector_physical_density_diag_avg = &
                           projector_physical_density_diag_avg + projected_term
                        DO ie = 1, ne
                           dense_term = energy_cross_density(ie, r)*response_density_exact(ie, r)
                           projector_physical_density_diag_abs_sum = &
                              projector_physical_density_diag_abs_sum + ABS(dense_term)
                           IF (occ_curv(ie) + tether_curv(ie) <= 0.1_dp*total_curv_diag_max) &
                              projector_physical_density_low_curv_sum = &
                              projector_physical_density_low_curv_sum + ABS(dense_term)
                        END DO
                     END IF
                  END DO
               END DO
               projector_physical_density_abs_avg = projector_physical_density_abs_avg/ &
                                                    REAL(MAX(1, nrot*nrot), KIND=dp)
               projector_physical_density_diag_avg = projector_physical_density_diag_avg/ &
                                                     REAL(MAX(1, nrot), KIND=dp)
               IF (projector_physical_density_diag_abs_sum > &
                   EPSILON(projector_physical_density_diag_abs_sum)) &
                  projector_physical_density_low_curv_fraction = &
                  projector_physical_density_low_curv_sum/projector_physical_density_diag_abs_sum
            END IF
            exact_density_plateau_response_ready = .FALSE.
            IF (projector_plateau_gap_model_enabled) &
               CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response_density_plateau, &
                                                          0.0_dp*response_density_plateau, 0.0_dp*grad_e, &
                                                          channel_nmo, e_offset, energy_hessian, &
                                                          energy_cross_density_plateau, response_density_plateau_exact, &
                                                          z_density_plateau_trial, ipiv_energy, &
                                                          exact_density_plateau_response_ready, energy_gauge_weight)
         END IF
         exact_density_full_audit_ready = .FALSE.
         exact_density_floor_audit_ready = .FALSE.
         exact_density_floor_safe_audit_ready = .FALSE.
         exact_density_basis_audit_ready = .FALSE.
         exact_density_basis_curvfloor_audit_ready = .FALSE.
         exact_density_basis_damped_audit_ready = .FALSE.
         exact_density_basis_filtered_audit_ready = .FALSE.
         exact_density_basis_selective_audit_ready = .FALSE.
         exact_density_full_response_ready = .FALSE.
         projector_density_floor_audit_exact_abs_avg = 0.0_dp
         projector_density_floor_audit_low_curv_fraction = 0.0_dp
         projector_density_floor_audit_diag_abs_sum = 0.0_dp
         projector_density_floor_audit_low_curv_sum = 0.0_dp
         projector_density_floor_safe_audit_abs_avg = 0.0_dp
         projector_density_floor_safe_audit_exact_abs_avg = 0.0_dp
         projector_density_floor_safe_audit_low_curv_fraction = 0.0_dp
         projector_density_floor_safe_audit_diag_abs_sum = 0.0_dp
         projector_density_floor_safe_audit_low_curv_sum = 0.0_dp
         projector_density_basis_audit_exact_abs_avg = 0.0_dp
         projector_density_basis_audit_low_curv_fraction = 0.0_dp
         projector_density_basis_audit_diag_abs_sum = 0.0_dp
         projector_density_basis_audit_low_curv_sum = 0.0_dp
         projector_density_basis_curvfloor_audit_exact_abs_avg = 0.0_dp
         projector_density_basis_curvfloor_audit_low_curv_fraction = 0.0_dp
         projector_density_basis_curvfloor_audit_diag_abs_sum = 0.0_dp
         projector_density_basis_curvfloor_audit_low_curv_sum = 0.0_dp
         projector_density_basis_selective_audit_exact_abs_avg = 0.0_dp
         projector_density_basis_selective_audit_low_curv_fraction = 0.0_dp
         projector_density_basis_selective_audit_diag_abs_sum = 0.0_dp
         projector_density_basis_selective_audit_low_curv_sum = 0.0_dp
         projector_density_basis_filtered_audit_abs_avg = 0.0_dp
         projector_density_basis_filtered_audit_exact_abs_avg = 0.0_dp
         projector_density_basis_filtered_audit_low_curv_fraction = 0.0_dp
         projector_density_basis_filtered_audit_diag_abs_sum = 0.0_dp
         projector_density_basis_filtered_audit_low_curv_sum = 0.0_dp
         projector_density_basis_filtered_retained_fraction = 0.0_dp
         projector_density_basis_damped_audit_abs_avg = 0.0_dp
         projector_density_basis_damped_audit_exact_abs_avg = 0.0_dp
         projector_density_basis_damped_audit_low_curv_fraction = 0.0_dp
         projector_density_basis_damped_audit_diag_abs_sum = 0.0_dp
         projector_density_basis_damped_audit_low_curv_sum = 0.0_dp
         projector_density_basis_damped_retained_fraction = 0.0_dp
         IF (projector_density_full_audit_enabled .AND. projector_density_basis_audit_abs_avg > &
             EPSILON(projector_density_basis_audit_abs_avg)) THEN
            CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response_density_basis_audit, &
                                                       0.0_dp*response_density_basis_audit, 0.0_dp*grad_e, &
                                                       channel_nmo, e_offset, energy_hessian, &
                                                       energy_cross_density_basis_audit, &
                                                       response_density_basis_audit_exact, &
                                                       z_density_basis_audit_trial, ipiv_energy, &
                                                       exact_density_basis_audit_ready, energy_gauge_weight)
            IF (exact_density_basis_audit_ready) THEN
               projector_density_basis_audit_exact_abs_avg = &
                  SUM(ABS(response_density_basis_audit_exact(:, :)))/REAL(MAX(1, ne*nrot), KIND=dp)
               DO r = 1, nrot
                  DO ie = 1, ne
                     dense_term = energy_cross_density_basis_audit(ie, r)* &
                                  response_density_basis_audit_exact(ie, r)
                     projector_density_basis_audit_diag_abs_sum = &
                        projector_density_basis_audit_diag_abs_sum + ABS(dense_term)
                     IF (occ_curv(ie) + tether_curv(ie) <= 0.1_dp*total_curv_diag_max) &
                        projector_density_basis_audit_low_curv_sum = &
                        projector_density_basis_audit_low_curv_sum + ABS(dense_term)
                  END DO
               END DO
               IF (projector_density_basis_audit_diag_abs_sum > &
                   EPSILON(projector_density_basis_audit_diag_abs_sum)) &
                  projector_density_basis_audit_low_curv_fraction = &
                  projector_density_basis_audit_low_curv_sum/projector_density_basis_audit_diag_abs_sum
            END IF
            CALL build_kpoint_ot_exact_energy_response( &
               occ_curv, tether_curv, response_density_basis_audit, &
               0.0_dp*response_density_basis_audit, 0.0_dp*grad_e, channel_nmo, e_offset, &
               energy_hessian, energy_cross_density_basis_curvfloor_audit, &
               response_density_basis_curvfloor_audit_exact, z_density_basis_curvfloor_audit_trial, &
               ipiv_energy, exact_density_basis_curvfloor_audit_ready, energy_gauge_weight, &
               curv_floor_fraction=0.1_dp)
            IF (exact_density_basis_curvfloor_audit_ready) THEN
               projector_density_basis_curvfloor_audit_exact_abs_avg = &
                  SUM(ABS(response_density_basis_curvfloor_audit_exact(:, :)))/ &
                  REAL(MAX(1, ne*nrot), KIND=dp)
               DO r = 1, nrot
                  DO ie = 1, ne
                     dense_term = energy_cross_density_basis_curvfloor_audit(ie, r)* &
                                  response_density_basis_curvfloor_audit_exact(ie, r)
                     projector_density_basis_curvfloor_audit_diag_abs_sum = &
                        projector_density_basis_curvfloor_audit_diag_abs_sum + ABS(dense_term)
                     IF (occ_curv(ie) + tether_curv(ie) <= 0.1_dp*total_curv_diag_max) &
                        projector_density_basis_curvfloor_audit_low_curv_sum = &
                        projector_density_basis_curvfloor_audit_low_curv_sum + ABS(dense_term)
                  END DO
               END DO
               IF (projector_density_basis_curvfloor_audit_diag_abs_sum > &
                   EPSILON(projector_density_basis_curvfloor_audit_diag_abs_sum)) &
