                  projector_density_basis_curvfloor_audit_low_curv_sum/ &
                  projector_density_basis_curvfloor_audit_diag_abs_sum
            END IF
            CALL build_kpoint_ot_exact_energy_response( &
               occ_curv, tether_curv, response_density_basis_audit, &
