               ipiv_energy, exact_density_basis_selective_audit_ready, energy_gauge_weight, &
               curv_floor_fraction=0.1_dp, curv_floor_weight=density_basis_selective_floor_weight)
            IF (exact_density_basis_selective_audit_ready) THEN
               projector_density_basis_selective_audit_exact_abs_avg = &
                  SUM(ABS(response_density_basis_selective_audit_exact(:, :)))/ &
                  REAL(MAX(1, ne*nrot), KIND=dp)
               DO r = 1, nrot
                  DO ie = 1, ne
                     dense_term = energy_cross_density_basis_selective_audit(ie, r)* &
                                  response_density_basis_selective_audit_exact(ie, r)
                     projector_density_basis_selective_audit_diag_abs_sum = &
                        projector_density_basis_selective_audit_diag_abs_sum + ABS(dense_term)
                     IF (occ_curv(ie) + tether_curv(ie) <= 0.1_dp*total_curv_diag_max) &
                        projector_density_basis_selective_audit_low_curv_sum = &
                        projector_density_basis_selective_audit_low_curv_sum + ABS(dense_term)
                  END DO
               END DO
               IF (projector_density_basis_selective_audit_diag_abs_sum > &
                   EPSILON(projector_density_basis_selective_audit_diag_abs_sum)) &
                  projector_density_basis_selective_audit_low_curv_fraction = &
                  projector_density_basis_selective_audit_low_curv_sum/ &
                  projector_density_basis_selective_audit_diag_abs_sum
            END IF
            response_density_basis_filtered_audit(:, :) = response_density_basis_audit(:, :)
            DO s = 1, nrot
               DO ie = 1, ne
                  IF (occ_curv(ie) + tether_curv(ie) <= 0.1_dp*total_curv_diag_max) &
                     response_density_basis_filtered_audit(ie, s) = 0.0_dp
               END DO
               CALL project_kpoint_ot_schur_response(response_density_basis_filtered_audit(:, s), &
                                                     occ_curv, tether_curv, occ_curv_projection_sum, &
                                                     channel_nmo, e_offset)
            END DO
            projector_density_basis_filtered_audit_abs_avg = &
               SUM(ABS(response_density_basis_filtered_audit(:, :)))/REAL(MAX(1, ne*nrot), KIND=dp)
            IF (projector_density_basis_audit_abs_avg > EPSILON(projector_density_basis_audit_abs_avg)) &
               projector_density_basis_filtered_retained_fraction = &
               projector_density_basis_filtered_audit_abs_avg/projector_density_basis_audit_abs_avg
            IF (projector_density_basis_filtered_audit_abs_avg > &
                EPSILON(projector_density_basis_filtered_audit_abs_avg)) THEN
               CALL build_kpoint_ot_exact_energy_response( &
                  occ_curv, tether_curv, response_density_basis_filtered_audit, &
                  0.0_dp*response_density_basis_filtered_audit, 0.0_dp*grad_e, &
                  channel_nmo, e_offset, energy_hessian, energy_cross_density_basis_filtered_audit, &
                  response_density_basis_filtered_audit_exact, z_density_basis_filtered_audit_trial, &
                  ipiv_energy, exact_density_basis_filtered_audit_ready, energy_gauge_weight)
               IF (exact_density_basis_filtered_audit_ready) THEN
                  projector_density_basis_filtered_audit_exact_abs_avg = &
                     SUM(ABS(response_density_basis_filtered_audit_exact(:, :)))/ &
                     REAL(MAX(1, ne*nrot), KIND=dp)
                  DO r = 1, nrot
                     DO ie = 1, ne
                        dense_term = energy_cross_density_basis_filtered_audit(ie, r)* &
                                     response_density_basis_filtered_audit_exact(ie, r)
                        projector_density_basis_filtered_audit_diag_abs_sum = &
                           projector_density_basis_filtered_audit_diag_abs_sum + ABS(dense_term)
                        IF (occ_curv(ie) + tether_curv(ie) <= 0.1_dp*total_curv_diag_max) &
                           projector_density_basis_filtered_audit_low_curv_sum = &
                           projector_density_basis_filtered_audit_low_curv_sum + ABS(dense_term)
                     END DO
                  END DO
                  IF (projector_density_basis_filtered_audit_diag_abs_sum > &
                      EPSILON(projector_density_basis_filtered_audit_diag_abs_sum)) &
                     projector_density_basis_filtered_audit_low_curv_fraction = &
                     projector_density_basis_filtered_audit_low_curv_sum/ &
                     projector_density_basis_filtered_audit_diag_abs_sum
               END IF
            END IF
            density_basis_damping_threshold = 0.1_dp*total_curv_diag_max
            response_density_basis_damped_audit(:, :) = response_density_basis_audit(:, :)
            DO s = 1, nrot
               DO ie = 1, ne
                  IF (density_basis_damping_threshold > EPSILON(density_basis_damping_threshold)) THEN
                     density_basis_damp = (occ_curv(ie) + tether_curv(ie))/density_basis_damping_threshold
                     density_basis_damp = MIN(1.0_dp, MAX(0.0_dp, density_basis_damp))
                  ELSE
                     density_basis_damp = 0.0_dp
                  END IF
                  response_density_basis_damped_audit(ie, s) = &
                     density_basis_damp*response_density_basis_damped_audit(ie, s)
               END DO
               CALL project_kpoint_ot_schur_response(response_density_basis_damped_audit(:, s), &
                                                     occ_curv, tether_curv, occ_curv_projection_sum, &
                                                     channel_nmo, e_offset, metric_floor_fraction=0.1_dp)
            END DO
            projector_density_basis_damped_audit_abs_avg = &
               SUM(ABS(response_density_basis_damped_audit(:, :)))/REAL(MAX(1, ne*nrot), KIND=dp)
            IF (projector_density_basis_audit_abs_avg > EPSILON(projector_density_basis_audit_abs_avg)) &
               projector_density_basis_damped_retained_fraction = &
               projector_density_basis_damped_audit_abs_avg/projector_density_basis_audit_abs_avg
            IF (projector_density_basis_damped_audit_abs_avg > &
                EPSILON(projector_density_basis_damped_audit_abs_avg)) THEN
               CALL build_kpoint_ot_exact_energy_response( &
                  occ_curv, tether_curv, response_density_basis_damped_audit, &
                  0.0_dp*response_density_basis_damped_audit, 0.0_dp*grad_e, &
                  channel_nmo, e_offset, energy_hessian, energy_cross_density_basis_damped_audit, &
                  response_density_basis_damped_audit_exact, z_density_basis_damped_audit_trial, &
                  ipiv_energy, exact_density_basis_damped_audit_ready, energy_gauge_weight)
               IF (exact_density_basis_damped_audit_ready) THEN
                  projector_density_basis_damped_audit_exact_abs_avg = &
                     SUM(ABS(response_density_basis_damped_audit_exact(:, :)))/ &
                     REAL(MAX(1, ne*nrot), KIND=dp)
                  DO r = 1, nrot
                     DO ie = 1, ne
                        dense_term = energy_cross_density_basis_damped_audit(ie, r)* &
                                     response_density_basis_damped_audit_exact(ie, r)
                        projector_density_basis_damped_audit_diag_abs_sum = &
                           projector_density_basis_damped_audit_diag_abs_sum + ABS(dense_term)
                        IF (occ_curv(ie) + tether_curv(ie) <= 0.1_dp*total_curv_diag_max) &
                           projector_density_basis_damped_audit_low_curv_sum = &
                           projector_density_basis_damped_audit_low_curv_sum + ABS(dense_term)
                     END DO
                  END DO
                  IF (projector_density_basis_damped_audit_diag_abs_sum > &
                      EPSILON(projector_density_basis_damped_audit_diag_abs_sum)) &
                     projector_density_basis_damped_audit_low_curv_fraction = &
                     projector_density_basis_damped_audit_low_curv_sum/ &
                     projector_density_basis_damped_audit_diag_abs_sum
               END IF
            END IF
         END IF
         IF (exact_density_basis_filtered_audit_ready) &
            projector_density_full_global_filtered_mix_weight = &
            kpoint_ot_density_full_global_filtered_source_weight( &
            residual_delta, local_ot_env(1)%schur_projector_density_full_global_sel_quality, &
            local_ot_env(1)%schur_projector_density_full_global_sel_quality_ema, &
            local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality, &
            local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality_ema, &
            local_ot_env(1)%schur_projector_density_full_global_sel_quality_samples, &
            projector_density_basis_filtered_audit_abs_avg, &
            projector_density_basis_filtered_audit_exact_abs_avg, &
            projector_density_basis_filtered_audit_low_curv_fraction)
         IF (projector_density_full_global_filtered_mix_weight > &
             EPSILON(projector_density_full_global_filtered_mix_weight)) THEN
            response_density_full_global(:, :) = &
               response_density_full_global(:, :) + &
               projector_density_full_global_filtered_mix_weight* &
               (response_density_basis_filtered_audit(:, :) - response_density_full_global(:, :))
            DO s = 1, nrot
               CALL project_kpoint_ot_schur_response(response_density_full_global(:, s), &
                                                     occ_curv, tether_curv, occ_curv_projection_sum, &
