            END IF
         END IF
         IF (projector_physical_shadow_enabled .AND. projector_physical_density_full_abs_avg > &
             EPSILON(projector_physical_density_full_abs_avg)) THEN
            CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response_density_full, &
                                                       0.0_dp*response_density_full, 0.0_dp*grad_e, &
                                                       channel_nmo, e_offset, energy_hessian, &
                                                       energy_cross_density_full, response_density_full_exact, &
                                                       z_density_full_trial, ipiv_energy, &
                                                       exact_density_full_response_ready, energy_gauge_weight)
         END IF
         IF (projector_density_full_audit_enabled .AND. projector_density_full_global_abs_avg > &
             EPSILON(projector_density_full_global_abs_avg)) THEN
            IF (projector_density_full_global_selective_mix_weight > &
                EPSILON(projector_density_full_global_selective_mix_weight)) THEN
               CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response_density_full_global, &
                                                          0.0_dp*response_density_full_global, 0.0_dp*grad_e, &
                                                          channel_nmo, e_offset, energy_hessian, &
                                                          energy_cross_density_full_global, &
                                                          response_density_full_global_exact, &
                                                          z_density_full_global_trial, ipiv_energy, &
                                                          exact_density_full_audit_ready, energy_gauge_weight, &
                                                          curv_floor_fraction= &
                                                          density_full_global_floor_solver_fraction, &
                                                          curv_floor_weight= &
                                                          density_basis_selective_floor_weight)
            ELSE IF (projector_density_full_global_floor_mix_weight > &
                     EPSILON(projector_density_full_global_floor_mix_weight)) THEN
               CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response_density_full_global, &
                                                          0.0_dp*response_density_full_global, 0.0_dp*grad_e, &
                                                          channel_nmo, e_offset, energy_hessian, &
                                                          energy_cross_density_full_global, &
                                                          response_density_full_global_exact, &
                                                          z_density_full_global_trial, ipiv_energy, &
                                                          exact_density_full_audit_ready, energy_gauge_weight, &
                                                          curv_floor_fraction= &
                                                          density_full_global_floor_solver_fraction)
            ELSE
               CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response_density_full_global, &
                                                          0.0_dp*response_density_full_global, 0.0_dp*grad_e, &
                                                          channel_nmo, e_offset, energy_hessian, &
                                                          energy_cross_density_full_global, &
                                                          response_density_full_global_exact, &
                                                          z_density_full_global_trial, ipiv_energy, &
                                                          exact_density_full_audit_ready, energy_gauge_weight)
            END IF
            IF (exact_density_full_audit_ready) THEN
               energy_cross_density_full_audit(:, :) = energy_cross_density_full_global(:, :)
               response_density_full_audit_exact(:, :) = response_density_full_global_exact(:, :)
               z_density_full_audit_trial(:) = z_density_full_global_trial(:)
            END IF
         END IF
         density_full_global_history_trust_quality = 1.0_dp
         density_full_global_quality_for_selection = 0.0_dp
         projector_physical_direct_floor_density_quality = 0.0_dp
         projector_physical_direct_floor_density_trust_quality = 1.0_dp
         IF (local_ot_env(1)%schur_projector_density_full_global_sel_quality_samples >= &
             ot_kp_schur_calibration_min_samples) THEN
            density_full_global_selected_mermin_quality = &
               kpoint_ot_schur_history_quality( &
               local_ot_env(1)%schur_projector_density_full_global_sel_drop_sum, &
               local_ot_env(1)%schur_projector_density_full_global_sel_measured_sum, &
               local_ot_env(1)%schur_projector_density_full_global_sel_quality_ema, &
               local_ot_env(1)%schur_projector_density_full_global_sel_quality_samples, &
               ot_kp_schur_calibration_min_samples, &
               0.0_dp, 0.0_dp, ot_kp_schur_projector_response_quality_max_ratio)
            IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) THEN
               density_full_global_selected_residual_quality = &
                  kpoint_ot_selected_tail_residual_quality( &
                  local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality, &
                  local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality_ema)
               density_full_global_selected_mix_residual_quality = &
                  kpoint_ot_selected_tail_mix_residual_quality( &
                  local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality, &
                  local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality_ema)
            END IF
            density_full_global_selected_response_scale = &
               kpoint_ot_density_full_global_selected_response_scale( &
               residual_delta, local_ot_env(1)%schur_projector_density_full_global_sel_quality, &
               local_ot_env(1)%schur_projector_density_full_global_sel_quality_ema, &
               local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality, &
               local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality_ema, &
               local_ot_env(1)%schur_projector_density_full_global_sel_quality_samples)
         END IF
         exact_density_direct_response_ready = exact_density_response_ready
         energy_cross_density_direct(:, :) = energy_cross_density(:, :)
         response_density_direct_exact(:, :) = response_density_exact(:, :)
         ! Once the accepted full-density response history is mature and good,
         ! keep the Direct model blend history controlled.  Individual trial
         ! line-search probes can miss the local Direct response and should
         ! not switch this correction on/off between probes in the same tail.
         IF ((exact_density_floor_audit_ready .OR. exact_density_full_audit_ready) .AND. &
             local_ot_env(1)%schur_projector_density_full_global_quality_samples > 0 .AND. &
             local_ot_env(1)%schur_projector_density_full_global_drop_sum > &
             ot_kp_schur_projector_density_full_min_drop .AND. &
             local_ot_env(1)%schur_projector_density_full_global_measured_sum > 0.0_dp .AND. &
             local_ot_env(1)%schur_projector_density_full_global_quality_ema >= &
             0.5_dp*ot_kp_schur_projector_response_quality_min_ratio) THEN
            density_full_global_history_trust_quality = &
               kpoint_ot_schur_metric_trust_quality( &
               local_ot_env(1)%schur_projector_density_full_global_weighted_trust_ema, 0.0_dp)
            density_full_global_quality_for_selection = &
               kpoint_ot_schur_history_quality( &
               local_ot_env(1)%schur_projector_density_full_global_drop_sum, &
               local_ot_env(1)%schur_projector_density_full_global_measured_sum, &
               local_ot_env(1)%schur_projector_density_full_global_quality_ema, &
               local_ot_env(1)%schur_projector_density_full_global_quality_samples, &
               ot_kp_schur_projector_response_min_samples, &
               local_ot_env(1)%schur_projector_density_full_global_quality_ema, &
               ot_kp_schur_projector_response_quality_min_ratio, &
               ot_kp_schur_projector_response_quality_max_ratio)
            density_full_global_quality_for_selection = &
               kpoint_ot_floor_bootstrap_history_quality( &
               density_full_global_quality_for_selection, &
               local_ot_env(1)%schur_projector_density_full_global_quality, &
               local_ot_env(1)%schur_projector_density_full_global_quality_ema, &
               local_ot_env(1)%schur_projector_density_full_global_quality_samples, &
               ot_kp_schur_projector_response_min_samples)
            projector_physical_direct_floor_density_quality = &
               density_full_global_quality_for_selection
            projector_physical_direct_floor_density_trust_quality = &
               density_full_global_history_trust_quality
            IF (local_ot_env(1)%schur_projector_density_full_global_quality_samples >= &
                ot_kp_schur_projector_response_min_samples) THEN
               projector_physical_direct_floor_density_maturity = &
                  REAL(local_ot_env(1)%schur_projector_density_full_global_quality_samples - &
                       ot_kp_schur_projector_response_min_samples + 1, KIND=dp)/ &
                  REAL(MAX(1, ot_kp_schur_projector_response_min_samples), KIND=dp)
            ELSE
               projector_physical_direct_floor_density_maturity = &
                  0.25_dp*REAL(local_ot_env(1)%schur_projector_density_full_global_quality_samples, &
                               KIND=dp)/ &
                  REAL(MAX(1, ot_kp_schur_projector_response_min_samples), KIND=dp)
            END IF
            projector_physical_direct_floor_density_maturity = &
               MIN(1.0_dp, MAX(0.0_dp, projector_physical_direct_floor_density_maturity))
            projector_physical_direct_floor_density_weight = &
               projector_physical_direct_floor_density_maturity* &
               MIN(0.5_dp*ot_kp_schur_projector_trace_active_max_weight, &
                   MAX(0.0_dp, MIN(1.0_dp, density_full_global_quality_for_selection))* &
                   MAX(0.0_dp, MIN(1.0_dp, density_full_global_history_trust_quality)))
            IF (projector_physical_direct_floor_density_weight > &
                EPSILON(projector_physical_direct_floor_density_weight)) THEN
               exact_density_direct_response_ready = .TRUE.
               IF (exact_density_response_ready) THEN
                  energy_cross_density_direct(:, :) = &
                     (1.0_dp - projector_physical_direct_floor_density_weight)* &
                     energy_cross_density(:, :) + &
                     projector_physical_direct_floor_density_weight* &
                     MERGE(energy_cross_density_floor_audit(:, :), &
                           energy_cross_density_full_audit(:, :), &
                           exact_density_floor_audit_ready)
                  response_density_direct_exact(:, :) = &
                     (1.0_dp - projector_physical_direct_floor_density_weight)* &
                     response_density_exact(:, :) + &
                     projector_physical_direct_floor_density_weight* &
                     MERGE(response_density_floor_audit_exact(:, :), &
                           response_density_full_audit_exact(:, :), &
                           exact_density_floor_audit_ready)
               ELSE
                  energy_cross_density_direct(:, :) = &
                     projector_physical_direct_floor_density_weight* &
                     MERGE(energy_cross_density_floor_audit(:, :), &
                           energy_cross_density_full_audit(:, :), &
                           exact_density_floor_audit_ready)
                  response_density_direct_exact(:, :) = &
                     projector_physical_direct_floor_density_weight* &
                     MERGE(response_density_floor_audit_exact(:, :), &
                           response_density_full_audit_exact(:, :), &
                           exact_density_floor_audit_ready)
               END IF
            END IF
         END IF
         IF (projector_physical_direct_floor_density_weight <= &
             EPSILON(projector_physical_direct_floor_density_weight) .AND. &
             exact_density_floor_audit_ready) THEN
            projector_physical_direct_floor_density_bootstrap_weight = &
               kpoint_ot_direct_floor_density_bootstrap_weight( &
               residual_delta, local_ot_env(1)%mermin_ls_accepted_quality_ema, &
               local_ot_env(1)%mermin_ls_accepted_quality_samples, &
               projector_density_floor_audit_abs_avg, projector_density_floor_audit_exact_abs_avg, &
               projector_density_floor_audit_low_curv_fraction, projector_density_full_global_abs_avg)
            IF (projector_physical_direct_floor_density_bootstrap_weight > &
                EPSILON(projector_physical_direct_floor_density_bootstrap_weight)) THEN
               projector_physical_direct_floor_density_quality = &
                  MAX(ot_kp_schur_projector_response_quality_min_ratio, &
                      MIN(ot_kp_schur_projector_response_quality_max_ratio, &
                          local_ot_env(1)%mermin_ls_accepted_quality_ema))
               projector_physical_direct_floor_density_trust_quality = 1.0_dp
               projector_physical_direct_floor_density_maturity = 0.0_dp
               projector_physical_direct_floor_density_weight = &
                  projector_physical_direct_floor_density_bootstrap_weight
            END IF
         END IF
         IF (local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_samples >= &
             ot_kp_schur_calibration_min_samples) THEN
            projector_physical_direct_density_selected_mermin_quality = &
               kpoint_ot_schur_history_quality( &
               local_ot_env(1)%schur_projector_phys_direct_density_sel_drop_sum, &
               local_ot_env(1)%schur_projector_phys_direct_density_sel_measured_sum, &
               local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_ema, &
               local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_samples, &
               ot_kp_schur_calibration_min_samples, &
               0.0_dp, 0.0_dp, &
               ot_kp_schur_projector_response_quality_max_ratio)
            projector_physical_direct_density_selected_history_quality = &
               projector_physical_direct_density_selected_mermin_quality
            IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) THEN
               projector_physical_direct_density_recent_residual_quality = &
                  kpoint_ot_selected_tail_residual_quality( &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality, &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality_ema)
               projector_physical_direct_density_mix_residual_quality = &
                  kpoint_ot_selected_tail_mix_residual_quality( &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality, &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality_ema)
               projector_physical_direct_density_selected_history_quality = &
                  projector_physical_direct_density_selected_history_quality* &
                  projector_physical_direct_density_recent_residual_quality
               projector_density_selected_history_weight = &
                  kpoint_ot_direct_density_selected_mix_weight( &
                  residual_delta, projector_physical_direct_density_selected_mermin_quality, &
                  projector_physical_direct_density_mix_residual_quality, &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_samples)
            END IF
         ELSE IF (local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_samples > 0 .AND. &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_drop_sum > &
                  ot_kp_schur_projector_density_full_min_drop .AND. &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_measured_sum > 0.0_dp .AND. &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_ema >= &
                  ot_kp_schur_projector_response_quality_min_ratio .AND. &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality_ema >= &
                  0.5_dp*ot_kp_schur_projector_response_quality_min_ratio) THEN
            ! A single accepted Direct-density tail step is not mature enough
            ! to promote the response model, but it is real Mermin evidence.
            ! Use it only as an early quality boost for subsequent probes.
            projector_physical_direct_density_selected_mermin_quality = &
               kpoint_ot_schur_history_quality( &
               local_ot_env(1)%schur_projector_phys_direct_density_sel_drop_sum, &
               local_ot_env(1)%schur_projector_phys_direct_density_sel_measured_sum, &
               local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_ema, &
               local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_samples, &
               1, 0.0_dp, 0.0_dp, &
               ot_kp_schur_projector_response_quality_max_ratio)
            projector_physical_direct_density_selected_history_quality = &
               projector_physical_direct_density_selected_mermin_quality
            IF (residual_delta <= ot_kp_schur_projector_coupled_tail_delta) THEN
               projector_physical_direct_density_recent_residual_quality = &
                  kpoint_ot_selected_tail_residual_quality( &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality, &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality_ema)
               projector_physical_direct_density_mix_residual_quality = &
                  kpoint_ot_selected_tail_mix_residual_quality( &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality, &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality_ema)
               projector_physical_direct_density_selected_history_quality = &
                  projector_physical_direct_density_selected_history_quality* &
                  projector_physical_direct_density_recent_residual_quality
            END IF
         END IF
         IF (local_ot_env(1)%schur_projector_density_full_global_sel_quality_samples >= &
             ot_kp_schur_calibration_min_samples) THEN
            projector_density_selected_history_weight = &
               MAX(projector_density_selected_history_weight, &
                   kpoint_ot_direct_density_selected_mix_weight( &
                   residual_delta, density_full_global_selected_mermin_quality, &
                   density_full_global_selected_mix_residual_quality, &
                   local_ot_env(1)%schur_projector_density_full_global_sel_quality_samples))
            projector_physical_direct_density_selected_mermin_quality = &
               MAX(projector_physical_direct_density_selected_mermin_quality, &
                   density_full_global_selected_mermin_quality)
            projector_physical_direct_density_recent_residual_quality = &
               MAX(projector_physical_direct_density_recent_residual_quality, &
                   density_full_global_selected_residual_quality)
            projector_physical_direct_density_mix_residual_quality = &
               MAX(projector_physical_direct_density_mix_residual_quality, &
                   density_full_global_selected_mix_residual_quality)
         END IF
         IF (projector_density_selected_history_weight > &
             EPSILON(projector_density_selected_history_weight)) THEN
            projector_physical_direct_floor_density_weight = &
               MAX(projector_physical_direct_floor_density_weight, &
                   projector_density_selected_history_weight)
            projector_physical_direct_floor_density_quality = &
               MAX(projector_physical_direct_floor_density_quality, &
                   MIN(ot_kp_schur_projector_response_quality_max_ratio, &
                       projector_physical_direct_density_selected_mermin_quality))
            projector_physical_direct_floor_density_trust_quality = &
               MAX(projector_physical_direct_floor_density_trust_quality, &
                   MIN(1.0_dp, MAX(0.0_dp, &
                                   projector_physical_direct_density_mix_residual_quality)))
         END IF
         IF (projector_physical_direct_floor_density_weight > &
             EPSILON(projector_physical_direct_floor_density_weight) .AND. &
             (exact_density_floor_audit_ready .OR. exact_density_full_audit_ready)) THEN
            exact_density_direct_response_ready = .TRUE.
            IF (exact_density_response_ready) THEN
               energy_cross_density_direct(:, :) = &
                  (1.0_dp - projector_physical_direct_floor_density_weight)* &
                  energy_cross_density(:, :) + &
                  projector_physical_direct_floor_density_weight* &
                  MERGE(energy_cross_density_floor_audit(:, :), &
                        energy_cross_density_full_audit(:, :), &
                        exact_density_floor_audit_ready)
               response_density_direct_exact(:, :) = &
                  (1.0_dp - projector_physical_direct_floor_density_weight)* &
                  response_density_exact(:, :) + &
                  projector_physical_direct_floor_density_weight* &
                  MERGE(response_density_floor_audit_exact(:, :), &
                        response_density_full_audit_exact(:, :), &
                        exact_density_floor_audit_ready)
            ELSE
               energy_cross_density_direct(:, :) = &
                  projector_physical_direct_floor_density_weight* &
                  MERGE(energy_cross_density_floor_audit(:, :), &
                        energy_cross_density_full_audit(:, :), &
                        exact_density_floor_audit_ready)
               response_density_direct_exact(:, :) = &
                  projector_physical_direct_floor_density_weight* &
                  MERGE(response_density_floor_audit_exact(:, :), &
                        response_density_full_audit_exact(:, :), &
                        exact_density_floor_audit_ready)
            END IF
         END IF
         IF (exact_density_direct_response_ready .AND. &
             exact_density_basis_selective_audit_ready .AND. &
             projector_physical_direct_floor_density_weight > &
             EPSILON(projector_physical_direct_floor_density_weight) .AND. &
             projector_density_full_global_selective_mix_weight > &
             EPSILON(projector_density_full_global_selective_mix_weight)) THEN
            projector_physical_direct_density_selective_blend_weight = &
               MIN(1.0_dp, MAX(0.0_dp, projector_density_full_global_selective_mix_weight))
            IF (exact_density_response_ready) THEN
               energy_cross_density_direct(:, :) = &
                  (1.0_dp - projector_physical_direct_density_selective_blend_weight)* &
                  energy_cross_density_direct(:, :) + &
                  projector_physical_direct_density_selective_blend_weight* &
                  ((1.0_dp - projector_physical_direct_floor_density_weight)* &
                   energy_cross_density(:, :) + &
                   projector_physical_direct_floor_density_weight* &
                   energy_cross_density_basis_selective_audit(:, :))
               response_density_direct_exact(:, :) = &
                  (1.0_dp - projector_physical_direct_density_selective_blend_weight)* &
                  response_density_direct_exact(:, :) + &
                  projector_physical_direct_density_selective_blend_weight* &
                  ((1.0_dp - projector_physical_direct_floor_density_weight)* &
                   response_density_exact(:, :) + &
                   projector_physical_direct_floor_density_weight* &
                   response_density_basis_selective_audit_exact(:, :))
            ELSE
               energy_cross_density_direct(:, :) = &
                  (1.0_dp - projector_physical_direct_density_selective_blend_weight)* &
                  energy_cross_density_direct(:, :) + &
                  projector_physical_direct_density_selective_blend_weight* &
                  projector_physical_direct_floor_density_weight* &
                  energy_cross_density_basis_selective_audit(:, :)
               response_density_direct_exact(:, :) = &
                  (1.0_dp - projector_physical_direct_density_selective_blend_weight)* &
                  response_density_direct_exact(:, :) + &
                  projector_physical_direct_density_selective_blend_weight* &
                  projector_physical_direct_floor_density_weight* &
                  response_density_basis_selective_audit_exact(:, :)
            END IF
         END IF
         IF (exact_density_direct_response_ready .AND. &
             exact_density_basis_filtered_audit_ready .AND. &
             projector_physical_direct_floor_density_weight > &
             EPSILON(projector_physical_direct_floor_density_weight)) THEN
            projector_physical_direct_density_filtered_shadow_weight = &
               kpoint_ot_physical_direct_density_filtered_shadow_weight( &
               residual_delta, projector_physical_direct_floor_density_weight, &
               projector_physical_direct_floor_density_quality, &
               projector_physical_direct_floor_density_trust_quality, &
               projector_density_basis_filtered_audit_abs_avg, &
               projector_density_basis_filtered_audit_exact_abs_avg, &
               projector_density_basis_filtered_audit_low_curv_fraction)
         END IF
         projector_physical_direct_density_fshadow_promotion_weight = &
            kp_ot_phys_dir_den_fshadow_prom_weight( &
            projector_physical_direct_density_filtered_shadow_weight, &
            local_ot_env(1)%schur_projector_phys_direct_density_fshadow_quality_samples, &
            local_ot_env(1)%schur_projector_phys_direct_density_fshadow_quality, &
            local_ot_env(1)%schur_projector_phys_direct_density_fshadow_quality_ema, &
            local_ot_env(1)%schur_projector_phys_direct_density_fshadow_resid_quality, &
            local_ot_env(1)%schur_projector_phys_direct_density_fshadow_resid_quality_ema, &
            local_ot_env(1)%schur_projector_phys_direct_density_fshadow_coverage, &
            local_ot_env(1)%schur_projector_phys_direct_density_fshadow_coverage_ema)
         projector_physical_direct_density_fshadow_ready = &
            projector_physical_direct_density_fshadow_promotion_weight > &
            EPSILON(projector_physical_direct_density_fshadow_promotion_weight)
         local_ot_env(1)%schur_projector_phys_direct_density_fshadow_ready = &
            projector_physical_direct_density_fshadow_ready
         local_ot_env(1)%schur_projector_phys_direct_density_fshadow_promotion_weight = &
            projector_physical_direct_density_fshadow_promotion_weight
         IF (exact_density_direct_response_ready .AND. exact_density_basis_filtered_audit_ready .AND. &
             projector_physical_direct_density_fshadow_ready) THEN
            energy_cross_density_direct(:, :) = &
               (1.0_dp - projector_physical_direct_density_fshadow_promotion_weight)* &
               energy_cross_density_direct(:, :) + &
               projector_physical_direct_density_fshadow_promotion_weight* &
               energy_cross_density_basis_filtered_audit(:, :)
            response_density_direct_exact(:, :) = &
               (1.0_dp - projector_physical_direct_density_fshadow_promotion_weight)* &
               response_density_direct_exact(:, :) + &
               projector_physical_direct_density_fshadow_promotion_weight* &
               response_density_basis_filtered_audit_exact(:, :)
         END IF
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,17(1X,ES16.8),1X,L1,1(1X,ES16.8),2(1X,I8))') &
            " OT Schur projector phys direct density mix group weight boot mature qhist tqhist absavg "// &
            "selw selq selrq selmixrq gselq gselrq gscale rchavg rchmax rchfrac fshadow fready fprom "// &
            "samples sels:", &
            target_group, projector_physical_direct_floor_density_weight, &
            projector_physical_direct_floor_density_bootstrap_weight, &
            projector_physical_direct_floor_density_maturity, &
            projector_physical_direct_floor_density_quality, &
            projector_physical_direct_floor_density_trust_quality, &
            projector_density_full_global_abs_avg, &
            projector_density_selected_history_weight, &
            projector_physical_direct_density_selected_mermin_quality, &
            projector_physical_direct_density_recent_residual_quality, &
            projector_physical_direct_density_mix_residual_quality, &
            density_full_global_selected_mermin_quality, &
            density_full_global_selected_residual_quality, &
            density_full_global_selected_response_scale, &
            projector_response_character_abs_avg, &
            projector_response_character_max, &
            projector_response_character_fraction, &
            projector_physical_direct_density_filtered_shadow_weight, &
            projector_physical_direct_density_fshadow_ready, &
            projector_physical_direct_density_fshadow_promotion_weight, &
            local_ot_env(1)%schur_projector_density_full_global_quality_samples, &
            local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_samples
         IF (exact_density_direct_response_ready) THEN
            DO s = 1, nrot
               DO r = 1, nrot
                  projected_term = 0.5_dp* &
                                   (DOT_PRODUCT(energy_cross_density_direct(:, r), &
                                                response_density_direct_exact(:, s)) + &
                                    DOT_PRODUCT(energy_cross_density_direct(:, s), &
                                                response_density_direct_exact(:, r)))
                  IF (exact_density_response_ready) &
                     projected_term = projected_term - 0.5_dp* &
                                      (DOT_PRODUCT(energy_cross_density(:, r), response_density_exact(:, s)) + &
                                       DOT_PRODUCT(energy_cross_density(:, s), response_density_exact(:, r)))
                  rot_hessian_projector_physical(r, s) = &
                     rot_hessian_projector_physical(r, s) + projected_term
                  rot_hessian_projector_physical_diagref(r, s) = &
                     rot_hessian_projector_physical_diagref(r, s) + projected_term
               END DO
            END DO
         END IF
         ! Rebuild the off-diagonal projector-response active block with the
         ! same history-qualified physical pair weights used by the Direct
         ! Schur model below.  The early Fermi-window split is a conservative
         ! bootstrap; once density-response history is mature, occupied/virtual
         ! occupation-gap pairs carry physical response and should not remain
         ! lumped into the inactive projector-gauge bucket.
         rot_hessian_projector_physical_offdiag_active(:, :) = 0.0_dp
         rot_hessian_projector_physical_offdiag_plateau_active(:, :) = 0.0_dp
         DO s = 1, nrot
            DO r = 1, nrot
               IF (var_channel(r) /= var_channel(s)) CYCLE
               projector_physical_active_weight_r = &
                  kpoint_ot_physical_pair_projector_weight(var_projector_weight(r), &
                                                           var_projector_active_weight(r), &
                                                           var_occ_gap_weight(r), &
                                                           projector_physical_direct_floor_density_weight, &
                                                           var_projector_response_weight(r))
               projector_physical_active_weight_s = &
                  kpoint_ot_physical_pair_projector_weight(var_projector_weight(s), &
                                                           var_projector_active_weight(s), &
                                                           var_occ_gap_weight(s), &
                                                           projector_physical_direct_floor_density_weight, &
                                                           var_projector_response_weight(s))
               projector_offdiag_active_weight = 0.0_dp
               IF (var_projector_weight(r) + var_projector_weight(s) > &
                   EPSILON(projector_offdiag_active_weight)) THEN
                  projector_offdiag_active_weight = &
                     (projector_physical_active_weight_r + projector_physical_active_weight_s)/ &
                     MAX(var_projector_weight(r) + var_projector_weight(s), EPSILON(1.0_dp))
                  projector_offdiag_active_weight = &
                     MIN(1.0_dp, MAX(0.0_dp, projector_offdiag_active_weight))
               END IF
               rot_hessian_projector_physical_offdiag_active(r, s) = &
                  projector_offdiag_active_weight*rot_hessian_projector_physical_offdiag(r, s)
               rot_hessian_projector_physical_offdiag_plateau_active(r, s) = &
                  projector_offdiag_active_weight*rot_hessian_projector_physical_offdiag_plateau(r, s)
            END DO
         END DO
         rot_hessian_projector_physical_offdiag_active(:, :) = 0.5_dp* &
                                                               (rot_hessian_projector_physical_offdiag_active(:, :) + &
                                                                TRANSPOSE(rot_hessian_projector_physical_offdiag_active(:, :)))
         rot_hessian_projector_physical_offdiag_plateau_active(:, :) = 0.5_dp* &
                                                                    (rot_hessian_projector_physical_offdiag_plateau_active(:, :) + &
                                                             TRANSPOSE(rot_hessian_projector_physical_offdiag_plateau_active(:, :)))
         projector_physical_offdiag_active_abs_avg = &
            SUM(ABS(rot_hessian_projector_physical_offdiag_active(:, :)))
         projector_physical_offdiag_inactive_abs_avg = &
            SUM(ABS(rot_hessian_projector_physical_offdiag(:, :) - &
                    rot_hessian_projector_physical_offdiag_active(:, :)))
         projector_physical_offdiag_plateau_gap_active_abs_avg = &
            SUM(ABS(rot_hessian_projector_physical_offdiag_plateau_active(:, :) - &
                    rot_hessian_projector_physical_offdiag_active(:, :)))
         projector_physical_offdiag_plateau_gap_inactive_abs_avg = &
            SUM(ABS((rot_hessian_projector_physical_offdiag_plateau(:, :) - &
                     rot_hessian_projector_physical_offdiag(:, :)) - &
                    (rot_hessian_projector_physical_offdiag_plateau_active(:, :) - &
                     rot_hessian_projector_physical_offdiag_active(:, :))))
         ! Keep the validated full physical trace backbone for cross-channel
         ! fixed-N terms, but filter the same-channel non-covariant residual
         ! with the active occupation-window pair weight.  This keeps genuine
         ! Fermi-window curvature while avoiding hardening local gauge-noise
         ! modes in the Direct finite-response correction.
         rot_hessian_projector_physical_active(:, :) = rot_hessian_projector_physical(:, :)
         DO s = 1, nrot
            DO r = 1, nrot
               projector_physical_active_weight_r = &
                  kpoint_ot_physical_pair_projector_weight(var_projector_weight(r), &
                                                           var_projector_active_weight(r), &
                                                           var_occ_gap_weight(r), &
                                                           projector_physical_direct_floor_density_weight, &
                                                           var_projector_response_weight(r))
               projector_physical_active_weight_s = &
                  kpoint_ot_physical_pair_projector_weight(var_projector_weight(s), &
                                                           var_projector_active_weight(s), &
                                                           var_occ_gap_weight(s), &
                                                           projector_physical_direct_floor_density_weight, &
                                                           var_projector_response_weight(s))
               projector_physical_covariant_delta = &
                  -0.5_dp*(var_projector_weight(r) + var_projector_weight(s))*rot_hessian(r, s)
               projector_physical_active_covariant_delta = &
                  -0.5_dp*(projector_physical_active_weight_r + &
                           projector_physical_active_weight_s)*rot_hessian(r, s)
               IF (var_channel(r) /= var_channel(s)) CYCLE
               projector_offdiag_active_weight = 0.0_dp
               IF (var_projector_weight(r) + var_projector_weight(s) > &
                   EPSILON(projector_offdiag_active_weight)) THEN
                  projector_offdiag_active_weight = &
                     (projector_physical_active_weight_r + projector_physical_active_weight_s)/ &
                     MAX(var_projector_weight(r) + var_projector_weight(s), EPSILON(1.0_dp))
                  projector_offdiag_active_weight = &
                     MIN(1.0_dp, MAX(0.0_dp, projector_offdiag_active_weight))
               END IF
               projector_physical_residual_delta = &
                  rot_hessian_projector_physical(r, s) - rot_hessian(r, s) - &
                  projector_physical_covariant_delta
               rot_hessian_projector_physical_active(r, s) = &
                  rot_hessian(r, s) + projector_physical_active_covariant_delta + &
                  projector_offdiag_active_weight*projector_physical_residual_delta
            END DO
         END DO
         DO r = 1, nrot
            projector_hessian_diag_avg = projector_hessian_diag_avg + rot_hessian_projector(r, r)
            projector_hessian_delta_diag_avg = projector_hessian_delta_diag_avg + &
                                               rot_hessian_projector(r, r) - rot_hessian(r, r)
            projector_physical_diag_avg = projector_physical_diag_avg + rot_hessian_projector_physical(r, r)
            projector_physical_delta_diag_avg = projector_physical_delta_diag_avg + &
                                                rot_hessian_projector_physical(r, r) - rot_hessian(r, r)
            projector_physical_offdiag_diag_avg = projector_physical_offdiag_diag_avg + &
                                                  rot_hessian_projector_physical_offdiag(r, r)
            projector_physical_offdiag_plateau_diag_avg = projector_physical_offdiag_plateau_diag_avg + &
                                                          rot_hessian_projector_physical_offdiag_plateau(r, r)
            projector_physical_offdiag_plateau_gap_diag_avg = &
               projector_physical_offdiag_plateau_gap_diag_avg + &
               rot_hessian_projector_physical_offdiag_plateau(r, r) - &
               rot_hessian_projector_physical_offdiag(r, r)
            projector_physical_diagref_diag_avg = projector_physical_diagref_diag_avg + &
                                                  rot_hessian_projector_physical_diagref(r, r)
            projector_physical_diagref_delta_diag_avg = projector_physical_diagref_delta_diag_avg + &
                                                        rot_hessian_projector_physical_diagref(r, r) - rot_hessian(r, r)
            projector_physical_diagref_gap_diag_avg = projector_physical_diagref_gap_diag_avg + &
                                                 rot_hessian_projector_physical_diagref(r, r) - rot_hessian_projector_physical(r, r)
            projector_physical_active_weight_r = &
               kpoint_ot_physical_pair_projector_weight(var_projector_weight(r), &
                                                        var_projector_active_weight(r), &
                                                        var_occ_gap_weight(r), &
                                                        projector_physical_direct_floor_density_weight, &
                                                        var_projector_response_weight(r))
            projector_physical_covariant_delta = -var_projector_weight(r)*rot_hessian(r, r)
            projector_physical_active_covariant_delta = -projector_physical_active_weight_r*rot_hessian(r, r)
            projector_physical_residual_delta = rot_hessian_projector_physical(r, r) - rot_hessian(r, r) - &
                                                projector_physical_covariant_delta
            projector_physical_covariant_diag_avg = projector_physical_covariant_diag_avg + &
                                                    projector_physical_covariant_delta
            projector_physical_active_covariant_diag_avg = projector_physical_active_covariant_diag_avg + &
                                                           projector_physical_active_covariant_delta
            projector_physical_residual_diag_avg = projector_physical_residual_diag_avg + &
                                                   projector_physical_residual_delta
            IF (var_projector_weight(r) > EPSILON(var_projector_weight(r))) THEN
               projector_physical_active_weight_avg = projector_physical_active_weight_avg + &
                                                      projector_physical_active_weight_r/var_projector_weight(r)
               projector_physical_active_weight_max = MAX(projector_physical_active_weight_max, &
                                                          projector_physical_active_weight_r/var_projector_weight(r))
               IF (projector_physical_active_weight_r > EPSILON(projector_physical_active_weight_r)) &
                  projector_physical_active_weight_fraction = projector_physical_active_weight_fraction + 1.0_dp
            END IF
            DO s = 1, nrot
               projector_physical_active_weight_r = &
                  kpoint_ot_physical_pair_projector_weight(var_projector_weight(r), &
                                                           var_projector_active_weight(r), &
                                                           var_occ_gap_weight(r), &
                                                           projector_physical_direct_floor_density_weight, &
                                                           var_projector_response_weight(r))
               projector_physical_active_weight_s = &
                  kpoint_ot_physical_pair_projector_weight(var_projector_weight(s), &
                                                           var_projector_active_weight(s), &
                                                           var_occ_gap_weight(s), &
                                                           projector_physical_direct_floor_density_weight, &
                                                           var_projector_response_weight(s))
               projector_physical_covariant_delta = -0.5_dp*(var_projector_weight(r) + &
                                                             var_projector_weight(s))*rot_hessian(r, s)
               projector_physical_active_covariant_delta = &
                  -0.5_dp*(projector_physical_active_weight_r + &
                           projector_physical_active_weight_s)*rot_hessian(r, s)
               projector_physical_residual_delta = rot_hessian_projector_physical(r, s) - rot_hessian(r, s) - &
                                                   projector_physical_covariant_delta
               projector_hessian_abs_avg = projector_hessian_abs_avg + &
                                           ABS(rot_hessian_projector(r, s) - rot_hessian(r, s))
               projector_hessian_delta_max = MAX(projector_hessian_delta_max, &
                                                 ABS(rot_hessian_projector(r, s) - rot_hessian(r, s)))
               projector_physical_abs_avg = projector_physical_abs_avg + &
                                            ABS(rot_hessian_projector_physical(r, s) - rot_hessian(r, s))
               projector_physical_delta_max = MAX(projector_physical_delta_max, &
                                                  ABS(rot_hessian_projector_physical(r, s) - rot_hessian(r, s)))
               projector_physical_offdiag_abs_avg = projector_physical_offdiag_abs_avg + &
                                                    ABS(rot_hessian_projector_physical_offdiag(r, s))
               projector_physical_offdiag_delta_max = MAX(projector_physical_offdiag_delta_max, &
                                                          ABS(rot_hessian_projector_physical_offdiag(r, s)))
               projector_physical_offdiag_plateau_abs_avg = &
                  projector_physical_offdiag_plateau_abs_avg + &
                  ABS(rot_hessian_projector_physical_offdiag_plateau(r, s))
               projector_physical_offdiag_plateau_delta_max = &
                  MAX(projector_physical_offdiag_plateau_delta_max, &
                      ABS(rot_hessian_projector_physical_offdiag_plateau(r, s)))
               projector_physical_offdiag_plateau_gap_abs_avg = &
                  projector_physical_offdiag_plateau_gap_abs_avg + &
                  ABS(rot_hessian_projector_physical_offdiag_plateau(r, s) - &
                      rot_hessian_projector_physical_offdiag(r, s))
               projector_physical_offdiag_plateau_gap_delta_max = &
                  MAX(projector_physical_offdiag_plateau_gap_delta_max, &
                      ABS(rot_hessian_projector_physical_offdiag_plateau(r, s) - &
                          rot_hessian_projector_physical_offdiag(r, s)))
               projector_physical_diagref_abs_avg = projector_physical_diagref_abs_avg + &
                                                    ABS(rot_hessian_projector_physical_diagref(r, s) - rot_hessian(r, s))
               projector_physical_diagref_delta_max = MAX(projector_physical_diagref_delta_max, &
                                                          ABS(rot_hessian_projector_physical_diagref(r, s) - rot_hessian(r, s)))
               projector_physical_diagref_gap_abs_avg = projector_physical_diagref_gap_abs_avg + &
                                            ABS(rot_hessian_projector_physical_diagref(r, s) - rot_hessian_projector_physical(r, s))
               projector_physical_diagref_gap_delta_max = MAX(projector_physical_diagref_gap_delta_max, &
                                           ABS(rot_hessian_projector_physical_diagref(r, s) - rot_hessian_projector_physical(r, s)))
               projector_physical_covariant_abs_avg = projector_physical_covariant_abs_avg + &
                                                      ABS(projector_physical_covariant_delta)
               projector_physical_covariant_delta_max = MAX(projector_physical_covariant_delta_max, &
                                                            ABS(projector_physical_covariant_delta))
               projector_physical_active_covariant_abs_avg = projector_physical_active_covariant_abs_avg + &
                                                             ABS(projector_physical_active_covariant_delta)
               projector_physical_active_covariant_delta_max = &
                  MAX(projector_physical_active_covariant_delta_max, &
                      ABS(projector_physical_active_covariant_delta))
               projector_physical_residual_abs_avg = projector_physical_residual_abs_avg + &
                                                     ABS(projector_physical_residual_delta)
               projector_physical_residual_delta_max = MAX(projector_physical_residual_delta_max, &
                                                           ABS(projector_physical_residual_delta))
               projector_gauge_abs_avg = projector_gauge_abs_avg + &
                                         ABS(rot_hessian_projector(r, s) - rot_hessian_projector_physical(r, s))
               projector_gauge_delta_max = MAX(projector_gauge_delta_max, &
                                               ABS(rot_hessian_projector(r, s) - rot_hessian_projector_physical(r, s)))
            END DO
         END DO
         projector_hessian_diag_avg = projector_hessian_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_hessian_delta_diag_avg = projector_hessian_delta_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_hessian_abs_avg = projector_hessian_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_diag_avg = projector_physical_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_delta_diag_avg = projector_physical_delta_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_abs_avg = projector_physical_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_offdiag_diag_avg = &
            projector_physical_offdiag_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_offdiag_abs_avg = &
            projector_physical_offdiag_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_offdiag_active_abs_avg = &
            projector_physical_offdiag_active_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_offdiag_inactive_abs_avg = &
            projector_physical_offdiag_inactive_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_offdiag_plateau_diag_avg = &
            projector_physical_offdiag_plateau_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_offdiag_plateau_abs_avg = &
            projector_physical_offdiag_plateau_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_offdiag_plateau_gap_diag_avg = &
            projector_physical_offdiag_plateau_gap_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_offdiag_plateau_gap_abs_avg = &
            projector_physical_offdiag_plateau_gap_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_offdiag_plateau_gap_active_abs_avg = &
            projector_physical_offdiag_plateau_gap_active_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_offdiag_plateau_gap_inactive_abs_avg = &
            projector_physical_offdiag_plateau_gap_inactive_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         IF (projector_physical_abs_avg > EPSILON(projector_physical_abs_avg)) &
            projector_physical_offdiag_abs_ratio = &
            projector_physical_offdiag_abs_avg/projector_physical_abs_avg
         projector_physical_diagref_diag_avg = &
            projector_physical_diagref_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_diagref_delta_diag_avg = &
            projector_physical_diagref_delta_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_diagref_gap_diag_avg = &
            projector_physical_diagref_gap_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_diagref_abs_avg = &
            projector_physical_diagref_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_diagref_gap_abs_avg = &
            projector_physical_diagref_gap_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_diagref_trace_balance = MAX(0.0_dp, -projector_physical_diagref_delta_diag_avg)
         projector_physical_covariant_diag_avg = &
            projector_physical_covariant_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_covariant_abs_avg = &
            projector_physical_covariant_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_active_covariant_diag_avg = &
            projector_physical_active_covariant_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_active_covariant_abs_avg = &
            projector_physical_active_covariant_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_active_trace_balance = MAX(0.0_dp, -projector_physical_active_covariant_diag_avg)
         projector_physical_active_weight_avg = &
            projector_physical_active_weight_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_active_weight_fraction = &
            projector_physical_active_weight_fraction/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_residual_diag_avg = &
            projector_physical_residual_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         projector_physical_residual_abs_avg = &
            projector_physical_residual_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         projector_physical_trace_balance = MAX(0.0_dp, -projector_physical_delta_diag_avg)
         projector_physical_direct_diag_balance = projector_physical_delta_diag_avg - &
                                                  projector_physical_covariant_diag_avg - &
                                                  projector_physical_residual_diag_avg
         projector_gauge_abs_avg = projector_gauge_abs_avg/REAL(MAX(1, nrot*nrot), KIND=dp)
         curv_projection_sum = SUM(curv)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(curv_projection_sum)
         occ_curv_projection_sum = SUM(occ_curv)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%sum(occ_curv_projection_sum)
         ! The split candidate follows the same diagonal/spectral projector blend as
         ! the finite complex rotation gradient: occupation curvature sees the
         ! finite projector response, while the channel-local tether still sees the
         ! full Rayleigh diagonal it anchors.
         response_coupled(:, :) = response(:, :)
         response_split(:, :) = 0.0_dp
         DO r = 1, nrot
            DO ie = 1, ne
               IF (curv(ie) > EPSILON(curv(ie))) &
                  response_split(ie, r) = (occ_curv(ie)*response_occ(ie, r) + &
                                           tether_curv(ie)*response(ie, r))/curv(ie)
            END DO
         END DO
         DO r = 1, nrot
            response_shift = DOT_PRODUCT(curv, response_coupled(:, r))
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%sum(response_shift)
            IF (curv_projection_sum > EPSILON(curv_projection_sum)) &
               response_coupled(:, r) = response_coupled(:, r) - response_shift/curv_projection_sum
            DO ie = 1, ne
               IF (curv(ie) <= EPSILON(curv(ie))) response_coupled(ie, r) = 0.0_dp
            END DO
            CALL project_kpoint_ot_schur_response(response_split(:, r), occ_curv, tether_curv, &
                                                  occ_curv_projection_sum, channel_nmo, e_offset)
         END DO
         projector_response_gap_avg = 0.0_dp
         projector_response_gap_max = 0.0_dp
         physical_response_gap_avg = 0.0_dp
         physical_response_gap_max = 0.0_dp
         DO r = 1, nrot
            projector_response_gap_norm = DOT_PRODUCT(occ_curv(:)*(response_occ(:, r) - response(:, r)), &
                                                      response_occ(:, r) - response(:, r))
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%sum(projector_response_gap_norm)
            IF (occ_curv_projection_sum > EPSILON(occ_curv_projection_sum)) &
               projector_response_gap_avg = projector_response_gap_avg + &
                                            SQRT(MAX(0.0_dp, projector_response_gap_norm/occ_curv_projection_sum))
            projector_response_gap_max = MAX(projector_response_gap_max, &
                                             MAXVAL(ABS(response_occ(:, r) - response(:, r))))
            physical_response_gap_norm = DOT_PRODUCT(occ_curv(:)*(response_occ_physical(:, r) - response_occ(:, r)), &
                                                     response_occ_physical(:, r) - response_occ(:, r))
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%sum(physical_response_gap_norm)
            IF (occ_curv_projection_sum > EPSILON(occ_curv_projection_sum)) &
               physical_response_gap_avg = physical_response_gap_avg + &
                                           SQRT(MAX(0.0_dp, physical_response_gap_norm/occ_curv_projection_sum))
            physical_response_gap_max = MAX(physical_response_gap_max, &
                                            MAXVAL(ABS(response_occ_physical(:, r) - response_occ(:, r))))
         END DO
         projector_response_gap_avg = projector_response_gap_avg/REAL(MAX(1, nrot), KIND=dp)
         physical_response_gap_avg = physical_response_gap_avg/REAL(MAX(1, nrot), KIND=dp)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%max(projector_response_gap_max)
         IF (.NOT. global_schur_replicated) &
            CALL para_env_inter_kp%max(physical_response_gap_max)
         density_plateau_exact_gap_avg = 0.0_dp
         density_plateau_exact_gap_max = 0.0_dp
         density_plateau_raw_gap_avg = 0.0_dp
         density_plateau_raw_gap_max = 0.0_dp
         IF (exact_density_response_ready .AND. exact_density_full_response_ready) THEN
            DO r = 1, nrot
               physical_response_gap_norm = &
                  DOT_PRODUCT(occ_curv(:)*(response_density_full(:, r) - response_density_physical(:, r)), &
                              response_density_full(:, r) - response_density_physical(:, r))
               IF (.NOT. global_schur_replicated) &
                  CALL para_env_inter_kp%sum(physical_response_gap_norm)
               IF (occ_curv_projection_sum > EPSILON(occ_curv_projection_sum)) &
                  density_plateau_raw_gap_avg = density_plateau_raw_gap_avg + &
                                                SQRT(MAX(0.0_dp, physical_response_gap_norm/occ_curv_projection_sum))
               density_plateau_raw_gap_max = MAX(density_plateau_raw_gap_max, &
                                                 MAXVAL(ABS(response_density_full(:, r) - &
                                                            response_density_physical(:, r))))
               physical_response_gap_norm = &
                  DOT_PRODUCT(curv(:)*(response_density_full_exact(:, r) - response_density_exact(:, r)), &
                              response_density_full_exact(:, r) - response_density_exact(:, r))
               IF (.NOT. global_schur_replicated) &
                  CALL para_env_inter_kp%sum(physical_response_gap_norm)
               IF (curv_projection_sum > EPSILON(curv_projection_sum)) &
                  density_plateau_exact_gap_avg = density_plateau_exact_gap_avg + &
                                                  SQRT(MAX(0.0_dp, physical_response_gap_norm/curv_projection_sum))
               density_plateau_exact_gap_max = MAX(density_plateau_exact_gap_max, &
                                                   MAXVAL(ABS(response_density_full_exact(:, r) - &
                                                              response_density_exact(:, r))))
            END DO
            density_plateau_raw_gap_avg = density_plateau_raw_gap_avg/REAL(MAX(1, nrot), KIND=dp)
            density_plateau_exact_gap_avg = density_plateau_exact_gap_avg/REAL(MAX(1, nrot), KIND=dp)
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%max(density_plateau_raw_gap_max)
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%max(density_plateau_exact_gap_max)
         END IF
         CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response_occ, response, grad_e, &
                                                    channel_nmo, e_offset, energy_hessian, energy_cross, &
                                                    response_exact, z_exact_trial, ipiv_energy, &
                                                    exact_energy_model_ready, energy_gauge_weight, &
                                                    energy_hessian_reference=energy_hessian_reference)
         exact_physical_response_ready = .FALSE.
         IF (exact_energy_model_ready .AND. projector_physical_shadow_enabled) &
            CALL build_kpoint_ot_exact_energy_response(canonical_occ_curv, 0.0_dp*tether_curv, &
                                                       response_occ_canonical, 0.0_dp*response, &
                                                       0.0_dp*grad_e, channel_nmo, e_offset, energy_hessian, &
                                                       energy_cross_canonical, response_exact_physical, &
                                                       z_exact_physical_trial, ipiv_energy, &
                                                       exact_physical_response_ready, energy_gauge_weight)
         exact_active_response_ready = .FALSE.
         IF (exact_energy_model_ready .AND. projector_physical_shadow_enabled) &
            CALL build_kpoint_ot_exact_energy_response(canonical_occ_curv, 0.0_dp*tether_curv, &
                                                       response_occ_physical, 0.0_dp*response, &
                                                       0.0_dp*grad_e, channel_nmo, e_offset, energy_hessian, &
                                                       energy_cross_active, response_exact_active, &
                                                       z_exact_active_trial, ipiv_energy, &
                                                       exact_active_response_ready, energy_gauge_weight)
         IF (exact_physical_response_ready) THEN
            z_exact_physical_trial(:) = z_exact_trial(:)
            ! response_exact_physical is the desired canonical fixed-N map,
            ! while the actual optimization coordinates still use the current
            ! auxiliary-energy Hessian.  Reconstruct its conjugate cross block
            ! in that metric so B and H_ee^-1 B describe the same response.
            energy_cross_canonical(:, :) = &
               MATMUL(energy_hessian_reference, response_exact_physical)
            energy_cross_physical_model(:, :) = energy_cross_canonical(:, :)
         END IF
         IF (exact_active_response_ready) THEN
            z_exact_active_trial(:) = z_exact_trial(:)
            energy_cross_active(:, :) = MATMUL(energy_hessian_reference, response_exact_active)
         END IF
         IF (exact_energy_model_ready) &
            CALL build_kpoint_ot_exact_energy_response(occ_curv, tether_curv, response, response, grad_e, &
                                                       channel_nmo, e_offset, energy_hessian, energy_cross_raw, &
                                                       response_exact_raw, z_exact_raw_trial, ipiv_energy, &
                                                       exact_energy_model_ready, energy_gauge_weight)
         IF (exact_energy_model_ready) THEN
            CALL project_kpoint_ot_schur_response(z_exact_trial, occ_curv, tether_curv, &
                                                  occ_curv_projection_sum, channel_nmo, e_offset)
            CALL project_kpoint_ot_schur_response(z_exact_raw_trial, occ_curv, tether_curv, &
                                                  occ_curv_projection_sum, channel_nmo, e_offset)
            DO s = 1, nrot
               DO r = 1, nrot
                  CALL kpoint_ot_mixed_projected_term( &
                     response_exact(:, r), response_exact(:, s), occ_curv, tether_curv, &
                     occ_curv_projection_sum, channel_nmo, e_offset, reduced_response_metric(r, s))
               END DO
            END DO
            reduced_response_metric(:, :) = 0.5_dp* &
                                            (reduced_response_metric + &
                                             TRANSPOSE(reduced_response_metric))
            DO r = 1, nrot
               exact_response_diag_avg = exact_response_diag_avg + &
                                         DOT_PRODUCT(energy_cross(:, r), response_exact(:, r))
               response_mixed_diag_avg = response_mixed_diag_avg + &
                                         0.5_dp*(DOT_PRODUCT(energy_cross(:, r), response_exact_raw(:, r)) + &
                                                 DOT_PRODUCT(energy_cross_raw(:, r), response_exact(:, r)))
            END DO
            exact_response_diag_avg = exact_response_diag_avg/REAL(MAX(1, nrot), KIND=dp)
            response_mixed_diag_avg = response_mixed_diag_avg/REAL(MAX(1, nrot), KIND=dp)
         END IF
         IF (new_search_point .AND. exact_energy_model_ready) &
            CALL audit_kpoint_ot_vector_secant_model(target_group, channel_nmo, &
                                                     channel_full_var_offset, e_offset, &
                                                     var_channel, var_i, var_j, var_kind, &
                                                     occ_curv, tether_curv, rot_hessian_coupled, &
                                                     energy_hessian_reference, energy_cross, response_exact, &
                                                     reduced_response_metric, &
                                                     residual_delta, schur_active_subspace, &
                                                     rot_hessian_secant, rot_hessian_multisecant, &
                                                     rot_hessian_reduced_secant, &
                                                     energy_hessian_multisecant, &
                                                     energy_cross_multisecant, &
                                                     reduced_secant_full_targets, &
                                                     reduced_secant_modes, &
                                                     reduced_secant_targets, &
                                                     vector_secant_update_eligible, &
                                                     multisecant_update_eligible, &
                                                     prediction_update_eligible, &
                                                     prediction_predicted_residual_ratio, &
                                                     reduced_secant_update_eligible, &
                                                     reduced_secant_replacement_eligible, &
                                                     closure_response_steps, &
                                                     closure_response_targets, &
                                                     closure_response_pair_ready, &
                                                     closure_coupled_full_rotation_correction, &
                                                     closure_coupled_full_energy_correction, &
                                                     closure_coupled_full_cross_correction, &
                                                     closure_coupled_predictive_rotation_correction, &
                                                     closure_coupled_predictive_energy_correction, &
                                                     closure_coupled_predictive_cross_correction, &
                                                     closure_coupled_predictive_finite, &
                                                     closure_coupled_predictive_consistent, &
                                                     closure_coupled_predictive_work_consistent, &
                                                     closure_predictive_overlap, &
                                                     closure_predictive_capture, &
                                                     closure_predictive_quality, &
                                                     closure_predictive_rotation_quality, &
                                                     closure_predictive_energy_quality, &
                                                     closure_predictive_work_quality, &
                                                     closure_predictive_alignment, &
                                                     closure_predictive_curvature_min, &
                                                     closure_predictive_curvature_max, &
                                                     closure_coupled_response_metric, &
                                                     closure_coupled_response_ready, &
                                                     closure_coupled_independence, &
                                                     closure_coupled_compatibility, &
                                                     closure_coupled_response_capture, &
                                                     closure_coupled_residual_ratio, &
                                                     closure_coupled_transport_ratio)
         IF (new_search_point .AND. qs_scf_kp_density_response_tail_ready( &
             response_raw_delta, ot_kp_schur_projector_response_full_delta)) &
            local_ot_env(1)%schur_density_probe_tail_armed = .TRUE.
         IF (new_search_point) &
            CALL qs_scf_kp_density_response_probe( &
            [local_ot_env(1)%mermin_closure_secant_previous_flavor, &
             local_ot_env(1)%mermin_closure_secant_flavor, &
             local_ot_env(1)%mermin_closure_secant_anchor_flavor], &
            local_ot_env(1)%schur_density_probe_tail_armed, closure_response_steps, &
            closure_response_targets, closure_density_probe_steps, &
            closure_density_probe_targets, closure_density_probe_sample_ready)
         IF (prediction_update_eligible) THEN
            CALL qs_scf_kp_coupled_schur_transport( &
               rot_hessian_coupled, energy_hessian_reference, energy_cross, &
               rot_hessian_multisecant, energy_hessian_multisecant, &
               energy_cross_multisecant, schur_metric, prediction_transport_ready, &
               prediction_transport_correction_ratio)
            prediction_update_eligible = prediction_transport_ready .AND. &
                                         prediction_transport_correction_ratio <= 0.35_dp
            IF (prediction_update_eligible) THEN
               rot_hessian_prediction(:, :) = schur_metric(:, :)
               energy_hessian_prediction(:, :) = energy_hessian_reference(:, :)
               energy_cross_prediction(:, :) = energy_cross(:, :)
               response_prediction(:, :) = response_exact(:, :)
               prediction_z_base(:) = z_exact_trial(:)
            END IF
         END IF
         IF (multisecant_update_eligible) &
            CALL solve_kpoint_ot_secant_energy_response( &
            energy_hessian_multisecant, energy_cross_multisecant, grad_e, occ_curv, tether_curv, &
            channel_nmo, e_offset, response_multisecant, z_multisecant, ipiv_energy, &
            multisecant_response_ready)
         multisecant_update_eligible = multisecant_update_eligible .AND. multisecant_response_ready
         vector_secant_update_ready = vector_secant_update_eligible .AND. &
                                      (local_ot_env(1)%schur_vector_secant_candidate_enabled .OR. &
                                       local_ot_env(1)%schur_vector_secant_quality_samples < &
                                       ot_kp_schur_calibration_min_samples)
         prediction_update_ready = prediction_update_eligible .AND. &
                                   (local_ot_env(1)%schur_prediction_candidate_enabled .OR. &
                                    local_ot_env(1)%schur_prediction_quality_samples < &
                                    ot_kp_schur_calibration_min_samples)
         multisecant_update_ready = multisecant_update_eligible .AND. &
                                    local_ot_env(1)%schur_vector_secant_candidate_enabled .AND. &
                                    (local_ot_env(1)%schur_multisecant_candidate_enabled .OR. &
                                     local_ot_env(1)%schur_multisecant_quality_samples < &
                                     ot_kp_schur_calibration_min_samples)
         IF (.NOT. vector_secant_update_ready) rot_hessian_secant(:, :) = rot_hessian_coupled(:, :)
         IF (.NOT. multisecant_update_ready) &
            rot_hessian_multisecant(:, :) = rot_hessian_coupled(:, :)
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,3(1X,L1),1X,I6)') &
            " OT Schur vector-secant candidate group eligible apply promoted samples:", &
            target_group, vector_secant_update_eligible, vector_secant_update_ready, &
            local_ot_env(1)%schur_vector_secant_candidate_enabled, &
            local_ot_env(1)%schur_vector_secant_quality_samples
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,4(1X,L1),1X,I6)') &
            " OT Schur multisecant candidate group eligible response apply promoted samples:", &
            target_group, multisecant_update_eligible, multisecant_response_ready, &
            multisecant_update_ready, &
            local_ot_env(1)%schur_multisecant_candidate_enabled, &
            local_ot_env(1)%schur_multisecant_quality_samples
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,4(1X,L1),1X,ES16.8,1X,I6)') &
            " OT Schur prediction candidate group eligible transport apply promoted correction samples:", &
            target_group, prediction_update_eligible, prediction_transport_ready, &
            prediction_update_ready, local_ot_env(1)%schur_prediction_candidate_enabled, &
            prediction_transport_correction_ratio, local_ot_env(1)%schur_prediction_quality_samples
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,3(1X,L1),1X,I6)') &
            " OT Schur reduced-secant shadow group eligible replacement validated samples:", &
            target_group, reduced_secant_update_eligible, &
            reduced_secant_replacement_eligible, &
            local_ot_env(1)%schur_reduced_secant_shadow_validated, &
            local_ot_env(1)%schur_reduced_secant_quality_samples

         IF (sigma > EPSILON(sigma)) THEN
            response_trust_base = schur_response_trust_factor* &
                                  kpoint_ot_fermi_window_anchor(sigma, smear%method)
            response_abs_trust = ot_kp_fermi_window_outer_factor*sigma
            DO local_channel = 1, SIZE(local_ot_env)
               IF (local_ot_env(local_channel)%ener_x_trust_radius <= 0.0_dp) CYCLE
               density_projector_trust_scale = &
                  MIN(density_projector_trust_scale, local_ot_env(local_channel)%ener_x_trust_scale)
            END DO
            IF (global_schur_replicated) CALL para_env_inter_kp%min(density_projector_trust_scale)
            density_projector_trust_scale = MIN(1.0_dp, MAX(0.0_dp, density_projector_trust_scale))
            IF (density_projector_control_delta > 0.0_dp .AND. &
                ot_kp_canonical_density_max_weight > 0.0_dp) THEN
               density_projector_fraction = &
                  kpoint_ot_canonical_density_projector_weight(density_projector_control_delta)/ &
                  ot_kp_canonical_density_max_weight
               density_projector_fraction = density_projector_trust_scale* &
                                            MIN(1.0_dp, MAX(0.0_dp, density_projector_fraction))
               density_projector_response_trust_fraction = density_projector_fraction
               ! The density blend may be active early; only let it tighten the
               ! Schur response trust when the residual has reached the coupled tail.
               IF (residual_delta > ot_kp_schur_projector_coupled_tail_delta) &
                  density_projector_response_trust_fraction = density_projector_response_trust_fraction* &
                                                              MIN(1.0_dp, &
                                                                  ot_kp_schur_projector_coupled_tail_delta/ &
                                                                  MAX(residual_delta, EPSILON(1.0_dp)))
               response_trust_factor = MAX(ot_kp_schur_response_trust_min_factor, &
                                           1.0_dp - density_projector_response_trust_fraction)
            END IF
            response_trust = response_trust_base*response_trust_factor
         END IF
         ! current_point_is_fine() consumes the preconditioned direction in this
         ! same minimizer call, including an explicitly evaluated line-search endpoint.
         reduced_secant_candidate_enabled = new_search_point .AND. &
                                            reduced_secant_update_eligible .AND. &
                                            exact_energy_model_ready .AND. &
                                            .NOT. reduced_secant_endpoint_pending
         closure_candidate_enabled = new_search_point .AND. exact_energy_model_ready .AND. &
                                     .NOT. closure_candidate_endpoint_pending
         solved = .FALSE.
         trust_rejected = .FALSE.
         schur_used_attempt = 0
         selected_flavor = 0
         ! Evaluate the split fixed-N/tether Schur model under HIGH audit, or
         ! after accepted Mermin line-search drops validate the model quality.
         split_candidate_enabled = new_search_point .AND. local_ot_env(1)%schur_split_candidate_enabled
         constrained_candidate_enabled = new_search_point .AND. &
                                         local_ot_env(1)%schur_constrained_candidate_enabled
         split_candidate_diagnostic = split_candidate_enabled .OR. constrained_candidate_enabled
         IF (local_ot_env(1)%schur_split_quality_samples >= ot_kp_schur_calibration_min_samples) THEN
            split_quality_for_calibration = &
               kpoint_ot_schur_history_quality(local_ot_env(1)%schur_split_drop_sum, &
                                               local_ot_env(1)%schur_split_measured_sum, &
                                               local_ot_env(1)%schur_split_quality_ema, &
                                               local_ot_env(1)%schur_split_quality_samples, &
                                               ot_kp_schur_calibration_min_samples, &
                                               local_ot_env(1)%schur_split_quality_ema, &
                                               ot_kp_schur_calibration_floor, 1.0_dp)
            split_quality_for_calibration = MAX(split_quality_for_calibration, &
                                                MAX(ot_kp_schur_calibration_floor, &
                                                    MIN(1.0_dp, local_ot_env(1)%schur_split_quality_ema)))
         ELSE IF (local_ot_env(1)%schur_coupled_quality_samples >= ot_kp_schur_calibration_min_samples) THEN
            ! Bootstrap Split curvature from the accepted dense/coupled Mermin
            ! model quality.  Otherwise Split candidates that are already known
            ! to be over-optimistic can be rejected by the OT z.z=g.z scale gate
            ! before they ever collect their own calibration samples.
            split_quality_for_calibration = &
               kpoint_ot_schur_history_quality(local_ot_env(1)%schur_coupled_calibrated_drop_sum, &
                                               local_ot_env(1)%schur_coupled_measured_sum, &
                                               local_ot_env(1)%schur_coupled_calibrated_quality_ema, &
                                               local_ot_env(1)%schur_coupled_quality_samples, &
                                               ot_kp_schur_calibration_min_samples, &
                                               local_ot_env(1)%schur_coupled_calibrated_quality_ema, &
                                               ot_kp_schur_calibration_floor, 1.0_dp)
            split_quality_for_calibration = MAX(split_quality_for_calibration, &
                                                MAX(ot_kp_schur_calibration_floor, &
                                                    MIN(1.0_dp, &
                                                        local_ot_env(1)%schur_coupled_calibrated_quality_ema)))
         END IF
         IF (local_ot_env(1)%schur_coupled_quality_samples >= ot_kp_schur_calibration_min_samples) THEN
            dense_quality_for_selection = &
               kpoint_ot_schur_history_quality(local_ot_env(1)%schur_coupled_calibrated_drop_sum, &
                                               local_ot_env(1)%schur_coupled_measured_sum, &
                                               local_ot_env(1)%schur_coupled_calibrated_quality_ema, &
                                               local_ot_env(1)%schur_coupled_quality_samples, &
                                               ot_kp_schur_calibration_min_samples, 1.0_dp, &
                                               ot_kp_schur_calibrated_quality_min_ratio, &
                                               ot_kp_schur_calibrated_quality_max_ratio)
            dense_quality_for_selection = MAX(dense_quality_for_selection, &
                                              MAX(ot_kp_schur_calibrated_quality_min_ratio, &
                                                  MIN(ot_kp_schur_calibrated_quality_max_ratio, &
                                                      local_ot_env(1)%schur_coupled_calibrated_quality_ema)))
         END IF
         projector_mode_history_quality = dense_quality_for_selection
         IF (local_ot_env(1)%schur_projector_mode_quality_samples >= ot_kp_schur_calibration_min_samples) THEN
            projector_mode_history_quality = &
               kpoint_ot_schur_history_quality(local_ot_env(1)%schur_projector_mode_drop_sum, &
                                               local_ot_env(1)%schur_projector_mode_measured_sum, &
                                               local_ot_env(1)%schur_projector_mode_quality_ema, &
                                               local_ot_env(1)%schur_projector_mode_quality_samples, &
                                               ot_kp_schur_calibration_min_samples, &
                                               dense_quality_for_selection, &
                                               ot_kp_schur_calibrated_quality_min_ratio, &
                                               ot_kp_schur_calibrated_quality_max_ratio)
         END IF
         IF (local_ot_env(1)%schur_projector_mode_drop_sum > &
             EPSILON(local_ot_env(1)%schur_projector_mode_drop_sum)) &
            projector_mode_history_response_ratio = &
            local_ot_env(1)%schur_projector_mode_response_drop_sum/ &
            local_ot_env(1)%schur_projector_mode_drop_sum
         projector_mode_history_response_negative = &
            local_ot_env(1)%schur_projector_mode_response_negative_ema
         projector_physical_direct_spectral_quality_for_selection = &
            kpoint_ot_schur_history_quality( &
            local_ot_env(1)%schur_projector_spectral_selected_drop_sum, &
            local_ot_env(1)%schur_projector_spectral_selected_measured_sum, &
            local_ot_env(1)%schur_projector_spectral_selected_quality_ema, &
            local_ot_env(1)%schur_projector_spectral_selected_quality_samples, &
            ot_kp_schur_projector_response_min_samples, &
            0.0_dp, &
            ot_kp_schur_projector_response_quality_min_ratio, &
            ot_kp_schur_projector_response_quality_max_ratio)
         projector_physical_direct_spectral_shadow_quality_for_probe = &
            kpoint_ot_schur_history_quality(local_ot_env(1)%schur_projector_spectral_drop_sum, &
