                  density_full_global_candidate_selected = .FALSE.
                  projector_physical_direct_spectral_candidate_selected = .FALSE.
                  projector_physical_direct_spectral_probe_selected = .FALSE.
                  projector_response_candidate_selected = .FALSE.
                  z_e(:) = projector_offdiag_z_e(:)
                  sol(:) = projector_offdiag_sol(:)
                  direction_scale = projector_offdiag_direction_scale
                  gdotp = projector_offdiag_gdotp
                  gdot_energy = projector_offdiag_gdot_energy
                  gdot_rotation = projector_offdiag_gdot_rotation
                  norm_energy = projector_offdiag_norm_energy
                  norm_rotation = projector_offdiag_norm_rotation
                  normp = projector_offdiag_normp
                  norm_ratio = projector_offdiag_norm_ratio
                  scale_quality = projector_offdiag_scale_quality
                  model_drop = projector_offdiag_model_drop
                  model_calibrated_drop = projector_offdiag_model_calibrated_drop
                  model_gap = projector_offdiag_model_gap
                  model_gap_drop = projector_offdiag_model_gap_drop
                  model_gap_ratio = projector_offdiag_model_gap_ratio
                  model_gap_trust = projector_offdiag_model_gap_trust
                  response_abs_step = projector_offdiag_response_abs_step
                  response_abs_trust_ratio = projector_offdiag_response_abs_trust_ratio
                  response_weighted_step = projector_offdiag_response_weighted_step
                  response_weighted_trust_ratio = projector_offdiag_response_weighted_trust_ratio
                  mermin_branch_loss_gain = MAX(mermin_branch_loss_gain, &
                                                dense_branch_expected_drop - &
                                                projector_offdiag_expected_drop)
                  dense_expected_drop = dense_branch_expected_drop
               END IF
               split_dense_expected_ratio = 0.0_dp
               IF (dense_expected_drop > EPSILON(dense_expected_drop)) &
                  split_dense_expected_ratio = split_expected_drop/dense_expected_drop
               split_residual_competitive = .TRUE.
               IF (.NOT. attempt_failed .AND. &
                   residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
                   local_ot_env(1)%schur_coupled_quality_samples >= ot_kp_schur_calibration_min_samples) THEN
                  split_residual_competitive = &
                     local_ot_env(1)%schur_split_quality_samples >= ot_kp_schur_calibration_min_samples .AND. &
                     split_residual_quality >= &
                     ot_kp_schur_split_tail_residual_min_ratio*dense_residual_quality
               END IF
               split_candidate_selected = attempt_failed .OR. &
                                          (split_residual_competitive .AND. &
                                           split_expected_drop > dense_expected_drop)
               IF (new_search_point .AND. split_candidate_ready .AND. .NOT. split_candidate_selected .AND. &
                   split_model_drop > EPSILON(split_model_drop)) THEN
                  local_ot_env(1)%schur_split_shadow_pending = .TRUE.
                  local_ot_env(1)%schur_split_shadow_drop = &
                     local_ot_env(1)%schur_split_shadow_drop + split_model_drop
                  local_ot_env(1)%schur_split_shadow_calibrated_drop = &
                     local_ot_env(1)%schur_split_shadow_calibrated_drop + split_model_calibrated_drop
               END IF
               IF (split_candidate_selected) THEN
                  attempt_failed = .FALSE.
                  projector_physical_candidate_selected = .FALSE.
                  projector_physical_direct_candidate_selected = .FALSE.
                  projector_physical_direct_density_candidate_selected = .FALSE.
                  density_descent_candidate_selected = .FALSE.
                  density_full_candidate_selected = .FALSE.
                  density_full_direct_candidate_selected = .FALSE.
                  density_full_global_candidate_selected = .FALSE.
                  projector_offdiag_candidate_selected = .FALSE.
                  projector_physical_direct_spectral_candidate_selected = .FALSE.
                  projector_physical_direct_spectral_probe_selected = .FALSE.
                  projector_response_candidate_selected = .FALSE.
                  z_e(:) = split_z_e(:)
                  sol(:) = split_sol(:)
                  direction_scale = split_direction_scale
                  gdotp = split_gdotp
                  gdot_energy = split_gdot_energy
                  gdot_rotation = split_gdot_rotation
                  norm_energy = split_norm_energy
                  norm_rotation = split_norm_rotation
                  normp = split_normp
                  norm_ratio = split_norm_ratio
                  scale_quality = split_scale_quality
                  model_drop = split_model_drop
                  model_calibrated_drop = split_model_calibrated_drop
                  model_gap_ratio = split_model_gap_ratio
                  occgap_shadow_drop = split_occgap_shadow_drop
                  occgap_shadow_gap_ratio = split_occgap_shadow_gap_ratio
                  density_projector_fraction = split_density_projector_fraction
                  diag_shift_max = split_diag_shift_max
                  diag_shift_sum = split_diag_shift_sum
                  residual_delta = split_residual_delta
                  response_step_max = split_response_step
                  response_abs_step = split_response_abs_step
                  response_abs_trust = split_response_abs_trust
                  response_abs_trust_ratio = split_response_abs_trust_ratio
                  response_trust = split_response_trust
                  response_trust_factor = split_response_trust_factor
                  response_weighted_step = split_response_weighted_step
                  response_weighted_trust_ratio = split_response_weighted_trust_ratio
                  rot_floor_min = split_rot_floor_min
                  schur_diag_min = split_schur_diag_min
               END IF
            END IF

            IF (schur_attempt >= 3 .AND. .NOT. split_candidate_ready) THEN
               dense_direction_scale = direction_scale
               dense_gdot_energy = gdot_energy
               dense_gdot_rotation = gdot_rotation
               dense_model_gap = model_gap
               dense_model_gap_drop = model_gap_drop
               dense_model_gap_ratio = model_gap_ratio
               dense_model_gap_trust = model_gap_trust
               dense_norm_energy = norm_energy
               dense_norm_rotation = norm_rotation
               dense_projector_coupled_weight = projector_coupled_weight
               dense_reject_reason = reject_reason
               dense_scale_quality = scale_quality
               dense_trust_quality = kpoint_ot_schur_trust_quality(response_weighted_trust_ratio, &
                                                                   response_abs_trust_ratio, &
                                                                   model_gap_ratio)
               IF (.NOT. attempt_failed) &
                  dense_expected_drop = kpoint_ot_schur_expected_drop(model_calibrated_drop, &
                                                                      dense_quality_for_selection, &
                                                                      dense_trust_quality)
               ! Candidate-specific response trust may rescue a dense base step
               ! rejected by the generic attempt gate.
               IF (local_ot_env(1)%schur_projector_response_candidate_enabled .AND. &
                   projector_response_candidate_ready .AND. &
                   projector_response_expected_drop > EPSILON(projector_response_expected_drop) .AND. &
                   projector_response_expected_drop >= &
                   ot_kp_schur_projector_response_advantage_ratio*MAX(dense_expected_drop, EPSILON(dense_expected_drop))) THEN
                  attempt_failed = .FALSE.
                  projector_response_candidate_selected = .TRUE.
                  projector_physical_direct_density_candidate_selected = .FALSE.
                  density_descent_candidate_selected = .FALSE.
                  density_full_candidate_selected = .FALSE.
                  density_full_direct_candidate_selected = .FALSE.
                  density_full_global_candidate_selected = .FALSE.
                  z_e(:) = projector_response_z_e(:)
                  sol(:) = projector_response_sol(:)
                  direction_scale = projector_response_direction_scale
                  gdotp = projector_response_gdotp
                  gdot_energy = projector_response_gdot_energy
                  gdot_rotation = projector_response_gdot_rotation
                  norm_energy = projector_response_norm_energy
                  norm_rotation = projector_response_norm_rotation
                  normp = projector_response_normp
                  norm_ratio = projector_response_norm_ratio
                  scale_quality = projector_response_scale_quality
                  model_drop = projector_response_model_drop
                  model_calibrated_drop = projector_response_model_calibrated_drop
                  model_gap = projector_response_model_gap
                  model_gap_drop = projector_response_model_gap_drop
                  model_gap_ratio = projector_response_model_gap_ratio
                  model_gap_trust = projector_response_model_gap_trust
                  response_abs_step = projector_response_response_abs_step
                  response_abs_trust_ratio = projector_response_response_abs_trust_ratio
                  response_weighted_step = projector_response_response_weighted_step
                  response_weighted_trust_ratio = projector_response_response_weighted_trust_ratio
                  dense_expected_drop = projector_response_expected_drop
               END IF
               dense_branch_expected_drop = kpoint_ot_branch_loss_density_drop( &
                                            projector_physical_direct_density_expected_drop, &
                                            dense_expected_drop, mermin_branch_loss_weight)
               projector_physical_direct_density_probe_branch_expected_drop = &
                  kpoint_ot_branch_loss_density_drop( &
                  projector_physical_direct_density_probe_expected_drop, dense_expected_drop, &
                  mermin_branch_loss_weight)
               IF (projector_physical_direct_density_candidate_ready .AND. &
                   ((projector_physical_direct_density_expected_drop > &
                     EPSILON(projector_physical_direct_density_expected_drop) .AND. &
                     dense_branch_expected_drop >= &
                     ot_kp_schur_projector_response_advantage_ratio*MAX(dense_expected_drop, &
                                                                        EPSILON(dense_expected_drop))) .OR. &
                    (projector_physical_direct_density_tail_probe_ready .AND. &
                     qs_scf_kp_density_full_direct_tail_probe( &
                     residual_delta, projector_physical_direct_density_probe_expected_drop, dense_expected_drop, &
                     projector_physical_direct_floor_density_quality, &
                     local_ot_env(1)%schur_projector_density_full_global_quality_samples, &
                     local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality, &
                     local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality_ema, &
                     local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_samples, &
                     local_ot_env(1)%kpoint_density_stationarity_ready .AND. &
                     local_ot_env(1)%kpoint_density_stationarity_delta > eps_scf_channel, &
                     local_ot_env(1)%schur_density_stationarity_quality_ema)))) THEN
                  attempt_failed = .FALSE.
                  projector_physical_direct_density_candidate_selected = .TRUE.
                  projector_physical_candidate_selected = .FALSE.
                  projector_physical_direct_candidate_selected = .FALSE.
                  density_full_global_candidate_selected = .FALSE.
                  projector_response_candidate_selected = .FALSE.
                  z_e(:) = projector_physical_direct_density_direction_scale* &
                           projector_physical_direct_density_z_e(:)
                  sol(:) = projector_physical_direct_density_direction_scale* &
                           projector_physical_direct_density_sol(:)
                  direction_scale = projector_physical_direct_density_direction_scale
                  gdotp = projector_physical_direct_density_gdotp
                  gdot_energy = projector_physical_direct_density_gdot_energy
                  gdot_rotation = projector_physical_direct_density_gdot_rotation
                  norm_energy = projector_physical_direct_density_norm_energy
                  norm_rotation = projector_physical_direct_density_norm_rotation
                  normp = projector_physical_direct_density_normp
                  norm_ratio = projector_physical_direct_density_direction_scale* &
                               projector_physical_direct_density_direction_scale* &
                               normp/MAX(gnorm, EPSILON(1.0_dp))
                  scale_quality = projector_physical_direct_density_scale_quality
                  model_drop = projector_physical_direct_density_model_drop
                  model_calibrated_drop = projector_physical_direct_density_model_calibrated_drop
                  model_gap = 0.0_dp
                  model_gap_drop = 0.0_dp
                  model_gap_ratio = 0.0_dp
                  model_gap_trust = response_trust
                  response_abs_step = projector_physical_direct_density_response_abs_step
                  response_abs_trust_ratio = projector_physical_direct_density_response_abs_trust_ratio
                  response_weighted_step = projector_physical_direct_density_response_weighted_step
                  response_weighted_trust_ratio = &
                     projector_physical_direct_density_response_weighted_trust_ratio
                  mermin_branch_loss_gain = MAX(mermin_branch_loss_gain, &
                                                MAX(dense_branch_expected_drop, &
                                                    projector_physical_direct_density_probe_branch_expected_drop) - &
                                                MAX(projector_physical_direct_density_expected_drop, &
                                                    projector_physical_direct_density_probe_expected_drop))
                  dense_expected_drop = MAX(dense_branch_expected_drop, &
                                            projector_physical_direct_density_probe_branch_expected_drop)
               END IF
               dense_branch_expected_drop = kpoint_ot_branch_loss_density_drop( &
                                            density_descent_expected_drop, &
                                            dense_expected_drop, mermin_branch_loss_weight)
               density_descent_tail_probe_ready = &
                  kpoint_ot_density_descent_tail_probe( &
                  residual_delta, density_descent_probe_expected_drop, dense_expected_drop, &
                  density_descent_quality_for_selection, density_descent_gap_recoverable_fraction, &
                  density_descent_response_weighted_trust_ratio, &
                  density_descent_response_abs_trust_ratio, &
                  local_ot_env(1)%schur_projector_density_descent_selected_residual_quality, &
                  local_ot_env(1)%schur_projector_density_descent_selected_residual_quality_ema, &
                  local_ot_env(1)%schur_projector_density_descent_selected_quality_samples, &
                  dense_residual_quality, density_descent_bootstrap_quality, &
                  local_ot_env(1)%schur_projector_density_descent_quality_samples, &
                  local_ot_env(1)%schur_projector_density_descent_support, &
                  local_ot_env(1)%schur_projector_density_descent_support_ema)
               IF (MAX(density_descent_expected_drop, density_descent_probe_expected_drop) > &
                   EPSILON(density_descent_expected_drop) .AND. &
                   ((density_descent_candidate_ready .AND. &
                     dense_branch_expected_drop >= &
                     ot_kp_schur_projector_response_advantage_ratio*MAX(dense_expected_drop, &
                                                                        EPSILON(dense_expected_drop))) .OR. &
                    density_descent_tail_probe_ready)) THEN
                  attempt_failed = .FALSE.
                  density_descent_candidate_selected = .TRUE.
                  projector_physical_candidate_selected = .FALSE.
                  projector_physical_direct_candidate_selected = .FALSE.
                  projector_physical_direct_density_candidate_selected = .FALSE.
                  density_full_global_candidate_selected = .FALSE.
                  projector_response_candidate_selected = .FALSE.
                  z_e(:) = density_descent_direction_scale*density_descent_z_e(:)
                  sol(:) = density_descent_direction_scale*density_descent_sol(:)
                  direction_scale = density_descent_direction_scale
                  gdotp = density_descent_gdotp
                  gdot_energy = density_descent_gdot_energy
                  gdot_rotation = density_descent_gdot_rotation
                  norm_energy = density_descent_norm_energy
                  norm_rotation = density_descent_norm_rotation
                  normp = density_descent_normp
                  norm_ratio = density_descent_direction_scale*density_descent_direction_scale* &
                               normp/MAX(gnorm, EPSILON(1.0_dp))
                  scale_quality = density_descent_scale_quality
                  model_drop = density_descent_model_drop
                  model_calibrated_drop = density_descent_model_calibrated_drop
                  model_gap = 0.0_dp
                  model_gap_drop = 0.0_dp
                  model_gap_ratio = 0.0_dp
                  model_gap_trust = response_trust
                  response_abs_step = density_descent_response_abs_step
                  response_abs_trust_ratio = density_descent_response_abs_trust_ratio
                  response_weighted_step = density_descent_response_weighted_step
                  response_weighted_trust_ratio = density_descent_response_weighted_trust_ratio
                  mermin_branch_loss_gain = MAX(mermin_branch_loss_gain, &
                                                dense_branch_expected_drop - density_descent_expected_drop)
                  dense_expected_drop = dense_branch_expected_drop
               END IF
               dense_branch_expected_drop = kpoint_ot_branch_loss_density_drop( &
                                            density_full_expected_drop, &
                                            dense_expected_drop, mermin_branch_loss_weight)
               IF (density_full_candidate_ready .AND. &
                   density_full_expected_drop > EPSILON(density_full_expected_drop) .AND. &
                   (dense_branch_expected_drop >= &
                    ot_kp_schur_projector_response_advantage_ratio*MAX(dense_expected_drop, &
                                                                       EPSILON(dense_expected_drop)) .OR. &
                    ((.NOT. projector_physical_direct_density_candidate_selected .OR. &
                      projector_physical_direct_density_residual_bad) .AND. &
                     ( &
                     kpoint_ot_density_full_tail_selection_probe( &
                     density_full_tail_probe_ready, density_full_expected_drop, dense_expected_drop, &
                     local_ot_env(1)%schur_projector_density_full_selected_residual_quality, &
                     local_ot_env(1)%schur_projector_density_full_selected_residual_quality_ema, &
                     local_ot_env(1)%schur_projector_density_full_selected_quality_samples, &
                     dense_residual_quality) .OR. &
                     kpoint_ot_density_full_tail_refresh_probe( &
                     density_full_tail_probe_ready, density_full_expected_drop, dense_expected_drop, &
                     local_ot_env(1)%schur_projector_density_full_quality_samples, &
                     local_ot_env(1)%schur_projector_density_full_selected_residual_quality_ema, &
                     dense_residual_quality))))) THEN
                  attempt_failed = .FALSE.
                  density_full_candidate_selected = .TRUE.
                  density_descent_candidate_selected = .FALSE.
                  projector_physical_candidate_selected = .FALSE.
                  projector_physical_direct_candidate_selected = .FALSE.
                  projector_physical_direct_density_candidate_selected = .FALSE.
                  density_full_global_candidate_selected = .FALSE.
                  projector_response_candidate_selected = .FALSE.
                  z_e(:) = density_full_direction_scale*density_full_z_e(:)
                  sol(:) = density_full_direction_scale*density_full_sol(:)
                  direction_scale = density_full_direction_scale
                  gdotp = density_full_gdotp
                  gdot_energy = density_full_gdot_energy
                  gdot_rotation = density_full_gdot_rotation
                  norm_energy = density_full_norm_energy
                  norm_rotation = density_full_norm_rotation
                  normp = density_full_normp
                  norm_ratio = density_full_direction_scale*density_full_direction_scale* &
                               normp/MAX(gnorm, EPSILON(1.0_dp))
                  scale_quality = density_full_scale_quality
                  model_drop = density_full_model_drop
                  model_calibrated_drop = density_full_model_calibrated_drop
                  model_gap = 0.0_dp
                  model_gap_drop = 0.0_dp
                  model_gap_ratio = 0.0_dp
                  model_gap_trust = response_trust
                  response_abs_step = density_full_response_abs_step
                  response_abs_trust_ratio = density_full_response_abs_trust_ratio
                  response_weighted_step = density_full_response_weighted_step
                  response_weighted_trust_ratio = density_full_response_weighted_trust_ratio
                  mermin_branch_loss_gain = MAX(mermin_branch_loss_gain, &
                                                dense_branch_expected_drop - density_full_expected_drop)
                  dense_expected_drop = dense_branch_expected_drop
               END IF
               dense_branch_expected_drop = kpoint_ot_branch_loss_density_drop( &
                                            density_full_global_expected_drop, &
                                            dense_expected_drop, mermin_branch_loss_weight)
               projector_physical_direct_density_override_protected = &
                  kpoint_ot_direct_density_selected_probe_protect( &
                  residual_delta, residual_delta <= eps_scf_channel, &
                  local_ot_env(1)%kpoint_density_stationarity_ready .AND. &
                  local_ot_env(1)%kpoint_density_stationarity_delta > eps_scf_channel, &
                  projector_physical_direct_density_candidate_selected, &
                  projector_physical_direct_density_selected_probe_ready, &
                  projector_physical_direct_density_residual_bad, &
                  projector_physical_direct_density_response_weighted_trust_ratio, &
                  projector_physical_direct_density_response_abs_trust_ratio)
               density_full_global_tail_prefer = &
                  kpoint_ot_density_full_global_tail_prefer( &
                  residual_delta, density_full_global_bootstrap_ready, &
                  density_full_global_tail_probe_ready, density_full_global_expected_drop, &
                  dense_expected_drop, &
                  local_ot_env(1)%schur_projector_density_full_global_quality, &
                  local_ot_env(1)%schur_projector_density_full_global_quality_ema, &
                  local_ot_env(1)%schur_projector_density_full_global_quality_samples, &
                  local_ot_env(1)%schur_projector_density_full_global_sel_quality, &
                  local_ot_env(1)%schur_projector_density_full_global_sel_quality_ema, &
                  local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality, &
                  local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality_ema, &
                  local_ot_env(1)%schur_projector_density_full_global_sel_quality_samples, &
                  projector_physical_direct_density_candidate_selected, &
                  projector_physical_direct_density_residual_bad, &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality, &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_resid_quality_ema, &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel_quality_samples, &
                  dense_residual_quality)
               IF (kpoint_ot_direct_density_fshadow_tail_protect( &
                   residual_delta, projector_physical_direct_density_candidate_selected, &
                   projector_physical_direct_density_fshadow_ready, &
                   projector_physical_direct_density_residual_bad, &
                   projector_physical_direct_density_expected_drop, density_full_global_expected_drop, &
                   density_full_global_tail_prefer, &
                   projector_physical_direct_density_response_weighted_trust_ratio, &
                   projector_physical_direct_density_response_abs_trust_ratio)) &
                  density_full_global_tail_prefer = .FALSE.
               IF (density_full_global_candidate_ready .AND. &
                   .NOT. projector_physical_direct_density_override_protected .AND. &
                   density_full_global_expected_drop > EPSILON(density_full_global_expected_drop) .AND. &
                   (dense_branch_expected_drop >= &
                    ot_kp_schur_projector_response_advantage_ratio*MAX(dense_expected_drop, &
                                                                       EPSILON(dense_expected_drop)) .OR. &
                    ((.NOT. projector_physical_direct_density_candidate_selected .OR. &
                      projector_physical_direct_density_residual_bad) .AND. &
                     .NOT. density_full_candidate_selected .AND. &
                     .NOT. density_descent_candidate_selected .AND. &
                     kpoint_ot_density_full_tail_selection_probe( &
                     density_full_global_tail_probe_ready, density_full_global_expected_drop, dense_expected_drop, &
                     local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality, &
                     local_ot_env(1)%schur_projector_density_full_global_sel_resid_quality_ema, &
                     local_ot_env(1)%schur_projector_density_full_global_sel_quality_samples, &
                     dense_residual_quality)) .OR. &
                    density_full_global_tail_prefer)) THEN
                  attempt_failed = .FALSE.
                  density_full_global_candidate_selected = .TRUE.
                  density_full_candidate_selected = .FALSE.
                  density_descent_candidate_selected = .FALSE.
                  projector_physical_candidate_selected = .FALSE.
                  projector_physical_direct_candidate_selected = .FALSE.
                  projector_physical_direct_density_candidate_selected = .FALSE.
                  density_full_direct_candidate_selected = .FALSE.
                  projector_response_candidate_selected = .FALSE.
                  z_e(:) = density_full_global_direction_scale*z_density_full_global_trial(:)
                  sol(:) = density_full_global_direction_scale*density_full_global_sol(:)
                  direction_scale = density_full_global_direction_scale
                  gdotp = density_full_global_gdotp
                  gdot_energy = density_full_global_gdot_energy
                  gdot_rotation = density_full_global_gdot_rotation
                  norm_energy = density_full_global_norm_energy
                  norm_rotation = density_full_global_norm_rotation
                  normp = density_full_global_normp
                  norm_ratio = density_full_global_direction_scale*density_full_global_direction_scale* &
                               normp/MAX(gnorm, EPSILON(1.0_dp))
                  scale_quality = density_full_global_scale_quality
                  model_drop = density_full_global_model_drop
                  model_calibrated_drop = density_full_global_model_calibrated_drop
                  model_gap = 0.0_dp
                  model_gap_drop = 0.0_dp
                  model_gap_ratio = 0.0_dp
                  model_gap_trust = response_trust
                  response_abs_step = density_full_global_response_abs_step
                  response_abs_trust_ratio = density_full_global_response_abs_trust_ratio
                  response_weighted_step = density_full_global_response_weighted_step
                  response_weighted_trust_ratio = density_full_global_response_weighted_trust_ratio
                  mermin_branch_loss_gain = MAX(mermin_branch_loss_gain, &
                                                dense_branch_expected_drop - &
                                                density_full_global_expected_drop)
                  dense_expected_drop = dense_branch_expected_drop
               END IF
               dense_branch_expected_drop = kpoint_ot_branch_loss_density_drop( &
                                            density_full_direct_expected_drop, &
                                            dense_expected_drop, mermin_branch_loss_weight)
               IF (density_full_direct_candidate_ready .AND. &
                   density_full_direct_expected_drop > EPSILON(density_full_direct_expected_drop) .AND. &
                   (dense_branch_expected_drop >= &
                    ot_kp_schur_projector_response_advantage_ratio*MAX(dense_expected_drop, &
                                                                       EPSILON(dense_expected_drop)) .OR. &
                    ((.NOT. projector_physical_direct_density_candidate_selected .OR. &
                      projector_physical_direct_density_residual_bad) .AND. &
                     .NOT. density_full_candidate_selected .AND. &
                     .NOT. density_full_global_candidate_selected .AND. &
                     qs_scf_kp_density_full_direct_tail_probe(residual_delta, density_full_direct_expected_drop, &
                                                              dense_expected_drop, &
                                                              local_ot_env(1)%schur_projector_density_full_direct_quality_ema, &
                                                              local_ot_env(1)%schur_projector_density_full_direct_quality_samples, &
                                                              local_ot_env(1)%schur_projector_density_fdir_sel_resid_quality, &
                                                              local_ot_env(1)%schur_projector_density_fdir_sel_resid_quality_ema, &
                                                              local_ot_env(1)%schur_projector_density_fdir_sel_quality_samples, &
                                                              local_ot_env(1)%kpoint_density_stationarity_ready .AND. &
                                                              local_ot_env(1)%kpoint_density_stationarity_delta > &
                                                              eps_scf_channel, &
                                                              dense_residual_quality)))) THEN
                  attempt_failed = .FALSE.
                  density_full_direct_candidate_selected = .TRUE.
                  density_full_candidate_selected = .FALSE.
                  density_descent_candidate_selected = .FALSE.
                  projector_physical_candidate_selected = .FALSE.
                  projector_physical_direct_candidate_selected = .FALSE.
                  projector_physical_direct_density_candidate_selected = .FALSE.
                  density_full_global_candidate_selected = .FALSE.
                  projector_response_candidate_selected = .FALSE.
                  z_e(:) = density_full_direct_direction_scale*z_density_full_trial(:)
                  sol(:) = density_full_direct_direction_scale*projector_physical_direct_sol(:)
                  direction_scale = density_full_direct_direction_scale
                  gdotp = density_full_direct_gdotp
                  gdot_energy = density_full_direct_gdot_energy
                  gdot_rotation = density_full_direct_gdot_rotation
                  norm_energy = density_full_direct_norm_energy
                  norm_rotation = density_full_direct_norm_rotation
                  normp = density_full_direct_normp
                  norm_ratio = density_full_direct_direction_scale*density_full_direct_direction_scale* &
                               normp/MAX(gnorm, EPSILON(1.0_dp))
                  scale_quality = density_full_direct_scale_quality
                  model_drop = density_full_direct_model_drop
                  model_calibrated_drop = density_full_direct_model_calibrated_drop
                  model_gap = 0.0_dp
                  model_gap_drop = 0.0_dp
                  model_gap_ratio = 0.0_dp
                  model_gap_trust = response_trust
                  response_abs_step = density_full_direct_response_abs_step
                  response_abs_trust_ratio = density_full_direct_response_abs_trust_ratio
                  response_weighted_step = density_full_direct_response_weighted_step
                  response_weighted_trust_ratio = density_full_direct_response_weighted_trust_ratio
                  mermin_branch_loss_gain = MAX(mermin_branch_loss_gain, &
                                                dense_branch_expected_drop - &
                                                density_full_direct_expected_drop)
                  dense_expected_drop = dense_branch_expected_drop
               END IF
               dense_branch_expected_drop = kpoint_ot_branch_loss_physical_drop( &
                                            projector_physical_expected_drop, &
                                            dense_expected_drop, mermin_branch_loss_weight)
               IF ((local_ot_env(1)%schur_projector_physical_candidate_enabled .OR. &
                    (projector_physical_direct_candidate_used .AND. &
                     (projector_physical_direct_promoted .OR. &
                      projector_physical_direct_mixed_enabled .OR. &
                      projector_physical_direct_tail_probe_ready))) .AND. &
                   projector_physical_candidate_ready .AND. &
                   projector_physical_expected_drop > EPSILON(projector_physical_expected_drop) .AND. &
                   (.NOT. (density_full_global_candidate_selected .AND. &
                           density_full_global_tail_prefer) .OR. &
                    dense_branch_expected_drop >= &
                    ot_kp_schur_projector_response_advantage_ratio* &
                    MAX(dense_expected_drop, EPSILON(dense_expected_drop))) .AND. &
                   (dense_branch_expected_drop >= &
                    ot_kp_schur_projector_response_advantage_ratio*MAX(dense_expected_drop, &
                                                                       EPSILON(dense_expected_drop)) .OR. &
                    (.NOT. projector_physical_direct_density_candidate_selected .AND. &
                     projector_physical_direct_candidate_used .AND. &
                     kpoint_ot_direct_tail_close_call( &
                     residual_delta, projector_physical_expected_drop, dense_expected_drop, &
                     projector_physical_direct_quality_for_selection, projector_physical_direct_promoted, &
                     projector_physical_direct_mixed_enabled, projector_physical_direct_tail_probe_ready, &
                     projector_physical_direct_response_weighted_trust_ratio, &
                     projector_physical_direct_response_abs_trust_ratio, &
                     projector_physical_direct_model_gap_ratio, dense_residual_quality)))) THEN
                  attempt_failed = .FALSE.
                  projector_physical_candidate_selected = .TRUE.
                  projector_physical_direct_candidate_selected = projector_physical_direct_candidate_used
                  projector_physical_direct_density_candidate_selected = .FALSE.
                  density_descent_candidate_selected = .FALSE.
                  density_full_candidate_selected = .FALSE.
                  density_full_direct_candidate_selected = .FALSE.
                  density_full_global_candidate_selected = .FALSE.
                  projector_response_candidate_selected = .FALSE.
                  z_e(:) = projector_physical_z_e(:)
                  sol(:) = projector_physical_sol(:)
                  direction_scale = projector_physical_direction_scale
                  gdotp = projector_physical_gdotp
                  gdot_energy = projector_physical_gdot_energy
                  gdot_rotation = projector_physical_gdot_rotation
                  norm_energy = projector_physical_norm_energy
                  norm_rotation = projector_physical_norm_rotation
                  normp = projector_physical_normp
                  norm_ratio = projector_physical_norm_ratio
                  scale_quality = projector_physical_scale_quality
                  model_drop = projector_physical_model_drop
                  model_calibrated_drop = projector_physical_model_calibrated_drop
                  model_gap = projector_physical_model_gap
                  model_gap_drop = projector_physical_model_gap_drop
                  model_gap_ratio = projector_physical_model_gap_ratio
                  model_gap_trust = projector_physical_model_gap_trust
                  response_abs_step = projector_physical_response_abs_step
                  response_abs_trust_ratio = projector_physical_response_abs_trust_ratio
                  response_weighted_step = projector_physical_response_weighted_step
                  response_weighted_trust_ratio = projector_physical_response_weighted_trust_ratio
                  IF (projector_physical_direct_candidate_selected) THEN
                     diag_shift_sum = projector_physical_direct_diag_shift_sum
                     diag_shift_max = projector_physical_direct_diag_shift_max
                     rot_floor_min = projector_physical_direct_rot_floor_min
                     schur_diag_min = projector_physical_direct_schur_diag_min
                  END IF
                  mermin_branch_loss_gain = MAX(mermin_branch_loss_gain, &
                                                dense_branch_expected_drop - &
                                                projector_physical_expected_drop)
                  dense_expected_drop = dense_branch_expected_drop
               END IF
               dense_branch_expected_drop = kpoint_ot_branch_loss_physical_drop( &
                                            projector_physical_direct_spectral_expected_drop, &
                                            dense_expected_drop, mermin_branch_loss_weight)
               IF (projector_physical_direct_spectral_candidate_ready .AND. &
                   projector_physical_direct_spectral_expected_drop > &
                   EPSILON(projector_physical_direct_spectral_expected_drop) .AND. &
                   kpoint_ot_projector_full_density_override_allowed( &
                   projector_physical_direct_spectral_expected_drop, density_full_candidate_ready, &
                   density_full_expected_drop, density_full_direct_candidate_ready, &
                   density_full_direct_expected_drop, density_full_global_candidate_ready, &
                   density_full_global_expected_drop) .AND. &
                   (.NOT. (density_full_global_candidate_selected .AND. &
                           density_full_global_tail_prefer) .OR. &
                    dense_branch_expected_drop >= &
                    ot_kp_schur_projector_response_advantage_ratio* &
                    MAX(dense_expected_drop, EPSILON(dense_expected_drop))) .AND. &
                   ((local_ot_env(1)%schur_projector_spectral_candidate_enabled .AND. &
                     dense_branch_expected_drop >= &
                     ot_kp_schur_projector_response_advantage_ratio* &
                     MAX(dense_expected_drop, EPSILON(dense_expected_drop))) .OR. &
                    projector_physical_direct_spectral_probe_ready)) THEN
                  attempt_failed = .FALSE.
                  projector_physical_direct_spectral_candidate_selected = .TRUE.
                  projector_physical_direct_spectral_probe_selected = &
                     projector_physical_direct_spectral_probe_ready .AND. &
                     .NOT. local_ot_env(1)%schur_projector_spectral_candidate_enabled
                  projector_physical_candidate_selected = .FALSE.
                  projector_physical_direct_candidate_selected = .FALSE.
                  projector_physical_direct_density_candidate_selected = .FALSE.
                  density_descent_candidate_selected = .FALSE.
                  density_full_candidate_selected = .FALSE.
                  density_full_direct_candidate_selected = .FALSE.
                  density_full_global_candidate_selected = .FALSE.
                  projector_response_candidate_selected = .FALSE.
                  z_e(:) = projector_physical_direct_spectral_direction_scale* &
                           projector_physical_direct_spectral_z_e(:)
                  sol(:) = projector_physical_direct_spectral_direction_scale* &
                           projector_physical_direct_spectral_sol(:)
                  direction_scale = projector_physical_direct_spectral_direction_scale
                  gdotp = projector_physical_direct_spectral_gdotp
                  gdot_energy = projector_physical_direct_spectral_gdot_energy
                  gdot_rotation = projector_physical_direct_spectral_gdot_rotation
                  norm_energy = projector_physical_direct_spectral_norm_energy
                  norm_rotation = projector_physical_direct_spectral_norm_rotation
                  normp = projector_physical_direct_spectral_normp
                  norm_ratio = projector_physical_direct_spectral_norm_ratio
                  scale_quality = projector_physical_direct_spectral_scale_quality
                  model_drop = projector_physical_direct_spectral_model_drop
                  model_calibrated_drop = projector_physical_direct_spectral_model_calibrated_drop
                  model_gap = projector_physical_direct_spectral_model_gap
                  model_gap_drop = projector_physical_direct_spectral_model_gap_drop
                  model_gap_ratio = projector_physical_direct_spectral_model_gap_ratio
                  model_gap_trust = projector_physical_direct_spectral_model_gap_trust
                  response_abs_step = projector_physical_direct_spectral_response_abs_step
                  response_abs_trust_ratio = projector_physical_direct_spectral_resp_atrust
                  response_weighted_step = projector_physical_direct_spectral_response_weighted_step
                  response_weighted_trust_ratio = &
                     projector_physical_direct_spectral_resp_wtrust
                  mermin_branch_loss_gain = MAX(mermin_branch_loss_gain, &
                                                dense_branch_expected_drop - &
                                                projector_physical_direct_spectral_expected_drop)
                  dense_expected_drop = dense_branch_expected_drop
               END IF
               dense_branch_expected_drop = kpoint_ot_branch_loss_physical_drop( &
                                            projector_offdiag_expected_drop, &
                                            dense_expected_drop, mermin_branch_loss_weight)
               IF (.NOT. attempt_failed .AND. &
                   projector_offdiag_candidate_ready .AND. &
                   projector_offdiag_expected_drop > EPSILON(projector_offdiag_expected_drop)) THEN
                  projector_offdiag_reference_drop = MAX(dense_expected_drop, EPSILON(dense_expected_drop))
                  projector_offdiag_expected_drop_ratio = &
                     dense_branch_expected_drop/projector_offdiag_reference_drop
                  IF (projector_offdiag_candidate_inactive) &
                     projector_inactive_offdiag_tail_refresh_probe = &
                     kpoint_ot_inactive_offdiag_tail_refresh_probe( &
                     projector_inactive_offdiag_tail_refresh_ready, &
                     dense_branch_expected_drop, projector_offdiag_reference_drop)
               END IF
               IF (.NOT. projector_physical_direct_candidate_selected .AND. &
                   .NOT. projector_physical_direct_spectral_candidate_selected .AND. &
                   projector_offdiag_candidate_ready .AND. &
                   projector_offdiag_expected_drop > EPSILON(projector_offdiag_expected_drop) .AND. &
                   (dense_branch_expected_drop >= &
                    projector_offdiag_model_advantage_ratio*MAX(dense_expected_drop, &
                                                                EPSILON(dense_expected_drop)) .OR. &
                    projector_inactive_offdiag_tail_refresh_probe)) THEN
                  attempt_failed = .FALSE.
                  projector_offdiag_candidate_selected = .TRUE.
                  projector_physical_candidate_selected = .FALSE.
                  projector_physical_direct_candidate_selected = .FALSE.
                  projector_physical_direct_density_candidate_selected = .FALSE.
                  density_descent_candidate_selected = .FALSE.
                  density_full_candidate_selected = .FALSE.
                  density_full_direct_candidate_selected = .FALSE.
                  density_full_global_candidate_selected = .FALSE.
                  projector_physical_direct_spectral_candidate_selected = .FALSE.
                  projector_physical_direct_spectral_probe_selected = .FALSE.
                  projector_response_candidate_selected = .FALSE.
                  z_e(:) = projector_offdiag_z_e(:)
                  sol(:) = projector_offdiag_sol(:)
                  direction_scale = projector_offdiag_direction_scale
                  gdotp = projector_offdiag_gdotp
                  gdot_energy = projector_offdiag_gdot_energy
                  gdot_rotation = projector_offdiag_gdot_rotation
                  norm_energy = projector_offdiag_norm_energy
                  norm_rotation = projector_offdiag_norm_rotation
                  normp = projector_offdiag_normp
                  norm_ratio = projector_offdiag_norm_ratio
                  scale_quality = projector_offdiag_scale_quality
                  model_drop = projector_offdiag_model_drop
                  model_calibrated_drop = projector_offdiag_model_calibrated_drop
                  model_gap = projector_offdiag_model_gap
                  model_gap_drop = projector_offdiag_model_gap_drop
                  model_gap_ratio = projector_offdiag_model_gap_ratio
                  model_gap_trust = projector_offdiag_model_gap_trust
                  response_abs_step = projector_offdiag_response_abs_step
                  response_abs_trust_ratio = projector_offdiag_response_abs_trust_ratio
                  response_weighted_step = projector_offdiag_response_weighted_step
                  response_weighted_trust_ratio = projector_offdiag_response_weighted_trust_ratio
                  mermin_branch_loss_gain = MAX(mermin_branch_loss_gain, &
                                                dense_branch_expected_drop - &
                                                projector_offdiag_expected_drop)
                  dense_expected_drop = dense_branch_expected_drop
               END IF
            END IF

            IF (schur_attempt == 3 .AND. prediction_update_ready .AND. &
                .NOT. attempt_failed) THEN
               CALL build_kpoint_ot_coupled_prediction_candidate( &
                  rot_hessian_prediction, reduced_response_metric, response_prediction, &
                  prediction_z_base, response_exact, grad_rot, grad_e, sol, &
                  occ_curv, tether_curv, occ_curv_projection_sum, channel_nmo, e_offset, &
                  rot_floor, curv, curv_projection_sum, response_trust, response_abs_trust, &
                  schur_model_gap_factor, var_step_weight, energy_step_weight, &
                  var_grad_metric_weight, energy_grad_metric_weight, max_norm_ratio, &
                  prediction_sol, prediction_z_e, prediction_direction_scale, &
                  prediction_model_slope, prediction_model_quadratic, prediction_model_drop, &
                  prediction_model_calibrated_drop, prediction_model_gap, prediction_model_gap_drop, &
                  prediction_model_gap_ratio, prediction_response_weighted_step, &
                  prediction_response_abs_step, prediction_candidate_residual_ratio, &
                  prediction_reference_residual_ratio, prediction_negative_scale, &
                  prediction_negative_gradient_fraction, prediction_candidate_ready)
               prediction_response_weighted_trust_ratio = 0.0_dp
               IF (response_trust > EPSILON(response_trust)) &
                  prediction_response_weighted_trust_ratio = &
                  prediction_response_weighted_step/response_trust
               prediction_response_abs_trust_ratio = 0.0_dp
               IF (response_abs_trust > EPSILON(response_abs_trust)) &
                  prediction_response_abs_trust_ratio = &
                  prediction_response_abs_step/response_abs_trust
               prediction_history_quality = kpoint_ot_schur_history_quality( &
                                            local_ot_env(1)%schur_prediction_drop_sum, &
                                            local_ot_env(1)%schur_prediction_measured_sum, &
                                            local_ot_env(1)%schur_prediction_quality_ema, &
                                            local_ot_env(1)%schur_prediction_quality_samples, &
                                            ot_kp_schur_calibration_min_samples, 1.0_dp, &
                                            ot_kp_schur_calibration_floor, 1.0_dp)
               prediction_trust_quality = kpoint_ot_schur_trust_quality( &
                                          prediction_response_weighted_trust_ratio, &
                                          prediction_response_abs_trust_ratio, &
                                          prediction_model_gap_ratio)
               prediction_expected_drop = kpoint_ot_schur_expected_drop( &
                                          prediction_model_calibrated_drop, &
                                          prediction_history_quality, prediction_trust_quality)
            END IF
            IF (schur_attempt == 3 .AND. logger%iter_info%print_level >= debug_print_level .AND. &
                logger%para_env%is_source()) &
               WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,2(1X,L1),16(1X,ES16.8))') &
               " OT Schur coupled-prediction direct candidate group eligible ready slope quad "// &
               "scale drop cdrop expected hq tq wtrust atrust gapratio validation_res "// &
               "candidate_res reference_res neg_scale neg_fraction:", &
               target_group, prediction_update_ready, prediction_candidate_ready, &
               prediction_model_slope, prediction_model_quadratic, prediction_direction_scale, &
               prediction_model_drop, prediction_model_calibrated_drop, prediction_expected_drop, &
               prediction_history_quality, prediction_trust_quality, &
               prediction_response_weighted_trust_ratio, prediction_response_abs_trust_ratio, &
               prediction_model_gap_ratio, prediction_predicted_residual_ratio, &
               prediction_candidate_residual_ratio, prediction_reference_residual_ratio, &
               prediction_negative_scale, prediction_negative_gradient_fraction

            IF (schur_attempt == 3 .AND. prediction_candidate_ready) THEN
               prediction_reference_drop = 0.0_dp
               IF (.NOT. attempt_failed) THEN
                  prediction_reference_drop = dense_expected_drop
                  IF (split_candidate_selected) prediction_reference_drop = split_expected_drop
               END IF
               prediction_probe_selected = qs_scf_kp_secant_bootstrap_probe( &
                                           local_ot_env(1)%schur_prediction_quality_samples, &
                                           .TRUE., prediction_trust_quality, &
                                           prediction_candidate_residual_ratio, &
                                           prediction_expected_drop, prediction_reference_drop)
               prediction_probe_selected = prediction_probe_selected .OR. &
                                           qs_scf_kp_secant_calibration_probe( &
                                           local_ot_env(1)%schur_prediction_quality_samples, &
                                           ot_kp_schur_calibration_min_samples, .TRUE., &
                                           local_ot_env(1)%schur_prediction_quality, &
                                           local_ot_env(1)%schur_prediction_quality_ema, &
                                           local_ot_env(1)%schur_prediction_residual_quality, &
                                           local_ot_env(1)%schur_prediction_residual_quality_ema, &
                                           prediction_trust_quality, &
                                           prediction_candidate_residual_ratio, &
                                           prediction_expected_drop, prediction_reference_drop, &
                                           ot_kp_schur_calibrated_quality_min_ratio)
               prediction_candidate_selected = &
                  prediction_expected_drop > EPSILON(prediction_expected_drop) .AND. &
                  (prediction_probe_selected .OR. &
                   (local_ot_env(1)%schur_prediction_candidate_enabled .AND. &
                    (attempt_failed .OR. prediction_expected_drop >= &
                     ot_kp_schur_projector_response_advantage_ratio* &
                     MAX(prediction_reference_drop, EPSILON(prediction_reference_drop)))))
               IF (prediction_candidate_selected) THEN
                  attempt_failed = .FALSE.
                  split_candidate_selected = .FALSE.
                  projector_coupled_weight = 0.0_dp
                  inactive_gauge_projection_used = .FALSE.
                  vector_secant_update_used = .FALSE.
                  multisecant_update_used = .FALSE.
                  prediction_update_used = .TRUE.
                  projector_offdiag_candidate_selected = .FALSE.
                  projector_physical_candidate_selected = .FALSE.
                  projector_physical_direct_candidate_selected = .FALSE.
                  projector_physical_direct_density_candidate_selected = .FALSE.
                  projector_physical_direct_spectral_candidate_selected = .FALSE.
                  projector_physical_direct_spectral_probe_selected = .FALSE.
                  projector_response_candidate_selected = .FALSE.
                  density_descent_candidate_selected = .FALSE.
                  density_full_candidate_selected = .FALSE.
                  density_full_direct_candidate_selected = .FALSE.
                  density_full_global_candidate_selected = .FALSE.
                  sol(:) = prediction_sol(:)
                  z_e(:) = prediction_z_e(:)
                  direction_scale = prediction_direction_scale
                  gdot_rotation = DOT_PRODUCT(grad_rot, sol)
                  gdot_energy = DOT_PRODUCT(grad_e, z_e)
                  gdotp = gdot_rotation + gdot_energy
                  norm_rotation = kpoint_ot_weighted_vector_dot(sol, sol, var_step_weight)
                  norm_energy = kpoint_ot_weighted_vector_dot(z_e, z_e, energy_step_weight)
                  normp = norm_rotation + norm_energy
                  gnorm = kpoint_ot_weighted_vector_dot( &
                          grad_e, grad_e, energy_grad_metric_weight) + &
                          kpoint_ot_weighted_vector_dot( &
                          grad_rot, grad_rot, var_grad_metric_weight)
                  norm_ratio = normp/MAX(gnorm, EPSILON(1.0_dp))
                  scale_quality = kpoint_ot_schur_scale_quality(direction_scale, &
                                                                schur_min_coupled_scale)
                  model_drop = prediction_model_drop
                  model_calibrated_drop = prediction_model_calibrated_drop
                  model_gap = prediction_model_gap
                  model_gap_drop = prediction_model_gap_drop
                  model_gap_ratio = prediction_model_gap_ratio
                  model_gap_trust = schur_model_gap_factor*response_trust
                  response_weighted_step = prediction_response_weighted_step
                  response_weighted_trust_ratio = &
                     prediction_response_weighted_trust_ratio
                  response_abs_step = prediction_response_abs_step
                  response_abs_trust_ratio = prediction_response_abs_trust_ratio
                  response_step_max = response_abs_step
                  dense_expected_drop = prediction_expected_drop
               END IF
               IF (logger%iter_info%print_level >= debug_print_level .AND. &
                   logger%para_env%is_source()) &
                  WRITE (cp_logger_get_default_unit_nr(logger), &
                         '(A,1X,I3,2(1X,L1),4(1X,ES16.8))') &
                  " OT Schur coupled-prediction independent selection group selected probe "// &
                  "expected reference ratio residual:", &
                  target_group, prediction_candidate_selected, prediction_probe_selected, &
                  prediction_expected_drop, prediction_reference_drop, &
                  prediction_expected_drop/ &
                  MAX(prediction_reference_drop, EPSILON(1.0_dp)), &
                  prediction_predicted_residual_ratio
            END IF

            IF (schur_attempt == 3 .AND. reduced_secant_candidate_enabled .AND. &
                .NOT. attempt_failed) THEN
               CALL build_kpoint_ot_reduced_secant_candidate( &
                  rot_hessian_reduced_secant, rot_hessian_multisecant, reduced_response_metric, &
                  reduced_secant_modes, reduced_secant_targets, var_physical_grad_metric_weight, &
                  var_step_weight, response_exact, response_exact_raw, &
                  grad_rot, grad_e, sol, z_e, &
                  gdotp, 2.0_dp*(gdotp - model_drop), model_calibrated_drop, &
                  occ_curv, tether_curv, occ_curv_projection_sum, channel_nmo, e_offset, &
                  rot_floor, curv, curv_projection_sum, response_trust, response_abs_trust, &
                  schur_model_gap_factor, reduced_secant_sol, reduced_secant_z_e, &
                  reduced_secant_direction_scale, reduced_secant_model_slope, &
                  reduced_secant_model_quadratic, reduced_secant_model_drop, &
                  reduced_secant_model_calibrated_drop, reduced_secant_model_gap, &
                  reduced_secant_model_gap_drop, reduced_secant_model_gap_ratio, &
                  reduced_secant_response_weighted_step, reduced_secant_response_abs_step, &
                  reduced_secant_predicted_residual_ratio, &
                  reduced_secant_reference_residual_ratio, &
                  reduced_secant_predicted_residual_start_sq, &
                  reduced_secant_predicted_residual_delta_dot, &
                  reduced_secant_predicted_residual_delta_sq, reduced_secant_measured_response, &
                  reduced_secant_candidate_ready, use_measured_response=.TRUE., &
                  full_rotation_gradient=full_grad_rot, &
                  full_rotation_targets=reduced_secant_full_targets, &
                  full_rotation_hessian=full_rot_hessian_coupled, &
                  full_rotation_residual_weight=full_var_physical_grad_metric_weight, &
                  full_rotation_index=var_full_index, &
                  replace_base_subspace=reduced_secant_replacement_eligible)
               reduced_secant_response_weighted_trust_ratio = 0.0_dp
               IF (response_trust > EPSILON(response_trust)) &
                  reduced_secant_response_weighted_trust_ratio = &
                  reduced_secant_response_weighted_step/response_trust
               reduced_secant_response_abs_trust_ratio = 0.0_dp
               IF (response_abs_trust > EPSILON(response_abs_trust)) &
                  reduced_secant_response_abs_trust_ratio = &
                  reduced_secant_response_abs_step/response_abs_trust
               reduced_secant_history_quality = kpoint_ot_schur_history_quality( &
                                                local_ot_env(1)%schur_reduced_secant_drop_sum, &
                                                local_ot_env(1)%schur_reduced_secant_measured_sum, &
                                                local_ot_env(1)%schur_reduced_secant_quality_ema, &
                                                local_ot_env(1)%schur_reduced_secant_quality_samples, &
                                                ot_kp_schur_calibration_min_samples, 1.0_dp, &
                                                ot_kp_schur_calibration_floor, 1.0_dp)
               reduced_secant_trust_quality = kpoint_ot_schur_trust_quality( &
                                              reduced_secant_response_weighted_trust_ratio, &
                                              reduced_secant_response_abs_trust_ratio, &
                                              reduced_secant_model_gap_ratio)
               reduced_secant_expected_drop = kpoint_ot_schur_expected_drop( &
                                              reduced_secant_model_calibrated_drop, &
                                              reduced_secant_history_quality, &
                                              reduced_secant_trust_quality)
            END IF
            IF (schur_attempt == 3 .AND. logger%iter_info%print_level >= debug_print_level .AND. &
                logger%para_env%is_source()) &
               WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,2(1X,L1),13(1X,ES16.8))') &
               " OT Schur reduced-secant affine candidate group enabled ready slope quad scale "// &
               "drop cdrop expected hq tq wtrust atrust gapratio residual reference_residual:", &
               target_group, reduced_secant_candidate_enabled, reduced_secant_candidate_ready, &
               reduced_secant_model_slope, reduced_secant_model_quadratic, &
               reduced_secant_direction_scale, reduced_secant_model_drop, &
               reduced_secant_model_calibrated_drop, reduced_secant_expected_drop, &
               reduced_secant_history_quality, reduced_secant_trust_quality, &
               reduced_secant_response_weighted_trust_ratio, &
               reduced_secant_response_abs_trust_ratio, reduced_secant_model_gap_ratio, &
               reduced_secant_predicted_residual_ratio, &
               reduced_secant_reference_residual_ratio

            IF (schur_attempt == 3 .AND. reduced_secant_candidate_ready) THEN
               reduced_secant_reference_drop = 0.0_dp
               IF (.NOT. attempt_failed) THEN
                  reduced_secant_reference_drop = dense_expected_drop
                  IF (split_candidate_selected) &
                     reduced_secant_reference_drop = split_expected_drop
               END IF
               reduced_secant_probe_selected = qs_scf_kp_secant_bootstrap_probe( &
                                               local_ot_env(1)%schur_reduced_secant_quality_samples, &
                                               reduced_secant_measured_response, &
                                               reduced_secant_trust_quality, &
                                               reduced_secant_predicted_residual_ratio, &
                                               reduced_secant_expected_drop, &
                                               reduced_secant_reference_drop)
               reduced_secant_probe_selected = reduced_secant_probe_selected .OR. &
                                               qs_scf_kp_secant_calibration_probe( &
                                               local_ot_env(1)%schur_reduced_secant_quality_samples, &
                                               ot_kp_schur_calibration_min_samples, reduced_secant_measured_response, &
                                               local_ot_env(1)%schur_reduced_secant_quality, &
                                               local_ot_env(1)%schur_reduced_secant_quality_ema, &
                                               local_ot_env(1)%schur_reduced_secant_residual_quality, &
                                               local_ot_env(1)%schur_reduced_secant_residual_quality_ema, &
                                               reduced_secant_trust_quality, reduced_secant_predicted_residual_ratio, &
                                               reduced_secant_expected_drop, reduced_secant_reference_drop, &
                                               ot_kp_schur_calibrated_quality_min_ratio)
               reduced_secant_candidate_selected = &
                  reduced_secant_expected_drop > EPSILON(reduced_secant_expected_drop) .AND. &
                  (reduced_secant_probe_selected .OR. &
                   (local_ot_env(1)%schur_reduced_secant_shadow_validated .AND. &
                    (attempt_failed .OR. reduced_secant_expected_drop >= &
                     ot_kp_schur_projector_response_advantage_ratio* &
                     MAX(reduced_secant_reference_drop, EPSILON(reduced_secant_reference_drop)))))
               IF (reduced_secant_candidate_selected) THEN
                  attempt_failed = .FALSE.
                  split_candidate_selected = .FALSE.
                  projector_coupled_weight = 0.0_dp
                  inactive_gauge_projection_used = .FALSE.
                  vector_secant_update_used = .FALSE.
                  multisecant_update_used = .FALSE.
                  prediction_update_used = .FALSE.
                  projector_offdiag_candidate_selected = .FALSE.
                  projector_physical_candidate_selected = .FALSE.
                  projector_physical_direct_candidate_selected = .FALSE.
                  projector_physical_direct_density_candidate_selected = .FALSE.
                  projector_physical_direct_spectral_candidate_selected = .FALSE.
                  projector_physical_direct_spectral_probe_selected = .FALSE.
                  projector_response_candidate_selected = .FALSE.
                  density_descent_candidate_selected = .FALSE.
                  density_full_candidate_selected = .FALSE.
                  density_full_direct_candidate_selected = .FALSE.
                  density_full_global_candidate_selected = .FALSE.
                  sol(:) = reduced_secant_sol(:)
                  z_e(:) = reduced_secant_z_e(:)
                  direction_scale = reduced_secant_direction_scale
                  gdot_rotation = DOT_PRODUCT(grad_rot, sol)
                  gdot_energy = DOT_PRODUCT(grad_e, z_e)
                  gdotp = gdot_rotation + gdot_energy
                  norm_rotation = kpoint_ot_weighted_vector_dot(sol, sol, var_step_weight)
                  norm_energy = kpoint_ot_weighted_vector_dot(z_e, z_e, energy_step_weight)
                  normp = norm_rotation + norm_energy
                  gnorm = kpoint_ot_weighted_vector_dot(grad_e, grad_e, energy_grad_metric_weight) + &
                          kpoint_ot_weighted_vector_dot(grad_rot, grad_rot, var_grad_metric_weight)
                  norm_ratio = normp/MAX(gnorm, EPSILON(1.0_dp))
                  scale_quality = kpoint_ot_schur_scale_quality(direction_scale, &
                                                                schur_min_coupled_scale)
                  model_drop = reduced_secant_model_drop
                  model_calibrated_drop = reduced_secant_model_calibrated_drop
                  model_gap = reduced_secant_model_gap
                  model_gap_drop = reduced_secant_model_gap_drop
                  model_gap_ratio = reduced_secant_model_gap_ratio
                  model_gap_trust = schur_model_gap_factor*response_trust
                  response_weighted_step = reduced_secant_response_weighted_step
                  response_weighted_trust_ratio = &
                     reduced_secant_response_weighted_trust_ratio
                  response_abs_step = reduced_secant_response_abs_step
                  response_abs_trust_ratio = reduced_secant_response_abs_trust_ratio
                  response_step_max = response_abs_step
                  dense_expected_drop = reduced_secant_expected_drop
               END IF
               IF (logger%iter_info%print_level >= debug_print_level .AND. &
                   logger%para_env%is_source()) &
                  WRITE (cp_logger_get_default_unit_nr(logger), &
                         '(A,1X,I3,2(1X,L1),4(1X,ES16.8))') &
                  " OT Schur reduced-secant independent selection group selected probe expected "// &
                  "reference ratio residual:", &
                  target_group, reduced_secant_candidate_selected, reduced_secant_probe_selected, &
                  reduced_secant_expected_drop, &
                  reduced_secant_reference_drop, reduced_secant_expected_drop/ &
                  MAX(reduced_secant_reference_drop, EPSILON(1.0_dp)), &
                  reduced_secant_predicted_residual_ratio
            END IF

            IF (schur_attempt == 3 .AND. closure_candidate_enabled .AND. &
                closure_response_subspace_ready .AND. .NOT. attempt_failed) THEN
               CALL build_kpoint_ot_reduced_secant_candidate( &
                  rot_hessian_closure_candidate, rot_hessian_closure_candidate, &
                  closure_response_metric, closure_response_steps, closure_response_targets, &
                  var_physical_grad_metric_weight, var_step_weight, response_physical_model, &
                  response_exact_raw, grad_rot, grad_e, sol, z_e, gdotp, &
                  2.0_dp*(gdotp - model_drop), model_calibrated_drop, occ_curv, tether_curv, &
                  occ_curv_projection_sum, channel_nmo, e_offset, rot_floor, curv, &
                  curv_projection_sum, response_trust, response_abs_trust, &
                  schur_model_gap_factor, closure_candidate_sol, closure_candidate_z_e, &
                  closure_candidate_direction_scale, closure_candidate_model_slope, &
                  closure_candidate_model_quadratic, closure_candidate_model_drop, &
                  closure_candidate_model_calibrated_drop, closure_candidate_model_gap, &
                  closure_candidate_model_gap_drop, closure_candidate_model_gap_ratio, &
                  closure_candidate_response_weighted_step, closure_candidate_response_abs_step, &
                  closure_candidate_predicted_residual_ratio, &
                  closure_candidate_reference_residual_ratio, &
                  closure_candidate_predicted_residual_start_sq, &
                  closure_candidate_predicted_residual_delta_dot, &
                  closure_candidate_predicted_residual_delta_sq, &
                  closure_candidate_measured_response, closure_candidate_ready, &
                  pareto_blend_with_base=.TRUE., &
                  base_blend_scale=closure_candidate_base_blend_scale, &
                  rebase_established_model=.TRUE., full_rotation_gradient=full_grad_rot, &
                  full_rotation_targets=reduced_secant_full_targets, &
                  full_rotation_modes=reduced_secant_modes, &
                  full_rotation_hessian=full_rot_hessian_coupled, &
                  full_rotation_residual_weight=full_var_physical_grad_metric_weight, &
                  full_rotation_index=var_full_index)
               closure_candidate_response_weighted_trust_ratio = 0.0_dp
               IF (response_trust > EPSILON(response_trust)) &
                  closure_candidate_response_weighted_trust_ratio = &
                  closure_candidate_response_weighted_step/response_trust
               closure_candidate_response_abs_trust_ratio = 0.0_dp
               IF (response_abs_trust > EPSILON(response_abs_trust)) &
                  closure_candidate_response_abs_trust_ratio = &
                  closure_candidate_response_abs_step/response_abs_trust
               closure_candidate_history_quality = kpoint_ot_schur_history_quality( &
                                                   local_ot_env(1)%schur_closure_candidate_drop_sum, &
                                                   local_ot_env(1)%schur_closure_candidate_measured_sum, &
                                                   local_ot_env(1)%schur_closure_candidate_quality_ema, &
                                                   local_ot_env(1)%schur_closure_candidate_quality_samples, &
                                                   ot_kp_schur_calibration_min_samples, 1.0_dp, &
                                                   ot_kp_schur_calibration_floor, 1.0_dp)
               closure_candidate_trust_quality = kpoint_ot_schur_trust_quality( &
                                                 closure_candidate_response_weighted_trust_ratio, &
                                                 closure_candidate_response_abs_trust_ratio, &
                                                 closure_candidate_model_gap_ratio)
               closure_candidate_expected_drop = kpoint_ot_schur_expected_drop( &
                                                 closure_candidate_model_calibrated_drop, &
                                                 closure_candidate_history_quality, &
                                                 closure_candidate_trust_quality)
            END IF
            IF (schur_attempt == 3 .AND. logger%iter_info%print_level >= debug_print_level .AND. &
                logger%para_env%is_source()) &
               WRITE (cp_logger_get_default_unit_nr(logger), &
                      '(A,1X,I3,3(1X,L1),14(1X,ES16.8))') &
               " OT Schur closure affine candidate group enabled subspace ready slope quad scale blend "// &
               "drop cdrop expected hq tq wtrust atrust gapratio residual reference_residual:", &
               target_group, closure_candidate_enabled, closure_response_subspace_ready, &
               closure_candidate_ready, closure_candidate_model_slope, &
               closure_candidate_model_quadratic, closure_candidate_direction_scale, &
               closure_candidate_base_blend_scale, &
               closure_candidate_model_drop, closure_candidate_model_calibrated_drop, &
               closure_candidate_expected_drop, closure_candidate_history_quality, &
               closure_candidate_trust_quality, closure_candidate_response_weighted_trust_ratio, &
               closure_candidate_response_abs_trust_ratio, closure_candidate_model_gap_ratio, &
               closure_candidate_predicted_residual_ratio, &
               closure_candidate_reference_residual_ratio

            IF (schur_attempt == 3 .AND. closure_candidate_ready) THEN
               closure_candidate_reference_drop = 0.0_dp
               IF (.NOT. attempt_failed) THEN
                  closure_candidate_reference_drop = dense_expected_drop
                  IF (split_candidate_selected) closure_candidate_reference_drop = split_expected_drop
               END IF
               closure_candidate_residual_advantage_resolved = &
                  qs_scf_kp_residual_advantage_resolved( &
                  closure_candidate_predicted_residual_ratio, &
                  closure_candidate_reference_residual_ratio, &
                  closure_response_residual_ratio)
               closure_candidate_probe_selected = qs_scf_kp_secant_bootstrap_probe( &
                                                  local_ot_env(1)% &
                                                  schur_closure_candidate_quality_samples, &
                                                  closure_response_subspace_ready, &
                                                  closure_candidate_trust_quality, &
                                                  closure_candidate_predicted_residual_ratio, &
                                                  closure_candidate_expected_drop, &
                                                  closure_candidate_reference_drop)
               closure_candidate_probe_selected = closure_candidate_probe_selected .OR. &
                                                  (local_ot_env(1)%schur_closure_candidate_residual_coverage >= &
                                                   ot_kp_schur_calibrated_quality_min_ratio .AND. &
                                                   local_ot_env(1)%schur_closure_candidate_residual_coverage_ema >= &
                                                   ot_kp_schur_calibrated_quality_min_ratio .AND. &
                                                   qs_scf_kp_secant_calibration_probe( &
                                                   local_ot_env(1)%schur_closure_candidate_quality_samples, &
                                                   ot_kp_schur_calibration_min_samples, closure_response_subspace_ready, &
                                                   local_ot_env(1)%schur_closure_candidate_quality, &
                                                   local_ot_env(1)%schur_closure_candidate_quality_ema, &
                                                   local_ot_env(1)%schur_closure_candidate_residual_quality, &
                                                   local_ot_env(1)%schur_closure_candidate_residual_quality_ema, &
                                                   closure_candidate_trust_quality, closure_candidate_predicted_residual_ratio, &
                                                   closure_candidate_expected_drop, closure_candidate_reference_drop, &
                                                   ot_kp_schur_calibrated_quality_min_ratio))
               closure_candidate_selected = &
                  closure_candidate_expected_drop > EPSILON(closure_candidate_expected_drop) .AND. &
                  closure_candidate_residual_advantage_resolved .AND. &
                  (closure_candidate_probe_selected .OR. &
                   (local_ot_env(1)%schur_closure_candidate_validated .AND. &
                    (attempt_failed .OR. closure_candidate_expected_drop >= &
                     ot_kp_schur_projector_response_advantage_ratio* &
                     MAX(closure_candidate_reference_drop, &
                         EPSILON(closure_candidate_reference_drop)))))
               IF (closure_candidate_selected) THEN
                  attempt_failed = .FALSE.
                  split_candidate_selected = .FALSE.
                  projector_coupled_weight = 0.0_dp
                  inactive_gauge_projection_used = .FALSE.
                  vector_secant_update_used = .FALSE.
                  multisecant_update_used = .FALSE.
                  prediction_update_used = .FALSE.
                  reduced_secant_candidate_selected = .FALSE.
                  projector_offdiag_candidate_selected = .FALSE.
                  projector_physical_candidate_selected = .FALSE.
                  projector_physical_direct_candidate_selected = .FALSE.
                  projector_physical_direct_density_candidate_selected = .FALSE.
                  projector_physical_direct_spectral_candidate_selected = .FALSE.
                  projector_physical_direct_spectral_probe_selected = .FALSE.
                  projector_response_candidate_selected = .FALSE.
                  density_descent_candidate_selected = .FALSE.
                  density_full_candidate_selected = .FALSE.
                  density_full_direct_candidate_selected = .FALSE.
                  density_full_global_candidate_selected = .FALSE.
                  sol(:) = closure_candidate_sol(:)
                  z_e(:) = closure_candidate_z_e(:)
                  direction_scale = closure_candidate_direction_scale
                  gdot_rotation = DOT_PRODUCT(grad_rot, sol)
                  gdot_energy = DOT_PRODUCT(grad_e, z_e)
                  gdotp = gdot_rotation + gdot_energy
                  norm_rotation = kpoint_ot_weighted_vector_dot(sol, sol, var_step_weight)
                  norm_energy = kpoint_ot_weighted_vector_dot(z_e, z_e, energy_step_weight)
                  normp = norm_rotation + norm_energy
                  gnorm = kpoint_ot_weighted_vector_dot( &
                          grad_e, grad_e, energy_grad_metric_weight) + &
                          kpoint_ot_weighted_vector_dot( &
                          grad_rot, grad_rot, var_grad_metric_weight)
                  norm_ratio = normp/MAX(gnorm, EPSILON(1.0_dp))
                  scale_quality = kpoint_ot_schur_scale_quality(direction_scale, &
                                                                schur_min_coupled_scale)
                  model_drop = closure_candidate_model_drop
                  model_calibrated_drop = closure_candidate_model_calibrated_drop
                  model_gap = closure_candidate_model_gap
                  model_gap_drop = closure_candidate_model_gap_drop
                  model_gap_ratio = closure_candidate_model_gap_ratio
                  model_gap_trust = schur_model_gap_factor*response_trust
                  response_weighted_step = closure_candidate_response_weighted_step
                  response_weighted_trust_ratio = &
                     closure_candidate_response_weighted_trust_ratio
                  response_abs_step = closure_candidate_response_abs_step
                  response_abs_trust_ratio = closure_candidate_response_abs_trust_ratio
                  response_step_max = response_abs_step
                  dense_expected_drop = closure_candidate_expected_drop
               END IF
               IF (logger%iter_info%print_level >= debug_print_level .AND. &
                   logger%para_env%is_source()) &
                  WRITE (cp_logger_get_default_unit_nr(logger), &
                         '(A,1X,I3,3(1X,L1),6(1X,ES16.8))') &
                  " OT Schur closure independent selection group selected probe resolved expected "// &
                  "reference ratio residual reference_residual uncertainty:", &
                  target_group, closure_candidate_selected, closure_candidate_probe_selected, &
                  closure_candidate_residual_advantage_resolved, &
                  closure_candidate_expected_drop, closure_candidate_reference_drop, &
                  closure_candidate_expected_drop/ &
                  MAX(closure_candidate_reference_drop, EPSILON(1.0_dp)), &
                  closure_candidate_predicted_residual_ratio, &
                  closure_candidate_reference_residual_ratio, closure_response_residual_ratio
            END IF

            ! A remaining canonical-density residual can be an auxiliary-energy closure problem
            ! either after the complete Mermin residual has converged or while the fixed-N energy
            ! gradient is the dominant physical block.  Solve that block in its own Hessian metric
            ! instead of shrinking it with the orbital Euclidean norm.  The resulting direction
            ! still passes through the ordinary Mermin line search and accepted residual closure.
            IF (schur_attempt == 3 .AND. logger%iter_info%print_level >= debug_print_level .AND. &
                logger%para_env%is_source()) &
               WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,4(1X,L1),3(1X,ES16.8))') &
               " OT Schur energy closure gate group ready new density_ready tail physical density eps:", &
               target_group, qs_scf_kp_energy_closure_ready( &
               new_search_point, local_ot_env(1)%kpoint_density_stationarity_ready, residual_delta, &
               local_ot_env(1)%kpoint_density_stationarity_delta, eps_scf_channel, &
               rot_grad_energy_norm, rot_grad_physical_norm, rot_grad_gauge_norm, &
               energy_closure_tail_ready, energy_occupation_plateau_ready), &
               new_search_point, local_ot_env(1)%kpoint_density_stationarity_ready, &
               energy_closure_tail_ready, residual_delta, &
               local_ot_env(1)%kpoint_density_stationarity_delta, eps_scf_channel
            IF (schur_attempt == 3 .AND. qs_scf_kp_energy_closure_ready( &
                new_search_point, local_ot_env(1)%kpoint_density_stationarity_ready, residual_delta, &
                local_ot_env(1)%kpoint_density_stationarity_delta, eps_scf_channel, &
                rot_grad_energy_norm, rot_grad_physical_norm, rot_grad_gauge_norm, &
                energy_closure_tail_ready, energy_occupation_plateau_ready)) THEN
               local_ot_env(:)%kpoint_energy_closure_attempted = .TRUE.
               energy_closure_competing_ready = .NOT. attempt_failed
               energy_closure_reference_drop = dense_expected_drop
               ! Solve the diagonal fixed-N occupation block in its physical
               ! susceptibility metric.  This is an independent closure
               ! candidate, not a replacement for the coupled base direction:
               ! the ordinary energy trust radius and Mermin line search still
               ! bound and accept the finite auxiliary-energy step.
               energy_curvature_floor = &
                  qs_scf_kp_energy_bootstrap_curvature_floor(total_curv_diag_max)
               z_trial(:) = 0.0_dp
               energy_active_occ_sum = 0.0_dp
               energy_active_shift = 0.0_dp
               DO ie = 1, ne
                  IF (curv(ie) <= EPSILON(curv(ie))) CYCLE
                  z_trial(ie) = grad_e(ie)/MAX(curv(ie), energy_curvature_floor)
                  energy_active_occ_sum = energy_active_occ_sum + occ_curv(ie)
                  energy_active_shift = energy_active_shift + occ_curv(ie)*z_trial(ie)
               END DO
               IF (.NOT. global_schur_replicated) &
                  CALL para_env_inter_kp%sum(energy_active_occ_sum)
               IF (.NOT. global_schur_replicated) &
                  CALL para_env_inter_kp%sum(energy_active_shift)
               IF (energy_active_occ_sum > EPSILON(energy_active_occ_sum)) THEN
                  energy_active_shift = energy_active_shift/energy_active_occ_sum
                  DO ie = 1, ne
                     IF (curv(ie) > EPSILON(curv(ie))) &
                        z_trial(ie) = z_trial(ie) - energy_active_shift
                  END DO
               ELSE
                  z_trial(:) = 0.0_dp
               END IF
               energy_closure_gdot_energy = DOT_PRODUCT(grad_e, z_trial)
               CALL kpoint_ot_mixed_projected_term(z_trial, z_trial, occ_curv, tether_curv, &
                                                   occ_curv_projection_sum, channel_nmo, e_offset, &
                                                   energy_closure_metric_norm_energy)
               energy_closure_metric_norm_energy = MAX(0.0_dp, energy_closure_metric_norm_energy)
               IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,4(1X,ES16.8))') &
                  " OT Schur energy closure raw group slope curvature max_step max_grad:", &
                  target_group, energy_closure_gdot_energy, energy_closure_metric_norm_energy, &
                  MAXVAL(ABS(z_trial)), MAXVAL(ABS(grad_e))
               IF (energy_closure_gdot_energy > EPSILON(energy_closure_gdot_energy) .AND. &
                   energy_closure_metric_norm_energy > EPSILON(energy_closure_metric_norm_energy)) THEN
                  energy_closure_direction_scale = &
                     MIN(1.0_dp, energy_closure_gdot_energy/energy_closure_metric_norm_energy)
                  energy_closure_gdot_energy = energy_closure_direction_scale*energy_closure_gdot_energy
                  energy_closure_metric_norm_energy = energy_closure_direction_scale**2* &
                                                      energy_closure_metric_norm_energy
                  energy_closure_model_drop = MAX(0.0_dp, energy_closure_gdot_energy - &
                                                  0.5_dp*energy_closure_metric_norm_energy)
                  energy_closure_candidate_selected = qs_scf_kp_energy_closure_preferred( &
                                                      energy_closure_model_drop, energy_closure_reference_drop, &
                                                      energy_closure_competing_ready)
                  IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
                     WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,2(1X,L1),5(1X,ES16.8))') &
                     " OT Schur energy closure model group selected competing slope curvature scale drop ref:", &
                     target_group, energy_closure_candidate_selected, &
                     energy_closure_competing_ready, energy_closure_gdot_energy, &
                     energy_closure_metric_norm_energy, energy_closure_direction_scale, &
                     energy_closure_model_drop, energy_closure_reference_drop
                  IF (energy_closure_candidate_selected) THEN
                     vector_secant_update_used = .FALSE.
                     multisecant_update_used = .FALSE.
                     prediction_update_used = .FALSE.
                     direction_scale = energy_closure_direction_scale
                     z_e(:) = direction_scale*z_trial(:)
                     gdot_energy = energy_closure_gdot_energy
                     dense_metric_norm_energy = energy_closure_metric_norm_energy
                     model_drop = energy_closure_model_drop
                     sol(:) = 0.0_dp
                     gdot_rotation = 0.0_dp
                     gdotp = gdot_energy
                     norm_energy = kpoint_ot_weighted_vector_dot(z_e, z_e, energy_step_weight)
                     norm_rotation = 0.0_dp
                     normp = norm_energy
                     gnorm = kpoint_ot_weighted_vector_dot(grad_e, grad_e, energy_grad_metric_weight) + &
                             kpoint_ot_weighted_vector_dot(grad_rot, grad_rot, var_grad_metric_weight)
                     norm_ratio = normp/MAX(gnorm, EPSILON(1.0_dp))
                     model_calibrated_drop = model_drop
                     model_gap = 0.0_dp
                     model_gap_drop = 0.0_dp
                     model_gap_ratio = 0.0_dp
                     model_gap_trust = response_trust
                     response_abs_step = 0.0_dp
                     response_abs_trust_ratio = 0.0_dp
                     response_weighted_step = 0.0_dp
                     response_weighted_trust_ratio = 0.0_dp
                     scale_quality = kpoint_ot_schur_scale_quality(direction_scale, schur_min_coupled_scale)
                     dense_expected_drop = model_drop
                     attempt_failed = .FALSE.
                     projector_offdiag_candidate_selected = .FALSE.
                     projector_physical_candidate_selected = .FALSE.
                     projector_physical_direct_candidate_selected = .FALSE.
                     projector_physical_direct_density_candidate_selected = .FALSE.
                     projector_physical_direct_spectral_candidate_selected = .FALSE.
                     projector_response_candidate_selected = .FALSE.
                     density_descent_candidate_selected = .FALSE.
                     density_full_candidate_selected = .FALSE.
                     density_full_direct_candidate_selected = .FALSE.
                     density_full_global_candidate_selected = .FALSE.
                  END IF
               END IF
            END IF

            IF (.NOT. attempt_failed) THEN
               solved = .TRUE.
               selected_attempt = schur_attempt
               IF (split_candidate_selected) selected_attempt = split_selected_attempt
               schur_used_attempt = selected_attempt
               selected_flavor = selected_attempt
               IF (.NOT. split_candidate_selected) THEN
                  IF (selected_attempt == 3) selected_flavor = 30
                  IF (selected_attempt == 3 .AND. inactive_gauge_projection_used) selected_flavor = 42
                  IF (selected_attempt == 3 .AND. vector_secant_update_used .AND. &
                      .NOT. inactive_gauge_projection_used) selected_flavor = 43
                  IF (selected_attempt == 3 .AND. multisecant_update_used .AND. &
                      .NOT. inactive_gauge_projection_used) selected_flavor = 44
                  IF (selected_attempt == 3 .AND. prediction_update_used .AND. &
                      .NOT. inactive_gauge_projection_used) selected_flavor = 47
                  IF (selected_attempt == 3 .AND. reduced_secant_candidate_selected) &
                     selected_flavor = 46
                  IF (selected_attempt == 3 .AND. closure_candidate_selected) &
                     selected_flavor = 48
                  ! Projector/density candidates are built by the exact-response
                  ! dense attempt and may be selected later while comparing
                  ! against the raw fallback.  Preserve their sub-flavor so the
                  ! accepted-step history and CG reset logic see the actual model.
                  IF (projector_response_candidate_selected) selected_flavor = 31
                  IF (projector_physical_direct_density_candidate_selected) selected_flavor = 32
                  IF (density_descent_candidate_selected) selected_flavor = 33
                  IF (density_full_candidate_selected) selected_flavor = 38
                  IF (density_full_direct_candidate_selected) selected_flavor = 39
                  IF (density_full_global_candidate_selected) selected_flavor = 40
                  IF (projector_physical_candidate_selected) selected_flavor = 34
                  IF (projector_physical_direct_candidate_selected) selected_flavor = 35
                  IF (projector_physical_direct_spectral_candidate_selected) selected_flavor = 36
                  IF (projector_offdiag_candidate_selected) selected_flavor = 37
                  IF (projector_offdiag_candidate_selected .AND. &
                      projector_offdiag_candidate_inactive) selected_flavor = 41
                  IF (energy_closure_candidate_selected) selected_flavor = 45
               END IF
               accepted_model_drop = model_drop
               accepted_model_calibrated_drop = model_calibrated_drop
               accepted_model_gap_ratio = model_gap_ratio
               accepted_dense_metric_shadow_drop = dense_metric_shadow_candidate_drop
               accepted_occgap_shadow_drop = occgap_shadow_drop
               accepted_occgap_shadow_gap_ratio = occgap_shadow_gap_ratio
               accepted_projector_coupled_weight = projector_coupled_weight
               accepted_z_e(:) = z_e(:)
               accepted_sol(:) = sol(:)
               closure_response_shadow_ready = .FALSE.
               closure_response_accepted_quad = 0.0_dp
               closure_response_baseline_quad = 0.0_dp
               closure_response_candidate_quad = 0.0_dp
               closure_response_accepted_drop = accepted_model_drop
               IF (closure_coupled_subspace_ready) THEN
                  closure_response_shadow_ready = .TRUE.
                  closure_response_reduced_quad = 0.0_dp
                  IF (closure_reduced_response_ready) &
                     closure_response_reduced_quad = &
                     kpoint_ot_symmetric_quad(rot_hessian_closure_reduced_response, accepted_sol)
                  closure_response_coupled_quad = &
                     kpoint_ot_symmetric_quad(rot_hessian_closure_coupled_response, accepted_sol)
                  closure_response_accepted_quad = closure_response_coupled_quad - &
                                                   closure_response_reduced_quad
                  CALL qs_scf_kp_closure_response_model_adjustments( &
                     closure_response_reduced_quad, closure_response_coupled_quad, &
                     closure_candidate_selected, closure_coupled_response_selected, &
                     closure_response_baseline_quad, closure_response_candidate_quad)
                  closure_response_accepted_drop = MAX(0.0_dp, accepted_model_drop - &
                                                       0.5_dp*closure_response_candidate_quad)
               END IF
               IF (logger%iter_info%print_level >= debug_print_level .AND. &
                   logger%para_env%is_source()) &
                  WRITE (cp_logger_get_default_unit_nr(logger), &
                         '(A,1X,I3,2(1X,L1),6(1X,ES16.8))') &
                  " OT Schur closure accepted-step shadow group ready density_selected base_drop "// &
                  "baseline_quad candidate_quad delta_quad candidate_drop ratio:", &
                  target_group, closure_response_shadow_ready, &
                  projector_physical_direct_density_candidate_selected, accepted_model_drop, &
                  closure_response_baseline_quad, closure_response_candidate_quad, &
                  closure_response_accepted_quad, closure_response_accepted_drop, &
                  closure_response_accepted_drop/MAX(accepted_model_drop, EPSILON(1.0_dp))
               closure_full_response_baseline_quad = 0.0_dp
               closure_full_response_candidate_quad = 0.0_dp
               closure_full_response_existing_quad = 0.0_dp
               closure_full_response_coupled_quad = 0.0_dp
               closure_full_response_rotation_quad = 0.0_dp
               closure_full_response_energy_quad = 0.0_dp
               closure_full_response_cross_quad = 0.0_dp
               closure_full_response_delta_quad = 0.0_dp
               closure_full_response_accepted_drop = accepted_model_drop
               IF (closure_coupled_response_ready) THEN
                  IF (closure_response_subspace_ready) &
                     closure_full_response_existing_quad = &
                     kpoint_ot_symmetric_quad(rot_hessian_closure_response, accepted_sol)
                  closure_full_response_coupled_quad = qs_scf_kp_coupled_response_quadratic( &
                                                       accepted_sol, accepted_z_e, &
                                                       closure_coupled_full_rotation_correction, &
                                                       closure_coupled_full_energy_correction, &
                                                       closure_coupled_full_cross_correction, &
                                                       closure_full_response_rotation_quad, &
                                                       closure_full_response_energy_quad, &
                                                       closure_full_response_cross_quad)
                  closure_full_response_delta_quad = closure_full_response_coupled_quad - &
                                                     closure_full_response_existing_quad
                  CALL qs_scf_kp_full_closure_response_model_adjustments( &
                     closure_full_response_existing_quad, closure_full_response_coupled_quad, &
                     closure_candidate_selected, closure_full_response_baseline_quad, &
                     closure_full_response_candidate_quad)
                  closure_full_response_accepted_drop = MAX(0.0_dp, accepted_model_drop - &
                                                            0.5_dp*closure_full_response_candidate_quad)
               END IF
               IF (logger%iter_info%print_level >= debug_print_level .AND. &
                   logger%para_env%is_source()) &
                  WRITE (cp_logger_get_default_unit_nr(logger), &
                         '(A,1X,I3,2(1X,L1),6(1X,ES16.8))') &
                  " OT Schur full closure accepted-step shadow group ready closure_selected base_drop "// &
                  "baseline_quad candidate_quad delta_quad candidate_drop ratio:", &
                  target_group, closure_coupled_response_ready, closure_candidate_selected, &
                  accepted_model_drop, closure_full_response_baseline_quad, &
                  closure_full_response_candidate_quad, closure_full_response_delta_quad, &
                  closure_full_response_accepted_drop, &
                  closure_full_response_accepted_drop/ &
                  MAX(accepted_model_drop, EPSILON(1.0_dp))
               IF (logger%iter_info%print_level >= debug_print_level .AND. &
                   logger%para_env%is_source() .AND. closure_coupled_response_ready) &
                  WRITE (cp_logger_get_default_unit_nr(logger), &
                         '(A,1X,I3,5(1X,ES16.8))') &
                  " OT Schur full closure step components group rotation energy cross sum existing:", &
                  target_group, closure_full_response_rotation_quad, &
                  closure_full_response_energy_quad, closure_full_response_cross_quad, &
                  closure_full_response_coupled_quad, closure_full_response_existing_quad
               closure_predictive_response_active_quad = 0.0_dp
               closure_predictive_response_adjustment = 0.0_dp
               closure_predictive_response_baseline_adjustment = 0.0_dp
               closure_predictive_response_rotation_quad = 0.0_dp
               closure_predictive_response_energy_quad = 0.0_dp
               closure_predictive_response_cross_quad = 0.0_dp
               closure_predictive_response_quad = 0.0_dp
               closure_predictive_response_accepted_drop = accepted_model_drop
               IF (closure_coupled_predictive_finite) THEN
                  IF (closure_candidate_selected .AND. closure_response_subspace_ready) &
                     closure_predictive_response_active_quad = &
                     kpoint_ot_symmetric_quad(rot_hessian_closure_response, accepted_sol)
                  closure_predictive_response_quad = qs_scf_kp_coupled_response_quadratic( &
                                                     accepted_sol, accepted_z_e, &
                                                     closure_coupled_predictive_rotation_correction, &
                                                     closure_coupled_predictive_energy_correction, &
                                                     closure_coupled_predictive_cross_correction, &
                                                     closure_predictive_response_rotation_quad, &
                                                     closure_predictive_response_energy_quad, &
                                                     closure_predictive_response_cross_quad)
                  CALL qs_scf_kp_full_closure_response_model_adjustments( &
                     closure_predictive_response_active_quad, closure_predictive_response_quad, &
                     closure_candidate_selected, closure_predictive_response_baseline_adjustment, &
                     closure_predictive_response_adjustment)
                  closure_predictive_response_accepted_drop = MAX( &
                                                        0.0_dp, accepted_model_drop - 0.5_dp*closure_predictive_response_adjustment)
               END IF
               IF (logger%iter_info%print_level >= debug_print_level .AND. &
                   logger%para_env%is_source()) &
                  WRITE (cp_logger_get_default_unit_nr(logger), &
                         '(A,1X,I3,2(1X,L1),9(1X,ES16.8))') &
                  " OT Schur residual-H accepted-step group finite consistent base_drop "// &
                  "rotation energy cross sum active adjustment candidate_drop ratio:", &
                  target_group, closure_coupled_predictive_finite, &
                  closure_coupled_predictive_consistent, accepted_model_drop, &
                  closure_predictive_response_rotation_quad, &
                  closure_predictive_response_energy_quad, closure_predictive_response_cross_quad, &
                  closure_predictive_response_quad, closure_predictive_response_active_quad, &
                  closure_predictive_response_adjustment, closure_predictive_response_accepted_drop, &
                  closure_predictive_response_accepted_drop/ &
                  MAX(accepted_model_drop, EPSILON(1.0_dp))
               IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) THEN
                  accepted_pair_var = 0
                  accepted_pair_re_var = 0
                  accepted_pair_im_var = 0
                  accepted_pair_residual = 0.0_dp
                  DO r = 1, nrot
                     IF (var_kind(r) /= 1) CYCLE
                     IF (channel_density_pair_residual(var_i(r), var_j(r), var_channel(r)) > &
                         accepted_pair_residual) THEN
                        accepted_pair_residual = &
                           channel_density_pair_residual(var_i(r), var_j(r), var_channel(r))
                        accepted_pair_var = r
                        accepted_pair_re_var = r
                     END IF
                  END DO
                  IF (accepted_pair_var > 0) THEN
                     DO r = 1, nrot
                        IF (var_kind(r) == 2 .AND. &
                            var_channel(r) == var_channel(accepted_pair_var) .AND. &
                            var_i(r) == var_i(accepted_pair_var) .AND. &
                            var_j(r) == var_j(accepted_pair_var)) THEN
                           accepted_pair_im_var = r
                           EXIT
                        END IF
                     END DO
                     WRITE (cp_logger_get_default_unit_nr(logger), &
                            '(A,1X,I3,4(1X,I8),1X,ES16.8)') &
                        " OT Schur accepted density-pair group flavor channel i j residual:", &
                        target_group, selected_flavor, var_channel(accepted_pair_var), &
                        var_i(accepted_pair_var), var_j(accepted_pair_var), accepted_pair_residual
                     DO r = accepted_pair_re_var, accepted_pair_im_var, &
                        MAX(1, accepted_pair_im_var - accepted_pair_re_var)
                        WRITE (cp_logger_get_default_unit_nr(logger), &
                               '(A,2(1X,I8),8(1X,ES16.8))') &
                           " OT Schur accepted density coord kind var grad step tangent trial hb hc hs hp:", &
                           var_kind(r), r, grad_rot(r), accepted_sol(r), canonical_density_tangent(r), &
                           canonical_density_trial_sol(r), rot_hessian(r, r), rot_hessian_coupled(r, r), &
                           schur(r, r), projector_physical_direct_delta(r, r)
                     END DO
                  END IF
               END IF
               IF (reduced_secant_update_eligible) THEN
                  reduced_secant_response_step(:) = MATMUL(response_exact, accepted_sol)
                  CALL project_kpoint_ot_schur_response( &
                     reduced_secant_response_step, occ_curv, tether_curv, occ_curv_projection_sum, &
                     channel_nmo, e_offset)
                  CALL evaluate_kpoint_ot_projected_coupled_step_model( &
                     grad_rot, grad_e, rot_hessian_reduced_secant, accepted_sol, accepted_z_e, &
                     reduced_secant_response_step, occ_curv, tether_curv, &
                     occ_curv_projection_sum, channel_nmo, e_offset, &
                     accepted_reduced_secant_shadow_slope, &
                     accepted_reduced_secant_shadow_quadratic, &
                     accepted_reduced_secant_shadow_drop, &
                     accepted_reduced_secant_shadow_ready)
                  accepted_reduced_secant_shadow_ratio = 0.0_dp
                  IF (accepted_model_calibrated_drop > EPSILON(accepted_model_calibrated_drop)) &
                     accepted_reduced_secant_shadow_ratio = &
                     accepted_reduced_secant_shadow_drop/accepted_model_calibrated_drop
                  IF (logger%iter_info%print_level >= debug_print_level .AND. &
                      logger%para_env%is_source()) &
                     WRITE (cp_logger_get_default_unit_nr(logger), &
                            '(A,1X,I3,2(1X,L1),4(1X,ES16.8))') &
                     " OT Schur reduced-secant accepted-step shadow group ready validated slope quad drop ratio:", &
                     target_group, accepted_reduced_secant_shadow_ready, &
                     local_ot_env(1)%schur_reduced_secant_shadow_validated, &
                     accepted_reduced_secant_shadow_slope, &
                     accepted_reduced_secant_shadow_quadratic, &
                     accepted_reduced_secant_shadow_drop, &
                     accepted_reduced_secant_shadow_ratio
               END IF
               orbital_schur_step_quad = &
                  DOT_PRODUCT(sol, MATMUL(rot_hessian_orbital_schur, sol))
               orbital_schur_drop_ratio = 0.0_dp
               IF (model_calibrated_drop > EPSILON(model_calibrated_drop)) &
                  orbital_schur_drop_ratio = 0.5_dp*orbital_schur_step_quad/model_calibrated_drop
               IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,3(1X,ES16.8))') &
                  " OT Schur orbital-complement accepted shadow group quad add_drop ratio:", &
                  target_group, orbital_schur_step_quad, 0.5_dp*orbital_schur_step_quad, &
                  orbital_schur_drop_ratio
               IF (split_candidate_selected) accepted_projector_coupled_weight = 1.0_dp
               IF (logger%iter_info%print_level >= debug_print_level .OR. projector_physical_shadow_enabled .OR. &
                   projector_plateau_gap_model_enabled) THEN
                  CALL audit_kpoint_ot_hessian_delta_modes(rot_hessian_projector_physical_offdiag_active, sol, &
                                                           model_calibrated_drop, &
                                                           projector_physical_offdiag_mode_negative_fraction, &
                                                           projector_physical_offdiag_mode_eval_min, &
                                                           projector_physical_offdiag_mode_eval_max, &
                                                           projector_physical_offdiag_mode_step_negative_fraction, &
                                                           projector_physical_offdiag_mode_quad, &
                                                           projector_physical_offdiag_mode_abs_quad, &
                                                           projector_physical_offdiag_mode_positive_quad, &
                                                           projector_physical_offdiag_mode_negative_quad, &
                                                           projector_physical_offdiag_mode_quad_signed_ratio, &
                                                           projector_physical_offdiag_mode_quad_abs_ratio, &
                                                           step_metric_weight=var_step_weight)
                  CALL audit_kpoint_ot_hessian_delta_modes( &
                     rot_hessian_projector_physical_offdiag_plateau_active - &
                     rot_hessian_projector_physical_offdiag_active, sol, model_calibrated_drop, &
                     plateau_gap_mode_negative_fraction, &
                     plateau_gap_mode_eval_min, &
                     plateau_gap_mode_eval_max, &
                     plateau_gap_mode_step_negative_fraction, &
                     plateau_gap_mode_quad, &
                     plateau_gap_mode_abs_quad, &
                     plateau_gap_mode_positive_quad, &
                     plateau_gap_mode_negative_quad, &
                     plateau_gap_mode_quad_signed_ratio, &
                     plateau_gap_mode_quad_abs_ratio, &
                     step_metric_weight=var_step_weight)
                  CALL audit_kpoint_ot_hessian_delta_modes( &
                     rot_hessian_projector_physical_offdiag - &
                     rot_hessian_projector_physical_offdiag_active, sol, model_calibrated_drop, &
                     inactive_offdiag_mode_negative_fraction, &
                     inactive_offdiag_mode_eval_min, &
                     inactive_offdiag_mode_eval_max, &
                     inactive_offdiag_mode_step_negative_fraction, &
                     inactive_offdiag_mode_quad, &
                     inactive_offdiag_mode_abs_quad, &
                     inactive_offdiag_mode_positive_quad, &
                     inactive_offdiag_mode_negative_quad, &
                     inactive_offdiag_mode_quad_signed_ratio, &
                     inactive_offdiag_mode_quad_abs_ratio, &
                     step_metric_weight=var_step_weight)
               END IF
               IF (projector_physical_shadow_enabled .AND. &
                   projector_physical_offdiag_mode_abs_quad > &
                   EPSILON(projector_physical_offdiag_mode_abs_quad)) THEN
                  accepted_projector_offdiag_drop = 0.5_dp*projector_physical_offdiag_mode_abs_quad
                  accepted_projector_offdiag_signed_ratio = &
                     projector_physical_offdiag_mode_quad_signed_ratio
                  accepted_projector_offdiag_abs_ratio = &
                     projector_physical_offdiag_mode_quad_abs_ratio
                  accepted_projector_offdiag_negative = &
                     projector_physical_offdiag_mode_negative_fraction
                  accepted_projector_offdiag_step_negative = &
                     projector_physical_offdiag_mode_step_negative_fraction
               END IF
               IF (projector_physical_shadow_enabled .AND. inactive_offdiag_mode_abs_quad > &
                   EPSILON(inactive_offdiag_mode_abs_quad)) THEN
                  accepted_projector_inactive_offdiag_drop = 0.5_dp*inactive_offdiag_mode_abs_quad
                  accepted_projector_inactive_offdiag_signed_ratio = inactive_offdiag_mode_quad_signed_ratio
                  accepted_projector_inactive_offdiag_abs_ratio = inactive_offdiag_mode_quad_abs_ratio
                  accepted_projector_inactive_offdiag_negative = inactive_offdiag_mode_negative_fraction
                  accepted_projector_inactive_offdiag_step_negative = &
                     inactive_offdiag_mode_step_negative_fraction
               END IF
               IF (selected_attempt == 3 .AND. projector_coupled_weight > 0.0_dp .AND. &
                   (projector_mode_response_drop > 0.0_dp .OR. &
                    projector_mode_response_drop_ratio > 0.0_dp)) THEN
                  accepted_projector_mode_drop = model_calibrated_drop
                  accepted_projector_mode_response_drop = projector_mode_response_drop
                  accepted_projector_mode_response_negative_fraction = projector_mode_response_negative_fraction
                  accepted_projector_mode_step_negative_fraction = projector_mode_step_negative_fraction
                  accepted_projector_mode_trust_quality = projector_mode_trust_quality
               END IF
               IF (selected_attempt == 3 .AND. projector_response_candidate_ready .AND. &
                   .NOT. projector_physical_candidate_selected .AND. &
                   .NOT. projector_offdiag_candidate_selected .AND. &
                   projector_response_model_calibrated_drop > EPSILON(projector_response_model_calibrated_drop)) THEN
                  accepted_projector_response_drop = projector_response_model_calibrated_drop
                  accepted_projector_response_weight = projector_mode_response_weight
                  accepted_projector_response_negative = projector_mode_response_correction_negative
               END IF
               IF (projector_plateau_gap_model_enabled) THEN
                  accepted_projector_plateau_gap_quadratic = plateau_gap_mode_quad
                  IF (ABS(accepted_projector_plateau_gap_quadratic) > &
                      64.0_dp*EPSILON(MAX(1.0_dp, plateau_gap_mode_abs_quad))) THEN
                     accepted_projector_plateau_gap_weight = &
                        MAX(direct_pg_response_weight, MIN(1.0_dp, MAX(0.0_dp, &
                                                                       plateau_gap_mode_quad_abs_ratio)))
                     accepted_projector_plateau_gap_negative = &
                        MAX(direct_pg_raw_negative_fraction, plateau_gap_mode_negative_fraction)
                     accepted_projector_plateau_gap_step = &
                        MAX(direct_pg_metric_step, plateau_gap_mode_step_negative_fraction)
                  END IF
               END IF
               EXIT
            END IF
         END DO
         failed = .NOT. solved

         IF (new_search_point .AND. accepted_model_drop > EPSILON(accepted_model_drop)) THEN
            IF (.NOT. local_ot_env(1)%schur_model_pending) THEN
               local_ot_env(1)%schur_model_attempt = schur_used_attempt
               local_ot_env(1)%schur_model_flavor = selected_flavor
            ELSE IF (local_ot_env(1)%schur_model_attempt /= schur_used_attempt) THEN
               local_ot_env(1)%schur_model_attempt = -1
               local_ot_env(1)%schur_model_flavor = -1
            ELSE IF (local_ot_env(1)%schur_model_flavor /= selected_flavor) THEN
               local_ot_env(1)%schur_model_flavor = -1
            END IF
            local_ot_env(1)%schur_model_pending = .TRUE.
            local_ot_env(1)%schur_model_drop = local_ot_env(1)%schur_model_drop + accepted_model_drop
            local_ot_env(1)%schur_model_calibrated_drop = &
               local_ot_env(1)%schur_model_calibrated_drop + accepted_model_calibrated_drop
            local_ot_env(1)%schur_model_slope = local_ot_env(1)%schur_model_slope + &
                                                DOT_PRODUCT(grad_rot, accepted_sol) + &
                                                DOT_PRODUCT(grad_e, accepted_z_e)
            local_ot_env(1)%schur_model_quadratic = local_ot_env(1)%schur_model_quadratic + &
                                                    2.0_dp*(DOT_PRODUCT(grad_rot, accepted_sol) + &
                                                            DOT_PRODUCT(grad_e, accepted_z_e) - accepted_model_drop)
            IF (closure_response_shadow_ready .AND. &
                ABS(closure_response_candidate_quad - closure_response_baseline_quad) > &
                TINY(1.0_dp)) THEN
               local_ot_env(1)%schur_closure_shadow_pending = .TRUE.
               local_ot_env(1)%schur_closure_shadow_baseline_quadratic = &
                  local_ot_env(1)%schur_closure_shadow_baseline_quadratic + &
                  closure_response_baseline_quad
               local_ot_env(1)%schur_closure_shadow_quadratic = &
                  local_ot_env(1)%schur_closure_shadow_quadratic + &
                  closure_response_candidate_quad
            END IF
            IF (closure_coupled_response_ready .AND. &
                ABS(closure_full_response_candidate_quad - closure_full_response_baseline_quad) > &
                TINY(1.0_dp)) THEN
               local_ot_env(1)%schur_closure_full_shadow_pending = .TRUE.
               local_ot_env(1)%schur_closure_full_shadow_baseline_quadratic = &
                  local_ot_env(1)%schur_closure_full_shadow_baseline_quadratic + &
                  closure_full_response_baseline_quad
               local_ot_env(1)%schur_closure_full_shadow_quadratic = &
                  local_ot_env(1)%schur_closure_full_shadow_quadratic + &
                  closure_full_response_candidate_quad
            END IF
            IF (closure_coupled_predictive_finite .AND. &
                ABS(closure_predictive_response_adjustment - &
                    closure_predictive_response_baseline_adjustment) > TINY(1.0_dp)) THEN
               IF (.NOT. local_ot_env(1)%schur_closure_vector_shadow_pending) THEN
