               rx_model(:) = MATMUL(response_exact_active, accepted_sol) + &
                             MATMUL(response_density_basis_selective_audit_exact, accepted_sol)
               CALL project_kpoint_ot_schur_response(rx_e, occ_curv, tether_curv, &
                                                     occ_curv_projection_sum, channel_nmo, e_offset)
               CALL project_kpoint_ot_schur_response(rx_model, occ_curv, tether_curv, &
                                                     occ_curv_projection_sum, channel_nmo, e_offset)
               density_basis_selective_history_gap_drop = &
                  kpoint_ot_response_mismatch_drop(rx_e, rx_model, curv, 1.0_dp)
               density_basis_selective_history_drop = &
                  MAX(0.0_dp, accepted_model_calibrated_drop - density_basis_selective_history_gap_drop)
               density_basis_selective_history_abs_step = MAXVAL(ABS(rx_model))
               IF (.NOT. global_schur_replicated) &
                  CALL para_env_inter_kp%max(density_basis_selective_history_abs_step)
               density_basis_selective_history_weighted_step = &
                  kpoint_ot_weighted_response_step(rx_model, curv, curv_projection_sum)
               IF (response_trust > EPSILON(response_trust)) &
                  density_basis_selective_history_weighted_trust_ratio = &
                  density_basis_selective_history_weighted_step/response_trust
               IF (response_abs_trust > EPSILON(response_abs_trust)) &
                  density_basis_selective_history_abs_trust_ratio = &
                  density_basis_selective_history_abs_step/response_abs_trust
               density_basis_selective_history_trust_quality = &
                  kpoint_ot_schur_trust_quality(density_basis_selective_history_weighted_trust_ratio, &
                                                density_basis_selective_history_abs_trust_ratio, 0.0_dp)
               density_basis_selective_history_quality = 0.0_dp
               IF (accepted_model_calibrated_drop > EPSILON(accepted_model_calibrated_drop)) &
                  density_basis_selective_history_quality = &
                  density_basis_selective_history_drop/accepted_model_calibrated_drop
            END IF
            IF (projector_density_full_audit_enabled .AND. exact_physical_response_ready .AND. &
                exact_density_basis_filtered_audit_ready .AND. &
                accepted_model_calibrated_drop > ot_kp_schur_projector_density_full_min_drop) THEN
               rx_e(:) = accepted_z_e(:) - z_exact_physical_trial(:)
               rx_model(:) = MATMUL(response_exact_active, accepted_sol) + &
                             MATMUL(response_density_basis_filtered_audit_exact, accepted_sol)
               CALL project_kpoint_ot_schur_response(rx_e, occ_curv, tether_curv, &
                                                     occ_curv_projection_sum, channel_nmo, e_offset)
               CALL project_kpoint_ot_schur_response(rx_model, occ_curv, tether_curv, &
                                                     occ_curv_projection_sum, channel_nmo, e_offset)
               density_basis_filtered_history_gap_drop = &
                  kpoint_ot_response_mismatch_drop(rx_e, rx_model, curv, 1.0_dp)
               density_basis_filtered_history_drop = &
                  MAX(0.0_dp, accepted_model_calibrated_drop - density_basis_filtered_history_gap_drop)
               density_basis_filtered_history_abs_step = MAXVAL(ABS(rx_model))
               IF (.NOT. global_schur_replicated) &
                  CALL para_env_inter_kp%max(density_basis_filtered_history_abs_step)
               density_basis_filtered_history_weighted_step = &
                  kpoint_ot_weighted_response_step(rx_model, curv, curv_projection_sum)
               IF (response_trust > EPSILON(response_trust)) &
                  density_basis_filtered_history_weighted_trust_ratio = &
                  density_basis_filtered_history_weighted_step/response_trust
               IF (response_abs_trust > EPSILON(response_abs_trust)) &
                  density_basis_filtered_history_abs_trust_ratio = &
                  density_basis_filtered_history_abs_step/response_abs_trust
               density_basis_filtered_history_trust_quality = &
                  kpoint_ot_schur_trust_quality(density_basis_filtered_history_weighted_trust_ratio, &
                                                density_basis_filtered_history_abs_trust_ratio, 0.0_dp)
               density_basis_filtered_history_quality = 0.0_dp
               IF (accepted_model_calibrated_drop > EPSILON(accepted_model_calibrated_drop)) &
                  density_basis_filtered_history_quality = &
                  density_basis_filtered_history_drop/accepted_model_calibrated_drop
               ! Calibrate the filtered fixed-N source against the accepted step
               ! before applying the conservative source blend.  Scaling this
               ! history drop by the tiny blend weight makes the source look like
               ! a pathological under-predictor and prevents the physical
               ! response signal from ever being promoted in the metallic tail.
               projector_physical_direct_density_fshadow_history_drop = &
                  kpoint_ot_physical_direct_density_filtered_shadow_drop( &
                  1.0_dp, density_basis_filtered_history_drop, &
                  density_basis_filtered_history_trust_quality)
               IF (projector_physical_direct_density_fshadow_history_drop > &
                   EPSILON(projector_physical_direct_density_fshadow_history_drop)) THEN
                  local_ot_env(1)%schur_projector_phys_direct_density_fshadow = &
                     local_ot_env(1)%schur_projector_phys_direct_density_fshadow + &
                     projector_physical_direct_density_fshadow_history_drop
               END IF
            END IF
            IF (projector_density_full_audit_enabled .AND. exact_physical_response_ready .AND. &
                exact_density_basis_damped_audit_ready .AND. &
                accepted_model_calibrated_drop > ot_kp_schur_projector_density_full_min_drop) THEN
               rx_e(:) = accepted_z_e(:) - z_exact_physical_trial(:)
               rx_model(:) = MATMUL(response_exact_active, accepted_sol) + &
