               CALL project_kpoint_ot_schur_response(rx_model, occ_curv, tether_curv, &
                                                     occ_curv_projection_sum, channel_nmo, e_offset)
               density_basis_damped_history_gap_drop = &
                  kpoint_ot_response_mismatch_drop(rx_e, rx_model, curv, 1.0_dp)
               density_basis_damped_history_drop = &
                  MAX(0.0_dp, accepted_model_calibrated_drop - density_basis_damped_history_gap_drop)
               density_basis_damped_history_abs_step = MAXVAL(ABS(rx_model))
               IF (.NOT. global_schur_replicated) &
                  CALL para_env_inter_kp%max(density_basis_damped_history_abs_step)
               density_basis_damped_history_weighted_step = &
                  kpoint_ot_weighted_response_step(rx_model, curv, curv_projection_sum)
               IF (response_trust > EPSILON(response_trust)) &
                  density_basis_damped_history_weighted_trust_ratio = &
                  density_basis_damped_history_weighted_step/response_trust
               IF (response_abs_trust > EPSILON(response_abs_trust)) &
                  density_basis_damped_history_abs_trust_ratio = &
                  density_basis_damped_history_abs_step/response_abs_trust
               density_basis_damped_history_trust_quality = &
                  kpoint_ot_schur_trust_quality(density_basis_damped_history_weighted_trust_ratio, &
