               density_basis_damped_history_quality = 0.0_dp
               IF (accepted_model_calibrated_drop > EPSILON(accepted_model_calibrated_drop)) &
                  density_basis_damped_history_quality = &
                  density_basis_damped_history_drop/accepted_model_calibrated_drop
            END IF
            IF (exact_physical_response_ready .AND. exact_density_full_response_ready .AND. &
