                  local_ot_env(1)%schur_projector_density_fdir_selected + &
                  MIN(1.0_dp, MAX(0.0_dp, density_full_direct_history_trust_quality))* &
                  density_full_direct_history_drop
            END IF
            IF (exact_density_response_ready) THEN
