               local_ot_env(1)%schur_projector_density_audit_lowcurv = &
                  MAX(local_ot_env(1)%schur_projector_density_audit_lowcurv, &
                      projector_physical_density_low_curv_fraction)
               IF (projector_physical_density_rhs_abs_max > &
                   EPSILON(projector_physical_density_rhs_abs_max)) &
                  local_ot_env(1)%schur_projector_density_audit_amplification = &
                  MAX(local_ot_env(1)%schur_projector_density_audit_amplification, &
                      projector_physical_density_response_abs_max/ &
                      projector_physical_density_rhs_abs_max)
            END IF
            IF (projector_physical_candidate_ready .AND. &
                projector_physical_model_calibrated_drop > EPSILON(projector_physical_model_calibrated_drop)) THEN
               local_ot_env(1)%schur_projector_physical_pending = .TRUE.
               local_ot_env(1)%schur_projector_physical_drop = &
                  local_ot_env(1)%schur_projector_physical_drop + projector_physical_model_calibrated_drop
               IF (projector_physical_candidate_selected) &
                  local_ot_env(1)%schur_projector_physical_selected = &
                  local_ot_env(1)%schur_projector_physical_selected + projector_physical_model_calibrated_drop
               IF (projector_physical_direct_candidate_used) THEN
                  local_ot_env(1)%schur_projector_physical_direct = &
                     local_ot_env(1)%schur_projector_physical_direct + projector_physical_model_calibrated_drop
                  IF (projector_physical_candidate_selected) &
                     local_ot_env(1)%schur_projector_physical_direct_selected = &
                     local_ot_env(1)%schur_projector_physical_direct_selected + &
                     projector_physical_model_calibrated_drop
                  local_ot_env(1)%schur_projector_physical_shift = &
                     local_ot_env(1)%schur_projector_physical_shift + &
                     projector_physical_model_calibrated_drop*projector_physical_direct_diag_shift_avg
                  local_ot_env(1)%schur_projector_physical_compensation = &
                     local_ot_env(1)%schur_projector_physical_compensation + &
                     projector_physical_model_calibrated_drop*projector_physical_direct_diag_compensation
                  local_ot_env(1)%schur_projector_physical_trace_actual = &
                     local_ot_env(1)%schur_projector_physical_trace_actual + &
                     projector_physical_model_calibrated_drop* &
                     projector_physical_direct_trace_actual_norm
                  local_ot_env(1)%schur_projector_physical_trace_raw = &
                     local_ot_env(1)%schur_projector_physical_trace_raw + &
                     projector_physical_model_calibrated_drop* &
                     projector_physical_direct_trace_full_norm
                  local_ot_env(1)%schur_projector_physical_trace_active = &
                     local_ot_env(1)%schur_projector_physical_trace_active + &
                     projector_physical_model_calibrated_drop* &
                     projector_physical_direct_trace_active_norm
                  local_ot_env(1)%schur_projector_physical_trace_invariant = &
                     local_ot_env(1)%schur_projector_physical_trace_invariant + &
                     projector_physical_model_calibrated_drop* &
                     projector_physical_direct_trace_invariant_norm
                  local_ot_env(1)%schur_projector_physical_trace_actual_diag = &
                     local_ot_env(1)%schur_projector_physical_trace_actual_diag + &
                     projector_physical_model_calibrated_drop* &
                     projector_physical_direct_trace_actual_diag_quad/ &
                     MAX(projector_physical_direct_norm_rotation, EPSILON(1.0_dp))
                  local_ot_env(1)%schur_projector_physical_trace_actual_free = &
                     local_ot_env(1)%schur_projector_physical_trace_actual_free + &
                     projector_physical_model_calibrated_drop* &
                     projector_physical_direct_trace_actual_free_quad/ &
                     MAX(projector_physical_direct_norm_rotation, EPSILON(1.0_dp))
                  local_ot_env(1)%schur_projector_physical_trace_raw_diag = &
                     local_ot_env(1)%schur_projector_physical_trace_raw_diag + &
                     projector_physical_model_calibrated_drop* &
                     projector_physical_direct_trace_full_diag_quad/ &
                     MAX(projector_physical_direct_norm_rotation, EPSILON(1.0_dp))
                  local_ot_env(1)%schur_projector_physical_trace_raw_free = &
                     local_ot_env(1)%schur_projector_physical_trace_raw_free + &
                     projector_physical_model_calibrated_drop* &
                     projector_physical_direct_trace_full_free_quad/ &
                     MAX(projector_physical_direct_norm_rotation, EPSILON(1.0_dp))
                  local_ot_env(1)%schur_projector_physical_trace_active_diag = &
                     local_ot_env(1)%schur_projector_physical_trace_active_diag + &
                     projector_physical_model_calibrated_drop* &
                     projector_physical_direct_trace_active_diag_quad/ &
                     MAX(projector_physical_direct_norm_rotation, EPSILON(1.0_dp))
                  local_ot_env(1)%schur_projector_physical_trace_active_free = &
                     local_ot_env(1)%schur_projector_physical_trace_active_free + &
                     projector_physical_model_calibrated_drop* &
                     projector_physical_direct_trace_active_free_quad/ &
                     MAX(projector_physical_direct_norm_rotation, EPSILON(1.0_dp))
                  local_ot_env(1)%schur_projector_physical_trace_invariant_diag = &
                     local_ot_env(1)%schur_projector_physical_trace_invariant_diag + &
                     projector_physical_model_calibrated_drop* &
                     projector_physical_direct_trace_invariant_diag_quad/ &
                     MAX(projector_physical_direct_norm_rotation, EPSILON(1.0_dp))
                  local_ot_env(1)%schur_projector_physical_trace_invariant_free = &
                     local_ot_env(1)%schur_projector_physical_trace_invariant_free + &
                     projector_physical_model_calibrated_drop* &
                     projector_physical_direct_trace_invariant_free_quad/ &
                     MAX(projector_physical_direct_norm_rotation, EPSILON(1.0_dp))
               END IF
               IF (projector_physical_direct_candidate_used .AND. &
                   projector_physical_direct_metric_norm_ratio > EPSILON(projector_physical_direct_metric_norm_ratio)) &
                  local_ot_env(1)%schur_projector_physical_metric = &
                  local_ot_env(1)%schur_projector_physical_metric + &
                  projector_physical_model_calibrated_drop*projector_physical_direct_metric_norm_ratio
               local_ot_env(1)%schur_projector_physical_weight = &
                  MAX(local_ot_env(1)%schur_projector_physical_weight, projector_physical_response_weight)
               local_ot_env(1)%schur_projector_physical_correction_drop = &
                  local_ot_env(1)%schur_projector_physical_correction_drop + &
                  projector_physical_response_correction_drop
               local_ot_env(1)%schur_projector_physical_negative = &
                  MAX(local_ot_env(1)%schur_projector_physical_negative, &
                      projector_physical_response_correction_negative)
            END IF
            IF (projector_physical_direct_density_candidate_selected .AND. &
                accepted_model_calibrated_drop > EPSILON(accepted_model_calibrated_drop)) THEN
               local_ot_env(1)%schur_projector_physical_direct_selected = &
                  local_ot_env(1)%schur_projector_physical_direct_selected + &
                  accepted_model_calibrated_drop
               local_ot_env(1)%schur_projector_phys_direct_density_sel = &
                  local_ot_env(1)%schur_projector_phys_direct_density_sel + &
                  accepted_model_calibrated_drop
            END IF
            IF (.NOT. projector_physical_direct_candidate_selected .AND. &
                .NOT. projector_physical_direct_density_candidate_selected) THEN
               projector_physical_direct_selected_bridge_drop = MAX( &
                                                                kpoint_ot_direct_selected_bridge_drop( &
                                                      density_full_direct_candidate_selected, density_full_direct_candidate_ready, &
                                       projector_physical_direct_candidate_ready, projector_physical_direct_model_calibrated_drop, &
                                                        density_full_direct_model_calibrated_drop, accepted_model_calibrated_drop, &
                                                                ot_kp_schur_projector_direct_bridge_min_ratio), &
                                                                kpoint_ot_direct_selected_bridge_drop( &
                                                              density_descent_candidate_selected, density_descent_candidate_ready, &
                                       projector_physical_direct_candidate_ready, projector_physical_direct_model_calibrated_drop, &
                                                            density_descent_model_calibrated_drop, accepted_model_calibrated_drop, &
                                                                ot_kp_schur_projector_direct_bridge_min_ratio))
               projector_physical_direct_selected_bridge_drop = MAX( &
                                                                projector_physical_direct_selected_bridge_drop, &
                                                                kpoint_ot_direct_selected_bridge_drop( &
                                                             density_full_candidate_selected, density_full_direct_candidate_ready, &
                                       projector_physical_direct_candidate_ready, projector_physical_direct_model_calibrated_drop, &
                                                        density_full_direct_model_calibrated_drop, accepted_model_calibrated_drop, &
                                                                ot_kp_schur_projector_direct_bridge_min_ratio))
               IF (projector_physical_direct_selected_bridge_drop > &
                   EPSILON(projector_physical_direct_selected_bridge_drop)) &
                  local_ot_env(1)%schur_projector_physical_direct_selected = &
                  local_ot_env(1)%schur_projector_physical_direct_selected + &
                  projector_physical_direct_selected_bridge_drop
            END IF
         END IF

         IF (.NOT. failed) THEN
            energy_gradient_sum = SUM(grad_e)
            energy_gradient_abs_sum = SUM(ABS(grad_e))
            energy_independent_gdot = DOT_PRODUCT(grad_e, z_trial)
            energy_selected_gdot = DOT_PRODUCT(grad_e, z_e)
            energy_independent_norm = kpoint_ot_weighted_vector_dot( &
                                      z_trial, z_trial, energy_step_weight)
            energy_selected_norm = kpoint_ot_weighted_vector_dot(z_e, z_e, energy_step_weight)
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%sum(energy_gradient_sum)
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%sum(energy_gradient_abs_sum)
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%sum(energy_independent_gdot)
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%sum(energy_selected_gdot)
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%sum(energy_independent_norm)
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%sum(energy_selected_norm)
            energy_split_ratio = 0.0_dp
            IF (energy_independent_gdot > EPSILON(energy_independent_gdot)) &
               energy_split_ratio = energy_selected_gdot/energy_independent_gdot
            IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
               WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,8(1X,ES16.8))') &
               " OT Schur energy split audit group gsum gabs phys ind_gdot sel_gdot ratio ind_norm sel_norm:", &
               target_group, energy_gradient_sum, energy_gradient_abs_sum, rot_grad_energy_norm, &
               energy_independent_gdot, energy_selected_gdot, energy_split_ratio, &
               energy_independent_norm, energy_selected_norm
            DO local_kpoint = 1, SIZE(kpoints%kp_env)
               kp => kpoints%kp_env(local_kpoint)%kpoint_env
               ikpoint = kp%nkpoint
               DO ispin = 1, nspin_ot
                  group = MERGE(ispin, 1, ngroups == nspin_ot)
                  IF (group /= target_group) CYCLE
                  local_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot) - first_channel + 1
                  global_channel = qs_ot_channel_index(ispin, ikpoint, nspin_ot)
                  nmo = channel_nmo(global_channel)
                  DO imo = 1, nmo
                     ie = e_offset(global_channel) + imo - 1
                     local_ot_env(local_channel)%ener_gx(imo) = z_e(ie)
                  END DO
               END DO
            END DO

            DO local_channel = 1, SIZE(local_ot_env)
               global_channel = first_channel + local_channel - 1
               nmo = channel_nmo(global_channel)
               IF (nmo <= 0) CYCLE
               ALLOCATE (grad_re(nmo, nmo), grad_im(nmo, nmo))
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_gx, grad_re)
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_gx_im, grad_im)
               CALL local_ot_env(local_channel)%para_env%sum(grad_re)
               CALL local_ot_env(local_channel)%para_env%sum(grad_im)
               DO r = 1, nrot
                  IF (var_channel(r) /= global_channel) CYCLE
                  imo = var_i(r)
                  jmo = var_j(r)
                  SELECT CASE (var_kind(r))
                  CASE (1)
                     grad_re(imo, jmo) = sol(r)
                     grad_re(jmo, imo) = -sol(r)
                  CASE (2)
                     grad_im(imo, jmo) = sol(r)
                     grad_im(jmo, imo) = sol(r)
                  END SELECT
               END DO
               CALL dense_to_dbcsr_square(local_ot_env(local_channel)%rot_mat_gx, grad_re)
               CALL dense_to_dbcsr_square(local_ot_env(local_channel)%rot_mat_gx_im, grad_im)
               DEALLOCATE (grad_re, grad_im)
            END DO
            group_done = .TRUE.
            accepted_step_gap_re = 0.0_dp
            accepted_step_gap_im = 0.0_dp
            accepted_step_gauge_re = 0.0_dp
            accepted_step_gauge_im = 0.0_dp
            accepted_step_fermi_re = 0.0_dp
            accepted_step_fermi_im = 0.0_dp
            accepted_step_gap_weight = 0.0_dp
            accepted_step_gauge_weight = 0.0_dp
            DO r = 1, nrot
               rot_grad_pair_fraction = 0.0_dp
               IF (var_projector_weight(r) > EPSILON(var_projector_weight(r))) &
                  rot_grad_pair_fraction = var_projector_active_weight(r)/var_projector_weight(r)
               rot_grad_pair_fraction = MIN(1.0_dp, MAX(0.0_dp, rot_grad_pair_fraction))
               rot_grad_rest_fraction = 1.0_dp - rot_grad_pair_fraction
               rot_grad_fermi_weight = rot_grad_pair_fraction
               accepted_step_gap_fraction = kpoint_ot_residual_occ_gap_weight(var_occ_gap_weight(r))
               accepted_step_sq = sol(r)*sol(r)
               accepted_step_gap_weight = accepted_step_gap_weight + &
                                          rot_grad_rest_fraction*accepted_step_gap_fraction
               accepted_step_gauge_weight = accepted_step_gauge_weight + &
                                            rot_grad_rest_fraction*(1.0_dp - accepted_step_gap_fraction)
               IF (var_kind(r) == 1) THEN
                  accepted_step_fermi_re = accepted_step_fermi_re + rot_grad_fermi_weight*accepted_step_sq
                  accepted_step_gap_re = accepted_step_gap_re + &
                                         rot_grad_rest_fraction*accepted_step_gap_fraction*accepted_step_sq
                  accepted_step_gauge_re = accepted_step_gauge_re + &
                                           rot_grad_rest_fraction*(1.0_dp - accepted_step_gap_fraction)* &
                                           accepted_step_sq
               ELSE
                  accepted_step_fermi_im = accepted_step_fermi_im + rot_grad_fermi_weight*accepted_step_sq
                  accepted_step_gap_im = accepted_step_gap_im + &
                                         rot_grad_rest_fraction*accepted_step_gap_fraction*accepted_step_sq
                  accepted_step_gauge_im = accepted_step_gauge_im + &
                                           rot_grad_rest_fraction*(1.0_dp - accepted_step_gap_fraction)* &
                                           accepted_step_sq
               END IF
            END DO
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%sum(accepted_step_gap_re)
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%sum(accepted_step_gap_im)
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%sum(accepted_step_gauge_re)
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%sum(accepted_step_gauge_im)
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%sum(accepted_step_fermi_re)
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%sum(accepted_step_fermi_im)
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%sum(accepted_step_gap_weight)
            IF (.NOT. global_schur_replicated) &
               CALL para_env_inter_kp%sum(accepted_step_gauge_weight)
            accepted_step_gap_re = SQRT(MAX(0.0_dp, accepted_step_gap_re))
            accepted_step_gap_im = SQRT(MAX(0.0_dp, accepted_step_gap_im))
            accepted_step_gauge_re = SQRT(MAX(0.0_dp, accepted_step_gauge_re))
            accepted_step_gauge_im = SQRT(MAX(0.0_dp, accepted_step_gauge_im))
            accepted_step_fermi_re = SQRT(MAX(0.0_dp, accepted_step_fermi_re))
            accepted_step_fermi_im = SQRT(MAX(0.0_dp, accepted_step_fermi_im))
            accepted_step_gap_norm = SQRT(accepted_step_gap_re*accepted_step_gap_re + &
                                          accepted_step_gap_im*accepted_step_gap_im)
            accepted_step_gauge_norm = SQRT(accepted_step_gauge_re*accepted_step_gauge_re + &
                                            accepted_step_gauge_im*accepted_step_gauge_im)
            accepted_step_fermi_norm = SQRT(accepted_step_fermi_re*accepted_step_fermi_re + &
                                            accepted_step_fermi_im*accepted_step_fermi_im)
            accepted_step_gauge_ratio = 0.0_dp
            IF (accepted_step_gap_norm + accepted_step_gauge_norm > EPSILON(1.0_dp)) &
               accepted_step_gauge_ratio = &
               MIN(100.0_dp, accepted_step_gauge_norm/MAX(accepted_step_gap_norm, EPSILON(1.0_dp)))
            local_ot_env(1)%schur_step_gap_norm = accepted_step_gap_norm
            local_ot_env(1)%schur_step_gauge_norm = accepted_step_gauge_norm
            local_ot_env(1)%schur_step_fermi_norm = accepted_step_fermi_norm
            local_ot_env(1)%schur_step_gauge_ratio = accepted_step_gauge_ratio
            IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) THEN
               diag_shift_avg = diag_shift_sum/REAL(MAX(1, nrot), KIND=dp)
               response_abs_trust_ratio = 0.0_dp
               IF (response_abs_trust > EPSILON(response_abs_trust)) &
                  response_abs_trust_ratio = response_abs_step/response_abs_trust
               response_trust_ratio = 0.0_dp
               IF (response_trust > EPSILON(response_trust)) &
                  response_trust_ratio = response_step_max/response_trust
               response_weighted_trust_ratio = 0.0_dp
               IF (response_trust > EPSILON(response_trust)) &
                  response_weighted_trust_ratio = response_weighted_step/response_trust
               WRITE (cp_logger_get_default_unit_nr(logger), '(A,4(1X,I6),19(1X,ES16.8),1(1X,L1))') &
                  " OT Schur ne nrot att scale gdotp normp drop resp trust rtrust wresp wratio atrust aratio fac "// &
                  "delta proj dsum davg dmax dmin floor reject:", &
                  target_group, ne, nrot, schur_used_attempt, direction_scale, gdotp, normp, &
                  model_drop, response_step_max, response_trust, response_trust_ratio, response_weighted_step, &
                  response_weighted_trust_ratio, response_abs_trust, response_abs_trust_ratio, &
                  response_trust_factor, residual_delta, density_projector_fraction, diag_shift_sum, diag_shift_avg, &
                  diag_shift_max, schur_diag_min, rot_floor_min, trust_rejected
               WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,8(1X,ES16.8))') &
                  " OT Schur accepted step occ audit grp gap_re gap_im gauge_re gauge_im wgap wgauge fermi_re fermi_im:", &
                  target_group, accepted_step_gap_re, accepted_step_gap_im, accepted_step_gauge_re, &
                  accepted_step_gauge_im, accepted_step_gap_weight, accepted_step_gauge_weight, &
                  accepted_step_fermi_re, accepted_step_fermi_im
               WRITE (cp_logger_get_default_unit_nr(logger), '(A,2(1X,I6),7(1X,ES16.8))') &
                  " OT Schur accepted step gauge history flavor samples ratio rema rq rqema qshadow gap gauge:", &
                  selected_flavor, local_ot_env(1)%schur_step_gauge_quality_samples, accepted_step_gauge_ratio, &
                  local_ot_env(1)%schur_step_gauge_ratio_ema, &
                  local_ot_env(1)%schur_step_gauge_residual_quality, &
                  local_ot_env(1)%schur_step_gauge_residual_quality_ema, &
                  step_gauge_quality, accepted_step_gap_norm, accepted_step_gauge_norm
               IF (split_candidate_diagnostic) THEN
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,3(1X,I6),3(1X,L1),27(1X,ES16.8))') &
                     " OT Schur split audit group code samples gate new energy scale drop cdrop pred meas "// &
                     "qratio qema cqual cema calib qcal resp rtrust rratio wresp wratio atrust aratio mgap mdrop "// &
                     "mtrust mgratio norm "// &
                     "davg rdiag odiag tdiag:", &
                     target_group, coupled_reject_reason, local_ot_env(1)%schur_model_quality_samples, &
                     split_candidate_enabled, new_search_point, local_ot_env(1)%energy_only, &
                     coupled_direction_scale, coupled_model_drop, coupled_model_calibrated_drop, &
                     local_ot_env(1)%schur_model_drop, &
                     local_ot_env(1)%schur_model_measured_drop, local_ot_env(1)%schur_model_quality, &
                     local_ot_env(1)%schur_model_quality_ema, local_ot_env(1)%schur_split_calibrated_quality, &
                     local_ot_env(1)%schur_split_calibrated_quality_ema, &
                     split_curvature_scale, split_quality_for_calibration, &
                     coupled_response_step, response_trust, &
                     coupled_response_trust_ratio, coupled_response_weighted_step, &
                     coupled_response_weighted_trust_ratio, response_abs_trust, coupled_response_abs_trust_ratio, &
                     coupled_model_gap, coupled_model_gap_drop, coupled_model_gap_trust, &
                     coupled_model_gap_ratio, coupled_norm_ratio, &
                     coupled_diag_shift_avg, coupled_rot_diag_avg, coupled_occ_response_diag_avg, &
                     coupled_tether_response_diag_avg
                  IF (constrained_reject_reason /= 0 .OR. &
                      constrained_model_drop > EPSILON(constrained_model_drop)) &
                     WRITE (cp_logger_get_default_unit_nr(logger), '(A,3(1X,I6),3(1X,L1),25(1X,ES16.8))') &
                     " OT Schur constrained audit group code samples gate new energy scale drop cdrop "// &
                     "resp rtrust rratio wresp wratio atrust aratio mgap mdrop mtrust mgratio norm davg rdiag "// &
                     "odiag tdiag pdiag "// &
                     "calib qcal split_exp constr_exp exp_ratio:", &
                     target_group, constrained_reject_reason, local_ot_env(1)%schur_model_quality_samples, &
                     split_candidate_enabled, new_search_point, local_ot_env(1)%energy_only, &
                     constrained_direction_scale, constrained_model_drop, constrained_model_calibrated_drop, &
                     constrained_response_step, response_trust, constrained_response_trust_ratio, &
                     constrained_response_weighted_step, constrained_response_weighted_trust_ratio, response_abs_trust, &
                     constrained_response_abs_trust_ratio, constrained_model_gap, constrained_model_gap_drop, &
                     constrained_model_gap_trust, constrained_model_gap_ratio, constrained_norm_ratio, &
                     constrained_diag_shift_avg, &
                     constrained_rot_diag_avg, constrained_occ_response_diag_avg, constrained_tether_response_diag_avg, &
                     constrained_response_penalty_diag_avg, split_curvature_scale, split_quality_for_calibration, &
                     split_expected_drop, constrained_expected_drop, constrained_expected_drop_ratio
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,2(1X,L1),6(1X,ES16.8))') &
                     " OT Schur exact energy response ready physical gauge diag occ_gap occ_gap_max phys_gap phys_gap_max:", &
                     exact_energy_model_ready, exact_physical_response_ready, energy_gauge_weight, &
                     exact_response_diag_avg, projector_response_gap_avg, projector_response_gap_max, &
                     physical_response_gap_avg, physical_response_gap_max
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,ES16.8)') &
                     " OT Schur mixed response diag:", response_mixed_diag_avg
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,4(1X,ES16.8))') &
                     " OT Schur projector Hessian diag delta_diag abs_avg delta_max:", &
                     projector_hessian_diag_avg, projector_hessian_delta_diag_avg, &
                     projector_hessian_abs_avg, projector_hessian_delta_max
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,7(1X,ES16.8))') &
                     " OT Schur projector physical Hessian diag delta_diag abs_avg delta_max gauge_avg gauge_max trace_balance:", &
                     projector_physical_diag_avg, projector_physical_delta_diag_avg, &
                     projector_physical_abs_avg, projector_physical_delta_max, &
                     projector_gauge_abs_avg, projector_gauge_delta_max, projector_physical_trace_balance
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,4(1X,ES16.8))') &
                     " OT Schur projector physical offdiag-dP shadow diag abs max ratio:", &
                     projector_physical_offdiag_diag_avg, projector_physical_offdiag_abs_avg, &
                     projector_physical_offdiag_delta_max, projector_physical_offdiag_abs_ratio
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,6(1X,ES16.8))') &
                     " OT Schur projector physical offdiag-dP raw audit diag abs max gap_diag gap_avg gap_max:", &
                     projector_physical_offdiag_plateau_diag_avg, projector_physical_offdiag_plateau_abs_avg, &
                     projector_physical_offdiag_plateau_delta_max, &
                     projector_physical_offdiag_plateau_gap_diag_avg, &
                     projector_physical_offdiag_plateau_gap_abs_avg, &
                     projector_physical_offdiag_plateau_gap_delta_max
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,4(1X,ES16.8))') &
                     " OT Schur projector physical offdiag-dP active split active inactive gap_active gap_inactive:", &
                     projector_physical_offdiag_active_abs_avg, &
                     projector_physical_offdiag_inactive_abs_avg, &
                     projector_physical_offdiag_plateau_gap_active_abs_avg, &
                     projector_physical_offdiag_plateau_gap_inactive_abs_avg
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,10(1X,ES16.8))') &
                     " OT Schur projector physical offdiag-dP modes neg stepneg emin emax quad absq "// &
                     "qratio aratio pquad nquad:", &
                     projector_physical_offdiag_mode_negative_fraction, &
                     projector_physical_offdiag_mode_step_negative_fraction, &
                     projector_physical_offdiag_mode_eval_min, projector_physical_offdiag_mode_eval_max, &
                     projector_physical_offdiag_mode_quad, projector_physical_offdiag_mode_abs_quad, &
                     projector_physical_offdiag_mode_quad_signed_ratio, &
                     projector_physical_offdiag_mode_quad_abs_ratio, &
                     projector_physical_offdiag_mode_positive_quad, &
                     projector_physical_offdiag_mode_negative_quad
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,10(1X,ES16.8))') &
                     " OT Schur projector physical offdiag-dP inactive modes neg stepneg emin emax quad absq "// &
                     "qratio aratio pquad nquad:", &
                     inactive_offdiag_mode_negative_fraction, &
                     inactive_offdiag_mode_step_negative_fraction, &
                     inactive_offdiag_mode_eval_min, inactive_offdiag_mode_eval_max, &
                     inactive_offdiag_mode_quad, inactive_offdiag_mode_abs_quad, &
                     inactive_offdiag_mode_quad_signed_ratio, &
