                              projector_physical_direct_trust_scale = 1.0_dp
                              IF (response_trust > EPSILON(response_trust) .AND. &
                                  projector_physical_direct_unit_weighted_step > &
                                  EPSILON(projector_physical_direct_unit_weighted_step)) &
                                 projector_physical_direct_trust_scale = &
                                 MIN(projector_physical_direct_trust_scale, &
                                     0.8_dp*response_trust/ &
                                     projector_physical_direct_unit_weighted_step)
                              IF (response_abs_trust > EPSILON(response_abs_trust) .AND. &
                                  projector_physical_direct_unit_abs_step > &
                                  EPSILON(projector_physical_direct_unit_abs_step)) &
                                 projector_physical_direct_trust_scale = &
                                 MIN(projector_physical_direct_trust_scale, &
                                     0.8_dp*response_abs_trust/ &
                                     projector_physical_direct_unit_abs_step)
                              direction_scale = MIN(1.0_dp, projector_physical_direct_trust_scale, &
                                                    gdotp/MAX(projector_physical_direct_metric_normp, &
                                                              EPSILON(projector_physical_direct_metric_normp)))
                              scale_quality = kpoint_ot_schur_scale_quality(direction_scale, schur_min_coupled_scale)
                              model_drop = direction_scale*gdotp - &
                                           0.5_dp*direction_scale*direction_scale* &
                                           projector_physical_direct_metric_normp
                              model_drop = MAX(0.0_dp, model_drop)
                              response_abs_step = direction_scale*projector_physical_direct_unit_abs_step
                              response_weighted_step = direction_scale*projector_physical_direct_unit_weighted_step
                              model_gap = direction_scale*MAXVAL(ABS(rx_model - rx_e))
                              model_gap_drop = kpoint_ot_response_mismatch_drop(rx_e, rx_model, curv, direction_scale)
                              model_calibrated_drop = MAX(0.0_dp, model_drop - model_gap_drop)
                              IF (direction_scale < schur_min_coupled_scale) &
                                 model_calibrated_drop = scale_quality*model_calibrated_drop
                              model_gap_trust = schur_model_gap_factor*response_trust
                              model_gap_ratio = 0.0_dp
                              IF (model_gap_trust > EPSILON(model_gap_trust)) model_gap_ratio = model_gap/model_gap_trust
                              IF (response_trust > EPSILON(response_trust)) &
                                 response_weighted_trust_ratio = response_weighted_step/response_trust
                              IF (response_abs_trust > EPSILON(response_abs_trust)) &
                                 response_abs_trust_ratio = response_abs_step/response_abs_trust
                              dense_trust_quality = kpoint_ot_schur_trust_quality(response_weighted_trust_ratio, &
                                                                                  response_abs_trust_ratio, &
                                                                                  model_gap_ratio)
                              dense_expected_drop = kpoint_ot_schur_expected_drop(model_calibrated_drop, &
                                                                                  projector_physical_direct_quality_for_selection* &
                                                                                  projector_plateau_gap_quality_for_selection, &
                                                                dense_trust_quality*projector_physical_direct_density_audit_quality)
                           END IF
                        END IF
                        ! Keep this DEBUG-only active/full Direct probe diagnostic.
                        ! Promotion must be learned from print-level-neutral
                        ! accepted steps, otherwise PRINT_LEVEL changes the
                        ! k-point OT minimizer path.
                        WRITE (cp_logger_get_default_unit_nr(logger), '(A,1(1X,L1),13(1X,ES16.8))') &
                           " OT Schur projector mixed direct shadow solved wactive exp cdrop mgap rratio aratio "// &
                           "scale dsum dmax dmin wactive_comp emin emax:", &
                           solved, z_weight, dense_expected_drop, model_calibrated_drop, model_gap, &
                           response_weighted_trust_ratio, response_abs_trust_ratio, direction_scale, &
                           diag_shift_sum, diag_shift_max, schur_diag_min, &
                           z_weight*projector_physical_direct_active_diag_compensation, &
                           projector_physical_direct_schur_eval_min, projector_physical_direct_schur_eval_max
                     END DO
                  END IF
               END IF
            END IF
         END IF
         ! Learn the mixed active/physical Direct curvature from any accepted
         ! exact-response dense step, including the row-floor fallback that
         ! dominates the metallic residual tail. Waiting for an already selected
         ! Direct candidate makes promotion circular.
         ! Keep this outside the DEBUG print block so PRINT_LEVEL cannot change
         ! the k-point OT minimizer path.
         IF (new_search_point .AND. accepted_model_drop > EPSILON(accepted_model_drop) .AND. &
             (selected_attempt == 3 .OR. selected_attempt == 4 .OR. &
              projector_physical_direct_candidate_selected .OR. &
              projector_physical_direct_density_candidate_selected .OR. &
              projector_physical_direct_spectral_candidate_selected)) THEN
            projector_physical_direct_shadow_weight = &
               MAX(projector_coupled_weight, &
                   MAX(projector_physical_response_weight, projector_physical_direct_response_weight))
            IF (projector_physical_shadow_enabled .AND. exact_physical_response_ready .AND. &
                projector_physical_direct_shadow_weight > &
                EPSILON(projector_physical_direct_shadow_weight) .AND. &
                (local_ot_env(1)%schur_projector_mode_quality_samples >= &
                 ot_kp_schur_calibration_min_samples .OR. &
                 projector_physical_direct_promoted .OR. &
                 projector_density_history_weight > EPSILON(projector_density_history_weight))) THEN
               CALL qs_scf_kp_density_replaced_response( &
                  response_exact_physical, energy_cross_canonical, &
                  response_exact_active, energy_cross_active, &
                  response_density_direct_exact, energy_cross_density_direct, &
                  exact_active_response_ready .AND. exact_density_direct_response_ready, &
                  response_physical_model, energy_cross_physical_model)
               DO ivar = 1, 4
                  z_weight = REAL(ivar, KIND=dp)/4.0_dp
                  projector_physical_direct_schur_vec(:, :) = &
                     (1.0_dp - z_weight)*projector_physical_direct_base_delta(:, :) + &
                     z_weight*0.5_dp*((rot_hessian_projector_physical_active(:, :) - rot_hessian(:, :)) + &
                                      TRANSPOSE(rot_hessian_projector_physical_active(:, :) - &
                                                rot_hessian(:, :)))
                  IF (projector_physical_direct_shadow_weight > &
                      EPSILON(projector_physical_direct_shadow_weight)) THEN
                     DO r = 1, nrot
                        diag_shift = z_weight*projector_physical_direct_active_lcomp(r)/ &
                                     projector_physical_direct_shadow_weight
                        IF (diag_shift <= 0.0_dp) CYCLE
                        projector_physical_direct_schur_vec(r, r) = &
                           projector_physical_direct_schur_vec(r, r) + diag_shift
                     END DO
                  END IF
                  schur(:, :) = rot_hessian_coupled(:, :) + &
                                projector_physical_direct_shadow_weight* &
                                projector_physical_direct_schur_vec(:, :)
                  DO s = 1, nrot
                     DO r = 1, nrot
                        projected_term = 0.5_dp* &
                                         (DOT_PRODUCT(energy_cross_physical_model(:, r), &
                                                      response_physical_model(:, s)) + &
                                          DOT_PRODUCT(energy_cross_physical_model(:, s), &
                                                      response_physical_model(:, r)))
                        schur(r, s) = schur(r, s) - projected_term
                     END DO
                  END DO
                  DO r = 1, nrot
                     row_floor = kpoint_ot_physical_rotation_floor(sigma, schur(r, r), &
                                                        rot_hessian(r, r) + projector_physical_direct_schur_vec(r, r), rot_floor(r))
                     schur(r, r) = schur(r, r) + MAX(0.0_dp, row_floor - schur(r, r))
                  END DO
                  projector_physical_direct_schur_vec(:, :) = 0.5_dp*(schur(:, :) + TRANSPOSE(schur(:, :)))
                  rx_e(:) = accepted_z_e(:) - z_exact_physical_trial(:)
                  rx_model(:) = (1.0_dp - z_weight)*MATMUL(response_exact_raw, accepted_sol) + &
                                z_weight*MATMUL(response_physical_model, accepted_sol)
                  CALL project_kpoint_ot_schur_response(rx_e, occ_curv, tether_curv, &
                                                        occ_curv_projection_sum, channel_nmo, e_offset)
                  CALL project_kpoint_ot_schur_response(rx_model, occ_curv, tether_curv, &
                                                        occ_curv_projection_sum, channel_nmo, e_offset)
                  z_e(:) = z_exact_physical_trial(:) + rx_model(:)
                  CALL project_kpoint_ot_schur_response(z_e, occ_curv, tether_curv, &
                                                        occ_curv_projection_sum, channel_nmo, e_offset)
                  gdotp = DOT_PRODUCT(grad_e, z_e) + DOT_PRODUCT(grad_rot, accepted_sol)
                  CALL kpoint_ot_mixed_projected_term(z_e, z_e, occ_curv, tether_curv, &
                                                      occ_curv_projection_sum, channel_nmo, e_offset, &
                                                      projector_physical_direct_metric_norm_energy)
                  projector_physical_direct_metric_norm_energy = &
                     MAX(0.0_dp, projector_physical_direct_metric_norm_energy)
                  rhs(:) = MATMUL(projector_physical_direct_schur_vec, accepted_sol)
                  projector_physical_direct_metric_norm_rotation = SUM(ABS(accepted_sol(:)*rhs(:)))
                  projector_physical_direct_metric_normp = &
                     projector_physical_direct_metric_norm_energy + &
                     projector_physical_direct_metric_norm_rotation
                  IF (gdotp <= 0.0_dp .OR. &
                      projector_physical_direct_metric_normp <= &
                      EPSILON(projector_physical_direct_metric_normp)) CYCLE
                  model_drop = gdotp - 0.5_dp*projector_physical_direct_metric_normp
                  model_drop = MAX(0.0_dp, model_drop)
                  IF (model_drop <= EPSILON(model_drop)) CYCLE
                  model_gap_drop = kpoint_ot_response_mismatch_drop(rx_e, rx_model, curv, 1.0_dp)
                  model_calibrated_drop = MAX(0.0_dp, model_drop - model_gap_drop)
                  IF (model_calibrated_drop > local_ot_env(1)%schur_projector_mixed_direct_drop .AND. &
                      model_calibrated_drop >= &
                      MAX(accepted_model_calibrated_drop/ot_kp_schur_calibrated_quality_max_ratio, &
                          EPSILON(accepted_model_calibrated_drop)) .AND. &
                      model_calibrated_drop <= ot_kp_schur_calibrated_quality_max_ratio* &
                      MAX(accepted_model_calibrated_drop, EPSILON(accepted_model_calibrated_drop))) THEN
                     local_ot_env(1)%schur_projector_mixed_direct_pending = .TRUE.
                     local_ot_env(1)%schur_projector_mixed_direct_drop = model_calibrated_drop
                     local_ot_env(1)%schur_projector_mixed_direct_weight = z_weight
                  END IF
               END DO
            END IF
         END IF

         DEALLOCATE (canonical_occ_curv, curv, grad_e, occ_curv, tether_curv, &
                     density_basis_selective_floor_weight, &
                     energy_grad_metric_weight, energy_step_weight, &
                     z_e, accepted_z_e, z_density_plateau_trial, &
                     z_density_floor_audit_trial, z_density_floor_safe_audit_trial, &
                     z_density_full_audit_trial, &
                     z_density_full_global_trial, &
                     z_density_full_trial, z_density_trial, &
                     z_exact_active_trial, z_exact_physical_trial, z_exact_raw_trial, &
                     z_exact_trial, z_multisecant, z_trial, rx_e, rx_model, constrained_z_e, &
                     canonical_density_trial_raw_rx_e, &
                     direct_pg_base_e, direct_pg_rx_e, &
                     projector_physical_direct_curv_eval, projector_physical_direct_model_e, &
                     projector_physical_direct_response_rx_e, &
                     projector_physical_direct_diagref_rx_e, &
                     projector_physical_direct_density_rx_e, &
                     projector_physical_direct_effective_rx_e, &
                     projector_physical_direct_density_z_e, &
                     density_descent_rx_e, &
                     density_descent_sol, &
                     density_descent_z_e, &
                     density_full_rx_e, &
                     density_full_global_rx_e, &
                     density_full_global_sol, &
                     density_full_sol, &
                     density_full_z_e, &
                     density_gap_projected_e, &
                     density_gap_rx_e, &
                     density_gap_trial_basis_e, &
                     density_gap_trial_projected_e, &
                     density_plateau_rx_e, density_plateau_z_e, &
                     z_density_basis_audit_trial, z_density_basis_curvfloor_audit_trial, &
                     z_density_basis_selective_audit_trial, &
                     z_density_basis_damped_audit_trial, z_density_basis_filtered_audit_trial, &
                     projector_physical_direct_rx_e, &
                     projector_physical_direct_schur_eval, &
                     projector_physical_direct_spectral_model_e, &
                     projector_physical_direct_spectral_rx_e, &
                     projector_physical_direct_z_e, &
                     projector_physical_direct_spectral_z_e, &
                     projector_offdiag_rx_e, projector_offdiag_z_e, &
                     projector_inactive_offdiag_rx_e, &
                     projector_inactive_offdiag_z_e, &
                     projector_physical_model_e, projector_physical_rx_e, &
                     projector_physical_z_e, &
                     projector_response_rx_e, projector_response_z_e, &
                     prediction_z_base, prediction_z_e, reduced_secant_response_step, &
                     reduced_secant_z_e, closure_candidate_z_e, split_z_e)
         DEALLOCATE (full_grad_rot, full_var_physical_grad_metric_weight, &
                     grad_rot, rhs, rtd, sol, accepted_sol, canonical_density_tangent, &
                     canonical_density_mode_alpha, canonical_density_mode_curvature, &
                     canonical_density_mode_linear, canonical_density_tangent_modes, &
                     canonical_density_trial_sol, constrained_sol, &
                     projector_physical_direct_sol, &
                     projector_physical_direct_spectral_sol, &
                     projector_physical_sol, projector_offdiag_sol, &
                     projector_inactive_offdiag_sol, projector_response_sol, &
                     prediction_sol, reduced_secant_sol, closure_candidate_sol, split_sol, &
                     var_grad_metric_weight, var_occ_gap_weight, var_physical_grad_metric_weight, &
                     var_projector_active_weight, &
                     var_projector_response_weight, var_projector_weight, var_step_weight, &
                     var_thermal_activity)
         DEALLOCATE (var_channel, var_ei, var_ej, var_i, var_j, var_kind, var_full_index)
         DEALLOCATE (rot_floor, row_floor_shift, projector_physical_direct_active_lcomp, &
                     energy_cross, energy_cross_active, energy_cross_canonical, energy_cross_density, &
                     energy_cross_density_basis_audit, energy_cross_density_basis_curvfloor_audit, &
                     energy_cross_density_basis_damped_audit, energy_cross_density_basis_filtered_audit, &
                     energy_cross_density_basis_selective_audit, &
                     energy_cross_density_direct, energy_cross_multisecant, &
                     energy_cross_prediction, &
                     energy_cross_physical_model, &
                     energy_cross_raw, &
                     energy_cross_density_floor_audit, energy_cross_density_floor_safe_audit, &
                     energy_cross_density_full, energy_cross_density_full_audit, &
                     energy_cross_density_full_global, energy_cross_density_plateau, &
                     energy_hessian, energy_hessian_multisecant, energy_hessian_prediction, &
                     energy_hessian_reference, &
                     response, response_coupled, response_multisecant, &
                     response_density_direct_exact, &
                     response_density_exact, &
                     response_density_basis_audit, response_density_basis_audit_exact, &
                     response_density_basis_curvfloor_audit_exact, &
                     response_density_basis_damped_audit, response_density_basis_damped_audit_exact, &
                     response_density_basis_filtered_audit, response_density_basis_filtered_audit_exact, &
                     response_density_basis_selective_audit_exact, &
                     response_density_floor_audit, response_density_floor_audit_exact, &
                     response_density_floor_safe_audit, response_density_floor_safe_audit_exact, &
                     response_density_full, response_density_full_audit, &
                     response_density_full_audit_exact, response_density_full_exact, &
                     response_density_full_global, response_density_full_global_exact, response_density_physical, &
                     response_density_plateau, response_density_plateau_exact, &
                     response_exact, response_exact_active, response_exact_physical, response_exact_raw, &
                     response_occ, response_occ_canonical, response_occ_physical, response_physical_model, &
                     response_prediction, response_split, rot_hessian, &
                     projector_physical_direct_base_delta, projector_physical_direct_curv_evec, &
                     projector_physical_direct_curv_vec, &
                     projector_physical_direct_delta, &
                     closure_response_steps, closure_response_targets, &
                     closure_density_probe_steps, closure_density_probe_targets, &
                     closure_coupled_full_cross_correction, &
                     closure_coupled_full_energy_correction, &
                     closure_coupled_full_rotation_correction, &
                     closure_coupled_predictive_cross_correction, &
                     closure_coupled_predictive_energy_correction, &
                     closure_coupled_predictive_rotation_correction, &
                     closure_coupled_response_metric, &
                     closure_response_metric, &
                     rot_hessian_closure_candidate, &
                     rot_hessian_closure_coupled_fullrank_response, &
                     rot_hessian_closure_fullrank_response, &
                     rot_hessian_closure_baseline, rot_hessian_closure_probe_response, &
                     rot_hessian_closure_reduced_response, &
                     rot_hessian_closure_response, &
                     rot_hessian_closure_coupled_response, rot_hessian_coupled, &
                     full_rot_hessian_coupled, &
                     rot_hessian_multisecant, rot_hessian_prediction, &
                     reduced_response_metric, reduced_secant_full_targets, reduced_secant_modes, &
                     reduced_secant_targets, &
                     rot_hessian_reduced_secant, rot_hessian_secant, &
                     rot_hessian_orbital_schur, &
                     rot_hessian_projector, &
                     projector_physical_direct_schur_evec, projector_physical_direct_schur_mat, &
                     projector_physical_direct_schur_vec, &
                     rot_hessian_projector_physical, &
                     rot_hessian_projector_physical_active, rot_hessian_projector_physical_diagref, &
                     rot_hessian_projector_physical_offdiag_active, &
                     rot_hessian_projector_physical_offdiag, &
                     rot_hessian_projector_physical_offdiag_plateau, &
                     rot_hessian_projector_physical_offdiag_plateau_active, &
                     schur, schur_metric, ipiv, ipiv_energy, &
                     canonical_density_cauchy_channel, channel_full_var_offset, &
                     channel_multiplicity, channel_nmo, &
                     channel_nrot, channel_var_offset, channel_maxocc, e_offset, &
                     channel_density_pair_residual, channel_density_pair_active, &
                     channel_density_pair_candidate, channel_fermi_pair_active, &
                     channel_residual_pair_active, channel_residual_pair_candidate, &
                     channel_residual_pair_score)
      END SUBROUTINE precondition_kpoint_ot_schur_group

! **************************************************************************************************
!> \brief Build a direct coupled candidate from a bidirectionally validated finite secant Hessian.
!>
!>        The candidate solves the complete fixed-N Schur complement in its own response metric.
!>        It remains separate from the established density/projector candidate so its accepted
!>        Mermin drop and residual quality can be calibrated without model mixing.
!> \param rotation_hessian ...
!> \param response_metric ...
!> \param response ...
!> \param energy_base_step ...
!> \param reference_response ...
!> \param rotation_gradient ...
!> \param energy_gradient ...
!> \param reference_rotation_step ...
!> \param occ_curv ...
!> \param tether_curv ...
!> \param occ_curv_sum ...
!> \param channel_nmo ...
!> \param e_offset ...
!> \param rotation_floor ...
!> \param response_curv ...
!> \param response_curv_sum ...
!> \param response_trust ...
!> \param response_abs_trust ...
!> \param model_gap_factor ...
!> \param rotation_step_weight ...
!> \param energy_step_weight ...
!> \param rotation_gradient_weight ...
!> \param energy_gradient_weight ...
!> \param max_norm_ratio ...
!> \param rotation_step ...
!> \param energy_step ...
!> \param direction_scale ...
!> \param model_slope ...
!> \param model_quadratic ...
!> \param model_drop ...
!> \param model_calibrated_drop ...
!> \param model_gap ...
!> \param model_gap_drop ...
!> \param model_gap_ratio ...
!> \param response_weighted_step ...
!> \param response_abs_step ...
!> \param candidate_residual_ratio ...
!> \param reference_residual_ratio ...
!> \param negative_scale ...
!> \param negative_gradient_fraction ...
!> \param ready ...
! **************************************************************************************************
      SUBROUTINE build_kpoint_ot_coupled_prediction_candidate( &
         rotation_hessian, response_metric, response, energy_base_step, reference_response, &
         rotation_gradient, energy_gradient, reference_rotation_step, occ_curv, tether_curv, &
         occ_curv_sum, channel_nmo, e_offset, rotation_floor, response_curv, response_curv_sum, &
         response_trust, response_abs_trust, model_gap_factor, rotation_step_weight, &
         energy_step_weight, rotation_gradient_weight, energy_gradient_weight, max_norm_ratio, &
         rotation_step, energy_step, direction_scale, model_slope, model_quadratic, model_drop, &
         model_calibrated_drop, model_gap, model_gap_drop, model_gap_ratio, &
         response_weighted_step, response_abs_step, candidate_residual_ratio, &
         reference_residual_ratio, negative_scale, negative_gradient_fraction, ready)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: rotation_hessian, response_metric, &
                                                            response
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: energy_base_step
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: reference_response
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: rotation_gradient, energy_gradient, &
                                                            reference_rotation_step, occ_curv, &
                                                            tether_curv
      REAL(KIND=dp), INTENT(IN)                          :: occ_curv_sum
      INTEGER, DIMENSION(:), INTENT(IN)                  :: channel_nmo, e_offset
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: rotation_floor, response_curv
      REAL(KIND=dp), INTENT(IN)                          :: response_curv_sum, response_trust, &
                                                            response_abs_trust, model_gap_factor
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: rotation_step_weight, &
                                                            energy_step_weight, &
                                                            rotation_gradient_weight, &
                                                            energy_gradient_weight
      REAL(KIND=dp), INTENT(IN)                          :: max_norm_ratio
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: rotation_step, energy_step
      REAL(KIND=dp), INTENT(OUT) :: direction_scale, model_slope, model_quadratic, model_drop, &
         model_calibrated_drop, model_gap, model_gap_drop, model_gap_ratio, &
         response_weighted_step, response_abs_step, candidate_residual_ratio, &
         reference_residual_ratio, negative_scale, negative_gradient_fraction
      LOGICAL, INTENT(OUT)                               :: ready

      INTEGER                                            :: nener, nrot
      LOGICAL                                            :: model_ready, spectral_ready
      REAL(KIND=dp)                                      :: gradient_norm, residual_norm, &
                                                            response_abs_unit, &
                                                            response_weighted_unit, step_norm
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:)           :: candidate_residual, reference_residual, &
                                                            reference_step, response_step, &
                                                            rhs_local
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: schur_local

         nrot = SIZE(rotation_gradient)
         nener = SIZE(energy_gradient)
         CPASSERT(ALL(SHAPE(rotation_hessian) == [nrot, nrot]))
         CPASSERT(ALL(SHAPE(response_metric) == [nrot, nrot]))
         CPASSERT(ALL(SHAPE(response) == [nener, nrot]))
         CPASSERT(ALL(SHAPE(reference_response) == [nener, nrot]))
         CPASSERT(SIZE(energy_base_step) == nener)
         CPASSERT(SIZE(reference_rotation_step) == nrot)
         CPASSERT(SIZE(rotation_floor) == nrot)
         CPASSERT(SIZE(rotation_step) == nrot)
         CPASSERT(SIZE(energy_step) == nener)

         rotation_step(:) = 0.0_dp
         energy_step(:) = 0.0_dp
         direction_scale = 0.0_dp
         model_slope = 0.0_dp
         model_quadratic = 0.0_dp
         model_drop = 0.0_dp
         model_calibrated_drop = 0.0_dp
         model_gap = 0.0_dp
         model_gap_drop = 0.0_dp
         model_gap_ratio = 0.0_dp
         response_weighted_step = 0.0_dp
         response_abs_step = 0.0_dp
         candidate_residual_ratio = 1.0_dp
         reference_residual_ratio = 1.0_dp
         negative_scale = 0.0_dp
         negative_gradient_fraction = 0.0_dp
         ready = .FALSE.
         IF (nrot <= 0 .OR. nener <= 0) RETURN

         ALLOCATE (candidate_residual(nrot), reference_residual(nrot), reference_step(nener), &
                   response_step(nener), rhs_local(nrot), schur_local(nrot, nrot))
         schur_local(:, :) = rotation_hessian - response_metric
         schur_local(:, :) = 0.5_dp*(schur_local + TRANSPOSE(schur_local))
         rhs_local(:) = rotation_gradient + MATMUL(TRANSPOSE(response), energy_gradient)
         CALL qs_scf_kp_indefinite_residual_balanced_step( &
            schur_local, rhs_local, rotation_floor, reference_rotation_step, rotation_step, &
            spectral_ready, negative_scale, negative_gradient_fraction, candidate_residual_ratio, &
            reference_residual_ratio)
         IF (.NOT. spectral_ready) THEN
            DEALLOCATE (candidate_residual, reference_residual, reference_step, response_step, &
                        rhs_local, schur_local)
            RETURN
         END IF

         response_step(:) = MATMUL(response, rotation_step)
         reference_step(:) = MATMUL(reference_response, rotation_step)
         CALL project_kpoint_ot_schur_response(response_step, occ_curv, tether_curv, occ_curv_sum, &
                                               channel_nmo, e_offset)
         CALL project_kpoint_ot_schur_response(reference_step, occ_curv, tether_curv, occ_curv_sum, &
                                               channel_nmo, e_offset)
         energy_step(:) = energy_base_step + response_step
         CALL project_kpoint_ot_schur_response(energy_step, occ_curv, tether_curv, occ_curv_sum, &
                                               channel_nmo, e_offset)

         response_abs_unit = MAXVAL(ABS(response_step))
         IF (.NOT. global_schur_replicated) CALL para_env_inter_kp%max(response_abs_unit)
         response_weighted_unit = kpoint_ot_weighted_response_step( &
                                  response_step, response_curv, response_curv_sum)
         direction_scale = 1.0_dp
         IF (response_trust > EPSILON(response_trust) .AND. &
             response_weighted_unit > EPSILON(response_weighted_unit)) &
            direction_scale = MIN(direction_scale, 0.8_dp*response_trust/response_weighted_unit)
         IF (response_abs_trust > EPSILON(response_abs_trust) .AND. &
             response_abs_unit > EPSILON(response_abs_unit)) &
            direction_scale = MIN(direction_scale, 0.8_dp*response_abs_trust/response_abs_unit)
         gradient_norm = kpoint_ot_weighted_vector_dot( &
                         rotation_gradient, rotation_gradient, rotation_gradient_weight) + &
                         kpoint_ot_weighted_vector_dot( &
                         energy_gradient, energy_gradient, energy_gradient_weight)
         step_norm = kpoint_ot_weighted_vector_dot( &
                     rotation_step, rotation_step, rotation_step_weight) + &
                     kpoint_ot_weighted_vector_dot(energy_step, energy_step, energy_step_weight)
         IF (step_norm > EPSILON(step_norm) .AND. gradient_norm > EPSILON(gradient_norm)) &
            direction_scale = MIN(direction_scale, SQRT(max_norm_ratio*gradient_norm/step_norm))
         IF (direction_scale <= EPSILON(direction_scale)) THEN
            rotation_step(:) = 0.0_dp
            energy_step(:) = 0.0_dp
            DEALLOCATE (candidate_residual, reference_residual, reference_step, response_step, &
                        rhs_local, schur_local)
            RETURN
         END IF

         rotation_step(:) = direction_scale*rotation_step
         energy_step(:) = direction_scale*energy_step
         response_step(:) = direction_scale*response_step
         reference_step(:) = direction_scale*reference_step
         response_abs_step = direction_scale*response_abs_unit
         response_weighted_step = direction_scale*response_weighted_unit
         residual_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(rhs_local, rhs_local)))
         candidate_residual(:) = rhs_local - MATMUL(schur_local, rotation_step)
         reference_residual(:) = rhs_local - MATMUL(schur_local, reference_rotation_step)
         IF (residual_norm > EPSILON(residual_norm)) THEN
            candidate_residual_ratio = SQRT(MAX(0.0_dp, DOT_PRODUCT(candidate_residual, &
                                                                    candidate_residual)))/ &
                                       residual_norm
            reference_residual_ratio = SQRT(MAX(0.0_dp, DOT_PRODUCT(reference_residual, &
                                                                    reference_residual)))/ &
                                       residual_norm
         END IF
         CALL evaluate_kpoint_ot_projected_coupled_step_model( &
            rotation_gradient, energy_gradient, rotation_hessian, rotation_step, energy_step, &
            response_step, occ_curv, tether_curv, occ_curv_sum, channel_nmo, e_offset, &
            model_slope, model_quadratic, model_drop, model_ready)
         model_gap = MAXVAL(ABS(reference_step - response_step))
         IF (.NOT. global_schur_replicated) CALL para_env_inter_kp%max(model_gap)
         model_gap_drop = kpoint_ot_response_mismatch_drop( &
                          reference_step, response_step, response_curv, 1.0_dp)
         model_calibrated_drop = MAX(0.0_dp, model_drop - model_gap_drop)
         IF (model_gap_factor*response_trust > EPSILON(response_trust)) &
            model_gap_ratio = model_gap/(model_gap_factor*response_trust)
         ready = model_ready .AND. model_slope > EPSILON(model_slope) .AND. &
                 model_calibrated_drop > EPSILON(model_calibrated_drop) .AND. &
                 response_weighted_step <= response_trust .AND. &
                 response_abs_step <= response_abs_trust .AND. &
                 candidate_residual_ratio <= MIN(1.0_dp, reference_residual_ratio) + &
                 256.0_dp*EPSILON(1.0_dp) .AND. &
                 ALL(energy_step == energy_step)
         IF (.NOT. ready) THEN
            rotation_step(:) = 0.0_dp
            energy_step(:) = 0.0_dp
         END IF
         DEALLOCATE (candidate_residual, reference_residual, reference_step, response_step, &
                     rhs_local, schur_local)

      END SUBROUTINE build_kpoint_ot_coupled_prediction_candidate

! **************************************************************************************************
!> \brief Add a finite coupled-secant correction to an established fixed-N candidate.
!>
!>        The reduced multisecant model is used only in the measured rotation span.  Its solution
!>        is an affine correction around the candidate already selected by the established
!>        projector/density model.  The associated energy increment is R times that correction;
!>        the established energy and density step is retained instead of being replaced by an
!>        independent auxiliary-energy Newton step.
!> \param rotation_hessian ...
!> \param rotation_residual_hessian ...
!> \param response_metric ...
!> \param rotation_modes accepted complex rotation secants defining the measured subspace
!> \param rotation_targets ...
!> \param rotation_residual_weight physical diagonal rotation-gradient metric
!> \param rotation_step_weight diagonal coordinate metric used to project the established step
!> \param response ...
!> \param response_raw ...
!> \param rotation_gradient ...
!> \param energy_gradient ...
!> \param rotation_base_step established rotation candidate
!> \param energy_base_step ...
!> \param established_model_slope linear term of the established candidate
!> \param established_model_quadratic quadratic term of the established candidate
!> \param established_model_calibrated_drop trusted decrease of the established candidate
!> \param occ_curv ...
!> \param tether_curv ...
!> \param occ_curv_sum ...
!> \param channel_nmo ...
!> \param e_offset ...
!> \param rotation_floor ...
!> \param response_curv ...
!> \param response_curv_sum ...
!> \param response_trust ...
!> \param response_abs_trust ...
!> \param model_gap_factor ...
!> \param rotation_step ...
!> \param energy_step ...
!> \param direction_scale ...
!> \param model_slope ...
!> \param model_quadratic ...
!> \param model_drop ...
!> \param model_calibrated_drop ...
!> \param model_gap ...
!> \param model_gap_drop ...
!> \param model_gap_ratio ...
!> \param response_weighted_step ...
!> \param response_abs_step ...
!> \param predicted_residual_ratio ...
!> \param reference_residual_ratio minimum predicted physical residual on the established step ray
!> \param predicted_residual_start_sq physical residual norm squared before the candidate
!> \param predicted_residual_delta_dot affine physical residual cross term
!> \param predicted_residual_delta_sq affine physical residual change norm squared
!> \param measured_response_used ...
!> \param ready ...
!> \param use_measured_response ...
!> \param full_rotation_gradient stable full-pair physical gradient for residual prediction
!> \param full_rotation_targets accepted full-pair gradient changes for the active secant modes
!> \param full_rotation_modes rotation modes associated with full_rotation_targets when they differ
!>        from the modes used to construct the reduced correction
!> \param full_rotation_hessian analytic full-pair response to active rotation coordinates
!> \param full_rotation_residual_weight physical metric in the stable full-pair ordering
!> \param full_rotation_index full-pair index of every active rotation coordinate
!> \param replace_base_subspace replace rather than increment the reference component in the
!>        measured rotation span
!> \param contract_complete_step contract the complete candidate to its quadratic descent minimum
!> \param pareto_blend_with_base minimize the physical residual between the established candidate
!>        and the finite-position candidate while retaining the established Mermin decrease
!> \param base_blend_scale finite-response fraction in the resulting Pareto candidate
!> \param rebase_established_model preserve the accepted base curvature and add only the
!>        finite-response correction and cross terms
! **************************************************************************************************
      SUBROUTINE build_kpoint_ot_reduced_secant_candidate( &
         rotation_hessian, rotation_residual_hessian, response_metric, rotation_modes, &
         rotation_targets, rotation_residual_weight, rotation_step_weight, response, response_raw, &
         rotation_gradient, energy_gradient, &
         rotation_base_step, energy_base_step, established_model_slope, &
         established_model_quadratic, established_model_calibrated_drop, occ_curv, tether_curv, &
         occ_curv_sum, channel_nmo, e_offset, rotation_floor, response_curv, response_curv_sum, &
         response_trust, response_abs_trust, model_gap_factor, rotation_step, energy_step, &
         direction_scale, model_slope, model_quadratic, model_drop, model_calibrated_drop, &
         model_gap, model_gap_drop, model_gap_ratio, response_weighted_step, response_abs_step, &
         predicted_residual_ratio, reference_residual_ratio, predicted_residual_start_sq, &
         predicted_residual_delta_dot, predicted_residual_delta_sq, measured_response_used, ready, &
         use_measured_response, full_rotation_gradient, full_rotation_targets, full_rotation_modes, &
         full_rotation_hessian, &
         full_rotation_residual_weight, full_rotation_index, replace_base_subspace, &
         contract_complete_step, pareto_blend_with_base, base_blend_scale, &
         rebase_established_model)
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: rotation_hessian, &
                                                            rotation_residual_hessian, &
                                                            response_metric
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN), TARGET :: rotation_modes
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: rotation_targets
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: rotation_residual_weight, &
                                                            rotation_step_weight
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: response, response_raw
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: rotation_gradient, energy_gradient, &
                                                            rotation_base_step, energy_base_step
      REAL(KIND=dp), INTENT(IN) :: established_model_slope, established_model_quadratic, &
         established_model_calibrated_drop
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: occ_curv, tether_curv
      REAL(KIND=dp), INTENT(IN)                          :: occ_curv_sum
      INTEGER, DIMENSION(:), INTENT(IN)                  :: channel_nmo, e_offset
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: rotation_floor, response_curv
      REAL(KIND=dp), INTENT(IN)                          :: response_curv_sum, response_trust, &
                                                            response_abs_trust, model_gap_factor
      REAL(KIND=dp), DIMENSION(:), INTENT(OUT)           :: rotation_step, energy_step
      REAL(KIND=dp), INTENT(OUT) :: direction_scale, model_slope, model_quadratic, model_drop, &
         model_calibrated_drop, model_gap, model_gap_drop, model_gap_ratio, &
         response_weighted_step, response_abs_step, predicted_residual_ratio, &
         reference_residual_ratio, predicted_residual_start_sq, predicted_residual_delta_dot, &
         predicted_residual_delta_sq
      LOGICAL, INTENT(OUT)                               :: measured_response_used, ready
      LOGICAL, INTENT(IN), OPTIONAL                      :: use_measured_response
      REAL(KIND=dp), DIMENSION(:), INTENT(IN), OPTIONAL  :: full_rotation_gradient
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN), &
         OPTIONAL                                        :: full_rotation_targets
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN), &
         OPTIONAL, TARGET                                :: full_rotation_modes
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN), &
         OPTIONAL                                        :: full_rotation_hessian
      REAL(KIND=dp), DIMENSION(:), INTENT(IN), OPTIONAL  :: full_rotation_residual_weight
      INTEGER, DIMENSION(:), INTENT(IN), OPTIONAL        :: full_rotation_index
      LOGICAL, INTENT(IN), OPTIONAL                      :: replace_base_subspace, &
                                                            contract_complete_step, &
                                                            pareto_blend_with_base
      REAL(KIND=dp), INTENT(OUT), OPTIONAL               :: base_blend_scale
      LOGICAL, INTENT(IN), OPTIONAL                      :: rebase_established_model

      INTEGER                                            :: modal_rank, nener, nfull, nfull_modes, &
                                                            nrot, r
      LOGICAL :: base_ready, base_residual_minimum_ready, complete_contraction_requested, &
         correction_ready, current_residual_ready, full_residual_requested, &
         full_response_requested, measured_response_requested, model_ready, &
         pareto_blend_requested, pareto_ready, rebase_established_requested, &
         replacement_requested, residual_minimum_ready, residual_step_ready, subspace_ready, &
         trial_ready
      REAL(KIND=dp) :: base_drop, base_quadratic, base_residual_delta_dot, base_residual_delta_sq, &
         base_residual_minimum_position, base_residual_start_sq, base_slope, complete_step_scale, &
         correction_cross, correction_direction_scale, correction_drop, correction_quadratic, &
         correction_slope, current_residual_alpha, current_residual_ratio, current_residual_scale, &
         floor_quadratic, increment_slope, modal_shift, model_increment, pareto_delta_dot, &
         pareto_delta_sq, pareto_drop, pareto_reference_drop, pareto_residual_ratio, pareto_scale, &
         pareto_start_sq, replacement_reference_residual_ratio
      REAL(KIND=dp) :: residual_direction_scale, residual_minimum_position, response_abs_unit, &
         response_cross, response_weighted_unit, rotation_residual_alpha, rotation_residual_ratio, &
         schur_gradient_fraction, schur_model_residual, trial_drop, trial_quadratic, trial_slope
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:) :: base_response, base_rotation_residual, &
         correction_energy, correction_rotation, correction_rotation_residual, model_response, &
         raw_response, rhs_local, total_response
      REAL(KIND=dp), ALLOCATABLE, DIMENSION(:, :)        :: residual_hessian, schur_reference
      REAL(KIND=dp), DIMENSION(:, :), POINTER            :: full_rotation_response_modes

         nrot = SIZE(rotation_gradient)
         nener = SIZE(energy_gradient)
         CPASSERT(ALL(SHAPE(rotation_hessian) == [nrot, nrot]))
         CPASSERT(ALL(SHAPE(rotation_residual_hessian) == [nrot, nrot]))
         CPASSERT(ALL(SHAPE(response_metric) == [nrot, nrot]))
         CPASSERT(SIZE(rotation_modes, 1) == nrot)
         CPASSERT(ALL(SHAPE(rotation_targets) == SHAPE(rotation_modes)))
         CPASSERT(SIZE(rotation_residual_weight) == nrot)
         CPASSERT(SIZE(rotation_step_weight) == nrot)
         CPASSERT(ALL(SHAPE(response) == [nener, nrot]))
         CPASSERT(ALL(SHAPE(response_raw) == [nener, nrot]))
         CPASSERT(SIZE(rotation_base_step) == nrot)
         CPASSERT(SIZE(energy_base_step) == nener)
         CPASSERT(SIZE(rotation_floor) == nrot)
         CPASSERT(SIZE(rotation_step) == nrot)
         CPASSERT(SIZE(energy_step) == nener)

         rotation_step(:) = 0.0_dp
         energy_step(:) = 0.0_dp
         direction_scale = 0.0_dp
         model_slope = 0.0_dp
         model_quadratic = 0.0_dp
         model_drop = 0.0_dp
         model_calibrated_drop = 0.0_dp
         model_gap = 0.0_dp
         model_gap_drop = 0.0_dp
         model_gap_ratio = 0.0_dp
         response_weighted_step = 0.0_dp
         response_abs_step = 0.0_dp
         predicted_residual_ratio = 1.0_dp
         reference_residual_ratio = 1.0_dp
         predicted_residual_start_sq = 0.0_dp
         predicted_residual_delta_dot = 0.0_dp
         predicted_residual_delta_sq = 0.0_dp
         measured_response_used = .FALSE.
         ready = .FALSE.
         IF (PRESENT(base_blend_scale)) base_blend_scale = 0.0_dp
         replacement_requested = .FALSE.
         IF (PRESENT(replace_base_subspace)) replacement_requested = replace_base_subspace
         complete_contraction_requested = .FALSE.
         IF (PRESENT(contract_complete_step)) &
            complete_contraction_requested = contract_complete_step
         pareto_blend_requested = .FALSE.
         IF (PRESENT(pareto_blend_with_base)) &
            pareto_blend_requested = pareto_blend_with_base
         rebase_established_requested = .FALSE.
         IF (PRESENT(rebase_established_model)) &
            rebase_established_requested = rebase_established_model
         CPASSERT(.NOT. (complete_contraction_requested .AND. rebase_established_requested))
         measured_response_requested = .FALSE.
         IF (PRESENT(use_measured_response)) measured_response_requested = use_measured_response
         measured_response_requested = measured_response_requested .AND. .NOT. replacement_requested
         full_residual_requested = PRESENT(full_rotation_gradient)
         CPASSERT(PRESENT(full_rotation_residual_weight) .EQV. full_residual_requested)
         CPASSERT(PRESENT(full_rotation_index) .EQV. full_residual_requested)
         full_response_requested = PRESENT(full_rotation_targets)
         CPASSERT(.NOT. full_response_requested .OR. full_residual_requested)
         CPASSERT(.NOT. PRESENT(full_rotation_modes) .OR. full_response_requested)
         CPASSERT(.NOT. PRESENT(full_rotation_hessian) .OR. full_response_requested)
         nfull = nrot
         IF (full_residual_requested) THEN
            nfull = SIZE(full_rotation_gradient)
            CPASSERT(SIZE(full_rotation_residual_weight) == nfull)
            CPASSERT(ALL(full_rotation_residual_weight >= 0.0_dp))
            CPASSERT(SIZE(full_rotation_index) == nrot)
            CPASSERT(ALL(full_rotation_index > 0 .AND. full_rotation_index <= nfull))
         END IF
         IF (full_response_requested) THEN
            full_rotation_response_modes => rotation_modes
            IF (PRESENT(full_rotation_modes)) full_rotation_response_modes => full_rotation_modes
            CPASSERT(SIZE(full_rotation_response_modes, 1) == nrot)
            nfull_modes = SIZE(full_rotation_response_modes, 2)
            CPASSERT(SIZE(full_rotation_targets, 1) == nfull)
            CPASSERT(SIZE(full_rotation_targets, 2) == nfull_modes)
            IF (PRESENT(full_rotation_hessian)) THEN
               CPASSERT(ALL(SHAPE(full_rotation_hessian) == [nfull, nrot]))
            END IF
         END IF
         IF (nrot <= 0 .OR. nener <= 0) RETURN

         ALLOCATE (base_response(nener), base_rotation_residual(nrot), correction_energy(nener), &
                   correction_rotation(nrot), correction_rotation_residual(nrot), &
                   model_response(nener), raw_response(nener), rhs_local(nrot), &
                   total_response(nener), residual_hessian(nrot, nrot), &
                   schur_reference(nrot, nrot))
         schur_reference(:, :) = 0.5_dp*(rotation_hessian + TRANSPOSE(rotation_hessian)) - &
                                 0.5_dp*(response_metric + TRANSPOSE(response_metric))
         schur_reference(:, :) = 0.5_dp*(schur_reference + TRANSPOSE(schur_reference))
         residual_hessian(:, :) = rotation_residual_hessian
         IF (replacement_requested) THEN
            ! Endpoint-local response covectors do not define raw-gradient targets for the
            ! historical residual Hessian. Use the replacement energy Hessian here; accepted
            ! endpoints still provide the independent physical-residual calibration.
            residual_hessian(:, :) = rotation_hessian
         END IF
         rhs_local(:) = rotation_gradient + MATMUL(TRANSPOSE(response), energy_gradient)
         replacement_reference_residual_ratio = 0.0_dp
         IF (replacement_requested) THEN
            CALL qs_scf_kp_reduced_subspace_replacement_step( &
               schur_reference, rhs_local, rotation_modes, rotation_floor, rotation_base_step, &
               correction_rotation, subspace_ready, modal_rank, modal_shift, schur_model_residual, &
               replacement_reference_residual_ratio, schur_gradient_fraction)
            IF (subspace_ready) correction_rotation(:) = correction_rotation - rotation_base_step
         ELSE
            rhs_local(:) = rhs_local - MATMUL(schur_reference, rotation_base_step)
            CALL qs_scf_kp_reduced_subspace_step( &
               schur_reference, rhs_local, rotation_modes, rotation_floor, correction_rotation, &
               subspace_ready, modal_rank, modal_shift, schur_model_residual, &
               schur_gradient_fraction)
         END IF
         IF (.NOT. subspace_ready) THEN
            DEALLOCATE (base_response, base_rotation_residual, correction_energy, &
                        correction_rotation, correction_rotation_residual, model_response, &
                        raw_response, rhs_local, total_response, residual_hessian, schur_reference)
            RETURN
         END IF

         base_response(:) = MATMUL(response, rotation_base_step)
         correction_energy(:) = MATMUL(response, correction_rotation)
         raw_response(:) = MATMUL(response_raw, correction_rotation)
         model_response(:) = correction_energy(:)
         CALL project_kpoint_ot_schur_response(base_response, occ_curv, tether_curv, &
                                               occ_curv_sum, channel_nmo, e_offset)
         CALL project_kpoint_ot_schur_response(raw_response, occ_curv, tether_curv, &
                                               occ_curv_sum, channel_nmo, e_offset)
         CALL project_kpoint_ot_schur_response(model_response, occ_curv, tether_curv, &
                                               occ_curv_sum, channel_nmo, e_offset)
         correction_energy(:) = model_response(:)
         total_response(:) = base_response + correction_energy
         base_rotation_residual(:) = rotation_gradient - &
                                     MATMUL(residual_hessian, rotation_base_step)
         correction_rotation_residual(:) = -MATMUL(residual_hessian, correction_rotation)
         DO r = 1, nrot
            CALL kpoint_ot_mixed_projected_term( &
               energy_base_step, response(:, r), occ_curv, tether_curv, occ_curv_sum, &
               channel_nmo, e_offset, response_cross)
            base_rotation_residual(r) = base_rotation_residual(r) + response_cross
            CALL kpoint_ot_mixed_projected_term( &
               correction_energy, response(:, r), occ_curv, tether_curv, occ_curv_sum, &
               channel_nmo, e_offset, response_cross)
            correction_rotation_residual(r) = correction_rotation_residual(r) + response_cross
         END DO
         IF (full_residual_requested) THEN
            CALL qs_scf_kp_active_residual_affine( &
               full_rotation_gradient, rotation_gradient, base_rotation_residual, &
               full_rotation_index, full_rotation_residual_weight, base_residual_start_sq, &
               base_residual_delta_dot, base_residual_delta_sq, reference_residual_ratio)
         ELSE
            base_residual_start_sq = &
               DOT_PRODUCT(rotation_residual_weight, rotation_gradient**2)
            base_residual_delta_dot = &
               DOT_PRODUCT(rotation_residual_weight, rotation_gradient* &
                           (base_rotation_residual - rotation_gradient))
            base_residual_delta_sq = &
               DOT_PRODUCT(rotation_residual_weight, &
                           (base_rotation_residual - rotation_gradient)**2)
         END IF
         CALL qs_scf_kp_affine_residual_minimum( &
            base_residual_start_sq, base_residual_delta_dot, base_residual_delta_sq, 1.0_dp, &
            base_residual_minimum_position, reference_residual_ratio, &
            base_residual_minimum_ready)
         IF (.NOT. base_residual_minimum_ready) reference_residual_ratio = 1.0_dp
         CALL evaluate_kpoint_ot_projected_coupled_step_model( &
            rotation_gradient, energy_gradient, rotation_hessian, rotation_base_step, &
            energy_base_step, base_response, occ_curv, tether_curv, occ_curv_sum, channel_nmo, &
            e_offset, base_slope, base_quadratic, base_drop, base_ready)
         CALL evaluate_kpoint_ot_projected_coupled_step_model( &
            rotation_gradient, energy_gradient, rotation_hessian, correction_rotation, &
            correction_energy, model_response, occ_curv, tether_curv, occ_curv_sum, channel_nmo, &
            e_offset, correction_slope, correction_quadratic, correction_drop, correction_ready)
         rotation_step(:) = rotation_base_step + correction_rotation
         energy_step(:) = energy_base_step + correction_energy
         CALL evaluate_kpoint_ot_projected_coupled_step_model( &
            rotation_gradient, energy_gradient, rotation_hessian, rotation_step, energy_step, &
            total_response, occ_curv, tether_curv, occ_curv_sum, channel_nmo, e_offset, &
            trial_slope, trial_quadratic, trial_drop, trial_ready)
         IF (.NOT. base_ready .OR. .NOT. correction_ready .OR. .NOT. trial_ready) THEN
            rotation_step(:) = 0.0_dp
            energy_step(:) = 0.0_dp
            DEALLOCATE (base_response, base_rotation_residual, correction_energy, &
                        correction_rotation, correction_rotation_residual, model_response, &
                        raw_response, rhs_local, total_response, residual_hessian, schur_reference)
            RETURN
         END IF

         IF (measured_response_requested) THEN
            BLOCK
               INTEGER :: measured_base_rank, measured_full_base_rank, &
                          measured_full_correction_rank, measured_rank
               LOGICAL                                      :: measured_base_ready, &
                                                               measured_correction_ready, &
                                                               measured_full_base_ready, &
                                                               measured_full_correction_ready, &
                                                               measured_model_ready, &
                                                               measured_residual_minimum_ready, &
                                                               measured_subspace_ready, &
                                                               measured_trial_ready
               REAL(KIND=dp) :: measured_base_capture, measured_base_ratio, measured_capture, &
                                measured_correction_cross, &
                                measured_correction_drop, measured_correction_quadratic, &
                                measured_correction_slope, measured_direction_scale, measured_increment_slope, &
                                measured_model_drop, measured_model_increment, measured_model_quadratic, &
                                measured_model_slope, &
                                measured_full_base_capture, measured_full_base_ratio, &
                                measured_full_correction_capture, measured_full_correction_ratio, &
                                measured_residual_ratio, &
                                measured_residual_minimum_position, measured_scaled_residual_ratio, &
                                measured_trial_drop, measured_trial_quadratic, measured_trial_slope
               REAL(KIND=dp), ALLOCATABLE, DIMENSION(:) :: measured_base_projection, &
                                                           measured_base_residual, measured_base_target_response, &
                                                           measured_correction_energy, measured_correction_rotation, &
                                                           measured_energy_step, measured_residual_reduction, measured_response, &
                                                           measured_rotation_step, measured_scaled_residual, &
                                                           measured_total_response
               REAL(KIND=dp), ALLOCATABLE, DIMENSION(:) :: measured_full_base_projection, &
                                                           measured_full_base_response, measured_full_correction_projection, &
                                                           measured_full_correction_response, measured_full_residual, &
                                                           measured_full_scaled_residual

               ALLOCATE (measured_base_projection(nrot), measured_base_residual(nrot), &
                         measured_base_target_response(nrot), measured_correction_energy(nener), &
                         measured_correction_rotation(nrot), measured_residual_reduction(nrot), &
                         measured_response(nener), measured_rotation_step(nrot), &
                         measured_scaled_residual(nrot), &
                         measured_full_base_projection(nrot), &
                         measured_full_base_response(nfull), &
                         measured_full_correction_projection(nrot), &
                         measured_full_correction_response(nfull), measured_full_residual(nfull), &
                         measured_full_scaled_residual(nfull), &
                         measured_energy_step(nener), measured_total_response(nener))
               measured_correction_energy(:) = 0.0_dp
               measured_correction_rotation(:) = 0.0_dp
               measured_response(:) = 0.0_dp
               measured_full_base_projection(:) = 0.0_dp
               measured_full_base_response(:) = 0.0_dp
               measured_full_correction_projection(:) = 0.0_dp
               measured_full_correction_response(:) = 0.0_dp
               measured_full_residual(:) = 0.0_dp
               measured_full_scaled_residual(:) = 0.0_dp
               measured_full_base_ready = .FALSE.
               measured_full_correction_ready = .FALSE.
               CALL qs_scf_kp_measured_residual_subspace_step( &
                  rotation_base_step, rotation_targets, rotation_modes, rotation_step_weight, &
                  measured_base_target_response, measured_base_projection, measured_base_ready, &
                  measured_base_rank, measured_base_ratio, measured_base_capture)
               measured_base_residual(:) = rotation_gradient
               IF (measured_base_ready) &
                  measured_base_residual(:) = measured_base_residual - measured_base_target_response
               CALL qs_scf_kp_measured_residual_subspace_step( &
                  measured_base_residual, rotation_modes, rotation_targets, rotation_residual_weight, &
                  measured_correction_rotation, measured_residual_reduction, measured_subspace_ready, &
                  measured_rank, measured_residual_ratio, measured_capture)
               IF (full_response_requested .AND. measured_subspace_ready) THEN
                  CALL qs_scf_kp_measured_residual_subspace_step( &
                     rotation_base_step, full_rotation_targets, full_rotation_response_modes, &
                     rotation_step_weight, &
                     measured_full_base_response, measured_full_base_projection, &
                     measured_full_base_ready, measured_full_base_rank, measured_full_base_ratio, &
                     measured_full_base_capture)
                  CALL qs_scf_kp_measured_residual_subspace_step( &
                     measured_correction_rotation, full_rotation_targets, &
                     full_rotation_response_modes, &
                     rotation_step_weight, measured_full_correction_response, &
                     measured_full_correction_projection, measured_full_correction_ready, &
                     measured_full_correction_rank, measured_full_correction_ratio, &
                     measured_full_correction_capture)
                  IF (PRESENT(full_rotation_hessian)) THEN
                     CALL qs_scf_kp_add_full_response_complement( &
                        rotation_base_step, measured_full_base_projection, &
                        full_rotation_hessian, measured_full_base_response)
                     CALL qs_scf_kp_add_full_response_complement( &
                        measured_correction_rotation, measured_full_correction_projection, &
                        full_rotation_hessian, measured_full_correction_response)
                  ELSE
                     CALL qs_scf_kp_add_measured_response_complement( &
                        rotation_base_step, measured_full_base_projection, schur_reference, &
                        full_rotation_index, measured_full_base_response)
                     CALL qs_scf_kp_add_measured_response_complement( &
                        measured_correction_rotation, measured_full_correction_projection, &
                        schur_reference, full_rotation_index, measured_full_correction_response)
                  END IF
                  measured_full_residual(:) = full_rotation_gradient - measured_full_base_response
               END IF
               measured_model_drop = 0.0_dp
               measured_model_increment = 0.0_dp
               measured_model_quadratic = 0.0_dp
               measured_model_slope = 0.0_dp
               measured_direction_scale = 0.0_dp
               measured_increment_slope = 0.0_dp
               measured_correction_quadratic = 0.0_dp
               measured_correction_slope = 0.0_dp
               measured_residual_minimum_position = 0.0_dp
               measured_residual_minimum_ready = .FALSE.
               measured_scaled_residual_ratio = 1.0_dp
               IF (measured_subspace_ready) THEN
                  measured_response(:) = MATMUL(response, measured_correction_rotation)
                  CALL project_kpoint_ot_schur_response( &
                     measured_response, occ_curv, tether_curv, occ_curv_sum, channel_nmo, e_offset)
                  measured_correction_energy(:) = measured_response
                  CALL evaluate_kpoint_ot_projected_coupled_step_model( &
                     rotation_gradient, energy_gradient, rotation_hessian, &
                     measured_correction_rotation, measured_correction_energy, measured_response, &
                     occ_curv, tether_curv, occ_curv_sum, channel_nmo, e_offset, &
                     measured_correction_slope, measured_correction_quadratic, &
                     measured_correction_drop, measured_correction_ready)
                  measured_rotation_step(:) = rotation_base_step + measured_correction_rotation
                  measured_energy_step(:) = energy_base_step + measured_correction_energy
                  measured_total_response(:) = base_response + measured_response
                  CALL evaluate_kpoint_ot_projected_coupled_step_model( &
                     rotation_gradient, energy_gradient, rotation_hessian, measured_rotation_step, &
                     measured_energy_step, measured_total_response, occ_curv, tether_curv, &
                     occ_curv_sum, channel_nmo, e_offset, measured_trial_slope, &
                     measured_trial_quadratic, measured_trial_drop, measured_trial_ready)
                  IF (measured_correction_ready .AND. measured_trial_ready) THEN
                     measured_correction_cross = 0.5_dp* &
                                                 (measured_trial_quadratic - base_quadratic - &
                                                  measured_correction_quadratic)
                     measured_increment_slope = measured_correction_slope - &
                                                measured_correction_cross
                     measured_direction_scale = 1.0_dp
                     IF (measured_correction_quadratic > EPSILON(measured_correction_quadratic)) &
                        measured_direction_scale = MIN(measured_direction_scale, &
                                                       measured_increment_slope/ &
                                                       measured_correction_quadratic)
                     IF (measured_increment_slope > EPSILON(measured_increment_slope) .AND. &
                         measured_direction_scale > EPSILON(measured_direction_scale)) THEN
                        measured_rotation_step(:) = rotation_base_step + &
                                                    measured_direction_scale* &
                                                    measured_correction_rotation
                        measured_energy_step(:) = energy_base_step + &
                                                  measured_direction_scale*measured_correction_energy
                        measured_total_response(:) = base_response + &
                                                     measured_direction_scale*measured_response
                        CALL qs_scf_kp_affine_correction_model( &
                           base_slope, established_model_quadratic, &
                           measured_correction_slope, measured_correction_quadratic, &
                           measured_correction_cross, measured_direction_scale, measured_model_slope, &
                           measured_model_quadratic, measured_model_drop, measured_model_increment, &
                           measured_model_ready)
                        measured_scaled_residual(:) = measured_base_residual - &
                                                      measured_direction_scale*measured_residual_reduction
                        IF (full_response_requested .AND. measured_full_correction_ready) THEN
                           measured_full_scaled_residual(:) = measured_full_residual - &
                                                              measured_direction_scale*measured_full_correction_response
                           predicted_residual_start_sq = &
                              DOT_PRODUCT(full_rotation_residual_weight, full_rotation_gradient**2)
                           predicted_residual_delta_dot = &
                              DOT_PRODUCT(full_rotation_residual_weight, full_rotation_gradient* &
                                          (measured_full_scaled_residual - full_rotation_gradient))
                           predicted_residual_delta_sq = &
                              DOT_PRODUCT(full_rotation_residual_weight, &
                                          (measured_full_scaled_residual - full_rotation_gradient)**2)
                        ELSE
                           predicted_residual_start_sq = &
                              DOT_PRODUCT(rotation_residual_weight, rotation_gradient**2)
                           predicted_residual_delta_dot = &
                              DOT_PRODUCT(rotation_residual_weight, rotation_gradient* &
                                          (measured_scaled_residual - rotation_gradient))
                           predicted_residual_delta_sq = &
                              DOT_PRODUCT(rotation_residual_weight, &
                                          (measured_scaled_residual - rotation_gradient)**2)
                        END IF
                        CALL qs_scf_kp_affine_residual_minimum( &
                           predicted_residual_start_sq, predicted_residual_delta_dot, &
                           predicted_residual_delta_sq, 1.0_dp, measured_residual_minimum_position, &
                           measured_scaled_residual_ratio, measured_residual_minimum_ready)
                        measured_model_ready = measured_model_ready .AND. measured_residual_minimum_ready
                     ELSE
                        measured_model_ready = .FALSE.
                     END IF
                  ELSE
                     measured_model_ready = .FALSE.
                  END IF
               ELSE
                  measured_model_ready = .FALSE.
               END IF
               IF (logger%iter_info%print_level >= debug_print_level .AND. &
                   logger%para_env%is_source()) &
                  WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I2,3(1X,L1),13(1X,ES16.8))') &
                  " OT Schur measured-residual affine candidate rank base subspace model bratio bcapture "// &
                  "rratio capture sratio spos ilinear iquad alpha drop bdrop rnorm enorm:", &
                  measured_rank, measured_base_ready, measured_subspace_ready, measured_model_ready, &
                  measured_base_ratio, measured_base_capture, measured_residual_ratio, measured_capture, &
                  measured_scaled_residual_ratio, measured_residual_minimum_position, &
                  measured_increment_slope, &
                  measured_correction_quadratic, measured_direction_scale, measured_model_drop, &
                  base_drop, &
                  SQRT(MAX(0.0_dp, DOT_PRODUCT(measured_correction_rotation, &
                                               measured_correction_rotation))), &
                  SQRT(MAX(0.0_dp, DOT_PRODUCT(measured_correction_energy, &
                                               measured_correction_energy)))
               IF (measured_response_requested .AND. measured_model_ready) THEN
                  raw_response(:) = MATMUL(response_raw, measured_correction_rotation)
                  CALL project_kpoint_ot_schur_response( &
                     raw_response, occ_curv, tether_curv, occ_curv_sum, channel_nmo, e_offset)
                  response_abs_unit = MAXVAL(ABS(measured_response))
                  IF (.NOT. global_schur_replicated) CALL para_env_inter_kp%max(response_abs_unit)
                  response_weighted_unit = kpoint_ot_weighted_response_step( &
                                           measured_response, response_curv, response_curv_sum)
                  model_gap = measured_direction_scale*MAXVAL(ABS(measured_response - raw_response))
                  IF (.NOT. global_schur_replicated) CALL para_env_inter_kp%max(model_gap)
                  model_gap_drop = kpoint_ot_response_mismatch_drop( &
                                   raw_response, measured_response, response_curv, &
                                   measured_direction_scale)
                  direction_scale = measured_direction_scale
                  response_abs_step = direction_scale*response_abs_unit
                  response_weighted_step = direction_scale*response_weighted_unit
                  rotation_step(:) = measured_rotation_step
                  energy_step(:) = measured_energy_step
                  model_slope = measured_model_slope
                  model_quadratic = measured_model_quadratic
                  model_drop = measured_model_drop
                  model_calibrated_drop = qs_scf_kp_affine_rebased_drop( &
                                          established_model_slope, base_slope, &
                                          established_model_calibrated_drop, &
                                          measured_model_increment, model_gap_drop)
                  model_gap_ratio = 0.0_dp
                  IF (model_gap_factor*response_trust > EPSILON(response_trust)) &
                     model_gap_ratio = model_gap/(model_gap_factor*response_trust)
                  ready = model_calibrated_drop > established_model_calibrated_drop + &
                          EPSILON(MAX(model_drop, established_model_calibrated_drop))
                  IF (response_trust > EPSILON(response_trust)) &
                     ready = ready .AND. response_weighted_step <= response_trust
                  IF (response_abs_trust > EPSILON(response_abs_trust)) &
                     ready = ready .AND. response_abs_step <= response_abs_trust
                  IF (ready) THEN
                     predicted_residual_ratio = measured_scaled_residual_ratio
                     measured_response_used = .TRUE.
                     DEALLOCATE (measured_base_projection, measured_base_residual, &
                                 measured_base_target_response, measured_correction_energy, &
                                 measured_correction_rotation, measured_residual_reduction, &
                                 measured_response, measured_rotation_step, measured_scaled_residual, &
                                 measured_energy_step, measured_total_response, &
                                 measured_full_base_projection, measured_full_base_response, &
                                 measured_full_correction_projection, &
                                 measured_full_correction_response, measured_full_residual, &
                                 measured_full_scaled_residual)
                     DEALLOCATE (base_response, base_rotation_residual, correction_energy, &
                                 correction_rotation, correction_rotation_residual, model_response, &
                                 raw_response, rhs_local, total_response, residual_hessian, &
                                 schur_reference)
                     RETURN
                  END IF
               END IF
               DEALLOCATE (measured_base_projection, measured_base_residual, &
                           measured_base_target_response, measured_correction_energy, &
                           measured_correction_rotation, measured_residual_reduction, &
                           measured_response, measured_rotation_step, measured_scaled_residual, &
                           measured_energy_step, measured_total_response, &
                           measured_full_base_projection, measured_full_base_response, &
                           measured_full_correction_projection, measured_full_correction_response, &
                           measured_full_residual, measured_full_scaled_residual)
            END BLOCK
         END IF

         correction_cross = 0.5_dp*(trial_quadratic - base_quadratic - correction_quadratic)
         increment_slope = correction_slope - correction_cross
         direction_scale = 1.0_dp
         IF (correction_quadratic > EPSILON(correction_quadratic)) &
            direction_scale = MIN(direction_scale, increment_slope/correction_quadratic)
         CALL qs_scf_kp_residual_compatible_scale( &
            base_rotation_residual, correction_rotation_residual, direction_scale, &
            residual_direction_scale, rotation_residual_alpha, rotation_residual_ratio, &
            residual_step_ready, weight=rotation_residual_weight)
         CALL qs_scf_kp_residual_compatible_scale( &
            rotation_gradient, correction_rotation_residual, direction_scale, &
            current_residual_scale, current_residual_alpha, current_residual_ratio, &
            current_residual_ready, weight=rotation_residual_weight)
         IF (residual_step_ready) direction_scale = residual_direction_scale
         floor_quadratic = modal_shift*DOT_PRODUCT(correction_rotation, correction_rotation)
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I2,1X,L1,10(1X,ES16.8))') &
            " OT Schur reduced-secant KKT rank replacement sres refres gfrac floor bdrop "// &
            "ilinear iquad alpha rnorm enorm:", &
            modal_rank, replacement_requested, schur_model_residual, &
            replacement_reference_residual_ratio, schur_gradient_fraction, floor_quadratic, &
            base_drop, increment_slope, correction_quadratic, direction_scale, &
            SQRT(MAX(0.0_dp, DOT_PRODUCT(correction_rotation, correction_rotation))), &
            SQRT(MAX(0.0_dp, DOT_PRODUCT(correction_energy, correction_energy)))
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,L1,6(1X,ES16.8))') &
            " OT Schur reduced-secant affine rotation residual ready base delta alpha scale ratio dot:", &
            residual_step_ready, &
            SQRT(MAX(0.0_dp, DOT_PRODUCT(rotation_residual_weight, base_rotation_residual**2))), &
            SQRT(MAX(0.0_dp, DOT_PRODUCT(rotation_residual_weight, &
                                         correction_rotation_residual**2))), rotation_residual_alpha, &
            residual_direction_scale, rotation_residual_ratio, &
            DOT_PRODUCT(rotation_residual_weight, &
                        base_rotation_residual*correction_rotation_residual)
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,L1,5(1X,ES16.8))') &
            " OT Schur reduced-secant measured rotation residual ready current delta alpha scale ratio:", &
            current_residual_ready, &
            SQRT(MAX(0.0_dp, DOT_PRODUCT(rotation_residual_weight, rotation_gradient**2))), &
            SQRT(MAX(0.0_dp, DOT_PRODUCT(rotation_residual_weight, &
                                         correction_rotation_residual**2))), &
            current_residual_alpha, current_residual_scale, &
            current_residual_ratio
         IF (.NOT. residual_step_ready .OR. increment_slope <= EPSILON(increment_slope) .OR. &
             direction_scale <= EPSILON(direction_scale)) THEN
            rotation_step(:) = 0.0_dp
            energy_step(:) = 0.0_dp
            DEALLOCATE (base_response, base_rotation_residual, correction_energy, &
                        correction_rotation, correction_rotation_residual, model_response, &
                        raw_response, rhs_local, total_response, residual_hessian, schur_reference)
            RETURN
         END IF

         response_abs_unit = MAXVAL(ABS(correction_energy))
         IF (.NOT. global_schur_replicated) CALL para_env_inter_kp%max(response_abs_unit)
         response_weighted_unit = &
            kpoint_ot_weighted_response_step(correction_energy, response_curv, response_curv_sum)
         IF (response_trust > EPSILON(response_trust) .AND. &
             response_weighted_unit > EPSILON(response_weighted_unit)) &
            direction_scale = MIN(direction_scale, 0.8_dp*response_trust/response_weighted_unit)
         IF (response_abs_trust > EPSILON(response_abs_trust) .AND. &
             response_abs_unit > EPSILON(response_abs_unit)) &
            direction_scale = MIN(direction_scale, 0.8_dp*response_abs_trust/response_abs_unit)
         IF (direction_scale <= EPSILON(direction_scale)) THEN
            rotation_step(:) = 0.0_dp
            energy_step(:) = 0.0_dp
            DEALLOCATE (base_response, base_rotation_residual, correction_energy, &
                        correction_rotation, correction_rotation_residual, model_response, &
                        raw_response, rhs_local, total_response, residual_hessian, schur_reference)
            RETURN
         END IF

         model_gap = direction_scale*MAXVAL(ABS(model_response - raw_response))
         IF (.NOT. global_schur_replicated) CALL para_env_inter_kp%max(model_gap)
         model_gap_drop = kpoint_ot_response_mismatch_drop(raw_response, model_response, &
                                                           response_curv, direction_scale)
         response_abs_step = direction_scale*response_abs_unit
         response_weighted_step = direction_scale*response_weighted_unit
         correction_direction_scale = direction_scale
         rotation_step(:) = rotation_base_step + correction_direction_scale*correction_rotation
         energy_step(:) = energy_base_step + correction_direction_scale*correction_energy
         total_response(:) = base_response + correction_direction_scale*model_response
         IF (rebase_established_requested) THEN
            CALL qs_scf_kp_affine_correction_model( &
               base_slope, established_model_quadratic, correction_slope, correction_quadratic, &
               correction_cross, correction_direction_scale, model_slope, model_quadratic, &
               model_drop, model_increment, model_ready)
         ELSE
            CALL evaluate_kpoint_ot_projected_coupled_step_model( &
               rotation_gradient, energy_gradient, rotation_hessian, rotation_step, energy_step, &
               total_response, occ_curv, tether_curv, occ_curv_sum, channel_nmo, e_offset, &
               model_slope, model_quadratic, model_drop, model_ready)
         END IF
         complete_step_scale = 1.0_dp
         IF (complete_contraction_requested .AND. model_ready) &
            complete_step_scale = qs_scf_kp_quadratic_descent_scale( &
                                  model_slope, model_quadratic, 1.0_dp)
         IF (complete_contraction_requested .AND. &
             complete_step_scale <= EPSILON(complete_step_scale)) model_ready = .FALSE.
         IF (model_ready .AND. complete_step_scale < 1.0_dp) THEN
            rotation_step(:) = complete_step_scale*rotation_step
            energy_step(:) = complete_step_scale*energy_step
            total_response(:) = complete_step_scale*total_response
            model_gap = complete_step_scale*model_gap
            model_gap_drop = complete_step_scale*complete_step_scale*model_gap_drop
            response_abs_step = complete_step_scale*response_abs_step
            response_weighted_step = complete_step_scale*response_weighted_step
            CALL evaluate_kpoint_ot_projected_coupled_step_model( &
               rotation_gradient, energy_gradient, rotation_hessian, rotation_step, energy_step, &
               total_response, occ_curv, tether_curv, occ_curv_sum, channel_nmo, e_offset, &
               model_slope, model_quadratic, model_drop, model_ready)
         END IF
         direction_scale = correction_direction_scale*complete_step_scale
         IF (rebase_established_requested) THEN
            model_calibrated_drop = qs_scf_kp_affine_rebased_drop( &
                                    established_model_slope, base_slope, &
                                    established_model_calibrated_drop, model_increment, &
                                    model_gap_drop)
         ELSE
            model_calibrated_drop = MAX(0.0_dp, model_drop - model_gap_drop)
         END IF
         IF (model_gap_factor*response_trust > EPSILON(response_trust)) &
            model_gap_ratio = model_gap/(model_gap_factor*response_trust)
         IF (rebase_established_requested) THEN
            ready = model_ready .AND. model_calibrated_drop > &
                    established_model_calibrated_drop + &
                    EPSILON(MAX(model_drop, established_model_calibrated_drop))
         ELSE
            ready = model_ready .AND. model_calibrated_drop > &
                    base_drop + EPSILON(MAX(model_drop, base_drop))
         END IF
         IF (response_trust > EPSILON(response_trust)) &
            ready = ready .AND. response_weighted_step <= response_trust
         IF (response_abs_trust > EPSILON(response_abs_trust)) &
            ready = ready .AND. response_abs_step <= response_abs_trust
         IF (.NOT. ready) THEN
            rotation_step(:) = 0.0_dp
            energy_step(:) = 0.0_dp
         ELSE
            rhs_local(:) = base_rotation_residual + &
                           correction_direction_scale*correction_rotation_residual
            IF (complete_step_scale < 1.0_dp) &
               rhs_local(:) = rotation_gradient + &
                              complete_step_scale*(rhs_local - rotation_gradient)
            IF (pareto_blend_requested) THEN
               correction_rotation(:) = rotation_step - rotation_base_step
               correction_energy(:) = energy_step - energy_base_step
               model_response(:) = total_response - base_response
               correction_rotation_residual(:) = rhs_local - base_rotation_residual
               CALL evaluate_kpoint_ot_projected_coupled_step_model( &
                  rotation_gradient, energy_gradient, rotation_hessian, correction_rotation, &
                  correction_energy, model_response, occ_curv, tether_curv, occ_curv_sum, &
                  channel_nmo, e_offset, correction_slope, correction_quadratic, correction_drop, &
                  correction_ready)
               IF (rebase_established_requested) THEN
                  correction_cross = 0.5_dp* &
                                     (model_quadratic - established_model_quadratic - &
                                      correction_quadratic)
               ELSE
                  correction_cross = 0.5_dp* &
                                     (model_quadratic - base_quadratic - correction_quadratic)
               END IF
               increment_slope = correction_slope - correction_cross
               IF (full_residual_requested) THEN
                  IF (full_response_requested .AND. .NOT. measured_response_requested) THEN
                     BLOCK
                        INTEGER :: full_base_rank, full_correction_rank
                        LOGICAL :: full_base_ready, full_correction_ready
                        REAL(KIND=dp) :: full_base_capture, full_base_ratio, &
                                         full_correction_capture, full_correction_ratio
                        REAL(KIND=dp), ALLOCATABLE, DIMENSION(:) :: full_base_projection, &
                                                                    full_base_response, full_base_residual, full_correction_delta, &
                                                                    full_correction_projection, full_correction_response

                        ALLOCATE (full_base_projection(nrot), full_base_response(nfull), &
                                  full_base_residual(nfull), full_correction_delta(nfull), &
                                  full_correction_projection(nrot), &
                                  full_correction_response(nfull))
                        CALL qs_scf_kp_measured_residual_subspace_step( &
                           rotation_base_step, full_rotation_targets, full_rotation_response_modes, &
                           rotation_step_weight, full_base_response, full_base_projection, &
                           full_base_ready, full_base_rank, full_base_ratio, full_base_capture)
                        CALL qs_scf_kp_measured_residual_subspace_step( &
                           correction_rotation, full_rotation_targets, full_rotation_response_modes, &
                           rotation_step_weight, full_correction_response, &
                           full_correction_projection, full_correction_ready, &
                           full_correction_rank, full_correction_ratio, full_correction_capture)
                        IF (PRESENT(full_rotation_hessian)) THEN
                           CALL qs_scf_kp_add_full_response_complement( &
                              rotation_base_step, full_base_projection, full_rotation_hessian, &
                              full_base_response)
                           CALL qs_scf_kp_add_full_response_complement( &
                              correction_rotation, full_correction_projection, &
                              full_rotation_hessian, full_correction_response)
                        END IF
                        CALL qs_scf_kp_full_residual_completion( &
                           full_rotation_gradient, base_rotation_residual, full_rotation_index, &
                           full_base_response, full_base_residual)
                        full_correction_delta(:) = -full_correction_response
                        DO r = 1, nrot
                           full_correction_delta(full_rotation_index(r)) = &
                              correction_rotation_residual(r)
                        END DO
                        pareto_start_sq = DOT_PRODUCT(full_rotation_residual_weight, &
                                                      full_base_residual**2)
                        pareto_delta_dot = DOT_PRODUCT(full_rotation_residual_weight, &
                                                       full_base_residual*full_correction_delta)
                        pareto_delta_sq = DOT_PRODUCT(full_rotation_residual_weight, &
                                                      full_correction_delta**2)
                        DEALLOCATE (full_base_projection, full_base_response, full_base_residual, &
                                    full_correction_delta, full_correction_projection, &
                                    full_correction_response)
                     END BLOCK
                  ELSE
                     pareto_start_sq = DOT_PRODUCT(full_rotation_residual_weight, &
                                                   full_rotation_gradient**2)
                     pareto_delta_dot = 0.0_dp
                     pareto_delta_sq = 0.0_dp
                     DO r = 1, nrot
                        pareto_start_sq = pareto_start_sq + &
                                          full_rotation_residual_weight(full_rotation_index(r))* &
                                          (base_rotation_residual(r)**2 - &
                                           full_rotation_gradient(full_rotation_index(r))**2)
                        pareto_delta_dot = pareto_delta_dot + &
                                           full_rotation_residual_weight(full_rotation_index(r))* &
                                           base_rotation_residual(r)* &
                                           correction_rotation_residual(r)
                        pareto_delta_sq = pareto_delta_sq + &
                                          full_rotation_residual_weight(full_rotation_index(r))* &
                                          correction_rotation_residual(r)**2
                     END DO
                  END IF
               ELSE
                  pareto_start_sq = DOT_PRODUCT(rotation_residual_weight, &
                                                base_rotation_residual**2)
                  pareto_delta_dot = DOT_PRODUCT(rotation_residual_weight, &
                                                 base_rotation_residual* &
                                                 correction_rotation_residual)
                  pareto_delta_sq = DOT_PRODUCT(rotation_residual_weight, &
                                                correction_rotation_residual**2)
               END IF
               pareto_reference_drop = base_drop
               IF (rebase_established_requested) &
                  pareto_reference_drop = established_model_calibrated_drop
               CALL qs_scf_kp_mermin_residual_pareto_blend( &
                  pareto_reference_drop, increment_slope, correction_quadratic, pareto_start_sq, &
                  pareto_delta_dot, pareto_delta_sq, 1.0_dp, 1.0_dp, pareto_scale, pareto_drop, &
                  pareto_residual_ratio, pareto_ready)
               IF (PRESENT(base_blend_scale) .AND. pareto_ready) &
                  base_blend_scale = pareto_scale
               IF (pareto_ready .AND. pareto_scale < 1.0_dp) THEN
                  rotation_step(:) = rotation_base_step + pareto_scale*correction_rotation
                  energy_step(:) = energy_base_step + pareto_scale*correction_energy
                  total_response(:) = base_response + pareto_scale*model_response
                  rhs_local(:) = base_rotation_residual + &
                                 pareto_scale*correction_rotation_residual
                  model_gap = pareto_scale*model_gap
                  model_gap_drop = pareto_scale*pareto_scale*model_gap_drop
                  response_abs_step = pareto_scale*response_abs_step
                  response_weighted_step = pareto_scale*response_weighted_step
                  direction_scale = pareto_scale*direction_scale
                  IF (rebase_established_requested) THEN
                     CALL qs_scf_kp_affine_correction_model( &
                        base_slope, established_model_quadratic, correction_slope, &
                        correction_quadratic, correction_cross, pareto_scale, model_slope, &
                        model_quadratic, model_drop, model_increment, model_ready)
                     model_calibrated_drop = qs_scf_kp_affine_rebased_drop( &
                                             established_model_slope, base_slope, &
                                             established_model_calibrated_drop, model_increment, &
                                             model_gap_drop)
                  ELSE
                     CALL evaluate_kpoint_ot_projected_coupled_step_model( &
                        rotation_gradient, energy_gradient, rotation_hessian, rotation_step, &
                        energy_step, total_response, occ_curv, tether_curv, occ_curv_sum, &
                        channel_nmo, e_offset, model_slope, model_quadratic, model_drop, model_ready)
                     model_calibrated_drop = MAX(0.0_dp, model_drop - model_gap_drop)
                  END IF
                  IF (model_gap_factor*response_trust > EPSILON(response_trust)) &
                     model_gap_ratio = model_gap/(model_gap_factor*response_trust)
                  IF (rebase_established_requested) THEN
                     ready = model_ready .AND. model_calibrated_drop > &
                             established_model_calibrated_drop + &
                             EPSILON(MAX(model_drop, established_model_calibrated_drop))
                  ELSE
                     ready = model_ready .AND. model_calibrated_drop > &
                             base_drop + EPSILON(MAX(model_drop, base_drop))
                  END IF
               END IF
            END IF
            IF (full_residual_requested) THEN
               IF (full_response_requested .AND. .NOT. measured_response_requested) THEN
                  BLOCK
                     INTEGER :: full_response_rank
                     LOGICAL :: full_response_ready
                     REAL(KIND=dp) :: full_response_capture, full_response_ratio
                     REAL(KIND=dp), ALLOCATABLE, DIMENSION(:) :: full_response, &
                                                                 full_response_projection, full_trial_residual

                     ALLOCATE (full_response(nfull), full_response_projection(nrot), &
                               full_trial_residual(nfull))
                     CALL qs_scf_kp_measured_residual_subspace_step( &
                        rotation_step, full_rotation_targets, full_rotation_response_modes, &
                        rotation_step_weight, &
                        full_response, full_response_projection, full_response_ready, &
                        full_response_rank, full_response_ratio, full_response_capture)
                     IF (PRESENT(full_rotation_hessian)) &
                        CALL qs_scf_kp_add_full_response_complement( &
                        rotation_step, full_response_projection, full_rotation_hessian, &
                        full_response)
                     CALL qs_scf_kp_full_residual_completion( &
                        full_rotation_gradient, rhs_local, full_rotation_index, full_response, &
                        full_trial_residual)
                     predicted_residual_start_sq = &
                        DOT_PRODUCT(full_rotation_residual_weight, full_rotation_gradient**2)
                     predicted_residual_delta_dot = &
                        DOT_PRODUCT(full_rotation_residual_weight, full_rotation_gradient* &
                                    (full_trial_residual - full_rotation_gradient))
                     predicted_residual_delta_sq = &
                        DOT_PRODUCT(full_rotation_residual_weight, &
                                    (full_trial_residual - full_rotation_gradient)**2)
                     predicted_residual_ratio = 1.0_dp
                     IF (predicted_residual_start_sq > EPSILON(predicted_residual_start_sq)) &
                        predicted_residual_ratio = SQRT(MAX(0.0_dp, &
                                                            DOT_PRODUCT(full_rotation_residual_weight, &
                                                                        full_trial_residual**2))/ &
                                                        predicted_residual_start_sq)
                     DEALLOCATE (full_response, full_response_projection, full_trial_residual)
                  END BLOCK
               ELSE
                  CALL qs_scf_kp_active_residual_affine( &
                     full_rotation_gradient, rotation_gradient, rhs_local, full_rotation_index, &
                     full_rotation_residual_weight, predicted_residual_start_sq, &
                     predicted_residual_delta_dot, predicted_residual_delta_sq, &
                     predicted_residual_ratio)
               END IF
            ELSE
               predicted_residual_start_sq = &
                  DOT_PRODUCT(rotation_residual_weight, rotation_gradient**2)
               predicted_residual_delta_dot = &
                  DOT_PRODUCT(rotation_residual_weight, rotation_gradient* &
                              (rhs_local - rotation_gradient))
               predicted_residual_delta_sq = &
                  DOT_PRODUCT(rotation_residual_weight, (rhs_local - rotation_gradient)**2)
               IF (predicted_residual_start_sq > EPSILON(predicted_residual_start_sq)) &
                  predicted_residual_ratio = SQRT(MAX(0.0_dp, &
                                                      DOT_PRODUCT(rotation_residual_weight, &
                                                                  rhs_local**2))/ &
                                                  predicted_residual_start_sq)
            END IF
            CALL qs_scf_kp_affine_residual_minimum( &
               predicted_residual_start_sq, predicted_residual_delta_dot, &
               predicted_residual_delta_sq, 1.0_dp, residual_minimum_position, &
               predicted_residual_ratio, residual_minimum_ready)
            ready = ready .AND. residual_minimum_ready
            IF (.NOT. ready) THEN
               rotation_step(:) = 0.0_dp
               energy_step(:) = 0.0_dp
            END IF
            ! The replacement response is measured from accepted endpoint-local frozen-H
            ! secants and validated out of sample.  It may therefore collect line-search
            ! calibration even though the incompatible raw-gradient target audit is skipped.
            measured_response_used = replacement_requested .AND. ready
         END IF
         DEALLOCATE (base_response, base_rotation_residual, correction_energy, correction_rotation, &
                     correction_rotation_residual, model_response, raw_response, rhs_local, &
                     total_response, residual_hessian, schur_reference)

      END SUBROUTINE build_kpoint_ot_reduced_secant_candidate

! **************************************************************************************************
!> \brief Evaluate the coupled quadratic model in the projected fixed-N energy tangent space.
!> \param rotation_gradient ...
!> \param energy_gradient ...
!> \param rotation_hessian ...
!> \param rotation_step ...
!> \param energy_step ...
!> \param response_step R times rotation_step in the projected energy tangent space
!> \param occ_curv ...
!> \param tether_curv ...
!> \param occ_curv_sum ...
!> \param channel_nmo ...
!> \param e_offset ...
!> \param model_slope ...
!> \param model_quadratic ...
!> \param model_drop ...
!> \param ready ...
! **************************************************************************************************
      SUBROUTINE evaluate_kpoint_ot_projected_coupled_step_model( &
         rotation_gradient, energy_gradient, rotation_hessian, rotation_step, energy_step, &
         response_step, occ_curv, tether_curv, occ_curv_sum, channel_nmo, e_offset, &
         model_slope, model_quadratic, model_drop, ready)
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: rotation_gradient, energy_gradient
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: rotation_hessian
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: rotation_step, energy_step, &
                                                            response_step, occ_curv, tether_curv
      REAL(KIND=dp), INTENT(IN)                          :: occ_curv_sum
      INTEGER, DIMENSION(:), INTENT(IN)                  :: channel_nmo, e_offset
      REAL(KIND=dp), INTENT(OUT)                         :: model_slope, model_quadratic, model_drop
      LOGICAL, INTENT(OUT)                               :: ready

      INTEGER                                            :: nener, nrot
      REAL(KIND=dp)                                      :: energy_quadratic, response_cross

         nrot = SIZE(rotation_step)
         nener = SIZE(energy_step)
         CPASSERT(SIZE(rotation_gradient) == nrot)
         CPASSERT(SIZE(energy_gradient) == nener)
         CPASSERT(SIZE(response_step) == nener)
         CPASSERT(ALL(SHAPE(rotation_hessian) == [nrot, nrot]))

         model_slope = DOT_PRODUCT(rotation_gradient, rotation_step) + &
                       DOT_PRODUCT(energy_gradient, energy_step)
         CALL kpoint_ot_mixed_projected_term( &
            energy_step, energy_step, occ_curv, tether_curv, occ_curv_sum, channel_nmo, e_offset, &
            energy_quadratic)
         CALL kpoint_ot_mixed_projected_term( &
            energy_step, response_step, occ_curv, tether_curv, occ_curv_sum, channel_nmo, e_offset, &
            response_cross)
         model_quadratic = DOT_PRODUCT(rotation_step, MATMUL(rotation_hessian, rotation_step)) + &
                           energy_quadratic - 2.0_dp*response_cross
         model_drop = MAX(0.0_dp, model_slope - 0.5_dp*model_quadratic)
         ready = model_slope == model_slope .AND. model_quadratic == model_quadratic .AND. &
                 model_drop == model_drop .AND. ABS(model_slope) < HUGE(model_slope) .AND. &
                 ABS(model_quadratic) < HUGE(model_quadratic) .AND. model_drop < HUGE(model_drop)
         IF (.NOT. ready) THEN
            model_slope = 0.0_dp
            model_quadratic = 0.0_dp
            model_drop = 0.0_dp
         END IF

      END SUBROUTINE evaluate_kpoint_ot_projected_coupled_step_model

! **************************************************************************************************
!> \brief Compare the finite coupled Hessian with the last accepted complex OT vector secant.
!> \param target_group fixed-N spin group
!> \param channel_nmo number of local MOs for every global channel
!> \param channel_full_var_offset first full rotation variable for every global channel
!> \param e_offset first auxiliary-energy variable for every global channel
!> \param var_channel global channel for every rotation variable
!> \param var_i first MO index for every rotation variable
!> \param var_j second MO index for every rotation variable
!> \param var_kind real (1) or imaginary (2) rotation component
!> \param occ_curv occupation curvature
!> \param tether_curv canonical tether curvature
!> \param rotation_hessian finite complex rotation block
!> \param energy_hessian dense fixed-N auxiliary-energy block
!> \param energy_cross signed rotation/energy cross block
!> \param energy_response projected fixed-N E^-1 B response used by the active energy solve
!> \param response_metric fixed-N metric Gram matrix of energy_response
!> \param residual_delta current fixed-N Mermin residual
!> \param active_subspace rotations were restricted to the thermal Fermi subspace
!> \param rotation_hessian_secant accepted-secant rotation candidate
!> \param rotation_hessian_multisecant compatible two-secant rotation candidate
!> \param rotation_hessian_reduced_secant direct coupled fixed-N multisecant in the analytic Schur block
!> \param energy_hessian_multisecant analytic energy block carried by the active candidate
!> \param energy_cross_multisecant analytic signed cross block carried by the active candidate
!> \param reduced_secant_full_targets measured gradient changes in the stable full-pair ordering
!> \param reduced_secant_modes accepted complex rotation modes defining the reduced candidate span
!> \param reduced_secant_targets measured raw complex rotation-gradient changes for those modes
!> \param update_ready whether the candidate passed the physical trust gate
!> \param multisecant_update_ready whether the two-secant candidate passed its geometry gate
!> \param prediction_update_ready whether the bidirectionally predicted coupled candidate is stable
!> \param prediction_residual_ratio worst held-out residual ratio of the bidirectional prediction
!> \param reduced_secant_shadow_ready whether the reduced coupled shadow passed its geometry gate
!> \param reduced_secant_replacement_ready whether the shadow is the validated frozen-H replacement
!> \param closure_response_steps accepted rotation steps for the closure response
!> \param closure_response_targets measured fixed-N closure response for those steps
!> \param closure_response_pair_ready whether at least two accepted closure secants are available
!> \param closure_coupled_full_rotation full-space fitted rotation-block correction
!> \param closure_coupled_full_energy full-space fitted auxiliary-energy-block correction
!> \param closure_coupled_full_cross full-space fitted signed cross-block correction
!> \param closure_predictive_rotation newest-trained analytic-Hessian residual rotation correction
!> \param closure_predictive_energy newest-trained analytic-Hessian residual energy correction
!> \param closure_predictive_cross newest-trained analytic-Hessian residual cross correction
!> \param closure_predictive_finite whether both directional prediction audits are finite
!> \param closure_predictive_consistent whether both predictions pass the physical-response gate
!> \param closure_predictive_work_consistent whether observable Hessian work is reproducible
!> \param closure_predictive_overlap minimum scaled step overlap
!> \param closure_predictive_capture minimum training-response capture
!> \param closure_predictive_quality minimum full-residual prediction quality
!> \param closure_predictive_rotation_quality minimum rotation-residual prediction quality
!> \param closure_predictive_energy_quality minimum auxiliary-energy-residual prediction quality
!> \param closure_predictive_work_quality minimum observable Hessian-work prediction quality
!> \param closure_predictive_alignment minimum response alignment
!> \param closure_predictive_curvature_min minimum bidirectional curvature ratio
!> \param closure_predictive_curvature_max maximum bidirectional curvature ratio
!> \param closure_coupled_response reduced response from the full rotation/energy closure fit
!> \param closure_coupled_ready whether the full-space fit and Schur transport succeeded
!> \param closure_coupled_independence independence of the scaled coupled steps
!> \param closure_coupled_compatibility symmetric-secant compatibility correction
!> \param closure_coupled_capture fraction of the closure residual in the fitted subspace
!> \param closure_coupled_residual_ratio fitted/full closure-residual norm ratio
!> \param closure_coupled_transport_ratio relative reduced Schur correction
! **************************************************************************************************
      SUBROUTINE audit_kpoint_ot_vector_secant_model(target_group, channel_nmo, &
                                                     channel_full_var_offset, e_offset, &
                                                     var_channel, var_i, var_j, var_kind, &
                                                     occ_curv, tether_curv, rotation_hessian, &
                                                     energy_hessian, energy_cross, energy_response, &
                                                     response_metric, residual_delta, &
                                                     active_subspace, rotation_hessian_secant, &
                                                     rotation_hessian_multisecant, &
                                                     rotation_hessian_reduced_secant, &
                                                     energy_hessian_multisecant, &
                                                     energy_cross_multisecant, &
                                                     reduced_secant_full_targets, reduced_secant_modes, &
                                                     reduced_secant_targets, update_ready, &
                                                     multisecant_update_ready, &
                                                     prediction_update_ready, &
                                                     prediction_residual_ratio, &
                                                     reduced_secant_shadow_ready, &
                                                     reduced_secant_replacement_ready, &
                                                     closure_response_steps, &
                                                     closure_response_targets, &
                                                     closure_response_pair_ready, &
                                                     closure_coupled_full_rotation, &
                                                     closure_coupled_full_energy, &
                                                     closure_coupled_full_cross, &
                                                     closure_predictive_rotation, &
                                                     closure_predictive_energy, &
                                                     closure_predictive_cross, &
                                                     closure_predictive_finite, &
                                                     closure_predictive_consistent, &
                                                     closure_predictive_work_consistent, &
                                                     closure_predictive_overlap, &
                                                     closure_predictive_capture, &
                                                     closure_predictive_quality, &
                                                     closure_predictive_rotation_quality, &
                                                     closure_predictive_energy_quality, &
                                                     closure_predictive_work_quality, &
                                                     closure_predictive_alignment, &
                                                     closure_predictive_curvature_min, &
                                                     closure_predictive_curvature_max, &
                                                     closure_coupled_response, &
                                                     closure_coupled_ready, &
                                                     closure_coupled_independence, &
                                                     closure_coupled_compatibility, &
                                                     closure_coupled_capture, &
                                                     closure_coupled_residual_ratio, &
                                                     closure_coupled_transport_ratio)
      INTEGER, INTENT(IN)                                :: target_group
      INTEGER, DIMENSION(:), INTENT(IN)                  :: channel_nmo, channel_full_var_offset, &
                                                            e_offset, var_channel, var_i, var_j, &
                                                            var_kind
      REAL(KIND=dp), DIMENSION(:), INTENT(IN)            :: occ_curv, tether_curv
      REAL(KIND=dp), DIMENSION(:, :), INTENT(IN)         :: rotation_hessian, energy_hessian, &
                                                            energy_cross, energy_response, &
                                                            response_metric
      REAL(KIND=dp), INTENT(IN)                          :: residual_delta
      LOGICAL, INTENT(IN)                                :: active_subspace
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT) :: rotation_hessian_secant, &
         rotation_hessian_multisecant, rotation_hessian_reduced_secant, &
         energy_hessian_multisecant, energy_cross_multisecant, reduced_secant_full_targets, &
         reduced_secant_modes, reduced_secant_targets
      LOGICAL, INTENT(OUT)                               :: update_ready, multisecant_update_ready, &
                                                            prediction_update_ready
      REAL(KIND=dp), INTENT(OUT)                         :: prediction_residual_ratio
      LOGICAL, INTENT(OUT) :: reduced_secant_shadow_ready, reduced_secant_replacement_ready
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: closure_response_steps, &
                                                            closure_response_targets
      LOGICAL, INTENT(OUT)                               :: closure_response_pair_ready
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT) :: closure_coupled_full_rotation, &
         closure_coupled_full_energy, closure_coupled_full_cross, closure_predictive_rotation, &
         closure_predictive_energy, closure_predictive_cross
      LOGICAL, INTENT(OUT) :: closure_predictive_finite, closure_predictive_consistent, &
         closure_predictive_work_consistent
      REAL(KIND=dp), INTENT(OUT) :: closure_predictive_overlap, closure_predictive_capture, &
         closure_predictive_quality, closure_predictive_rotation_quality, &
         closure_predictive_energy_quality, closure_predictive_work_quality, &
         closure_predictive_alignment, closure_predictive_curvature_min, &
         closure_predictive_curvature_max
      REAL(KIND=dp), DIMENSION(:, :), INTENT(OUT)        :: closure_coupled_response
      LOGICAL, INTENT(OUT)                               :: closure_coupled_ready
      REAL(KIND=dp), INTENT(OUT) :: closure_coupled_independence, closure_coupled_compatibility, &
         closure_coupled_capture, closure_coupled_residual_ratio, closure_coupled_transport_ratio

      INTEGER :: active_energy_count, directional_subspace_correction_rank, &
         directional_subspace_rank, global_channel, global_spin, group, ie, ifull, imo, iobs, jmo, &
         local_channel, nclosure_observations, nener, nmo, nrot, nrot_full, r, valid_i
      LOGICAL :: closure_anchor_valid, closure_coupled_fit_ready, closure_coupled_transport_ready, &
         closure_previous_valid, closure_secant_valid, coupled_multisecant_finite, &
         coupled_multisecant_ready, coupled_prediction_finite, coupled_prediction_reverse_finite, &
         coupled_schur_eligible, coupled_schur_finite, coupled_subspace_eligible, &
         coupled_subspace_finite, directional_subspace_finite, directional_subspace_ready, &
         directional_update_finite, directional_update_ready, frozen_candidate_eligible, &
         frozen_endpoint_multisecant_finite, frozen_prediction_consistent, full_update_ready, &
         multisecant_finite
      LOGICAL :: previous_frozen_reduced_valid, previous_valid, reduced_multisecant_eligible, &
         reduced_multisecant_finite, reduced_prediction_consistent, reduced_prediction_finite, &
         reduced_prediction_reverse_finite, rotation_multisecant_ready, update_finite, valid
      LOGICAL, DIMENSION(2)                              :: frozen_prediction_finite
      LOGICAL, DIMENSION(3)                              :: work_projection_applied
