      REAL(KIND=dp), DIMENSION(3)                        :: work_after, work_before, work_ratio

         nrot = SIZE(var_channel)
         nrot_full = SIZE(reduced_secant_full_targets, 1)
         nener = SIZE(occ_curv)
         CPASSERT(ALL(SHAPE(rotation_hessian_secant) == SHAPE(rotation_hessian)))
         CPASSERT(ALL(SHAPE(rotation_hessian_multisecant) == SHAPE(rotation_hessian)))
         CPASSERT(ALL(SHAPE(rotation_hessian_reduced_secant) == SHAPE(rotation_hessian)))
         CPASSERT(ALL(SHAPE(closure_response_steps) == [nrot, 3]))
         CPASSERT(ALL(SHAPE(closure_response_targets) == [nrot, 3]))
         CPASSERT(ALL(SHAPE(closure_coupled_full_rotation) == [nrot, nrot]))
         CPASSERT(ALL(SHAPE(closure_coupled_full_energy) == [nener, nener]))
         CPASSERT(ALL(SHAPE(closure_coupled_full_cross) == [nener, nrot]))
         CPASSERT(ALL(SHAPE(closure_predictive_rotation) == [nrot, nrot]))
         CPASSERT(ALL(SHAPE(closure_predictive_energy) == [nener, nener]))
         CPASSERT(ALL(SHAPE(closure_predictive_cross) == [nener, nrot]))
         CPASSERT(ALL(SHAPE(closure_coupled_response) == [nrot, nrot]))
         CPASSERT(ALL(SHAPE(energy_hessian_multisecant) == SHAPE(energy_hessian)))
         CPASSERT(ALL(SHAPE(energy_cross_multisecant) == SHAPE(energy_cross)))
         CPASSERT(ALL(SHAPE(reduced_secant_modes) == [nrot, 2]))
         CPASSERT(ALL(SHAPE(reduced_secant_targets) == [nrot, 2]))
         CPASSERT(SIZE(reduced_secant_full_targets, 2) == 2)
         CPASSERT(ALL(SHAPE(energy_response) == SHAPE(energy_cross)))
         CPASSERT(ALL(SHAPE(response_metric) == SHAPE(rotation_hessian)))
         rotation_hessian_secant(:, :) = rotation_hessian(:, :)
         rotation_hessian_multisecant(:, :) = rotation_hessian(:, :)
         rotation_hessian_reduced_secant(:, :) = rotation_hessian(:, :)
         energy_hessian_multisecant(:, :) = energy_hessian(:, :)
         energy_cross_multisecant(:, :) = energy_cross(:, :)
         reduced_secant_modes(:, :) = 0.0_dp
         reduced_secant_targets(:, :) = 0.0_dp
         reduced_secant_full_targets(:, :) = 0.0_dp
         closure_response_steps(:, :) = 0.0_dp
         closure_response_targets(:, :) = 0.0_dp
         closure_coupled_full_rotation(:, :) = 0.0_dp
         closure_coupled_full_energy(:, :) = 0.0_dp
         closure_coupled_full_cross(:, :) = 0.0_dp
         closure_predictive_rotation(:, :) = 0.0_dp
         closure_predictive_energy(:, :) = 0.0_dp
         closure_predictive_cross(:, :) = 0.0_dp
         closure_predictive_finite = .FALSE.
         closure_predictive_consistent = .FALSE.
         closure_predictive_work_consistent = .FALSE.
         closure_predictive_overlap = 0.0_dp
         closure_predictive_capture = 0.0_dp
         closure_predictive_quality = 0.0_dp
         closure_predictive_rotation_quality = 0.0_dp
         closure_predictive_energy_quality = 0.0_dp
         closure_predictive_work_quality = 0.0_dp
         closure_predictive_alignment = 0.0_dp
         closure_predictive_curvature_min = 0.0_dp
         closure_predictive_curvature_max = 0.0_dp
         closure_coupled_response(:, :) = 0.0_dp
         closure_coupled_ready = .FALSE.
         closure_coupled_independence = 0.0_dp
         closure_coupled_compatibility = 0.0_dp
         closure_coupled_capture = 0.0_dp
         closure_coupled_residual_ratio = 0.0_dp
         closure_coupled_transport_ratio = 0.0_dp
         closure_coupled_fit_ready = .FALSE.
         closure_coupled_transport_ready = .FALSE.
         closure_coupled_cross_ratio = 0.0_dp
         closure_coupled_energy_ratio = 0.0_dp
         closure_coupled_rotation_ratio = 0.0_dp
         update_ready = .FALSE.
         multisecant_update_ready = .FALSE.
         prediction_update_ready = .FALSE.
         prediction_residual_ratio = 1.0_dp
         rotation_multisecant_ready = .FALSE.
         reduced_secant_shadow_ready = .FALSE.
         reduced_secant_replacement_ready = .FALSE.
         closure_response_pair_ready = .FALSE.
         IF (nrot <= 0 .OR. nener <= 0) RETURN
         ALLOCATE (anchor_step_rotation(nrot), anchor_secant_rotation(nrot), &
                   anchor_closure_secant_rotation(nrot), &
                   anchor_closure_reduced_target(nrot), step_rotation(nrot), &
                   secant_rotation(nrot), closure_secant_rotation(nrot), &
                   frozen_secant_rotation(nrot), model_rotation(nrot), &
                   anchor_step_energy(nener), anchor_secant_energy(nener), &
                   anchor_closure_secant_energy(nener), &
                   step_energy(nener), secant_energy(nener), closure_secant_energy(nener), &
                   frozen_secant_energy(nener), model_energy(nener), &
                   model_rotation_base(nrot), model_rotation_cross(nrot), &
                   model_energy_base(nener), model_energy_cross(nener), &
                   previous_step_rotation(nrot), previous_secant_rotation(nrot), &
                   previous_step_energy(nener), previous_secant_energy(nener), &
                   previous_closure_secant_rotation(nrot), previous_frozen_secant_rotation(nrot), &
                   previous_closure_secant_energy(nener), previous_frozen_secant_energy(nener), &
                   previous_closure_reduced_target(nrot), &
                   previous_frozen_reduced_target(nrot), &
                   total_reduced_target(nrot), frozen_reduced_target(nrot), &
                   closure_reduced_target(nrot), reduced_model(nrot), total_reduced_prediction(nrot))
         anchor_step_rotation(:) = 0.0_dp
         anchor_secant_rotation(:) = 0.0_dp
         anchor_closure_secant_rotation(:) = 0.0_dp
         anchor_closure_reduced_target(:) = 0.0_dp
         step_rotation(:) = 0.0_dp
         secant_rotation(:) = 0.0_dp
         closure_secant_rotation(:) = 0.0_dp
         frozen_secant_rotation(:) = 0.0_dp
         model_rotation(:) = 0.0_dp
         anchor_step_energy(:) = 0.0_dp
         anchor_secant_energy(:) = 0.0_dp
         anchor_closure_secant_energy(:) = 0.0_dp
         step_energy(:) = 0.0_dp
         secant_energy(:) = 0.0_dp
         closure_secant_energy(:) = 0.0_dp
         frozen_secant_energy(:) = 0.0_dp
         model_energy(:) = 0.0_dp
         model_rotation_base(:) = 0.0_dp
         model_rotation_cross(:) = 0.0_dp
         model_energy_base(:) = 0.0_dp
         model_energy_cross(:) = 0.0_dp
         previous_step_rotation(:) = 0.0_dp
         previous_secant_rotation(:) = 0.0_dp
         previous_step_energy(:) = 0.0_dp
         previous_secant_energy(:) = 0.0_dp
         previous_closure_secant_rotation(:) = 0.0_dp
         previous_frozen_secant_rotation(:) = 0.0_dp
         previous_closure_secant_energy(:) = 0.0_dp
         previous_frozen_secant_energy(:) = 0.0_dp
         previous_closure_reduced_target(:) = 0.0_dp
         previous_frozen_reduced_target(:) = 0.0_dp
         total_reduced_target(:) = 0.0_dp
         frozen_reduced_target(:) = 0.0_dp
         closure_reduced_target(:) = 0.0_dp
         reduced_model(:) = 0.0_dp
         total_reduced_prediction(:) = 0.0_dp
         full_step_rotation_norm = 0.0_dp
         full_secant_rotation_norm = 0.0_dp
         previous_full_step_rotation_norm = 0.0_dp
         previous_full_secant_rotation_norm = 0.0_dp
         work_ratio_current = 1.0_dp
         work_ratio_previous = 1.0_dp
         work_ratio_anchor = 1.0_dp

         valid = .TRUE.
         previous_valid = .TRUE.
         closure_secant_valid = .TRUE.
         closure_previous_valid = .TRUE.
         closure_anchor_valid = .TRUE.
         previous_frozen_reduced_valid = .TRUE.
         DO local_channel = 1, SIZE(local_ot_env)
            global_channel = first_channel + local_channel - 1
            IF (global_channel < 1 .OR. global_channel > SIZE(channel_nmo)) CYCLE
            nmo = channel_nmo(global_channel)
            IF (nmo <= 0) CYCLE
            global_spin = MOD(global_channel - 1, nspin_ot) + 1
            group = MERGE(global_spin, 1, ngroups == nspin_ot)
            IF (group /= target_group) CYCLE
            work_ratio_current = local_ot_env(local_channel)%mermin_secant_work_ratio
            work_ratio_previous = local_ot_env(local_channel)%mermin_secant_work_ratio_previous
            work_ratio_anchor = local_ot_env(local_channel)%mermin_secant_work_ratio_anchor
            valid = valid .AND. local_ot_env(local_channel)%mermin_secant_ready .AND. &
                    ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_s) .AND. &
                    ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_s_im) .AND. &
                    ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_y) .AND. &
                    ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_y_im) .AND. &
                    ASSOCIATED(local_ot_env(local_channel)%ener_mermin_s) .AND. &
                    ASSOCIATED(local_ot_env(local_channel)%ener_mermin_y)
            previous_valid = previous_valid .AND. &
                             local_ot_env(local_channel)%mermin_secant_previous_ready .AND. &
                             ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_s_previous) .AND. &
                             ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_s_previous_im) .AND. &
                             ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_y_previous) .AND. &
                             ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_y_previous_im) .AND. &
                             ASSOCIATED(local_ot_env(local_channel)%ener_mermin_s_previous) .AND. &
                             ASSOCIATED(local_ot_env(local_channel)%ener_mermin_y_previous)
            closure_secant_valid = closure_secant_valid .AND. &
                                   local_ot_env(local_channel)%mermin_closure_secant_ready .AND. &
                                   ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_closure_y) .AND. &
                                   ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_closure_y_im) .AND. &
                                   ASSOCIATED(local_ot_env(local_channel)%ener_mermin_closure_y)
            closure_previous_valid = closure_previous_valid .AND. &
                                     local_ot_env(local_channel)%mermin_closure_secant_previous_ready .AND. &
                                     ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_closure_y_previous) .AND. &
                                     ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_closure_y_previous_im) .AND. &
                                     ASSOCIATED(local_ot_env(local_channel)%ener_mermin_closure_y_previous)
            closure_anchor_valid = closure_anchor_valid .AND. &
                                   local_ot_env(local_channel)%mermin_closure_secant_anchor_ready .AND. &
                                   ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_s_anchor) .AND. &
                                   ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_s_anchor_im) .AND. &
                                   ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_y_anchor) .AND. &
                                   ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_y_anchor_im) .AND. &
                                   ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_closure_y_anchor) .AND. &
                                   ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_closure_y_anchor_im) .AND. &
                                   ASSOCIATED(local_ot_env(local_channel)%ener_mermin_s_anchor) .AND. &
                                   ASSOCIATED(local_ot_env(local_channel)%ener_mermin_y_anchor) .AND. &
                                   ASSOCIATED(local_ot_env(local_channel)%ener_mermin_closure_y_anchor)
            previous_frozen_reduced_valid = previous_frozen_reduced_valid .AND. &
                                            local_ot_env(local_channel)%mermin_frozen_reduced_target_ready .AND. &
                                            ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_frozen_reduced_y) .AND. &
                                            ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_frozen_reduced_y_im)
            IF (.NOT. valid) CYCLE

            ALLOCATE (dense_re(nmo, nmo), dense_im(nmo, nmo))
            CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_mermin_s, dense_re)
            CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_mermin_s_im, dense_im)
            CALL local_ot_env(local_channel)%para_env%sum(dense_re)
            CALL local_ot_env(local_channel)%para_env%sum(dense_im)
            DO jmo = 2, nmo
               DO imo = 1, jmo - 1
                  full_step_rotation_norm = full_step_rotation_norm + &
                                            dense_re(imo, jmo)**2 + dense_im(imo, jmo)**2
               END DO
            END DO
            DO r = 1, nrot
               IF (var_channel(r) /= global_channel) CYCLE
               SELECT CASE (var_kind(r))
               CASE (1)
                  step_rotation(r) = dense_re(var_i(r), var_j(r))
               CASE (2)
                  step_rotation(r) = dense_im(var_i(r), var_j(r))
               END SELECT
            END DO
            CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_mermin_y, dense_re)
            CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_mermin_y_im, dense_im)
            CALL local_ot_env(local_channel)%para_env%sum(dense_re)
            CALL local_ot_env(local_channel)%para_env%sum(dense_im)
            DO imo = 1, nmo - 1
               DO jmo = imo + 1, nmo
                  full_secant_rotation_norm = full_secant_rotation_norm + &
                                              4.0_dp*(dense_re(imo, jmo)**2 + dense_im(imo, jmo)**2)
               END DO
            END DO
            ifull = channel_full_var_offset(global_channel) - 1
            DO imo = 1, nmo - 1
               DO jmo = imo + 1, nmo
                  ifull = ifull + 1
                  reduced_secant_full_targets(ifull, 2) = 2.0_dp*dense_re(imo, jmo)
                  ifull = ifull + 1
                  reduced_secant_full_targets(ifull, 2) = 2.0_dp*dense_im(imo, jmo)
               END DO
            END DO
            DO r = 1, nrot
               IF (var_channel(r) /= global_channel) CYCLE
               SELECT CASE (var_kind(r))
               CASE (1)
                  secant_rotation(r) = 2.0_dp*dense_re(var_i(r), var_j(r))
               CASE (2)
                  secant_rotation(r) = 2.0_dp*dense_im(var_i(r), var_j(r))
               END SELECT
            END DO
            IF (closure_secant_valid) THEN
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_mermin_closure_y, dense_re)
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_mermin_closure_y_im, dense_im)
               CALL local_ot_env(local_channel)%para_env%sum(dense_re)
               CALL local_ot_env(local_channel)%para_env%sum(dense_im)
               DO r = 1, nrot
                  IF (var_channel(r) /= global_channel) CYCLE
                  SELECT CASE (var_kind(r))
                  CASE (1)
                     closure_secant_rotation(r) = 2.0_dp*dense_re(var_i(r), var_j(r))
                  CASE (2)
                     closure_secant_rotation(r) = 2.0_dp*dense_im(var_i(r), var_j(r))
                  END SELECT
               END DO
               IF (closure_previous_valid) THEN
                  CALL dbcsr_square_to_dense( &
                     local_ot_env(local_channel)%rot_mat_mermin_closure_y_previous, dense_re)
                  CALL dbcsr_square_to_dense( &
                     local_ot_env(local_channel)%rot_mat_mermin_closure_y_previous_im, dense_im)
                  CALL local_ot_env(local_channel)%para_env%sum(dense_re)
                  CALL local_ot_env(local_channel)%para_env%sum(dense_im)
                  DO r = 1, nrot
                     IF (var_channel(r) /= global_channel) CYCLE
                     SELECT CASE (var_kind(r))
                     CASE (1)
                        previous_closure_secant_rotation(r) = &
                           2.0_dp*dense_re(var_i(r), var_j(r))
                     CASE (2)
                        previous_closure_secant_rotation(r) = &
                           2.0_dp*dense_im(var_i(r), var_j(r))
                     END SELECT
                  END DO
               END IF
            END IF
            IF (previous_valid) THEN
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_mermin_s_previous, dense_re)
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_mermin_s_previous_im, dense_im)
               CALL local_ot_env(local_channel)%para_env%sum(dense_re)
               CALL local_ot_env(local_channel)%para_env%sum(dense_im)
               DO jmo = 2, nmo
                  DO imo = 1, jmo - 1
                     previous_full_step_rotation_norm = previous_full_step_rotation_norm + &
                                                        dense_re(imo, jmo)**2 + dense_im(imo, jmo)**2
                  END DO
               END DO
               DO r = 1, nrot
                  IF (var_channel(r) /= global_channel) CYCLE
                  SELECT CASE (var_kind(r))
                  CASE (1)
                     previous_step_rotation(r) = dense_re(var_i(r), var_j(r))
                  CASE (2)
                     previous_step_rotation(r) = dense_im(var_i(r), var_j(r))
                  END SELECT
               END DO
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_mermin_y_previous, dense_re)
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_mermin_y_previous_im, dense_im)
               CALL local_ot_env(local_channel)%para_env%sum(dense_re)
               CALL local_ot_env(local_channel)%para_env%sum(dense_im)
               DO imo = 1, nmo - 1
                  DO jmo = imo + 1, nmo
                     previous_full_secant_rotation_norm = previous_full_secant_rotation_norm + &
                                                          4.0_dp*(dense_re(imo, jmo)**2 + dense_im(imo, jmo)**2)
                  END DO
               END DO
               ifull = channel_full_var_offset(global_channel) - 1
               DO imo = 1, nmo - 1
                  DO jmo = imo + 1, nmo
                     ifull = ifull + 1
                     reduced_secant_full_targets(ifull, 1) = 2.0_dp*dense_re(imo, jmo)
                     ifull = ifull + 1
                     reduced_secant_full_targets(ifull, 1) = 2.0_dp*dense_im(imo, jmo)
                  END DO
               END DO
               DO r = 1, nrot
                  IF (var_channel(r) /= global_channel) CYCLE
                  SELECT CASE (var_kind(r))
                  CASE (1)
                     previous_secant_rotation(r) = 2.0_dp*dense_re(var_i(r), var_j(r))
                  CASE (2)
                     previous_secant_rotation(r) = 2.0_dp*dense_im(var_i(r), var_j(r))
                  END SELECT
               END DO
            END IF
            IF (closure_anchor_valid) THEN
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_mermin_s_anchor, dense_re)
               CALL dbcsr_square_to_dense(local_ot_env(local_channel)%rot_mat_mermin_s_anchor_im, dense_im)
               CALL local_ot_env(local_channel)%para_env%sum(dense_re)
               CALL local_ot_env(local_channel)%para_env%sum(dense_im)
               DO r = 1, nrot
                  IF (var_channel(r) /= global_channel) CYCLE
                  SELECT CASE (var_kind(r))
                  CASE (1)
                     anchor_step_rotation(r) = dense_re(var_i(r), var_j(r))
                  CASE (2)
                     anchor_step_rotation(r) = dense_im(var_i(r), var_j(r))
                  END SELECT
               END DO
               CALL dbcsr_square_to_dense( &
                  local_ot_env(local_channel)%rot_mat_mermin_y_anchor, dense_re)
               CALL dbcsr_square_to_dense( &
                  local_ot_env(local_channel)%rot_mat_mermin_y_anchor_im, dense_im)
               CALL local_ot_env(local_channel)%para_env%sum(dense_re)
               CALL local_ot_env(local_channel)%para_env%sum(dense_im)
               DO r = 1, nrot
                  IF (var_channel(r) /= global_channel) CYCLE
                  SELECT CASE (var_kind(r))
                  CASE (1)
                     anchor_secant_rotation(r) = 2.0_dp*dense_re(var_i(r), var_j(r))
                  CASE (2)
                     anchor_secant_rotation(r) = 2.0_dp*dense_im(var_i(r), var_j(r))
                  END SELECT
               END DO
               CALL dbcsr_square_to_dense( &
                  local_ot_env(local_channel)%rot_mat_mermin_closure_y_anchor, dense_re)
               CALL dbcsr_square_to_dense( &
                  local_ot_env(local_channel)%rot_mat_mermin_closure_y_anchor_im, dense_im)
               CALL local_ot_env(local_channel)%para_env%sum(dense_re)
               CALL local_ot_env(local_channel)%para_env%sum(dense_im)
               DO r = 1, nrot
                  IF (var_channel(r) /= global_channel) CYCLE
                  SELECT CASE (var_kind(r))
                  CASE (1)
                     anchor_closure_secant_rotation(r) = &
                        2.0_dp*dense_re(var_i(r), var_j(r))
                  CASE (2)
                     anchor_closure_secant_rotation(r) = &
                        2.0_dp*dense_im(var_i(r), var_j(r))
                  END SELECT
               END DO
            END IF
            IF (previous_frozen_reduced_valid) THEN
               CALL dbcsr_square_to_dense( &
                  local_ot_env(local_channel)%rot_mat_mermin_frozen_reduced_y, dense_re)
               CALL dbcsr_square_to_dense( &
                  local_ot_env(local_channel)%rot_mat_mermin_frozen_reduced_y_im, dense_im)
               CALL local_ot_env(local_channel)%para_env%sum(dense_re)
               CALL local_ot_env(local_channel)%para_env%sum(dense_im)
               DO r = 1, nrot
                  IF (var_channel(r) /= global_channel) CYCLE
                  SELECT CASE (var_kind(r))
                  CASE (1)
                     previous_frozen_reduced_target(r) = dense_re(var_i(r), var_j(r))
                  CASE (2)
                     previous_frozen_reduced_target(r) = dense_im(var_i(r), var_j(r))
                  END SELECT
               END DO
            END IF
            DEALLOCATE (dense_re, dense_im)

            DO imo = 1, nmo
               ie = e_offset(global_channel) + imo - 1
               step_energy(ie) = local_ot_env(local_channel)%ener_mermin_s(imo)
               secant_energy(ie) = local_ot_env(local_channel)%ener_mermin_y(imo)
               IF (closure_secant_valid) &
                  closure_secant_energy(ie) = local_ot_env(local_channel)%ener_mermin_closure_y(imo)
               IF (previous_valid) THEN
                  previous_step_energy(ie) = local_ot_env(local_channel)%ener_mermin_s_previous(imo)
                  previous_secant_energy(ie) = local_ot_env(local_channel)%ener_mermin_y_previous(imo)
                  IF (closure_previous_valid) &
                     previous_closure_secant_energy(ie) = &
                     local_ot_env(local_channel)%ener_mermin_closure_y_previous(imo)
               END IF
               IF (closure_anchor_valid) THEN
                  anchor_step_energy(ie) = local_ot_env(local_channel)%ener_mermin_s_anchor(imo)
                  anchor_secant_energy(ie) = local_ot_env(local_channel)%ener_mermin_y_anchor(imo)
                  anchor_closure_secant_energy(ie) = &
                     local_ot_env(local_channel)%ener_mermin_closure_y_anchor(imo)
               END IF
            END DO
         END DO

         valid_i = MERGE(1, 0, valid)
         IF (global_schur_replicated) CALL para_env_inter_kp%min(valid_i)
         valid = valid_i > 0
         valid_i = MERGE(1, 0, previous_valid)
         IF (global_schur_replicated) CALL para_env_inter_kp%min(valid_i)
         previous_valid = valid_i > 0
         valid_i = MERGE(1, 0, closure_secant_valid)
         IF (global_schur_replicated) CALL para_env_inter_kp%min(valid_i)
         closure_secant_valid = valid_i > 0
         valid_i = MERGE(1, 0, closure_previous_valid)
         IF (global_schur_replicated) CALL para_env_inter_kp%min(valid_i)
         closure_previous_valid = valid_i > 0 .AND. previous_valid
         valid_i = MERGE(1, 0, closure_anchor_valid)
         IF (global_schur_replicated) CALL para_env_inter_kp%min(valid_i)
         closure_anchor_valid = valid_i > 0 .AND. closure_previous_valid
         valid_i = MERGE(1, 0, previous_frozen_reduced_valid)
         IF (global_schur_replicated) CALL para_env_inter_kp%min(valid_i)
         previous_frozen_reduced_valid = valid_i > 0 .AND. previous_valid
         IF (.NOT. valid) THEN
            DO local_channel = 1, SIZE(local_ot_env)
               global_channel = first_channel + local_channel - 1
               IF (global_channel < 1 .OR. global_channel > SIZE(channel_nmo)) CYCLE
               global_spin = MOD(global_channel - 1, nspin_ot) + 1
               group = MERGE(global_spin, 1, ngroups == nspin_ot)
               IF (group == target_group) &
                  local_ot_env(local_channel)%mermin_frozen_reduced_target_ready = .FALSE.
            END DO
            DEALLOCATE (anchor_step_rotation, anchor_secant_rotation, &
                        anchor_closure_secant_rotation, &
                        anchor_closure_reduced_target, step_rotation, secant_rotation, &
                        closure_secant_rotation, &
                        frozen_secant_rotation, model_rotation, step_energy, secant_energy, &
                        anchor_step_energy, anchor_secant_energy, anchor_closure_secant_energy, &
                        closure_secant_energy, &
                        frozen_secant_energy, model_energy, model_rotation_base, &
                        model_rotation_cross, model_energy_base, model_energy_cross, previous_step_rotation, &
                        previous_secant_rotation, previous_step_energy, previous_secant_energy, &
                        previous_closure_secant_rotation, previous_frozen_secant_rotation, &
                        previous_closure_secant_energy, previous_frozen_secant_energy, &
                        previous_closure_reduced_target, previous_frozen_reduced_target, &
                        total_reduced_target, frozen_reduced_target, closure_reduced_target, reduced_model, &
                        total_reduced_prediction)
            RETURN
         END IF
         IF (global_schur_replicated) THEN
            CALL para_env_inter_kp%sum(step_rotation)
            CALL para_env_inter_kp%sum(secant_rotation)
            CALL para_env_inter_kp%sum(step_energy)
            CALL para_env_inter_kp%sum(secant_energy)
            IF (closure_secant_valid) THEN
               CALL para_env_inter_kp%sum(closure_secant_rotation)
               CALL para_env_inter_kp%sum(closure_secant_energy)
            END IF
            CALL para_env_inter_kp%sum(reduced_secant_full_targets)
            CALL para_env_inter_kp%sum(full_step_rotation_norm)
            CALL para_env_inter_kp%sum(full_secant_rotation_norm)
            IF (previous_valid) THEN
               CALL para_env_inter_kp%sum(previous_step_rotation)
               CALL para_env_inter_kp%sum(previous_secant_rotation)
               CALL para_env_inter_kp%sum(previous_step_energy)
               CALL para_env_inter_kp%sum(previous_secant_energy)
               IF (closure_previous_valid) THEN
                  CALL para_env_inter_kp%sum(previous_closure_secant_rotation)
                  CALL para_env_inter_kp%sum(previous_closure_secant_energy)
               END IF
               CALL para_env_inter_kp%sum(previous_full_step_rotation_norm)
               CALL para_env_inter_kp%sum(previous_full_secant_rotation_norm)
               IF (previous_frozen_reduced_valid) &
                  CALL para_env_inter_kp%sum(previous_frozen_reduced_target)
            END IF
            IF (closure_anchor_valid) THEN
               CALL para_env_inter_kp%sum(anchor_step_rotation)
               CALL para_env_inter_kp%sum(anchor_secant_rotation)
               CALL para_env_inter_kp%sum(anchor_closure_secant_rotation)
               CALL para_env_inter_kp%sum(anchor_step_energy)
               CALL para_env_inter_kp%sum(anchor_secant_energy)
               CALL para_env_inter_kp%sum(anchor_closure_secant_energy)
            END IF
         END IF
         IF (closure_secant_valid) THEN
            frozen_secant_rotation(:) = secant_rotation(:) - closure_secant_rotation(:)
            frozen_secant_energy(:) = secant_energy(:) - closure_secant_energy(:)
         END IF
         IF (closure_previous_valid) THEN
            previous_frozen_secant_rotation(:) = previous_secant_rotation(:) - &
                                                 previous_closure_secant_rotation(:)
            previous_frozen_secant_energy(:) = previous_secant_energy(:) - &
                                               previous_closure_secant_energy(:)
         END IF

         current_step_coverage = 1.0_dp
         IF (full_step_rotation_norm > EPSILON(full_step_rotation_norm)) &
            current_step_coverage = DOT_PRODUCT(step_rotation, step_rotation)/full_step_rotation_norm
         current_response_coverage = 1.0_dp
         IF (full_secant_rotation_norm > EPSILON(full_secant_rotation_norm)) &
            current_response_coverage = DOT_PRODUCT(secant_rotation, secant_rotation)/ &
                                        full_secant_rotation_norm
         previous_step_coverage = 1.0_dp
         IF (previous_full_step_rotation_norm > EPSILON(previous_full_step_rotation_norm)) &
            previous_step_coverage = DOT_PRODUCT(previous_step_rotation, previous_step_rotation)/ &
                                     previous_full_step_rotation_norm
         previous_response_coverage = 1.0_dp
         IF (previous_full_secant_rotation_norm > EPSILON(previous_full_secant_rotation_norm)) &
            previous_response_coverage = DOT_PRODUCT(previous_secant_rotation, previous_secant_rotation)/ &
                                         previous_full_secant_rotation_norm
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,1X,L1,8(1X,ES16.8))') &
            " OT Schur accepted secant active coverage group history step response pstep presponse "// &
            "full_step full_response pfull_step pfull_response:", &
            target_group, previous_valid, current_step_coverage, current_response_coverage, &
            previous_step_coverage, previous_response_coverage, full_step_rotation_norm, &
            full_secant_rotation_norm, previous_full_step_rotation_norm, &
            previous_full_secant_rotation_norm

         active_energy_count = COUNT(occ_curv + tether_curv > EPSILON(MAXVAL(occ_curv + tether_curv)))
         DO ie = 1, nener
            IF (occ_curv(ie) + tether_curv(ie) <= EPSILON(MAXVAL(occ_curv + tether_curv))) THEN
               step_energy(ie) = 0.0_dp
               secant_energy(ie) = 0.0_dp
               closure_secant_energy(ie) = 0.0_dp
               frozen_secant_energy(ie) = 0.0_dp
               previous_step_energy(ie) = 0.0_dp
               previous_secant_energy(ie) = 0.0_dp
               previous_closure_secant_energy(ie) = 0.0_dp
               previous_frozen_secant_energy(ie) = 0.0_dp
               anchor_step_energy(ie) = 0.0_dp
               anchor_secant_energy(ie) = 0.0_dp
               anchor_closure_secant_energy(ie) = 0.0_dp
            END IF
         END DO
         IF (active_energy_count > 0) THEN
            energy_mean = SUM(step_energy)/REAL(active_energy_count, KIND=dp)
            WHERE (occ_curv + tether_curv > EPSILON(MAXVAL(occ_curv + tether_curv)))
               step_energy = step_energy - energy_mean
            END WHERE
            energy_mean = SUM(secant_energy)/REAL(active_energy_count, KIND=dp)
            WHERE (occ_curv + tether_curv > EPSILON(MAXVAL(occ_curv + tether_curv)))
               secant_energy = secant_energy - energy_mean
            END WHERE
            IF (closure_secant_valid) THEN
               energy_mean = SUM(closure_secant_energy)/REAL(active_energy_count, KIND=dp)
               WHERE (occ_curv + tether_curv > EPSILON(MAXVAL(occ_curv + tether_curv)))
                  closure_secant_energy = closure_secant_energy - energy_mean
               END WHERE
               energy_mean = SUM(frozen_secant_energy)/REAL(active_energy_count, KIND=dp)
               WHERE (occ_curv + tether_curv > EPSILON(MAXVAL(occ_curv + tether_curv)))
                  frozen_secant_energy = frozen_secant_energy - energy_mean
               END WHERE
            END IF
            IF (previous_valid) THEN
               energy_mean = SUM(previous_step_energy)/REAL(active_energy_count, KIND=dp)
               WHERE (occ_curv + tether_curv > EPSILON(MAXVAL(occ_curv + tether_curv)))
                  previous_step_energy = previous_step_energy - energy_mean
               END WHERE
               energy_mean = SUM(previous_secant_energy)/REAL(active_energy_count, KIND=dp)
               WHERE (occ_curv + tether_curv > EPSILON(MAXVAL(occ_curv + tether_curv)))
                  previous_secant_energy = previous_secant_energy - energy_mean
               END WHERE
               IF (closure_previous_valid) THEN
                  energy_mean = SUM(previous_closure_secant_energy)/ &
                                REAL(active_energy_count, KIND=dp)
                  WHERE (occ_curv + tether_curv > EPSILON(MAXVAL(occ_curv + tether_curv)))
                     previous_closure_secant_energy = previous_closure_secant_energy - energy_mean
                  END WHERE
                  energy_mean = SUM(previous_frozen_secant_energy)/ &
                                REAL(active_energy_count, KIND=dp)
                  WHERE (occ_curv + tether_curv > EPSILON(MAXVAL(occ_curv + tether_curv)))
                     previous_frozen_secant_energy = previous_frozen_secant_energy - energy_mean
                  END WHERE
               END IF
            END IF
            IF (closure_anchor_valid) THEN
               energy_mean = SUM(anchor_step_energy)/REAL(active_energy_count, KIND=dp)
               WHERE (occ_curv + tether_curv > EPSILON(MAXVAL(occ_curv + tether_curv)))
                  anchor_step_energy = anchor_step_energy - energy_mean
               END WHERE
               energy_mean = SUM(anchor_secant_energy)/REAL(active_energy_count, KIND=dp)
               WHERE (occ_curv + tether_curv > EPSILON(MAXVAL(occ_curv + tether_curv)))
                  anchor_secant_energy = anchor_secant_energy - energy_mean
               END WHERE
               energy_mean = SUM(anchor_closure_secant_energy)/ &
                             REAL(active_energy_count, KIND=dp)
               WHERE (occ_curv + tether_curv > EPSILON(MAXVAL(occ_curv + tether_curv)))
                  anchor_closure_secant_energy = anchor_closure_secant_energy - energy_mean
               END WHERE
            END IF
         END IF

         CALL qs_scf_kp_coupled_secant_model(rotation_hessian, energy_hessian, energy_cross, &
                                             step_rotation, step_energy, model_rotation, model_energy)
         model_rotation_base(:) = MATMUL(rotation_hessian, step_rotation)
         model_rotation_cross(:) = -MATMUL(TRANSPOSE(energy_cross), step_energy)
         model_energy_base(:) = MATMUL(energy_hessian, step_energy)
         model_energy_cross(:) = -MATMUL(energy_cross, step_rotation)
         total_reduced_target(:) = secant_rotation + &
                                   MATMUL(TRANSPOSE(energy_response), secant_energy)
         reduced_model(:) = MATMUL(rotation_hessian - response_metric, step_rotation)
         total_reduced_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(total_reduced_target, total_reduced_target)))
         reduced_model_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(reduced_model, reduced_model)))
         total_reduced_curvature = DOT_PRODUCT(step_rotation, total_reduced_target)
         reduced_model_curvature = DOT_PRODUCT(step_rotation, reduced_model)
         total_model_alignment = 0.0_dp
         IF (total_reduced_norm > TINY(1.0_dp) .AND. reduced_model_norm > TINY(1.0_dp)) &
            total_model_alignment = DOT_PRODUCT(total_reduced_target, reduced_model)/ &
                                    (total_reduced_norm*reduced_model_norm)
         frozen_reduced_norm = 0.0_dp
         closure_reduced_norm = 0.0_dp
         frozen_model_residual_norm = 0.0_dp
         frozen_model_alignment = 0.0_dp
         closure_model_alignment = 0.0_dp
         frozen_reduced_curvature = 0.0_dp
         closure_reduced_curvature = 0.0_dp
         decomposition_error = 0.0_dp
         IF (closure_secant_valid) THEN
            frozen_reduced_target(:) = frozen_secant_rotation + &
                                       MATMUL(TRANSPOSE(energy_response), frozen_secant_energy)
            closure_reduced_target(:) = closure_secant_rotation + &
                                        MATMUL(TRANSPOSE(energy_response), closure_secant_energy)
            frozen_reduced_norm = SQRT(MAX(0.0_dp, &
                                           DOT_PRODUCT(frozen_reduced_target, frozen_reduced_target)))
            closure_reduced_norm = SQRT(MAX(0.0_dp, &
                                            DOT_PRODUCT(closure_reduced_target, closure_reduced_target)))
            frozen_model_residual_norm = SQRT(MAX(0.0_dp, &
                                                  DOT_PRODUCT(frozen_reduced_target - reduced_model, &
                                                              frozen_reduced_target - reduced_model)))
            IF (frozen_reduced_norm > TINY(1.0_dp) .AND. reduced_model_norm > TINY(1.0_dp)) &
               frozen_model_alignment = DOT_PRODUCT(frozen_reduced_target, reduced_model)/ &
                                        (frozen_reduced_norm*reduced_model_norm)
            IF (closure_reduced_norm > TINY(1.0_dp) .AND. reduced_model_norm > TINY(1.0_dp)) &
               closure_model_alignment = DOT_PRODUCT(closure_reduced_target, reduced_model)/ &
                                         (closure_reduced_norm*reduced_model_norm)
            frozen_reduced_curvature = DOT_PRODUCT(step_rotation, frozen_reduced_target)
            closure_reduced_curvature = DOT_PRODUCT(step_rotation, closure_reduced_target)
            decomposition_error = SQRT(MAX(0.0_dp, &
                                           DOT_PRODUCT(total_reduced_target - frozen_reduced_target - &
                                                       closure_reduced_target, &
                                                       total_reduced_target - frozen_reduced_target - &
                                                       closure_reduced_target)))
         END IF
         ! Keep the endpoint-local closure sample available even when the older
         ! sample needed by the general multisecant fit is immature.  The
         ! density-specific probe deliberately consumes only this column.
         IF (closure_secant_valid) THEN
            closure_response_steps(:, 2) = step_rotation
            closure_response_targets(:, 2) = closure_reduced_target
         END IF
         IF (closure_secant_valid .AND. closure_previous_valid .AND. &
             previous_frozen_reduced_valid) THEN
            previous_closure_reduced_target(:) = previous_closure_secant_rotation + &
                                                 MATMUL(TRANSPOSE(energy_response), &
                                                        previous_closure_secant_energy)
            closure_response_steps(:, 1) = previous_step_rotation
            closure_response_targets(:, 1) = previous_closure_reduced_target
            IF (closure_anchor_valid) THEN
               anchor_closure_reduced_target(:) = anchor_closure_secant_rotation + &
                                                  MATMUL(TRANSPOSE(energy_response), &
                                                         anchor_closure_secant_energy)
               closure_response_steps(:, 3) = anchor_step_rotation
               closure_response_targets(:, 3) = anchor_closure_reduced_target
            END IF
            closure_response_pair_ready = ALL(closure_response_steps == closure_response_steps) .AND. &
                                          ALL(closure_response_targets == closure_response_targets)
            IF (.NOT. closure_response_pair_ready) THEN
               closure_response_steps(:, 1) = 0.0_dp
               closure_response_steps(:, 3) = 0.0_dp
               closure_response_targets(:, 1) = 0.0_dp
               closure_response_targets(:, 3) = 0.0_dp
            END IF
         END IF

         ! Fit the self-consistent endpoint response in the complete accepted
         ! (rotation, auxiliary-energy) step space.  Reducing closure targets
         ! against rotation alone aliases occupation-driven density response
         ! into the complex rotation block whenever the accepted ener_x step
         ! differs from its instantaneous Schur response.  The full symmetric
         ! fit keeps those cross and energy curvatures explicit before the
         ! exact fixed-N Schur transport returns to rotation coordinates.
         IF (closure_secant_valid .AND. closure_previous_valid) THEN
            nclosure_observations = MERGE(3, 2, closure_anchor_valid)
            ALLOCATE (closure_coupled_rotation_steps(nrot, nclosure_observations), &
                      closure_coupled_energy_steps(nener, nclosure_observations), &
                      closure_coupled_rotation_targets(nrot, nclosure_observations), &
                      closure_coupled_energy_targets(nener, nclosure_observations))
            closure_coupled_rotation_steps(:, 1) = previous_step_rotation
            closure_coupled_rotation_steps(:, 2) = step_rotation
            closure_coupled_energy_steps(:, 1) = previous_step_energy
            closure_coupled_energy_steps(:, 2) = step_energy
            closure_coupled_rotation_targets(:, 1) = previous_closure_secant_rotation
            closure_coupled_rotation_targets(:, 2) = closure_secant_rotation
            closure_coupled_energy_targets(:, 1) = previous_closure_secant_energy
            closure_coupled_energy_targets(:, 2) = closure_secant_energy
            IF (closure_anchor_valid) THEN
               closure_coupled_rotation_steps(:, 3) = anchor_step_rotation
               closure_coupled_energy_steps(:, 3) = anchor_step_energy
               closure_coupled_rotation_targets(:, 3) = anchor_closure_secant_rotation
               closure_coupled_energy_targets(:, 3) = anchor_closure_secant_energy
            END IF
            CALL qs_scf_kp_coupled_closure_response( &
               rotation_hessian, energy_hessian, energy_cross, &
               closure_coupled_rotation_steps(:, 1:2), closure_coupled_energy_steps(:, 1:2), &
               closure_coupled_rotation_targets(:, 1:2), closure_coupled_energy_targets(:, 1:2), &
               closure_coupled_response, closure_coupled_ready, &
               closure_coupled_independence, closure_coupled_compatibility, &
               closure_coupled_capture, closure_coupled_residual_ratio, &
               closure_coupled_transport_ratio, closure_coupled_rotation_ratio, &
               closure_coupled_energy_ratio, closure_coupled_cross_ratio, &
               full_rotation_correction=closure_coupled_full_rotation, &
               full_energy_correction=closure_coupled_full_energy, &
               full_cross_correction=closure_coupled_full_cross)
            closure_coupled_rotation_targets(:, 1) = previous_secant_rotation
            closure_coupled_rotation_targets(:, 2) = secant_rotation
            closure_coupled_energy_targets(:, 1) = previous_secant_energy
            closure_coupled_energy_targets(:, 2) = secant_energy
            IF (closure_anchor_valid) THEN
               closure_coupled_rotation_targets(:, 3) = anchor_secant_rotation
               closure_coupled_energy_targets(:, 3) = anchor_secant_energy
            END IF
            work_ratio(:) = [work_ratio_previous, work_ratio_current, work_ratio_anchor]
            work_projection_applied(:) = .FALSE.
            work_before(:) = 0.0_dp
            work_after(:) = 0.0_dp
            DO iobs = 1, nclosure_observations
               CALL qs_scf_kp_work_consistent_response( &
                  closure_coupled_rotation_steps(:, iobs), &
                  closure_coupled_energy_steps(:, iobs), &
                  closure_coupled_rotation_targets(:, iobs), &
                  closure_coupled_energy_targets(:, iobs), work_ratio(iobs), &
                  work_projection_applied(iobs), work_before(iobs), work_after(iobs))
               IF (logger%iter_info%print_level >= debug_print_level .AND. &
                   logger%para_env%is_source()) &
                  WRITE (cp_logger_get_default_unit_nr(logger), &
                         '(A,2(1X,I3),1X,L1,4(1X,ES16.8))') &
                  " OT Schur finite-Mermin work projection group obs applied ratio before after correction:", &
                  target_group, iobs, work_projection_applied(iobs), work_ratio(iobs), &
                  work_before(iobs), work_after(iobs), work_after(iobs) - work_before(iobs)
            END DO
            CALL qs_scf_kp_coupled_residual_prediction( &
               rotation_hessian, energy_hessian, energy_cross, &
               closure_coupled_rotation_steps, closure_coupled_energy_steps, &
               closure_coupled_rotation_targets, closure_coupled_energy_targets, &
               closure_predictive_rotation, closure_predictive_energy, &
               closure_predictive_cross, closure_predictive_finite, &
               closure_predictive_consistent, closure_predictive_overlap, &
               closure_predictive_capture, closure_predictive_quality, &
               closure_predictive_rotation_quality, closure_predictive_energy_quality, &
               closure_predictive_alignment, closure_predictive_curvature_min, &
               closure_predictive_curvature_max, &
               observable_work_quality=closure_predictive_work_quality, &
               observable_consistent=closure_predictive_work_consistent)
            closure_coupled_fit_ready = closure_coupled_ready
            closure_coupled_transport_ready = closure_coupled_ready
            IF (logger%iter_info%print_level >= debug_print_level .AND. &
                logger%para_env%is_source()) &
               WRITE (cp_logger_get_default_unit_nr(logger), &
                      '(A,1X,I3,3(1X,L1),9(1X,ES16.8))') &
               " OT Schur coupled residual prediction group finite consistent work_consistent "// &
               "overlap capture quality rquality equality work_quality alignment "// &
               "cratio_min cratio_max:", target_group, closure_predictive_finite, &
               closure_predictive_consistent, closure_predictive_work_consistent, &
               closure_predictive_overlap, closure_predictive_capture, closure_predictive_quality, &
               closure_predictive_rotation_quality, closure_predictive_energy_quality, &
               closure_predictive_work_quality, &
               closure_predictive_alignment, closure_predictive_curvature_min, &
               closure_predictive_curvature_max
            DEALLOCATE (closure_coupled_rotation_steps, closure_coupled_energy_steps, &
                        closure_coupled_rotation_targets, closure_coupled_energy_targets)
         END IF

         ! Keep the reduced frozen-H target in the stable channel/pair ordering.  On the next
         ! accepted endpoint this target belongs to the secant that the minimizer has shifted
         ! into its previous slot, so it must not be rebuilt with the new endpoint response map.
         DO local_channel = 1, SIZE(local_ot_env)
            global_channel = first_channel + local_channel - 1
            IF (global_channel < 1 .OR. global_channel > SIZE(channel_nmo)) CYCLE
            nmo = channel_nmo(global_channel)
            IF (nmo <= 0) CYCLE
            global_spin = MOD(global_channel - 1, nspin_ot) + 1
            group = MERGE(global_spin, 1, ngroups == nspin_ot)
            IF (group /= target_group) CYCLE
            local_ot_env(local_channel)%mermin_frozen_reduced_target_ready = .FALSE.
            IF (.NOT. closure_secant_valid) CYCLE
            IF (.NOT. ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_frozen_reduced_y) .OR. &
                .NOT. ASSOCIATED(local_ot_env(local_channel)%rot_mat_mermin_frozen_reduced_y_im)) CYCLE
            ALLOCATE (dense_re(nmo, nmo), dense_im(nmo, nmo))
            dense_re(:, :) = 0.0_dp
            dense_im(:, :) = 0.0_dp
            DO r = 1, nrot
               IF (var_channel(r) /= global_channel) CYCLE
               SELECT CASE (var_kind(r))
               CASE (1)
                  dense_re(var_i(r), var_j(r)) = frozen_reduced_target(r)
                  dense_re(var_j(r), var_i(r)) = -frozen_reduced_target(r)
               CASE (2)
                  dense_im(var_i(r), var_j(r)) = frozen_reduced_target(r)
                  dense_im(var_j(r), var_i(r)) = frozen_reduced_target(r)
               END SELECT
            END DO
            ! A freshly allocated DBCSR matrix has no data blocks to visit.
            ! Seed the stable accepted-step block pattern before overwriting it
            ! with the endpoint-local reduced covector.
            CALL dbcsr_copy(local_ot_env(local_channel)%rot_mat_mermin_frozen_reduced_y, &
                            local_ot_env(local_channel)%rot_mat_mermin_s)
            CALL dbcsr_copy(local_ot_env(local_channel)%rot_mat_mermin_frozen_reduced_y_im, &
                            local_ot_env(local_channel)%rot_mat_mermin_s_im)
            CALL dense_to_dbcsr_square( &
               local_ot_env(local_channel)%rot_mat_mermin_frozen_reduced_y, dense_re)
            CALL dense_to_dbcsr_square( &
               local_ot_env(local_channel)%rot_mat_mermin_frozen_reduced_y_im, dense_im)
            local_ot_env(local_channel)%mermin_frozen_reduced_target_ready = .TRUE.
            DEALLOCATE (dense_re, dense_im)
         END DO

         frozen_endpoint_multisecant_finite = .FALSE.
         frozen_endpoint_multisecant_independence = 0.0_dp
         frozen_endpoint_multisecant_compatibility = 0.0_dp
         frozen_endpoint_multisecant_correction_norm = 0.0_dp
         frozen_endpoint_multisecant_residual_norm = 0.0_dp
         frozen_endpoint_multisecant_updated_residual_norm = 0.0_dp
         frozen_endpoint_multisecant_correction_ratio = 0.0_dp
         IF (closure_secant_valid .AND. previous_frozen_reduced_valid) THEN
            ALLOCATE (frozen_endpoint_multisecant_steps(nrot, 2), &
                      frozen_endpoint_multisecant_targets(nrot, 2), &
                      frozen_endpoint_multisecant_hessian(nrot, nrot), &
                      frozen_endpoint_reference_hessian(nrot, nrot))
            frozen_endpoint_multisecant_steps(:, 1) = previous_step_rotation
            frozen_endpoint_multisecant_steps(:, 2) = step_rotation
            frozen_endpoint_multisecant_targets(:, 1) = previous_frozen_reduced_target
            frozen_endpoint_multisecant_targets(:, 2) = frozen_reduced_target
            frozen_endpoint_reference_hessian(:, :) = 0.0_dp
            CALL qs_scf_kp_symmetric_multisecant_update( &
               frozen_endpoint_reference_hessian, frozen_endpoint_multisecant_steps, &
               frozen_endpoint_multisecant_targets, 1.0_dp, frozen_endpoint_multisecant_hessian, &
               frozen_endpoint_multisecant_finite, frozen_endpoint_multisecant_independence, &
               frozen_endpoint_multisecant_compatibility, frozen_endpoint_multisecant_correction_norm, &
               frozen_endpoint_multisecant_residual_norm, &
               frozen_endpoint_multisecant_updated_residual_norm)
            base_hessian_norm = SQRT(MAX(0.0_dp, SUM((rotation_hessian - response_metric)**2)))
            frozen_endpoint_multisecant_correction_ratio = &
               frozen_endpoint_multisecant_correction_norm/ &
               MAX(base_hessian_norm, EPSILON(1.0_dp))
         END IF

         frozen_prediction_finite(:) = .FALSE.
         frozen_prediction_overlap(:) = 0.0_dp
         frozen_prediction_capture(:) = 0.0_dp
         frozen_prediction_quality(:) = 0.0_dp
         frozen_prediction_alignment(:) = 0.0_dp
         frozen_prediction_curvature_ratio(:) = 0.0_dp
         frozen_prediction_residual_norm(:) = 0.0_dp
         frozen_prediction_predicted_residual_norm(:) = 0.0_dp
         frozen_prediction_curvature(:) = 0.0_dp
         frozen_prediction_consistent = .FALSE.
         frozen_candidate_eligible = .FALSE.
         total_reduced_residual_norm = SQRT(MAX(0.0_dp, &
                                                DOT_PRODUCT(total_reduced_target - reduced_model, &
                                                            total_reduced_target - reduced_model)))
         frozen_total_prediction_quality = 0.0_dp
         frozen_total_prediction_alignment = 0.0_dp
         frozen_total_prediction_curvature = 0.0_dp
         frozen_total_prediction_curvature_ratio = 0.0_dp
         frozen_total_prediction_residual_norm = total_reduced_residual_norm
         IF (closure_secant_valid .AND. closure_previous_valid .AND. &
             previous_frozen_reduced_valid) THEN
            ALLOCATE (frozen_prediction_forward_hessian(nrot, nrot), &
                      frozen_prediction_current_hessian(nrot, nrot))
            ! The analytic reduced Hessian tracks the self-consistent closure in the measured
            ! tail.  Fit the finite frozen-H term around a zero reduced baseline and add it
            ! to that analytic closure model instead of replacing the closure response.
            CALL qs_scf_kp_reduced_secant_prediction( &
               response_metric, response_metric, energy_response, previous_step_rotation, &
               previous_frozen_secant_rotation, previous_frozen_secant_energy, step_rotation, &
               frozen_secant_rotation, frozen_secant_energy, frozen_prediction_forward_hessian, &
               frozen_prediction_finite(1), frozen_prediction_overlap(1), &
               frozen_prediction_capture(1), frozen_prediction_quality(1), &
               frozen_prediction_alignment(1), frozen_prediction_curvature_ratio(1), &
               frozen_prediction_residual_norm(1), frozen_prediction_predicted_residual_norm(1), &
               frozen_prediction_curvature(1), &
               training_reduced_target=previous_frozen_reduced_target, &
               validation_reduced_target=frozen_reduced_target)
            CALL qs_scf_kp_reduced_secant_prediction( &
               response_metric, response_metric, energy_response, step_rotation, &
               frozen_secant_rotation, frozen_secant_energy, previous_step_rotation, &
               previous_frozen_secant_rotation, previous_frozen_secant_energy, &
               frozen_prediction_current_hessian, frozen_prediction_finite(2), &
               frozen_prediction_overlap(2), frozen_prediction_capture(2), &
               frozen_prediction_quality(2), frozen_prediction_alignment(2), &
               frozen_prediction_curvature_ratio(2), frozen_prediction_residual_norm(2), &
               frozen_prediction_predicted_residual_norm(2), frozen_prediction_curvature(2), &
               training_reduced_target=frozen_reduced_target, &
               validation_reduced_target=previous_frozen_reduced_target)
            frozen_prediction_consistent = qs_scf_kp_coupled_prediction_consistent( &
                                           frozen_prediction_finite(1), &
                                           frozen_prediction_finite(2), active_subspace, residual_delta, &
                                           frozen_prediction_overlap(1), frozen_prediction_overlap(2), &
                                           frozen_prediction_capture(1), frozen_prediction_capture(2), &
                                           frozen_prediction_quality(1), frozen_prediction_quality(2), &
                                           frozen_prediction_quality(1), frozen_prediction_quality(2), &
                                           frozen_prediction_alignment(1), frozen_prediction_alignment(2), &
                                           frozen_prediction_curvature_ratio(1), &
                                           frozen_prediction_curvature_ratio(2))
            total_reduced_prediction(:) = &
               reduced_model + MATMUL(frozen_prediction_forward_hessian - response_metric, &
                                      step_rotation)
            frozen_total_prediction_residual_norm = SQRT(MAX(0.0_dp, &
                                                             DOT_PRODUCT(total_reduced_target - total_reduced_prediction, &
                                                                         total_reduced_target - total_reduced_prediction)))
            IF (total_reduced_residual_norm > EPSILON(total_reduced_residual_norm)) &
               frozen_total_prediction_quality = 1.0_dp - &
                                                 frozen_total_prediction_residual_norm**2/ &
                                                 total_reduced_residual_norm**2
            IF (total_reduced_norm > TINY(1.0_dp) .AND. &
                DOT_PRODUCT(total_reduced_prediction, total_reduced_prediction) > TINY(1.0_dp)) &
               frozen_total_prediction_alignment = DOT_PRODUCT( &
                                                   total_reduced_target, total_reduced_prediction)/ &
                                                   (total_reduced_norm*SQRT(DOT_PRODUCT( &
                                                                            total_reduced_prediction, total_reduced_prediction)))
            frozen_total_prediction_curvature = DOT_PRODUCT(step_rotation, total_reduced_prediction)
            IF (ABS(total_reduced_curvature) > EPSILON(total_reduced_curvature)) &
               frozen_total_prediction_curvature_ratio = frozen_total_prediction_curvature/ &
                                                         total_reduced_curvature
            frozen_candidate_eligible = frozen_prediction_consistent .AND. &
                                        frozen_total_prediction_quality > 0.0_dp .AND. &
                                        frozen_total_prediction_alignment >= &
                                        ot_kp_schur_prediction_alignment_min .AND. &
                                        frozen_total_prediction_curvature_ratio >= 0.5_dp .AND. &
                                        frozen_total_prediction_curvature_ratio <= 1.5_dp
            IF (frozen_candidate_eligible) THEN
               rotation_hessian_reduced_secant(:, :) = rotation_hessian + &
                                                       frozen_prediction_current_hessian - &
                                                       response_metric
               rotation_hessian_reduced_secant(:, :) = 0.5_dp* &
                                                       (rotation_hessian_reduced_secant + &
                                                        TRANSPOSE(rotation_hessian_reduced_secant))
               ! The current frozen-H secant defines the local mode.  The previous secant validates
               ! it out of sample but is not projected through the current fixed-N response.
               reduced_secant_modes(:, 1) = step_rotation
               reduced_secant_modes(:, 2) = frozen_reduced_target
               BLOCK
                  REAL(KIND=dp) :: mode_norm, step_norm_sq

                  step_norm_sq = DOT_PRODUCT(step_rotation, step_rotation)
                  IF (step_norm_sq > EPSILON(1.0_dp)) &
                     reduced_secant_modes(:, 2) = reduced_secant_modes(:, 2) - &
                                                  DOT_PRODUCT(step_rotation, frozen_reduced_target)/ &
                                                  step_norm_sq*step_rotation
                  mode_norm = SQRT(MAX(0.0_dp, &
                                       DOT_PRODUCT(reduced_secant_modes(:, 2), &
                                                   reduced_secant_modes(:, 2))))
                  IF (mode_norm <= 64.0_dp*SQRT(EPSILON(1.0_dp))* &
                      MAX(frozen_reduced_norm, SQRT(MAX(step_norm_sq, 0.0_dp)))) &
                     reduced_secant_modes(:, 2) = 0.0_dp
               END BLOCK
               ! Keep the measured raw physical gradient changes for residual prediction.
               reduced_secant_targets(:, 1) = previous_secant_rotation
               reduced_secant_targets(:, 2) = secant_rotation
               reduced_secant_shadow_ready = .TRUE.
               reduced_secant_replacement_ready = .TRUE.
            END IF
            DEALLOCATE (frozen_prediction_forward_hessian, frozen_prediction_current_hessian)
         END IF
         step_norm = DOT_PRODUCT(step_rotation, step_rotation) + DOT_PRODUCT(step_energy, step_energy)
         y_norm = DOT_PRODUCT(secant_rotation, secant_rotation) + DOT_PRODUCT(secant_energy, secant_energy)
         model_norm = DOT_PRODUCT(model_rotation, model_rotation) + DOT_PRODUCT(model_energy, model_energy)
         residual_rotation_norm = DOT_PRODUCT(secant_rotation - model_rotation, &
                                              secant_rotation - model_rotation)
         residual_energy_norm = DOT_PRODUCT(secant_energy - model_energy, secant_energy - model_energy)
         residual_norm = residual_rotation_norm + residual_energy_norm
         sty = DOT_PRODUCT(step_rotation, secant_rotation) + DOT_PRODUCT(step_energy, secant_energy)
         sths = DOT_PRODUCT(step_rotation, model_rotation) + DOT_PRODUCT(step_energy, model_energy)
         CALL ot_kpoint_secant_geometry(step_norm, y_norm, sty, snorm, ynorm, alignment, &
                                        orthogonal_fraction)
         model_alignment = 0.0_dp
         IF (model_norm > TINY(1.0_dp) .AND. y_norm > TINY(1.0_dp)) &
            model_alignment = DOT_PRODUCT(secant_rotation, model_rotation) + &
                              DOT_PRODUCT(secant_energy, model_energy)
         IF (model_norm > TINY(1.0_dp) .AND. y_norm > TINY(1.0_dp)) &
            model_alignment = model_alignment/(SQRT(model_norm)*SQRT(y_norm))
         curvature_ratio = 0.0_dp
         IF (ABS(sty) > EPSILON(sty)) curvature_ratio = sths/sty
         stored_sty = local_ot_env(1)%mermin_secant_sty

         rotation_y_norm = DOT_PRODUCT(secant_rotation, secant_rotation)
         rotation_model_norm = DOT_PRODUCT(model_rotation, model_rotation)
         component_step_rotation_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(step_rotation, step_rotation)))
         component_step_energy_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(step_energy, step_energy)))
         component_rotation_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(model_rotation_base, model_rotation_base)))
         component_cross_curvature = DOT_PRODUCT(step_rotation, model_rotation_cross) + &
                                     DOT_PRODUCT(step_energy, model_energy_cross)
         component_rotation_curvature = DOT_PRODUCT(step_rotation, model_rotation_base)
         component_energy_norm = SQRT(MAX(0.0_dp, DOT_PRODUCT(model_energy_base, model_energy_base)))
         component_energy_curvature = DOT_PRODUCT(step_energy, model_energy_base)
         component_rotation_response_norm = SQRT(MAX(0.0_dp, &
                                                   DOT_PRODUCT(secant_rotation - model_rotation, secant_rotation - model_rotation)))
         component_rotation_response_curvature = &
            DOT_PRODUCT(step_rotation, secant_rotation - model_rotation)
         component_energy_response_norm = SQRT(MAX(0.0_dp, &
                                                   DOT_PRODUCT(secant_energy - model_energy, secant_energy - model_energy)))
         component_energy_response_curvature = DOT_PRODUCT(step_energy, secant_energy - model_energy)
         component_rotation_alignment = 0.0_dp
         IF (component_rotation_norm > TINY(1.0_dp) .AND. rotation_y_norm > TINY(1.0_dp)) &
            component_rotation_alignment = DOT_PRODUCT(secant_rotation, model_rotation_base)/ &
                                           (SQRT(rotation_y_norm)*component_rotation_norm)
         component_energy_alignment = 0.0_dp
         IF (component_energy_norm > TINY(1.0_dp) .AND. &
             DOT_PRODUCT(secant_energy, secant_energy) > TINY(1.0_dp)) &
            component_energy_alignment = DOT_PRODUCT(secant_energy, model_energy_base)/ &
                                         (SQRT(DOT_PRODUCT(secant_energy, secant_energy))* &
                                          component_energy_norm)
         component_rotation_response_alignment = 0.0_dp
         IF (component_rotation_response_norm > TINY(1.0_dp) .AND. rotation_y_norm > TINY(1.0_dp)) &
            component_rotation_response_alignment = &
            DOT_PRODUCT(secant_rotation, secant_rotation - model_rotation)/ &
            (SQRT(rotation_y_norm)*component_rotation_response_norm)
         component_energy_response_alignment = 0.0_dp
         IF (component_energy_response_norm > TINY(1.0_dp) .AND. &
             DOT_PRODUCT(secant_energy, secant_energy) > TINY(1.0_dp)) &
            component_energy_response_alignment = &
            DOT_PRODUCT(secant_energy, secant_energy - model_energy)/ &
            (SQRT(DOT_PRODUCT(secant_energy, secant_energy))*component_energy_response_norm)

         rotation_sty = DOT_PRODUCT(step_rotation, secant_rotation)
         rotation_stbs = DOT_PRODUCT(step_rotation, model_rotation)
         rotation_curvature_ratio = 0.0_dp
         IF (ABS(rotation_sty) > EPSILON(rotation_sty)) &
            rotation_curvature_ratio = rotation_stbs/rotation_sty
         rotation_model_alignment = 0.0_dp
         IF (rotation_model_norm > TINY(1.0_dp) .AND. rotation_y_norm > TINY(1.0_dp)) &
            rotation_model_alignment = DOT_PRODUCT(secant_rotation, model_rotation)/ &
                                       (SQRT(rotation_model_norm)*SQRT(rotation_y_norm))
         ALLOCATE (target_rotation(nrot), updated_rotation_hessian(nrot, nrot), &
                   directional_rotation_hessian(nrot, nrot))
         target_rotation(:) = secant_rotation(:) + MATMUL(TRANSPOSE(energy_cross), step_energy)
         CALL qs_scf_kp_symmetric_secant_update(rotation_hessian, step_rotation, target_rotation, 1.0_dp, &
                                                updated_rotation_hessian, update_finite, correction_norm, &
                                                rotation_residual_norm, updated_rotation_residual_norm)
         base_hessian_norm = SQRT(MAX(0.0_dp, SUM(rotation_hessian**2)))
         correction_ratio = correction_norm/MAX(base_hessian_norm, EPSILON(1.0_dp))
         full_update_ready = update_finite .AND. &
                             active_subspace .AND. &
                             residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
                             rotation_sty > EPSILON(rotation_sty) .AND. &
                             rotation_stbs > EPSILON(rotation_stbs) .AND. &
                             rotation_curvature_ratio >= 0.15_dp .AND. &
                             rotation_curvature_ratio <= 1.25_dp .AND. &
                             rotation_model_alignment >= 0.90_dp .AND. &
                             correction_ratio <= 0.35_dp .AND. &
                             local_ot_env(1)%mermin_ls_accepted_quality_samples >= &
                             ot_kp_schur_calibration_min_samples .AND. &
                             local_ot_env(1)%mermin_ls_accepted_quality_ema >= 0.8_dp

         ! Complete only the accepted reduced Schur curvature when the full vector secant is
         ! dominated by unresolved response orthogonal to the accepted rotation direction.
         CALL qs_scf_kp_directional_curvature_update( &
            rotation_hessian - response_metric, step_rotation, total_reduced_curvature, &
            directional_rotation_hessian, directional_update_finite, &
            directional_model_curvature, directional_correction_curvature, &
            directional_correction_norm)
         directional_correction_ratio = directional_correction_norm/ &
                                        MAX(base_hessian_norm, EPSILON(1.0_dp))
         directional_update_ready = directional_update_finite .AND. &
                                    active_subspace .AND. &
                                    residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
                                    local_ot_env(1)%mermin_ls_accepted_quality_samples >= &
                                    ot_kp_schur_calibration_min_samples .AND. &
                                    local_ot_env(1)%mermin_ls_accepted_quality_ema >= 0.8_dp
         update_ready = full_update_ready .OR. directional_update_ready
         IF (full_update_ready) THEN
            rotation_hessian_secant(:, :) = updated_rotation_hessian(:, :)
         ELSE IF (directional_update_ready) THEN
            rotation_hessian_secant(:, :) = directional_rotation_hessian(:, :) + response_metric(:, :)
         END IF

         multisecant_finite = .FALSE.
         multisecant_independence = 0.0_dp
         multisecant_compatibility = 0.0_dp
         multisecant_correction_norm = 0.0_dp
         multisecant_residual_norm = 0.0_dp
         multisecant_updated_residual_norm = 0.0_dp
         multisecant_correction_ratio = 0.0_dp
         directional_subspace_finite = .FALSE.
         directional_subspace_ready = .FALSE.
         directional_subspace_rank = 0
         directional_subspace_correction_rank = 0
         directional_subspace_independence = 0.0_dp
         directional_subspace_compatibility = 0.0_dp
         directional_subspace_correction_norm = 0.0_dp
         directional_subspace_correction_ratio = 0.0_dp
         directional_subspace_curvature_error = 0.0_dp
         coupled_multisecant_finite = .FALSE.
         coupled_multisecant_ready = .FALSE.
         coupled_multisecant_independence = 0.0_dp
         coupled_multisecant_compatibility = 0.0_dp
         coupled_multisecant_correction_norm = 0.0_dp
         coupled_multisecant_residual_norm = 0.0_dp
         coupled_multisecant_updated_residual_norm = 0.0_dp
         coupled_multisecant_hessian_norm = 0.0_dp
         coupled_multisecant_correction_ratio = 0.0_dp
         coupled_multisecant_rotation_correction_ratio = 0.0_dp
         coupled_multisecant_cross_correction_ratio = 0.0_dp
         coupled_multisecant_energy_correction_ratio = 0.0_dp
         coupled_schur_finite = .FALSE.
         coupled_schur_eligible = .FALSE.
         coupled_schur_correction_ratio = 0.0_dp
         coupled_prediction_finite = .FALSE.
         coupled_prediction_overlap = 0.0_dp
         coupled_prediction_capture = 0.0_dp
         coupled_prediction_quality = 0.0_dp
         coupled_prediction_rotation_quality = 0.0_dp
         coupled_prediction_energy_quality = 0.0_dp
         coupled_prediction_alignment = 0.0_dp
         coupled_prediction_curvature_ratio = 0.0_dp
         coupled_prediction_residual_norm = 0.0_dp
         coupled_prediction_predicted_residual_norm = 0.0_dp
         coupled_prediction_curvature = 0.0_dp
         coupled_prediction_reverse_finite = .FALSE.
         coupled_prediction_reverse_overlap = 0.0_dp
         coupled_prediction_reverse_capture = 0.0_dp
         coupled_prediction_reverse_quality = 0.0_dp
         coupled_prediction_reverse_rotation_quality = 0.0_dp
         coupled_prediction_reverse_energy_quality = 0.0_dp
         coupled_prediction_reverse_alignment = 0.0_dp
         coupled_prediction_reverse_curvature_ratio = 0.0_dp
         coupled_prediction_reverse_residual_norm = 0.0_dp
         coupled_prediction_reverse_predicted_residual_norm = 0.0_dp
         coupled_prediction_reverse_curvature = 0.0_dp
         reduced_prediction_consistent = .FALSE.
         reduced_prediction_finite = .FALSE.
         reduced_prediction_overlap = 0.0_dp
         reduced_prediction_capture = 0.0_dp
         reduced_prediction_quality = 0.0_dp
         reduced_prediction_alignment = 0.0_dp
         reduced_prediction_curvature_ratio = 0.0_dp
         reduced_prediction_residual_norm = 0.0_dp
         reduced_prediction_predicted_residual_norm = 0.0_dp
         reduced_prediction_curvature = 0.0_dp
         reduced_prediction_reverse_finite = .FALSE.
         reduced_prediction_reverse_overlap = 0.0_dp
         reduced_prediction_reverse_capture = 0.0_dp
         reduced_prediction_reverse_quality = 0.0_dp
         reduced_prediction_reverse_alignment = 0.0_dp
         reduced_prediction_reverse_curvature_ratio = 0.0_dp
         reduced_prediction_reverse_residual_norm = 0.0_dp
         reduced_prediction_reverse_predicted_residual_norm = 0.0_dp
         reduced_prediction_reverse_curvature = 0.0_dp
         coupled_subspace_finite = .FALSE.
         coupled_subspace_eligible = .FALSE.
         coupled_subspace_independence = 0.0_dp
         coupled_subspace_compatibility = 0.0_dp
         coupled_subspace_response_capture = 0.0_dp
         coupled_subspace_correction_norm = 0.0_dp
         coupled_subspace_residual_norm = 0.0_dp
         coupled_subspace_updated_residual_norm = 0.0_dp
         coupled_subspace_projected_residual_norm = 0.0_dp
         coupled_subspace_rotation_correction_ratio = 0.0_dp
         coupled_subspace_energy_correction_ratio = 0.0_dp
         coupled_subspace_cross_correction_ratio = 0.0_dp
         reduced_multisecant_finite = .FALSE.
         reduced_multisecant_eligible = .FALSE.
         reduced_multisecant_independence = 0.0_dp
         reduced_multisecant_compatibility = 0.0_dp
         reduced_multisecant_correction_norm = 0.0_dp
         reduced_multisecant_residual_norm = 0.0_dp
         reduced_multisecant_updated_residual_norm = 0.0_dp
         reduced_multisecant_correction_ratio = 0.0_dp
         IF (previous_valid) THEN
            ALLOCATE (multisecant_rotation_steps(nrot, 2), multisecant_energy_steps(nener, 2), &
                      multisecant_rotation_targets(nrot, 2), multisecant_energy_targets(nener, 2), &
                      coupled_rotation_targets(nrot, 2), coupled_rotation_hessian(nrot, nrot), &
                      coupled_schur_rotation_hessian(nrot, nrot), &
                      coupled_prediction_rotation_hessian(nrot, nrot), &
                      coupled_prediction_current_rotation_hessian(nrot, nrot), &
                      reduced_prediction_rotation_hessian(nrot, nrot), &
                      reduced_prediction_current_rotation_hessian(nrot, nrot), &
                      coupled_subspace_rotation_hessian(nrot, nrot), &
                      reduced_multisecant_rotation_hessian(nrot, nrot), &
                      directional_subspace_hessian(nrot, nrot), &
                      directional_subspace_steps(nrot, 2), &
                      directional_subspace_targets(nrot, 2), &
                      coupled_energy_hessian(nener, nener), coupled_energy_cross(nener, nrot), &
                      coupled_prediction_energy_hessian(nener, nener), &
                      coupled_prediction_energy_cross(nener, nrot), &
                      coupled_prediction_current_energy_hessian(nener, nener), &
                      coupled_prediction_current_energy_cross(nener, nrot), &
                      coupled_subspace_energy_hessian(nener, nener), &
                      coupled_subspace_energy_cross(nener, nrot))
            multisecant_rotation_steps(:, 1) = previous_step_rotation(:)
            multisecant_rotation_steps(:, 2) = step_rotation(:)
            multisecant_energy_steps(:, 1) = previous_step_energy(:)
            multisecant_energy_steps(:, 2) = step_energy(:)
            coupled_rotation_targets(:, 1) = previous_secant_rotation(:)
            coupled_rotation_targets(:, 2) = secant_rotation(:)
            multisecant_rotation_targets(:, :) = coupled_rotation_targets(:, :) + &
                                                 MATMUL(TRANSPOSE(energy_cross), &
                                                        multisecant_energy_steps)
            multisecant_energy_targets(:, 1) = previous_secant_energy(:)
            multisecant_energy_targets(:, 2) = secant_energy(:)

            directional_subspace_steps(:, 1) = step_rotation(:)
            directional_subspace_steps(:, 2) = previous_step_rotation(:)
            directional_subspace_targets(:, 1) = total_reduced_target(:)
            directional_subspace_targets(:, 2) = previous_secant_rotation(:) + &
                                                 MATMUL(TRANSPOSE(energy_response), &
                                                        previous_secant_energy)
            CALL qs_scf_kp_directional_subspace_curvature_update( &
               rotation_hessian - response_metric, directional_subspace_steps, &
               directional_subspace_targets, directional_subspace_hessian, &
               directional_subspace_finite, directional_subspace_rank, &
               directional_subspace_correction_rank, directional_subspace_independence, &
               directional_subspace_compatibility, directional_subspace_correction_norm, &
               directional_subspace_curvature_error)
            directional_subspace_correction_ratio = directional_subspace_correction_norm/ &
                                                    MAX(base_hessian_norm, EPSILON(1.0_dp))
            directional_subspace_ready = directional_subspace_finite .AND. &
                                         directional_subspace_rank == 2 .AND. &
                                         directional_subspace_correction_rank == 2 .AND. &
                                         directional_subspace_independence >= 5.0E-2_dp .AND. &
                                         directional_subspace_compatibility <= 1.0E-1_dp .AND. &
                                         active_subspace .AND. &
                                         residual_delta <= &
                                         ot_kp_schur_projector_coupled_tail_delta .AND. &
                                         local_ot_env(1)%mermin_ls_accepted_quality_samples >= &
                                         ot_kp_schur_calibration_min_samples .AND. &
                                         local_ot_env(1)%mermin_ls_accepted_quality_ema >= 0.8_dp .AND. &
                                         local_ot_env(1)%schur_vector_secant_candidate_enabled

            CALL qs_scf_kp_coupled_secant_prediction( &
               rotation_hessian, energy_hessian, energy_cross, previous_step_rotation, &
               previous_step_energy, previous_secant_rotation, previous_secant_energy, &
               step_rotation, step_energy, secant_rotation, secant_energy, &
               coupled_prediction_rotation_hessian, coupled_prediction_energy_hessian, &
               coupled_prediction_energy_cross, &
               coupled_prediction_finite, coupled_prediction_overlap, coupled_prediction_capture, &
               coupled_prediction_quality, coupled_prediction_rotation_quality, &
               coupled_prediction_energy_quality, coupled_prediction_alignment, &
               coupled_prediction_curvature_ratio, coupled_prediction_residual_norm, &
               coupled_prediction_predicted_residual_norm, coupled_prediction_curvature)
            CALL qs_scf_kp_coupled_secant_prediction( &
               rotation_hessian, energy_hessian, energy_cross, step_rotation, step_energy, &
               secant_rotation, secant_energy, previous_step_rotation, previous_step_energy, &
               previous_secant_rotation, previous_secant_energy, &
               coupled_prediction_current_rotation_hessian, &
               coupled_prediction_current_energy_hessian, coupled_prediction_current_energy_cross, &
               coupled_prediction_reverse_finite, coupled_prediction_reverse_overlap, &
               coupled_prediction_reverse_capture, coupled_prediction_reverse_quality, &
               coupled_prediction_reverse_rotation_quality, coupled_prediction_reverse_energy_quality, &
               coupled_prediction_reverse_alignment, coupled_prediction_reverse_curvature_ratio, &
               coupled_prediction_reverse_residual_norm, &
               coupled_prediction_reverse_predicted_residual_norm, coupled_prediction_reverse_curvature)
            CALL qs_scf_kp_reduced_secant_prediction( &
               rotation_hessian, response_metric, energy_response, previous_step_rotation, &
               previous_secant_rotation, previous_secant_energy, step_rotation, secant_rotation, &
               secant_energy, reduced_prediction_rotation_hessian, reduced_prediction_finite, &
               reduced_prediction_overlap, reduced_prediction_capture, reduced_prediction_quality, &
               reduced_prediction_alignment, reduced_prediction_curvature_ratio, &
               reduced_prediction_residual_norm, reduced_prediction_predicted_residual_norm, &
               reduced_prediction_curvature)
            CALL qs_scf_kp_reduced_secant_prediction( &
               rotation_hessian, response_metric, energy_response, step_rotation, secant_rotation, &
               secant_energy, previous_step_rotation, previous_secant_rotation, &
               previous_secant_energy, reduced_prediction_current_rotation_hessian, &
               reduced_prediction_reverse_finite, reduced_prediction_reverse_overlap, &
               reduced_prediction_reverse_capture, reduced_prediction_reverse_quality, &
               reduced_prediction_reverse_alignment, reduced_prediction_reverse_curvature_ratio, &
               reduced_prediction_reverse_residual_norm, &
               reduced_prediction_reverse_predicted_residual_norm, &
               reduced_prediction_reverse_curvature)
            IF (reduced_prediction_finite .AND. reduced_prediction_reverse_finite) THEN
               prediction_residual_ratio = MAX( &
                                           reduced_prediction_predicted_residual_norm/ &
                                           MAX(reduced_prediction_residual_norm, EPSILON(1.0_dp)), &
                                           reduced_prediction_reverse_predicted_residual_norm/ &
                                           MAX(reduced_prediction_reverse_residual_norm, EPSILON(1.0_dp)))
            END IF
            prediction_update_ready = qs_scf_kp_coupled_prediction_consistent( &
                                      coupled_prediction_finite, coupled_prediction_reverse_finite, &
                                      active_subspace, residual_delta, coupled_prediction_overlap, &
                                      coupled_prediction_reverse_overlap, coupled_prediction_capture, &
                                      coupled_prediction_reverse_capture, coupled_prediction_quality, &
                                      coupled_prediction_reverse_quality, coupled_prediction_energy_quality, &
                                      coupled_prediction_reverse_energy_quality, coupled_prediction_alignment, &
                                      coupled_prediction_reverse_alignment, coupled_prediction_curvature_ratio, &
                                      coupled_prediction_reverse_curvature_ratio)
            reduced_prediction_consistent = qs_scf_kp_coupled_prediction_consistent( &
                                            reduced_prediction_finite, &
                                            reduced_prediction_reverse_finite, active_subspace, &
                                            residual_delta, reduced_prediction_overlap, &
                                            reduced_prediction_reverse_overlap, &
                                            reduced_prediction_capture, &
                                            reduced_prediction_reverse_capture, &
                                            reduced_prediction_quality, &
                                            reduced_prediction_reverse_quality, &
                                            reduced_prediction_quality, &
                                            reduced_prediction_reverse_quality, &
                                            reduced_prediction_alignment, &
                                            reduced_prediction_reverse_alignment, &
                                            reduced_prediction_curvature_ratio, &
                                            reduced_prediction_reverse_curvature_ratio)
            prediction_update_ready = prediction_update_ready .AND. reduced_prediction_consistent

            CALL qs_scf_kp_coupled_reduced_multisecant_update( &
               rotation_hessian, energy_hessian, energy_cross, multisecant_rotation_steps, &
               coupled_rotation_targets, multisecant_energy_targets, 1.0_dp, &
               reduced_multisecant_rotation_hessian, reduced_multisecant_finite, &
               reduced_multisecant_independence, reduced_multisecant_compatibility, &
               reduced_multisecant_correction_norm, reduced_multisecant_residual_norm, &
               reduced_multisecant_updated_residual_norm, reduced_multisecant_correction_ratio, &
               energy_response, response_metric)
            reduced_multisecant_eligible = reduced_multisecant_finite .AND. active_subspace .AND. &
                                           residual_delta <= &
                                           ot_kp_schur_projector_coupled_tail_delta .AND. &
                                           reduced_multisecant_independence >= 5.0E-2_dp .AND. &
                                           reduced_multisecant_compatibility <= 1.0E-1_dp .AND. &
                                           reduced_multisecant_correction_ratio <= 0.35_dp .AND. &
                                           local_ot_env(1)%mermin_ls_accepted_quality_samples >= &
                                           ot_kp_schur_calibration_min_samples .AND. &
                                           local_ot_env(1)%mermin_ls_accepted_quality_ema >= 0.8_dp
            IF (reduced_multisecant_eligible .AND. .NOT. reduced_secant_shadow_ready) THEN
               reduced_secant_shadow_ready = .TRUE.
               rotation_hessian_reduced_secant(:, :) = reduced_multisecant_rotation_hessian(:, :)
               reduced_secant_modes(:, :) = multisecant_rotation_steps(:, :)
               ! The reduced Schur fit above uses y_R+R^T*y_e.  Residual prediction, however,
               ! models the observable raw physical rotation gradient and therefore needs y_R.
               reduced_secant_targets(:, :) = coupled_rotation_targets(:, :)
            END IF

            ! Retain the previously calibrated rotation-only candidate as the
            ! fallback until the coupled prediction is mutually validated.
            CALL qs_scf_kp_symmetric_multisecant_update( &
               rotation_hessian, multisecant_rotation_steps, multisecant_rotation_targets, 1.0_dp, &
               rotation_hessian_multisecant, multisecant_finite, multisecant_independence, &
               multisecant_compatibility, multisecant_correction_norm, multisecant_residual_norm, &
               multisecant_updated_residual_norm)
            multisecant_correction_ratio = &
               multisecant_correction_norm/MAX(base_hessian_norm, EPSILON(1.0_dp))
            rotation_multisecant_ready = multisecant_finite .AND. active_subspace .AND. &
                                         residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
                                         multisecant_independence >= 5.0E-2_dp .AND. &
                                         multisecant_compatibility <= 1.0E-1_dp .AND. &
                                         multisecant_correction_ratio <= 0.35_dp .AND. &
                                         local_ot_env(1)%mermin_ls_accepted_quality_samples >= &
                                         ot_kp_schur_calibration_min_samples .AND. &
                                         local_ot_env(1)%mermin_ls_accepted_quality_ema >= 0.8_dp
            IF (.NOT. rotation_multisecant_ready .AND. directional_subspace_ready) THEN
               rotation_hessian_multisecant(:, :) = directional_subspace_hessian(:, :) + &
                                                    response_metric(:, :)
            ELSE IF (.NOT. rotation_multisecant_ready) THEN
               rotation_hessian_multisecant(:, :) = rotation_hessian(:, :)
            END IF

            CALL qs_scf_kp_coupled_multisecant_update( &
               rotation_hessian, energy_hessian, energy_cross, multisecant_rotation_steps, &
               multisecant_energy_steps, coupled_rotation_targets, multisecant_energy_targets, &
               1.0_dp, coupled_rotation_hessian, coupled_energy_hessian, &
               coupled_energy_cross, coupled_multisecant_finite, coupled_multisecant_independence, &
               coupled_multisecant_compatibility, coupled_multisecant_correction_norm, &
               coupled_multisecant_residual_norm, coupled_multisecant_updated_residual_norm, &
               coupled_multisecant_hessian_norm, coupled_multisecant_rotation_correction_ratio, &
               coupled_multisecant_energy_correction_ratio, coupled_multisecant_cross_correction_ratio)
            coupled_multisecant_correction_ratio = coupled_multisecant_correction_norm/ &
                                                   MAX(coupled_multisecant_hessian_norm, EPSILON(1.0_dp))
            CALL qs_scf_kp_coupled_subspace_multisecant_update( &
               rotation_hessian, energy_hessian, energy_cross, multisecant_rotation_steps, &
               multisecant_energy_steps, coupled_rotation_targets, multisecant_energy_targets, &
               1.0_dp, coupled_subspace_rotation_hessian, coupled_subspace_energy_hessian, &
               coupled_subspace_energy_cross, coupled_subspace_finite, coupled_subspace_independence, &
               coupled_subspace_compatibility, coupled_subspace_response_capture, &
               coupled_subspace_correction_norm, coupled_subspace_residual_norm, &
               coupled_subspace_updated_residual_norm, coupled_subspace_projected_residual_norm, &
               coupled_subspace_rotation_correction_ratio, coupled_subspace_energy_correction_ratio, &
               coupled_subspace_cross_correction_ratio)
            coupled_subspace_eligible = coupled_subspace_finite .AND. active_subspace .AND. &
                                        residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
                                        coupled_subspace_independence >= 5.0E-2_dp .AND. &
                                        coupled_subspace_compatibility <= 1.0E-1_dp .AND. &
                                        coupled_subspace_response_capture >= 0.5_dp .AND. &
                                        coupled_subspace_rotation_correction_ratio <= 0.35_dp .AND. &
                                        coupled_subspace_energy_correction_ratio <= 0.35_dp .AND. &
                                        local_ot_env(1)%mermin_ls_accepted_quality_samples >= &
                                        ot_kp_schur_calibration_min_samples .AND. &
                                        local_ot_env(1)%mermin_ls_accepted_quality_ema >= 0.8_dp
            IF (coupled_multisecant_finite) &
               CALL qs_scf_kp_coupled_schur_transport( &
               rotation_hessian, energy_hessian, energy_cross, coupled_rotation_hessian, &
               coupled_energy_hessian, coupled_energy_cross, coupled_schur_rotation_hessian, &
               coupled_schur_finite, coupled_schur_correction_ratio)
            coupled_schur_eligible = coupled_schur_finite .AND. active_subspace .AND. &
                                     residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
                                     coupled_multisecant_independence >= 5.0E-2_dp .AND. &
                                     coupled_multisecant_compatibility <= 1.0E-1_dp .AND. &
                                     coupled_schur_correction_ratio <= 0.35_dp .AND. &
                                     local_ot_env(1)%mermin_ls_accepted_quality_samples >= &
                                     ot_kp_schur_calibration_min_samples .AND. &
                                     local_ot_env(1)%mermin_ls_accepted_quality_ema >= 0.8_dp
            coupled_multisecant_ready = coupled_multisecant_finite .AND. active_subspace .AND. &
                                        residual_delta <= ot_kp_schur_projector_coupled_tail_delta .AND. &
                                        coupled_multisecant_independence >= 5.0E-2_dp .AND. &
                                        coupled_multisecant_compatibility <= 1.0E-1_dp .AND. &
                                        coupled_multisecant_correction_ratio <= 0.35_dp .AND. &
                                        coupled_multisecant_rotation_correction_ratio <= 0.35_dp .AND. &
                                        coupled_multisecant_energy_correction_ratio <= 0.35_dp .AND. &
                                        local_ot_env(1)%mermin_ls_accepted_quality_samples >= &
                                        ot_kp_schur_calibration_min_samples .AND. &
                                        local_ot_env(1)%mermin_ls_accepted_quality_ema >= 0.8_dp
            ! Prefer the current-secant response only after the two accepted
            ! secants predict each other.  It then receives a separate
            ! accepted-Mermin-drop history in the caller.
            multisecant_update_ready = (rotation_multisecant_ready .OR. &
                                        directional_subspace_ready) .AND. &
                                       .NOT. prediction_update_ready
            IF (prediction_update_ready) THEN
               rotation_hessian_multisecant(:, :) = &
                  reduced_prediction_current_rotation_hessian(:, :)
               energy_hessian_multisecant(:, :) = energy_hessian(:, :)
               energy_cross_multisecant(:, :) = energy_cross(:, :)
            ELSE IF (multisecant_update_ready) THEN
               energy_hessian_multisecant(:, :) = energy_hessian(:, :)
               energy_cross_multisecant(:, :) = energy_cross(:, :)
            ELSE
               rotation_hessian_multisecant(:, :) = rotation_hessian(:, :)
               energy_hessian_multisecant(:, :) = energy_hessian(:, :)
               energy_cross_multisecant(:, :) = energy_cross(:, :)
            END IF
         END IF

         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,12(1X,ES16.8))') &
     " OT Schur accepted vector model group selected_sty global_sty sths ratio ynorm mnorm rnorm rrot rener align ym_align orth:", &
            target_group, sty, stored_sty, sths, curvature_ratio, SQRT(MAX(0.0_dp, y_norm)), &
            SQRT(MAX(0.0_dp, model_norm)), SQRT(MAX(0.0_dp, residual_norm)), &
            SQRT(MAX(0.0_dp, residual_rotation_norm)), SQRT(MAX(0.0_dp, residual_energy_norm)), &
            alignment, model_alignment, orthogonal_fraction
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,12(1X,ES16.8))') &
            " OT Schur accepted response components group sr se Hrr HrE HEe HrespR HrespE "// &
            "qrr qrE qee qrespR qrespE:", &
            target_group, component_step_rotation_norm, component_step_energy_norm, &
            component_rotation_norm, SQRT(MAX(0.0_dp, DOT_PRODUCT(model_rotation_cross, model_rotation_cross) + &
                                              DOT_PRODUCT(model_energy_cross, model_energy_cross))), &
            component_energy_norm, component_rotation_response_norm, component_energy_response_norm, &
            component_rotation_curvature, component_cross_curvature, component_energy_curvature, &
            component_rotation_response_curvature, component_energy_response_curvature
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,4(1X,ES16.8))') &
            " OT Schur accepted response alignments group Hrr HEe responseR responseE:", &
            target_group, component_rotation_alignment, component_energy_alignment, &
            component_rotation_response_alignment, component_energy_response_alignment
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,1X,L1,13(1X,ES16.8))') &
            " OT Schur frozen-H closure reduced group valid tnorm fnorm cnorm mnorm fres "// &
            "tcurv fcurv ccurv mcurv talign falign calign decomp:", &
            target_group, closure_secant_valid, total_reduced_norm, frozen_reduced_norm, &
            closure_reduced_norm, reduced_model_norm, frozen_model_residual_norm, &
            total_reduced_curvature, frozen_reduced_curvature, closure_reduced_curvature, &
            reduced_model_curvature, total_model_alignment, frozen_model_alignment, &
            closure_model_alignment, &
            decomposition_error
         IF (logger%iter_info%print_level >= debug_print_level .AND. logger%para_env%is_source()) &
            WRITE (cp_logger_get_default_unit_nr(logger), '(A,1X,I3,2(1X,L1),8(1X,ES16.8))') &
            " OT Schur coupled closure response group fit transport independence compatibility "// &
            "capture residual_ratio transport_ratio rot_ratio ener_ratio cross_ratio:", &
            target_group, closure_coupled_fit_ready, closure_coupled_transport_ready, &
            closure_coupled_independence, closure_coupled_compatibility, closure_coupled_capture, &
            closure_coupled_residual_ratio, closure_coupled_transport_ratio, &
